/****** Object:  UserDefinedFunction [dbo].[CountFridaysBetweenTwoDates]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[CountFridaysBetweenTwoDates]
(
    @StartDate DATE,
    @EndDate DATE
)
RETURNS INT
AS
BEGIN
    DECLARE @NumberOfFridays INT;

    -- Count the number of Fridays between the two dates
    SELECT @NumberOfFridays = (select count(*) from dbo._GregorianHijriDate gh
	where 1=1
	and CAST(gh.gregorianDate AS DATE) between @StartDate and @EndDate
	and DATEPART(DW,CAST(gh.gregorianDate AS DATE)) =6); -- 6 indicates Friday (assuming the first day of the week is Sunday)

    RETURN @NumberOfFridays;
END;
GO
/****** Object:  UserDefinedFunction [dbo].[funcGetDepartmentDistID]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   FUNCTION [dbo].[funcGetDepartmentDistID] (@departmentID INT)
RETURNS INT
AS
BEGIN
    DECLARE @distributorID INT

    SELECT @distributorID = D.distributorID
    FROM DeptSecDiv DSD
    INNER JOIN  dbo.Distributor D ON DSD.DSDID = D.DSDID_FK
    INNER JOIN  dbo.DistributorType DT ON D.distributorType_FK = DT.distributorTypeID
    INNER JOIN  dbo.Department Dep ON Dep.deptID = DSD.deptID_FK
    WHERE DT.distributorTypeID = 1 AND DSD.divID_FK IS NULL AND DSD.secID_FK IS NULL AND Dep.deptID = @departmentID

    RETURN @distributorID
END
GO
/****** Object:  UserDefinedFunction [dbo].[fungetRank_]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[fungetRank_]
(@userID int)
RETURNS nvarchar (100)
AS
BEGIN
	declare @rankName_A nvarchar (100)
 set @rankName_A=
	(SELECT top (1)  d.distributorName_A
	FROM UserDistributor AS ud 
	INNER JOIN Distributor AS d ON ud.distributorID_FK = d.distributorID 
	INNER JOIN UserType AS ut ON d.groupID_FK = ut.userTypeID
	WHERE 1=1
	AND (ud.userID_FK=@userID)
	AND(d.distributorType_FK=3)
	AND (d.groupID_FK IS NOT NULL)
	AND (d.distributorActive = 1) 
	AND (ud.UDEndDate IS NULL OR ud.UDEndDate='') 
	AND (ud.UDActive = 1)

order by ud.UDID desc
)

	-- Return the result of the function
	RETURN @rankName_A

END
GO
