/****** Object:  UserDefinedFunction [dbo].[GetCountAllUsers]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[GetCountAllUsers]
(

)
RETURNS  int
AS
BEGIN
	DECLARE @Result  int 
	SET @Result=(
					SELECT COUNT(ud.userID_FK) CountUsers
					FROM UserDistributor AS ud 
						INNER JOIN Distributor AS d ON ud.distributorID_FK = d.distributorID
					WHERE (1=1) 
								AND (NOT (ud.UDStartDate IS NULL)) 
								AND (ud.UDEndDate IS NULL) 
								AND (ud.UDActive = 1) 
								AND (d.distributorType_FK = 1) 
								AND (NOT (d.DSDID_FK IS NULL)) 
								AND (d.roleID_FK IS NULL)
				)
				

	RETURN @Result

END
GO
/****** Object:  UserDefinedFunction [dbo].[GetCountUserFromDSD]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[GetCountUserFromDSD] 
(
	@DSDID int
)
RETURNS int
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Result  int = 0
	SET @Result=(
					SELECT COUNT(ud.userID_FK) CountUsers
					FROM UserDistributor AS ud 
					INNER JOIN dbo.[Users] u ON ud.userID_FK=u.usersID AND u.usersActive=1
						INNER JOIN Distributor AS d ON ud.distributorID_FK = d.distributorID
					WHERE (1=1) 
								AND (NOT (ud.UDStartDate IS NULL)) 
								AND (ud.UDEndDate IS NULL) 
								AND (ud.UDActive = 1) 
								AND (d.distributorType_FK = 1) 
								AND (NOT (d.DSDID_FK IS NULL)) 
								AND (d.roleID_FK IS NULL)
								AND (d.DSDID_FK=@DSDID)
	)
	
	RETURN @Result

END
GO
/****** Object:  UserDefinedFunction [dbo].[GetRank]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[GetRank]
(
	-- Add the parameters for the function here
	@userID int
)
RETURNS NVARCHAR (100)
AS
BEGIN
	DECLARE @result NVARCHAR (100)

	SET @result = (	SELECT d.distributorName_A AS [rank]
					FROM dbo.UserDistributor ud 
						INNER JOIN dbo.Distributor  d ON ud.distributorID_FK = d.distributorID 
					WHERE 1=1
						AND (d.distributorType_FK = 3) 
						AND (ud.UDActive = 1)
						AND (ud.UDStartDate IS NOT NULL)
						AND (ud.UDEndDate IS NULL)
						AND (ud.userID_FK=@userID))

	-- Return the result of the function
	RETURN @result

END
GO
/****** Object:  UserDefinedFunction [dbo].[GetUserTypeID]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[GetUserTypeID]
(
	-- Add the parameters for the function here
	@userID int 
)
RETURNS  int
AS
BEGIN
	-- Declare the return variable here
	DECLARE @Result int

	-- Add the T-SQL statements to compute the return value here
	SET	@Result=(	SELECT 
					CASE 
					WHEN ( US_UserID LIKE ('600%') ) OR ( US_UserID LIKE ('650%') ) THEN 1
					WHEN ( US_UserID LIKE ('100%') ) THEN 2
					WHEN ( US_UserID LIKE ('900%') ) THEN 4
					else 3
					END N'userTypeID_FK'
					FROM TBS_BAWSE2.dbo.TBST_Users 
					WHERE cast(US_UserID as int)=@userID)
	RETURN  @Result

END
GO
/****** Object:  UserDefinedFunction [dbo].[MergeDates]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date, ,>
-- Description:	<Description, ,>
-- =============================================
CREATE FUNCTION [dbo].[MergeDates] 
(
	-- Add the parameters for the function here
	@hijriDate nvarchar(50) = NULL,
	@greoDate Date = NULL
)
RETURNS nvarchar(100)
AS
BEGIN
	-- Declare the return variable here
	DECLARE @MergeDate nvarchar(100)

	-- Add the T-SQL statements to compute the return value here
	IF(@hijriDate IS NULL AND @greoDate IS NOT NULL)

BEGIN

 SET @MergeDate =(SELECT CAST( CAST(g.gregorianDate AS DATE)AS nvarchar(100))+' - '+ g.hijriDateyyyymmdd_ FROM  dbo._GregorianHijriDate g WHERE g.gregorianDate = @greoDate) 

END
ELSE IF(@hijriDate IS NOT NULL AND @greoDate IS NULL)

BEGIN

 SET @MergeDate = (SELECT CAST( CAST(g.gregorianDate AS DATE)AS nvarchar(100))+' - '+ g.hijriDateyyyymmdd_ FROM  dbo._GregorianHijriDate g WHERE g.hijriDateyyyymmdd_ = @hijriDate) 

END
ELSE

BEGIN

 SET @MergeDate = N'لا يوجد تواريخ مدخلة'

END


	-- Return the result of the function
	RETURN @MergeDate 

END
GO
/****** Object:  UserDefinedFunction [dbo].[minutesToHours]    Script Date: 6/17/2026 11:38:59 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[minutesToHours]
(
 	@minutes INT , @type NVARCHAR(100) =NULL
)
RETURNS NVARCHAR(100) 
AS
BEGIN
	 RETURN  CASE WHEN @minutes < 60 THEN CONVERT(NVARCHAR,@minutes) + ' ' +N'د' 
		ELSE 
			CASE WHEN @type IS NULL THEN CONVERT(NVARCHAR,CONVERT(DECIMAL(10,1),@minutes/60.0)) + ' ' +N'س' 
			WHEN @type = 'hh mm' THEN CONVERT(NVARCHAR, @minutes/60 ) +N'س' + CASE WHEN @minutes%60 = 0 THEN '' ELSE N' ' + CONVERT(NVARCHAR, @minutes%60 )+ N'د' END 
			ELSE NULL 
			END 
		END 
END
GO
