SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[V_GetListIdara]
AS
SELECT        ds.distributorID, dsd.DSDID, dsd.idaraID_FK AS IdaraID, LTRIM(RTRIM(i.idaraLongName_A)) AS IdaraName, NULL AS idaraDescription, i.organizationID_FK
FROM            dbo.Organization AS O INNER JOIN
                         dbo.Idara AS i ON O.OrganizationID = i.organizationID_FK INNER JOIN
                         dbo.DeptSecDiv AS dsd ON dsd.idaraID_FK = i.idaraID INNER JOIN
                         dbo.Distributor AS ds ON ds.DSDID_FK = dsd.DSDID
WHERE        (dsd.secID_FK IS NULL) AND (dsd.divID_FK IS NULL) AND (dsd.deptID_FK IS NULL) AND (dsd.idaraID_FK IS NOT NULL) AND (ds.distributorActive = 1) AND (ds.DSDID_FK IS NOT NULL) AND (ds.roleID_FK IS NULL) AND 
                         (ds.distributorType_FK = 1) AND (dsd.OrganizationID_FK IS NOT NULL)
GO
