CREATE VIEW [dbo].[V_GetFullStructureForDSD]
AS
SELECT        dsd.DSDID, o.OrganizationID, o.OrganizationName, I.IdaraID, I.IdaraName, d.DepartmentID, d.DepartmentName, s.SectionID, s.SectionName, v.DivisonID, v.DivisonName, CASE WHEN (v.DivisonID IS NULL) AND 
                         (s.SectionID IS NULL) AND (d .DepartmentID IS NULL) AND (i.IdaraID IS NULL) AND (o.OrganizationID IS NOT NULL) THEN 1 WHEN (v.DivisonID IS NULL) AND (s.SectionID IS NULL) AND (d .DepartmentID IS NULL) AND 
                         (i.IdaraID IS NOT NULL) AND (o.OrganizationID IS NOT NULL) THEN 2 WHEN (v.DivisonID IS NULL) AND (s.SectionID IS NULL) AND (d .DepartmentID IS NOT NULL) AND (i.IdaraID IS NOT NULL) AND 
                         (o.OrganizationID IS NOT NULL) THEN 3 WHEN (v.DivisonID IS NULL) AND (s.SectionID IS NOT NULL) AND (d .DepartmentID IS NOT NULL) AND (i.IdaraID IS NOT NULL) AND (o.OrganizationID IS NOT NULL) 
                         THEN 4 WHEN (v.DivisonID IS NOT NULL) AND (s.SectionID IS NOT NULL) AND (d .DepartmentID IS NOT NULL) AND (i.IdaraID IS NOT NULL) AND (o.OrganizationID IS NOT NULL) THEN 5 END AS DSDLevel
FROM            dbo.DeptSecDiv AS dsd LEFT OUTER JOIN
                         dbo.V_GetListOrganization AS o ON dsd.OrganizationID_FK = o.OrganizationID LEFT OUTER JOIN
                         dbo.V_GetListIdara AS I ON dsd.idaraID_FK = I.IdaraID LEFT OUTER JOIN
                         dbo.V_GetListDepartment AS d ON dsd.deptID_FK = d.DepartmentID LEFT OUTER JOIN
                         dbo.V_GetListSection AS s ON dsd.secID_FK = s.SectionID LEFT OUTER JOIN
                         dbo.V_GetListDivison AS v ON dsd.divID_FK = v.DivisonID
WHERE        (1 = 1) AND (d.deptActive = 1) AND (d.deptStartDate IS NOT NULL) AND (CAST(d.deptStartDate AS date) <= CAST(GETDATE() AS date)) AND (CAST(d.deptEndDate AS date) > CAST(GETDATE() AS date)) OR
                         (1 = 1) AND (d.deptActive = 1) AND (d.deptStartDate IS NOT NULL) AND (CAST(d.deptStartDate AS date) <= CAST(GETDATE() AS date)) AND (d.deptEndDate IS NULL) OR
                         (s.secActive = 1) AND (s.secStartDate IS NOT NULL) AND (CAST(s.secStartDate AS date) <= CAST(GETDATE() AS date)) AND (CAST(s.secEndDate AS date) > CAST(GETDATE() AS date)) OR
                         (s.secActive = 1) AND (s.secStartDate IS NOT NULL) AND (CAST(s.secStartDate AS date) <= CAST(GETDATE() AS date)) AND (s.secEndDate IS NULL) OR
                         (v.divActive = 1) AND (v.divStartDate IS NOT NULL) AND (CAST(v.divStartDate AS date) <= CAST(GETDATE() AS date)) AND (CAST(v.divEndDate AS date) > CAST(GETDATE() AS date)) OR
                         (v.divActive = 1) AND (v.divStartDate IS NOT NULL) AND (CAST(v.divStartDate AS date) <= CAST(GETDATE() AS date)) AND (v.divEndDate IS NULL) OR
                         (dsd.idaraID_FK IS NOT NULL) AND (dsd.deptID_FK IS NULL) AND (dsd.secID_FK IS NULL) AND (dsd.divID_FK IS NULL) OR
                         (dsd.idaraID_FK IS NULL) AND (dsd.deptID_FK IS NULL) AND (dsd.secID_FK IS NULL) AND (dsd.divID_FK IS NULL) AND (dsd.OrganizationID_FK IS NOT NULL)
GO
/****** Object:  UserDefinedFunction [dbo].[ft_UserAllPermissionsForAi]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE   FUNCTION [dbo].[ft_UserAllPermissionsForAi]
(
      @UsersID     BigInt
    
)
RETURNS TABLE
AS
RETURN
(
    SELECT DISTINCT
        isnull(v.userID,@UsersID) as userID,
    v.menuName_E,
    v.menuName_A,
    v.permissionTypeName_E,
    v.permissionTypeName_A
    FROM  dbo.V_GetListUserPermission AS v
    INNER JOIN  dbo.Permission AS p
        ON v.permissionID = p.permissionID
    WHERE
        (
            (p.UsersID_FK = @UsersID)
        
                    OR
        
                    (p.RoleID_FK in 
                    (select d.roleID_FK 
                    from  dbo.UserDistributor ud 
                    inner join  dbo.Distributor d on ud.distributorID_FK = d.distributorID
                    where d.distributorActive = 1 and d.roleID_FK is not null and ud.UDActive = 1 
                    and cast(ud.UDStartDate as date) <= cast(GETDATE() as date) 
                    and ((cast(ud.UDEndDate as date) > cast(GETDATE() as date)) or (ud.UDEndDate is null))
                    and ud.userID_FK = @UsersID
                    ))
        
                    OR
                    (p.DSDID_FK in
                    (
                    select f.DSDID
                    from  dbo.V_GetListUsersInDSD d
                    inner join  dbo.V_GetFullStructureForDSD f on d.DSDID = f.DSDID
                    where d.usersID = @UsersID
                    )
                    )

                    OR
                    (p.distributorID_FK in
                    (
                    select d.distributorID 
                    from  dbo.UserDistributor ud 
                    inner join  dbo.Distributor d on ud.distributorID_FK = d.distributorID
                    where d.distributorActive = 1  and ud.UDActive = 1 
                    and cast(ud.UDStartDate as date) <= cast(GETDATE() as date) 
                    and ((cast(ud.UDEndDate as date) > cast(GETDATE() as date)) or (ud.UDEndDate is null))
                    and ud.userID_FK = @UsersID
                    )
                    )

                    OR
                    (
                    p.UsersID_FK IS NULL AND p.DSDID_FK IS NULL AND p.RoleID_FK IS NULL
                    )
        )
        -- فلترة الصفحة
        -- فلترة التواريخ
        AND CAST(v.permissionStartDate AS DATE) <= CAST(GETDATE() AS DATE)
        AND (v.permissionEndDate IS NULL OR CAST(v.permissionEndDate AS DATE) > CAST(GETDATE() AS DATE))
);
GO
/****** Object:  UserDefinedFunction [Housing].[fn_BuildingAction_ChainToRoot]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   FUNCTION [Housing].[fn_BuildingAction_ChainToRoot]
(
    @buildingActionID BIGINT
)
RETURNS TABLE
AS
RETURN
(
    WITH chain AS
    (
        SELECT
            b.*,
            0 AS Lvl,
            CAST(N'|' + CAST(b.buildingActionID AS NVARCHAR(50)) + N'|' AS NVARCHAR(MAX)) AS PathIds
        FROM Housing.BuildingAction b
        WHERE b.buildingActionID = @buildingActionID

        UNION ALL

        SELECT
            p.*,
            c.Lvl + 1 AS Lvl,
            CAST(c.PathIds + CAST(p.buildingActionID AS NVARCHAR(50)) + N'|' AS NVARCHAR(MAX)) AS PathIds
        FROM chain c
        INNER JOIN Housing.BuildingAction p
            ON p.buildingActionID = c.buildingActionParentID
        WHERE CHARINDEX(
                N'|' + CAST(p.buildingActionID AS NVARCHAR(50)) + N'|',
                c.PathIds
              ) = 0
    ),
    mx AS
    (
        SELECT MAX(Lvl) AS MaxLvl FROM chain
    )
    SELECT
        -- جميع الأعمدة
        buildingActionID,
        buildingActionUDID,
        buildingActionTypeID_FK,
        buildingStatusID_FK,
        residentInfoID_FK,
        generalNo_FK,
        buildingPaymentTypeID_FK,
        buildingDetailsID_FK,
        buildingDetailsNo,
        buildingActionFromDate,
        buildingActionToDate,
        buildingActionDate,
        buildingActionDate2,
        buildingActionDecisionNo,
        buildingActionDecisionDate,
        fromDSD_FK,
        toDSD_FK,
        buildingActionFromSourceID_FK,
        buildingActionToSourceID_FK,
        buildingActionNote,
        buildingActionExtraText1,
        buildingActionExtraText2,
        buildingActionExtraText3,
        buildingActionExtraText4,
        buildingActionExtraDate1,
        buildingActionExtraDate2,
        buildingActionExtraDate3,
        buildingActionExtraFloat1,
        buildingActionExtraFloat2,
        buildingActionExtraInt1,
        buildingActionExtraInt2,
        buildingActionExtraInt3,
        buildingActionExtraInt4,
        buildingActionExtraType1,
        buildingActionExtraType2,
        buildingActionExtraType3,
        buildingActionActive,
        buildingActionParentID,
        CustdyRecord,
        AssignPeriodID_FK,
        OccupentDate,
        ExitDate,
        IdaraId_FK,
        entryDate,
        entryData,
        hostName,

        -- ✅ لفل جديد يبدأ من الجذر
        (mx.MaxLvl - c.Lvl) AS Lvl
    FROM chain c
    CROSS JOIN mx
);
GO
/****** Object:  View [Housing].[V_WaitingListxx]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO







CREATE VIEW [Housing].[V_WaitingListxx]
AS
WITH d AS
(
    SELECT
        b.buildingActionID AS RootActionID,
        x.buildingActionID,
        x.buildingActionParentID,
        x.buildingActionTypeID_FK,
        x.IdaraId_FK,
        1 AS Lvl
    FROM Housing.BuildingAction b
    INNER JOIN Housing.BuildingAction x
        ON x.buildingActionParentID = b.buildingActionID
    WHERE b.buildingActionTypeID_FK in(1,7)
      AND b.buildingActionActive = 1

    UNION ALL

    SELECT
        d.RootActionID,
        x.buildingActionID,
        x.buildingActionParentID,
        x.buildingActionTypeID_FK,
        x.IdaraId_FK,
        d.Lvl + 1
    FROM d
    INNER JOIN Housing.BuildingAction x
        ON x.buildingActionParentID = d.buildingActionID

        where x.buildingActionActive = 1
),
action_dates AS
(
    SELECT
        d.RootActionID,
        MIN(CASE WHEN ba.buildingActionTypeID_FK = 2 THEN ba.buildingActionDate END) AS ResidentMoveInDate,
        COALESCE
        (
            MAX(CASE WHEN ba.buildingActionTypeID_FK = 3 THEN ba.buildingActionDate END),
            MAX(CASE WHEN ba.buildingActionTypeID_FK = 54 THEN ba.buildingActionDate END)
        ) AS ResidentMoveOutDate
    FROM d
    INNER JOIN Housing.BuildingAction rb
        ON rb.buildingActionID = d.RootActionID
       AND rb.buildingActionTypeID_FK IN (1, 7)
    INNER JOIN Housing.BuildingAction ba
        ON ba.buildingActionID = d.buildingActionID
    GROUP BY d.RootActionID
),
leaf AS
(
    SELECT
        d.RootActionID,
        d.buildingActionID,
        d.buildingActionTypeID_FK,
        d.IdaraId_FK,
        d.Lvl,
        ROW_NUMBER() OVER
        (
            PARTITION BY d.RootActionID
            ORDER BY d.Lvl DESC, d.buildingActionID DESC
        ) AS rn
    FROM d
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM Housing.BuildingAction ch
        WHERE ch.buildingActionParentID = d.buildingActionID
    )
)
SELECT
    b.buildingActionID AS ActionID,
    b.buildingActionTypeID_FK as ActionTypeID,
    ri.NationalID,
    rd.generalNo_FK AS GeneralNo,
    b.buildingActionDecisionNo AS ActionDecisionNo,
    CONVERT(nvarchar(10), b.buildingActionDecisionDate, 23) AS ActionDecisionDate,

    wc.waitingClassID AS WaitingClassID,
    wc.waitingClassName_A AS WaitingClassName,
    wo.waitingOrderTypeID AS WaitingOrderTypeID,
    wo.waitingOrderTypeName_A AS WaitingOrderTypeName,
    wc.waitingClassSequence AS waitingClassSequence,

    b.buildingActionDate AS ActionDate,
    ri.residentInfoID AS residentInfoID,

    LTRIM(RTRIM(CONCAT_WS(N' ', rd.firstName_A, rd.secondName_A, rd.thirdName_A, rd.lastName_A))) AS fullname,

    b.buildingActionNote AS ActionNote,
    b.IdaraId_FK AS IdaraId,
    i.idaraLongName_A AS ActionIdaraName,

    b.entryData AS MainActionEntryData,
    b.entryDate AS MainActionEntryDate,

    la.buildingActionExtraInt1 AS ToIdaraID,
    toidara.idaraLongName_A AS Toidaraname,

    la.buildingDetailsID_FK as buildingDetailsID,
    la.buildingDetailsNo,
    

    l.buildingActionID AS LastActionID,
    l.buildingActionTypeID_FK AS LastActionTypeID,
    bt.buildingActionTypeName_A AS LastActionTypeName,
    bt.buildingActionRoot,
    la.buildingActionDate  as LastActionDate,
    l.IdaraId_FK AS LastActionIdaraID,
    it.idaraLongName_A AS LastActionIdaraName,



    la.buildingActionDecisionNo AS LastActionDecisionNo,
    CONVERT(nvarchar(10), la.buildingActionDecisionDate, 23) AS LastActionDecisionDate,
    la.buildingActionFromDate,
    la.buildingActionToDate,

    
    la.AssignPeriodID_FK as AssignPeriodID,
    la.InAssignPeriod as InAssignPeriod,
    la.buildingActionParentID as LastActionbuildingActionParentID,

    la.buildingActionNote AS LastActionNote,
    la.entryDate AS LastActionEntryDate,
    la.entryData AS LastActionEntryData,
    la.ExtendReasonTypeID_FK as LastActionExtendReasonTypeID,
    rd.IdaraId_FK ResidentIdaraID,

    ad.ResidentMoveInDate,
    ad.ResidentMoveOutDate
    
FROM Housing.BuildingAction b
LEFT JOIN action_dates ad
    ON ad.RootActionID = b.buildingActionID
LEFT JOIN leaf l
    ON l.RootActionID = b.buildingActionID
   AND l.rn = 1
LEFT JOIN Housing.BuildingAction la
    ON la.buildingActionID = l.buildingActionID
LEFT JOIN Housing.BuildingActionType bt
    ON bt.buildingActionTypeID = l.buildingActionTypeID_FK
LEFT JOIN Housing.ResidentInfo ri
    ON ri.residentInfoID = b.residentInfoID_FK

-- ✅ اختر آخر ResidentDetails Active فقط (بدون تكرار)
OUTER APPLY (
    SELECT TOP (1) rd1.*
    FROM Housing.ResidentDetails rd1
    WHERE rd1.residentInfoID_FK = ri.residentInfoID
      AND rd1.IdaraId_FK = b.IdaraId_FK
      AND rd1.residentDetailsActive = 1
    ORDER BY rd1.residentDetailsID DESC
) rd

LEFT JOIN Housing.WaitingClass wc
    ON b.buildingActionExtraType1 = wc.waitingClassID
LEFT JOIN Housing.WaitingOrderType wo
    ON b.buildingActionExtraType2 = wo.waitingOrderTypeID
LEFT JOIN dbo.Idara i
    ON b.IdaraId_FK = i.idaraID
LEFT JOIN dbo.Idara it
    ON l.IdaraId_FK = it.idaraID
LEFT JOIN dbo.Idara toidara
    ON la.buildingActionExtraInt1 = toidara.idaraID
WHERE b.buildingActionTypeID_FK in(1,7)
  AND b.buildingActionActive = 1;

GO
/****** Object:  View [Housing].[V_ResidentBillsFinancialSummary]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE   VIEW [Housing].[V_ResidentBillsFinancialSummary]
AS
SELECT
    f.residentInfoID,

    -- إجمالي فواتير الإيجار
    ISNULL(
        (
            SELECT SUM(r.TotalPrice)
            FROM Housing.Bills r
            WHERE r.residentInfoID_FK = f.residentInfoID and r.BillChargeTypeID_FK = 1
              AND r.BillActive = 1
        ), 0
    ) AS TotalRentBillsAmount,

    -- إجمالي المدفوع من الإيجار
    ISNULL(
        (
            SELECT SUM(p.amount)
            FROM Housing.BuildingPayment p
            WHERE p.residentInfoID_FK = f.residentInfoID
            and p.BillChargeTypeID_FK = 1
            and p.buildingPayementActive = 1
        ), 0
    ) AS TotalRentBillsPaid,

    -- إجمالي فواتير الكهرباء
    ISNULL(
        (
            SELECT SUM(r.TotalPrice)
            FROM Housing.Bills r
            WHERE r.residentInfoID_FK = f.residentInfoID and r.BillChargeTypeID_FK = 2
              AND r.BillActive = 1
        ), 0
    ) AS TotalElectrecityBillsAmount,

     -- إجمالي المدفوع من الكهرباء
    ISNULL(
        (
            SELECT SUM(p.amount)
            FROM Housing.BuildingPayment p
            WHERE p.residentInfoID_FK = f.residentInfoID
            and p.BillChargeTypeID_FK = 2
            and p.buildingPayementActive = 1
        ), 0
    ) AS TotalElectrecityBillsPaid,

     -- إجمالي فواتير الماء
    ISNULL(
        (
            SELECT SUM(r.TotalPrice)
            FROM Housing.Bills r
            WHERE r.residentInfoID_FK = f.residentInfoID and r.BillChargeTypeID_FK = 3
              AND r.BillActive = 1
        ), 0
    ) AS TotalWaterBillsAmount,

     -- إجمالي المدفوع من الماء
     ISNULL(
        (
            SELECT SUM(p.amount)
            FROM Housing.BuildingPayment p
            WHERE p.residentInfoID_FK = f.residentInfoID
            and p.BillChargeTypeID_FK = 3
            and p.buildingPayementActive = 1
        ), 0
    ) AS TotalWaterBillsPaid,


      -- إجمالي فواتير الغاز
    ISNULL(
        (
            SELECT SUM(r.TotalPrice)
            FROM Housing.Bills r
            WHERE r.residentInfoID_FK = f.residentInfoID and r.BillChargeTypeID_FK = 4
              AND r.BillActive = 1
        ), 0
    ) AS TotalGasBillsAmount,

     -- إجمالي المدفوع من الغاز
    ISNULL(
        (
            SELECT SUM(p.amount)
            FROM Housing.BuildingPayment p
            WHERE p.residentInfoID_FK = f.residentInfoID
            and p.BillChargeTypeID_FK = 4
            and p.buildingPayementActive = 1

        ), 0
    ) AS TotalGasBillsPaid,

       -- إجمالي فواتير الغرامات
    ISNULL(
        (
            SELECT SUM(r.TotalPrice)
            FROM Housing.Bills r
            WHERE r.residentInfoID_FK = f.residentInfoID and r.BillChargeTypeID_FK = 5
              AND r.BillActive = 1
        ), 0
    ) AS TotalFineBillsAmount,

     -- إجمالي المدفوع من الغرامات
    ISNULL(
        (
            SELECT SUM(p.amount)
            FROM Housing.BuildingPayment p
            WHERE p.residentInfoID_FK = f.residentInfoID
            and p.BillChargeTypeID_FK = 5
            and p.buildingPayementActive = 1
        ), 0
    ) AS TotalFineBillsPaid

 

FROM Housing.V_GetFullResidentDetails f;
GO
