/****** Object:  View [Housing].[V_GetListMetersLinkedWithBuildings]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Housing].[V_GetListMetersLinkedWithBuildings]
AS
SELECT        m.meterID, m.meterTypeID_FK, m.meterNo, m.meterName_A, m.meterName_E, m.meterDescription, mt.meterServiceTypeID_FK, mb.meterID_FK, mb.buildingDetailsID_FK, bd.buildingDetailsNo, bd.buildingUtilityTypeID_FK, 
                         msp.meterServicePrice, msp.meterServicePriceStartDate, msp.meterServicePriceEndDate, mt.meterTypeConversionFactor, m.IdaraId_FK AS MeterIdaraId, bd.IdaraId_FK AS BuildingIdaraID
FROM            Housing.MeterForBuilding AS mb INNER JOIN
                         Housing.BuildingDetails AS bd ON mb.buildingDetailsID_FK = bd.buildingDetailsID INNER JOIN
                         Housing.Meter AS m ON mb.meterID_FK = m.meterID INNER JOIN
                         Housing.MeterType AS mt ON m.meterTypeID_FK = mt.meterTypeID INNER JOIN
                         Housing.MeterServiceType AS mst ON mt.meterServiceTypeID_FK = mst.meterServiceTypeID INNER JOIN
                         Housing.BuildingUtilityType AS but ON bd.buildingUtilityTypeID_FK = but.buildingUtilityTypeID INNER JOIN
                         Housing.MeterServicePrice AS msp ON mt.meterTypeID = msp.meterTypeID_FK
WHERE        (1 = 1) AND (mb.meterForBuildingActive = 1) AND (mb.meterForBuildingStartDate IS NOT NULL) AND (mb.meterForBuildingEndDate IS NULL) AND (bd.buildingDetailsActive = 1) AND (bd.buildingDetailsStartDate IS NOT NULL) AND
                          (bd.buildingDetailsEndDate IS NULL) AND (m.meterActive = 1) AND (m.meterStartDate IS NOT NULL) AND (m.meterEndDate IS NULL) AND (mt.meterTypeActive = 1) AND (mt.meterTypeStartDate IS NOT NULL) AND 
                         (mt.meterTypeEndDate IS NULL)  AND (but.buildingUtilityTypeActive = 1) AND (but.buildingUtilityTypeStartDate IS NOT NULL) AND (but.buildingUtilityTypeEndDate IS NULL) AND 
                         (mst.meterServiceTypeActive = 1) AND (mst.meterServiceTypeStartDate IS NOT NULL) AND (mst.meterServiceTypeEndDate IS NULL) AND (msp.meterServicePriceActive = 1) AND (msp.meterServicePriceStartDate IS NOT NULL)
                         

GO
/****** Object:  View [Housing].[V_GetListAllMetersLastAndBeforeLastRead_WithWrap]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Housing].[V_GetListAllMetersLastAndBeforeLastRead_WithWrap]
AS
WITH Reads AS
(
    SELECT
        mr.meterReadID,
        mr.meterID_FK,
        mr.meterReadValue,
        mr.dateOfRead,
        mr.entryDate,
        ROW_NUMBER() OVER
        (
            PARTITION BY mr.meterID_FK
            ORDER BY
                mr.meterReadID DESC,
                ISNULL(mr.dateOfRead, mr.entryDate) DESC
        ) AS rn
    FROM Housing.MeterRead mr
    WHERE mr.meterReadActive = 1
      AND EXISTS
      (
          SELECT 1
          FROM Housing.V_GetListMetersLinkedWithBuildings ml
          WHERE ml.meterID_FK = mr.meterID_FK
      )
),

LastRead AS
(
    SELECT
        meterID_FK,
        meterReadID     AS LastMeterReadID,
        meterReadValue  AS LastReadValue,
        ISNULL(dateOfRead, entryDate) AS LastReadDate
    FROM Reads
    WHERE rn = 1
),

BeforeLastRead AS
(
    SELECT
        meterID_FK,
        meterReadID     AS BeforeLastMeterReadID,
        meterReadValue  AS BeforeLastReadValue,
        ISNULL(dateOfRead, entryDate) AS BeforeLastReadDate
    FROM Reads
    WHERE rn = 2
),

MeterMax AS
(
    SELECT
        m.meterID,
        mt.meterMaxRead
    FROM Housing.Meter m
    INNER JOIN Housing.MeterType mt
        ON mt.meterTypeID = m.meterTypeID_FK
)

SELECT
    l.meterID_FK,

    l.LastMeterReadID,
    l.LastReadValue,
    l.LastReadDate,

    b.BeforeLastMeterReadID,
    b.BeforeLastReadValue,
    b.BeforeLastReadDate,

    mm.meterMaxRead,

    ReadDiff =
        CASE
            WHEN b.BeforeLastReadValue IS NULL OR l.LastReadValue IS NULL THEN NULL
            WHEN l.LastReadValue >= b.BeforeLastReadValue
                THEN l.LastReadValue - b.BeforeLastReadValue
            WHEN l.LastReadValue < b.BeforeLastReadValue
                THEN (ISNULL(mm.meterMaxRead, 0) - b.BeforeLastReadValue) + l.LastReadValue
        END

FROM LastRead l
LEFT JOIN BeforeLastRead b
    ON b.meterID_FK = l.meterID_FK
LEFT JOIN MeterMax mm
    ON mm.meterID = l.meterID_FK;
GO
