CREATE VIEW [Housing].[V_AllResidentsWithMoreThanOneSera]
AS
SELECT        TOP (100) PERCENT COUNT(*) AS Expr1, generalNo_FK
FROM            Housing.BuildingAction
WHERE        (buildingActionTypeID_FK = 1) AND (generalNo_FK IN
                             (SELECT        GeneralNo
                                FROM            Housing.GetGeneralListActionForResident() AS rr
                                WHERE        (ActionTypeID = 2)))
GROUP BY generalNo_FK
HAVING        (COUNT(*) > 1)
