/****** Object:  View [dbo].[_VIEW_TSK_TasksInfo]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[_VIEW_TSK_TasksInfo] AS 
	SELECT v.*  
		, CASE 
			WHEN v.subComponentName IS NOT NULL THEN v.subComponentName + ISNULL(' ('+v.stepTitle+')','') 
			WHEN v.taskStepID IS NOT NULL AND ISNULL(v.hideStepName,0) = 0  THEN v.stepTitle +' (' + v.parentComponentNameAll +')' 
			ELSE v.taskName 
		END theTask2
		, CASE 
			WHEN v.isSingleTask = 1 THEN v.parentComponentNameAll 
			WHEN v.subComponentNameAll IS NOT NULL THEN v.subComponentNameAll  
			WHEN v.taskStepID IS NOT NULL AND ISNULL(v.hideStepName,0) = 0  THEN v.stepTitle +' (' + v.parentComponentNameAll +')' 
			ELSE v.taskName 
		END theTask 
		, CASE WHEN v.statusID IS NULL THEN 1 ELSE  tl.isUnderprocess END   isUnderprocess
		, tl.isFinished 
		, tl.isCanceled 
		, tl.isNew 
		, tl.isSuccessful 
		, tl.isDelay 

	FROM ( 
		SELECT t.taskID , t.taskName 
			, CASE WHEN tc.isSingleTask = 1 THEN '' 
				ELSE 
					ISNULL
					(
						( SELECT t_.componentName FROM TSK_Task t_  WHERE t.parentID_FK = t_.taskID )
						, (SELECT t_.componentName FROM TSK_Task t_ INNER JOIN TSK_Task tt ON tt.parentID_FK = t_.taskID  WHERE t.parentID_FK = tt.taskID ) 
					) 
				END 
			parentComponentName  
			, ISNULL
				(
					( SELECT t_.componentName FROM TSK_Task t_  WHERE t.parentID_FK = t_.taskID )
					, (SELECT t_.componentName FROM TSK_Task t_ INNER JOIN TSK_Task tt ON tt.parentID_FK = t_.taskID  WHERE t.parentID_FK = tt.taskID ) 
				) parentComponentNameAll
			, t.description , CASE WHEN t.description IS NULL THEN 0 ELSE 1 END hasDescription
			, t.weightMinutes enteredWeightMinutes
			, CASE WHEN  isOrganizer = 1 OR taskStepID IS NULL THEN 0 ELSE t.weightMinutes END weightMinutes  
			, dbo.minutesToHours(CASE WHEN  isOrganizer = 1 OR taskStepID IS NULL THEN 0 ELSE t.weightMinutes END ,'hh mm') durationText
			, t.parentID_FK taskParentID , t.initiatorID_FK , t.componentName 
			, tsc.title subComponentNameAll
			, CASE WHEN ISNULL(hideStepName,0) = 0 THEN tsc.title ELSE NULL END subComponentName
			, tsc.title subComponentTitle , t.subComponentID_FK
			, tp.taskProjectID , tp.taskProjectName , tp.taskProjectTitle 
			, ts.taskStepID , ts.stepName , ts.stepTitle , ts.isMultiRecord ,ts.hideStepName , ts.parentID_FK taskStepParentID 
			, tc.taskComponentID , tc.fieldName , tc.title taskComponentTitle , tc.parentID_FK taskComponentParentID 
			, ISNULL(( SELECT l.taskLabelID_FK FROM _VIEW_TSK_Task_TaskLabel l WHERE l.taskID_FK = t.taskID AND l.taskLabelTypeID = 1 ),1) statusID 
			, ( SELECT l.taskLabelID_FK FROM _VIEW_TSK_Task_TaskLabel l WHERE l.taskID_FK = t.taskID AND l.taskLabelTypeID = 2 ) urgentID
			, CASE WHEN ( SELECT COUNT(*) FROM TSK_TaskStep ts_ WHERE ts_.parentID_FK = t.taskStepID_FK ) > 0 THEN 1 ELSE 0 END isComplex
			, (
				SELECT taskLabelTypeID , taskLabelTypeName  , taskLabelID_FK currentLabel , vttl.labelColor , vttl.fontColor , vttl.class , vttl.borderColor , vttl.taskLabelName , vttl.note 
				FROM _VIEW_TSK_Task_TaskLabel vttl 
				WHERE vttl.taskID_FK = t.taskID 
				FOR JSON PATH , INCLUDE_NULL_VALUES 
			) labels  
			, ( SELECT TOP(1) tl_.note FROM TSK_Task_TaskLabel tl_ WHERE tl_.taskID_FK = t.taskID AND tl_.note IS NOT NULL ORDER BY tl_.TTLID DESC ) lastNote 
			, ts.isFiltered isTaskStepFiltered , ts.isDeletable 
			, ( SELECT TOP(1) tt.taskDurationID_FK FROM TSK_Task tt WHERE tt.taskDurationID_FK IS NOT NULL AND (tt.taskID = t.taskID OR tt.taskID = t.parentID_FK )  ) taskDurationID 
			, pt.taskID parentID_1 , ppt.taskID parentID_2
			, ts.isOrganizer 
			, t.attachmentBookID_FK 
			, CASE WHEN tsc.taskSubComponentID IS NOT NULL THEN 1 ELSE 0 END isSubComponent 
			, tc.isComponentUpdatable , tc.isSubComponentUpdatable , tc.isSingleTask 
			, DATEDIFF(DAY,t.initiationDateTime ,GETDATE() ) taskSince 
		FROM TSK_Task t 
			LEFT OUTER JOIN TSK_TaskStep ts ON t.taskStepID_FK = ts.taskStepID 		
			LEFT OUTER JOIN TSK_TaskComponent tc ON t.taskComponentID_FK = tc.taskComponentID  
			LEFT OUTER JOIN TSK_TaskSubComponent tsc ON t.subComponentID_FK = tsc.taskSubComponentID 
			LEFT OUTER JOIN TSK_Task pt ON t.parentID_FK = pt.taskID 
			LEFT OUTER JOIN TSK_Task ppt ON pt.parentID_FK = ppt.taskID 
			LEFT OUTER JOIN TSK_TaskProject tp ON t.taskProjectID_FK = tp.taskProjectID  
		WHERE t.isActive = 1 AND ISNULL(pt.isActive,1) = 1  AND ISNULL(ppt.isActive,1) = 1 -- SELECT * FROM TSK_TaskComponent 
	) v 
		LEFT OUTER JOIN TSK_TaskLabel tl ON tl.taskLabelID = v.statusID 


GO
/****** Object:  View [dbo].[_VIEW_TSK_TaskParents]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   VIEW [dbo].[_VIEW_TSK_TaskParents]
AS
WITH hierarchy AS
(
    -- مستوى 1: المهام الجذرية (بدون أب)
    SELECT
        t.taskID,
        t.parentID_FK,
        CAST(NULL AS INT) AS parentTaskID,
        CAST(NULL AS INT) AS parentParentTaskID,
        1 AS taskLevel
    FROM dbo.TSK_Task AS t
    WHERE t.parentID_FK IS NULL

    UNION ALL

    -- المستويات التالية: نمرّر الأب والجد
    SELECT
        c.taskID,
        c.parentID_FK,
        h.taskID AS parentTaskID,
        h.parentTaskID AS parentParentTaskID,
        h.taskLevel + 1 AS taskLevel
    FROM dbo.TSK_Task AS c
    INNER JOIN hierarchy AS h
        ON c.parentID_FK = h.taskID
)
SELECT
    taskID,
    parentTaskID,
    parentParentTaskID,
    CASE WHEN taskLevel > 3 THEN 3 ELSE taskLevel END AS taskLevel
FROM hierarchy;
GO
/****** Object:  View [dbo].[TSK_VIEW_FinishedTasks]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   VIEW [dbo].[TSK_VIEW_FinishedTasks]
AS
WITH Hier AS
(
    -- ربط كل مهمة بأطفالها المباشرين (نشطة فقط)
    SELECT 
        p.taskID       AS rootTaskID,
        c.taskID       AS childTaskID
    FROM dbo.TSK_Task AS p
    INNER JOIN dbo.TSK_Task AS c
        ON c.parentID_FK = p.taskID
    WHERE p.isActive = 1
      AND c.isActive = 1

    UNION ALL

    -- توسيع للسلسلة: أحفاد وأحفاد الأحفاد... (نشطة فقط)
    SELECT
        h.rootTaskID,
        gc.taskID      AS childTaskID
    FROM Hier AS h
    INNER JOIN dbo.TSK_Task AS gc
        ON gc.parentID_FK = h.childTaskID
    WHERE gc.isActive = 1
),
Agg AS
(
    -- تجميع لكل rootTask: كم طفل/حفيد غير منتهٍ
    SELECT
        h.rootTaskID                     AS taskID,
        COUNT(*)                         AS totalDescendants,
        SUM(CASE WHEN t.taskStepID_FK IS NULL THEN 1 ELSE 0 END) AS unfinishedDescendants
    FROM Hier AS h
    INNER JOIN dbo.TSK_Task AS t
        ON t.taskID = h.childTaskID
    GROUP BY h.rootTaskID
)
SELECT 
    t.taskID,
    -- لو لا يوجد أحفاد/أطفال أو لا يوجد غير منتهين ⇒ 1
    CASE WHEN ISNULL(a.unfinishedDescendants, 0) = 0 THEN 1 ELSE 0 END AS itsChildrenFinished,
    ISNULL(a.totalDescendants, 0)         AS totalChildren,          -- اختياري: إجمالي الأطفال/الأحفاد
    ISNULL(a.unfinishedDescendants, 0)    AS unfinishedChildren      -- اختياري: غير المنتهين
FROM dbo.TSK_Task AS t
LEFT JOIN Agg AS a
    ON a.taskID = t.taskID;
GO
/****** Object:  View [dbo].[V_MVCProgramMenuTree]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[V_MVCProgramMenuTree] AS
WITH MenuHierarchy AS (
    -- المستوى 0: البرنامج نفسه
    SELECT
        p.programID,
        p.programName_A AS programName,
		p.programLink as programLink,
        CAST(NULL AS bigint) AS menuID,
        CAST(NULL AS NVARCHAR(100)) AS menuName_A,
        CAST(NULL AS INT) AS parentMenuID_FK,
        CAST(NULL AS NVARCHAR(1000)) AS menuLink,
        CAST(NULL AS INT) AS menuSerial,
        CAST(p.programName_A AS NVARCHAR(MAX)) AS fullPath,
        0 AS level
    FROM Program p

    UNION ALL

    -- المستويات 1 إلى 5: القوائم الرئيسية والفرعية
    SELECT
        mh.programID,
        mh.programName,
		null as programLink,
        m.menuID,
        m.menuName_A,
        m.parentMenuID_FK,
        m.menuLink,
        m.menuSerial,
        CAST(mh.fullPath + ' > ' + m.menuName_A AS NVARCHAR(MAX)) AS fullPath,
        mh.level + 1 AS level
    FROM MenuHierarchy mh
    INNER JOIN Menu m ON 
        (mh.level = 0 AND m.programID_FK = mh.programID AND m.parentMenuID_FK IS NULL) -- القوائم الرئيسية
        OR (mh.level > 0 AND m.parentMenuID_FK = mh.menuID) -- القوائم الفرعية
    WHERE mh.level < 5
)
SELECT
    mh.programID,
    mh.programName,
	mh.programLink,
    mh.menuID,
    mh.menuName_A,
    mh.parentMenuID_FK,
    mh.menuLink,
    mh.menuSerial,
    mh.fullPath,
    mh.level
FROM MenuHierarchy mh;

GO
/****** Object:  View [dbo].[V_MVCProgramMenuTree_MenuDistributor]    Script Date: 6/17/2026 11:39:00 AM ******/
