-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE   PROCEDURE [dbo].[_searchInSPsOrViews]  @textToSearch NVARCHAR(1000) , @isCaseInsenstive BIT = NULL 

AS 
	DECLARE @textToSearch_ NVARCHAR(1000)
	IF @isCaseInsenstive = 1 
		SET @textToSearch_ = LOWER(@textToSearch)
	ELSE 
		SET @textToSearch_ = @textToSearch
		PRINT @textToSearch_
	SELECT DISTINCT 
		   o.name AS Object_Name , o.type_desc
	  FROM sys.sql_modules m 
		   INNER JOIN  sys.objects o 
			 ON m.object_id = o.object_id
	 WHERE CASE WHEN @isCaseInsenstive = 1 THEN LOWER(m.definition) ELSE m.definition END Like '%'+@textToSearch_+'%' ESCAPE '\' 
GO
/****** Object:  StoredProcedure [dbo].[ChartsDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[ChartsDL] 
	-- Add the parameters for the stored procedure here
	  @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
    , @UsersID 	      NVARCHAR(400) = NULL
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   
  -- Assign Data

           select c.ChartListName_E from dbo.ChartList c
           inner join dbo.ChartListUsers cl on c.ChartListID = cl.ChartListID_FK

           where c.ChartListActive = 1 and c.ChartListStartDate is not null and (c.ChartListEndDate is null or cast(c.ChartListEndDate as date) < cast(GETDATE() as date))
           AND
           cl.ChartListUsersActive = 1 and cl.ChartListUsersStartDate is not null and (cl.ChartListUsersEndDate is null or cast(cl.ChartListUsersEndDate as date) < cast(GETDATE() as date))
           AND
           cl.UsersID_FK = @UsersID

           order by cl.DisplayOrder asc



           ----------------

IF OBJECT_ID('tempdb..#building') IS NOT NULL
    DROP TABLE #building;

SELECT
    gf.buildingDetailsNo      AS BuildingNo,
    gf.buildingTypeID_FK      AS BuildingTypeID,
    gf.buildingClassID_FK     AS BuildingClassID,
    gf.buildingClassName_A    AS BuildingClassName,
    ISNULL(gf.LastActionTypeID, 8) AS LastAction
INTO #building
FROM Housing.V_GetGeneralListForBuilding gf
LEFT JOIN Housing.V_LastActionForBuilding v
    ON gf.LastActionID = v.buildingActionID
WHERE gf.buildingUtilityTypeID_FK IN (1,11)
and gf.BuildingIdaraID = 1
;

CREATE CLUSTERED INDEX IX_building_LastAction
    ON #building (LastAction);

DECLARE
    @allbuildings       DECIMAL(18,2),
    @Occbuildings       DECIMAL(18,2),
    @Emptybuildings     DECIMAL(18,2),
    @Unknownbuildings   DECIMAL(18,2),
    @Maintancebuildings DECIMAL(18,2),
    @Jawdahbuildings    DECIMAL(18,2),
    @Servicebuildings   DECIMAL(18,2),
    @Readybuildings     DECIMAL(18,2);

SELECT
    @allbuildings       = SUM(CASE WHEN LastAction IN (2,24,3,4,5,15,16,17,9,10,8,11,12,13,14,5) THEN 1 ELSE 0 END), --COUNT(*),
    @Occbuildings       = SUM(CASE WHEN LastAction IN (2,24) THEN 1 ELSE 0 END),
    @Emptybuildings     = SUM(CASE WHEN LastAction IN (3,4,15,16,17) THEN 1 ELSE 0 END),
  --  @Unknownbuildings   = SUM(CASE WHEN LastAction = 8 THEN 1 ELSE 0 END),
    @Maintancebuildings = SUM(CASE WHEN LastAction IN (9,10,8) THEN 1 ELSE 0 END),
    @Jawdahbuildings    = SUM(CASE WHEN LastAction IN (11,12) THEN 1 ELSE 0 END),
    @Servicebuildings   = SUM(CASE WHEN LastAction IN (13,14) THEN 1 ELSE 0 END),
    @Readybuildings     = SUM(CASE WHEN LastAction = 5 THEN 1 ELSE 0 END)
FROM #building;

DECLARE @OccPercentge       DECIMAL(18,2) = (@Occbuildings       / NULLIF(@allbuildings,0)) * 100;
DECLARE @EmptyPercentge     DECIMAL(18,2) = (@Emptybuildings     / NULLIF(@allbuildings,0)) * 100;
DECLARE @MaintancePercentge DECIMAL(18,2) = (@Maintancebuildings / NULLIF(@allbuildings,0)) * 100;
DECLARE @JawdahPercentge    DECIMAL(18,2) = (@Jawdahbuildings    / NULLIF(@allbuildings,0)) * 100;
DECLARE @ServicePercentge   DECIMAL(18,2) = (@Servicebuildings   / NULLIF(@allbuildings,0)) * 100;
DECLARE @ReadyPercentge     DECIMAL(18,2) = (@Readybuildings     / NULLIF(@allbuildings,0)) * 100;

SELECT 1 AS #, N'المشغولة'           AS N'النوع', CAST(@OccPercentge       AS DECIMAL(18,2)) AS Percentages, cast(@Occbuildings as int)      AS N'العدد'
UNION ALL
SELECT 2 AS #, N'المساكن الخالية'    AS N'النوع', CAST(@EmptyPercentge     AS DECIMAL(18,2)) AS Percentages, cast(@Emptybuildings as int)     AS N'العدد'
--UNION ALL
--SELECT 3 AS #, N'المساكن الغير معروفة' AS N'النوع', CAST(@UnknownPercentge   AS DECIMAL(18,2)) AS Percentages, cast(@Unknownbuildings as int)   AS N'العدد'
UNION ALL
SELECT 4 AS #, N'تحت الصيانة'        AS N'النوع', CAST(@MaintancePercentge AS DECIMAL(18,2)) AS Percentages, cast(@Maintancebuildings as int) AS N'العدد'
UNION ALL
SELECT 5 AS #, N'الجودة'             AS N'النوع', CAST(@JawdahPercentge    AS DECIMAL(18,2)) AS Percentages, cast(@Jawdahbuildings as int)    AS N'العدد'
UNION ALL
SELECT 6 AS #, N'الخدمات'            AS N'النوع', CAST(@ServicePercentge   AS DECIMAL(18,2)) AS Percentages, cast(@Servicebuildings as int)   AS N'العدد'
UNION ALL
SELECT 7 AS #, N'جاهزة للتسكين'      AS N'النوع', CAST(@ReadyPercentge     AS DECIMAL(18,2)) AS Percentages, cast(@Readybuildings as int)     AS N'العدد'
UNION ALL
SELECT 8 AS #, N'الاجمالي'           AS N'النوع', CAST(100 AS DECIMAL(18,2))                 AS Percentages, cast(@allbuildings  as int)      AS N'العدد';
			   ---------------------------------------------------
  


   
END
GO
/****** Object:  StoredProcedure [dbo].[GetSessionInfoForMVC]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[GetSessionInfoForMVC]
    @NationalID NVARCHAR(20),
    @Password Nvarchar(200),
    @hostName Nvarchar(200)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @usersID bigint;
    DECLARE @GeneralNo bigint;

    SET @usersID = (
        SELECT TOP(1) u.usersID
        FROM  dbo.Users u 
        WHERE u.nationalID = @NationalID
          AND u.usersActive = 1 
          AND u.usersStartDate IS NOT NULL 
          AND CAST(u.usersStartDate AS date) <= CAST(GETDATE() AS date)
          AND ((CAST(u.usersEndDate AS date) > CAST(GETDATE() AS date)) OR u.usersEndDate IS NULL)
        ORDER BY u.usersID DESC
    );

    -- ✅ تعديل ضروري: لو ما حصل مستخدم، اطلع مباشرة (بدون تكملة)
    IF @usersID IS NULL
    BEGIN
        SELECT
            0 AS userActive,
            N'عذرا لايوجد حساب نشط بالنظام لصاحب الهوية رقم : ' + CONVERT(nvarchar(20), @NationalID) AS Message_;
        RETURN;
    END

    DECLARE @Salt VARBINARY(32);
    DECLARE @StoredHash VARBINARY(64);
    DECLARE @PasswordResult int;

    -- هل يوجد كلمة مرور للمستخدم؟
    IF NOT EXISTS (
        SELECT 1 
        FROM  dbo.usersPassword us
        WHERE us.usersID_FK = @usersID AND us.userPasswordActive = 1
    )
    BEGIN
        SET @PasswordResult = 3;   -- لا يوجد كلمة مرور
    END
    ELSE
    BEGIN
        -- جلب الهاش والسولت
        SELECT TOP (1)
            @Salt = PasswordSalt,
            @StoredHash = PasswordHash
        FROM  dbo.usersPassword
        WHERE usersID_FK = @usersID
          AND userPasswordActive = 1
        ORDER BY entryDate DESC;

        -- فحص كلمة المرور
        IF @StoredHash = HASHBYTES('SHA2_256', @Salt + CAST(@Password AS VARBINARY(200)))
        BEGIN
            SET @PasswordResult = 1;  -- كلمة المرور صحيحة
        END
        ELSE
        BEGIN
            SET @PasswordResult = 0;  -- كلمة المرور خاطئة
        END
    END

    IF (SELECT COUNT(us.usersID) FROM  dbo.[Users] us WHERE us.usersID = @usersID) > 0
    BEGIN
        -- ✅ تعديل ضروري: TRY_CONVERT لتفادي تحويل NVARCHAR إلى BIGINT
        SET @GeneralNo = (
            SELECT TOP(1) TRY_CONVERT(bigint, LTRIM(RTRIM(ud.GeneralNo)))
            FROM  dbo.[Users] us 
            INNER JOIN  dbo.UsersDetails ud ON us.usersID = ud.usersID_FK
            WHERE us.usersID = @usersID
              AND us.usersActive = 1 
              AND us.usersStartDate IS NOT NULL 
              AND CAST(us.usersStartDate AS date) <= CAST(GETDATE() AS date)
              AND ((CAST(us.usersEndDate AS date) > CAST(GETDATE() AS date)) OR us.usersEndDate IS NULL)
            ORDER BY us.entryDate DESC
        );

        IF @GeneralNo IS NULL
            SET @GeneralNo = -99;
    END
    ELSE
    BEGIN
        SET @GeneralNo = -99;
    END

    -- Create a temporary table to store the department info
    DECLARE @DepartmentInfo TABLE (
        UserID bigINT,
        OrganizationName NVARCHAR(255),
        IdaraName NVARCHAR(255),
        DepartmentName NVARCHAR(255),
        SectionName NVARCHAR(255),
        DivisonName NVARCHAR(255),
        DeptCode nvarchar(20),
        OrganizationID INT,
        IdaraID INT,
        DepartmentID INT,
        SectionID INT,
        DivisonID INT
    );

    DECLARE @ThameInfo TABLE (
        UserID bigINT,
        ThameName NVARCHAR(255)
    );

    -- Get the department info first
    INSERT INTO @DepartmentInfo (UserID,OrganizationName,IdaraName, DepartmentName,SectionName,DivisonName, DeptCode,OrganizationID,IdaraID,DepartmentID,SectionID,DivisonID)
    SELECT TOP 1 
        udsd.usersID,
        dsd.OrganizationName,
        dsd.IdaraName,
        dsd.DepartmentName,
        dsd.SectionName,
        dsd.DivisonName,
        d.deptCode,
        dsd.OrganizationID,
        dsd.IdaraID,
        dsd.DepartmentID,
        dsd.SectionID,
        dsd.DivisonID
    FROM dbo.V_GetFullStructureForDSD dsd
    INNER JOIN dbo.V_GetListUsersInDSD udsd ON dsd.DSDID = udsd.DSDID
    left JOIN dbo.Department d ON dsd.DepartmentID = d.deptID
    WHERE udsd.usersID = @usersID;

    -- Combine the user and department information along with photo from Payroll database
    IF (@GeneralNo = -99)
    BEGIN
        SELECT
            0 AS userActive,
            -- ✅ تعديل ضروري: لا تجمع نص مع BIGINT مباشرة
            N'عذرا لايوجد حساب مسجل بالنظام لصاحب الهوية رقم : ' + CONVERT(nvarchar(20), @NationalID) AS Message_;
    END
    ELSE
    BEGIN
        IF (SELECT COUNT(*) 
        FROM  dbo.[Users] uu
        Left JOIN  dbo.UsersDetails ud ON uu.usersID = ud.usersID_FK
        left Join  dbo.UsersAuthType ua on ud.usersAuthTypeID_FK = ua.UsersAuthTypeID
        WHERE uu.usersID = @usersID 
        AND uu.usersActive = 1 and ud.userActive = 1) > 0
        BEGIN
            IF (
                SELECT COUNT(*)
                FROM dbo.[Users] u
                LEFT JOIN @DepartmentInfo d ON u.usersID = d.UserID
                LEFT JOIN @ThameInfo t ON u.usersID = t.UserID
                WHERE u.usersID = @usersID
                  AND u.usersActive = 1
                  AND d.IdaraID IS NOT NULL
                  AND d.DepartmentName IS NOT NULL
            ) > 0
            BEGIN
                IF (@PasswordResult = 1)
                BEGIN
                    SELECT TOP(1)
                        CONCAT_WS(' ', ud.firstName_A, ud.secondName_A, ud.lastName_A) AS fullName, 
                        u.usersID,
                        d.OrganizationID,
                        d.OrganizationName,
                        d.IdaraID,
                        d.IdaraName,
                        d.DepartmentID,
                        d.DepartmentName,
                        d.SectionID,
                        d.SectionName,
                        d.DivisonID,
                        d.DivisonName,
                        (SELECT Photo FROM  dbo.UsersPhoto up WHERE up.usersID_FK = @usersID) AS Photo,
                        CASE WHEN t.ThameName IS NULL THEN 'default' ELSE t.ThameName END AS ThameName,
                        d.DeptCode,
                        u.nationalID,
                        u.usersActive,
                        isNULL(ud.usersAuthTypeID_FK,3) AdminTypeID,
                        isNULL(ua.UsersAuthTypeName_A,N'مستخدم عادي') AdminTypeName,
                        @GeneralNo AS GeneralNo,
                        N'مرحبا بك : ' + CONCAT_WS(' ', ud.firstName_A, ud.secondName_A, ud.lastName_A)
                        + N' تم تسجيل دخولك للنظام في ' + CONVERT(nvarchar(10), GETDATE(), 111)
                        + N' الساعة ' + CONVERT(nvarchar(8), GETDATE(), 108) AS Message_,
                        up.ChangedPassword
                    FROM dbo.[Users] u
                    Left JOIN  dbo.UsersDetails ud ON u.usersID = ud.usersID_FK
                    left Join  dbo.UsersAuthType ua on ud.usersAuthTypeID_FK = ua.UsersAuthTypeID
                    LEFT JOIN @DepartmentInfo d ON u.usersID = d.UserID
                    LEFT JOIN @ThameInfo t ON u.usersID = t.UserID
                    inner Join  dbo.UsersPassword up on u.usersID = up.usersID_FK and up.userPasswordActive = 1
                    WHERE u.usersID = @usersID AND u.usersActive = 1 And ud.userActive = 1
                    order by u.usersID desc
                    ;
                END
                ELSE IF (@PasswordResult = 0)
                BEGIN
                    SELECT
                        0 AS userActive,
                        N'عذرا اسم المستخدم او كلمة المرور غير صحيحة' AS Message_;
                END
                ELSE IF (@PasswordResult = 3)
                BEGIN
                    SELECT
                        0 AS userActive,
                        N'يجب اعادة ضبط كلمة المرور للمستخدم' AS Message_;
                END
            END
            ELSE
            BEGIN
                SELECT
                    0 AS userActive,
                    -- ✅ تعديل ضروري: استخدم الهوية، وتأكد التحويل النصي
                    N'عذرا يوجد خطأ بالهيكل الاداري لصاحب الهوية رقم : ' + CONVERT(nvarchar(20), @NationalID) AS Message_;
            END
        END
        ELSE
        BEGIN
            SELECT
                0 AS userActive,
                N'عذرا لايوجد حساب نشط بالنظام لصاحب الهوية رقم : ' + CONVERT(nvarchar(20), @NationalID) AS Message_;
        END
    END
END;
GO
/****** Object:  StoredProcedure [dbo].[GetUserMenuTree]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[GetUserMenuTree]
    @UsersID int
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH UserPermMenus AS
    (
        -- المنيوهات اللي للمستخدم عليها صلاحية فعلية
        SELECT DISTINCT
            mt.menuID
        FROM dbo.V_MenuTree AS mt
        LEFT JOIN dbo.MenuDistributor AS md
            ON md.menuID_FK = mt.menuID 
           AND md.menuDistributorActive = 1 

        LEFT JOIN dbo.Distributor AS d
            ON d.distributorID = md.distributorID_FK 
           AND d.distributorActive = 1

        INNER JOIN dbo.DistributorPermissionType dpt 
            ON d.distributorID = dpt.distributorID_FK 
           AND dpt.distributorPermissionTypeActive = 1 
           AND dpt.distributorPermissionTypeStartDate IS NOT NULL 
           AND CAST(dpt.distributorPermissionTypeStartDate AS date) <= CAST(GETDATE() AS date)
           AND (
                  dpt.distributorPermissionTypeEndDate IS NULL 
                  OR CAST(dpt.distributorPermissionTypeEndDate AS date) > CAST(GETDATE() AS date)
               )

        INNER JOIN dbo.Permission p 
            ON dpt.distributorPermissionTypeID = p.DistributorPermissionTypeID_FK
           AND p.permissionActive = 1 
           AND p.permissionStartDate IS NOT NULL 
           AND CAST(p.permissionStartDate AS date) <= CAST(GETDATE() AS date)
           AND (
                  p.permissionEndDate IS NULL 
                  OR CAST(p.permissionEndDate AS date) > CAST(GETDATE() AS date)
               )

        INNER JOIN dbo.PermissionType pt 
            ON dpt.permissionTypeID_FK = pt.permissionTypeID
           AND pt.permissionTypeActive = 1 

        LEFT JOIN dbo.V_GetListUsersInDSD dsd 
            ON dsd.usersID = p.UsersID_FK

        LEFT JOIN dbo.V_GetFullStructureForDSD f 
            ON dsd.DSDID = f.DSDID

       -- WHERE dsd.userID = @UserID

        WHERE
        (
           (p.UsersID_FK is not null)
           and
           (p.permissionActive = 1)

           AND

           (cast(p.permissionStartDate as date) <= cast(GETDATE() as date))

           AND

           ((cast(p.permissionEndDate as date) > cast(GETDATE() as date)) OR p.permissionEndDate IS NULL)

           AND

            (
            
                    (p.UsersID_FK = @UsersID)
        
                    OR
        
                    (p.RoleID_FK in 
                    (select d.roleID_FK 
                    from  dbo.UserDistributor ud 
                    inner join  dbo.Distributor d on ud.distributorID_FK = d.distributorID
                    where d.distributorActive = 1 and d.roleID_FK is not null and ud.UDActive = 1 
                    and cast(ud.UDStartDate as date) <= cast(GETDATE() as date) 
                    and ((cast(ud.UDEndDate as date) > cast(GETDATE() as date)) or (ud.UDEndDate is null))
                    and ud.userID_FK = @UsersID
                    ))
        
                    OR
                    (p.DSDID_FK in
                    (
                    select f.DSDID
                    from  dbo.V_GetListUsersInDSD d
                    inner join  dbo.V_GetFullStructureForDSD f on d.DSDID = f.DSDID
                    where d.usersID = @UsersID
                    )
                    )

                    OR
                    (p.distributorID_FK in
                    (
                    select d.distributorID 
                    from  dbo.UserDistributor ud 
                    inner join  dbo.Distributor d on ud.distributorID_FK = d.distributorID
                    where d.distributorActive = 1  and ud.UDActive = 1 
                    and cast(ud.UDStartDate as date) <= cast(GETDATE() as date) 
                    and ((cast(ud.UDEndDate as date) > cast(GETDATE() as date)) or (ud.UDEndDate is null))
                    and ud.userID_FK = @UsersID
                    )
                    )

                    OR
                    (
                    p.UsersID_FK IS NULL AND p.DSDID_FK IS NULL AND p.RoleID_FK IS NULL
                    )

            )
        
        )



    ),
    MenuHierarchy AS
    (
        -- المنيوهات المصرّح بها للمستخدم
        SELECT 
            mt.*
        FROM dbo.V_MenuTree AS mt
        INNER JOIN UserPermMenus AS up
            ON up.menuID = mt.menuID

        UNION ALL

        -- جميع الآباء فوقها
        SELECT 
            parent.*
        FROM dbo.V_MenuTree AS parent
        INNER JOIN MenuHierarchy AS child
            ON child.parentMenuID_FK = parent.menuID
    ),
    ProgramNodes AS
    (
        -- عقد البرامج كـ Level 1
        SELECT DISTINCT
            mh.programID,
            mh.programName_A,
            mh.programName_E,
            mh.programIcon,
            mh.programLink,
            mh.programSerial,

            CAST(NULL AS int)               AS menuID,
            CAST(NULL AS nvarchar(100))     AS menuName_A,
            CAST(NULL AS nvarchar(100))     AS menuName_E,
            CAST(NULL AS nvarchar(4000))    AS menuDescription,
            CAST(NULL AS nvarchar(1000))    AS menuLink,
            CAST(NULL AS int)               AS parentMenuID_FK,
            CAST(NULL AS int)               AS programID_FK,
            CAST(NULL AS int)               AS menuSerial,
            CAST(NULL AS bit)               AS menuActive,
            CAST(NULL AS bit)               AS isDashboard,
            CAST(1 AS int)                  AS LevelNo,     -- البرنامج = لفل 1
            mh.programName_A                AS PathName_A,
            mh.programName_E                AS PathName_E,
            CAST(
                RIGHT('0000' + CAST(ISNULL(mh.programSerial, mh.programID) AS varchar(4)), 4)
                AS varchar(500)
            ) AS SortKey,
            CAST(1 AS int)                  AS HasPermissionForUser,
            mh.programName_A                AS IndentedMenuName
        FROM MenuHierarchy AS mh
    ),
    MenuNodes AS
    (
        -- عقد المنيو من الشجرة مع رفع المستوى +1
        SELECT DISTINCT
            mh.programID,
            mh.programName_A,
            mh.programName_E,
            mh.programIcon,
            mh.programLink,
            mh.programSerial,

            mh.menuID,
            mh.menuName_A,
            mh.menuName_E,
            mh.menuDescription,
            mh.menuLink,
            mh.parentMenuID_FK,
            mh.programID_FK,
            mh.menuSerial,
            mh.menuActive,
            mh.isDashboard,
            mh.LevelNo + 1 AS LevelNo,         -- نرفع المستوى 1 عشان البرنامج يكون 1
            mh.PathName_A,
            mh.PathName_E,
            mh.SortKey,
            CASE 
                WHEN up.menuID IS NULL THEN 0 
                ELSE 1 
            END AS HasPermissionForUser,
            REPLICATE(N'   ', mh.LevelNo) + mh.menuName_A AS IndentedMenuName
        FROM MenuHierarchy AS mh
        LEFT JOIN UserPermMenus AS up
            ON up.menuID = mh.menuID
    )


    --select alls.MPID,alls.menuName_A,alls.MPSerial,alls.MPLink ,alls.parentMenuID_FK,alls.programID,isnull(parentMenuID_FK ,programID ) parents,alls.Levels, alls.MPIcon


    -- النتيجة النهائية: Program + Menus
    SELECT 

        programID as MPID, 
        programName_A AS menuName_A,
        programSerial as MPSerial,
        programLink MPLink,
        parentMenuID_FK,
        --programID_FK as programID,
        parentMenuID_FK  as parents,
        LevelNo as Levels,
        programIcon as MPIcon,


        programName_A AS MenuNameForView,
        LevelNo,
        menuLink,
        PathName_A,
        PathName_E,
        programID,
        programName_A,
        programName_E,
        programIcon,
        programLink,
        programSerial,
        menuID,
        --menuName_A,
        --menuName_E,
        --menuDescription,
        --parentMenuID_FK,
       -- programID_FK,
       -- menuSerial,
       -- menuActive,
       -- isDashboard,
        SortKey,
        HasPermissionForUser,
        IndentedMenuName
        
    FROM ProgramNodes

    UNION ALL

    SELECT 

        menuID as MPID, 
        menuName_A AS menuName_A,
        menuSerial as MPSerial,
        programLink MPLink,
        parentMenuID_FK,
        --programID_FK as programID,
        isnull(parentMenuID_FK ,programID ) as parents,
        LevelNo as Levels,
        --programIcon as MPIcon,
        null as MPIcon,

        menuName_A AS MenuNameForView,
        LevelNo,
        menuLink,
        PathName_A,
        PathName_E,
        programID,
        programName_A,
        programName_E,
        programIcon,
        programLink,
        programSerial,
       
        menuID,
       -- menuName_A,
        --menuName_E,
       -- menuDescription,
       -- parentMenuID_FK,
       -- programID_FK,
       -- menuSerial,
       -- menuActive,
       -- isDashboard,
        SortKey,
        HasPermissionForUser,
        IndentedMenuName
        
    FROM MenuNodes
    ORDER BY 
        SortKey, LevelNo
    OPTION (MAXRECURSION 50);
END
GO
