            ELSE
            BEGIN
                SET @ok = 0;
                SET @msg = N'نوع العملية المطلوبة غير معروف. ActionType';
                GOTO Finish;
            END

            SELECT TOP 1 @ok = IsSuccessful, @msg = Message_ FROM @Result;
            GOTO Finish;
        END


        ----------------------------------------------------------------
        -- PagesManagment
        ----------------------------------------------------------------
        ELSE IF @pageName_ = 'PagesManagment'
        BEGIN
