                    , @entryData = @entrydata
                    , @hostName  = @hostName
                    , @permissionUserID = @parameter_01;
            END
        END

ELSE IF @pageName_ = 'SupportTicketDetails'
        BEGIN
            IF NOT EXISTS (
                SELECT 1
