        EXEC [VIC].[Vehicle_Get_DL]
      @UsersID        = @parameter_01
    , @MenuLink       = @parameter_02
    , @SkipPermission = @parameter_03
    , @chassisNumber  = @parameter_04
    , @idaraID_FK      = @parameter_05;
    END

    -------------------------------------------------------------------
--                     PAGE: Vehicle_GetLookups
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'Vehicle_GetLookups'
    BEGIN
        

        -- Vehicle Lookups Data
        EXEC [VIC].[Vehicle_GetLookups_DL]
      @UsersID            = @parameter_01
    , @MenuLink           = @parameter_02
    , @SkipPermission     = @parameter_03
    , @TypesRoot_ParentID = @parameter_04;
    END

    -------------------------------------------------------------------
--                     PAGE: Vehicle_List
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'Vehiclelist'
    BEGIN
        

        -- Vehicle List Data
        EXEC [VIC].[Vehicle_List_DL]
      @ownerID_FK   = @parameter_01
    , @plateLetters = @parameter_02
    , @plateNumbers = @parameter_03
    , @hasCustody   = @parameter_04
    , @pageNumber   = @parameter_05
    , @pageSize     = @parameter_06
    , @idaraID_FK     = @parameter_07;
    END

    -------------------------------------------------------------------
--                     PAGE: Vehicle_List_EXT
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'Vehicle_List_EXT'
    BEGIN
       

        -- Vehicle List EXT Data
        EXEC [VIC].[Vehicle_List_EXT_DL]
      @UsersID          = @parameter_01
    , @MenuLink         = @parameter_02
    , @SkipPermission   = @parameter_03
    , @q                = @parameter_04
    , @ownerID_FK       = @parameter_05
    , @plateLetters     = @parameter_06
    , @plateNumbers     = @parameter_07
    , @HasCustody       = @parameter_08
    , @HasActiveRequest = @parameter_09
    , @PageNumber       = @parameter_10
    , @PageSize         = @parameter_11
    , @idaraID_FK        = @parameter_12;
    END


    -------------------------------------------------------------------
--                     PAGE: Vehicle_Profile_Get
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'Vehicle_Profile_Get'
    BEGIN
        

        -- Vehicle Profile (multiple result-sets)
        EXEC [VIC].[Vehicle_Profile_Get_DL]
      @UsersID        = @parameter_01
    , @MenuLink       = @parameter_02
    , @SkipPermission = @parameter_03
    , @chassisNumber  = @parameter_04
    , @TopDocuments   = @parameter_05
    , @TopInsurance   = @parameter_06
    , @TopMaintenance = @parameter_07
    , @TopViolations  = @parameter_08
    , @idaraID_FK      = @parameter_09;
    END
-------------------------------------------------------------------
--                     PAGE: Vehicles
-------------------------------------------------------------------
ELSE IF @pageName_ = 'Vehicles'
BEGIN

    -- Vehicle List Data
    EXEC [VIC].[Vehicle_List_DL]
          @ownerID_FK   = @parameter_01
        , @plateLetters = @parameter_02
        , @plateNumbers = @parameter_03
        , @hasCustody   = @parameter_04
        , @pageNumber   = @parameter_05
        , @pageSize     = @parameter_06
        , @idaraID_FK   = @parameter_07;
END
    -------------------------------------------------------------------
--                     PAGE: Vehicle_Search
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'Vehicle_Search'
    BEGIN
       

        -- Vehicle Search (fast by plate OR general q)
        EXEC [VIC].[Vehicle_Search_DL]
      @q            = @parameter_01
    , @plateLetters = @parameter_02
    , @plateNumbers = @parameter_03
    , @Top          = @parameter_04
    , @idaraID_FK     = @parameter_05;
    END

    -------------------------------------------------------------------
--                     PAGE: VehicleDocument_List
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'VehicleDocument_List'
    BEGIN
        

        -- Vehicle Documents List (normal list OR expiring mode)
        EXEC [VIC].[VehicleDocument_List_DL]
      @chassisNumber         = @parameter_01
    , @vehicleDocumentTypeID = @parameter_02
    , @DocumentNo            = @parameter_03
    , @OnlyActiveNow         = @parameter_04
    , @Page                  = @parameter_05
    , @PageSize              = @parameter_06
    , @ExpireDays            = @parameter_07
    , @IncludeExpired        = @parameter_08
    , @idaraID_FK            = @parameter_09;
    END

    -------------------------------------------------------------------
--                     PAGE: VehicleDocumentType_List
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'VehicleDocumentType_List'
    BEGIN
        

        -- Vehicle Document Types (Lookup/Dropdown)
        EXEC [VIC].[VehicleDocumentType_List_DL]
    @ActiveOnly = @parameter_01;
    END

    -------------------------------------------------------------------
--                     PAGE: VehicleInsurance_List
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'VehicleInsurance_List'
    BEGIN
        

        -- Vehicle Insurance List (filters + optional expiring)
       EXEC [VIC].[VehicleInsurance_List_DL]
      @chassisNumber   = @parameter_01
    , @InsuranceTypeID = @parameter_02
    , @OperationTypeID = @parameter_03
    , @Active          = @parameter_04
    , @FromDate        = @parameter_05
    , @ToDate          = @parameter_06
    , @Page            = @parameter_07
    , @PageSize        = @parameter_08
    , @Days            = @parameter_09
    , @IncludeExpired  = @parameter_10;
    END

    -------------------------------------------------------------------
--                     PAGE: Violation_GetLookups
-------------------------------------------------------------------
   ----------------------------------------------------------------
-- Violation_GetLookups
----------------------------------------------------------------
ELSE IF @pageName_ = 'Violation_GetLookups'
BEGIN
    EXEC [VIC].[Violation_GetLookups_DL]
          @ActiveOnly = @parameter_01;
END

    -------------------------------------------------------------------
--                     PAGE: Violation_List
-------------------------------------------------------------------
    ELSE IF @pageName_ = 'Violation_List'
    BEGIN
        

        -- Violations List (filters + paging)
        EXEC [VIC].[Violation_List_DL]
      @chassisNumber   = @parameter_01
    , @violationTypeID = @parameter_02
    , @Paid            = @parameter_03
    , @FromDate        = @parameter_04
    , @ToDate          = @parameter_05
    , @Page            = @parameter_06
    , @PageSize        = @parameter_07
    , @idaraID_FK       = @parameter_08;
    END
     -------------------------------------------------------------------
--                    Violation_Get
-------------------------------------------------------------------

    ELSE IF @pageName_ = 'Violation_Get'
BEGIN
    EXEC [VIC].[Violation_Get_DL]
          @violationID = @parameter_01
        , @idaraID_FK  = @parameter_02;
END





    -- ============================================================
    --                       TICKETS MODULE
    -- ============================================================
    ELSE IF @pageName_ IN (N'TicketList', N'TicketDetails', N'TicketHistory', N'StatusDDL',
                           N'ChildTickets', N'PauseSessions', N'TicketSLAs',
                           N'QualityReviews', N'ArbitrationCases', N'TicketAttachments',
                           N'PauseReasonDDL', N'ArbitrationReasonDDL', N'QualityReviewResultDDL',
                           N'RequesterTypeDDL', N'TicketClassDDL', N'PriorityDDL',
                           N'OpenArbitrations', N'PendingReviews', N'BreachedSLAs',
                           N'TicketAdminLookup', N'ResidentDDL', N'BuildingDDL',
                           N'TicketReasonDDL', N'TicketDescriptionTemplateDDL', N'DSDDL', N'DsdUsersDDL', N'DsdUsersAllDDL')
    BEGIN
        EXEC [Tickets].[TicketDL]
              @pageName_   = @pageName_
            , @idaraID     = @idaraID
            , @entryData   = @entrydata
            , @hostName    = @hostname
            , @filterTicketID       = @parameter_01
            , @filterTicketNo       = @parameter_02
            , @filterStatusID       = @parameter_03
            , @filterServiceID      = @parameter_04
            , @filterAssignedUserID = @parameter_05
            , @filterDSDID          = @parameter_06;
    END

              ELSE IF @pageName_ IN (N'ServiceCatalogueList', N'RoutingRuleLookup', N'SLAPolicyLookup',
                   N'SuggestionReview', N'ServiceDDL')
              BEGIN
            EXEC [Tickets].[ServiceDL]
                  @pageName_             = @pageName_
                , @idaraID               = @idaraID
                , @entryData             = @entrydata
                , @hostName              = @hostname
                , @filterServiceID       = @parameter_01
                , @filterTicketClassID   = @parameter_02;
              END

    -------------------------------------------------------------------
    --                     PAGE NOT FOUND
    --            DO NOT TOUCH DOWN THIS LINE PLEASE
    -------------------------------------------------------------------
        ELSE
        BEGIN
            SELECT 0 AS IsSuccessful, N'الصفحة المرسلة مقيدة. PageName' AS Message_;
        END

        COMMIT TRANSACTION;
    END TRY

    -------------------------------------------------------------------
    --                     CATCH BLOCK
    -------------------------------------------------------------------
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity INT, @ErrState INT, @IdentityCatchError INT;

        SELECT 
              @ErrMsg      = ERROR_MESSAGE(),
              @ErrSeverity = ERROR_SEVERITY(),
              @ErrState    = ERROR_STATE();

        INSERT INTO  dbo.ErrorLog
        (
              ERROR_MESSAGE_
            , ERROR_SEVERITY_
            , ERROR_STATE_
            , SP_NAME
            , entryData
            , hostName
        )
        VALUES
        (
              @ErrMsg
            , @ErrSeverity
            , @ErrState
            , N'[dbo].[Masters_DataLoad]'
            , @entrydata
            , @hostname
        );

        SET @IdentityCatchError = SCOPE_IDENTITY();

        SELECT 
              0 AS IsSuccessful,
              N'حصل خطأ غير معروف رمز الخطأ : ' + CAST(@IdentityCatchError AS NVARCHAR(200)) AS Message_;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[Masters_ExtraDataLoad]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Masters_ExtraDataLoad]
      @pageName_      NVARCHAR(400)
    , @ActionType     NVARCHAR(100)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
    , @parameter_01   NVARCHAR(4000) = NULL
    , @parameter_02   NVARCHAR(4000) = NULL
    , @parameter_03   NVARCHAR(4000) = NULL
    , @parameter_04   NVARCHAR(4000) = NULL
    , @parameter_05   NVARCHAR(4000) = NULL
    , @parameter_06   NVARCHAR(4000) = NULL
    , @parameter_07   NVARCHAR(4000) = NULL
    , @parameter_08   NVARCHAR(4000) = NULL
    , @parameter_09   NVARCHAR(4000) = NULL
    , @parameter_10   NVARCHAR(4000) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -------------------------------------------------------------------
    --                   START TRY BLOCK
    -------------------------------------------------------------------

     -------------------------------------------------------------------
    --                   Residents
    -------------------------------------------------------------------
    BEGIN TRY
        BEGIN TRANSACTION;


        IF @pageName_ = 'Residents'
        BEGIN
         IF @ActionType = 'ResidentActions'
            BEGIN
                Select top(1)
                     [buildingActionID]
                    ,[buildingActionUDID]
                    ,[buildingActionTypeID_FK]
                    ,[buildingStatusID_FK]
                    ,[residentInfoID_FK]
                    ,[generalNo_FK]
                    ,[buildingPaymentTypeID_FK]
                    ,[buildingDetailsID_FK]
                    ,[buildingDetailsNo]
                    ,[buildingActionFromDate]
                    ,[buildingActionToDate]
                    ,[buildingActionDate]
                    ,[buildingActionDate2]
                    ,[buildingActionDecisionNo]
                    ,[buildingActionDecisionDate]
                    ,[fromDSD_FK]
                    ,[toDSD_FK]
                    ,[buildingActionFromSourceID_FK]
                    ,[buildingActionToSourceID_FK]
                    ,[buildingActionNote]
                    ,[buildingActionExtraText1]
                    ,[buildingActionExtraText2]
                    ,[buildingActionExtraText3]
                    ,[buildingActionExtraText4]
                    ,[buildingActionExtraDate1]
                    ,[buildingActionExtraDate2]
                    ,[buildingActionExtraDate3]
                    ,[buildingActionExtraFloat1]
                    ,[buildingActionExtraFloat2]
                    ,[buildingActionExtraInt1]
                    ,[buildingActionExtraInt2]
                    ,[buildingActionExtraInt3]
                    ,[buildingActionExtraInt4]
                    ,[buildingActionExtraType1]
                    ,[buildingActionExtraType2]
                    ,[buildingActionExtraType3]
                    ,[buildingActionActive]
                    ,[buildingActionParentID]
                    ,[CustdyRecord]
                    ,[AssignPeriodID_FK]
                    ,[ExtendReasonTypeID_FK]
                    ,[IdaraId_FK]
                    ,[entryDate]
                    ,[entryData]
                    ,[hostName]
                       from
                       Housing.BuildingAction w
                       where w.residentInfoID_FK = @parameter_01 --and w.buildingActionTypeID_FK = @parameter_02

                       order by buildingActionID asc

            END





            

        END



    -------------------------------------------------------------------
    --                   AllMeterRead
    -------------------------------------------------------------------

         ELSE IF @pageName_ = 'AllMeterRead'
        BEGIN
         IF @ActionType = 'MeterLastBill'
BEGIN

    IF EXISTS
    (
        SELECT 1
        FROM Housing.MeterRead mr
        WHERE mr.meterID_FK = @parameter_02
          AND mr.meterReadActive = 1
    )
    BEGIN
        SELECT TOP (1)
               mr.meterID_FK AS meterID,
               m.meterNo,
               mr.meterReadValue AS CurrentRead,
               ISNULL(bp.billPeriodName_A + N' - ' + CAST(DATEPART(YEAR, bp.billPeriodStartDate) AS NVARCHAR), N' - ') AS periods_,
               ISNULL(b.TotalPrice, 0) AS TotalPrice
        FROM Housing.MeterRead mr
        LEFT JOIN Housing.Meter m
            ON m.meterID = mr.meterID_FK
        LEFT JOIN Housing.Bills b
            ON b.meterReadID = mr.meterReadID
           AND b.BillActive = 1
           AND b.meterServiceTypeID = @parameter_01
           AND b.CurrentPeriodID <> @parameter_03
        LEFT JOIN Housing.BillPeriod bp
            ON bp.BillPeriodID = b.CurrentPeriodID
        WHERE mr.meterID_FK = @parameter_02
          AND mr.meterReadActive = 1
        ORDER BY
            ISNULL(mr.dateOfRead, mr.entryDate) DESC,
            mr.meterReadID DESC;
    END
    ELSE
    BEGIN
        SELECT TOP (1)
               md.meterID,
               md.meterNo,
               CAST(N'لا يوجد قراءة سابقة' AS NVARCHAR(200)) AS CurrentRead,
               N' - ' AS periods_,
               CAST(N'لا يوجد فاتورة سابقة' AS NVARCHAR(200)) AS TotalPrice
        FROM Housing.V_MetersDetails md
        WHERE md.meterID = @parameter_02
          AND md.meterServiceTypeID_FK = @parameter_01;
    END

END
ELSE IF @ActionType = 'MeterNewBill'
BEGIN

    SELECT 
        CASE 
            WHEN s.LastRead > s.CurrentRead THEN 0
            WHEN s.LastRead = s.CurrentRead THEN 0
            ELSE 1
        END AS checks,
        s.CurrentRead,
        s.LastRead,
        s.ReadDiff,
        s.PRICE,
        s.PRICETAX,
        s.meterServicePrice,
        s.meterServicePriceTAX,
        (s.meterServicePrice + s.meterServicePriceTAX) AS ServicePriceWithTAX,
        s.TotalPrice,
        s.meterID,
        s.meterNo,
        s.CurrentPeriodID
    FROM Housing.CalculteElectrictyBills_ByNewReadValue(@parameter_02, @parameter_04) s;

END


            ELSE  IF @ActionType = 'EDITBILL'
            BEGIN


            select b.BillsID,b.meterNo,b.CurrentRead,b.LastRead,b.CurrentPeriodID,b.ReadDiff, b.TotalPrice,mst.meterServiceTypeName_A
            FROM Housing.Bills b
            inner join Housing.MeterServiceType mst on b.meterServiceTypeID = mst.meterServiceTypeID
            where b.BillsID = @parameter_01
            END


        END

        -------------------------------------------------------------------
    --                   AllMeterRead
    -------------------------------------------------------------------

         ELSE IF @pageName_ = 'MeterReadForOccubentAndExit'
        BEGIN
        IF @ActionType = 'MeterLastBill'
BEGIN

    IF EXISTS
    (
        SELECT 1
        FROM Housing.MeterRead mr
        WHERE mr.meterID_FK = @parameter_02
          AND mr.meterReadActive = 1
    )
    BEGIN
        SELECT TOP (1)
               mr.meterID_FK AS meterID,
               m.meterNo,
               mr.meterReadValue AS CurrentRead,
               ISNULL(bp.billPeriodName_A + N' - ' + CAST(DATEPART(YEAR, bp.billPeriodStartDate) AS NVARCHAR), N' - ') AS periods_,
               ISNULL(b.TotalPrice, 0) AS TotalPrice
        FROM Housing.MeterRead mr
        LEFT JOIN Housing.Meter m
            ON m.meterID = mr.meterID_FK
        LEFT JOIN Housing.Bills b
            ON b.meterReadID = mr.meterReadID
           AND b.BillActive = 1
           AND b.meterServiceTypeID = @parameter_01
        LEFT JOIN Housing.BillPeriod bp
            ON bp.BillPeriodID = b.CurrentPeriodID
        WHERE mr.meterID_FK = @parameter_02
          AND mr.meterReadActive = 1
        ORDER BY
            ISNULL(mr.dateOfRead, mr.entryDate) DESC,
            mr.meterReadID DESC;
    END
    ELSE
    BEGIN
        SELECT TOP (1)
               md.meterID,
               md.meterNo,
               CAST(N'لا يوجد قراءة سابقة' AS NVARCHAR(200)) AS CurrentRead,
               N' - ' AS periods_,
               CAST(N'لا يوجد فاتورة سابقة' AS NVARCHAR(200)) AS TotalPrice
        FROM Housing.V_MetersDetails md
        WHERE md.meterID = @parameter_02
          AND md.meterServiceTypeID_FK = @parameter_01;
    END

END
ELSE IF @ActionType = 'MeterNewBill'
BEGIN

    SELECT 
        CASE 
            WHEN s.LastRead > s.CurrentRead THEN 0
            WHEN s.LastRead = s.CurrentRead THEN 0
            ELSE 1
        END AS checks,
        s.CurrentRead,
        s.LastRead,
        s.ReadDiff,
        s.PRICE,
        s.PRICETAX,
        s.meterServicePrice,
        s.meterServicePriceTAX,
        (s.meterServicePrice + s.meterServicePriceTAX) AS ServicePriceWithTAX,
        s.TotalPrice,
        s.meterID,
        s.meterNo,
        s.CurrentPeriodID
    FROM Housing.CalculteElectrictyBills_ByNewReadValue(@parameter_02, @parameter_04) s;

END

            ELSE  IF @ActionType = 'EDITBILL'
            BEGIN


            select b.BillsID,b.meterNo,b.CurrentRead,b.LastRead,b.CurrentPeriodID,b.ReadDiff, b.TotalPrice,mst.meterServiceTypeName_A
            FROM Housing.Bills b
            inner join Housing.MeterServiceType mst on b.meterServiceTypeID = mst.meterServiceTypeID
            where b.BillsID = @parameter_01
            END


        END




         -------------------------------------------------------------------
    --                  ImportExcelForBuildingPayment
    -------------------------------------------------------------------


         ELSE IF @pageName_ = 'ImportExcelForBuildingPayment'
        BEGIN
         IF @ActionType = 'GetBuildingPaymentByDeductList'
            BEGIN

                   SELECT [paymentID]
                        ,[PaymentUID]
                        ,[buildingPaymentTypeID_FK]
                        ,[generalNo_FK]
                        ,[IDNumber]
                        ,[residentInfoID_FK]
                        ,[rankNameA]
                        ,[unitID]
                        ,[userName]
                        ,[buildingDetailsID_FK]
                        ,[amount]
                        ,[deductListID_FK]
                        ,[buildingPayementActive]
                        ,[BillChargeTypeID_FK]
                        ,[IdaraId_FK]
                        ,[entryDate]
                        ,[entryData]
                        ,[hostName]
                    FROM [DATACORE].[Housing].[BuildingPayment] bb
                    where bb.buildingPayementActive = 1 and bb.deductListID_FK = @parameter_01

                
            END
                ELSE  IF @ActionType = 'MeterNewBill'
            BEGIN


            SELECT s.CurrentRead,s.LastRead,s.ReadDiff,s.PRICE,s.PRICETAX,s.meterServicePrice,s.meterServicePriceTAX,(s.meterServicePrice+s.meterServicePriceTAX) ServicePriceWithTAX,s.TotalPrice,s.meterID,s.meterNo,s.CurrentPeriodID
            FROM Housing.CalculteElectrictyBills_ByNewReadValue(@parameter_02, @parameter_04) s;

            END


            ELSE  IF @ActionType = 'EDITBILL'
            BEGIN


            select b.BillsID,b.meterNo,b.CurrentRead,b.LastRead,b.CurrentPeriodID,b.ReadDiff, b.TotalPrice
            FROM Housing.Bills b
            where b.BillsID = @parameter_01
            END


        END




     -------------------------------------------------------------------
    --                  FinancialAuditForExtendAndEvictions
    -------------------------------------------------------------------


         ELSE IF @pageName_ = 'FinancialAuditForExtendAndEvictions'
        BEGIN
         IF @ActionType = 'GetBillsTotalPriceForResident'
            BEGIN

                   
        SELECT 
        r.BillsID,
        r.BillNumber,
        r.TotalPrice,
        r.residentInfoID_FK AS residentInfoID,
        r.BillChargeTypeID_FK AS BillChargeTypeID,
        bct.BillChargeTypeName_A, r.buildingDetailsID,
        b.buildingDetailsNo,
        r.idaraID_FK AS idaraID,
        vgrd.FullName_A
        FROM   Housing.Bills AS r 
        INNER JOIN Housing.BillChargeType AS bct ON r.BillChargeTypeID_FK = bct.BillChargeTypeID
        LEFT JOIN  Housing.V_GetGeneralListForBuilding b on r.buildingDetailsID = b.buildingDetailsID
        LEFT JOIN Housing.V_GetFullResidentDetails AS vgrd ON r.residentInfoID_FK = vgrd.residentInfoID


        WHERE (r.BillActive = 1) 
        and (r.residentInfoID_FK = @parameter_01) 
        and (r.BillChargeTypeID_FK = @parameter_02) 
        and (r.buildingDetailsID = @parameter_03 or r.buildingDetailsID is null) 
        and (r.idaraID_FK = @idaraID)

                
            END
                ELSE  IF @ActionType = 'GetBillsPaidByResident'
            BEGIN


            SELECT 
            bp.amount ,
            bp.residentInfoID_FK AS residentInfoID,
            bp.BillChargeTypeID_FK AS BillChargeTypeID,
            t.BillChargeTypeName_A,
            bp.buildingDetailsID_FK AS buildingDetailsID,
            bd.buildingDetailsNo,
            vgrd.FullName_A,
            d.deductName
            FROM   Housing.BuildingPayment AS bp INNER JOIN
                         Housing.DeductList AS d ON bp.deductListID_FK = d.deductListID INNER JOIN
                         Housing.BillChargeType AS t ON bp.BillChargeTypeID_FK = t.BillChargeTypeID INNER JOIN
                         Housing.BuildingDetails AS bd ON bp.buildingDetailsID_FK = bd.buildingDetailsID LEFT JOIN
                         Housing.V_GetFullResidentDetails AS vgrd ON bp.residentInfoID_FK = vgrd.residentInfoID
                        
            WHERE 
            (d.deductActive = 1) 
            AND (bp.buildingPayementActive = 1) 
            AND(bp.residentInfoID_FK = @parameter_01) 
            AND (bp.BillChargeTypeID_FK = @parameter_02) 
            AND (bp.IdaraId_FK = 1) 
            AND (bp.buildingDetailsID_FK = @parameter_03 or bp.buildingDetailsID_FK is null)


            END


            ELSE  IF @ActionType = 'EDITBILL'
            BEGIN


            select b.BillsID,b.meterNo,b.CurrentRead,b.LastRead,b.CurrentPeriodID,b.ReadDiff, b.TotalPrice
            FROM Housing.Bills b
            where b.BillsID = @parameter_01
            END


        END


    -------------------------------------------------------------------
    --                  FinancialAuditForExtendAndEvictions
    -------------------------------------------------------------------


         ELSE IF @pageName_ = 'FinancialAuditForUser'
        BEGIN
         IF @ActionType = 'GetBillsTotalPriceForResident'
            BEGIN

                   
        SELECT 
        r.BillsID,
        r.BillNumber,
        r.TotalPrice,
        r.residentInfoID_FK AS residentInfoID,
        r.BillChargeTypeID_FK AS BillChargeTypeID,
        bct.BillChargeTypeName_A, r.buildingDetailsID,
        b.buildingDetailsNo,
        r.idaraID_FK AS idaraID,
        vgrd.FullName_A
        FROM   Housing.Bills AS r 
        INNER JOIN Housing.BillChargeType AS bct ON r.BillChargeTypeID_FK = bct.BillChargeTypeID
        LEFT JOIN  Housing.V_GetGeneralListForBuilding b on r.buildingDetailsID = b.buildingDetailsID
        LEFT JOIN Housing.V_GetFullResidentDetails AS vgrd ON r.residentInfoID_FK = vgrd.residentInfoID


        WHERE (r.BillActive = 1) 
        and (r.residentInfoID_FK = @parameter_01) 
        and (r.BillChargeTypeID_FK = @parameter_02) 
        and (r.buildingDetailsID = @parameter_03 or r.buildingDetailsID is null) 
        and (r.idaraID_FK = @idaraID)

                
            END
                ELSE  IF @ActionType = 'GetBillsPaidByResident'
            BEGIN


            SELECT 
            bp.amount ,
            bp.residentInfoID_FK AS residentInfoID,
            bp.BillChargeTypeID_FK AS BillChargeTypeID,
            t.BillChargeTypeName_A,
            bp.buildingDetailsID_FK AS buildingDetailsID,
            bd.buildingDetailsNo,
            vgrd.FullName_A
            FROM   Housing.BuildingPayment AS bp INNER JOIN
                         Housing.DeductList AS d ON bp.deductListID_FK = d.deductListID INNER JOIN
                         Housing.BillChargeType AS t ON bp.BillChargeTypeID_FK = t.BillChargeTypeID INNER JOIN
                         Housing.BuildingDetails AS bd ON bp.buildingDetailsID_FK = bd.buildingDetailsID LEFT JOIN
                         Housing.V_GetFullResidentDetails AS vgrd ON bp.residentInfoID_FK = vgrd.residentInfoID
            WHERE 
            (d.deductActive = 1) 
            AND (bp.buildingPayementActive = 1) 
            AND(bp.residentInfoID_FK = @parameter_01) 
            AND (bp.BillChargeTypeID_FK = @parameter_02) 
            AND (bp.IdaraId_FK = 1) 
            AND (bp.buildingDetailsID_FK = @parameter_03 or bp.buildingDetailsID_FK is null)


            END


            ELSE  IF @ActionType = 'EDITBILL'
            BEGIN


            select b.BillsID,b.meterNo,b.CurrentRead,b.LastRead,b.CurrentPeriodID,b.ReadDiff, b.TotalPrice
            FROM Housing.Bills b
            where b.BillsID = @parameter_01
            END


        END


          -------------------------------------------------------------------
    --                  FinancialAuditForExtendAndEvictions
    -------------------------------------------------------------------


         ELSE IF @pageName_ = 'WaitingListByResident'
        BEGIN
         IF @ActionType = 'GetWaitingListActions'
            BEGIN

               select b.buildingActionTypeResidentAlias
              ,convert(nvarchar(10),c.entryDate,23)+' '+convert(nvarchar(10),c.entryDate,8) as entryDate
              ,u.FullName
              from [Housing].[fn_BuildingAction_ChainToRoot](@parameter_01) c
              inner join Housing.BuildingActionType b on c.buildingActionTypeID_FK = b.buildingActionTypeID
              inner join dbo.V_GetFullSystemUsersDetails u on c.entryData = u.usersID    
       
            END


            


        END



    -------------------------------------------------------------------
    --                     PAGE NOT FOUND
    --            DO NOT TOUCH DOWN THIS LINE PLEASE
    -------------------------------------------------------------------
        ELSE
        BEGIN
            SELECT 0 AS IsSuccessful, N'الصفحة المرسلة مقيدة. PageName' AS Message_;
        END

        COMMIT TRANSACTION;
    END TRY

    -------------------------------------------------------------------
    --                     CATCH BLOCK
    -------------------------------------------------------------------
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrMsg NVARCHAR(4000), @ErrSeverity INT, @ErrState INT, @IdentityCatchError INT;

        SELECT 
              @ErrMsg      = ERROR_MESSAGE(),
              @ErrSeverity = ERROR_SEVERITY(),
              @ErrState    = ERROR_STATE();

        INSERT INTO DATACORE.dbo.ErrorLog
        (
              ERROR_MESSAGE_
            , ERROR_SEVERITY_
            , ERROR_STATE_
            , SP_NAME
            , entryData
            , hostName
        )
        VALUES
        (
              @ErrMsg
            , @ErrSeverity
            , @ErrState
            , N'[dbo].[Masters_DataLoad]'
            , @entrydata
            , @hostname
        );

        SET @IdentityCatchError = SCOPE_IDENTITY();

        SELECT 
              0 AS IsSuccessful,
              N'حصل خطأ غير معروف رمز الخطأ : ' + CAST(@IdentityCatchError AS NVARCHAR(200)) AS Message_;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[Notifications_Create]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Notifications_Create]
(
    @Title              NVARCHAR(200),
    @Body               NVARCHAR(MAX),
    @Url                NVARCHAR(500) = NULL,
    @StartDate          NVARCHAR(500) = NULL,
    @EndDate            NVARCHAR(500) = NULL,
    @UserID             BIGINT = NULL,
    @DistributorID      BIGINT = NULL,
    @RoleID             BIGINT = NULL,
    @DsdID              BIGINT = NULL,
    @IdaraID            NVARCHAR(500) = NULL,
    @MenuID             NVARCHAR(500) = NULL,
    @PermissionTypeID   BIGINT = NULL,
    @PermissionTypeIDs  NVARCHAR(MAX) = NULL,
    @entryData          NVARCHAR(20),
    @hostName           NVARCHAR(200)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @NotificationId BIGINT;
    DECLARE @Today DATE = CAST(GETDATE() AS DATE);

    DECLARE @StartDT DATETIME = TRY_CONVERT(DATETIME, NULLIF(@StartDate, ''), 120);
    DECLARE @EndDT   DATETIME = TRY_CONVERT(DATETIME, NULLIF(@EndDate, ''), 120);

    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@IdaraID, ''));
    DECLARE @MenuID_BIGINT BIGINT = TRY_CONVERT(BIGINT, NULLIF(@MenuID, ''));

    DECLARE @TargetUsers TABLE
    (
        UserID BIGINT PRIMARY KEY
    );

    INSERT INTO dbo.Notifications
    (
        Title,
        Body,
        Url_,
        StartDate,
        EndDate,
        IsActive,
        IdaraID_FK,
        entryData,
        hostName
    )
    VALUES
    (
        @Title,
        @Body,
        @Url,
        ISNULL(@StartDT, GETDATE()),
        @EndDT,
        1,
        @IdaraID_INT,
        @entryData,
        @hostName
    );

    SET @NotificationId = SCOPE_IDENTITY();

    IF @NotificationId IS NULL OR @NotificationId = 0
        RETURN;

    /*========================================================
      1) مستخدم محدد
    ========================================================*/
    IF (
           @UserID IS NOT NULL
       AND @DistributorID IS NULL
       AND @RoleID IS NULL
       AND @DsdID IS NULL
       AND @IdaraID IS NULL
       AND @MenuID IS NULL
       AND @PermissionTypeID IS NULL
       AND @PermissionTypeIDs IS NULL
    )
    BEGIN
        INSERT INTO @TargetUsers (UserID)
        SELECT u.usersID
        FROM dbo.Users u
        WHERE u.usersID = @UserID
          AND u.usersActive = 1
          AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
          AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today);
    END

    /*========================================================
      2) موزع فقط
    ========================================================*/
    ELSE IF (
           @UserID IS NULL
       AND @DistributorID IS NOT NULL
       AND @RoleID IS NULL
       AND @DsdID IS NULL
       AND @IdaraID IS NULL
       AND @MenuID IS NULL
       AND @PermissionTypeID IS NULL
       AND @PermissionTypeIDs IS NULL
    )
    BEGIN
        INSERT INTO @TargetUsers (UserID)
    SELECT DISTINCT u.usersID
    FROM dbo.Permission p
    INNER JOIN dbo.DistributorPermissionType dpt
        ON dpt.distributorPermissionTypeID = p.DistributorPermissionTypeID_FK
    INNER JOIN dbo.Users u
        ON u.usersID = p.UsersID_FK
    WHERE p.permissionActive = 1
      AND p.UsersID_FK IS NOT NULL
      AND dpt.DistributorID_FK = @DistributorID
      AND dpt.distributorPermissionTypeActive = 1
      AND u.usersActive = 1
      AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
      AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(p.permissionStartDate, GETDATE()) AS DATE) <= @Today
      AND (p.permissionEndDate IS NULL OR CAST(p.permissionEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(dpt.distributorPermissionTypeStartDate, GETDATE()) AS DATE) <= @Today
      AND (dpt.distributorPermissionTypeEndDate IS NULL OR CAST(dpt.distributorPermissionTypeEndDate AS DATE) >= @Today);
    END

    /*========================================================
      3) Role فقط
    ========================================================*/
    ELSE IF (
           @UserID IS NULL
       AND @DistributorID IS NULL
       AND @RoleID IS NOT NULL
       AND @DsdID IS NULL
       AND @IdaraID IS NULL
       AND @MenuID IS NULL
       AND @PermissionTypeID IS NULL
       AND @PermissionTypeIDs IS NULL
    )
    BEGIN
        INSERT INTO @TargetUsers (UserID)
        SELECT DISTINCT u.usersID
        FROM dbo.Users u
        INNER JOIN dbo.UserDistributor ud
            ON ud.userID_FK = u.usersID
        INNER JOIN dbo.Distributor d
            ON d.distributorID = ud.distributorID_FK
        WHERE d.roleID_FK = @RoleID
          AND u.usersActive = 1
          AND d.distributorActive = 1
          AND ud.UDActive = 1
          AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
          AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today)
          AND CAST(ud.UDStartDate AS DATE) <= @Today
          AND (ud.UDEndDate IS NULL OR CAST(ud.UDEndDate AS DATE) >= @Today);
    END

    /*========================================================
      4) Role + Idara
    ========================================================*/
    ELSE IF (
           @UserID IS NULL
       AND @DistributorID IS NULL
       AND @RoleID IS NOT NULL
       AND @DsdID IS NULL
       AND @IdaraID IS NOT NULL
       AND @MenuID IS NULL
       AND @PermissionTypeID IS NULL
       AND @PermissionTypeIDs IS NULL
    )
    BEGIN
        INSERT INTO @TargetUsers (UserID)
        SELECT DISTINCT u.usersID
        FROM dbo.Users u
        INNER JOIN dbo.UsersDetails udt
            ON udt.usersID_FK = u.usersID
        INNER JOIN dbo.UserDistributor ud
            ON ud.userID_FK = u.usersID
        INNER JOIN dbo.Distributor d
            ON d.distributorID = ud.distributorID_FK
        WHERE d.roleID_FK = @RoleID
          AND udt.IdaraID = @IdaraID_INT
          AND u.usersActive = 1
          AND udt.userActive = 1
          AND d.distributorActive = 1
          AND ud.UDActive = 1
          AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
          AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today)
          AND CAST(ud.UDStartDate AS DATE) <= @Today
          AND (ud.UDEndDate IS NULL OR CAST(ud.UDEndDate AS DATE) >= @Today);
    END

    /*========================================================
      5) DSD فقط
    ========================================================*/
    ELSE IF (
           @UserID IS NULL
       AND @DistributorID IS NULL
       AND @RoleID IS NULL
       AND @DsdID IS NOT NULL
       AND @IdaraID IS NULL
       AND @MenuID IS NULL
       AND @PermissionTypeID IS NULL
       AND @PermissionTypeIDs IS NULL
    )
    BEGIN
        INSERT INTO @TargetUsers (UserID)
        SELECT DISTINCT u.usersID
        FROM dbo.Users u
        INNER JOIN dbo.V_GetListUsersInDSD v
            ON v.usersID = u.usersID
        WHERE v.DSDID = @DsdID
          AND u.usersActive = 1
          AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
          AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today);
    END

    /*========================================================
      6) DSD + Idara
    ========================================================*/
    ELSE IF (
           @UserID IS NULL
       AND @DistributorID IS NULL
       AND @RoleID IS NULL
       AND @DsdID IS NOT NULL
       AND @IdaraID IS NOT NULL
       AND @MenuID IS NULL
       AND @PermissionTypeID IS NULL
       AND @PermissionTypeIDs IS NULL
    )
    BEGIN
        INSERT INTO @TargetUsers (UserID)
        SELECT DISTINCT u.usersID
        FROM dbo.Users u
        INNER JOIN dbo.UsersDetails udt
            ON udt.usersID_FK = u.usersID
        INNER JOIN dbo.V_GetListUsersInDSD v
            ON v.usersID = u.usersID
        INNER JOIN dbo.V_GetFullStructureForDSD fs
            ON fs.DSDID = v.DSDID
        WHERE v.DSDID = @DsdID
          AND fs.IdaraID = @IdaraID_INT
          AND udt.IdaraID = @IdaraID_INT
          AND u.usersActive = 1
          AND udt.userActive = 1
          AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
          AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today);
    END

    /*========================================================
      7) Idara فقط
    ========================================================*/
    ELSE IF (
           @UserID IS NULL
       AND @DistributorID IS NULL
       AND @RoleID IS NULL
       AND @DsdID IS NULL
       AND @IdaraID IS NOT NULL
       AND @MenuID IS NULL
       AND @PermissionTypeID IS NULL
       AND @PermissionTypeIDs IS NULL
    )
    BEGIN
        INSERT INTO @TargetUsers (UserID)
        SELECT DISTINCT u.usersID
        FROM dbo.Users u
        INNER JOIN dbo.UsersDetails udt
            ON udt.usersID_FK = u.usersID
        WHERE udt.IdaraID = @IdaraID_INT
          AND u.usersActive = 1
          AND udt.userActive = 1
          AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
          AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today);
    END

/*========================================================
  8) Menu + Idara
  من يملك صلاحية مباشرة لمستخدم
  مرتبطة بموزع ومرتبطة بالصفحة المحددة
  داخل إدارة معيّنة فقط
========================================================*/
ELSE IF (
       @UserID IS NULL
   AND @DistributorID IS NULL
   AND @RoleID IS NULL
   AND @DsdID IS NULL
   AND @IdaraID IS NOT NULL
   AND @MenuID IS NOT NULL
   AND @PermissionTypeID IS NULL
   AND @PermissionTypeIDs IS NULL
)
BEGIN
    INSERT INTO @TargetUsers (UserID)
    SELECT DISTINCT u.usersID
    FROM dbo.V_GetFullPermissionDetails s
    INNER JOIN dbo.Users u
        ON u.usersID = s.UsersID_FK
    INNER JOIN dbo.UsersDetails udt
        ON udt.usersID_FK = u.usersID
    WHERE s.UsersID_FK IS NOT NULL
      AND s.distributorID IS NOT NULL
      AND s.menuID = @MenuID_BIGINT
      AND udt.IdaraID = @IdaraID_INT
      AND s.permissionActive = 1
      AND s.distributorPermissionTypeActive = 1
      AND s.distributorActive = 1
      AND s.permissionTypeActive = 1
      AND s.userActive = 1
      AND u.usersActive = 1
      AND udt.userActive = 1
      AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
      AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(s.permissionStartDate, GETDATE()) AS DATE) <= @Today
      AND (s.permissionEndDate IS NULL OR CAST(s.permissionEndDate AS DATE) >= @Today);
END

  /*========================================================
  9) PermissionType + Idara
  صلاحية معيّنة مباشرة على مستخدم داخل إدارة معيّنة فقط
========================================================*/
ELSE IF (
       @UserID IS NULL
   AND @DistributorID IS NULL
   AND @RoleID IS NULL
   AND @DsdID IS NULL
   AND @IdaraID IS NOT NULL
   AND @MenuID IS NULL
   AND @PermissionTypeID IS NOT NULL
   AND @PermissionTypeIDs IS NULL
)
BEGIN
    INSERT INTO @TargetUsers (UserID)
    SELECT DISTINCT u.usersID
    FROM dbo.Permission p
    INNER JOIN dbo.DistributorPermissionType dpt
        ON dpt.distributorPermissionTypeID = p.DistributorPermissionTypeID_FK
    INNER JOIN dbo.Users u
        ON u.usersID = p.UsersID_FK
    INNER JOIN dbo.UsersDetails udt
        ON udt.usersID_FK = u.usersID
    WHERE p.permissionActive = 1
      AND p.UsersID_FK IS NOT NULL
      AND dpt.permissionTypeID_FK = @PermissionTypeID
      AND dpt.distributorPermissionTypeActive = 1
      AND udt.IdaraID = @IdaraID_INT
      AND u.usersActive = 1
      AND udt.userActive = 1
      AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
      AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(p.permissionStartDate, GETDATE()) AS DATE) <= @Today
      AND (p.permissionEndDate IS NULL OR CAST(p.permissionEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(dpt.distributorPermissionTypeStartDate, GETDATE()) AS DATE) <= @Today
      AND (dpt.distributorPermissionTypeEndDate IS NULL OR CAST(dpt.distributorPermissionTypeEndDate AS DATE) >= @Today);
END

   /*========================================================
  10) Distributor + Idara
  من يملك صلاحيات مرتبطة بموزع معيّن داخل إدارة معيّنة فقط
========================================================*/
ELSE IF (
       @UserID IS NULL
   AND @DistributorID IS NOT NULL
   AND @RoleID IS NULL
   AND @DsdID IS NULL
   AND @IdaraID IS NOT NULL
   AND @MenuID IS NULL
   AND @PermissionTypeID IS NULL
   AND @PermissionTypeIDs IS NULL
)
BEGIN
    INSERT INTO @TargetUsers (UserID)
    SELECT DISTINCT u.usersID
    FROM dbo.Permission p
    INNER JOIN dbo.DistributorPermissionType dpt
        ON dpt.distributorPermissionTypeID = p.DistributorPermissionTypeID_FK
    INNER JOIN dbo.Users u
        ON u.usersID = p.UsersID_FK
    INNER JOIN dbo.UsersDetails udt
        ON udt.usersID_FK = u.usersID
    WHERE p.permissionActive = 1
      AND p.UsersID_FK IS NOT NULL
      AND dpt.DistributorID_FK = @DistributorID
      AND dpt.distributorPermissionTypeActive = 1
      AND udt.IdaraID = @IdaraID_INT
      AND u.usersActive = 1
      AND udt.userActive = 1
      AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
      AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(p.permissionStartDate, GETDATE()) AS DATE) <= @Today
      AND (p.permissionEndDate IS NULL OR CAST(p.permissionEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(dpt.distributorPermissionTypeStartDate, GETDATE()) AS DATE) <= @Today
      AND (dpt.distributorPermissionTypeEndDate IS NULL OR CAST(dpt.distributorPermissionTypeEndDate AS DATE) >= @Today);
END
    /*========================================================
      11) الجميع
    ========================================================*/
    ELSE IF (
           @UserID IS NULL
       AND @DistributorID IS NULL
       AND @RoleID IS NULL
       AND @DsdID IS NULL
       AND @IdaraID IS NULL
       AND @MenuID IS NULL
       AND @PermissionTypeID IS NULL
       AND @PermissionTypeIDs IS NULL
    )
    BEGIN
        INSERT INTO @TargetUsers (UserID)
        SELECT u.usersID
        FROM dbo.Users u
        WHERE u.usersActive = 1
          AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
          AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today);
    END

    /*========================================================
  PermissionTypes (OR) + Idara
  من يملك أي صلاحية من الصلاحيات المحددة
  مباشرة على المستخدم داخل إدارة معيّنة فقط
========================================================*/
ELSE IF (
       @UserID IS NULL
   AND @DistributorID IS NULL
   AND @RoleID IS NULL
   AND @DsdID IS NULL
   AND @IdaraID IS NOT NULL
   AND @MenuID IS NULL
   AND @PermissionTypeID IS NULL
   AND @PermissionTypeIDs IS NOT NULL
)
BEGIN
    DECLARE @Perms TABLE
    (
        PermissionTypeID BIGINT PRIMARY KEY
    );

    INSERT INTO @Perms (PermissionTypeID)
    SELECT DISTINCT TRY_CONVERT(BIGINT, LTRIM(RTRIM(value)))
    FROM STRING_SPLIT(@PermissionTypeIDs, ',')
    WHERE TRY_CONVERT(BIGINT, LTRIM(RTRIM(value))) IS NOT NULL;

    INSERT INTO @TargetUsers (UserID)
    SELECT DISTINCT u.usersID
    FROM dbo.Users u
    INNER JOIN dbo.UsersDetails udt
        ON udt.usersID_FK = u.usersID
    INNER JOIN dbo.Permission p
        ON p.UsersID_FK = u.usersID
    INNER JOIN dbo.DistributorPermissionType dpt
        ON dpt.distributorPermissionTypeID = p.DistributorPermissionTypeID_FK
    WHERE udt.IdaraID = @IdaraID_INT
      AND u.usersActive = 1
      AND udt.userActive = 1
      AND p.permissionActive = 1
      AND p.UsersID_FK IS NOT NULL
      AND dpt.distributorPermissionTypeActive = 1
      AND dpt.permissionTypeID_FK IN (SELECT PermissionTypeID FROM @Perms)
      AND CAST(ISNULL(u.usersStartDate, GETDATE()) AS DATE) <= @Today
      AND (u.usersEndDate IS NULL OR CAST(u.usersEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(p.permissionStartDate, GETDATE()) AS DATE) <= @Today
      AND (p.permissionEndDate IS NULL OR CAST(p.permissionEndDate AS DATE) >= @Today)
      AND CAST(ISNULL(dpt.distributorPermissionTypeStartDate, GETDATE()) AS DATE) <= @Today
      AND (dpt.distributorPermissionTypeEndDate IS NULL OR CAST(dpt.distributorPermissionTypeEndDate AS DATE) >= @Today);
END

    ELSE
    BEGIN
        RETURN;
    END;

    INSERT INTO dbo.UserNotifications
    (
        NotificationId_FK,
        UserId_FK,
        IsRead,
        IsClicked,
        DeliveredUtc,
        entryData,
        hostName
    )
    SELECT
        @NotificationId,
        tu.UserID,
        0,
        0,
        GETDATE(),
        @entryData,
        @hostName
    FROM @TargetUsers tu
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM dbo.UserNotifications un
        WHERE un.NotificationId_FK = @NotificationId
          AND un.UserId_FK = tu.UserID
    );

END
GO
/****** Object:  StoredProcedure [dbo].[Notifications_CRUD]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Notifications_CRUD]
    @UserID NVARCHAR(50),
    @Type NVARCHAR(20) = NULL,
    @UserNotificationId BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Get notification details
    IF @Type = 'Body'
    BEGIN
        SELECT 
            un.UserNotificationId,
            un.NotificationId_FK,
            n.Title,
            n.Body,
            n.Url_,
            un.DeliveredUtc,
            un.IsClicked,
            un.IsRead,
            un.ReadUtc,
            un.ClickUtc
        FROM 
             dbo.UserNotifications un
            INNER JOIN  dbo.Notifications n 
                ON un.NotificationId_FK = n.NotificationId
        WHERE 
            un.UserId_FK = @UserID 
            AND un.IsClicked = 0 
            AND un.ClickUtc IS NULL
        ORDER BY 
            un.DeliveredUtc DESC;
    END
    
    -- Get notification count (unread only)
    ELSE IF @Type = 'Count'
    BEGIN
        SELECT COUNT(*) AS NotificationCount
        FROM  dbo.UserNotifications
        WHERE UserId_FK = @UserID 
          AND IsRead = 0
          AND ReadUtc IS NULL;
    END
    
    -- Mark single notification as clicked
    ELSE IF @Type = 'MarkClicked'
    BEGIN
        UPDATE  dbo.UserNotifications
        SET 
            IsClicked = 1,
            ClickUtc = GETUTCDATE(),
            IsRead = 1,
            ReadUtc = ISNULL(ReadUtc, GETUTCDATE())
        WHERE 
            UserNotificationId = @UserNotificationId
            AND UserId_FK = @UserID;
            
        SELECT @@ROWCOUNT AS RowsAffected;
    END
    
    -- ✅ NEW: Mark single notification as read (on hover)
    ELSE IF @Type = 'MarkRead'
    BEGIN
        UPDATE  dbo.UserNotifications
        SET 
            IsRead = 1,
            ReadUtc = GETUTCDATE()
        WHERE 
            UserNotificationId = @UserNotificationId
            AND UserId_FK = @UserID
            AND IsRead = 0;  -- Only if not already read
            
        SELECT @@ROWCOUNT AS RowsAffected;
    END
    
    -- Mark all notifications as read
    ELSE IF @Type = 'MarkAllRead'
    BEGIN
        UPDATE  dbo.UserNotifications
        SET 
            IsRead = 1,
            ReadUtc = GETUTCDATE()
        WHERE 
            UserId_FK = @UserID
            AND IsRead = 0
            AND ReadUtc IS NULL;
            
        SELECT @@ROWCOUNT AS RowsAffected;
    END
    
    -- Mark all notifications as clicked
    ELSE IF @Type = 'MarkAllClicked'
    BEGIN
        UPDATE  dbo.UserNotifications
        SET 
            IsClicked = 1,
            ClickUtc = GETUTCDATE(),
            IsRead = 1,
            ReadUtc = ISNULL(ReadUtc, GETUTCDATE())
        WHERE 
            UserId_FK = @UserID
            AND IsClicked = 0
            AND ClickUtc IS NULL;
            
        SELECT @@ROWCOUNT AS RowsAffected;
    END
END
GO
/****** Object:  StoredProcedure [dbo].[PagesManagmentSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PagesManagmentSP] 
(
      @Action                                NVARCHAR(200)
    , @programID                               NVARCHAR(200)   = NULL
    , @programName_A                            NVARCHAR(200)   = NULL
    , @programName_E                             NVARCHAR(200)   = NULL
    , @programDescription                           NVARCHAR(200)   = NULL
    , @programActive                          NVARCHAR(200)   = NULL
    , @programLink                           NVARCHAR(200)   = NULL
    , @programIcon                           NVARCHAR(200)   = NULL
    , @programSerial                            NVARCHAR(200)   = NULL


    , @firstName_E                           NVARCHAR(200)   = NULL
    , @secondName_E                          NVARCHAR(200)   = NULL
    , @thirdName_E                           NVARCHAR(200)   = NULL
    , @forthName_E                           NVARCHAR(200)   = NULL
    , @lastName_E                            NVARCHAR(200)   = NULL
    , @UsersAuthTypeID                       NVARCHAR(200)   = NULL
    , @ActiveStatus                          NVARCHAR(200)   = NULL
    , @userTypeID_FK                         NVARCHAR(200)   = NULL
    , @IdaraID                               NVARCHAR(200)   = NULL
    , @nationalIDIssueDate                   NVARCHAR(200)   = NULL
    , @dateOfBirth                           NVARCHAR(200)   = NULL
    , @genderID_FK                           NVARCHAR(200)   = NULL
    , @nationalityID_FK                      NVARCHAR(200)   = NULL
    , @religionID_FK                         NVARCHAR(200)   = NULL
    , @maritalStatusID_FK                    NVARCHAR(200)   = NULL
    , @educationID_FK                        NVARCHAR(100)   = NULL
    , @userNote                              NVARCHAR(1000)  = NULL
    , @distributorID                         NVARCHAR(1000)  = NULL


    , @idaraID_FK                            NVARCHAR(10)    = NULL
    , @entryData                             NVARCHAR(20)    = NULL
    , @hostName                              NVARCHAR(200)   = NULL
)


AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));
    DECLARE @isAdmin INT = (select top(1) isnull(d.UsersAuthTypeID,3) from dbo.V_GetFullSystemUsersDetails d where d.usersID = @entryData and d.userActive = 1)
   


    DECLARE @nationalIDIssueDate_DT date,
        @dateOfBirth_DT date;

-- حاول التحويل (أفضل شيء توقع ISO: 2026-02-13)
SET @nationalIDIssueDate_DT = TRY_CONVERT(date, @nationalIDIssueDate, 23);
SET @dateOfBirth_DT         = TRY_CONVERT(date, @dateOfBirth, 23);




    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END


         IF (@isAdmin <> 1)
        BEGIN
            ;THROW 50001, N'تم رصد دخول غير مصرح به انت لاتملك صلاحية للوصول الى هذه الصفحة', 1;
        END
        ----------------------------------------------------------------
        -- AddPorgram
        ----------------------------------------------------------------

        IF @Action = N'AddProgram'

            BEGIN
                IF NULLIF(LTRIM(RTRIM(@programName_A)), N'') IS NULL
                   OR NULLIF(LTRIM(RTRIM(@programName_E)), N'') IS NULL
                   OR NULLIF(LTRIM(RTRIM(@programDescription)), N'') IS NULL
                   OR NULLIF(LTRIM(RTRIM(@programLink)), N'') IS NULL
                   OR NULLIF(LTRIM(RTRIM(@programIcon)), N'') IS NULL
                BEGIN
                    ;THROW 50001, N'الرجاء اكمال جميع الحقول المطلوبة', 1;
                END
            
                DECLARE @programActiveBit INT = TRY_CONVERT(INT, @programActive);
                IF @programActiveBit IS NULL
                BEGIN
                    ;THROW 50001, N'حالة البرنامج غير صحيحة', 1;
                END
            
            
                DECLARE @programSerialInt INT = TRY_CONVERT(INT, @programSerial);
                IF @programSerialInt IS NULL OR @programSerialInt <= 0
                BEGIN
                    ;THROW 50001, N'الترقيم غير صحيح', 1;
                END
            
                        IF EXISTS (
                    SELECT 1
                    FROM dbo.Program p
                    WHERE p.programName_A = LTRIM(RTRIM(@programName_A))
                      AND p.programActive = 1
                )
                 BEGIN
                    ;THROW 50001, N'الاسم العربي مستخدم مسبقاً', 1;
                 END
            
                IF EXISTS (
                    SELECT 1
                    FROM dbo.Program p
                    WHERE p.programName_E = LTRIM(RTRIM(@programName_E))
                      AND p.programActive = 1
                )
                 BEGIN
                    ;THROW 50001, N'الاسم الإنجليزي مستخدم مسبقاً', 1;
                 END
            
            Declare @ProgOrder int
            set @ProgOrder = (select Top(1) programSerial + 1 from dbo.Program p order by p.programSerial desc )


            INSERT INTO  dbo.Program
            (
                [programName_A]
               ,[programName_E]
               ,[programDescription]
               ,[programActive]
               ,[programLink]
               ,[programIcon]
               ,[programSerial]
               ,[entryDate]
               ,[entryData]
               ,[hostName]
            )
            VALUES
            (
               @programName_A
              ,@programName_E      
              ,@programDescription 
              ,@programActive      
              ,@programLink        
              ,@programIcon        
              ,@ProgOrder      
              , GETDATE()
              ,@entryData
              ,@hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البرنامج', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();

            
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البرنامج - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"usersID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"programName_A": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @programName_A), '') + N'"'
                + N',"programName_E": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @programName_E), '') + N'"'
                + N',"programDescription": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @programDescription), '') + N'"'
                + N',"programActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @programActive), '') + N'"'
                + N',"programLink": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @programLink), '') + N'"'
                + N',"programIcon": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @programIcon), '') + N'"'
                + N',"programSerial": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @programSerial), '') + N'"'
                + N',"entryDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), GETDATE(),23), '') + N'"'
                + N',"entryData": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                 + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[dbo].[Program]'
                , N'AddProgram'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );


            SELECT 1 AS IsSuccessful, N'تم اضافة البرنامج بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- EditProgram
        ----------------------------------------------------------------
            ELSE IF @Action = N'EditProgram'
                BEGIN
                    DECLARE @programID_Int INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@programID)), N''));
                    IF @programID_Int IS NULL OR @programID_Int <= 0
                    BEGIN
                        ;THROW 50001, N'رقم البرنامج غير صحيح', 1;
                        END
                
                    -- تأكد موجود
                    IF NOT EXISTS (SELECT 1 FROM dbo.Program WHERE programID = @programID_Int)
                    BEGIN
                        ;THROW 50001, N'البرنامج غير موجود', 1;
                        END
                
                    -- لو أرسل Active تحقق أنه رقم (اختياري: 0/1 فقط)
                    IF NULLIF(LTRIM(RTRIM(@programActive)), N'') IS NOT NULL
                    BEGIN
                        DECLARE @programActive_Int INT = TRY_CONVERT(INT, @programActive);
                        IF @programActive_Int IS NULL OR @programActive_Int NOT IN (0,1)
                        BEGIN
                            ;THROW 50001, N'حالة البرنامج غير صحيحة (0 أو 1)', 1;
                        END
                    END
                
                    -- لو أرسل Serial تحقق أنه رقم > 0
                    IF NULLIF(LTRIM(RTRIM(@programSerial)), N'') IS NOT NULL
                    BEGIN
                        DECLARE @programSerial_Int INT = TRY_CONVERT(INT, @programSerial);
                        IF @programSerial_Int IS NULL OR @programSerial_Int <= 0
                        BEGIN
                            ;THROW 50001, N'الترقيم غير صحيح', 1;
                            END
                    END
                
                    -- (اختياري) فحص تكرار الاسم العربي/الانجليزي إذا تم تغييره
                    IF NULLIF(LTRIM(RTRIM(@programName_A)), N'') IS NOT NULL
                    BEGIN
                        IF EXISTS (
                            SELECT 1
                            FROM dbo.Program p
                            WHERE p.programID <> @programID_Int
                              AND p.programActive = 1
                              AND p.programName_A = LTRIM(RTRIM(@programName_A))
                        )
                        BEGIN
                            ;THROW 50001, N'الاسم العربي مستخدم مسبقاً', 1;
                            END
                    END
                
                    IF NULLIF(LTRIM(RTRIM(@programName_E)), N'') IS NOT NULL
                    BEGIN
                        IF EXISTS (
                            SELECT 1
                            FROM dbo.Program p
                            WHERE p.programID <> @programID_Int
                              AND p.programActive = 1
                              AND p.programName_E = LTRIM(RTRIM(@programName_E))
                        )
                        BEGIN
                            ;THROW 50001, N'الاسم الإنجليزي مستخدم مسبقاً', 1;
                            END
                    END
                
                    -- احفظ القديم للـ Audit
                    DECLARE
                        @Old_programName_A NVARCHAR(200),
                        @Old_programName_E NVARCHAR(200),
                        @Old_programDescription NVARCHAR(200),
                        @Old_programActive NVARCHAR(200),
                        @Old_programLink NVARCHAR(200),
                        @Old_programIcon NVARCHAR(200),
                        @Old_programSerial NVARCHAR(200);
                
                    SELECT
                        @Old_programName_A = programName_A,
                        @Old_programName_E = programName_E,
                        @Old_programDescription = programDescription,
                        @Old_programActive = CONVERT(NVARCHAR(200), programActive),
                        @Old_programLink = programLink,
                        @Old_programIcon = programIcon,
                        @Old_programSerial = CONVERT(NVARCHAR(200), programSerial)
                    FROM dbo.Program
                    WHERE programID = @programID_Int;
                
                    UPDATE dbo.Program
                    SET
                        programName_A      = COALESCE(NULLIF(LTRIM(RTRIM(@programName_A)), N''), programName_A),
                        programName_E      = COALESCE(NULLIF(LTRIM(RTRIM(@programName_E)), N''), programName_E),
                        programDescription = COALESCE(NULLIF(LTRIM(RTRIM(@programDescription)), N''), programDescription),
                        programActive      = COALESCE(TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@programActive)), N'')), programActive),
                        programLink        = COALESCE(NULLIF(LTRIM(RTRIM(@programLink)), N''), programLink),
                        programIcon        = COALESCE(NULLIF(LTRIM(RTRIM(@programIcon)), N''), programIcon),
                        programSerial      = COALESCE(TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@programSerial)), N'')), programSerial),
                        entryDate          = GETDATE(),
                        entryData          = @entryData,
                        hostName           = @hostName
                    WHERE programID = @programID_Int;
                
                    IF @@ROWCOUNT = 0
                    BEGIN
                        ;THROW 50002, N'لم يتم تعديل البرنامج', 1;
                        END
                
                    -- Audit Notes (قبل/بعد)
                    SET @Note = N'{'
                        + N'"programID": "' + CONVERT(NVARCHAR(MAX), @programID_Int) + N'"'
                        + N',"OLD": {'
                            + N'"programName_A": "' + ISNULL(@Old_programName_A, N'') + N'"'
                            + N',"programName_E": "' + ISNULL(@Old_programName_E, N'') + N'"'
                            + N',"programDescription": "' + ISNULL(@Old_programDescription, N'') + N'"'
                            + N',"programActive": "' + ISNULL(@Old_programActive, N'') + N'"'
                            + N',"programLink": "' + ISNULL(@Old_programLink, N'') + N'"'
                            + N',"programIcon": "' + ISNULL(@Old_programIcon, N'') + N'"'
                            + N',"programSerial": "' + ISNULL(@Old_programSerial, N'') + N'"'
                        + N'}'
                        + N',"NEW": {'
                            + N'"programName_A": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programName_A)), N''), @Old_programName_A) + N'"'
                            + N',"programName_E": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programName_E)), N''), @Old_programName_E) + N'"'
                            + N',"programDescription": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programDescription)), N''), @Old_programDescription) + N'"'
                            + N',"programActive": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programActive)), N''), @Old_programActive) + N'"'
                            + N',"programLink": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programLink)), N''), @Old_programLink) + N'"'
                            + N',"programIcon": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programIcon)), N''), @Old_programIcon) + N'"'
                            + N',"programSerial": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programSerial)), N''), @Old_programSerial) + N'"'
                        + N'}'
                        + N',"entryDate": "' + CONVERT(NVARCHAR(MAX), GETDATE(), 23) + N'"'
                        + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), N'') + N'"'
                        + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), N'') + N'"'
                        + N'}';
                
                    INSERT INTO  dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
                    VALUES (N'[dbo].[Program]', N'EditProgram', @programID_Int, @entryData, @Note);
                
                    SELECT 1 AS IsSuccessful, N'تم تعديل البرنامج بنجاح' AS Message_;
                    RETURN;
                END


                 ----------------------------------------------------------------
        -- DeleteProgram
        ----------------------------------------------------------------
            ELSE IF @Action = N'DeleteProgram'
                BEGIN
                    DECLARE @programID_Int1 INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@programID)), N''));
                    IF @programID_Int1 IS NULL OR @programID_Int1 <= 0
                    BEGIN
                        ;THROW 50001, N'رقم البرنامج غير صحيح', 1;
                        END
                
                    -- تأكد موجود
                    IF NOT EXISTS (SELECT 1 FROM dbo.Program WHERE programID = @programID_Int1)
                    BEGIN
                        ;THROW 50001, N'البرنامج غير موجود', 1;
                        END
                
                    -- لو أرسل Active تحقق أنه رقم (اختياري: 0/1 فقط)
                    IF NULLIF(LTRIM(RTRIM(@programActive)), N'') IS NOT NULL
                    BEGIN
                        DECLARE @programActive_Int1 INT = TRY_CONVERT(INT, @programActive);
                        IF @programActive_Int1 IS NULL OR @programActive_Int1 NOT IN (0,1)
                        BEGIN
                            ;THROW 50001, N'حالة البرنامج غير صحيحة (0 أو 1)', 1;
                        END
                    END
                
                    -- لو أرسل Serial تحقق أنه رقم > 0
                    IF NULLIF(LTRIM(RTRIM(@programSerial)), N'') IS NOT NULL
                    BEGIN
                        DECLARE @programSerial_Int1 INT = TRY_CONVERT(INT, @programSerial);
                        IF @programSerial_Int1 IS NULL OR @programSerial_Int1 <= 0
                        BEGIN
                            ;THROW 50001, N'الترقيم غير صحيح', 1;
                            END
                    END
                
                    -- (اختياري) فحص تكرار الاسم العربي/الانجليزي إذا تم تغييره
                    IF NULLIF(LTRIM(RTRIM(@programName_A)), N'') IS NOT NULL
                    BEGIN
                        IF EXISTS (
                            SELECT 1
                            FROM dbo.Program p
                            WHERE p.programID <> @programID_Int
                              AND p.programActive = 1
                              AND p.programName_A = LTRIM(RTRIM(@programName_A))
                        )
                        BEGIN
                            ;THROW 50001, N'الاسم العربي مستخدم مسبقاً', 1;
                            END
                    END
                
                    IF NULLIF(LTRIM(RTRIM(@programName_E)), N'') IS NOT NULL
                    BEGIN
                        IF EXISTS (
                            SELECT 1
                            FROM dbo.Program p
                            WHERE p.programID <> @programID_Int
                              AND p.programActive = 1
                              AND p.programName_E = LTRIM(RTRIM(@programName_E))
                        )
                        BEGIN
                            ;THROW 50001, N'الاسم الإنجليزي مستخدم مسبقاً', 1;
                            END
                    END
                
                    -- احفظ القديم للـ Audit
                    DECLARE
                        @Old_programName_A1 NVARCHAR(200),
                        @Old_programName_E1 NVARCHAR(200),
                        @Old_programDescription1 NVARCHAR(200),
                        @Old_programActive1 NVARCHAR(200),
                        @Old_programLink1 NVARCHAR(200),
                        @Old_programIcon1 NVARCHAR(200),
                        @Old_programSerial1 NVARCHAR(200);
                
                    SELECT
                        @Old_programName_A1 = programName_A,
                        @Old_programName_E1 = programName_E,
                        @Old_programDescription1 = programDescription,
                        @Old_programActive1 = CONVERT(NVARCHAR(200), programActive),
                        @Old_programLink1 = programLink,
                        @Old_programIcon1 = programIcon,
                        @Old_programSerial1 = CONVERT(NVARCHAR(200), programSerial)
                    FROM dbo.Program
                    WHERE programID = @programID_Int1;
                
                    UPDATE dbo.Program
                    SET
                        programName_A      = COALESCE(NULLIF(LTRIM(RTRIM(@programName_A)), N''), programName_A),
                        programName_E      = COALESCE(NULLIF(LTRIM(RTRIM(@programName_E)), N''), programName_E),
                        programDescription = COALESCE(NULLIF(LTRIM(RTRIM(@programDescription)), N''), programDescription),
                        programActive      = COALESCE(TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@programActive)), N'')), programActive),
                        programLink        = COALESCE(NULLIF(LTRIM(RTRIM(@programLink)), N''), programLink),
                        programIcon        = COALESCE(NULLIF(LTRIM(RTRIM(@programIcon)), N''), programIcon),
                        programSerial      = COALESCE(TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@programSerial)), N'')), programSerial),
                        entryDate          = GETDATE(),
                        entryData          = @entryData,
                        hostName           = @hostName
                    WHERE programID = @programID_Int1;
                
                    IF @@ROWCOUNT = 0
                    BEGIN
                        ;THROW 50002, N'لم يتم تعديل حالة البرنامج', 1;
                        END
                
                    -- Audit Notes (قبل/بعد)
                    SET @Note = N'{'
                        + N'"programID": "' + CONVERT(NVARCHAR(MAX), @programID_Int1) + N'"'
                        + N',"OLD": {'
                            + N'"programName_A": "' + ISNULL(@Old_programName_A, N'') + N'"'
                            + N',"programName_E": "' + ISNULL(@Old_programName_E, N'') + N'"'
                            + N',"programDescription": "' + ISNULL(@Old_programDescription, N'') + N'"'
                            + N',"programActive": "' + ISNULL(@Old_programActive, N'') + N'"'
                            + N',"programLink": "' + ISNULL(@Old_programLink, N'') + N'"'
                            + N',"programIcon": "' + ISNULL(@Old_programIcon, N'') + N'"'
                            + N',"programSerial": "' + ISNULL(@Old_programSerial, N'') + N'"'
                        + N'}'
                        + N',"NEW": {'
                            + N'"programName_A": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programName_A)), N''), @Old_programName_A1) + N'"'
                            + N',"programName_E": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programName_E)), N''), @Old_programName_E1) + N'"'
                            + N',"programDescription": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programDescription)), N''), @Old_programDescription1) + N'"'
                            + N',"programActive": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programActive)), N''), @Old_programActive1) + N'"'
                            + N',"programLink": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programLink)), N''), @Old_programLink1) + N'"'
                            + N',"programIcon": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programIcon)), N''), @Old_programIcon1) + N'"'
                            + N',"programSerial": "' + ISNULL(NULLIF(LTRIM(RTRIM(@programSerial)), N''), @Old_programSerial1) + N'"'
                        + N'}'
                        + N',"entryDate": "' + CONVERT(NVARCHAR(MAX), GETDATE(), 23) + N'"'
                        + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), N'') + N'"'
                        + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), N'') + N'"'
                        + N'}';
                
                    INSERT INTO  dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
                    VALUES (N'[dbo].[Program]', N'DeleteProgram', @programID_Int1, @entryData, @Note);
                
                    SELECT 1 AS IsSuccessful, N'تم تعديل حالة البرنامج بنجاح' AS Message_;
                    RETURN;
                END



        ----------------------------------------------------------------
        -- AddPorgram
        ----------------------------------------------------------------

        IF @Action = N'AddMenuList'

            BEGIN
                IF NULLIF(LTRIM(RTRIM(@programName_A)), N'') IS NULL
                   OR NULLIF(LTRIM(RTRIM(@programName_E)), N'') IS NULL
                   OR NULLIF(LTRIM(RTRIM(@programDescription)), N'') IS NULL

                BEGIN
                    ;THROW 50001, N'الرجاء اكمال جميع الحقول المطلوبة', 1;
                END
            
               
            
            
                DECLARE @programSerialInt12 INT = TRY_CONVERT(INT, @programSerial);
                IF @programSerialInt12 IS NULL OR @programSerialInt12 <= 0
                BEGIN
                    ;THROW 50001, N'الترقيم غير 4صحيح', 1;
                END
            
                        IF EXISTS (
                    SELECT 1
                    FROM dbo.menu p
                    WHERE p.menuName_A = LTRIM(RTRIM(@programName_A))
                      AND p.menuActive = 1 
                )
                 BEGIN
                    ;THROW 50001, N'الاسم العربي مستخدم مسبقاً', 1;
                 END
            
                IF EXISTS (
                    SELECT 1
                    FROM dbo.menu p
                    WHERE p.menuName_E = LTRIM(RTRIM(@programName_E))
                      AND p.menuActive = 1 
                )
                 BEGIN
                    ;THROW 50001, N'الاسم الإنجليزي مستخدم مسبقاً', 1;
                 END
            



            INSERT INTO  dbo.Menu
            (
                [menuName_A]
               ,[menuName_E]
               ,[menuDescription]
               ,[programID_FK]
               ,[menuSerial]
               ,[menuActive]
               ,[PageLvl]

            )
            VALUES
            (
               @programName_A
              ,@programName_E      
              ,@programDescription 
              ,@programID            
              ,@programSerial   
              ,1
              ,3
            
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة القائمة الجانبية', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();

            
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة القائمة الجانبية - Identity', 1; -- برمجي
            END
           SET @Note = N'{'
                          + N'"menuID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), N'') + N'"'
                          + N',"menuName_A": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @programName_A), N'') + N'"'
                          + N',"menuName_E": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @programName_E), N'') + N'"'
                          + N',"menuDescription": "'  + ISNULL(CONVERT(NVARCHAR(MAX), @programDescription), N'') + N'"'
                          + N',"programID_FK": "'     + ISNULL(CONVERT(NVARCHAR(MAX), @programID), N'') + N'"'
                          + N',"menuSerial": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @programSerial), N'') + N'"'
                          + N',"menuActive": "'       + N'1' + N'"'
                          + N',"PageLvl": "'          + N'3' + N'"'
                          + N',"entryDate": "'        + ISNULL(CONVERT(NVARCHAR(MAX), GETDATE(), 23), N'') + N'"'
                          + N',"entryData": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), N'') + N'"'
                          + N',"hostName": "'         + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), N'') + N'"'
                          + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[dbo].[menu]'
                , N'AddProgram'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );


            SELECT 1 AS IsSuccessful, N'تم اضافة القائمة الجانبية بنجاح' AS Message_;
            RETURN;
        END


        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[PermissionSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PermissionSP]
(
      @Action                             NVARCHAR(200)
    , @PermissionID                       BIGINT          = NULL
    , @DistributorPermissionTypeID_FK     BIGINT          = NULL
    , @UsersID                            NVARCHAR(100)   = NULL
    , @RoleID                             NVARCHAR(100)   = NULL
    , @distributorID                      NVARCHAR(100)   = NULL
    , @IdaraID                            NVARCHAR(100)   = NULL
    , @DeptID                             NVARCHAR(100)   = NULL
    , @SectionID                          NVARCHAR(100)   = NULL
    , @DivisonID                          NVARCHAR(100)   = NULL
    , @searchID                           BIGINT          = NULL
    , @permissionStartDate                NVARCHAR(1000)  = NULL
    , @permissionEndDate                  NVARCHAR(1000)  = NULL
    , @permissionNote                     NVARCHAR(2000)  = NULL
    , @permissionActive                   BIT             = NULL
    , @InIdaraID                          NVARCHAR(100)   = NULL
    , @entryData                          NVARCHAR(20)    = NULL
    , @hostName                           NVARCHAR(200)   = NULL
    , @distributorIDFroGiveAllPermissions BIGINT          = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL
        , @Rows  INT = 0
        , @DSDID BIGINT = NULL;

    -- تواريخ (تحويل آمن)
    DECLARE @StartDT DATE = TRY_CONVERT(DATE, NULLIF(LTRIM(RTRIM(@permissionStartDate)), ''), 120);
    DECLARE @EndDT   DATE = TRY_CONVERT(DATE, NULLIF(LTRIM(RTRIM(@permissionEndDate)), ''), 120);
    DECLARE @Falg1 BIGINT = 0;
    DECLARE @Falg2 BIGINT = 0;


    if
    (SELECT COUNT(*)  
    FROM dbo.DistributorPermissionType d
    inner join dbo.PermissionType p on d.permissionTypeID_FK = p.permissionTypeID
    WHERE distributorPermissionTypeID = @DistributorPermissionTypeID_FK and p.RoleID_FK = 20 and d.distributorPermissionTypeActive = 1 and p.permissionTypeActive = 1) > 0
    begin

    set @Falg1 = 1

    end


    if
    (SELECT COUNT(*)  
    FROM dbo.Permission p
    inner join dbo.DistributorPermissionType d on p.DistributorPermissionTypeID_FK = d.distributorPermissionTypeID
    inner join dbo.PermissionType t on d.permissionTypeID_FK = t.permissionTypeID
    WHERE p.UsersID_FK = 4 and t.RoleID_FK = 20 and p.permissionActive = 1 and d.distributorPermissionTypeActive = 1 and t.permissionTypeActive = 1) > 0
    begin

    set @Falg2 = 1

    end




    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001 (داخل BEGIN/END + ; قبل THROW)
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

        IF (@StartDT IS NOT NULL AND @EndDT IS NOT NULL AND @EndDT <= @StartDT)
        BEGIN
            ;THROW 50001, N'لايمكن ان يكون تاريخ النهاية اصغر من او مساوي لتاريخ البداية', 1;
        END

        IF (@StartDT IS NOT NULL AND @StartDT < CAST(GETDATE() AS DATE))
        BEGIN
            ;THROW 50001, N'لايمكن ان يكون تاريخ البداية اصغر من تاريخ اليوم', 1;
        END

        IF (@EndDT IS NOT NULL AND @EndDT <= CAST(GETDATE() AS DATE))
        BEGIN
            ;THROW 50001, N'لايمكن ان يكون تاريخ النهاية اصغر من او مساوي لتاريخ اليوم', 1;
        END

        IF (@Falg1 = @Falg2)
        BEGIN
            ;THROW 50001, N'لايمكن ان يكون مستخدم واحد مسؤول استلام وتسليم المساكن في قسمين', 1;
        END






        ----------------------------------------------------------------
        -- تحديث صلاحيات منتهية (كما عندك)
        ----------------------------------------------------------------
        UPDATE  dbo.Permission
        SET permissionActive = 0
        WHERE permissionEndDate IS NOT NULL
          AND CAST(permissionEndDate AS DATE) < CAST(GETDATE() AS DATE);

        UPDATE  dbo.Permission
        SET permissionEndDate = CAST(GETDATE() AS DATE)
        WHERE permissionActive = 0
          AND permissionEndDate IS NULL;

        UPDATE  dbo.UserDistributor
        SET UDActive = 0
        WHERE UDEndDate IS NOT NULL
          AND CAST(UDEndDate AS DATE) < CAST(GETDATE() AS DATE);

        UPDATE  dbo.UserDistributor
        SET UDEndDate = CAST(GETDATE() AS DATE)
        WHERE UDActive = 0
          AND UDEndDate IS NULL;

        ----------------------------------------------------------------
        -- DSDID (فقط إذا searchID = 5)
        ----------------------------------------------------------------
        IF ISNULL(@searchID, 0) = 5
        BEGIN
            IF (@IdaraID IS NOT NULL AND @DeptID IS NULL AND @SectionID IS NULL AND @DivisonID IS NULL)
            BEGIN
                SELECT @DSDID = dsd.DSDID
                FROM  dbo.DeptSecDiv dsd
                WHERE dsd.idaraID_FK = @IdaraID
                  AND dsd.deptID_FK IS NULL AND dsd.secID_FK IS NULL AND dsd.divID_FK IS NULL;
            END
            ELSE IF (@IdaraID IS NOT NULL AND @DeptID IS NOT NULL AND @SectionID IS NULL AND @DivisonID IS NULL)
            BEGIN
                SELECT @DSDID = dsd.DSDID
                FROM  dbo.DeptSecDiv dsd
                WHERE dsd.idaraID_FK = @IdaraID
                  AND dsd.deptID_FK = @DeptID
                  AND dsd.secID_FK IS NULL AND dsd.divID_FK IS NULL;
            END
            ELSE IF (@IdaraID IS NOT NULL AND @DeptID IS NOT NULL AND @SectionID IS NOT NULL AND @DivisonID IS NULL)
            BEGIN
                SELECT @DSDID = dsd.DSDID
                FROM  dbo.DeptSecDiv dsd
                WHERE dsd.idaraID_FK = @IdaraID
                  AND dsd.deptID_FK = @DeptID
                  AND dsd.secID_FK = @SectionID
                  AND dsd.divID_FK IS NULL;
            END
            ELSE IF (@IdaraID IS NOT NULL AND @DeptID IS NOT NULL AND @SectionID IS NOT NULL AND @DivisonID IS NOT NULL)
            BEGIN
                SELECT @DSDID = dsd.DSDID
                FROM  dbo.DeptSecDiv dsd
                WHERE dsd.idaraID_FK = @IdaraID
                  AND dsd.deptID_FK = @DeptID
                  AND dsd.secID_FK = @SectionID
                  AND dsd.divID_FK = @DivisonID;
            END
            ELSE
            BEGIN
                ;THROW 50001, N'حصل خطأ غير متوقع في تحديد DSDID', 1;
            END

            IF @DSDID IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ ما - DSDID غير موجود', 1;
            END
        END

        ----------------------------------------------------------------
        -- INSERT
        ----------------------------------------------------------------
        IF @Action = N'INSERT'
        BEGIN
            IF (ISNULL(@searchID,0) = 1 AND (NULLIF(LTRIM(RTRIM(@UsersID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار المستخدم اولا', 1;
            END

            IF (ISNULL(@searchID,0) = 2 AND (NULLIF(LTRIM(RTRIM(@distributorID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار الموزع اولا', 1;
            END

            IF (ISNULL(@searchID,0) = 3 AND (NULLIF(LTRIM(RTRIM(@RoleID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار الدور اولا', 1;
            END

            IF (ISNULL(@searchID,0) = 4 AND (NULLIF(LTRIM(RTRIM(@IdaraID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار الادارة اولا', 1;
            END

            IF (ISNULL(@searchID,0) = 5
                AND (NULLIF(LTRIM(RTRIM(@DeptID)), N'') IS NULL)
                AND (NULLIF(LTRIM(RTRIM(@SectionID)), N'') IS NULL)
                AND (NULLIF(LTRIM(RTRIM(@DivisonID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار القسم اولا', 1;
            END

            IF NULLIF(@DistributorPermissionTypeID_FK, 0) IS NULL
            BEGIN
                ;THROW 50001, N'نوع الصلاحية مطلوب', 1;
            END

            DECLARE @Flag INT = 0;

            IF ISNULL(@searchID,0) = 1
            BEGIN
                SELECT @Flag = COUNT(*)
                FROM  dbo.Permission p
                JOIN  dbo.DistributorPermissionType dt
                  ON p.DistributorPermissionTypeID_FK = dt.distributorPermissionTypeID
                WHERE p.DistributorPermissionTypeID_FK = @DistributorPermissionTypeID_FK
                  AND p.permissionActive = 1
                  AND dt.distributorPermissionTypeActive = 1
                  AND (p.permissionEndDate IS NULL OR CONVERT(date, p.permissionEndDate) > CONVERT(date, GETDATE()))
                  AND p.UsersID_FK = @UsersID;
            END
            ELSE IF ISNULL(@searchID,0) = 2
            BEGIN
                SELECT @Flag = COUNT(*)
                FROM  dbo.Permission p
                JOIN  dbo.DistributorPermissionType dt
                  ON p.DistributorPermissionTypeID_FK = dt.distributorPermissionTypeID
                WHERE p.DistributorPermissionTypeID_FK = @DistributorPermissionTypeID_FK
                  AND p.permissionActive = 1
                  AND dt.distributorPermissionTypeActive = 1
                  AND (p.permissionEndDate IS NULL OR CONVERT(date, p.permissionEndDate) > CONVERT(date, GETDATE()))
                  AND p.distributorID_FK = @distributorID;
            END
            ELSE IF ISNULL(@searchID,0) = 3
            BEGIN
                SELECT @Flag = COUNT(*)
                FROM  dbo.Permission p
                JOIN  dbo.DistributorPermissionType dt
                  ON p.DistributorPermissionTypeID_FK = dt.distributorPermissionTypeID
                WHERE p.DistributorPermissionTypeID_FK = @DistributorPermissionTypeID_FK
                  AND p.permissionActive = 1
                  AND dt.distributorPermissionTypeActive = 1
                  AND (p.permissionEndDate IS NULL OR CONVERT(date, p.permissionEndDate) > CONVERT(date, GETDATE()))
                  AND p.RoleID_FK = @RoleID;
            END
            ELSE IF ISNULL(@searchID,0) = 4
            BEGIN
                SELECT @Flag = COUNT(*)
                FROM  dbo.Permission p
                JOIN  dbo.DistributorPermissionType dt
                  ON p.DistributorPermissionTypeID_FK = dt.distributorPermissionTypeID
                WHERE p.DistributorPermissionTypeID_FK = @DistributorPermissionTypeID_FK
                  AND p.permissionActive = 1
                  AND dt.distributorPermissionTypeActive = 1
                  AND (p.permissionEndDate IS NULL OR CONVERT(date, p.permissionEndDate) > CONVERT(date, GETDATE()))
                  AND p.IdaraID_FK = @IdaraID;
            END
            ELSE IF ISNULL(@searchID,0) = 5
            BEGIN
                SELECT @Flag = COUNT(*)
                FROM  dbo.Permission p
                JOIN  dbo.DistributorPermissionType dt
                  ON p.DistributorPermissionTypeID_FK = dt.distributorPermissionTypeID
                WHERE p.DistributorPermissionTypeID_FK = @DistributorPermissionTypeID_FK
                  AND p.permissionActive = 1
                  AND dt.distributorPermissionTypeActive = 1
                  AND (p.permissionEndDate IS NULL OR CONVERT(date, p.permissionEndDate) > CONVERT(date, GETDATE()))
                  AND p.DSDID_FK = @DSDID;
            END
            ELSE
            BEGIN
                ;THROW 50001, N'يوجد خطأ ما - searchID غير صحيح', 1;
            END

            IF @Flag > 0
            BEGIN
                ;THROW 50001, N'البيانات مدخلة مسبقا', 1;
            END

            INSERT INTO  dbo.Permission
            (
                  DistributorPermissionTypeID_FK
                , UsersID_FK
                , distributorID_FK
                , RoleID_FK
                , IdaraID_FK
                , DSDID_FK
                , permissionStartDate
                , permissionEndDate
                , permissionActive
                , permissionNote
                , InIdaraID
                , entryData
                , hostName
            )
            VALUES
            (
                  @DistributorPermissionTypeID_FK
                , CASE WHEN @searchID = 1 THEN @UsersID ELSE NULL END
                , CASE WHEN @searchID = 2 THEN @distributorID ELSE NULL END
                , CASE WHEN @searchID = 3 THEN @RoleID ELSE NULL END
                , CASE WHEN @searchID = 4 THEN @IdaraID ELSE NULL END
                , CASE WHEN @searchID = 5 THEN @DSDID ELSE NULL END
                , ISNULL(CONVERT(DATETIME, @StartDT), GETDATE())
                , CONVERT(DATETIME, @EndDT)
                , 1
                , @permissionNote
                , @InIdaraID
                , @entryData
                , @hostName
            );

            IF @@ROWCOUNT <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة الصلاحية (Permission)', 1;
            END

            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة الصلاحية - Identity', 1;
            END

            SET @Note = N'{'
                + N'"PermissionID": "'                   + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"searchID": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @searchID), '') + N'"'
                + N',"UsersID_FK": "'                    + ISNULL(CONVERT(NVARCHAR(MAX), @UsersID), '') + N'"'
                + N',"distributorID_FK": "'              + ISNULL(CONVERT(NVARCHAR(MAX), @distributorID), '') + N'"'
                + N',"RoleID_FK": "'                     + ISNULL(CONVERT(NVARCHAR(MAX), @RoleID), '') + N'"'
                + N',"IdaraID_FK": "'                    + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID), '') + N'"'
                + N',"DSDID_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @DSDID), '') + N'"'
                + N',"permissionStartDate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @permissionStartDate), '') + N'"'
                + N',"permissionEndDate": "'             + ISNULL(CONVERT(NVARCHAR(MAX), @permissionEndDate), '') + N'"'
                + N',"permissionNote": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @permissionNote), '') + N'"'
                + N',"DistributorPermissionTypeID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @DistributorPermissionTypeID_FK), '') + N'"'
                + N',"entryData": "'                     + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[dbo].[Permission]', N'INSERT', ISNULL(@NewID, 0), @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم اضافة البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- INSERTFULLACCESS
        ----------------------------------------------------------------
        ELSE IF @Action = N'INSERTFULLACCESS'
        BEGIN

            IF EXISTS (SELECT 1 
                FROM  dbo.DistributorPermissionType dt
                INNER JOIN  dbo.PermissionType p
                    ON dt.permissionTypeID_FK = p.permissionTypeID
                WHERE dt.distributorID_FK = @distributorIDFroGiveAllPermissions
                  AND dt.distributorPermissionTypeActive = 1
                  AND p.permissionTypeActive = 1
                  AND p.RoleID_FK = 20
                  )
            BEGIN
                ;THROW 50001, N'لايمكن استخدام ميزة الوصول الكامل مع هذه الصفحة ', 1;
            END


            IF (ISNULL(@searchID,0) = 1 AND (NULLIF(LTRIM(RTRIM(@UsersID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار المستخدم اولا', 1;
            END

            IF (ISNULL(@searchID,0) = 2 AND (NULLIF(LTRIM(RTRIM(@distributorID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار الموزع اولا', 1;
            END

            IF (ISNULL(@searchID,0) = 3 AND (NULLIF(LTRIM(RTRIM(@RoleID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار الدور اولا', 1;
            END

            IF (ISNULL(@searchID,0) = 4 AND (NULLIF(LTRIM(RTRIM(@IdaraID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار الادارة اولا', 1;
            END

            IF (ISNULL(@searchID,0) = 5
                AND (NULLIF(LTRIM(RTRIM(@DeptID)), N'') IS NULL)
                AND (NULLIF(LTRIM(RTRIM(@SectionID)), N'') IS NULL)
                AND (NULLIF(LTRIM(RTRIM(@DivisonID)), N'') IS NULL))
            BEGIN
                ;THROW 50001, N'الرجاء اختيار القسم اولا', 1;
            END

            IF NULLIF(@distributorIDFroGiveAllPermissions, 0) IS NULL
            BEGIN
                ;THROW 50001, N'موزع منح الصلاحيات مطلوب', 1;
            END

            -- الإدخال حسب نوع الهدف
            IF ISNULL(@searchID,0) = 1
            BEGIN
                INSERT INTO  dbo.Permission
                (
                      DistributorPermissionTypeID_FK, UsersID_FK
                    , permissionStartDate, permissionEndDate, permissionNote
                    , permissionActive,InIdaraID, entryData, hostName
                )
                SELECT
                      dt.distributorPermissionTypeID, @UsersID
                    , ISNULL(CONVERT(DATETIME, @StartDT), GETDATE())
                    , CONVERT(DATETIME, @EndDT)
                    , @permissionNote
                    , 1,@InIdaraID, @entryData, @hostName
                FROM  dbo.DistributorPermissionType dt
                INNER JOIN  dbo.PermissionType p
                    ON dt.permissionTypeID_FK = p.permissionTypeID
                WHERE dt.distributorID_FK = @distributorIDFroGiveAllPermissions
                  AND dt.distributorPermissionTypeActive = 1
                  AND p.permissionTypeActive = 1
                  AND CAST(dt.distributorPermissionTypeStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                  AND (CAST(dt.distributorPermissionTypeEndDate AS DATE) > CAST(GETDATE() AS DATE)
                       OR dt.distributorPermissionTypeEndDate IS NULL)
                  AND dt.distributorPermissionTypeID NOT IN
                  (
                        SELECT r.DistributorPermissionTypeID_FK
                        FROM  dbo.Permission r
                        WHERE r.permissionActive = 1
                          AND CAST(r.permissionStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                          AND (CAST(r.permissionEndDate AS DATE) > CAST(GETDATE() AS DATE)
                               OR r.permissionEndDate IS NULL)
                          AND r.UsersID_FK = @UsersID
                  );

                SET @Rows = @@ROWCOUNT;
                IF @Rows <= 0
                BEGIN
                    ;THROW 50001, N'حصل خطأ في اضافة البيانات او الموظف يملك جميع الصلاحيات', 1;
                END
            END
            ELSE IF ISNULL(@searchID,0) = 2
            BEGIN
                INSERT INTO  dbo.Permission
                (
                      DistributorPermissionTypeID_FK, distributorID_FK
                    , permissionStartDate, permissionEndDate, permissionNote
                    , permissionActive,InIdaraID, entryData, hostName
                )
                SELECT
                      dt.distributorPermissionTypeID, @distributorID
                    , ISNULL(CONVERT(DATETIME, @StartDT), GETDATE())
                    , CONVERT(DATETIME, @EndDT)
                    , @permissionNote
                    , 1,@InIdaraID, @entryData, @hostName
                FROM  dbo.DistributorPermissionType dt
                INNER JOIN  dbo.PermissionType p
                    ON dt.permissionTypeID_FK = p.permissionTypeID
                WHERE dt.distributorID_FK = @distributorIDFroGiveAllPermissions
                  AND dt.distributorPermissionTypeActive = 1
                  AND p.permissionTypeActive = 1
                  AND CAST(dt.distributorPermissionTypeStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                  AND (CAST(dt.distributorPermissionTypeEndDate AS DATE) > CAST(GETDATE() AS DATE)
                       OR dt.distributorPermissionTypeEndDate IS NULL)
                  AND dt.distributorPermissionTypeID NOT IN
                  (
                        SELECT r.DistributorPermissionTypeID_FK
                        FROM  dbo.Permission r
                        WHERE r.permissionActive = 1
                          AND CAST(r.permissionStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                          AND (CAST(r.permissionEndDate AS DATE) > CAST(GETDATE() AS DATE)
                               OR r.permissionEndDate IS NULL)
                          AND r.distributorID_FK = @distributorID
                  );

                SET @Rows = @@ROWCOUNT;
                IF @Rows <= 0
                BEGIN
                    ;THROW 50001, N'حصل خطأ في اضافة البيانات او الموزع يملك جميع الصلاحيات', 1;
                END
            END
            ELSE IF ISNULL(@searchID,0) = 3
            BEGIN
                INSERT INTO  dbo.Permission
                (
                      DistributorPermissionTypeID_FK, RoleID_FK
                    , permissionStartDate, permissionEndDate, permissionNote
                    , permissionActive,InIdaraID, entryData, hostName
                )
                SELECT
                      dt.distributorPermissionTypeID, @RoleID
                    , ISNULL(CONVERT(DATETIME, @StartDT), GETDATE())
                    , CONVERT(DATETIME, @EndDT)
                    , @permissionNote
                    , 1,@InIdaraID, @entryData, @hostName
                FROM  dbo.DistributorPermissionType dt
                INNER JOIN  dbo.PermissionType p
                    ON dt.permissionTypeID_FK = p.permissionTypeID
                WHERE dt.distributorID_FK = @distributorIDFroGiveAllPermissions
                  AND dt.distributorPermissionTypeActive = 1
                  AND p.permissionTypeActive = 1
                  AND CAST(dt.distributorPermissionTypeStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                  AND (CAST(dt.distributorPermissionTypeEndDate AS DATE) > CAST(GETDATE() AS DATE)
                       OR dt.distributorPermissionTypeEndDate IS NULL)
                  AND dt.distributorPermissionTypeID NOT IN
                  (
                        SELECT r.DistributorPermissionTypeID_FK
                        FROM  dbo.Permission r
                        WHERE r.permissionActive = 1
                          AND CAST(r.permissionStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                          AND (CAST(r.permissionEndDate AS DATE) > CAST(GETDATE() AS DATE)
                               OR r.permissionEndDate IS NULL)
                          AND r.RoleID_FK = @RoleID
                  );

                SET @Rows = @@ROWCOUNT;
                IF @Rows <= 0
                BEGIN
                    ;THROW 50001, N'حصل خطأ في اضافة البيانات او الدور يملك جميع الصلاحيات', 1;
                END
            END
            ELSE IF ISNULL(@searchID,0) = 4
            BEGIN
                INSERT INTO  dbo.Permission
                (
                      DistributorPermissionTypeID_FK, IdaraID_FK
                    , permissionStartDate, permissionEndDate, permissionNote
                    , permissionActive,InIdaraID, entryData, hostName
                )
                SELECT
                      dt.distributorPermissionTypeID, @IdaraID
                    , ISNULL(CONVERT(DATETIME, @StartDT), GETDATE())
                    , CONVERT(DATETIME, @EndDT)
                    , @permissionNote
                    , 1,@InIdaraID, @entryData, @hostName
                FROM  dbo.DistributorPermissionType dt
                INNER JOIN  dbo.PermissionType p
                    ON dt.permissionTypeID_FK = p.permissionTypeID
                WHERE dt.distributorID_FK = @distributorIDFroGiveAllPermissions
                  AND dt.distributorPermissionTypeActive = 1
                  AND p.permissionTypeActive = 1
                  AND CAST(dt.distributorPermissionTypeStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                  AND (CAST(dt.distributorPermissionTypeEndDate AS DATE) > CAST(GETDATE() AS DATE)
                       OR dt.distributorPermissionTypeEndDate IS NULL)
                  AND dt.distributorPermissionTypeID NOT IN
                  (
                        SELECT r.DistributorPermissionTypeID_FK
                        FROM  dbo.Permission r
                        WHERE r.permissionActive = 1
                          AND CAST(r.permissionStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                          AND (CAST(r.permissionEndDate AS DATE) > CAST(GETDATE() AS DATE)
                               OR r.permissionEndDate IS NULL)
                          AND r.IdaraID_FK = @IdaraID
                  );

                SET @Rows = @@ROWCOUNT;
                IF @Rows <= 0
                BEGIN
                    ;THROW 50001, N'حصل خطأ في اضافة البيانات او الادارة تملك جميع الصلاحيات', 1;
                END
            END
            ELSE IF ISNULL(@searchID,0) = 5
            BEGIN
                INSERT INTO  dbo.Permission
                (
                      DistributorPermissionTypeID_FK, DSDID_FK
                    , permissionStartDate, permissionEndDate, permissionNote
                    , permissionActive,InIdaraID, entryData, hostName
                )
                SELECT
                      dt.distributorPermissionTypeID, @DSDID
                    , ISNULL(CONVERT(DATETIME, @StartDT), GETDATE())
                    , CONVERT(DATETIME, @EndDT)
                    , @permissionNote
                    , 1,@InIdaraID, @entryData, @hostName
                FROM  dbo.DistributorPermissionType dt
                INNER JOIN  dbo.PermissionType p
                    ON dt.permissionTypeID_FK = p.permissionTypeID
                WHERE dt.distributorID_FK = @distributorIDFroGiveAllPermissions
                  AND dt.distributorPermissionTypeActive = 1
                  AND p.permissionTypeActive = 1
                  AND CAST(dt.distributorPermissionTypeStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                  AND (CAST(dt.distributorPermissionTypeEndDate AS DATE) > CAST(GETDATE() AS DATE)
                       OR dt.distributorPermissionTypeEndDate IS NULL)
                  AND dt.distributorPermissionTypeID NOT IN
                  (
                        SELECT r.DistributorPermissionTypeID_FK
                        FROM  dbo.Permission r
                        WHERE r.permissionActive = 1
                          AND CAST(r.permissionStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                          AND (CAST(r.permissionEndDate AS DATE) > CAST(GETDATE() AS DATE)
                               OR r.permissionEndDate IS NULL)
                          AND r.DSDID_FK = @DSDID
                  );

                SET @Rows = @@ROWCOUNT;
                IF @Rows <= 0
                BEGIN
                    ;THROW 50001, N'حصل خطأ في اضافة البيانات او القسم/الفرع/الشعبة يملك جميع الصلاحيات', 1;
                END
            END
            ELSE
            BEGIN
                ;THROW 50001, N'يوجد خطأ ما - searchID غير صحيح', 1;
            END

            SET @Note = N'{'
                + N'"Action": "INSERTFULLACCESS"'
                + N',"searchID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @searchID), '') + N'"'
                + N',"RowsInserted": "' + CONVERT(NVARCHAR(50), @Rows) + N'"'
                + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[dbo].[Permission]', N'INSERTFULLACCESS', 0, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم اضافة البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- UPDATE (يقفل القديم + يضيف جديد)
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPDATE'
        BEGIN
            IF @PermissionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتعديل', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM  dbo.Permission WHERE permissionID = @PermissionID)
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

            UPDATE  dbo.Permission
            SET permissionEndDate = CAST(GETDATE() AS DATE),
                permissionActive  = 0
            WHERE permissionID = @PermissionID;

            IF @@ROWCOUNT <= 0
            BEGIN
                ;THROW 50002, N'لم يتم تعديل السجل القديم', 1;
            END

            INSERT INTO  dbo.Permission
            (
                  DistributorPermissionTypeID_FK
                , UsersID_FK
                , RoleID_FK
                , distributorID_FK
                , IdaraID_FK
                , DSDID_FK
                , permissionStartDate
                , permissionEndDate
                , permissionNote
                , permissionActive
                , InIdaraID
                , entryData
                , hostName
            )
            SELECT
                  p.DistributorPermissionTypeID_FK
                , p.UsersID_FK
                , p.RoleID_FK
                , p.distributorID_FK
                , p.IdaraID_FK
                , p.DSDID_FK
                , ISNULL(CONVERT(DATETIME, @StartDT), GETDATE())
                , CONVERT(DATETIME, @EndDT)
                , @permissionNote
                , 1
                , @InIdaraID
                , @entryData
                , @hostName
            FROM  dbo.Permission p
            WHERE p.permissionID = @PermissionID;

            SET @Rows = @@ROWCOUNT;
            IF @Rows <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة السجل الجديد بعد التعديل', 1;
            END

            SET @Note = N'{'
                + N'"PermissionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @PermissionID), '') + N'"'
                + N',"permissionStartDate": "' + ISNULL(CONVERT(NVARCHAR(MAX), @permissionStartDate), '') + N'"'
                + N',"permissionEndDate": "' + ISNULL(CONVERT(NVARCHAR(MAX), @permissionEndDate), '') + N'"'
                + N',"permissionNote": "' + ISNULL(CONVERT(NVARCHAR(MAX), @permissionNote), '') + N'"'
                + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[dbo].[Permission]', N'UPDATE', @PermissionID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم تعديل البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- DELETE (يقفل صلاحية)
        ----------------------------------------------------------------
        ELSE IF @Action = N'DELETE'
        BEGIN
            IF @PermissionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للحذف', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM  dbo.Permission WHERE permissionID = @PermissionID)
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

            UPDATE  dbo.Permission
            SET permissionEndDate = CAST(GETDATE() AS DATE),
                permissionActive  = 0
            WHERE permissionID = @PermissionID;

            IF @@ROWCOUNT <= 0
            BEGIN
                ;THROW 50002, N'لم يتم حذف أي سجل', 1;
            END

            SET @Note = N'{'
                + N'"PermissionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @PermissionID), '') + N'"'
                + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[dbo].[Permission]', N'DELETE', @PermissionID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم حذف البيانات بنجاح' AS Message_;
            RETURN;
        END
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[ReSetUserPassword]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[ReSetUserPassword]
(
    @Action              NVARCHAR(200),
    @usersID             NVARCHAR(200) = NULL,
    @NationalID          NVARCHAR(20) = NULL,     
    @PlainPassword       NVARCHAR(200) = NULL,
    @OldPassword         NVARCHAR(200) = NULL,
    @idaraID_FK          NVARCHAR(200) = NULL,
    @entryData           NVARCHAR(20) = NULL,     
    @hostName            NVARCHAR(200) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;



    DECLARE @usersIDs bigint;
    set @usersIDs = (
    select TOP(1) u.usersID
    from  dbo.Users u 
    where u.nationalID = @NationalID
    and u.usersActive = 1 
    and u.usersStartDate is not null 
    and cast(u.usersStartDate as date) <= cast(GETDATE() as date)
    and((cast(u.usersEndDate as date) > cast(GETDATE() as date)) OR u.usersEndDate is null)
    order by u.usersID desc
    )

    DECLARE @Salt       VARBINARY(32);
    DECLARE @Hash       VARBINARY(64);

    DECLARE @PrevSalt   VARBINARY(32);
    DECLARE @PrevHash   VARBINARY(64);
    DECLARE @Candidate  VARBINARY(64);

    BEGIN TRY

    IF @tc = 0
            BEGIN TRAN;


              IF @Action IN(N'RESETUSERPASSWORD')
        BEGIN

        DECLARE @DefualtPlainPassword       NVARCHAR(200)
        SET @DefualtPlainPassword =N'Aa123456'


         
            --IF NULLIF(LTRIM(RTRIM(@Notes)), N'') IS NULL
            --BEGIN
            --    ;THROW 50001, N'يجب كتابة وصف لمحضر التخصيص', 1;
            --END

             ----------------------------------------------------
        -- 0) التحقق أن المستخدم موجود وفعال في جدول [User]
        ----------------------------------------------------
        IF NOT EXISTS (
            SELECT 1   
              from  dbo.Users u 
              where u.usersID = @usersID
              and u.usersActive = 1 
              and u.usersStartDate is not null 
              and cast(u.usersStartDate as date) <= cast(GETDATE() as date)
              and((cast(u.usersEndDate as date) > cast(GETDATE() as date)) OR u.usersEndDate is null)
             
        )
        
            BEGIN
                ;THROW 50001, N'المستخدم غير موجود بالنظام', 1;
            END

            
       


        ----------------------------------------------------
        -- 1) التحقق من تعقيد كلمة المرور الجديدة
        ----------------------------------------------------
        --IF LEN(@PlainPassword) < 8
        --   OR @PlainPassword NOT LIKE '%[0-9]%'      -- لا تحتوي رقم
        --   OR @PlainPassword NOT LIKE '%[A-Za-z]%'   -- لا تحتوي حرف إنجليزي
        --BEGIN
        --    SELECT 0 AS IsSuccessful,
        --           N'كلمة المرور غير مقبولة. يجب أن لا تقل عن 8 خانات وتحتوي على حروف إنجليزية وأرقام.' AS Message_;
        --    RETURN;
        --END


        ----------------------------------------------------
        -- 2) التأكد أن كلمة المرور الجديدة ليست نفسها القديمة
        ----------------------------------------------------
        --SELECT TOP (1)
        --    @PrevSalt = PasswordSalt,
        --    @PrevHash = PasswordHash
        --FROM dbo.usersPassword p
        --WHERE p.usersID_FK = @UsersID
        --  AND ISNULL(userPasswordActive, 1) = 1
        --ORDER BY userPasswordStartDate DESC, usersPasswordID DESC;

        --IF @PrevHash IS NOT NULL
        --BEGIN
        --    SET @Candidate = HASHBYTES(
        --                        'SHA2_256',
        --                        @PrevSalt + CAST(@PlainPassword AS VARBINARY(200))
        --                     );

        --    IF @Candidate = @PrevHash
        --    BEGIN
        --        ;THROW 50001, N'لا يمكن استخدام نفس كلمة المرور السابقة. الرجاء اختيار كلمة مرور جديدة مختلفة.', 1;
        --    END
                    
        --END


        ----------------------------------------------------
        -- 3) البدء في المعاملة
        ----------------------------------------------------
        BEGIN TRANSACTION;

        -- تعطيل كل كلمات المرور السابقة
        UPDATE dbo.usersPassword
        SET 
            userPasswordActive  = 0,
            userPasswordEndDate = CAST(GETDATE() AS DATE)
        WHERE usersID_FK = @UsersID
          AND ISNULL(userPasswordActive, 1) = 1;


        ----------------------------------------------------
        -- 4) إنشاء Salt جديد + Hash جديد
        ----------------------------------------------------
        SET @Salt = CRYPT_GEN_RANDOM(32);

        SET @Hash = HASHBYTES(
                        'SHA2_256',
                        @Salt + CAST(@DefualtPlainPassword AS VARBINARY(200))
                    );


        ----------------------------------------------------
        -- 5) إدخال كلمة المرور الجديدة
        ----------------------------------------------------
        INSERT INTO dbo.usersPassword
        (
            usersID_FK,
            PasswordHash,
            PasswordSalt,
            HashAlgorithm,
            userPasswordStartDate,
            userPasswordActive,
            ChangedPassword,
            entryDate,
            entryData,
            hostName
        )
        VALUES
        (
            @UsersID,
            @Hash,
            @Salt,
            'SHA2_256',
            CAST(GETDATE() AS DATE),
            1,
            0,
            GETDATE(),
            @entryData,
            ISNULL(@hostName, HOST_NAME())
        );

        COMMIT TRANSACTION;

         SELECT 1 AS IsSuccessful, N'تم اعادة ضبط كلمة المرور بنجاح.' AS Message_;
            RETURN;

           
        END


        ELSE IF @Action = N'CHANGEUSERPASSWORD'
        BEGIN
            ----------------------------------------------------
            -- 0) Verify user exists and is active
            ----------------------------------------------------
            IF NOT EXISTS (
                SELECT 1   
                FROM  dbo.Users u 
                WHERE u.usersID = @usersID
                  AND u.usersActive = 1 
                  AND u.usersStartDate IS NOT NULL 
                  AND CAST(u.usersStartDate AS DATE) <= CAST(GETDATE() AS DATE)
                  AND (CAST(u.usersEndDate AS DATE) > CAST(GETDATE() AS DATE) OR u.usersEndDate IS NULL)
            )
            BEGIN
                SELECT 0 AS IsSuccessful, N'المستخدم غير موجود أو غير نشط' AS Message_;
                RETURN;
            END

            ----------------------------------------------------
            -- 1) Verify old password matches
            ----------------------------------------------------
            SELECT TOP (1)
                @PrevSalt = PasswordSalt,
                @PrevHash = PasswordHash
            FROM dbo.usersPassword p
            WHERE p.usersID_FK = @usersID
              AND ISNULL(userPasswordActive, 1) = 1
            ORDER BY userPasswordStartDate DESC, usersPasswordID DESC;

            IF @PrevHash IS NULL
            BEGIN
                SELECT 0 AS IsSuccessful, N'لم يتم العثور على كلمة المرور الحالية' AS Message_;
                RETURN;
            END

            -- Hash the provided old password and compare
            SET @Candidate = HASHBYTES(
                                'SHA2_256',
                                @PrevSalt + CAST(@OldPassword AS VARBINARY(200))
                             );

            IF @Candidate != @PrevHash
            BEGIN
                SELECT 0 AS IsSuccessful, N'كلمة المرور الحالية غير صحيحة' AS Message_;
                RETURN;
            END

            ----------------------------------------------------
            -- 2) Validate new password complexity
            ----------------------------------------------------
             IF LEN(@PlainPassword) < 8
           OR @PlainPassword NOT LIKE '%[0-9]%'      -- لا تحتوي رقم
           OR @PlainPassword NOT LIKE '%[A-Za-z]%'   -- لا تحتوي حرف إنجليزي
        BEGIN
            SELECT 0 AS IsSuccessful,
                   N'كلمة المرور غير مقبولة. يجب أن لا تقل عن 8 خانات وتحتوي على حروف إنجليزية وأرقام.' AS Message_;
            RETURN;
        END

            ----------------------------------------------------
            -- 3) Ensure new password is different from old
            ----------------------------------------------------
            SET @Candidate = HASHBYTES(
                                'SHA2_256',
                                @PrevSalt + CAST(@PlainPassword AS VARBINARY(200))
                             );

            IF @Candidate = @PrevHash
            BEGIN
                SELECT 0 AS IsSuccessful, N'كلمة المرور الجديدة يجب أن تختلف عن الحالية' AS Message_;
                RETURN;
            END

            ----------------------------------------------------
            -- 4) Deactivate old passwords
            ----------------------------------------------------
            UPDATE dbo.usersPassword
            SET 
                userPasswordActive  = 0,
                userPasswordEndDate = CAST(GETDATE() AS DATE)
            WHERE usersID_FK = @usersID
              AND ISNULL(userPasswordActive, 1) = 1;

            ----------------------------------------------------
            -- 5) Create new Salt and Hash
            ----------------------------------------------------
            SET @Salt = CRYPT_GEN_RANDOM(32);
            SET @Hash = HASHBYTES(
                            'SHA2_256',
                            @Salt + CAST(@PlainPassword AS VARBINARY(200))
                        );

            ----------------------------------------------------
            -- 6) Insert new password
            ----------------------------------------------------
            INSERT INTO dbo.usersPassword
            (
                usersID_FK,
                PasswordHash,
                PasswordSalt,
                HashAlgorithm,
                userPasswordStartDate,
                userPasswordActive,
                ChangedPassword,
                entryDate,
                entryData,
                hostName
            )
            VALUES
            (
                @usersID,
                @Hash,
                @Salt,
                'SHA2_256',
                CAST(GETDATE() AS DATE),
                1,
                1,  -- User changed their own password
                GETDATE(),
                @entryData,
                ISNULL(@hostName, HOST_NAME())
            );

            SELECT 1 AS IsSuccessful, N'تم تغيير كلمة المرور بنجاح' AS Message_;
            
            IF @tc = 0
                COMMIT TRAN;
                
            RETURN;
        END


        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

     END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SetUserPassword]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SetUserPassword]
(
    @NationalID          NVARCHAR(20),     -- الرقم العام / رقم المستخدم
    @PlainPassword   NVARCHAR(200),    -- كلمة المرور الجديدة
    @entryData       NVARCHAR(20),     -- المستخدم الذي قام بالتعديل
    @hostName        NVARCHAR(200) = NULL,
    @IsSuccessful    BIT OUTPUT,
    @Message_        NVARCHAR(4000) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    SET @IsSuccessful = 0;
    SET @Message_ = N'';

    DECLARE @usersID bigint;
    set @usersID = (
    select TOP(1) u.usersID
    from  dbo.Users u 
    where u.nationalID = @NationalID
    and u.usersActive = 1 
    and u.usersStartDate is not null 
    and cast(u.usersStartDate as date) <= cast(GETDATE() as date)
    and((cast(u.usersEndDate as date) > cast(GETDATE() as date)) OR u.usersEndDate is null)
    order by u.usersID desc
    )

    DECLARE @Salt       VARBINARY(32);
    DECLARE @Hash       VARBINARY(64);

    DECLARE @PrevSalt   VARBINARY(32);
    DECLARE @PrevHash   VARBINARY(64);
    DECLARE @Candidate  VARBINARY(64);

    BEGIN TRY

        ----------------------------------------------------
        -- 0) التحقق أن المستخدم موجود وفعال في جدول [User]
        ----------------------------------------------------
        IF NOT EXISTS (
            SELECT 1   
              from  dbo.Users u 
              where u.nationalID = @NationalID
              and u.usersActive = 1 
              and u.usersStartDate is not null 
              and cast(u.usersStartDate as date) <= cast(GETDATE() as date)
              and((cast(u.usersEndDate as date) > cast(GETDATE() as date)) OR u.usersEndDate is null)
             
        )
        BEGIN
           SET @IsSuccessful = 0;
SET @Message_ = N'المستخدم غير موجود أو غير فعّال في النظام.';
RETURN;

            
        END


        ----------------------------------------------------
        -- 1) التحقق من تعقيد كلمة المرور الجديدة
        ----------------------------------------------------
        --IF LEN(@PlainPassword) < 8
        --   OR @PlainPassword NOT LIKE '%[0-9]%'      -- لا تحتوي رقم
        --   OR @PlainPassword NOT LIKE '%[A-Za-z]%'   -- لا تحتوي حرف إنجليزي
        --BEGIN
        --    SELECT 0 AS IsSuccessful,
        --           N'كلمة المرور غير مقبولة. يجب أن لا تقل عن 8 خانات وتحتوي على حروف إنجليزية وأرقام.' AS Message_;
        --    RETURN;
        --END


        ----------------------------------------------------
        -- 2) التأكد أن كلمة المرور الجديدة ليست نفسها القديمة
        ----------------------------------------------------
        SELECT TOP (1)
            @PrevSalt = PasswordSalt,
            @PrevHash = PasswordHash
        FROM dbo.usersPassword p
        WHERE p.usersID_FK = @UsersID
          AND ISNULL(userPasswordActive, 1) = 1
        ORDER BY userPasswordStartDate DESC, usersPasswordID DESC;

        IF @PrevHash IS NOT NULL
        BEGIN
            SET @Candidate = HASHBYTES(
                                'SHA2_256',
                                @PrevSalt + CAST(@PlainPassword AS VARBINARY(200))
                             );

            IF @Candidate = @PrevHash
            BEGIN
              
                      SET @IsSuccessful = 0;
                      SET @Message_ = N'لا يمكن استخدام نفس كلمة المرور السابقة. الرجاء اختيار كلمة مرور جديدة مختلفة.';
                RETURN;
            END
        END


        ----------------------------------------------------
        -- 3) البدء في المعاملة
        ----------------------------------------------------
        BEGIN TRANSACTION;

        -- تعطيل كل كلمات المرور السابقة
        UPDATE dbo.usersPassword
        SET 
            userPasswordActive  = 0,
            userPasswordEndDate = CAST(GETDATE() AS DATE)
        WHERE usersID_FK = @UsersID
          AND ISNULL(userPasswordActive, 1) = 1;


        ----------------------------------------------------
        -- 4) إنشاء Salt جديد + Hash جديد
        ----------------------------------------------------
        SET @Salt = CRYPT_GEN_RANDOM(32);

        SET @Hash = HASHBYTES(
                        'SHA2_256',
                        @Salt + CAST(@PlainPassword AS VARBINARY(200))
                    );


        ----------------------------------------------------
        -- 5) إدخال كلمة المرور الجديدة
        ----------------------------------------------------
        INSERT INTO dbo.usersPassword
        (
            usersID_FK,
            PasswordHash,
            PasswordSalt,
            HashAlgorithm,
            userPasswordStartDate,
            userPasswordActive,
            ChangedPassword,
            entryDate,
            entryData,
            hostName
        )
        VALUES
        (
            @UsersID,
            @Hash,
            @Salt,
            'SHA2_256',
            CAST(GETDATE() AS DATE),
            1,
            0,
            GETDATE(),
            @entryData,
            ISNULL(@hostName, HOST_NAME())
        );

        COMMIT TRANSACTION;

        SET @IsSuccessful = 1;
        SET @Message_ = N'تم تحديث كلمة المرور / إنشاؤها بنجاح.';
        RETURN;



    END TRY
    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
            SET @IsSuccessful = 0;
            SET @Message_ = N'حصل خطأ أثناء تنفيذ العملية: ' + ERROR_MESSAGE();
            RETURN;

        
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[sp_AiChat_Dashboard]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[sp_AiChat_Dashboard]
(
    @FromDate DATETIME2 = NULL,
    @ToDate   DATETIME2 = NULL,
    @TopN     INT = 50
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @FromDate IS NULL SET @FromDate = DATEADD(DAY, -30, SYSDATETIME());
    IF @ToDate   IS NULL SET @ToDate   = SYSDATETIME();

    ----------------------------------------------------------------------
    -- SET 1: Heatmap (Entity+Intent+Page) مع الجودة والتغطية
    ----------------------------------------------------------------------
    SELECT TOP (@TopN)
        ISNULL(EntityKey, N'(NULL)') AS EntityKey,
        ISNULL(Intent,   N'(NULL)') AS Intent,
        ISNULL(PageKey,  N'(NULL)') AS PageKey,
        COUNT(*) AS Chats,
        SUM(CASE WHEN UserFeedback = -1 THEN 1 ELSE 0 END) AS ThumbsDown,
        SUM(CASE WHEN UserFeedback =  1 THEN 1 ELSE 0 END) AS ThumbsUp,
        AVG(CAST(ResponseTimeMs AS FLOAT)) AS AvgMs,
        AVG(CASE WHEN ISNULL(CitationsCount,0) > 0 THEN 1.0 ELSE 0.0 END) * 100 AS CitationCoveragePct
    FROM dbo.AiChatHistory
    WHERE CreatedAt BETWEEN @FromDate AND @ToDate
    GROUP BY EntityKey, Intent, PageKey
    ORDER BY Chats DESC;

    ----------------------------------------------------------------------
    -- SET 2: الأسئلة السيئة + مصادرها
    ----------------------------------------------------------------------
   SELECT TOP (@TopN)
    h.ChatId,
    h.CreatedAt,
    h.UserId,
    LEFT(h.UserQuestion, 250) AS Q,
    h.EntityKey,
    h.Intent,
    h.PageKey,
    h.UserFeedback,
    h.ResponseTimeMs,
    h.CitationsCount,
    src.Sources
FROM dbo.AiChatHistory h
OUTER APPLY
(
    SELECT STRING_AGG(s.Source, ' | ') AS Sources
    FROM (SELECT DISTINCT Source
          FROM dbo.AiChatCitations
          WHERE ChatId = h.ChatId) s
) src
WHERE h.CreatedAt BETWEEN @FromDate AND @ToDate
  AND h.UserFeedback = -1
ORDER BY h.CreatedAt DESC;

    ----------------------------------------------------------------------
    -- SET 3: Backlog للتطوير من AiFrequentQuestions
    ----------------------------------------------------------------------
    SELECT TOP (@TopN)
        QuestionId,
        Question,
        EntityKey,
        Intent,
        AskCount,
        SuccessRate,
        LastAsked,
        NeedsImprovement,
        SuggestedAnswer
    FROM dbo.AiFrequentQuestions
    WHERE (AskCount >= 3 AND (SuggestedAnswer IS NULL OR LTRIM(RTRIM(SuggestedAnswer)) = N''))
       OR (SuccessRate IS NOT NULL AND SuccessRate < 60)
       OR NeedsImprovement = 1
    ORDER BY AskCount DESC, ISNULL(SuccessRate, 0) ASC, LastAsked DESC;

    ----------------------------------------------------------------------
    -- SET 4: أسئلة بدون Citations
    ----------------------------------------------------------------------
    SELECT TOP (@TopN)
        h.ChatId,
        h.CreatedAt,
        h.EntityKey,
        h.Intent,
        h.PageKey,
        LEFT(h.UserQuestion, 300) AS Q
    FROM dbo.AiChatHistory h
    WHERE h.CreatedAt BETWEEN @FromDate AND @ToDate
      AND ISNULL(h.CitationsCount, 0) = 0
    ORDER BY h.CreatedAt DESC;

    ----------------------------------------------------------------------
    -- SET 5: أكثر ملفات MD استخداماً + علاقتها بالتقييم
    ----------------------------------------------------------------------
    SELECT TOP (@TopN)
        c.Source,
        COUNT(*) AS Citations,
        COUNT(DISTINCT c.ChatId) AS ChatsUsingSource,
        AVG(CAST(h.UserFeedback AS FLOAT)) AS AvgFeedback,
        SUM(CASE WHEN h.UserFeedback = -1 THEN 1 ELSE 0 END) AS DownCount,
        SUM(CASE WHEN h.UserFeedback =  1 THEN 1 ELSE 0 END) AS UpCount
    FROM dbo.AiChatCitations c
    JOIN dbo.AiChatHistory h ON h.ChatId = c.ChatId
    WHERE h.CreatedAt BETWEEN @FromDate AND @ToDate
    GROUP BY c.Source
    ORDER BY ChatsUsingSource DESC, Citations DESC;

    ----------------------------------------------------------------------
    -- SET 6: تكرار نفس المصدر داخل نفس Chat (يبي Dedup)
    ----------------------------------------------------------------------
    SELECT TOP (@TopN)
        c.ChatId,
        MAX(h.CreatedAt) AS CreatedAt,
        c.Source,
        COUNT(*) AS RepeatCount
    FROM dbo.AiChatCitations c
    JOIN dbo.AiChatHistory h ON h.ChatId = c.ChatId
    WHERE h.CreatedAt BETWEEN @FromDate AND @ToDate
    GROUP BY c.ChatId, c.Source
    HAVING COUNT(*) > 1
    ORDER BY RepeatCount DESC, CreatedAt DESC;

    ----------------------------------------------------------------------
    -- SET 7: أبطأ محادثات
    ----------------------------------------------------------------------
    SELECT TOP (@TopN)
        h.ChatId,
        h.CreatedAt,
        h.EntityKey,
        h.Intent,
        h.PageKey,
        h.ResponseTimeMs,
        LEFT(h.UserQuestion, 250) AS Q
    FROM dbo.AiChatHistory h
    WHERE h.CreatedAt BETWEEN @FromDate AND @ToDate
      AND h.ResponseTimeMs IS NOT NULL
    ORDER BY h.ResponseTimeMs DESC;
END
GO
/****** Object:  StoredProcedure [dbo].[sp_AiChat_GetQuestionsNeedingImprovement]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[sp_AiChat_GetQuestionsNeedingImprovement]
    @TopN INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT TOP (@TopN)
        QuestionId,
        Question,
        EntityKey,
        Intent,
        AskCount,
        SuccessRate,
        LastAsked,
        SuggestedAnswer,
        CASE 
            WHEN SuccessRate IS NULL THEN N'لا يوجد تقييم'
            WHEN SuccessRate < 30 THEN N'سيء جداً'
            WHEN SuccessRate < 50 THEN N'ضعيف'
            WHEN SuccessRate < 70 THEN N'متوسط'
            ELSE N'جيد'
        END AS StatusAr
    FROM dbo.AiFrequentQuestions
    WHERE NeedsImprovement = 1
       OR SuccessRate < 50
       OR (AskCount > 5 AND SuggestedAnswer IS NULL)
    ORDER BY 
        AskCount DESC, 
        ISNULL(SuccessRate, 0) ASC;
END;

GO
/****** Object:  StoredProcedure [dbo].[sp_AiChat_GetStatistics]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[sp_AiChat_GetStatistics]
    @FromDate DATETIME2 = NULL,
    @ToDate DATETIME2 = NULL
AS
BEGIN
    SET NOCOUNT ON;
    
    IF @FromDate IS NULL SET @FromDate = DATEADD(DAY, -30, GETDATE());
    IF @ToDate IS NULL SET @ToDate = GETDATE();
    
    -- إجمالي المحادثات
    SELECT 
        COUNT(*) AS TotalChats,
        COUNT(DISTINCT UserId) AS UniqueUsers,
        COUNT(CASE WHEN UserFeedback = 1 THEN 1 END) AS ThumbsUp,
        COUNT(CASE WHEN UserFeedback = -1 THEN 1 END) AS ThumbsDown,
        AVG(ResponseTimeMs) AS AvgResponseTimeMs,
        MAX(ResponseTimeMs) AS MaxResponseTimeMs
    FROM dbo.AiChatHistory
    WHERE CreatedAt BETWEEN @FromDate AND @ToDate;
    
    -- أكثر الـ Entities استخداماً
    SELECT TOP 10
        EntityKey,
        COUNT(*) AS ChatCount,
        AVG(CAST(UserFeedback AS FLOAT)) * 100 AS AvgFeedback
    FROM dbo.AiChatHistory
    WHERE CreatedAt BETWEEN @FromDate AND @ToDate
      AND EntityKey IS NOT NULL
    GROUP BY EntityKey
    ORDER BY ChatCount DESC;
    
    -- أكثر الـ Intents استخداماً
    SELECT TOP 10
        Intent,
        COUNT(*) AS ChatCount,
        AVG(CAST(UserFeedback AS FLOAT)) * 100 AS AvgFeedback
    FROM dbo.AiChatHistory
    WHERE CreatedAt BETWEEN @FromDate AND @ToDate
      AND Intent IS NOT NULL
    GROUP BY Intent
    ORDER BY ChatCount DESC;
END;

GO
/****** Object:  StoredProcedure [dbo].[sp_AiChat_SaveCitation]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[sp_AiChat_SaveCitation]
(
    @ChatId        bigint,
    @Source        nvarchar(500),
    @TextSnippet   nvarchar(max) = NULL,
    @RelevanceScore float = NULL,
    @UsedInAnswer  bit = 1
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        IF @ChatId IS NULL OR @ChatId <= 0
            THROW 50001, N'ChatId غير صحيح', 1;

        IF NOT EXISTS (SELECT 1 FROM dbo.AiChatHistory WHERE ChatId = @ChatId)
            THROW 50001, N'ChatId غير موجود في AiChatHistory', 1;

        IF NULLIF(LTRIM(RTRIM(@Source)), N'') IS NULL
            THROW 50001, N'Source مطلوب', 1;

        INSERT INTO dbo.AiChatCitations (ChatId, Source, TextSnippet, RelevanceScore, UsedInAnswer)
        VALUES (@ChatId, @Source, @TextSnippet, @RelevanceScore, @UsedInAnswer);

        SELECT
            CAST(1 AS bit) AS Success,
            N'تم حفظ الاقتباس' AS Message,
            SCOPE_IDENTITY() AS CitationId,
            @ChatId AS ChatId,
            @Source AS Source;
    END TRY
    BEGIN CATCH
        SELECT CAST(0 AS bit) AS Success, ERROR_MESSAGE() AS Message;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[sp_AiChat_SaveFeedback]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[sp_AiChat_SaveFeedback]
(
    @ChatId          BIGINT,
    @UserFeedback    INT,                 -- 1 أو -1
    @FeedbackComment NVARCHAR(2000) = NULL,
    @UsersId         NVARCHAR(50) = NULL   -- اختياري
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- تحقق أن الشات موجود في AiChatHistory (الجدول الصحيح)
    IF NOT EXISTS (SELECT 1 FROM dbo.AiChatHistory WHERE ChatId = @ChatId)
    BEGIN
        SELECT CAST(0 AS bit) AS IsSuccessful, N'ChatId غير موجود في AiChatHistory' AS Message_;
        RETURN;
    END

    DECLARE @IsHelpful BIT = CASE WHEN @UserFeedback = 1 THEN 1 ELSE 0 END;

    BEGIN TRY
        BEGIN TRAN;

        -- ✅ حدّث سجل المحادثة نفسه (عشان يظهر التقييم في نفس الجدول)
        UPDATE dbo.AiChatHistory
        SET
            UserFeedback    = @UserFeedback,
            FeedbackComment = @FeedbackComment,
            FeedbackDate    = SYSUTCDATETIME()
        WHERE ChatId = @ChatId;

        -- ✅ (اختياري) خزّن سجل تفصيلي في جدول AiChatFeedback
        INSERT INTO dbo.AiChatFeedback
        (
            AiChatLogId,     -- عندك مربوط FK على AiChatHistory(ChatId) (رغم الاسم)
            AtUtc,
            UsersId,
            IsHelpful,
            Comment
        )
        VALUES
        (
            @ChatId,
            SYSUTCDATETIME(),
            @UsersId,
            @IsHelpful,
            LEFT(@FeedbackComment, 500)
        );

        COMMIT;

        SELECT CAST(1 AS bit) AS IsSuccessful, N'تم حفظ التقييم' AS Message_, @ChatId AS ChatId;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK;
        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[sp_AiChat_SaveHistory]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[sp_AiChat_SaveHistory]
    @UserId INT = NULL,
    @UserQuestion NVARCHAR(MAX),
    @AiAnswer NVARCHAR(MAX),
    @PageKey NVARCHAR(100) = NULL,
    @PageTitle NVARCHAR(200) = NULL,
    @PageUrl NVARCHAR(500) = NULL,
    @EntityKey NVARCHAR(100) = NULL,
    @Intent NVARCHAR(50) = NULL,
    @ResponseTimeMs INT = NULL,
    @CitationsCount INT = NULL,
    @IpAddress NVARCHAR(50) = NULL,
    @idaraID NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;
    DECLARE @StartedTran BIT = 0;
    DECLARE @NewID BIGINT = NULL;

    BEGIN TRY
        -- (اختياري) تحقق أعمال بسيط
  
        -- Transaction-safe
        IF @tc = 0
        BEGIN
            BEGIN TRAN;
            SET @StartedTran = 1;
        END

        INSERT INTO dbo.AiChatHistory
        (
            UserId, UserQuestion, AiAnswer, PageKey, PageTitle, PageUrl,
            EntityKey, Intent, ResponseTimeMs, CitationsCount, IpAddress,IdaraID
        )
        VALUES
        (
            @UserId, @UserQuestion, @AiAnswer, @PageKey, @PageTitle, @PageUrl,
            @EntityKey, @Intent, @ResponseTimeMs, @CitationsCount, @IpAddress,@idaraID
        );

        SET @NewID = CAST(SCOPE_IDENTITY() AS BIGINT);


          BEGIN TRY
            EXEC dbo.sp_AiChat_UpdateFrequentQuestions @ChatId = @NewID;
        END TRY
        BEGIN CATCH
            -- لا نوقف حفظ المحادثة إذا فشل تحديث الأسئلة الشائعة
            -- (اختياري) سجل الخطأ في جدول ErrorLog عندك
        END CATCH


        IF @StartedTran = 1
            COMMIT;

        SELECT
            1 AS IsSuccessful,
            N'تم اضافة البيانات بنجاح' AS Message_,
            @NewID AS ChatId;
    END TRY
    BEGIN CATCH
        IF @StartedTran = 1 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[sp_AiChat_UpdateFrequentQuestions]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- 3) عدّل SP تحديث الأسئلة الشائعة (نفس المشكلة)
CREATE   PROCEDURE [dbo].[sp_AiChat_UpdateFrequentQuestions]
    @ChatId BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Question NVARCHAR(500);
    DECLARE @NormalizedQ NVARCHAR(500);
    DECLARE @EntityKey NVARCHAR(100);
    DECLARE @Intent NVARCHAR(50);
    DECLARE @Feedback SMALLINT;

    SELECT 
        @Question = SUBSTRING(UserQuestion, 1, 500),
        @EntityKey = EntityKey,
        @Intent = Intent,
        @Feedback = UserFeedback
    FROM dbo.AiChatHistory
    WHERE ChatId = @ChatId;

    IF @Question IS NULL RETURN;

    SET @NormalizedQ = LOWER(LTRIM(RTRIM(@Question)));
    SET @NormalizedQ = REPLACE(@NormalizedQ, N'؟', N'');
    SET @NormalizedQ = REPLACE(@NormalizedQ, N'?', N'');

    IF EXISTS (SELECT 1 FROM dbo.AiFrequentQuestions WHERE NormalizedQuestion = @NormalizedQ)
    BEGIN
        UPDATE dbo.AiFrequentQuestions
        SET AskCount = AskCount + 1,
            LastAsked = GETDATE(),
            SuccessRate = (
                SELECT AVG(CAST(UserFeedback AS FLOAT)) * 100
                FROM dbo.AiChatHistory
                WHERE LOWER(REPLACE(REPLACE(SUBSTRING(UserQuestion, 1, 500), N'؟', N''), N'?', N'')) = @NormalizedQ
                  AND UserFeedback IS NOT NULL
            ),
            NeedsImprovement = CASE WHEN @Feedback = -1 THEN 1 ELSE NeedsImprovement END
        WHERE NormalizedQuestion = @NormalizedQ;
    END
    ELSE
    BEGIN
        INSERT dbo.AiFrequentQuestions (Question, NormalizedQuestion, EntityKey, Intent, AskCount, LastAsked)
        VALUES (@Question, @NormalizedQ, @EntityKey, @Intent, 1, GETDATE());
    END
END;
GO
