                ;THROW 50001, N'صيغة تاريخ الميلاد غير صحيحة. استخدم YYYY-MM-DD', 1;
            END


            IF NULLIF(LTRIM(RTRIM(@NationalID)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'رقم الهوية مطلوب', 1;
        END

                      IF NULLIF(LTRIM(RTRIM(@GeneralNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'الرقم العام مطلوب', 1;
            END




         IF (select count(*) 
                from dbo.Users ri
                where ri.usersActive = 1 AND RI.nationalID = @nationalID AND RI.usersID <> @usersID
                ) > 0
        BEGIN
            ;THROW 50001, N'رقم الهوية مستخدم مسبقا', 1;
        END


          IF (select count(*) 
                from dbo.Users ri
                inner join dbo.UsersDetails rd on ri.usersID = rd.usersID_FK
                where ri.usersActive = 1 and rd.userActive = 1 and rd.GeneralNo = @generalNo AND RI.usersID <> @usersID
                ) > 0
        BEGIN
            ;THROW 50001, N'الرقم العام مستخدم مسبقا', 1;
        END


        if(@nationalityID_FK_INT = 1)
        Begin
        IF TRY_CONVERT(BIGINT, @NationalID) IS NULL
        BEGIN
            ;THROW 50001, N'رقم الهوية الوطنية يجب أن يكون أرقام فقط', 1;
        END

        IF LEN(@NationalID) <> 10
        BEGIN
            ;THROW 50001, N'رقم الهوية الوطنية يجب أن يكون 10 أرقام', 1;
        END
        
        IF LEFT(@NationalID, 1) <> N'1'
        BEGIN
            ;THROW 50001, N'رقم الهوية الوطنية يجب أن يبدأ بالرقم 1', 1;
        END
        END



         IF (
            (NULLIF(LTRIM(RTRIM(@firstName_A)), N'') IS NULL) 
         OR (NULLIF(LTRIM(RTRIM(@secondName_A)), N'') IS NULL)
         OR (NULLIF(LTRIM(RTRIM(@thirdName_A)), N'') IS NULL)
         OR (NULLIF(LTRIM(RTRIM(@lastName_A)), N'') IS NULL)
         )
        BEGIN
            ;THROW 50001, N'الاسم العربي الرباعي مطلوب', 1;
        END





              IF NULLIF(LTRIM(RTRIM(@UsersAuthTypeID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'نوع الصلاحية مطلوب', 1;
            END




              IF NULLIF(LTRIM(RTRIM(@userTypeID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'نوع المستخدم مطلوب', 1;
            END

              IF NULLIF(LTRIM(RTRIM(@IdaraID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'اسم الادارة مطلوب', 1;
            END

              IF NULLIF(LTRIM(RTRIM(@nationalIDIssueDate)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'تاريخ اصدار الهوية مطلوب', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@dateOfBirth)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'تاريخ الميلاد مطلوب', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@genderID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'نوع الجنس مطلوب', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@religionID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'نوع الديانة مطلوب', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@maritalStatusID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'نوع الحالة الاجتماعية مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@educationID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'نوع الدرجة العلمية مطلوب', 1;
            END



            UPDATE  dbo.Users SET 
            
                  usersActive = 0,
                  updatedby = updatedby +','+cast(@entryData as nvarchar),
                  updatedDate = updatedDate+','+cast(GETDATE() as nvarchar)

                  where usersID = @usersID
               

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تعطيل المستفيد', 1; -- برمجي
            END
           
            SET @Note = N'{'
                + N'"usersID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @usersID), '') + N'"'
                + N'"nationalID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @nationalID), '') + N'"'
                + N',"nationalIDTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"usersStartDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), GETDATE(),23), '') + N'"'
                + N',"usersActive": "1"'
                + N',"entryData": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                 + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[dbo].[UsersSP]'
                , N'DELETEUSERS'
                , ISNULL(@usersID, 0)
                , @entryData
                , @Note
            );






            
            UPDATE  dbo.UsersDetails SET 
            
                  userActive = 0,UDendDate = GETDATE(),canceldBy = cast(@entryData as nvarchar(50))+','+convert(nvarchar(10),GETDATE(),23),userNote =  N' تم التعطيل بسبب : ' +@userNote
                  where usersID_FK = @usersID
               

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تعطيل المستفيد', 1; -- برمجي
            END


            DECLARE @NewID3 BIGINT,@Note3 NVARCHAR(MAX)
            SET @NewID3 = SCOPE_IDENTITY();
            IF @NewID3 IS NULL OR @NewID1 <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تعطيل البيانات - NewID2', 1; -- برمجي
            END
            SET @Note3 = N'{'
                + N'"usersID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"GeneralNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"userTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @userTypeID_FK), '') + N'"'
                + N',"firstName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @firstName_A), '') + N'"'
                + N',"secondName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @secondName_A), '') + N'"'
                + N',"thirdName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @thirdName_A), '') + N'"'
                + N',"forthName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @forthName_A), '') + N'"'
                + N',"lastName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @lastName_A), '') + N'"'
                + N',"firstName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @firstName_E), '') + N'"'
                + N',"secondName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @secondName_E), '') + N'"'
                + N',"thirdName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @thirdName_E), '') + N'"'
                + N',"forthName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @forthName_E), '') + N'"'
                + N',"lastName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @lastName_E), '') + N'"'
                + N',"nationalIDIssueDate": "' + ISNULL(CONVERT(NVARCHAR(MAX), @nationalIDIssueDate), '') + N'"'
                + N',"dateOfBirth": "' + ISNULL(CONVERT(NVARCHAR(MAX), @dateOfBirth), '') + N'"'
                + N',"genderID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @genderID_FK), '') + N'"'
                + N',"nationalityID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @nationalityID_FK), '') + N'"'
                + N',"religionID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @religionID_FK), '') + N'"'
                + N',"maritalStatusID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @maritalStatusID_FK), '') + N'"'
                + N',"educationID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @educationID_FK), '') + N'"'
                + N',"userActive": "1"'
                + N',"userNote": "' + ISNULL(CONVERT(NVARCHAR(MAX), @userNote), '') + N'"'
                + N',"usersAuthTypeID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @UsersAuthTypeID), '') + N'"'
                + N',"IdaraID": "'               + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                 + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[dbo].[UsersSP]'
                , N'DELETEUSERS'
                , ISNULL(@NewID3, 0)
                , @entryData
                , @Note3
            );




             UPDATE ud
                SET ud.UDActive = 0,ud.UDEndDate = GETDATE(),ud.CanceldBy = cast(@entryData as nvarchar(50))+','+convert(nvarchar(10),GETDATE(),23)
                FROM dbo.Distributor d
                INNER JOIN dbo.UserDistributor ud 
                    ON ud.distributorID_FK = d.distributorID
                   AND d.distributorType_FK = 1
                WHERE ud.userID_FK = @usersID;


            SELECT 1 AS IsSuccessful, N'تم تعطيل المستخدم بنجاح' AS Message_;
            RETURN;
        END


        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Demo].[usp_Demo_Pie3D_Units]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   4) Stored Procedure (ترجع DataSet  )
========================================================= */
CREATE   PROCEDURE [Demo].[usp_Demo_Pie3D_Units]
(
    @PageName NVARCHAR(100),
    @IdaraId  INT,
    @UserId   INT,
    @HostName NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    /* ---------- Table (0): Permissions ---------- */
    SELECT permissionTypeName_E
    FROM (VALUES
        (N'INSERT'),
        (N'UPDATE'),
        (N'DELETE')
    ) AS P(permissionTypeName_E);

    /* ---------- Table (1): Pie3D Data ---------- */
    SELECT
        SegmentKey     AS [Key],
        SegmentLabel_A AS [Label],
        SegmentValue   AS [Value],
        SegmentHref    AS [Href],
        SegmentHint    AS [Hint]
    FROM Demo.Demo_Pie3D_UnitDistribution
    WHERE IsActive = 1
      AND (@IdaraId IS NULL OR IdaraId_FK IS NULL OR IdaraId_FK = @IdaraId)
    ORDER BY SortOrder;
END
GO
/****** Object:  StoredProcedure [Housing].[AllMeterReadDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[AllMeterReadDL]
      @pageName_              NVARCHAR(400)
    , @idaraID                INT
    , @entrydata              INT
    , @hostname               NVARCHAR(400)
    , @meterServiceTypeID_FK  INT
AS
BEGIN
    SET NOCOUNT ON;

    ----------------------------------------------------------------
    -- 0) Vars + Dates
    ----------------------------------------------------------------
    DECLARE
        @AllmeterReaded   INT = 0,
        @AllMetersCount   INT = 0,
        @CurrentPeriodID  INT = NULL;

    DECLARE
        @MonthStart DATE = DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1),
        @MonthEnd   DATE = EOMONTH(GETDATE());

    ----------------------------------------------------------------
    -- 1) Current Period (آخر فترة فعّالة لنوع الخدمة والإدارة)
    ----------------------------------------------------------------
    SELECT @CurrentPeriodID = COALESCE(MAX(bp.billPeriodID), -1)
        FROM  Housing.BillPeriod bp
        JOIN  Housing.BillPeriodType bpt
          ON bp.billPeriodTypeID_FK = bpt.billPeriodTypeID
        WHERE bpt.meterServiceTypeID_FK = @meterServiceTypeID_FK
          AND bp.IdaraId_FK = @idaraID
          AND bpt.billPeriodTypeActive = 1
          AND bp.billPeriodActive = 1;

    ----------------------------------------------------------------
    -- 2) Eligible Meters (Cache once)
    --    Best practice: TVF as source + #temp as cache for reuse
    ----------------------------------------------------------------
    IF OBJECT_ID('tempdb..#EligibleMeters') IS NOT NULL
        DROP TABLE #EligibleMeters;

    SELECT
        em.meterID,
        em.meterNo,
        em.meterServiceTypeID_FK
    INTO #EligibleMeters
    FROM Housing.FN_EligibleMeters(@idaraID, @MonthStart, @MonthEnd) em
    WHERE em.meterServiceTypeID_FK = @meterServiceTypeID_FK; -- مهم لتخفيف النتائج

    -- فهرس: نحتاج meterID للـ joins/exists + meterNo للـ order + meterServiceTypeID_FK للفلترة
    CREATE UNIQUE CLUSTERED INDEX IX_EligibleMeters ON #EligibleMeters(meterID);
    CREATE NONCLUSTERED INDEX IX_EligibleMeters_No ON #EligibleMeters(meterNo) INCLUDE (meterServiceTypeID_FK);

    ----------------------------------------------------------------
    -- 3) Counts
    ----------------------------------------------------------------
    SELECT @AllMetersCount = COUNT(*) FROM #EligibleMeters;

   SELECT @AllmeterReaded = COUNT(*)
    FROM #EligibleMeters em
    WHERE EXISTS
    (
        SELECT 1
        FROM  Housing.Bills b
        WHERE b.meterID = em.meterID
          AND b.meterServiceTypeID = @meterServiceTypeID_FK
          AND b.idaraID_FK = @idaraID
          AND b.BillActive = 1
          AND b.BillTypeID_FK = 2
          AND b.CurrentPeriodID = @CurrentPeriodID
    );

    ----------------------------------------------------------------
    -- RESULTSET (1) Periods + Counts
    ----------------------------------------------------------------
    SELECT
          bp.[billPeriodID]
        , bp.[billPeriodTypeID_FK]
        , bpt.billPeriodTypeName_A
        , bp.[billPeriodName_A]
        , bp.[billPeriodName_E]
        , DATEPART(YEAR, bp.[billPeriodStartDate]) AS billPeriodYear
        , CONVERT(NVARCHAR(10), bp.[billPeriodStartDate], 23) AS billPeriodStartDate
        , CONVERT(NVARCHAR(10), bp.[billPeriodEndDate], 23)   AS billPeriodEndDate
        , bp.[billPeriodActive]
        , bp.[ClosedBy]
        , bp.[IdaraId_FK]
        , @AllMetersCount AS AllMetersCount
        , @AllmeterReaded AS AllmeterReaded
        , (@AllMetersCount - @AllmeterReaded) AS AllMeterNotReaded
    FROM  Housing.BillPeriod bp
    INNER JOIN  Housing.BillPeriodType bpt
        ON bp.billPeriodTypeID_FK = bpt.billPeriodTypeID
    WHERE bpt.meterServiceTypeID_FK = @meterServiceTypeID_FK
      AND bp.IdaraId_FK = @idaraID
      AND bpt.billPeriodTypeActive = 1
      AND bp.billPeriodActive = 1;

    ----------------------------------------------------------------
    -- RESULTSET (2) Bills for Current Period
    ----------------------------------------------------------------
    IF @CurrentPeriodID IS NULL
    BEGIN
        SELECT TOP (0)
              b.[BillsID], b.[BillNumber], b.[PeriodMonth], b.[PeriodYear]
            , b.[meterNo], b.[meterID], b.[meterName_A]
            , b.[buildingDetailsNo], b.[buildingDetailsID]
            , b.[meterReadID], b.[CurrentRead], b.[LastRead], b.[ReadDiff]
            , b.[PriceForSlide1], b.[PriceForSlide2], b.[PriceForSlide3], b.[PriceForSlide4], b.[PriceForSlide5]
            , b.[PriceForSlide6], b.[PriceForSlide7], b.[PriceForSlide8], b.[PriceForSlide9], b.[PriceForSlide10]
            , b.[PRICE], b.[PRICETAX], b.[meterServicePrice], b.[meterServicePriceTAX]
            , (b.[meterServicePrice] + b.[meterServicePriceTAX]) AS meterServicePriceWithTAX
            , b.[TotalPrice]
            , CAST(0 AS DECIMAL(18,2)) AS previosBillTotalPrice
            , CAST(N'' AS NVARCHAR(200)) AS avrageMsg
            , CAST(N'' AS NVARCHAR(10))  AS avrageNo
            , b.[idaraID_FK]
            , CAST(N'' AS NVARCHAR(30)) AS entryDate
            , b.[entryData]
        FROM  Housing.Bills b
        WHERE 1 = 0;
    END
    ELSE
    BEGIN
        SELECT
              b.[BillsID]
            , b.[BillNumber]
            , b.[PeriodMonth]
            , b.[PeriodYear]
            , b.[meterNo]
            , b.[meterID]
            , b.[meterName_A]
            , b.[buildingDetailsNo]
            , b.[buildingDetailsID]
            , b.[meterReadID]
            , b.[CurrentRead]
            , b.[LastRead]
            , b.[ReadDiff]
            , b.[PriceForSlide1]
            , b.[PriceForSlide2]
            , b.[PriceForSlide3]
            , b.[PriceForSlide4]
            , b.[PriceForSlide5]
            , b.[PriceForSlide6]
            , b.[PriceForSlide7]
            , b.[PriceForSlide8]
            , b.[PriceForSlide9]
            , b.[PriceForSlide10]
            , b.[PRICE]
            , b.[PRICETAX]
            , b.[meterServicePrice]
            , b.[meterServicePriceTAX]
            , (b.[meterServicePrice] + b.[meterServicePriceTAX]) AS meterServicePriceWithTAX
            , b.[TotalPrice]
            , ISNULL(rp.TotalPrice, 0) AS previosBillTotalPrice

            , CASE
                WHEN ISNULL(rp.TotalPrice,0) = 0 THEN N'لا يوجد متوسط للساكن'
                WHEN b.TotalPrice >= ISNULL(rp.TotalPrice,0) * 2.00 THEN N'ارتفاع عالي جداً 🔺🔺'
                WHEN b.TotalPrice >= ISNULL(rp.TotalPrice,0) * 1.75 THEN N'ارتفاع عالي 🔺'
                WHEN b.TotalPrice >= ISNULL(rp.TotalPrice,0) * 1.50 THEN N'ارتفاع متوسط 📈'
                WHEN b.TotalPrice >= ISNULL(rp.TotalPrice,0) * 1.25 THEN N'ارتفاع خفيف 📈'
                WHEN b.TotalPrice <= ISNULL(rp.TotalPrice,0) * 0.00 THEN N'انخفاض عالي 🔻🔻'
                WHEN b.TotalPrice <= ISNULL(rp.TotalPrice,0) * 0.25 THEN N'انخفاض عالي 🔻'
                WHEN b.TotalPrice <= ISNULL(rp.TotalPrice,0) * 0.50 THEN N'انخفاض متوسط 📉'
                WHEN b.TotalPrice <= ISNULL(rp.TotalPrice,0) * 0.75 THEN N'انخفاض خفيف 📉'
                ELSE N'في الوضع الطبيعي'
              END AS avrageMsg

            , CASE
                WHEN ISNULL(rp.TotalPrice,0) = 0 THEN N'0'
                WHEN b.TotalPrice >= ISNULL(rp.TotalPrice,0) * 2.00 THEN N'5'
                WHEN b.TotalPrice >= ISNULL(rp.TotalPrice,0) * 1.75 THEN N'1'
                WHEN b.TotalPrice >= ISNULL(rp.TotalPrice,0) * 1.50 THEN N'2'
                WHEN b.TotalPrice >= ISNULL(rp.TotalPrice,0) * 1.25 THEN N'2'
                WHEN b.TotalPrice <= ISNULL(rp.TotalPrice,0) * 0.00 THEN N'6'
                WHEN b.TotalPrice <= ISNULL(rp.TotalPrice,0) * 0.25 THEN N'1'
                WHEN b.TotalPrice <= ISNULL(rp.TotalPrice,0) * 0.50 THEN N'2'
                WHEN b.TotalPrice <= ISNULL(rp.TotalPrice,0) * 0.75 THEN N'2'
                ELSE N'3'
              END AS avrageNo

            , b.[idaraID_FK]
            , CONVERT(NVARCHAR(10), b.[entryDate], 23) + N' ' + CONVERT(NVARCHAR(8), b.[entryDate], 108) AS entryDate
            , b.[entryData]
        FROM #EligibleMeters em
        INNER JOIN  Housing.Bills b
            ON b.meterID = em.meterID
           AND b.meterServiceTypeID = @meterServiceTypeID_FK
           AND b.idaraID_FK = @idaraID
           AND b.BillActive = 1
           AND b.BillTypeID_FK = 2
           AND b.CurrentPeriodID = @CurrentPeriodID
        OUTER APPLY (
            SELECT TOP (1) p.TotalPrice
            FROM  Housing.Bills p
            WHERE p.BillActive = 1
              AND p.BillTypeID_FK = 2
              AND p.residentInfoID_FK = b.residentInfoID_FK
              AND p.meterServiceTypeID = b.meterServiceTypeID
              AND p.BillsID <> b.BillsID
            ORDER BY
                ISNULL(p.PeriodYear, 0) DESC,
                ISNULL(p.PeriodMonth, 0) DESC,
                ISNULL(p.CurrentPeriodID, 0) DESC,
                p.BillsID DESC
        ) rp
        ORDER BY b.BillsID DESC;
    END

    ----------------------------------------------------------------
    -- RESULTSET (3) MeterServiceType Options (SARGable + idara)
    ----------------------------------------------------------------
    SELECT
          mst.meterServiceTypeID
        , mst.meterServiceTypeName_A
        , mst.BillChargeTypeID_FK
    FROM Housing.MeterServiceType mst
    INNER JOIN Housing.MeterServiceTypeLinkedWithIdara mi
        ON mst.meterServiceTypeID = mi.MeterServiceTypeID_FK
    WHERE mst.meterServiceTypeActive = 1
      AND mi.MeterServiceTypeLinkedWithIdaraActive = 1
      AND mi.Idara_FK = @idaraID
      AND mst.meterServiceTypeStartDate <= @MonthEnd
      AND (mst.meterServiceTypeEndDate IS NULL OR mst.meterServiceTypeEndDate >= @MonthStart)
      AND mi.MeterServiceTypeLinkedWithIdaraStartDate <= @MonthEnd
      AND (mi.MeterServiceTypeLinkedWithIdaraEndDate IS NULL OR mi.MeterServiceTypeLinkedWithIdaraEndDate >= @MonthStart)
    ORDER BY mst.meterServiceTypeName_A;

    ----------------------------------------------------------------
    -- RESULTSET (4) Meters WITHOUT bills in current period (DDL)
    ----------------------------------------------------------------
    if(@CurrentPeriodID = -1)
    BEGIN

    SELECT em.meterID, em.meterNo
            FROM #EligibleMeters em
            LEFT JOIN  Housing.Bills b
              ON  b.meterID = em.meterID
              AND b.meterServiceTypeID = @meterServiceTypeID_FK
              AND b.idaraID_FK = @idaraID
              AND b.BillActive = 1
              AND b.BillTypeID_FK = 2
              AND b.CurrentPeriodID = @CurrentPeriodID
            WHERE b.meterID IS not NULL
            ORDER BY em.meterNo;

    END
    ELSE
    BEGIN
    SELECT em.meterID, em.meterNo,em.meterServiceTypeID_FK
            FROM #EligibleMeters em
            LEFT JOIN  Housing.Bills b
              ON  b.meterID = em.meterID
              AND b.meterServiceTypeID = @meterServiceTypeID_FK
              AND b.idaraID_FK = @idaraID
              AND b.BillActive = 1
              AND b.BillTypeID_FK = 2
              AND b.CurrentPeriodID = @CurrentPeriodID
            WHERE b.meterID IS NULL
            ORDER BY em.meterNo;

    END
        
    
END
GO
/****** Object:  StoredProcedure [Housing].[AllMeterReadSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
