         ----------------------------------------------------------------
        -- EDIT
        ----------------------------------------------------------------
         ELSE IF @Action in(N'DELETEELECTRICITYMETER',N'DELETEWATERMETER',N'DELETEGASMETER')
         BEGIN

            IF @BillsID IS NULL 
            BEGIN
                ;THROW 50001, N'رقم الفاتورة مطلوب', 1;
            END

            IF @MeterReadID IS NULL 
            BEGIN
                ;THROW 50001, N'رقم القراءة مطلوب', 1;
            END

            IF @MeterReadValue IS NULL 
            BEGIN
                ;THROW 50001, N'قيمة القراءة الجديدة مطلوبة', 1;
            END

            IF NOT EXISTS
            (
                SELECT 1
                FROM Housing.MeterServiceType mst
                INNER JOIN Housing.MeterServiceTypeLinkedWithIdara msl
                    ON mst.meterServiceTypeID = msl.meterServiceTypeID_FK
                WHERE mst.meterServiceTypeActive = 1
                  AND msl.MeterServiceTypeLinkedWithIdaraActive = 1
                  AND msl.Idara_FK = @IdaraId_FK
                  AND msl.MeterServiceTypeID_FK = @MeterServiceTypeID
            )
            BEGIN
                ;THROW 50001, N'هذه الخدمة غير متوفرة في ادارتك حاليا', 1;
            END

            ----------------------------------------------------------------
            -- Load old bill
            ----------------------------------------------------------------

          
         
          
            IF NOT EXISTS
            (
                SELECT 1
                FROM Housing.BillPeriod bp
                INNER JOIN Housing.BillPeriodType bpt
                    ON bp.billPeriodTypeID_FK = bpt.billPeriodTypeID
                WHERE bp.billPeriodActive = 1
                  AND bpt.billPeriodTypeActive = 1
                  AND bp.IdaraId_FK = @IdaraID_INT
                  AND bpt.meterServiceTypeID_FK = @MeterServiceTypeID
                  AND bp.billPeriodID = @billPeriodID
            )
            BEGIN
                ;THROW 50001, N'الفترة المرتبطة بهذه القراءة ليست نشطة حاليا', 1;
            END

         
            ----------------------------------------------------------------
            -- Disable old bill
            ----------------------------------------------------------------
            UPDATE Housing.Bills
               SET BillActive = 0
             WHERE BillsID = @billsID
               AND BillActive = 1;

            SET @Identity_Update1 = @@ROWCOUNT;

            IF @Identity_Update1 IS NULL 
            BEGIN
                ;THROW 50002, N'حصل خطأ في حذف الفاتورة ', 1;
            END

            SET @Note = N'{'
                + N'"BillsID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @BillsID), N'') + N'"'
                + N',"meterReadID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @MeterReadID), N'') + N'"'
                + N',"meterID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @MeterID), N'') + N'"'
                + N',"CurrentPeriodID": "' + ISNULL(CONVERT(NVARCHAR(MAX),@billPeriodID ), N'') + N'"'
                + N',"NewReadValue": "' + ISNULL(CONVERT(NVARCHAR(MAX), @MeterReadValue), N'') + N'"'
                + N',"BillActive": "0"'
                + N',"IdaraId_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_INT), N'') + N'"'
                + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), N'') + N'"'
                + N',"entryDate": "' + CONVERT(NVARCHAR(19), GETDATE(), 120) + N'"'
                + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), N'') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[Bills]'
                , @Action
                , @BillsID
                , @entryData
                , @Note
            );

            ----------------------------------------------------------------
            -- Disable old meter read
            ----------------------------------------------------------------
            UPDATE Housing.MeterRead
               SET meterReadActive = 0
             WHERE meterReadID = @MeterReadID
               AND meterReadActive = 1;

            SET @Identity_Update2 = @@ROWCOUNT;

            IF @Identity_Update2 IS NULL 
            BEGIN
                ;THROW 50002, N'حصل خطأ في حذف الفاتورة ', 1;
            END

            SET @Note1 = N'{'
                + N'"meterReadID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @MeterReadID), N'') + N'"'
                + N',"BillsID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @BillsID), N'') + N'"'
                + N',"meterID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @MeterID), N'') + N'"'
                + N',"billPeriodID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @billPeriodID), N'') + N'"'
                + N',"residentInfoID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @ResidentInfoID), N'') + N'"'
                + N',"generalNo_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), N'') + N'"'
                + N',"buildingDetailsID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @BuildingDetailsID), N'') + N'"'
                + N',"buildingDetailsNo": "' + ISNULL(CONVERT(NVARCHAR(MAX), @BuildingDetailsNo), N'') + N'"'
                + N',"NewReadValue": "' + ISNULL(CONVERT(NVARCHAR(MAX), @MeterReadValue), N'') + N'"'
                + N',"meterReadActive": "0"'
                + N',"IdaraID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_INT), N'') + N'"'
                + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), N'') + N'"'
                + N',"entryDate": "' + CONVERT(NVARCHAR(19), GETDATE(), 120) + N'"'
                + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), N'') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[MeterRead]'
                , @Action
                , @MeterReadID
                , @entryData
                , @Note1
            );


            SELECT 1 AS IsSuccessful, N'تم حذف القراءة بنجاح وتعطيل الفاتورة السابقة بنجاح' AS Message_;
            RETURN;

         END


      

        

         ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[AssignDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[AssignDL] 
	-- Add the parameters for the stored procedure here
	  @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
	,@WaitingClassID  INT
    ,@AssignPeriodID  bigint
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   
  -- Assign Data

          
   ;WITH CurrentAssignPeriod AS
(
    SELECT TOP (1) a.AssignPeriodID
    FROM Housing.AssignPeriod a
    WHERE a.AssignPeriodActive = 1
      AND a.AssignPeriodClose = 1
      AND a.AssignPeriodStartdate IS NOT NULL
      AND (a.AssignPeriodEnddate IS NULL OR a.AssignPeriodEnddate > CAST(GETDATE() AS date))
      AND a.WaitingClassID_FK = @WaitingClassID
    ORDER BY a.AssignPeriodID DESC
)
SELECT 
    w.ActionID,
    ROW_NUMBER() OVER (
        ORDER BY w.ActionDecisionDate ASC, w.GeneralNo ASC
    ) AS WaitingListOrder,
    rd.FullName_A,
    w.NationalID,
    w.GeneralNo,
    w.ActionDecisionNo,
    CONVERT(nvarchar(10), w.ActionDecisionDate, 23) AS ActionDecisionDate,
    w.WaitingClassID,
    w.WaitingClassName,
    w.WaitingOrderTypeID,
    w.WaitingOrderTypeName,
    w.waitingClassSequence,
    w.residentInfoID,
    w.LastActionTypeID,
    w.LastActionID,
    ba.buildingActionTypeResidentAlias,
    w.buildingDetailsID,
    w.buildingDetailsNo,
    ISNULL(w.LastActionNote, w.ActionNote) AS ActionNote,
    w.IdaraId,
    ISNULL(cap.AssignPeriodID, 0) AS AssignPeriodID,
    CASE 
        WHEN w.LastActionTypeID IN (38,40) THEN N'1'
        ELSE N'0'
    END AS AssignStatus
FROM Housing.V_WaitingList w
INNER JOIN Housing.V_GetFullResidentDetails rd 
    ON w.residentInfoID = rd.residentInfoID
INNER JOIN Housing.BuildingActionType ba 
    ON w.LastActionTypeID = ba.buildingActionTypeID
OUTER APPLY
(
    SELECT AssignPeriodID
    FROM CurrentAssignPeriod
) cap
WHERE w.WaitingClassID = @WaitingClassID
  AND w.IdaraId = @idaraID
  AND w.LastActionTypeID IN (27,39,41);

  --AND w.LastActionTypeID IN (27,38,39,40,41,42);

      --or w.LastActionTypeID in (2,3,18,19,20,21,22,23,24,26,27,28,33,34,35)




     -- WaitingClass DDL
            SELECT 
            c.waitingClassID
            ,c.waitingClassName_A
            FROM [DATACORE].[Housing].[WaitingClass] c
            where (c.idara_FK is null)

            order by c.waitingClassSequence asc


            -- SELECT 
            --cast(c.waitingClassID as nvarchar(20))+','+cast(isnull(a.AssignPeriodID,0) as nvarchar(20)) as waitingClassID
            --,c.waitingClassName_A
            --FROM [DATACORE].[Housing].[WaitingClass] c
            --left join Housing.AssignPeriod a on c.WaitingClassID = a.WaitingClassID_FK 
            --and a.AssignPeriodActive = 1 and a.AssignPeriodClose = 1 
            --and a.AssignPeriodStartdate is not null 
            --and (a.AssignPeriodEnddate is null or cast(a.AssignPeriodEnddate as date) > cast(GETDATE() as date)) 
            --and a.IdaraId_FK = 1
            --where (c.idara_FK is null)

            --order by c.waitingClassSequence asc


     --AssignPeriod
   
            select 
             a.AssignPeriodID
            ,a.[AssignPeriodDescrption]
            ,convert(nvarchar(10),a.[AssignPeriodStartdate],111)+' '+convert(nvarchar,a.[AssignPeriodStartdate],108) AssignPeriodStartdate
            ,a.[AssignPeriodEnddate]
            ,a.[AssignPeriodActive]
            ,a.[IdaraId_FK]
            ,a.[entryDate]
            ,a.[entryData]
            ,a.[hostName]
            ,f.FullName
            ,w.waitingClassName_A
            
            from Housing.AssignPeriod a
            inner join dbo.V_GetFullSystemUsersDetails f on a.entryData = f.usersID
            left join Housing.WaitingClass w on a.WaitingClassID_FK = w.WaitingClassID
            where a.AssignPeriodActive = 1 and a.AssignPeriodClose = 1
            and a.AssignPeriodStartdate is not null
            and (a.AssignPeriodEnddate is null or cast(a.AssignPeriodEnddate as date) > cast(GETDATE() as date))
            and a.IdaraId_FK = @idaraID
            and a.WaitingClassID_FK = @WaitingClassID





             -- Houses DDL
            SELECT c.buildingDetailsID,c.buildingDetailsNo
            FROM [DATACORE].[Housing].[V_GetGeneralListForBuilding] c
            where c.BuildingIdaraID = 1 and c.buildingDetailsActive = 1 
            and (c.LastActionTypeID in(5,39,41) or c.LastActionTypeID is null )
            



   
END
GO
/****** Object:  StoredProcedure [Housing].[AssignSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[AssignSP] 
(
      @Action                               NVARCHAR(200)
    , @ActionID                             BIGINT          = NULL
    , @residentInfoID                       NVARCHAR(100)   = NULL
    , @NationalID                           NVARCHAR(100)   = NULL
    , @GeneralNo                            NVARCHAR(100)   = NULL
    , @buildingActionDecisionNo             NVARCHAR(1000)  = NULL
    , @buildingActionDecisionDate           NVARCHAR(1000)  = NULL
    , @WaitingClassID                       NVARCHAR(1000)  = NULL
    , @WaitingClassName                     NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeID                   NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeName                 NVARCHAR(1000)  = NULL
    , @waitingClassSequence                 NVARCHAR(1000)  = NULL
    , @WaitingListOrder                     NVARCHAR(1000)  = NULL
    , @FullName_A                           NVARCHAR(1000)  = NULL
    , @buildingDetailsID                    NVARCHAR(1000)  = NULL
    , @AssignPeriodID                       NVARCHAR(1000)  = NULL
    , @LastActionID                         NVARCHAR(1000)  = NULL
    , @LastActionTypeID                     NVARCHAR(1000)  = NULL
    , @Notes                                NVARCHAR(1000)  = NULL
    , @idaraID_FK                           NVARCHAR(10)    = NULL
    , @entryData                            NVARCHAR(20)    = NULL
    , @hostName                             NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));
    DECLARE @buildingDetailsNo nvarchar(200) 
    set @buildingDetailsNo = (select b.buildingDetailsNo from Housing.V_GetGeneralListForBuilding b where b.buildingDetailsID = @buildingDetailsID);

    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

   


         IF @Action IN(N'OPENASSIGNPERIOD')
        BEGIN
         
            IF NULLIF(LTRIM(RTRIM(@Notes)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يجب كتابة وصف لمحضر التخصيص', 1;
            END

           
        END

        ----------------------------------------------------------------
        -- OPENASSIGNPERIOD
        ----------------------------------------------------------------
        IF @Action = N'OPENASSIGNPERIOD'
        BEGIN


          IF EXISTS
            (
                SELECT 1
                FROM  Housing.AssignPeriod a
                WHERE a.AssignPeriodActive = 1 and a.AssignPeriodClose = 1 and a.WaitingClassID_FK = @WaitingClassID
                  AND a.IdaraId_FK = @IdaraID_INT
            )
            BEGIN
                ;THROW 50001, N'يوجد محضر تخصيص نشط', 1;
            END


            INSERT INTO  Housing.AssignPeriod
            (
                 [AssignPeriodDescrption]
                ,[AssignPeriodStartdate]
                ,[AssignPeriodActive]
                ,[AssignPeriodClose]
                ,[AssignPeriodFinalEND]
                ,[WaitingClassID_FK]
                ,[IdaraId_FK]
                ,[entryData]
                ,[hostName]
            )
            VALUES
            (
                  @Notes
                , GETDATE()
                , 1
                , 1
                , 1
                , @WaitingClassID
                , @IdaraID_INT
                , @entryData
                , @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في انشاء محضر التخصيص', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في انشاء محضر التخصيص - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"AssignPeriodID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"AssignPeriodDescrption": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"AssignPeriodStartdate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), GETDATE()), '') + N'"'
                + N',"AssignPeriodActive": "1"'
                + N',"WaitingClassID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @WaitingClassID), '') + N'"'
                + N',"IdaraId_FK": "'               + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                 + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[AssignPeriod]'
                , N'OPENASSIGNPERIOD'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم انشاء محضر التخصيص بنجاح' AS Message_;
            RETURN;
        END



         ----------------------------------------------------------------
        -- OPENASSIGNPERIOD
        ----------------------------------------------------------------
        ELSE IF @Action = N'CLOSEASSIGNPERIOD'
        BEGIN


          IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.AssignPeriod a
                WHERE a.AssignPeriodActive = 1 and a.AssignPeriodClose = 1 and a.AssignPeriodEnddate is null
                  AND a.IdaraId_FK = @IdaraID_INT
            )
            BEGIN
                ;THROW 50001, N'لا يوجد محضر تخصيص نشط', 1;
            END

            IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList a
                WHERE a.AssignPeriodID = @AssignPeriodID
                  AND a.IdaraId = @IdaraID_INT
            )
            BEGIN
                ;THROW 50001, N'لايمكن اغلاق المحضر التخصيص لعدم وجود اي مستفيد مخصص له منزل', 1;
            END

            SET @NewID = (SELECT TOP(1) a.AssignPeriodID 
            FROM Housing.AssignPeriod a 
            where a.IdaraId_FK = @idaraID_FK and a.AssignPeriodActive = 1 and a.AssignPeriodClose = 1 and a.AssignPeriodEnddate is null
            order by a.AssignPeriodID desc);

            UPDATE Housing.AssignPeriod 
            set AssignPeriodEnddate = GETDATE(), AssignPeriodCloseNote = @Notes, AssignPeriodCloseBy =@entryData,AssignPeriodClose = 0
            where IdaraId_FK = @idaraID_FK and AssignPeriodActive = 1 and AssignPeriodClose = 1 and AssignPeriodEnddate is null 
            and WaitingClassID_FK = @WaitingClassID
            
          

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اغلاق محضر التخصيص', 1; -- برمجي
            END


            
              INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , AssignPeriodID_FK
                , InAssignPeriod
                , IdaraId_FK
                , entryData
                , hostName
            )
            
            Select 
             w.LastActionTypeID
            ,w.residentInfoID
            ,w.GeneralNo
            ,w.ActionDecisionNo
            ,w.ActionDecisionDate
            ,w.buildingDetailsID
            ,w.buildingDetailsNo
            ,1
            ,w.LastActionNote
            ,w.LastActionbuildingActionParentID
            ,@AssignPeriodID
            , 0
            ,@idaraID_FK
            ,@entryData
            ,@hostName

            From Housing.V_WaitingList w
            where 
                 w.IdaraId = @idaraID_FK
                 AND  w.LastActionTypeID in (27,39,41)


            
            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اغلاق محضر التخصيص', 1; -- برمجي
            END



            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اغلاق محضر التخصيص - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"AssignPeriodID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"AssignPeriodDescrption": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"AssignPeriodStartdate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), GETDATE()), '') + N'"'
                + N',"AssignPeriodActive": "1"'
                + N',"IdaraId_FK": "'               + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                 + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[AssignPeriod]'
                , N'CLOSEASSIGNPERIOD'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم اغلاق محضر التخصيص بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- ASSIGNHOUSE
        ----------------------------------------------------------------
        ELSE IF @Action = N'ASSIGNHOUSE'
        BEGIN
       


            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

              IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.AssignPeriod a
                WHERE a.AssignPeriodActive = 1 and a.AssignPeriodClose = 1 and a.AssignPeriodEnddate is null
                  AND a.IdaraId_FK = @IdaraID_INT
            )
            BEGIN
                ;THROW 50001, N'لا يوجد محضر تخصيص نشط', 1;
            END
            
             IF @buildingDetailsID IS NULL
            BEGIN
                ;THROW 50001, N'يجب اختيار المبنى', 1;
            END
            

            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


             IF NOT EXISTS
            (
                 SELECT 1
                FROM [DATACORE].[Housing].[V_GetGeneralListForBuilding] c
                where c.BuildingIdaraID = @IdaraID_INT and c.buildingDetailsActive = 1
            )
            BEGIN
                ;THROW 50001, N'عذرا المنزل غير نشط حاليا', 1;
            END


              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) in (38,40)
            BEGIN
                ;THROW 50001, N'تم التخصيص لهذا المستفيد مسبقا', 1;
            END

            Declare @buildingActionTypeID_FK INT

            select 
            @buildingActionTypeID_FK =
            case 
            when w.LastActionTypeID = 27 then 38
            when w.LastActionTypeID = 39 then 40
            else 0
            END
            from Housing.V_WaitingList w
            where w.residentInfoID = @residentInfoID




            IF 
            (
               @buildingActionTypeID_FK = 0 
            )
            BEGIN
                ;THROW 50001, N'لايمكن التخصيص لهذا المستفيد لتجاوزه الحد الاعلى من التخصيص', 1;
            END

          

             IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) in (42)
            BEGIN
            Declare @msg1 nvarchar(1000)
            set @msg1 = N'تم الغاء أحقية السكن للمستفيد'+cast(@FullName_A as nvarchar(1000))+N' مسبقا لتجاوزه عدد مرات التخصيص المسموحة نظام'
                ;THROW 50001, @msg1, 1;
            END


              INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , AssignPeriodID_FK
                , InAssignPeriod
                , IdaraId_FK
                , entryData
                , hostName
            )
            
             VALUES
            (
                  @buildingActionTypeID_FK
                , @residentInfoID
                , @GeneralNo
                , @buildingActionDecisionNo
                , @buildingActionDecisionDate
                , @buildingDetailsID
                , @buildingDetailsNo
                , 1
                , @Notes
                , @LastActionID
                , @AssignPeriodID
                , 1
                , @IdaraID_INT
                , @entryData
                , @hostName
            );


            
            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تخصيص المنزل للمستفيد', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تخصيص المنزل للمستفيد - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionTypeID_FK), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionDate), '') + N'"'
                + N',"buildingDetailsID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"buildingDetailsNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsNo), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"buildingActionNote": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @LastActionID), '') + N'"'
                + N',"AssignPeriodID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @AssignPeriodID), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'ASSIGNHOUSE'
                , @ActionID
                , @entryData
                , @Note
            );
            

            SELECT 1 AS IsSuccessful, N'تم تخصيص المنزل للمستفيد بنجاح' AS Message_;
            RETURN;
        END


        ----------------------------------------------------------------
        -- CANCLEASSIGNHOUSE
        ----------------------------------------------------------------
        ELSE IF @Action = N'CANCLEASSIGNHOUSE'
        BEGIN
       
            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END
            
             IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.AssignPeriod a
                WHERE a.AssignPeriodActive = 1 and a.AssignPeriodClose = 1 and a.AssignPeriodEnddate is null
                  AND a.IdaraId_FK = @IdaraID_INT
            )
            BEGIN
                ;THROW 50001, N'لا يوجد محضر تخصيص نشط', 1;
            END
            

            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


            IF 
