-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[buildingUtilityTypeDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   

            -- BuildingType Data
            SELECT 
                  t.buildingUtilityTypeID
                , t.buildingUtilityTypeName_A
                , t.buildingUtilityTypeName_E
                , t.buildingUtilityTypeDescription
                , t.buildingUtilityTypeActive
                , convert(nvarchar(10),t.buildingUtilityTypeStartDate,23) buildingUtilityTypeStartDate
                , convert(nvarchar(10),t.buildingUtilityTypeEndDate,23) buildingUtilityTypeEndDate
                , CASE 
                    WHEN t.buildingUtilityIsRent = 0 THEN N'0'
                    WHEN t.buildingUtilityIsRent = 1 THEN N'1'
                    ELSE N''
                  END AS buildingUtilityIsRent
            FROM  Housing.buildingUtilityType t
            WHERE t.buildingUtilityTypeActive = 1 and (t.IdaraId_FK is null or t.IdaraId_FK = @idaraID)
            ORDER BY t.buildingUtilityTypeID asc;
    -- Insert statements for procedure here
END
GO
/****** Object:  StoredProcedure [Housing].[BuildingUtilityTypeSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[BuildingUtilityTypeSP] 
(
      @Action                         NVARCHAR(200)
    , @buildingUtilityTypeID          BIGINT          = NULL
    , @buildingUtilityTypeName_A      NVARCHAR(100)   = NULL
    , @buildingUtilityTypeName_E      NVARCHAR(100)   = NULL
    , @buildingUtilityTypeDescription NVARCHAR(1000)  = NULL
    , @buildingUtilityTypeActive      NVARCHAR(1)     = NULL
    , @buildingUtilityTypeStartDate   NVARCHAR(1000)  = NULL
    , @buildingUtilityTypeEndDate     NVARCHAR(1000)  = NULL
    , @buildingUtilityIsRent          NVARCHAR(1)     = NULL
    , @idaraID_FK                     NVARCHAR(10)    = NULL
    , @entryData                      NVARCHAR(20)    = NULL
    , @hostName                       NVARCHAR(200)   = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويل التواريخ
    DECLARE @StartDT DATETIME = TRY_CONVERT(DATETIME, NULLIF(LTRIM(RTRIM(@buildingUtilityTypeStartDate)), ''), 120);
    DECLARE @EndDT   DATETIME = TRY_CONVERT(DATETIME, NULLIF(LTRIM(RTRIM(@buildingUtilityTypeEndDate)), ''), 120);

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), ''));

    -- تحويلات BIT/INT آمنة
    DECLARE @IsRent_BIT BIT = TRY_CONVERT(BIT, NULLIF(LTRIM(RTRIM(@buildingUtilityIsRent)), ''));
    IF @IsRent_BIT IS NULL
        SET @IsRent_BIT = 0;

    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

        ----------------------------------------------------------------
        -- INSERT
        ----------------------------------------------------------------
        IF @Action = N'INSERT'
        BEGIN
            IF NULLIF(LTRIM(RTRIM(@buildingUtilityTypeName_A)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'اسم نوع المرفق (عربي) مطلوب', 1;
            END

            IF (@StartDT IS NOT NULL AND @EndDT IS NOT NULL AND @EndDT <= @StartDT)
            BEGIN
                ;THROW 50001, N'لايمكن ان يكون تاريخ النهاية اصغر من او مساوي لتاريخ البداية', 1;
            END

            IF EXISTS
            (
                SELECT 1
                FROM  Housing.BuildingUtilityType but
                WHERE but.buildingUtilityTypeName_A = @buildingUtilityTypeName_A
                  AND but.buildingUtilityTypeActive = 1
                  AND (but.IdaraId_FK = @IdaraID_INT OR @IdaraID_INT IS NULL)
            )
            BEGIN
                ;THROW 50001, N'البيانات مدخلة مسبقا', 1;
            END

            INSERT INTO  Housing.BuildingUtilityType
            (
                  buildingUtilityTypeName_A
                , buildingUtilityTypeName_E
                , buildingUtilityTypeDescription
                , buildingUtilityTypeActive
                , buildingUtilityTypeStartDate
                , buildingUtilityTypeEndDate
                , buildingUtilityIsRent
                , IdaraId_FK
                , entryData
                , hostName
            )
            VALUES
            (
                  @buildingUtilityTypeName_A
                , @buildingUtilityTypeName_E
                , @buildingUtilityTypeDescription
                , 1
                , ISNULL(@StartDT, GETDATE())
                , @EndDT
                , @IsRent_BIT
                , @IdaraID_INT
                , @entryData
                , @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البيانات', 1; -- برمجي/غير متوقع
            END

            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البيانات - Identity', 1; -- برمجي/غير متوقع
            END

            SET @Note = N'{'
                + N'"buildingUtilityTypeID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingUtilityTypeName_A": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @buildingUtilityTypeName_A), '') + N'"'
                + N',"buildingUtilityTypeName_E": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @buildingUtilityTypeName_E), '') + N'"'
                + N',"buildingUtilityTypeDescription": "'  + ISNULL(CONVERT(NVARCHAR(MAX), @buildingUtilityTypeDescription), '') + N'"'
                + N',"buildingUtilityTypeActive": "1"'
                + N',"buildingUtilityTypeStartDate": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @StartDT, 120), '') + N'"'
                + N',"buildingUtilityTypeEndDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @EndDT, 120), '') + N'"'
                + N',"buildingUtilityIsRent": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @IsRent_BIT), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingUtilityType]'
                , N'INSERT'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم اضافة البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- UPDATE
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPDATE'
        BEGIN
            IF @buildingUtilityTypeID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

            IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.BuildingUtilityType
                WHERE buildingUtilityTypeID = @buildingUtilityTypeID
                  AND buildingUtilityTypeActive = 1
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

            IF (@StartDT IS NOT NULL AND @EndDT IS NOT NULL AND @EndDT <= @StartDT)
            BEGIN
                ;THROW 50001, N'لايمكن ان يكون تاريخ النهاية اصغر من او مساوي لتاريخ البداية', 1;
            END

            UPDATE  Housing.BuildingUtilityType
            SET
                  buildingUtilityTypeName_A      = ISNULL(@buildingUtilityTypeName_A, buildingUtilityTypeName_A)
                , buildingUtilityTypeName_E      = ISNULL(@buildingUtilityTypeName_E, buildingUtilityTypeName_E)
                , buildingUtilityTypeDescription = ISNULL(@buildingUtilityTypeDescription, buildingUtilityTypeDescription)
                , buildingUtilityTypeStartDate   = ISNULL(@StartDT, buildingUtilityTypeStartDate)
                , buildingUtilityTypeEndDate     = ISNULL(@EndDT, buildingUtilityTypeEndDate)
                , buildingUtilityIsRent          = ISNULL(@IsRent_BIT, buildingUtilityIsRent)
                , IdaraId_FK                     = ISNULL(@IdaraID_INT, IdaraId_FK)
                , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)
            WHERE buildingUtilityTypeID = @buildingUtilityTypeID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1; -- برمجي/غير متوقع
            END

            SET @Note = N'{'
                + N'"buildingUtilityTypeID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @buildingUtilityTypeID), '') + N'"'
                + N',"buildingUtilityTypeName_A": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @buildingUtilityTypeName_A), '') + N'"'
                + N',"buildingUtilityTypeName_E": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @buildingUtilityTypeName_E), '') + N'"'
                + N',"buildingUtilityTypeDescription": "'  + ISNULL(CONVERT(NVARCHAR(MAX), @buildingUtilityTypeDescription), '') + N'"'
                + N',"buildingUtilityTypeStartDate": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @StartDT, 120), '') + N'"'
                + N',"buildingUtilityTypeEndDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @EndDT, 120), '') + N'"'
                + N',"buildingUtilityIsRent": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @IsRent_BIT), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingUtilityType]'
                , N'UPDATE'
                , @buildingUtilityTypeID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم تحديث البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- DELETE (Soft Delete)
        ----------------------------------------------------------------
        ELSE IF @Action = N'DELETE'
        BEGIN
            IF @buildingUtilityTypeID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للحذف', 1;
            END

            IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.BuildingUtilityType
                WHERE buildingUtilityTypeID = @buildingUtilityTypeID
                  AND buildingUtilityTypeActive = 1
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

            UPDATE  Housing.BuildingUtilityType
            SET
                  buildingUtilityTypeActive = 0
                , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)
            WHERE buildingUtilityTypeID = @buildingUtilityTypeID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم حذف أي سجل', 1; -- برمجي/غير متوقع
            END

            SET @Note = N'{'
                + N'"buildingUtilityTypeID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @buildingUtilityTypeID), '') + N'"'
                + N',"entryData": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'             + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingUtilityType]'
                , N'DELETE'
                , @buildingUtilityTypeID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم حذف البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[FinancialAuditForExtendAndEvictionsDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[FinancialAuditForExtendAndEvictionsDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      BIGINT
    , @hostname       NVARCHAR(400)
	,@residentInfoID   BIGINT
    
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	    -- MeterReadForOccubentAndExit Data
 -- HousingExtend Data
        -- FinancialAuditForExtendAndEvictions Data
        Declare @buildingDetailsID   BIGINT
        set @buildingDetailsID = (
        select Top(1) w.buildingDetailsID 
        from Housing.V_WaitingList w 
        where w.residentInfoID = @residentInfoID and w.LastActionTypeID in (51,57) 
        order by w.LastActionID desc)

        ------------------------------1--------------------------------------------
       
             SELECT 
                 fr.residentInfoID [residentInfoID]
                ,fr.NationalID [NationalID]
                ,fr.generalNo_FK [generalNo_FK]
                ,fr.firstName_A [firstName_A]
                ,fr.secondName_A [secondName_A]
                ,fr.thirdName_A [thirdName_A]
                ,fr.lastName_A [lastName_A]
                ,fr.firstName_E [firstName_E]
                ,fr.secondName_E [secondName_E]
                ,fr.thirdName_E [thirdName_E]
                ,fr.lastName_E [lastName_E]
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_A,
                     fr.secondName_A,
                     fr.thirdName_A,
                     fr.lastName_A
                 )
                 )) AS FullName_A
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_E,
                     fr.secondName_E,
                     fr.thirdName_E,
                     fr.lastName_E
                 )
                 )) AS FullName_E
                ,fr.rankID_FK [rankID_FK]
                ,fr.rankNameA
                ,fr.militaryUnitID_FK [militaryUnitID_FK]
                ,fr.militaryUnitName_A
                ,fr.martialStatusID_FK [martialStatusID_FK]
                ,fr.maritalStatusName_A
                ,fr.dependinceCounter [dependinceCounter]
                ,fr.nationalityID_FK [nationalityID_FK]
                ,fr.nationalityName_A
                ,fr.genderID_FK [genderID_FK]
                ,fr.genderName_A
                ,convert(nvarchar(10),fr.birthdate,23) birthdate
                ,fr.residentcontactDetails
                ,fr.note [note]
                ,fr.IdaraID IdaraID
                ,fr.IdaraName IdaraName
                ,w.buildingDetailsID
                ,w.buildingDetailsNo
                ,isnull(r.buildingRentAmount,0.00) buildingRentAmount
                ,w.LastActionID
                ,w.LastActionTypeID
                ,w.ActionID
                ,convert(nvarchar(10),w.LastActionDate,23) LastActionDate
                ,w.LastActionExtendReasonTypeID
                ,convert(nvarchar(10),w.OccupentDate,23) OccupentDate
                ,convert(nvarchar(10),w.ExitDate,23) ExitDate

                
           FROM [DATACORE].[Housing].V_WaitingList w
           inner join [DATACORE].[Housing].V_GetFullResidentDetails fr on fr.residentInfoID = w.residentInfoID
           left join Housing.V_buildingWithRent r on w.buildingDetailsID = r.buildingDetailsID
           where w.LastActionTypeID in (51,57) 
           and fr.residentInfoID = @residentInfoID
           and fr.IdaraID = @idaraID

           

           -----------------------------------2-----------------------------------------------------------------------------------------



          
        SELECT 
            rd.FullName_A+' - '+rd.NationalID+' - '+case when w.LastActionTypeID = 51 then N'امهال' when w.LastActionTypeID = 57 then N'اخلاء' END as FullName_A,
            w.residentInfoID
          
    FROM Housing.V_WaitingList w 
    INNER JOIN Housing.V_GetFullResidentDetails rd 
        ON w.residentInfoID = rd.residentInfoID
        Inner Join Housing.BuildingActionType ba on w.LastActionTypeID = ba.buildingActionTypeID
    WHERE w.IdaraId = @idaraID
      AND  w.LastActionTypeID in (51,57)
      order by   w.waitingClassSequence asc


      --or w.LastActionTypeID in (2,3,18,19,20,21,22,23,24,26,27,28,33,34,35)


--------------------------------------3--------------------------------------------------------------------------------------------------------------

IF @residentInfoID IS NOT NULL
Begin

SELECT 
       ROW_NUMBER() OVER (ORDER BY bt.BillChargeTypeID ASC) AS order_
      ,ISNULL(s.[residentInfoID], @residentInfoID) AS residentInfoID
      ,bt.[BillChargeTypeID]
      ,bt.[BillChargeTypeName_A]
      ,ISNULL(s.[buildingDetailsID], -1) AS buildingDetailsID 
      ,ISNULL(b.buildingDetailsNo, N'لايوجد') AS buildingDetailsNo 
      ,ISNULL(s.[SumBillsTotalPrice], 0) AS SumBillsTotalPrice
      ,ISNULL(s.[SumTotalPaidBills], 0) AS SumTotalPaidBills
      --,ISNULL(s.[Remaining], 0) AS Remaining
      ,case
        when ISNULL(s.[Remaining], 0) < 0 then ISNULL(s.[Remaining], 0) * -1
        else ISNULL(s.[Remaining], 0)
        end as Remaining
      ,CASE
          WHEN ISNULL(s.[Remaining], 0) > 0 THEN N'فواتير ' + bt.BillChargeTypeName_A + N' مستحقة للادارة'
          WHEN ISNULL(s.[Remaining], 0) < 0 THEN N'فواتير ' + bt.BillChargeTypeName_A + N' زائدة للمستفيد'
          ELSE N'لايوجد مطالبات'
       END AS BillsStatus
      ,CASE
          WHEN ISNULL(s.[Remaining], 0) > 0 THEN 0
          WHEN ISNULL(s.[Remaining], 0) < 0 THEN 1
          ELSE 2
       END AS BillsStatusID
FROM Housing.BillChargeType bt
LEFT JOIN Housing.V_SumBillsTotalPriceAndTotalPaidForResident s
       ON s.BillChargeTypeID = bt.BillChargeTypeID
      AND s.residentInfoID = @residentInfoID
      AND (s.buildingDetailsID = @buildingDetailsID OR s.buildingDetailsID IS NULL)
LEFT JOIN Housing.V_GetGeneralListForBuilding b
       ON s.buildingDetailsID = b.buildingDetailsID
ORDER BY bt.BillChargeTypeID ASC;
END



--------------------------------------4--------------------------------------------------------------------------------------------------------------


         SELECT
      
        (([TotalRentBillsAmount]+[TotalServiceBillsAmount]) - ([TotalRentBillsPaid]+[TotalServiceBillsPaid])) AllAmountresidual
      
      ,([TotalRentBillsAmount] - [TotalRentBillsPaid]) RentBillsAmountresidual
      ,([TotalServiceBillsAmount] - [TotalServiceBillsPaid]) ServiceBillsAmountresidual


        FROM [DATACORE].[Housing].V_WaitingList w
           inner join [DATACORE].[Housing].V_GetFullResidentDetails fr on fr.residentInfoID = w.residentInfoID
        inner join [DATACORE].[Housing].[V_ResidentFinancialSummary] s on fr.residentInfoID = s.residentInfoID

        where s.residentInfoID = @residentInfoID
        AND  w.LastActionTypeID in (51,57)
        and fr.IdaraID = @idaraID




        ------------------------------5----------------------------------------------------------------------------------------------------------------------

        select 
        t.billPaymentTypeID,
        t.billPaymentTypeName_A
        from Housing.billPaymentType t 
        where t.billPaymentDestainationID_FK = 1
        

        ------------------------------6----------------------------------------------------------------------------------------------------------------------

         select 
        t.billPaymentTypeID,
        t.billPaymentTypeName_A
        from Housing.billPaymentType t 
        where t.billPaymentDestainationID_FK = 2
     
     ------------------------------------7----------------------------------------------------------------------------------------------------------------
     select 
        t.billPaymentTypeID,
        t.billPaymentTypeName_A
        from Housing.billPaymentType t 
        where t.billPaymentTypeID in(1,2)

        ---------------------------------8-------------------------------------------------------------------------------------------------------------------
    Select e.BillChargeTypeID,e.BillChargeTypeName_A 
      from Housing.BillChargeType e
      where e.BillChargeTypeActive  = 1

    
    
    --select r.buildingRentAmount * 40 insuranceRentAmount,r.buildingRentAmount

     --FROM [DATACORE].[Housing].V_WaitingList w
     --   inner join [DATACORE].[Housing].V_GetFullResidentDetails fr on fr.residentInfoID = w.residentInfoID
     --   inner join [DATACORE].[Housing].[V_ResidentFinancialSummary] s on fr.residentInfoID = s.residentInfoID
     --   inner join Housing.V_buildingWithRent r on w.buildingDetailsID = r.buildingDetailsID
     --   where s.residentInfoID = @residentInfoID
     --   AND  w.LastActionTypeID in (51,57)
     --   and fr.IdaraID = @idaraID




        ----------------------------------9------------------------------------------------------------------------------------------------------------------
      --Select e.ExtendReasonTypeID,e.ExtendReasonTypeName_A 
      --from Housing.ExtendReasonType e
      --where e.Active = 1

      Select e.BillChargeTypeID,e.BillChargeTypeName_A 
      from Housing.BillChargeType e
      where e.BillChargeTypeActive  = 1 and e.BillChargeTypeID <> 6

       
        ----------------------------------10------------------------------------------------------------------------------------------------------------------
     
     if(@residentInfoID is null)
     begin
     
     SELECT 
    e.residentInfoID,
    SUM(e.SumBillsTotalPrice) AS SumBillsTotalPrice,
    SUM(e.SumTotalPaidBills) AS SumTotalPaidBills,
    case
        when SUM(e.Remaining) < 0 then SUM(e.Remaining) * -1
        else SUM(e.Remaining)
    end as Remaining,
    --SUM(e.Remaining) AS Remaining,
    CASE 
        WHEN SUM(e.Remaining) > 0 THEN N'المستفيد مطالب بمبالغ مستحقة للادارة'
        WHEN SUM(e.Remaining) < 0 THEN N'يوجد مبالغ فائضة للمستفيد'
        ELSE N'لايوجد مطالبات'
    END AS BillsStatus,
    CASE 
        WHEN SUM(e.Remaining) > 0 THEN 0
        WHEN SUM(e.Remaining) < 0 THEN 1
        ELSE 2
    END AS BillsStatusID
FROM Housing.V_SumBillsTotalPriceAndTotalPaidForResident e
WHERE e.residentInfoID = @residentInfoID
AND (e.buildingDetailsID = @buildingDetailsID OR e.buildingDetailsID IS NULL)
GROUP BY e.residentInfoID;
     
     end

     else
     begin

     SELECT 
    @residentInfoID AS residentInfoID,

    COALESCE(SUM(e.SumBillsTotalPrice), 0) AS SumBillsTotalPrice,
    COALESCE(SUM(e.SumTotalPaidBills), 0) AS SumTotalPaidBills,

    CASE
        WHEN COALESCE(SUM(e.Remaining), 0) < 0 
            THEN COALESCE(SUM(e.Remaining), 0) * -1
        ELSE COALESCE(SUM(e.Remaining), 0)
    END AS Remaining,

    CASE 
        WHEN COALESCE(SUM(e.Remaining), 0) > 0 THEN N'مطالب بمبالغ للادارة'
        WHEN COALESCE(SUM(e.Remaining), 0) < 0 THEN N'يوجد مبالغ زائدة للمستفيد'
        ELSE N'لايوجد مطالبات'
    END AS BillsStatus,

    CASE 
        WHEN COALESCE(SUM(e.Remaining), 0) > 0 THEN 0
        WHEN COALESCE(SUM(e.Remaining), 0) < 0 THEN 1
        ELSE 2
    END AS BillsStatusID

FROM Housing.V_SumBillsTotalPriceAndTotalPaidForResident e
WHERE e.residentInfoID = @residentInfoID
AND (e.buildingDetailsID = @buildingDetailsID OR e.buildingDetailsID IS NULL)

     end

       ------------------------------------11----------------------------------------------------------------------------------------------------------------
      
       
END
GO
/****** Object:  StoredProcedure [Housing].[FinancialAuditForExtendAndEvictionsSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[FinancialAuditForExtendAndEvictionsSP] 
(
      @Action                               NVARCHAR(200)
    , @ActionID                             BIGINT          = NULL
    , @residentInfoID                       NVARCHAR(100)   = NULL
    , @buildingDetailsID                    NVARCHAR(1000)  = NULL
    , @LastActionID                         NVARCHAR(1000)  = NULL
    , @LastActionTypeID                     NVARCHAR(1000)  = NULL
    , @Notes                                NVARCHAR(1000)  = NULL
    , @LastActionExtendReasonTypeID         NVARCHAR(1000)  = NULL
    , @PaymentType                          NVARCHAR(1000)  = NULL
    , @PaymentNo                            NVARCHAR(1000)  = NULL
    , @PaymentDate                          NVARCHAR(1000)  = NULL
    , @Amount                               NVARCHAR(1000)  = NULL
    , @FullRemining                         NVARCHAR(1000)  = NULL
    , @BillChargeTypeID_FK                  NVARCHAR(1000)  = NULL
    , @ToBillChargeTypeID_FK                NVARCHAR(1000)  = NULL
    , @description                          NVARCHAR(4000)  = NULL
    , @OccupentDate                         NVARCHAR(4000)  = NULL
    , @ExitDate                             NVARCHAR(1000)  = NULL
    , @idaraID_FK                           NVARCHAR(10)    = NULL
    , @entryData                            NVARCHAR(20)    = NULL
    , @hostName                             NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL,
          @NewID1 BIGINT = NULL,
          @NewID2 BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));
    DECLARE @DeductType_INT INT = (select top (1) t.deductTypeID_FK from Housing.BuildingPaymentType t where t.buildingPaymentTypeID = @PaymentType order by t.buildingPaymentTypeID desc);


    DECLARE @Amount_Decimal DECIMAL(18,2);
    IF @Action = N'FINANCIALAUDITFOREXTENDANDEVICTIONS'
    begin
    SET @Amount_Decimal = TRY_CONVERT(DECIMAL(18,2), 0);
    end
    else
    begin
    SET @Amount_Decimal = TRY_CONVERT(DECIMAL(18,2), @Amount);
    
    IF @Amount_Decimal IS NULL
    BEGIN
        ;THROW 50001, N'قيمة المبلغ غير صحيحة', 1;
    END
    end

    
   
    

    DECLARE @buildingDetailsNo nvarchar(200)
            , @NationalID                           NVARCHAR(100)   
            , @GeneralNo                            NVARCHAR(100)   
            , @WaitingClassID                       NVARCHAR(1000)  
            , @WaitingClassName                     NVARCHAR(1000)  
            , @WaitingOrderTypeID                   NVARCHAR(1000)  
            , @WaitingOrderTypeName                 NVARCHAR(1000)  
            , @waitingClassSequence                 NVARCHAR(1000)  
            , @WaitingListOrder                     NVARCHAR(1000)  
            , @FullName_A                           NVARCHAR(1000)  
            , @AssignPeriodID                       NVARCHAR(1000)  
            , @ExtendStartDate                      NVARCHAR(1000)
            , @ExtendEndDate                        NVARCHAR(1000)
            , @ExtendLetterNo                       NVARCHAR(1000)
            , @ExtendLetterDate                     NVARCHAR(1000)
            , @unitID                               NVARCHAR(1000)
            , @FullName                             NVARCHAR(1000)
            
            
    select 
    --@NationalID               = w.NationalID,
    --@GeneralNo                = w.GeneralNo,
    @WaitingClassID           = w.WaitingClassID,
    @WaitingClassName         = w.WaitingClassName,
    @WaitingOrderTypeID       = w.WaitingOrderTypeID,
    @WaitingOrderTypeName     = w.WaitingClassName,
    @waitingClassSequence     = w.waitingClassSequence,
    @FullName_A               = w.fullname,
    @AssignPeriodID           = w.AssignPeriodID,
    @ExtendStartDate          = w.buildingActionFromDate,
    @ExtendEndDate            = w.buildingActionToDate,
    @ExtendLetterNo           = w.ActionDecisionNo,
    @ExtendLetterDate         = w.ActionDecisionDate,
    @buildingDetailsNo         = w.buildingDetailsNo

    from Housing.V_WaitingList w
    where 
    w.LastActionID = @LastActionID
    and 
    w.ActionID = @ActionID
    and 
    w.residentInfoID = @residentInfoID
    and 
    w.buildingDetailsID = @buildingDetailsID
    and 
    w.LastActionTypeID = @LastActionTypeID
    and 
    w.IdaraId = @idaraID_FK



              
    select 
    @NationalID               = w.NationalID,
    @GeneralNo                = w.generalNo_FK,
    @unitiD                   = w.militaryUnitID_FK,
    @FullName                 = w.FullName_A
    FROM Housing.V_GetFullResidentDetails w
    where w.residentInfoID = @residentInfoID

   
    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

   


        -- IF @Action IN(N'NewExtend',N'EditExtend',N'SendExtendToFinance')
        --BEGIN
         
           


        --END

        

     

        ----------------------------------------------------------------
        -- FINANCIALAUDITFOREXTENDANDEVICTIONS
        ----------------------------------------------------------------
        IF @Action = N'FINANCIALAUDITFOREXTENDANDEVICTIONS'
        BEGIN
       


            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@residentInfoID)), N'') IS NULL
             BEGIN
                 ;THROW 50001, N'رقم الساكن مطلوب', 1;
             END


              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) Not in (51,57)
            BEGIN
                ;THROW 50001, N'تم انهاء اجراءات الامهال / الاخلاء مسبقا', 1;
            END



            Declare @buildingActionTypeID_FK INT

            select 
            @buildingActionTypeID_FK =
            case 
            when w.LastActionTypeID = 51  then 52
            when w.LastActionTypeID = 57  then 58
            else 
            9999
            END
            from Housing.V_WaitingList w
            where w.residentInfoID = @residentInfoID and w.buildingDetailsID = @buildingDetailsID

            IF 
            (
               @buildingActionTypeID_FK = 9999 
            )
            BEGIN
                ;THROW 50001, N'حصل خطأ ما building Action Type', 1;
            END

          

            IF(@buildingActionTypeID_FK = 52)
            begin


              INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , buildingActionFromDate
                , buildingActionToDate
                , ExtendReasonTypeID_FK
                , OccupentDate
                --, ExitDate
                , IdaraId_FK
                , entryData
                , hostName
            )
            select
              @buildingActionTypeID_FK
                , @residentInfoID
                , @GeneralNo
                , @ExtendLetterNo
                , @ExtendLetterDate
                , @buildingDetailsID
                , @buildingDetailsNo
                , 1
                , @Notes
                , @LastActionID
                , @ExtendStartDate
                , @ExtendEndDate
                , w.LastActionExtendReasonTypeID
                , cast(@OccupentDate as date)
                --, @ExitDate
                , @IdaraID_INT
                , @entryData
                , @hostName
              from Housing.V_WaitingList w
            where w.residentInfoID = @residentInfoID 
            and w.buildingDetailsID = @buildingDetailsID
            
            -- VALUES
            --(
            --      @buildingActionTypeID_FK
            --    , @residentInfoID
            --    , @GeneralNo
            --    , @ExtendLetterNo
            --    , @ExtendLetterDate
            --    , @buildingDetailsID
            --    , @buildingDetailsNo
            --    , 1
            --    , @Notes
            --    , @LastActionID
            --    , @ExtendStartDate
            --    , @ExtendEndDate
            --    , @LastActionExtendReasonTypeID
            --    , @IdaraID_INT
            --    , @entryData
            --    , @hostName
            --);


            
            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اعتماد التدقيق المالي للامهال ', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اعتماد التدقيق المالي للامهال - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionTypeID_FK), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendLetterNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendLetterDate), '') + N'"'
                + N',"buildingDetailsID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"buildingDetailsNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsNo), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"buildingActionNote": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @LastActionID), '') + N'"'
                + N',"buildingActionFromDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendStartDate), '') + N'"'
                + N',"buildingActionToDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendEndDate), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'FINANCIALAUDITFOREXTENDANDEVICTIONS'
                , @ActionID
                , @entryData
                , @Note
            );
            

            SELECT 1 AS IsSuccessful, N'تم اعتماد التدقيق المالي للامهال بنجاح' AS Message_;
            RETURN;

            END



            ELSE IF(@buildingActionTypeID_FK = 58)
            begin


              INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , buildingActionDate
                , buildingActionDecisionDate
                , buildingActionDecisionNo
                , ExtendReasonTypeID_FK
                , OccupentDate
                , ExitDate
                , IdaraId_FK
                , entryData
                , hostName
            )
            SELECT
                  @buildingActionTypeID_FK
                , @residentInfoID
                , @GeneralNo
                , @buildingDetailsID
                , @buildingDetailsNo
                , 1
                , @Notes
                , @LastActionID
                , GETDATE() 
                , null
                , null
                , @LastActionExtendReasonTypeID
                , @OccupentDate
                , @ExitDate
                , @IdaraID_INT
                , @entryData
                , @hostName

            from Housing.V_WaitingList w
            where w.residentInfoID = @residentInfoID 
            and w.buildingDetailsID = @buildingDetailsID
            -- VALUES
            --(
            --      @buildingActionTypeID_FK
            --    , @residentInfoID
            --    , @GeneralNo
            --    , @buildingDetailsID
            --    , @buildingDetailsNo
            --    , 1
            --    , @Notes
            --    , @LastActionID
            --    , @ExitDate
            --    , @LastActionExtendReasonTypeID
            --    , @IdaraID_INT
            --    , @entryData
            --    , @hostName
            --);


            
            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اعتماد التدقيق المالي للاخلاء ', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اعتماد التدقيق المالي للاخلاء - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionTypeID_FK), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendLetterNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendLetterDate), '') + N'"'
                + N',"buildingDetailsID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"buildingDetailsNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsNo), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"buildingActionNote": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @LastActionID), '') + N'"'
                + N',"buildingActionFromDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendStartDate), '') + N'"'
                + N',"buildingActionToDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendEndDate), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'FINANCIALAUDITFOREXTENDANDEVICTIONS'
                , @ActionID
                , @entryData
                , @Note
            );
            

            SELECT 1 AS IsSuccessful, N'تم اعتماد التدقيق المالي للاخلاء بنجاح' AS Message_;
            RETURN;

            END
            ELSE
        BEGIN

        SELECT 0 AS IsSuccessful, N'حصل خطأ ما - Not Exit Or Extend' AS Message_;
            RETURN;

        END

        END
       
        

         ----------------------------------------------------------------
        -- PAYMENTANDREFUNDFOREXTENDANDEXIT
        ----------------------------------------------------------------
        ELSE IF @Action = N'PAYMENTANDREFUNDFOREXTENDANDEXIT'
        BEGIN
          
            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


              IF NULLIF(LTRIM(RTRIM(@residentInfoID)), N'') IS NULL
             BEGIN
                 ;THROW 50001, N'رقم الساكن مطلوب', 1;
             END



              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) Not in (51,57)
            BEGIN
                ;THROW 50001, N'تم انهاء اجراءات الامهال / الاخلاء مسبقا', 1;
            END

            Declare @InsertedAmount decimal(18,2)
             IF (select b.buildingPaymentDestainationID_FK from [DATACORE].[Housing].[BuildingPaymentType] b where b.buildingPaymentTypeID = @PaymentType) = 1
         BEGIN
                set @InsertedAmount = @Amount_Decimal
         END
         ELSE
         BEGIN
                set @InsertedAmount = @Amount_Decimal * -1
         END


          
           Declare @AvailableAmountForToChargeTypeForPayment decimal(18,2),@FinalAvailableAmountForToChargeTypeForPayment decimal(18,2);
            set @AvailableAmountForToChargeTypeForPayment = 
            (select TRY_CONVERT(DECIMAL(18,2),isnull(s.Remaining,0.00)) 
               FROM Housing.BillChargeType bt
               LEFT JOIN Housing.V_SumBillsTotalPriceAndTotalPaidForResident s
                      ON s.BillChargeTypeID = bt.BillChargeTypeID
                     AND s.residentInfoID = @residentInfoID
                     AND (s.buildingDetailsID = @buildingDetailsID OR s.buildingDetailsID IS NULL)
               LEFT JOIN Housing.V_GetGeneralListForBuilding b
                      ON s.buildingDetailsID = b.buildingDetailsID
                      where bt.BillChargeTypeID = @BillChargeTypeID_FK
             )

             IF (select b.buildingPaymentDestainationID_FK from [DATACORE].[Housing].[BuildingPaymentType] b where b.buildingPaymentTypeID = @PaymentType) = 1
         BEGIN
           
           set @FinalAvailableAmountForToChargeTypeForPayment = @AvailableAmountForToChargeTypeForPayment
                 
         END
        else
        BEGIN
           
           set @FinalAvailableAmountForToChargeTypeForPayment = @AvailableAmountForToChargeTypeForPayment * -1
                 
         END


         IF @Amount_Decimal > @FinalAvailableAmountForToChargeTypeForPayment
             BEGIN
             declare @msg1112 nvarchar(1000)
             set @msg1112 = N'المبلغ المدخل اكبر من المبلغ المطلوب في الخدمه المعالجة والمبلغ المطلوب هو : ' + CONVERT(NVARCHAR(100), @FinalAvailableAmountForToChargeTypeForPayment)
                 ;THROW 50001, @msg1112, 1;
             END

             
            
             



         IF (select b.buildingPaymentDestainationID_FK from [DATACORE].[Housing].[BuildingPaymentType] b where b.buildingPaymentTypeID = @PaymentType) = 1
         BEGIN
          INSERT INTO Housing.DeductList
            (
                  [deductTypeID_FK]
                 ,[DeductListStatusID_FK]
                 ,[deductName]
                 ,[amountTypeID_FK]
                 ,[paymentTypeID_FK]
                 ,[issueMonth]
                 ,[issueYear]
                 ,[paymentNo]
                 ,[paymentDate]
                 ,[description]
                 ,[deductActive]
                 ,[BillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @DeductType_INT,
                 2,
                 N'سداد عن طريق صندوق الإدارة',
                 1,
                 @PaymentType,
                 MONTH(GETDATE()),
                 YEAR(GETDATE()),
                 @PaymentNo,
                 @PaymentDate,
                 @description,
                 1,
                 @BillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في دفع المطالبات', 1; -- برمجي/غير متوقع
            END

               set @NewID = SCOPE_IDENTITY();

             SET @Note = N'{'
                + N'"deductListID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"deductTypeID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @DeductType_INT), '') + N'"'
                + N',"deductName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), N'سداد عن طريق صندوق الإدارة'), '') + N'"'
                + N',"amountTypeID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"paymentTypeID_FK": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"issueMonth": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  MONTH(GETDATE())), '') + N'"'
                + N',"issueYear": "'           + ISNULL(CONVERT(NVARCHAR(MAX), YEAR(GETDATE())), '') + N'"'
                + N',"paymentNo": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentNo), '') + N'"'
                + N',"paymentDate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentDate), '') + N'"'
                + N',"description": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @description), '') + N'"'
                + N',"deductActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @BillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[DeductList]'
                , @Action
                , @NewID
                , @entryData
                , @Note
            );


            END
            ELSE
            BEGIN

                 INSERT INTO Housing.DeductList
            (
                  [deductTypeID_FK]
                 ,[DeductListStatusID_FK]
                 ,[deductName]
                 ,[amountTypeID_FK]
                 ,[paymentTypeID_FK]
                 ,[issueMonth]
                 ,[issueYear]
                 ,[paymentNo]
                 ,[paymentDate]
                 ,[description]
                 ,[deductActive]
                 ,[BillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @DeductType_INT,
                 2,
                 N'معالجة واعادة مبالغ زائدة',
                 1,
                 @PaymentType,
                 MONTH(GETDATE()),
                 YEAR(GETDATE()),
                 @PaymentNo,
                 @PaymentDate,
                 @description,
                 1,
                 @BillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                 ;THROW 50002, N'حصل خطأ في اعادة المبالغ',  1; -- برمجي/غير متوقع
            END

            set @NewID = SCOPE_IDENTITY();

             SET @Note = N'{'
                + N'"deductListID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"deductTypeID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @DeductType_INT), '') + N'"'
                + N',"deductName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), N'معالجة واعادة مبالغ زائدة'), '') + N'"'
                + N',"amountTypeID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"paymentTypeID_FK": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"issueMonth": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  MONTH(GETDATE())), '') + N'"'
                + N',"issueYear": "'           + ISNULL(CONVERT(NVARCHAR(MAX), YEAR(GETDATE())), '') + N'"'
                + N',"paymentNo": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentNo), '') + N'"'
                + N',"paymentDate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentDate), '') + N'"'
                + N',"description": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @description), '') + N'"'
                + N',"deductActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @BillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[DeductList]'
                , @Action
                , @NewID
                , @entryData
                , @Note
            );

            END


               INSERT INTO [Housing].[BuildingPayment]
            (
                  [buildingPaymentTypeID_FK]
                 ,[generalNo_FK]
                 ,[IDNumber]
                 ,[residentInfoID_FK]
                 ,[unitID]
                 ,[userName]
                 ,[buildingDetailsID_FK]
                 ,[amount]
                 ,[deductListID_FK]
                 ,[buildingPayementActive]
                 ,[BillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @PaymentType,
                 @GeneralNo,
                 @NationalID,
                 @residentInfoID,
                 @unitID,
                 @FullName,
                 @buildingDetailsID,
                 @InsertedAmount,
                 @NewID,
                 1,
                 @BillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                 ;THROW 50002, N'حصل خطأ في عملية الدفع او الاعادة - BuildingPayment',  1; -- برمجي/غير متوقع
            END

            set @NewID1 = SCOPE_IDENTITY();

             SET @Note = N'{'
                + N'"paymentID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID1), '') + N'"'
                + N',"buildingPaymentTypeID_FK": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"generalNo_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"IDNumber": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @NationalID), '') + N'"'
                + N',"residentInfoID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"unitID": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @unitID), '') + N'"'
                + N',"userName": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  @FullName), '') + N'"'
                + N',"buildingDetailsID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"amount": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @InsertedAmount), '') + N'"'
                + N',"deductListID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingPayementActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @BillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingPayment]'
                , @Action
                , @NewID1
                , @entryData
                , @Note
            );



           

            SELECT 1 AS IsSuccessful, N'تم تنفيذ العملية بنجاح' AS Message_;
            RETURN;
        END



      
        ----------------------------------------------------------------
        -- FINANCIALSETTLEMENT
        ----------------------------------------------------------------
        ELSE IF @Action = N'FINANCIALSETTLEMENT'
        BEGIN
          
            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


              IF NULLIF(LTRIM(RTRIM(@residentInfoID)), N'') IS NULL
             BEGIN
                 ;THROW 50001, N'رقم الساكن مطلوب', 1;
             END

             
              IF @BillChargeTypeID_FK = @ToBillChargeTypeID_FK
             BEGIN
                 ;THROW 50001, N'لايمكن سحب رصيد من الخدمة لنفسها', 1;
             END


              DECLARE @FullRemining_Decimal DECIMAL(18,2);

    SET @FullRemining_Decimal = TRY_CONVERT(DECIMAL(18,2), @FullRemining);
    
    IF @FullRemining_Decimal IS NULL
    BEGIN
        ;THROW 50001, N'قيمة المبلغ غير صحيحة', 1;
    END

               IF @Amount_Decimal > @FullRemining_Decimal
             BEGIN
             declare @msg nvarchar(1000)
             set @msg = N'المبلغ المدخل اكبر من المبلغ المتوفر في هذه الخدمه : ' + CONVERT(NVARCHAR(100), @FullRemining_Decimal)
                 ;THROW 50001, @msg, 1;
             END

               IF @Amount_Decimal = 0.00
             BEGIN
              declare @msg3 nvarchar(1000)
             set @msg3 = N'يجب ان يكون المبلغ اكبر من صفر ';
                 ;THROW 50001, @msg3, 1;
             END


         
            Declare @AvailableAmountForToChargeType decimal(18,2);
            set @AvailableAmountForToChargeType = 
            (select TRY_CONVERT(DECIMAL(18,2),isnull(s.Remaining,0.00)) 
               FROM Housing.BillChargeType bt
               LEFT JOIN Housing.V_SumBillsTotalPriceAndTotalPaidForResident s
                      ON s.BillChargeTypeID = bt.BillChargeTypeID
                     AND s.residentInfoID = @residentInfoID
                     AND (s.buildingDetailsID = @buildingDetailsID OR s.buildingDetailsID IS NULL)
               LEFT JOIN Housing.V_GetGeneralListForBuilding b
                      ON s.buildingDetailsID = b.buildingDetailsID
                      where bt.BillChargeTypeID = @ToBillChargeTypeID_FK
             )

                  IF @Amount_Decimal > @AvailableAmountForToChargeType
             BEGIN
             declare @msg1 nvarchar(1000)
             set @msg1 = N'المبلغ المدخل اكبر من المبلغ المطلوب في الخدمه المعالجة والمبلغ المطلوب لسدادها هو : ' + CONVERT(NVARCHAR(100), @AvailableAmountForToChargeType)
                 ;THROW 50001, @msg1, 1;
             END

                 


              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) Not in (51,57)
            BEGIN
                ;THROW 50001, N'تم انهاء اجراءات الامهال / الاخلاء مسبقا', 1;
            END

            Declare @AmountForFromChargeType decimal(18,2),@AmountForToChargeType decimal(18,2)
            
                set @AmountForFromChargeType = @Amount_Decimal * -1

                set @AmountForToChargeType = @Amount_Decimal
         
 


         Declare @FromChargeTypeName nvarchar(1000) ,@ToChargeTypeName nvarchar(1000),@msgChargeType nvarchar(2000) 
         
         set @ToChargeTypeName = (select v.BillChargeTypeName_A from Housing.BillChargeType v where v.BillChargeTypeID = @ToBillChargeTypeID_FK)
         set @FromChargeTypeName = (select v.BillChargeTypeName_A from Housing.BillChargeType v where v.BillChargeTypeID = @BillChargeTypeID_FK)
         set @msgChargeType = N'تسوية مالية من ' + ISNULL(@FromChargeTypeName,'') + N' الى ' + ISNULL(@ToChargeTypeName,'')


          INSERT INTO Housing.DeductList
            (
                  [deductTypeID_FK]
                 ,[DeductListStatusID_FK]
                 ,[deductName]
                 ,[amountTypeID_FK]
                 ,[paymentTypeID_FK]
                 ,[issueMonth]
                 ,[issueYear]
                 ,[paymentDate]
                 ,[description]
                 ,[deductActive]
                 ,[BillChargeTypeID_FK]
                 ,[ToBillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @DeductType_INT,
                 2,
                 @msgChargeType,
                 1,
                 @PaymentType,
                 MONTH(GETDATE()),
                 YEAR(GETDATE()),
                 GETDATE(),
                 @description,
                 1,
                 @BillChargeTypeID_FK,
                 @ToBillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في التسوية المالية - deductList', 1; -- برمجي/غير متوقع
            END

           set @NewID = SCOPE_IDENTITY();







             SET @Note = N'{'
                + N'"deductListID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"deductTypeID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @DeductType_INT), '') + N'"'
                + N',"deductName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @msgChargeType), '') + N'"'
                + N',"amountTypeID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"paymentTypeID_FK": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"issueMonth": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  MONTH(GETDATE())), '') + N'"'
                + N',"issueYear": "'           + ISNULL(CONVERT(NVARCHAR(MAX), YEAR(GETDATE())), '') + N'"'
                + N',"paymentDate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), GETDATE()), '') + N'"'
                + N',"description": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @description), '') + N'"'
                + N',"deductActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @BillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[DeductList]'
                , @Action
                , @NewID
                , @entryData
                , @Note
            );



           


               INSERT INTO [Housing].[BuildingPayment]
            (
                  [buildingPaymentTypeID_FK]
                 ,[generalNo_FK]
                 ,[IDNumber]
                 ,[residentInfoID_FK]
                 ,[unitID]
                 ,[userName]
                 ,[buildingDetailsID_FK]
                 ,[amount]
                 ,[deductListID_FK]
                 ,[buildingPayementActive]
                 ,[BillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @PaymentType,
                 @GeneralNo,
                 @NationalID,
                 @residentInfoID,
                 @unitID,
                 @FullName,
                 @buildingDetailsID,
                 @AmountForFromChargeType,
                 @NewID,
                 1,
                 @BillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                 ;THROW 50002, N'حصل خطأ في عملية الدفع او الاعادة - BuildingPayment',  1; -- برمجي/غير متوقع
            END

            set @NewID1 = SCOPE_IDENTITY();

             SET @Note = N'{'
                + N'"paymentID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID1), '') + N'"'
                + N',"buildingPaymentTypeID_FK": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"generalNo_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"IDNumber": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @NationalID), '') + N'"'
                + N',"residentInfoID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"unitID": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @unitID), '') + N'"'
                + N',"userName": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  @FullName), '') + N'"'
                + N',"buildingDetailsID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"amount": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @InsertedAmount), '') + N'"'
                + N',"deductListID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingPayementActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @BillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingPayment]'
                , @Action
                , @NewID1
                , @entryData
                , @Note
            );






            
               INSERT INTO [Housing].[BuildingPayment]
            (
                  [buildingPaymentTypeID_FK]
                 ,[generalNo_FK]
                 ,[IDNumber]
                 ,[residentInfoID_FK]
                 ,[unitID]
                 ,[userName]
                 ,[buildingDetailsID_FK]
                 ,[amount]
                 ,[deductListID_FK]
                 ,[buildingPayementActive]
                 ,[BillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @PaymentType,
                 @GeneralNo,
                 @NationalID,
                 @residentInfoID,
                 @unitID,
                 @FullName,
                 @buildingDetailsID,
                 @AmountForToChargeType,
                 @NewID,
                 1,
                 @ToBillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                 ;THROW 50002, N'حصل خطأ في عملية الدفع او الاعادة - BuildingPayment',  1; -- برمجي/غير متوقع
            END

            set @NewID2 = SCOPE_IDENTITY();

             SET @Note = N'{'
                + N'"paymentID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID2), '') + N'"'
                + N',"buildingPaymentTypeID_FK": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"generalNo_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"IDNumber": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @NationalID), '') + N'"'
                + N',"residentInfoID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"unitID": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @unitID), '') + N'"'
                + N',"userName": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  @FullName), '') + N'"'
                + N',"buildingDetailsID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"amount": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @AmountForToChargeType), '') + N'"'
                + N',"deductListID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingPayementActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @ToBillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingPayment]'
                , @Action
                , @NewID2
                , @entryData
                , @Note
            );


           

            SELECT 1 AS IsSuccessful, N'تم تنفيذ التسوية المالية بنجاح' AS Message_;
            RETURN;
        END





          
        
       

        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[FinancialAuditForUserDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[FinancialAuditForUserDL] 
	-- Add the parameters for the stored procedure here
	  @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      BIGINT
    , @hostname       NVARCHAR(400)
	, @NationalID      NVARCHAR(20) = NULL
    
    
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	    -- MeterReadForOccubentAndExit Data
 -- HousingExtend Data
        -- FinancialAuditForExtendAndEvictions Data

       


        Declare @buildingDetailsID   BIGINT, @residentInfoID   BIGINT

         set @residentInfoID = (select Top(1) f.residentInfoID 
        from Housing.V_GetFullResidentDetails f 
        where f.NationalID = @NationalID
        order by f.residentDetailsID desc)


        set @buildingDetailsID = (
        select Top(1) w.buildingDetailsID 
        from Housing.V_WaitingList w 
        where w.residentInfoID = @residentInfoID --and w.LastActionTypeID in (51,57) 
        order by w.LastActionID desc)


        

        ------------------------------1--------------------------------------------
       
             SELECT top(1)
               ROW_NUMBER() OVER (ORDER BY w.LastActionID DESC) AS order_
                , fr.residentInfoID [residentInfoID]
                ,fr.NationalID [NationalID]
                ,fr.generalNo_FK [generalNo_FK]
                ,fr.firstName_A [firstName_A]
                ,fr.secondName_A [secondName_A]
                ,fr.thirdName_A [thirdName_A]
                ,fr.lastName_A [lastName_A]
                ,fr.firstName_E [firstName_E]
                ,fr.secondName_E [secondName_E]
                ,fr.thirdName_E [thirdName_E]
                ,fr.lastName_E [lastName_E]
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_A,
                     fr.secondName_A,
                     fr.thirdName_A,
                     fr.lastName_A
                 )
                 )) AS FullName_A
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_E,
                     fr.secondName_E,
                     fr.thirdName_E,
                     fr.lastName_E
                 )
                 )) AS FullName_E
                ,fr.rankID_FK [rankID_FK]
                ,fr.rankNameA
                ,fr.militaryUnitID_FK [militaryUnitID_FK]
                ,fr.militaryUnitName_A
                ,fr.martialStatusID_FK [martialStatusID_FK]
                ,fr.maritalStatusName_A
                ,fr.dependinceCounter [dependinceCounter]
                ,fr.nationalityID_FK [nationalityID_FK]
                ,fr.nationalityName_A
                ,fr.genderID_FK [genderID_FK]
                ,fr.genderName_A
                ,convert(nvarchar(10),fr.birthdate,23) birthdate
                ,fr.residentcontactDetails
                ,fr.note [note]
                ,fr.IdaraID IdaraID
                ,fr.IdaraName IdaraName
                --,w.buildingDetailsID
                --,w.buildingDetailsNo
                --,r.buildingRentAmount
                ,w.LastActionID
                ,w.LastActionTypeID
                ,w.ActionID
                ,convert(nvarchar(10),w.LastActionDate,23) LastActionDate
                ,w.LastActionExtendReasonTypeID
                
           FROM [DATACORE].[Housing].V_WaitingList w
           inner join [DATACORE].[Housing].V_GetFullResidentDetails fr on fr.residentInfoID = w.residentInfoID
           --inner join Housing.V_buildingWithRent r on w.buildingDetailsID = r.buildingDetailsID
           where 
          -- w.LastActionTypeID in (51,57) 
           --and 
           fr.residentInfoID = @residentInfoID
           and fr.IdaraID = @idaraID

           order by w.LastActionID desc

           

           -----------------------------------2-----------------------------------------------------------------------------------------



          
    --    SELECT 
    --        rd.FullName_A+' - '+rd.NationalID+' - '+case when w.LastActionTypeID = 51 then N'امهال' when w.LastActionTypeID = 57 then N'اخلاء' END as FullName_A,
    --        w.residentInfoID
          
    --FROM Housing.V_WaitingList w 
    --INNER JOIN Housing.V_GetFullResidentDetails rd 
    --    ON w.residentInfoID = rd.residentInfoID
    --    Inner Join Housing.BuildingActionType ba on w.LastActionTypeID = ba.buildingActionTypeID
    --WHERE w.IdaraId = @idaraID
    --  AND  w.LastActionTypeID in (51,57)
    --  order by   w.waitingClassSequence asc


      --or w.LastActionTypeID in (2,3,18,19,20,21,22,23,24,26,27,28,33,34,35)


--------------------------------------3--------------------------------------------------------------------------------------------------------------

IF @residentInfoID IS NOT NULL
Begin

SELECT 
       ROW_NUMBER() OVER (ORDER BY bt.BillChargeTypeID ASC) AS order_
      ,ISNULL(s.[residentInfoID], @residentInfoID) AS residentInfoID
      ,bt.[BillChargeTypeID]
      ,bt.[BillChargeTypeName_A]
      ,ISNULL(s.[buildingDetailsID], -1) AS buildingDetailsID 
      ,ISNULL(b.buildingDetailsNo, N'لايوجد') AS buildingDetailsNo 
      ,ISNULL(s.[SumBillsTotalPrice], 0) AS SumBillsTotalPrice
      ,ISNULL(s.[SumTotalPaidBills], 0) AS SumTotalPaidBills
      --,ISNULL(s.[Remaining], 0) AS Remaining
      ,case
        when ISNULL(s.[Remaining], 0) < 0 then ISNULL(s.[Remaining], 0) * -1
        else ISNULL(s.[Remaining], 0)
        end as Remaining
      ,CASE
          WHEN ISNULL(s.[Remaining], 0) > 0 THEN N'فواتير ' + bt.BillChargeTypeName_A + N' مستحقة للادارة'
          WHEN ISNULL(s.[Remaining], 0) < 0 THEN N'فواتير ' + bt.BillChargeTypeName_A + N' زائدة للمستفيد'
          ELSE N'لايوجد مطالبات'
       END AS BillsStatus
      ,CASE
          WHEN ISNULL(s.[Remaining], 0) > 0 THEN 0
          WHEN ISNULL(s.[Remaining], 0) < 0 THEN 1
          ELSE 2
       END AS BillsStatusID
FROM Housing.BillChargeType bt
LEFT JOIN Housing.V_SumBillsTotalPriceAndTotalPaidForResident s
       ON s.BillChargeTypeID = bt.BillChargeTypeID
      AND s.residentInfoID = @residentInfoID
     -- AND (s.buildingDetailsID = @buildingDetailsID OR s.buildingDetailsID IS NULL)
LEFT JOIN Housing.V_GetGeneralListForBuilding b
       ON s.buildingDetailsID = b.buildingDetailsID
ORDER BY bt.BillChargeTypeID ASC;
END




--------------------------------------4--------------------------------------------------------------------------------------------------------------


         SELECT
      ROW_NUMBER() OVER (ORDER BY w.LastActionID DESC) AS order_,
        (([TotalRentBillsAmount]+[TotalServiceBillsAmount]) - ([TotalRentBillsPaid]+[TotalServiceBillsPaid])) AllAmountresidual
      
      ,([TotalRentBillsAmount] - [TotalRentBillsPaid]) RentBillsAmountresidual
      ,([TotalServiceBillsAmount] - [TotalServiceBillsPaid]) ServiceBillsAmountresidual


        FROM [DATACORE].[Housing].V_WaitingList w
        inner join [DATACORE].[Housing].V_GetFullResidentDetails fr on fr.residentInfoID = w.residentInfoID
        inner join [DATACORE].[Housing].[V_ResidentFinancialSummary] s on fr.residentInfoID = s.residentInfoID

        where s.residentInfoID = @residentInfoID
        AND  w.LastActionTypeID in (51,57)
        and fr.IdaraID = @idaraID




        ------------------------------5----------------------------------------------------------------------------------------------------------------------

        select 
        t.billPaymentTypeID,
        t.billPaymentTypeName_A
        from Housing.billPaymentType t 
        where t.billPaymentDestainationID_FK = 1
        

        ------------------------------6----------------------------------------------------------------------------------------------------------------------

         select 
        t.billPaymentTypeID,
        t.billPaymentTypeName_A
        from Housing.billPaymentType t 
        where t.billPaymentDestainationID_FK = 2
     
     ------------------------------------7----------------------------------------------------------------------------------------------------------------
     select 
        t.billPaymentTypeID,
        t.billPaymentTypeName_A
        from Housing.billPaymentType t 
        where t.billPaymentTypeID in(1,2,5)

        ---------------------------------8-------------------------------------------------------------------------------------------------------------------
    Select e.BillChargeTypeID,e.BillChargeTypeName_A 
      from Housing.BillChargeType e
      where e.BillChargeTypeActive  = 1

    
    
    --select r.buildingRentAmount * 40 insuranceRentAmount,r.buildingRentAmount

     --FROM [DATACORE].[Housing].V_WaitingList w
     --   inner join [DATACORE].[Housing].V_GetFullResidentDetails fr on fr.residentInfoID = w.residentInfoID
     --   inner join [DATACORE].[Housing].[V_ResidentFinancialSummary] s on fr.residentInfoID = s.residentInfoID
     --   inner join Housing.V_buildingWithRent r on w.buildingDetailsID = r.buildingDetailsID
     --   where s.residentInfoID = @residentInfoID
     --   AND  w.LastActionTypeID in (51,57)
     --   and fr.IdaraID = @idaraID




        ----------------------------------9------------------------------------------------------------------------------------------------------------------
      Select e.ExtendReasonTypeID,e.ExtendReasonTypeName_A 
      from Housing.ExtendReasonType e
      where e.Active = 1

       
        ----------------------------------10------------------------------------------------------------------------------------------------------------------
      
      
     select alls.order_
     ,alls.residentInfoID
     ,b.buildingDetailsNo
     ,r.buildingRentAmount
     ,alls.buildingDetailsID
     ,alls.SumBillsTotalPrice
     ,alls.SumTotalPaidBills
     ,alls.Remaining
     ,alls.BillsStatus
     ,alls.BillsStatusID

     From( 
      SELECT 
      ROW_NUMBER() OVER (ORDER BY e.residentInfoID DESC) AS order_,
    e.residentInfoID,e.buildingDetailsID,
    SUM(e.SumBillsTotalPrice) AS SumBillsTotalPrice,
    SUM(e.SumTotalPaidBills) AS SumTotalPaidBills,
    case
        when SUM(e.Remaining) < 0 then SUM(e.Remaining) * -1
        else SUM(e.Remaining)
    end as Remaining,
    --SUM(e.Remaining) AS Remaining,
    CASE 
        WHEN SUM(e.Remaining) > 0 THEN N'مطالب بمبالغ للادارة'
        WHEN SUM(e.Remaining) < 0 THEN N'يوجد مبالغ زائدة للمستفيد'
        ELSE N'لايوجد مطالبات'
    END AS BillsStatus,
    CASE 
        WHEN SUM(e.Remaining) > 0 THEN 0
        WHEN SUM(e.Remaining) < 0 THEN 1
        ELSE 2
    END AS BillsStatusID
FROM Housing.V_SumBillsTotalPriceAndTotalPaidForResident e
WHERE e.residentInfoID = @residentInfoID
--AND (e.buildingDetailsID = @buildingDetailsID OR e.buildingDetailsID IS NULL)
GROUP BY e.residentInfoID,e.buildingDetailsID) alls
left join Housing.V_GetGeneralListForBuilding b on alls.buildingDetailsID = b.buildingDetailsID
left join Housing.V_buildingWithRent r on b.buildingDetailsID = r.buildingDetailsID
;
     


 ----------------------------------11--------------------------------------------------------------------
 


END
GO
/****** Object:  StoredProcedure [Housing].[FinancialAuditForUserSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[FinancialAuditForUserSP] 
(
      @Action                               NVARCHAR(200)
    , @ActionID                             BIGINT          = NULL
    , @residentInfoID                       NVARCHAR(100)   = NULL
    , @buildingDetailsID                    NVARCHAR(1000)  = NULL
    , @LastActionID                         NVARCHAR(1000)  = NULL
    , @LastActionTypeID                     NVARCHAR(1000)  = NULL
    , @Notes                                NVARCHAR(1000)  = NULL
    , @ExitDate                             NVARCHAR(1000)  = NULL
    , @LastActionExtendReasonTypeID         NVARCHAR(1000)  = NULL
    , @PaymentType                          NVARCHAR(1000)  = NULL
    , @PaymentNo                            NVARCHAR(1000)  = NULL
    , @PaymentDate                          NVARCHAR(1000)  = NULL
    , @Amount                               NVARCHAR(1000)  = NULL
    , @FullRemining                         NVARCHAR(1000)  = NULL
    , @BillChargeTypeID_FK                  NVARCHAR(1000)  = NULL
    , @ToBillChargeTypeID_FK                NVARCHAR(1000)  = NULL
    , @description                          NVARCHAR(4000)  = NULL
    , @idaraID_FK                           NVARCHAR(10)    = NULL
    , @entryData                            NVARCHAR(20)    = NULL
    , @hostName                             NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL,
          @NewID1 BIGINT = NULL,
          @NewID2 BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));
    DECLARE @DeductType_INT INT = (select t.deductTypeID_FK from Housing.BuildingPaymentType t where t.buildingPaymentTypeID = @PaymentType);


    DECLARE @Amount_Decimal DECIMAL(18,2);

    SET @Amount_Decimal = TRY_CONVERT(DECIMAL(18,2), @Amount);
    
    IF @Amount_Decimal IS NULL
    BEGIN
        ;THROW 50001, N'قيمة المبلغ غير صحيحة', 1;
    END


    
   
    

    DECLARE @buildingDetailsNo nvarchar(200)
            , @NationalID                           NVARCHAR(100)   
            , @GeneralNo                            NVARCHAR(100)   
            , @WaitingClassID                       NVARCHAR(1000)  
            , @WaitingClassName                     NVARCHAR(1000)  
            , @WaitingOrderTypeID                   NVARCHAR(1000)  
            , @WaitingOrderTypeName                 NVARCHAR(1000)  
            , @waitingClassSequence                 NVARCHAR(1000)  
            , @WaitingListOrder                     NVARCHAR(1000)  
            , @FullName_A                           NVARCHAR(1000)  
            , @AssignPeriodID                       NVARCHAR(1000)  
            , @ExtendStartDate                      NVARCHAR(1000)
            , @ExtendEndDate                        NVARCHAR(1000)
            , @ExtendLetterNo                       NVARCHAR(1000)
            , @ExtendLetterDate                     NVARCHAR(1000)
            , @unitID                               NVARCHAR(1000)
            , @FullName                             NVARCHAR(1000)
            
            
    select 
    --@NationalID               = w.NationalID,
    --@GeneralNo                = w.GeneralNo,
    @WaitingClassID           = w.WaitingClassID,
    @WaitingClassName         = w.WaitingClassName,
    @WaitingOrderTypeID       = w.WaitingOrderTypeID,
    @WaitingOrderTypeName     = w.WaitingClassName,
    @waitingClassSequence     = w.waitingClassSequence,
    @FullName_A               = w.fullname,
    @AssignPeriodID           = w.AssignPeriodID,
    @ExtendStartDate          = w.buildingActionFromDate,
    @ExtendEndDate            = w.buildingActionToDate,
    @ExtendLetterNo           = w.ActionDecisionNo,
    @ExtendLetterDate         = w.ActionDecisionDate,
    @buildingDetailsNo         = w.buildingDetailsNo

    from Housing.V_WaitingList w
    where 
    w.LastActionID = @LastActionID
    and 
    w.ActionID = @ActionID
    and 
    w.residentInfoID = @residentInfoID
    and 
    w.buildingDetailsID = @buildingDetailsID
    and 
    w.LastActionTypeID = @LastActionTypeID
    and 
    w.IdaraId = @idaraID_FK



              
    select 
    @NationalID               = w.NationalID,
    @GeneralNo                = w.generalNo_FK,
    @unitiD                   = w.militaryUnitID_FK,
    @FullName                 = w.FullName_A
    FROM Housing.V_GetFullResidentDetails w
    where w.residentInfoID = @residentInfoID

   
    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

   


        -- IF @Action IN(N'NewExtend',N'EditExtend',N'SendExtendToFinance')
        --BEGIN
         
           


        --END

        

     

        ----------------------------------------------------------------
        -- FINANCIALAUDITFOREXTENDANDEVICTIONS
        ----------------------------------------------------------------
        IF @Action = N'FinancialAuditForUser'
        BEGIN
       


            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@residentInfoID)), N'') IS NULL
             BEGIN
                 ;THROW 50001, N'رقم الساكن مطلوب', 1;
             END


              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) Not in (51,57)
            BEGIN
                ;THROW 50001, N'تم انهاء اجراءات الامهال / الاخلاء مسبقا', 1;
            END



            Declare @buildingActionTypeID_FK INT

            select 
            @buildingActionTypeID_FK =
            case 
            when w.LastActionTypeID = 51  then 52
            when w.LastActionTypeID = 57  then 58
            else 
            9999
            END
            from Housing.V_WaitingList w
            where w.residentInfoID = @residentInfoID

            IF 
            (
               @buildingActionTypeID_FK = 9999 
            )
            BEGIN
                ;THROW 50001, N'حصل خطأ ما building Action Type', 1;
            END

          

            IF(@buildingActionTypeID_FK = 52)
            begin


              INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , buildingActionFromDate
                , buildingActionToDate
                , ExtendReasonTypeID_FK
                , IdaraId_FK
                , entryData
                , hostName
            )
            
             VALUES
            (
                  @buildingActionTypeID_FK
                , @residentInfoID
                , @GeneralNo
                , @ExtendLetterNo
                , @ExtendLetterDate
                , @buildingDetailsID
                , @buildingDetailsNo
                , 1
                , @Notes
                , @LastActionID
                , @ExtendStartDate
                , @ExtendEndDate
                , @LastActionExtendReasonTypeID
                , @IdaraID_INT
                , @entryData
                , @hostName
            );


            
            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اعتماد التدقيق المالي للامهال ', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اعتماد التدقيق المالي للامهال - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionTypeID_FK), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendLetterNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendLetterDate), '') + N'"'
                + N',"buildingDetailsID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"buildingDetailsNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsNo), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"buildingActionNote": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @LastActionID), '') + N'"'
                + N',"buildingActionFromDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendStartDate), '') + N'"'
                + N',"buildingActionToDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendEndDate), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'ASSIGNHOUSE'
                , @ActionID
                , @entryData
                , @Note
            );
            

            SELECT 1 AS IsSuccessful, N'تم اعتماد التدقيق المالي للامهال بنجاح' AS Message_;
            RETURN;

            END



            ELSE IF(@buildingActionTypeID_FK = 58)
            begin


              INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , buildingActionDate
                , ExtendReasonTypeID_FK
                , IdaraId_FK
                , entryData
                , hostName
            )
            
             VALUES
            (
                  @buildingActionTypeID_FK
                , @residentInfoID
                , @GeneralNo
                , @buildingDetailsID
                , @buildingDetailsNo
                , 1
                , @Notes
                , @LastActionID
                , @ExitDate
                , @LastActionExtendReasonTypeID
                , @IdaraID_INT
                , @entryData
                , @hostName
            );


            
            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اعتماد التدقيق المالي للاخلاء ', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اعتماد التدقيق المالي للاخلاء - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionTypeID_FK), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendLetterNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendLetterDate), '') + N'"'
                + N',"buildingDetailsID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"buildingDetailsNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsNo), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"buildingActionNote": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @LastActionID), '') + N'"'
                + N',"buildingActionFromDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendStartDate), '') + N'"'
                + N',"buildingActionToDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ExtendEndDate), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'ASSIGNHOUSE'
                , @ActionID
                , @entryData
                , @Note
            );
            

            SELECT 1 AS IsSuccessful, N'تم اعتماد التدقيق المالي للاخلاء بنجاح' AS Message_;
            RETURN;

            END
            ELSE
        BEGIN

        SELECT 0 AS IsSuccessful, N'حصل خطأ ما - Not Exit Or Extend' AS Message_;
            RETURN;

        END

        END
       
        

         ----------------------------------------------------------------
        -- PAYMENTANDREFUNDFOREXTENDANDEXIT
        ----------------------------------------------------------------
        ELSE IF @Action = N'PAYMENTANDREFUNDFORUSER'
        BEGIN
          
            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


              IF NULLIF(LTRIM(RTRIM(@residentInfoID)), N'') IS NULL
             BEGIN
                 ;THROW 50001, N'رقم الساكن مطلوب', 1;
             END



              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) Not in (51,57)
            BEGIN
                ;THROW 50001, N'تم انهاء اجراءات الامهال / الاخلاء مسبقا', 1;
            END

            Declare @InsertedAmount decimal(18,2)
             IF (select b.buildingPaymentDestainationID_FK from [DATACORE].[Housing].[BuildingPaymentType] b where b.buildingPaymentTypeID = @PaymentType) = 1
         BEGIN
                set @InsertedAmount = @Amount_Decimal
         END
         ELSE
         BEGIN
                set @InsertedAmount = @Amount_Decimal * -1
         END



         IF (select b.buildingPaymentDestainationID_FK from [DATACORE].[Housing].[BuildingPaymentType] b where b.buildingPaymentTypeID = @PaymentType) = 1
         BEGIN
          INSERT INTO Housing.DeductList
            (
                  [deductTypeID_FK]
                 ,[DeductListStatusID_FK]
                 ,[deductName]
                 ,[amountTypeID_FK]
                 ,[paymentTypeID_FK]
                 ,[issueMonth]
                 ,[issueYear]
                 ,[paymentNo]
                 ,[paymentDate]
                 ,[description]
                 ,[deductActive]
                 ,[BillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @DeductType_INT,
                 2,
                 N'سداد عن طريق صندوق الإدارة',
                 1,
                 @PaymentType,
                 MONTH(GETDATE()),
                 YEAR(GETDATE()),
                 @PaymentNo,
                 @PaymentDate,
                 @description,
                 1,
                 @BillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في دفع المطالبات', 1; -- برمجي/غير متوقع
            END

               set @NewID = SCOPE_IDENTITY();

             SET @Note = N'{'
                + N'"deductListID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"deductTypeID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @DeductType_INT), '') + N'"'
                + N',"deductName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), N'سداد عن طريق صندوق الإدارة'), '') + N'"'
                + N',"amountTypeID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"paymentTypeID_FK": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"issueMonth": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  MONTH(GETDATE())), '') + N'"'
                + N',"issueYear": "'           + ISNULL(CONVERT(NVARCHAR(MAX), YEAR(GETDATE())), '') + N'"'
                + N',"paymentNo": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentNo), '') + N'"'
                + N',"paymentDate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentDate), '') + N'"'
                + N',"description": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @description), '') + N'"'
                + N',"deductActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @BillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[DeductList]'
                , @Action
                , @NewID
                , @entryData
                , @Note
            );


            END
            ELSE
            BEGIN

                 INSERT INTO Housing.DeductList
            (
                  [deductTypeID_FK]
                 ,[DeductListStatusID_FK]
                 ,[deductName]
                 ,[amountTypeID_FK]
                 ,[paymentTypeID_FK]
                 ,[issueMonth]
                 ,[issueYear]
                 ,[paymentNo]
                 ,[paymentDate]
                 ,[description]
                 ,[deductActive]
                 ,[BillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @DeductType_INT,
                 2,
                 N'معالجة واعادة مبالغ زائدة',
                 1,
                 @PaymentType,
                 MONTH(GETDATE()),
                 YEAR(GETDATE()),
                 @PaymentNo,
                 @PaymentDate,
                 @description,
                 1,
                 @BillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                 ;THROW 50002, N'حصل خطأ في اعادة المبالغ',  1; -- برمجي/غير متوقع
            END

            set @NewID = SCOPE_IDENTITY();

             SET @Note = N'{'
                + N'"deductListID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"deductTypeID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @DeductType_INT), '') + N'"'
                + N',"deductName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), N'معالجة واعادة مبالغ زائدة'), '') + N'"'
                + N',"amountTypeID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"paymentTypeID_FK": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"issueMonth": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  MONTH(GETDATE())), '') + N'"'
                + N',"issueYear": "'           + ISNULL(CONVERT(NVARCHAR(MAX), YEAR(GETDATE())), '') + N'"'
                + N',"paymentNo": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentNo), '') + N'"'
                + N',"paymentDate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentDate), '') + N'"'
                + N',"description": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @description), '') + N'"'
                + N',"deductActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @BillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[DeductList]'
                , @Action
                , @NewID
                , @entryData
                , @Note
            );

            END


               INSERT INTO [Housing].[BuildingPayment]
            (
                  [buildingPaymentTypeID_FK]
                 ,[generalNo_FK]
                 ,[IDNumber]
                 ,[residentInfoID_FK]
                 ,[unitID]
                 ,[userName]
                 ,[buildingDetailsID_FK]
                 ,[amount]
                 ,[deductListID_FK]
                 ,[buildingPayementActive]
                 ,[BillChargeTypeID_FK]
                 ,[IdaraId_FK]
                 ,[entryDate]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                 @PaymentType,
                 @GeneralNo,
                 @NationalID,
                 @residentInfoID,
                 @unitID,
                 @FullName,
                 @buildingDetailsID,
                 @InsertedAmount,
                 @NewID,
                 1,
                 @BillChargeTypeID_FK,
                 @IdaraID_INT,
                 GETDATE(),
                 @entryData,
                 @hostName

            )


            IF @@ROWCOUNT = 0
            BEGIN
                 ;THROW 50002, N'حصل خطأ في عملية الدفع او الاعادة - BuildingPayment',  1; -- برمجي/غير متوقع
            END

            set @NewID1 = SCOPE_IDENTITY();

             SET @Note = N'{'
                + N'"paymentID": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @NewID1), '') + N'"'
                + N',"buildingPaymentTypeID_FK": "'            + ISNULL(CONVERT(NVARCHAR(MAX), @PaymentType), '') + N'"'
                + N',"generalNo_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"IDNumber": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @NationalID), '') + N'"'
                + N',"residentInfoID_FK": "'  + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"unitID": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @unitID), '') + N'"'
                + N',"userName": "'      + ISNULL(CONVERT(NVARCHAR(MAX),  @FullName), '') + N'"'
                + N',"buildingDetailsID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"amount": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @InsertedAmount), '') + N'"'
                + N',"deductListID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingPayementActive": "'           + ISNULL(CONVERT(NVARCHAR(MAX), 1), '') + N'"'
                + N',"BillChargeTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @BillChargeTypeID_FK), '') + N'"'
                + N',"IdaraId_FK": "'                      + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                       + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                        + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingPayment]'
                , @Action
                , @NewID1
                , @entryData
                , @Note
            );



           

            SELECT 1 AS IsSuccessful, N'تم تنفيذ العملية بنجاح' AS Message_;
            RETURN;
        END



      
        ----------------------------------------------------------------
        -- FINANCIALSETTLEMENT
        ----------------------------------------------------------------
        ELSE IF @Action = N'FINANCIALSETTLEMENTFORUSER'
        BEGIN
          
            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


              IF NULLIF(LTRIM(RTRIM(@residentInfoID)), N'') IS NULL
             BEGIN
                 ;THROW 50001, N'رقم الساكن مطلوب', 1;
             END

             
              IF @BillChargeTypeID_FK = @ToBillChargeTypeID_FK
             BEGIN
                 ;THROW 50001, N'لايمكن سحب رصيد من الخدمة لنفسها', 1;
             END


              DECLARE @FullRemining_Decimal DECIMAL(18,2);

    SET @FullRemining_Decimal = TRY_CONVERT(DECIMAL(18,2), @FullRemining);
    
    IF @FullRemining_Decimal IS NULL
    BEGIN
        ;THROW 50001, N'قيمة المبلغ غير صحيحة', 1;
    END

               IF @Amount_Decimal > @FullRemining_Decimal
             BEGIN
             declare @msg nvarchar(1000)
             set @msg = N'المبلغ المدخل اكبر من المبلغ المتوفر في هذه الخدمه : ' + CONVERT(NVARCHAR(100), @FullRemining_Decimal)
                 ;THROW 50001, @msg, 1;
             END

               IF @Amount_Decimal = 0.00
             BEGIN
              declare @msg3 nvarchar(1000)
             set @msg3 = N'يجب ان يكون المبلغ اكبر من صفر ';
                 ;THROW 50001, @msg3, 1;
             END


         
            Declare @AvailableAmountForToChargeType decimal(18,2);
            set @AvailableAmountForToChargeType = 
            (select TRY_CONVERT(DECIMAL(18,2),s.Remaining) 
               FROM Housing.BillChargeType bt
               LEFT JOIN Housing.V_SumBillsTotalPriceAndTotalPaidForResident s
                      ON s.BillChargeTypeID = bt.BillChargeTypeID
                     AND s.residentInfoID = @residentInfoID
                     AND (s.buildingDetailsID = @buildingDetailsID OR s.buildingDetailsID IS NULL)
               LEFT JOIN Housing.V_GetGeneralListForBuilding b
                      ON s.buildingDetailsID = b.buildingDetailsID
                      where bt.BillChargeTypeID = @ToBillChargeTypeID_FK
             )

                  IF @Amount_Decimal > @AvailableAmountForToChargeType
             BEGIN
             declare @msg1 nvarchar(1000)
             set @msg1 = N'المبلغ المدخل اكبر من المبلغ المطلوب في الخدمه المعالجة والمبلغ المطلوب لسدادها هو : ' + CONVERT(NVARCHAR(100), @AvailableAmountForToChargeType)
                 ;THROW 50001, @msg1, 1;
             END

                 


              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) Not in (51,57)
            BEGIN
                ;THROW 50001, N'تم انهاء اجراءات الامهال / الاخلاء مسبقا', 1;
            END

            Declare @AmountForFromChargeType decimal(18,2),@AmountForToChargeType decimal(18,2)
            
                set @AmountForFromChargeType = @Amount_Decimal * -1

                set @AmountForToChargeType = @Amount_Decimal
         
 


         Declare @FromChargeTypeName nvarchar(1000) ,@ToChargeTypeName nvarchar(1000),@msgChargeType nvarchar(2000) 
         
         set @ToChargeTypeName = (select v.BillChargeTypeName_A from Housing.BillChargeType v where v.BillChargeTypeID = @ToBillChargeTypeID_FK)
         set @FromChargeTypeName = (select v.BillChargeTypeName_A from Housing.BillChargeType v where v.BillChargeTypeID = @BillChargeTypeID_FK)
         set @msgChargeType = N'تسوية مالية من ' + ISNULL(@FromChargeTypeName,'') + N' الى ' + ISNULL(@ToChargeTypeName,'')


          INSERT INTO Housing.DeductList
