/****** Object:  StoredProcedure [Housing].[HousingExitDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[HousingExitDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
    , @NationalID NVARCHAR(400)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

 -- HousingExit Data

 Declare @residentInfoID Bigint
 Set @residentInfoID = (select f.residentInfoID from  Housing.V_GetFullResidentDetails f where f.NationalID = @NationalID)

            SELECT 

            w.ActionID,
            ROW_NUMBER() OVER (
            ORDER BY w.ActionDecisionDate ASC, w.GeneralNo ASC
            ) AS WaitingListOrder,
            rd.FullName_A as FullName_A,
            w.NationalID,
            w.GeneralNo,
             case 
            when w.LastActionTypeID in (2,48,49,50,51,52,24) then Null
            else
            w.LastActionDecisionNo
            END LastActionDecisionNo,
            case 
            when w.LastActionTypeID in (2,48,49,50,51,52,24) then Null
            else
            convert(nvarchar(10),w.[LastActionDecisionDate],23) 
            END LastActionDecisionDate,
            w.WaitingClassID,
            w.WaitingClassName,
            w.WaitingOrderTypeID,
            w.WaitingOrderTypeName,
            w.waitingClassSequence,
            w.residentInfoID,
             case 
            when w.LastActionTypeID is null Then N'0' 
            ELSE
            w.LastActionTypeID
            END LastActionTypeID,


            w.LastActionID,
            case 
            when w.LastActionTypeID in (54,55,56,57,58,59,60,3) Then convert(nvarchar(10),w.LastActionDate,23)
            ELSE
            Null
            END LastActionDate,
           
            case 
            when w.LastActionTypeID in (48,49,50,51,52) Then N'تحت اجراءات الامهال' 
            when w.LastActionTypeID is null Then N'لازال بقائمة الانتظار' 
            ELSE
            ba.buildingActionTypeResidentAlias
            END buildingActionTypeResidentAlias
            ,
            w.buildingDetailsID,
            w.buildingDetailsNo,
            case 
            when w.LastActionTypeID in (2,48,49,50,51,52,24,54,55,56,57,58,59,60,3) then Null
            else
           isnull(w.LastActionNote,w.ActionNote)
            END ActionNote,

             case 
            when w.LastActionTypeID in (2,24) then 1
            else
            0
            END CanExit,
            b.TotalPrice penaltyPrice ,
            b.BillsID,
            b.PenaltyReason,
            

            w.IdaraId,
            (select count(*) from Housing.MeterForBuilding m 
            where m.buildingDetailsID_FK = w.buildingDetailsID 
            and m.IdaraID_FK = w.IdaraId 
            and m.meterForBuildingActive = 1) meterscount,
            convert(nvarchar(10),w.OccupentDate,23) OccupentDate,
            convert(nvarchar(10),w.ExitDate,23) ExitDate
           
            
            
    FROM Housing.V_WaitingList w 
    INNER JOIN Housing.V_GetFullResidentDetails rd 
        ON w.residentInfoID = rd.residentInfoID
        left Join Housing.BuildingActionType ba on w.LastActionTypeID = ba.buildingActionTypeID
        left join Housing.Bills b on w.residentInfoID = b.residentInfoID_FK and w.buildingDetailsID = b.buildingDetailsID and b.BillChargeTypeID_FK = 5 and b.BillActive = 1
    WHERE w.IdaraId = @idaraID
    and (w.buildingActionRoot = 2 or w.buildingActionRoot = 3)
      --AND  (w.LastActionTypeID in (2,24))
           --AND  (w.LastActionTypeID in (2,48,49,50,51,52,24,54,55,56,57,58,59,60) or w.LastActionTypeID is null)

     --AND  (w.LastActionTypeID in (2,48,49,50,51,52,24,54,55,56,57,58,59,60,3) or w.LastActionTypeID is null)
      AND w.residentInfoID = @residentInfoID
      order by w.LastActionEntryDate desc






END
GO
/****** Object:  StoredProcedure [Housing].[HousingExitSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[HousingExitSP] 
(
      @Action                               NVARCHAR(200)
    , @ActionID                             BIGINT          = NULL
    , @residentInfoID                       NVARCHAR(100)   = NULL
    , @NationalID                           NVARCHAR(100)   = NULL
    , @GeneralNo                            NVARCHAR(100)   = NULL
    , @WaitingClassID                       NVARCHAR(1000)  = NULL
    , @WaitingClassName                     NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeID                   NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeName                 NVARCHAR(1000)  = NULL
    , @waitingClassSequence                 NVARCHAR(1000)  = NULL
    , @WaitingListOrder                     NVARCHAR(1000)  = NULL
    , @FullName_A                           NVARCHAR(1000)  = NULL
    , @buildingDetailsID                    NVARCHAR(1000)  = NULL
    , @AssignPeriodID                       NVARCHAR(1000)  = NULL
    , @LastActionID                         NVARCHAR(1000)  = NULL
    , @LastActionTypeID                     NVARCHAR(1000)  = NULL
    , @Notes                                NVARCHAR(1000)  = NULL
    , @ExitDate                             NVARCHAR(1000)  = NULL
    , @PenaltyPrice                         NVARCHAR(1000)  = NULL
    , @PenaltyReason                        NVARCHAR(4000)  = NULL
    , @BillsID                              NVARCHAR(4000)  = NULL
    , @OccupentDate                         NVARCHAR(4000)  = NULL
    , @FinalExitDate                        NVARCHAR(4000)  = NULL
    , @idaraID_FK                           NVARCHAR(10)    = NULL
    , @entryData                            NVARCHAR(20)    = NULL
    , @hostName                             NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));

    DECLARE @buildingDetailsNo nvarchar(200) 
    set @buildingDetailsNo = (select b.buildingDetailsNo from Housing.V_GetGeneralListForBuilding b where b.buildingDetailsID = @buildingDetailsID);

DECLARE @Clean NVARCHAR(100) =
    LTRIM(RTRIM(NULLIF(@PenaltyPrice, '')));

-- إزالة المسافات
SET @Clean = REPLACE(@Clean, ' ', '');

IF @Clean IS NOT NULL
BEGIN
    DECLARE @LastComma INT = LEN(@Clean) - CHARINDEX(',', REVERSE(@Clean)) + 1;
    DECLARE @LastDot   INT = LEN(@Clean) - CHARINDEX('.', REVERSE(@Clean)) + 1;

    IF CHARINDEX(',', @Clean) > 0 AND CHARINDEX('.', @Clean) > 0
    BEGIN
        -- إذا النقطة هي الأخيرة → تنسيق أمريكي
        IF @LastDot > @LastComma
        BEGIN
            -- إزالة فواصل الآلاف
            SET @Clean = REPLACE(@Clean, ',', '');
        END
        ELSE
        BEGIN
            -- تنسيق أوروبي
            SET @Clean = REPLACE(@Clean, '.', '');
            SET @Clean = REPLACE(@Clean, ',', '.');
        END
    END
    ELSE
    BEGIN
        -- حالة وجود فاصلة واحدة فقط (آلاف)
        SET @Clean = REPLACE(@Clean, ',', '');
    END
END

DECLARE @PenaltyPriceDecimal DECIMAL(18,2) =
    TRY_CONVERT(DECIMAL(18,2), @Clean);


    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

   


         IF @Action IN(N'HOUSINGEXIT',N'EditExtend',N'SendExtendToFinance',N'ApproveExtend')
        BEGIN
         
            IF NULLIF(LTRIM(RTRIM(@ExitDate)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يجب كتابة تاريخ الاخلاء', 1;
            END

        END

        

     

        ----------------------------------------------------------------
        -- HOUSINGEXIT
        ----------------------------------------------------------------
        IF @Action = N'HOUSINGEXIT'
        BEGIN
       


            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) Not in (2,24)
            BEGIN
                ;THROW 50001, N'المستفيد غير مؤهل للاخلاء او تم اخلائه مسبقا', 1;
            END



            Declare @buildingActionTypeID_FK INT

            select 
            @buildingActionTypeID_FK =
            case 
            when w.LastActionTypeID = 2  then 54
            when w.LastActionTypeID = 24  then 54
            else 
            9999
            END
            from Housing.V_WaitingList w
            where w.residentInfoID = @residentInfoID

            IF 
            (
               @buildingActionTypeID_FK = 9999 
            )
            BEGIN
