/****** Object:  StoredProcedure [Housing].[HousingHandoverDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[HousingHandoverDL] 
	-- Add the parameters for the stored procedure here
	  @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
	, @LastActionTypeID  INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   
  -- Buildinghandover Data

          select distinct
		  b.buildingDetailsID,
		  b.buildingDetailsNo,
		  b.militaryLocationName_A,
		  b.militaryAreaCityName_A,
		  b.militaryAreaName_A,
		  b.buildingUtilityTypeName_A,
		  b.LastActionTypeID,
		  b.LastActionTypeName,
		  b.LastActionTypeBuildingAlias,
		  b.LastActionID,
		  b.LastActionNote,
		  convert(nvarchar(10),b.LastActionEntryDate,23) +N'  '+ convert(nvarchar(10),b.LastActionEntryDate,8) as LastActionEntryDatestring,
		  b.LastActionEntryDate
		  
		  
		  from [Housing].[V_GetGeneralListForBuilding] b
		  left join housing.Buildinghandover h on h.BuildingActionTypeID_FK = b.LastActionTypeID
		  where h.BuildinghandoverActive = 1
		  and b.buildingDetailsActive = 1
		  and b.LastActionTypeID = @LastActionTypeID
		  and b.BuildingIdaraID = @idaraID
		  and h.PermissionTypeID_FK 
		  in (select distinct d.permissionTypeID from dbo.V_GetListUserPermission d where d.permissionTypeRoleID = 20 and d.userID = @entrydata)
		  order by b.LastActionEntryDate desc

		  --------------------------

		   select distinct
		  
		  h.BuildingActionTypeID_FK,
		  t.buildingActionTypeBuildingAlias
		
		  
		  from 
		  housing.Buildinghandover h 
		  inner join Housing.BuildingActionType t on t.BuildingActionTypeID = h.BuildingActionTypeID_FK
		  where h.BuildinghandoverActive = 1
		  and h.IdaraID_FK = @idaraID
		  and h.PermissionTypeID_FK 
		  in (select distinct d.permissionTypeID from dbo.V_GetListUserPermission d where d.permissionTypeRoleID = 20 and d.userID = @entrydata)

		  
		  order by h.BuildingActionTypeID_FK asc

		  ----------------------------------

		  select distinct 
		  h.NextBuildingActionTypeID_FK,
		  t.buildingActionTypeName_A,
		  h.BuildingActionTypeID_FK
		  from [Housing].[Buildinghandover] h
		  inner join Housing.BuildingActionType t on t.BuildingActionTypeID = h.NextBuildingActionTypeID_FK
		  where h.BuildinghandoverActive = 1
		  and h.BuildingActionTypeID_FK = @LastActionTypeID
		  and h.IdaraID_FK = @idaraID

		  order by h.NextBuildingActionTypeID_FK asc

		

   
END
GO
/****** Object:  StoredProcedure [Housing].[HousingHandoverSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[HousingHandoverSP] 
(
      @Action                               NVARCHAR(200)
    , @buildingDetailsID                    NVARCHAR(100)   = NULL
    , @buildingDetailsNo                    NVARCHAR(100)   = NULL
    , @LastActionTypeID                     NVARCHAR(100)   = NULL
    , @NextActionTypeID                     NVARCHAR(1000)  = NULL
    , @LastActionID                         NVARCHAR(100)   = NULL
    , @Notes                                NVARCHAR(1000)  = NULL
    , @idaraID_FK                           NVARCHAR(10)    = NULL
    , @entryData                            NVARCHAR(20)    = NULL
    , @hostName                             NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL
        , @Identity_insert bigint;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));
    DECLARE @buildingStatusID INT = (select b.buildingStatusID_FK from Housing.BuildingActionType b where b.buildingActionTypeID = @NextActionTypeID);
   
    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END


         IF @Action IN(N'HousingHandoverAction')
        BEGIN
         
            IF NULLIF(LTRIM(RTRIM(@buildingDetailsID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'الرقم المرجعي للمبنى مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@buildingDetailsNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'رقم المبنى مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@LastActionTypeID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'الحالة الاخيرة مطلوبة', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@NextActionTypeID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'الحالة القادمة مطلوبة', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@Notes)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'الملاحظات مطلوبة', 1;
            END

           
        END

        ----------------------------------------------------------------
        -- OPENASSIGNPERIOD
        ----------------------------------------------------------------
        IF @Action = N'HousingHandoverAction'
        BEGIN


          IF EXISTS
            (
                SELECT 1
                FROM  Housing.BuildingAction a
                WHERE a.buildingActionParentID = @LastActionID
                  
            )
            BEGIN
                ;THROW 50001, N'تم تنفيذ هذا الاجراء مسبقا', 1;
            END


            INSERT INTO [Housing].[BuildingAction]
            (
                 [buildingActionTypeID_FK]
                ,[buildingStatusID_FK]
                ,[buildingDetailsID_FK]
                ,[buildingDetailsNo]
                ,[buildingActionDate]
                ,[buildingActionNote]
                ,[buildingActionActive]
                ,[buildingActionParentID]
                ,[IdaraId_FK]
                ,[entryDate]
                ,[entryData]
                ,[hostName]
            )
            VALUES
            (
                  @NextActionTypeID
                , @buildingStatusID
                , @buildingDetailsID
                , @buildingDetailsNo
                , GETDATE()
                , @Notes
                , 1
                , @LastActionID
                , @IdaraID_INT
                , GETDATE()
                , @entryData
                , @hostName
            );

            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اتخاذ الاجراء - BuildingAction', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NextActionTypeID), '') + N'"'
                + N',"buildingStatusID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @buildingStatusID), '') + N'"'
                + N',"buildingDetailsID_FK": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"buildingDetailsNo": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsNo), '') + N'"'
                + N',"buildingActionDate": "'           + ISNULL(CONVERT(NVARCHAR(MAX), GETDATE()), '') + N'"'
                + N',"buildingActionNote": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @LastActionID), '') + N'"'
                + N',"buildingActionActive": "1"'
                + N',"IdaraId_FK": "'               + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"entryDate": "'                + ISNULL(CONVERT(NVARCHAR(MAX), GETDATE()), '') + N'"'
                + N',"hostName": "'                 + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'HousingHandoverAction'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );

            declare @msg NVARCHAR(1000) = 
            N'تم اتخاذ اجراء للمبنى رقم ' + ISNULL(CONVERT(NVARCHAR(100), @buildingDetailsNo), '') +N' بنجاح ';
            SELECT 1 AS IsSuccessful, @msg AS Message_;
            RETURN;
        END



        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
