CREATE PROCEDURE [Housing].[HousingResidentSP] 
(
      @Action                               NVARCHAR(200)
    , @ActionID                             BIGINT          = NULL
    , @residentInfoID                       NVARCHAR(100)   = NULL
    , @NationalID                           NVARCHAR(100)   = NULL
    , @GeneralNo                            NVARCHAR(100)   = NULL
    , @buildingActionDecisionNo             NVARCHAR(1000)  = NULL
    , @buildingActionDecisionDate           NVARCHAR(1000)  = NULL
    , @WaitingClassID                       NVARCHAR(1000)  = NULL
    , @WaitingClassName                     NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeID                   NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeName                 NVARCHAR(1000)  = NULL
    , @waitingClassSequence                 NVARCHAR(1000)  = NULL
    , @WaitingListOrder                     NVARCHAR(1000)  = NULL
    , @FullName_A                           NVARCHAR(1000)  = NULL
    , @buildingDetailsID                    NVARCHAR(1000)  = NULL
    , @AssignPeriodID                       NVARCHAR(1000)  = NULL
    , @LastActionID                         NVARCHAR(1000)  = NULL
    , @LastActionTypeID                     NVARCHAR(1000)  = NULL
    , @Notes                                NVARCHAR(1000)  = NULL
    , @BuildingActionTypeCases              NVARCHAR(1000)  = NULL
    , @OccupentLetterNo                     NVARCHAR(1000)  = NULL
    , @OccupentLetterDate                   NVARCHAR(1000)  = NULL
    , @OccupentDate                         NVARCHAR(1000)  = NULL
    , @idaraID_FK                           NVARCHAR(10)    = NULL
    , @entryData                            NVARCHAR(20)    = NULL
    , @hostName                             NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));

    DECLARE @buildingDetailsNo nvarchar(200) 
    set @buildingDetailsNo = (select b.buildingDetailsNo from Housing.V_GetGeneralListForBuilding b where b.buildingDetailsID = @buildingDetailsID);

    Declare @HasMeterService int
    set @HasMeterService =(select count(*) 
    from  Housing.MeterForBuilding m 
    where m.buildingDetailsID_FK = @buildingDetailsID 
    and m.meterForBuildingActive = 1 
    and (m.meterForBuildingEndDate is null or cast(m.meterForBuildingEndDate as date) > cast(GETDATE() as date)))

    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

   


         IF @Action IN(N'CustdyRecord')
        BEGIN
         
            IF NULLIF(LTRIM(RTRIM(@Notes)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يجب كتابة العهد والملاحظات على المنزل', 1;
            END

           
        END

        

     

        ----------------------------------------------------------------
        -- CustdyRecord
        ----------------------------------------------------------------
        IF @Action = N'HOUSINGESRESIDENTSCUSTDY'
        BEGIN
       


            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) in (46)
            BEGIN
                ;THROW 50001, N'بانتظار قراءة عدادات الخدمات', 1;
            END



            Declare @buildingActionTypeID_FK INT

            select 
            @buildingActionTypeID_FK =
            case 
            when w.LastActionTypeID = 45 and @HasMeterService > 0 then 46
            when w.LastActionTypeID = 45 and @HasMeterService < 1 then 47 
            else 
            9999
            END
            from Housing.V_WaitingList w
            where w.residentInfoID = @residentInfoID

            IF 
            (
               @buildingActionTypeID_FK = 9999 
            )
            BEGIN
                ;THROW 50001, N'حصل خطأ ما Has Meter Service', 1;
            END

          

            


              INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionActive
                , CustdyRecord
                , buildingActionParentID
                , AssignPeriodID_FK
                , IdaraId_FK
                , entryData
                , hostName
            )
            
             VALUES
            (
                  @buildingActionTypeID_FK
                , @residentInfoID
                , @GeneralNo
                , @buildingActionDecisionNo
                , @buildingActionDecisionDate
                , @buildingDetailsID
                , @buildingDetailsNo
                , 1
                , @Notes
                , @LastActionID
                , @AssignPeriodID
                , @IdaraID_INT
                , @entryData
                , @hostName
            );


            
            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تسجيل العهد والملاحظات', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تسجيل العهد والملاحظات - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionTypeID_FK), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionDate), '') + N'"'
                + N',"buildingDetailsID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"buildingDetailsNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsNo), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"CustdyRecord": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @LastActionID), '') + N'"'
                + N',"AssignPeriodID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @AssignPeriodID), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'HOUSINGESRESIDENTSCUSTDY'
                , @ActionID
                , @entryData
                , @Note
            );
            

            SELECT 1 AS IsSuccessful, N'تم تسجيل العهد والملاحظات بنجاح' AS Message_;
            RETURN;
        END


      
        ----------------------------------------------------------------
        -- FinalOccupent
        ----------------------------------------------------------------
        ELSE IF @Action = N'HOUSINGESRESIDENTS'
        BEGIN
       


            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END


            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


              IF 
            (
               select w.LastActionTypeID from Housing.V_WaitingList w where w.ActionID = @ActionID 
            ) in (46)
            BEGIN
                ;THROW 50001, N'بانتظار قراءة عدادات الخدمات', 1;
            END




              INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionExtraText2
                , buildingActionExtraText3
                , buildingActionDate
                , OccupentDate
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , AssignPeriodID_FK
                , IdaraId_FK
                , entryData
                , hostName
            )
            
             VALUES
            (
                  2
                , @residentInfoID
                , @GeneralNo
                , @buildingActionDecisionNo
                , @buildingActionDecisionDate
                , @buildingDetailsID
                , @buildingDetailsNo
                , @OccupentLetterDate
                , @OccupentLetterNo
                , @OccupentDate
                , @OccupentDate
                , 1
                , @Notes
                , @LastActionID
                , @AssignPeriodID
                , @IdaraID_INT
                , @entryData
                , @hostName
            );

            SET @NewID = SCOPE_IDENTITY();
            
            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تسكين المستفيد بشكل نهائي', 1; -- برمجي
            END

            


            DECLARE @ToDate date = EOMONTH(DATEADD(MONTH, -1, GETDATE()));

            if(@OccupentDate <  @ToDate)
            begin

            -- INSERT INTO [DATACORE].[Housing].[RentBills]
            --(
            --      [residentInfoID_FK]
            --     ,[buildingDetailsID_FK]
            --     ,[buildingRentTypeID_FK]
            --     ,[rentBillsAmount]
            --     ,[rentBillsFromDate]
            --     ,[rentBillsToDate]
            --     ,[rentBillsActive]
            --     ,[idaraID_FK]
            --     ,[entryData]
            --     ,[hostName]
            --)

            
             INSERT INTO [DATACORE].[Housing].[Bills]
            (
                  [residentInfoID_FK]
                 ,[generalNo_FK]
                 ,[buildingDetailsID]
                 ,[BillChargeTypeID_FK]
                 ,[buildingRentTypeID_FK]
                 ,[PeriodMonth]
                 ,[PeriodYear]
                 ,[PRICE]
                 ,[PRICETAX]
                 ,[TotalPrice]
                 ,[BillsFromDate]
                 ,[BillsToDate]
                 ,[BillActive]
                 ,[idaraID_FK]
                 ,[entryData]
                 ,[hostName]
            )
            SELECT 
            @residentInfoID,
            @buildingDetailsID,
            @GeneralNo,
            1,
            1,
            DATEPART(MONTH,r.CalcFromDate),
            DATEPART(YEAR,r.CalcFromDate),
            r.RentForMonth,
            0.00,
            r.RentForMonth,
            r.CalcFromDate,
            r.CalcToDate,
            1,
            @idaraID_FK,
            @entryData,
            @hostName
            FROM Housing.fn_CalcMonthlyBuildingRent_ByBuildingDetailsID(@buildingDetailsID,@OccupentDate, @ToDate) r

             IF (@@ROWCOUNT = 0 )
            BEGIN
                ;THROW 50002, N'حصل خطأ في تسكين المستفيد بشكل نهائي - RentBills', 1; -- برمجي
            END

            end

            --SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تسكين المستفيد بشكل نهائي - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionTypeID_FK), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionDate), '') + N'"'
                + N',"buildingDetailsID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsID), '') + N'"'
                + N',"buildingDetailsNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingDetailsNo), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"CustdyRecord": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @LastActionID), '') + N'"'
                + N',"AssignPeriodID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @AssignPeriodID), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'HOUSINGESRESIDENTS'
                , @ActionID
                , @entryData
                , @Note
            );
            

            SELECT 1 AS IsSuccessful, N'تم تسكين المستفيد بشكل نهائي بنجاح' AS Message_;
            RETURN;
        END


                  
        
       

        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[ImportExcelForBuildingPayment]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[ImportExcelForBuildingPayment]
(
    @NationalIDs NVARCHAR(255) = NULL,
    @UnitNumbers NVARCHAR(255) = NULL,
    @GeneralNumbers NVARCHAR(255) = NULL,
    @Amounts NVARCHAR(255) = NULL,

    @BillChargeTypeID INT = NULL,  
    @IssueMonth NVARCHAR(255) = NULL,
    @IssueYear NVARCHAR(255) = NULL,
    @DeductListNo NVARCHAR(255) = NULL,
    @DeductListDate NVARCHAR(255) = NULL,
    @Notes NVARCHAR(255) = NULL,

    @IdaraId_FK NVARCHAR(255) = NULL,  
    @entryData NVARCHAR(255) = NULL,  
    @hostName NVARCHAR(255) = NULL,  

    @FileHash CHAR(64),
    @OriginalFileName NVARCHAR(260) = NULL,
    @Rows [Housing].[ImportExcelForBuildingPaymentRowType] READONLY
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @StartedTran bit = 0;

    BEGIN TRY
        IF NULLIF(LTRIM(RTRIM(@FileHash)), N'') IS NULL
            THROW 50001, N'بصمة الملف غير موجودة.', 1;

            IF NULLIF(LTRIM(RTRIM(@BillChargeTypeID)), N'') IS NULL
            THROW 50001, N'الرجاء اختيار نوع المسير', 1;

        IF NOT EXISTS (SELECT 1 FROM @Rows)
            THROW 50001, N'لا توجد صفوف للإدخال.', 1;

        IF @@TRANCOUNT = 0
        BEGIN
            SET @StartedTran = 1;
            BEGIN TRAN;
        END

        -- منع استيراد نفس الملف أكثر من مرة فقط
        IF EXISTS (SELECT 1 FROM [Housing].[UploadExcelImportLog] WHERE FileHash = @FileHash)
        BEGIN
            IF @StartedTran = 1 COMMIT;

            SELECT CAST(0 AS bit) AS IsSuccessful,
                   N'تم استيراد نفس الملف سابقاً، ولن يتم تكرار الإدخال.' AS Message_,
                   0 AS InsertedRows;
            RETURN;
        END



        DECLARE @DeductListName NVARCHAR(255) =
    CONCAT(
        N'مسير استقطاع ايجار المساكن برقم ',
        @DeductListNo,
        N' وتاريخ ',
        CONVERT(NVARCHAR(10), @DeductListDate, 111),
        N' لشهر ',
        RIGHT(N'0' + CAST(@IssueMonth AS NVARCHAR(2)), 2),
        N' لعام ',
        @IssueYear,
        N' للإدارة ',
        ISNULL(
            (SELECT TOP (1) a.IdaraName
             FROM dbo.V_GetListIdara a
             WHERE IdaraID = @IdaraId_FK),
            N'غير محددة'
        )
    );




        INSERT INTO [DATACORE].[Housing].[DeductList]
        (
            [deductTypeID_FK],
            [DeductListStatusID_FK],
            [deductName],
            [amountTypeID_FK],
            [paymentTypeID_FK],
            [issueMonth],
            [issueYear],
            [paymentNo],
            [paymentDate],
            [description],
            [deductActive],
            [IdaraId_FK],
            [BillChargeTypeID_FK],
            [entryDate],
            [entryData],
            [hostName]
        )
        VALUES
        (
            1,
            2,
            @DeductListName,
            1,
            1,
            @IssueMonth,
            @IssueYear,
            @DeductListNo,
            @DeductListDate,
            @Notes,
            1,
            @IdaraId_FK,
            @BillChargeTypeID,
            GETDATE(),
            @entryData,
            @hostName
        );

        DECLARE @DeductRows int = @@ROWCOUNT;
        DECLARE @DedcutID bigint = TRY_CONVERT(bigint, SCOPE_IDENTITY());

        IF @DeductRows = 0 OR ISNULL(@DedcutID, 0) < 1
        BEGIN
            IF @StartedTran = 1 COMMIT;

            SELECT CAST(0 AS bit) AS IsSuccessful,
                   N'لم يتم إنشاء سجل الدفعة (DeductList).' AS Message_,
                   0 AS InsertedRows;
            RETURN;
        END

        -- =========================
        -- Clean rows into TEMP table (أفضل أداء من table variable)
        -- =========================
        IF OBJECT_ID('tempdb..#Clean') IS NOT NULL
            DROP TABLE #Clean;

        CREATE TABLE #Clean
        (
            RowNo        int           NOT NULL,
            IDNumber     nvarchar(255) NULL,
            unitID       nvarchar(255) NULL,
            generalNo_FK nvarchar(255) NULL,
            amount       decimal(10,2) NULL,
            amountRaw    nvarchar(255) NULL
        );

        INSERT INTO #Clean (RowNo, IDNumber, unitID, generalNo_FK, amount, amountRaw)
        SELECT
            r.RowNo,
            NULLIF(LTRIM(RTRIM(r.IDNumber)), N''),
            NULLIF(LTRIM(RTRIM(r.unitID)), N''),
            NULLIF(LTRIM(RTRIM(r.generalNo_FK)), N''),
            TRY_CONVERT(decimal(10,2), NULLIF(LTRIM(RTRIM(r.amount)), N'')),
            NULLIF(LTRIM(RTRIM(r.amount)), N'')
        FROM @Rows r
        WHERE NOT
        (
            NULLIF(LTRIM(RTRIM(ISNULL(r.IDNumber,N''))), N'') IS NULL AND
            NULLIF(LTRIM(RTRIM(ISNULL(r.unitID,N''))), N'') IS NULL AND
            NULLIF(LTRIM(RTRIM(ISNULL(r.generalNo_FK,N''))), N'') IS NULL AND
            NULLIF(LTRIM(RTRIM(ISNULL(r.amount,N''))), N'') IS NULL
        );

        -- فهرس لتسريع الربط
        CREATE INDEX IX_Clean_generalNo ON #Clean(generalNo_FK);

        -- ❌ تحقق سريع جدًا: أول مبلغ غير صالح فقط
        IF EXISTS (SELECT 1 FROM #Clean WHERE amountRaw IS NOT NULL AND amount IS NULL)
        BEGIN
            DECLARE @BadRowNo int;
            DECLARE @BadValue nvarchar(255);

            SELECT TOP (1)
                @BadRowNo = RowNo,
                @BadValue = amountRaw
            FROM #Clean
            WHERE amountRaw IS NOT NULL AND amount IS NULL
            ORDER BY RowNo;

            DECLARE @Msg nvarchar(4000) =
                N'يوجد مبلغ غير صالح لا يمكن تحويله إلى رقم (decimal(10,2)). ' +
                N'أول خطأ عند الصف: ' + CAST(@BadRowNo AS nvarchar(20)) +
                N'، القيمة: ' + ISNULL(@BadValue, N'');

            THROW 50001, @Msg, 1;
        END

        INSERT INTO [DATACORE].[Housing].[BuildingPayment]
        (
            [buildingPaymentTypeID_FK],
            [generalNo_FK],
            [IDNumber],
            [residentInfoID_FK],
            [unitID],
            [buildingDetailsID_FK],
            [amount],
            [deductListID_FK],
            [buildingPayementActive],
            [BillChargeTypeID_FK],
            [IdaraId_FK],
            [entryDate],
            [entryData],
            [hostname]
        )
        SELECT
            1,
            c.generalNo_FK,
            c.IDNumber,
            r.residentInfoID,
            c.unitID,
            CASE
                WHEN oc.cnt > 1 THEN NULL
                ELSE o.buildingDetailsID
            END,
            c.amount,
            @DedcutID,
            1,
            @BillChargeTypeID,
            @IdaraId_FK,
            GETDATE(),
            @entryData,
            @hostName
        FROM #Clean AS c
        LEFT JOIN Housing.V_GetFullResidentDetails r
            ON c.generalNo_FK = r.generalNo_FK
        LEFT JOIN Housing.V_WaitingList o
            ON o.residentInfoID = r.residentInfoID
            LEFT JOIN (
                        SELECT
                            residentInfoID,
                            COUNT(*) AS cnt
                        FROM Housing.V_WaitingList
                        GROUP BY residentInfoID
                    ) oc
                        ON oc.residentInfoID = r.residentInfoID;

        DECLARE @Inserted int = @@ROWCOUNT;

        INSERT INTO [Housing].[UploadExcelImportLog] (FileHash, OriginalFileName, InsertedRows)
        VALUES (@FileHash, @OriginalFileName, @Inserted);

        IF @StartedTran = 1 COMMIT;

        SELECT CAST(1 AS bit) AS IsSuccessful,
               CONCAT(N'تم إدخال ', @Inserted, N' صف بنجاح.') AS Message_,
               @Inserted AS InsertedRows;
    END TRY
    BEGIN CATCH
        IF @StartedTran = 1 AND @@TRANCOUNT > 0 ROLLBACK;
        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[ImportExcelForBuildingPaymentDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[ImportExcelForBuildingPaymentDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
	
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   
  -- Assign Data

          
 SELECT  [BillChargeTypeID]
                  ,[BillChargeTypeName_A]
      
        FROM [DATACORE].[Housing].[BillChargeType] 
        where BillChargeTypeActive = 1 and BillChargeTypeID <> 5
        order by BillChargeTypeID asc




         DECLARE @StartYear INT = 2017;
        DECLARE @EndYear   INT = YEAR(GETDATE());
        
        ;WITH YearsCTE AS
        (
            SELECT @StartYear AS Year_
            UNION ALL
            SELECT Year_ + 1
            FROM YearsCTE
            WHERE Year_ + 1 <= @EndYear
        )
        SELECT Year_
        FROM YearsCTE
        ORDER BY Year_
        OPTION (MAXRECURSION 100);



        DECLARE @StartDate DATE = '2017-01-01';
        DECLARE @EndDate   DATE = EOMONTH(GETDATE());
        
        ;WITH MonthsCTE AS
        (
            SELECT @StartDate AS MonthStart
            UNION ALL
            SELECT DATEADD(MONTH, 1, MonthStart)
            FROM MonthsCTE
            WHERE DATEADD(MONTH, 1, MonthStart) <= @EndDate
        )
        SELECT
            YEAR(MonthStart)  AS Year_,
            MONTH(MonthStart) AS MonthNumber,
            CASE MONTH(MonthStart)
                WHEN 1  THEN N'يناير'
                WHEN 2  THEN N'فبراير'
                WHEN 3  THEN N'مارس'
                WHEN 4  THEN N'أبريل'
                WHEN 5  THEN N'مايو'
                WHEN 6  THEN N'يونيو'
                WHEN 7  THEN N'يوليو'
                WHEN 8  THEN N'أغسطس'
                WHEN 9  THEN N'سبتمبر'
                WHEN 10 THEN N'أكتوبر'
                WHEN 11 THEN N'نوفمبر'
                WHEN 12 THEN N'ديسمبر'
            END AS ArabicMonthName
        FROM MonthsCTE
        ORDER BY MonthStart
        OPTION (MAXRECURSION 1000);

        --------------------------------------

        SELECT  
       d.[deductListID]
      ,d.[deductTypeID_FK]
      ,p.deductTypeName_A
      ,c.BillChargeTypeName_A
      ,d.[DeductListStatusID_FK]
      ,d.[deductUID]
      ,d.[deductName]
      ,d.[amountTypeID_FK]
      ,d.[paymentTypeID_FK]
      ,d.[issueMonth]
      ,d.[issueYear]
      ,d.[paymentNo]
      ,CONVERT(nvarchar(10), d.paymentDate, 23) AS paymentDate
      ,d.[description]
      ,d.[deductActive]
      ,d.[BillChargeTypeID_FK]
      ,d.[IdaraId_FK]
      ,d.[entryDate]
      ,d.[entryData]
      ,d.[hostName]

  FROM [DATACORE].[Housing].[DeductList] d
  inner join Housing.DeductType p on d.deductTypeID_FK = p.deductTypeID
  inner join Housing.BillChargeType c on d.BillChargeTypeID_FK = c.BillChargeTypeID
  where d.deductActive = 1
  and d.IdaraId_FK = @idaraID
  order by deductListID desc



   
END
GO
/****** Object:  StoredProcedure [Housing].[MeterReadForOccubentAndExitDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[MeterReadForOccubentAndExitDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
	,@residentInfoID   INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	    -- MeterReadForOccubentAndExit Data

          
       SELECT 
            w.ActionID,
            rd.FullName_A as FullName_A,
            w.NationalID,
            w.GeneralNo,
            w.ActionDecisionNo,
            convert(nvarchar(10),w.[ActionDecisionDate],23) ActionDecisionDate,
            w.WaitingClassID,
            w.WaitingClassName,
            w.WaitingOrderTypeID,
            w.WaitingOrderTypeName,
            w.waitingClassSequence,
            w.residentInfoID,
            w.LastActionTypeID,
            w.LastActionID,
            ba.buildingActionTypeResidentAlias,
            
           
            w.buildingDetailsID,
            w.buildingDetailsNo,
            mbb.meterNo,
           
            w.IdaraId,
            w.AssignPeriodID
            ,
           
            mbb.meterID,
            mst.meterServiceTypeName_A,
            mst.meterServiceTypeID,
            mty.meterTypeName_A,
            mty.meterMaxRead,
              case 
             when m.BuildingActionID_FK is not null then  convert(nvarchar,mw.BeforeLastReadValue)
             when m.BuildingActionID_FK is null then N''
             END BeforeLastReadValue,
           
            m.meterReadValue,
             case 
             when m.BuildingActionID_FK is not null then  convert(nvarchar,mw.ReadDiff)
             when m.BuildingActionID_FK is null then N''
             END ReadDiff,
            
            case when m.BuildingActionID_FK is not null and mw.BeforeLastReadValue > m.meterReadValue then N'1'
            else
            N'0'
            END ReadSizeStatus,
            case when m.BuildingActionID_FK is not null and mw.BeforeLastReadValue > m.meterReadValue then N'تحقق من القراءة'
            else
            N'لايوجد ملاحظة'
            END ReadSizeStatusText,

            
            mr.meterReadID,
            w.LastActionDate,
            w.buildingActionRoot,

              case 
               when m.BuildingActionID_FK is not null and ba2.buildingActionTypeID_FK = 59 and w.LastActionTypeID = 59 then N'تم تسجيل قراءة العداد'
             when m.BuildingActionID_FK is not null and ba2.buildingActionTypeID_FK = 46 and w.LastActionTypeID = 46 then N'تم تسجيل قراءة العداد'
             when m.BuildingActionID_FK is null then N'بانتظار تسجيل القراءة'
             else N'بانتظار تسجيل القراءة'
             END ReadStatus,
             case 
            when w.LastActionTypeID = 46 then N'قراءة تسكين'
            when w.LastActionTypeID = 59 then N'قراءة اخلاء'
             END ReadType,
             case 
             when m.BuildingActionID_FK is not null and ba2.buildingActionTypeID_FK = 59 and w.LastActionTypeID = 59 then N'1'
             when m.BuildingActionID_FK is not null and ba2.buildingActionTypeID_FK = 46 and w.LastActionTypeID = 46 then N'1'
             when m.BuildingActionID_FK is null then N'0'
             else N'0'
             END ReadStatusInt,
             isnull(w.LastActionNote,w.ActionNote) ActionNote,
             b.BillsID,
             w.LastActionDecisionDate,
             w.LastActionDecisionNo
             
             
           
            
            
    FROM Housing.V_WaitingList w 
    INNER JOIN Housing.V_GetFullResidentDetails rd ON w.residentInfoID = rd.residentInfoID
    Inner Join Housing.BuildingActionType ba on w.LastActionTypeID = ba.buildingActionTypeID
    left Join Housing.V_GetListMetersLinkedWithBuildings mbb on w.buildingDetailsID = mbb.buildingDetailsID_FK
    left join Housing.V_GetListAllMetersLastRead mr on mbb.meterID = mr.meterID_FK
    left join [Housing].[V_GetListAllMetersLastAndBeforeLastRead_WithWrap] mw on mbb.meterID = mw.meterID_FK
    left join Housing.MeterRead m on mr.meterReadID = m.meterReadID
    left join Housing.MeterReadType mrt on m.meterReadTypeID_FK = mrt.meterReadTypeID
    left join Housing.MeterServiceType mst on mbb.meterServiceTypeID_FK = mst.meterServiceTypeID
    left join Housing.MeterType mty on mbb.meterTypeID_FK = mty.meterTypeID
    left join Housing.Bills b on m.meterReadID = b.meterReadID
    left join Housing.BuildingAction ba2 on m.buildingActionID_FK = ba2.buildingActionID
    WHERE w.IdaraId = @idaraID
      AND  w.LastActionTypeID in (46,59)
      AND w.residentInfoID = @residentInfoID
      order by   w.waitingClassSequence asc





          
        SELECT 
            rd.FullName_A+' - '+rd.NationalID+' - '+ case 
             when w.LastActionTypeID = 46 then N'قراءة تسكين'
             when w.LastActionTypeID in(59) then N'قراءة اخلاء'
             END as FullName_A,
            w.residentInfoID
          
    FROM Housing.V_WaitingList w 
    INNER JOIN Housing.V_GetFullResidentDetails rd 
        ON w.residentInfoID = rd.residentInfoID
        Inner Join Housing.BuildingActionType ba on w.LastActionTypeID = ba.buildingActionTypeID
    WHERE w.IdaraId = @idaraID
      AND  w.LastActionTypeID in (46,59)
      order by   w.waitingClassSequence asc


      --or w.LastActionTypeID in (2,3,18,19,20,21,22,23,24,26,27,28,33,34,35)




     -- AssignPeriod DDL
            --SELECT c.AssignPeriodID,c.AssignPeriodDescrption
            --FROM [DATACORE].[Housing].[AssignPeriod] c
            --where  c.IdaraId_FK = @idaraID and c.AssignPeriodActive = 1 and c.AssignPeriodClose = 0 and c.AssignPeriodEnddate is not null
            --and c.AssignPeriodFinalEND = 1 and c.AssignPeriodFinalEnddate is null
            --order by c.AssignPeriodID asc

END
GO
/****** Object:  StoredProcedure [Housing].[MeterReadForOccubentAndExitSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[MeterReadForOccubentAndExitSP] 
(

      @Action                               NVARCHAR(200)
    , @ActionID                             BIGINT          = NULL
    , @residentInfoID                       NVARCHAR(100)   = NULL
    , @NationalID                           NVARCHAR(100)   = NULL
    , @GeneralNo                            NVARCHAR(100)   = NULL
    , @buildingActionDecisionNo             NVARCHAR(1000)  = NULL
    , @buildingActionDecisionDate           NVARCHAR(1000)  = NULL
    , @WaitingClassID                       NVARCHAR(1000)  = NULL
    , @WaitingClassName                     NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeID                   NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeName                 NVARCHAR(1000)  = NULL
    , @waitingClassSequence                 NVARCHAR(1000)  = NULL
    , @WaitingListOrder                     NVARCHAR(1000)  = NULL
    , @FullName_A                           NVARCHAR(1000)  = NULL
    , @buildingDetailsID                    NVARCHAR(1000)  = NULL
    , @buildingDetailsNo                    NVARCHAR(1000)  = NULL
    , @AssignPeriodID                       NVARCHAR(1000)  = NULL
    , @LastActionID                         NVARCHAR(1000)  = NULL
    , @LastActionTypeID                     NVARCHAR(1000)  = NULL
    , @Notes                                NVARCHAR(1000)  = NULL
    , @meterID                              NVARCHAR(1000)  = NULL
    , @MeterServiceTypeID                   NVARCHAR(1000)  = NULL
    , @buildingActionRoot                   NVARCHAR(1000)  = NULL
    , @NewMeterReadValue                    NVARCHAR(1000)  = NULL
    , @meterReadID                          NVARCHAR(1000)  = NULL
    , @ExitDate                             NVARCHAR(1000)  = NULL
    , @BillsID                             NVARCHAR(1000)  = NULL
    , @idaraID_FK                           NVARCHAR(10)    = NULL
    , @entryData                            NVARCHAR(20)    = NULL
    , @hostName                             NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL
        , @Note1  NVARCHAR(MAX) = NULL
        , @Note2  NVARCHAR(MAX) = NULL
        , @Note3  NVARCHAR(MAX) = NULL
        , @Identity_Insert BIGINT = NULL
        , @Identity_Insert1 BIGINT = NULL
        , @Identity_Insert2 BIGINT = NULL
        , @meterReadTypeID_FK INT ;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));

    --DECLARE @buildingDetailsNo nvarchar(200) 
    --set @buildingDetailsNo = (select b.buildingDetailsNo from Housing.V_GetGeneralListForBuilding b where b.buildingDetailsID = @buildingDetailsID);

    Declare @MeterServiceCount int
    set @MeterServiceCount =(select count(*) 
    from  Housing.MeterForBuilding m 
    where m.buildingDetailsID_FK = @buildingDetailsID 
    and m.meterForBuildingActive = 1 
    and (m.meterForBuildingEndDate is null or cast(m.meterForBuildingEndDate as date) > cast(GETDATE() as date))
    )

   



    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

   


         IF @Action IN(N'MeterRead')
        BEGIN
         
            IF NULLIF(LTRIM(RTRIM(@meterID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'معرف العداد غير مرسل بشكل صحيح', 1;
            END

          IF NULLIF(LTRIM(RTRIM(@NewMeterReadValue)), N'') IS NULL
               OR TRY_CONVERT(BIGINT, @NewMeterReadValue) IS NULL
               OR TRY_CONVERT(BIGINT, @NewMeterReadValue) < 0
            BEGIN
                ;THROW 50001, N'يجب إدخال قراءة عداد صحيحة (رقم صحيح موجب)', 1;
            END


        END

        

     

        ----------------------------------------------------------------
        -- METERREADFOROCCUBENTANDEXIT
        ----------------------------------------------------------------
        IF @Action = N'METERREADFOROCCUBENTANDEXIT'



            BEGIN

        IF(@buildingActionRoot = 2)
        BEGIN
        IF EXISTS (
                 SELECT 1
                 FROM Housing.Bills b
                 WHERE b.meterID = @meterID
                   AND b.residentInfoID_FK = @residentInfoID
                   AND b.meterServiceTypeID = @MeterServiceTypeID
