/****** Object:  StoredProcedure [Housing].[MilitaryLocationSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[MilitaryLocationSP]
(
      @Action                           NVARCHAR(200)
    , @militaryLocationID               BIGINT          = NULL
    , @militaryLocationCode             NVARCHAR(10)    = NULL
    , @militaryAreaCityID_FK            INT             = NULL
    , @militaryLocationName_A           NVARCHAR(1000)  = NULL
    , @militaryLocationName_E           NVARCHAR(1000)  = NULL
    , @militaryLocationCoordinates      NVARCHAR(1000)  = NULL
    , @militaryLocationDescription      NVARCHAR(1000)  = NULL
    , @militaryLocationActive           INT             = NULL
    , @idaraID_FK                       NVARCHAR(10)    = NULL
    , @entryData                        NVARCHAR(20)    = NULL
    , @hostName                         NVARCHAR(200)   = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), ''));

    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

        ----------------------------------------------------------------
        -- INSERT
        ----------------------------------------------------------------
        IF @Action = N'INSERT'
        BEGIN
            IF NULLIF(LTRIM(RTRIM(@militaryLocationName_A)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'اسم الموقع العسكري (عربي) مطلوب', 1;
            END

            IF EXISTS
            (
                SELECT 1
                FROM  Housing.MilitaryLocation ml
                WHERE ml.militaryLocationName_A = @militaryLocationName_A
                  AND ml.militaryLocationActive = 1
                  AND (ml.IdaraId_FK = @IdaraID_INT OR @IdaraID_INT IS NULL)
            )
            BEGIN
                ;THROW 50001, N'البيانات مدخلة مسبقا', 1;
            END

            INSERT INTO  Housing.MilitaryLocation
            (
                  militaryLocationCode
                , militaryAreaCityID_FK
                , militaryLocationName_A
                , militaryLocationName_E
                , militaryLocationCoordinates
                , militaryLocationDescription
                , militaryLocationActive
                , IdaraId_FK
                , entryData
                , hostName
            )
            VALUES
            (
                  @militaryLocationCode
                , @militaryAreaCityID_FK
                , @militaryLocationName_A
                , @militaryLocationName_E
                , @militaryLocationCoordinates
                , @militaryLocationDescription
                , 1
                , @IdaraID_INT
                , @entryData
                , @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البيانات', 1; -- برمجي/غير متوقع
            END

            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البيانات - Identity', 1; -- برمجي/غير متوقع
            END

            SET @Note = N'{'
                + N'"militaryLocationID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"militaryLocationCode": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationCode), '') + N'"'
                + N',"militaryAreaCityID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @militaryAreaCityID_FK), '') + N'"'
                + N',"militaryLocationName_A": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationName_A), '') + N'"'
                + N',"militaryLocationName_E": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationName_E), '') + N'"'
                + N',"militaryLocationCoordinates": "' + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationCoordinates), '') + N'"'
                + N',"militaryLocationDescription": "' + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationDescription), '') + N'"'
                + N',"militaryLocationActive": "1"'
                + N',"IdaraId_FK": "'                  + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                   + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                    + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[MilitaryLocation]'
                , N'INSERT'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم اضافة البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- UPDATE
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPDATE'
        BEGIN
            IF @militaryLocationID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

            IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.MilitaryLocation
                WHERE militaryLocationID = @militaryLocationID
                  AND militaryLocationActive = 1
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

            UPDATE  Housing.MilitaryLocation
            SET
                  militaryLocationCode        = ISNULL(@militaryLocationCode, militaryLocationCode)
                , militaryAreaCityID_FK       = ISNULL(@militaryAreaCityID_FK, militaryAreaCityID_FK)
                , militaryLocationName_A      = ISNULL(@militaryLocationName_A, militaryLocationName_A)
                , militaryLocationName_E      = ISNULL(@militaryLocationName_E, militaryLocationName_E)
                , militaryLocationCoordinates = ISNULL(@militaryLocationCoordinates, militaryLocationCoordinates)
                , militaryLocationDescription = ISNULL(@militaryLocationDescription, militaryLocationDescription)
                , IdaraId_FK                  = ISNULL(@IdaraID_INT, IdaraId_FK)
                , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)
            WHERE militaryLocationID = @militaryLocationID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1; -- برمجي/غير متوقع
            END

            SET @Note = N'{'
                + N'"militaryLocationID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationID), '') + N'"'
                + N',"militaryLocationCode": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationCode), '') + N'"'
                + N',"militaryAreaCityID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @militaryAreaCityID_FK), '') + N'"'
                + N',"militaryLocationName_A": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationName_A), '') + N'"'
                + N',"militaryLocationName_E": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationName_E), '') + N'"'
                + N',"militaryLocationCoordinates": "' + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationCoordinates), '') + N'"'
                + N',"militaryLocationDescription": "' + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationDescription), '') + N'"'
                + N',"IdaraId_FK": "'                  + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                   + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                    + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[MilitaryLocation]'
                , N'UPDATE'
                , @militaryLocationID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم تحديث البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- DELETE (Soft Delete)
        ----------------------------------------------------------------
        ELSE IF @Action = N'DELETE'
        BEGIN
            IF @militaryLocationID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للحذف', 1;
            END

            IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.MilitaryLocation
                WHERE militaryLocationID = @militaryLocationID
                  AND militaryLocationActive = 1
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

            UPDATE  Housing.MilitaryLocation
            SET
                  militaryLocationActive = 0
                , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)
            WHERE militaryLocationID = @militaryLocationID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم حذف أي سجل', 1; -- برمجي/غير متوقع
            END

            SET @Note = N'{'
                + N'"militaryLocationID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @militaryLocationID), '') + N'"'
                + N',"entryData": "'         + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'          + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[MilitaryLocation]'
                , N'DELETE'
                , @militaryLocationID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم حذف البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[OtherWaitingListDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[OtherWaitingListDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
	, @WaitingClassID_nvar  NVARCHAR(400)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   
    Declare @WaitingClassID int
    set @WaitingClassID = TRY_CAST(@WaitingClassID_nvar as int)
  -- WaitingList Data

         
   SELECT 
            w.ActionID,
            ROW_NUMBER() OVER (
            ORDER BY w.ActionDecisionDate ASC,w.ActionDecisionNo ASC, w.GeneralNo ASC
            ) AS WaitingListOrder,
            rd.FullName_A as FullName_A,
            w.NationalID,
            w.GeneralNo,
            rd.rankNameA,
            w.ActionDecisionNo,
            convert(nvarchar(10),w.[ActionDecisionDate],23) ActionDecisionDate,
            w.WaitingClassID,
            w.WaitingClassName,
            w.WaitingOrderTypeID,
            w.WaitingOrderTypeName,
            w.waitingClassSequence,
            w.residentInfoID,
            w.LastActionTypeID,
            w.LastActionID,
            isnull(w.LastActionNote,w.ActionNote) ActionNote,
            w.IdaraId

FROM Housing.V_WaitingList w 
    INNER JOIN Housing.V_GetFullResidentDetails rd 
        ON w.residentInfoID = rd.residentInfoID
        left Join Housing.BuildingActionType ba on w.LastActionTypeID = ba.buildingActionTypeID
    WHERE 
    w.WaitingClassID = @WaitingClassID
      AND 
      w.IdaraId = @idaraID
      AND  (w.LastActionTypeID is null or w.LastActionTypeID in (34,35))
      AND (w.WaitingClassID not in(1,2,3,4,11))  
      AND (w.IdaraId = @idaraID)



     -- WaitingClass DDL
            SELECT c.waitingClassID,c.waitingClassName_A
            FROM [DATACORE].[Housing].[WaitingClass] c
            where (c.WaitingClassID not in(1,2,3,4,11)) and (c.idara_FK = @idaraID)
            order by c.waitingClassSequence asc



       -- Houses DDL
            SELECT c.buildingDetailsID,c.buildingDetailsNo
            FROM [DATACORE].[Housing].[V_GetGeneralListForBuilding] c
            where c.BuildingIdaraID = 1 and c.buildingDetailsActive = 1 
            and (c.LastActionTypeID in(5,39,41) or c.LastActionTypeID is null )
  
            



   
END
GO
/****** Object:  StoredProcedure [Housing].[OtherWaitingListSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[OtherWaitingListSP] 
(
      @Action                       NVARCHAR(200)
    , @ActionID                     BIGINT          = NULL
    , @residentInfoID_FK            NVARCHAR(100)   = NULL
    , @residentName                 NVARCHAR(100)   = NULL
    , @NationalID                   NVARCHAR(100)   = NULL
    , @GeneralNo                    NVARCHAR(100)   = NULL
    , @buildingActionDecisionNo     NVARCHAR(1000)  = NULL
    , @buildingActionDecisionDate   NVARCHAR(1000)  = NULL
    , @WaitingClassID               NVARCHAR(1000)  = NULL
    , @WaitingClassName             NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeID           NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeName         NVARCHAR(1000)  = NULL
    , @buildingDetailsID            NVARCHAR(1000)  = NULL
    , @Notes                        NVARCHAR(1000)  = NULL
    , @idaraID_FK                   NVARCHAR(10)    = NULL
    , @entryData                    NVARCHAR(20)    = NULL
    , @hostName                     NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));
    DECLARE @buildingDetailsNo nvarchar(500)
    set @buildingDetailsNo = (select top(1) b.buildingDetailsNo from Housing.V_GetGeneralListForBuilding b where b.buildingDetailsID = @buildingDetailsID and b.BuildingIdaraID = @idaraID_FK order by b.buildingDetailsID desc)
    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

            IF NULLIF(LTRIM(RTRIM(@ActionID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات سجل الانتظار - Action ID', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@residentInfoID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - resident ID', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@GeneralNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - GN', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@NationalID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - @NationalID', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'رقم القرار مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionDate)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'تاريخ القرار مطلوب', 1;
            END

         IF NULLIF(LTRIM(RTRIM(@WaitingClassID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'فئة سجل الانتظار مطلوبة', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@WaitingOrderTypeID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'ترتيب سجل الانتظار مطلوبة', 1;
            END


        ----------------------------------------------------------------
        -- MOVETOASSIGNLIST
        ----------------------------------------------------------------
        IF @Action = N'MOVETOOCCUPENTPROCEDURES'
         BEGIN

        
            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


             IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID and w.LastActionTypeID = 45 and w.ToIdaraID = @idaraID_FK
                  
            )
            BEGIN
                ;THROW 50001, N'تم اتخاذ اجراء للطلب مسبقا', 1;
            END



              
                DECLARE @MyOrder int;
                DECLARE @ErrMsg_  nvarchar(4000);
                
                SELECT @MyOrder = x.rn
                FROM
                (
                    SELECT
                        w.ActionID,
                        ROW_NUMBER() OVER (ORDER BY w.ActionDecisionDate ASC,w.ActionDecisionNo ASC, w.GeneralNo ASC) AS rn
                   FROM Housing.V_WaitingList w
                   INNER JOIN Housing.V_GetFullResidentDetails rd 
                       ON w.residentInfoID = rd.residentInfoID
                   WHERE w.WaitingClassID = @WaitingClassID
                     AND w.IdaraId = @idaraID_FK
                     AND  (w.LastActionTypeID is null or w.LastActionTypeID in (34,35))
                     AND w.residentInfoID = @residentInfoID_FK
                ) x
                WHERE x.ActionID = @ActionID;
                
                IF @MyOrder IS NULL
                BEGIN
                    SET @ErrMsg_ = N'لم يتم العثور على الطلب داخل قائمة الانتظار';
                    ;THROW 50001, @ErrMsg_, 1;
                END
                
                --IF cast(@MyOrder as int) <> 1
                --BEGIN
                --    SET @ErrMsg_ =
                --        N' المستفيد '+CAST(@residentName AS nvarchar(200))+N' ليس في رأس قائمة الانتظار في '
                --        + CAST(@WaitingClassName AS nvarchar(20));
                --    ;THROW 50001, @ErrMsg_, 1;
                --END

              

           

             INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingDetailsID_FK
                , buildingDetailsNo
                , buildingActionExtraType1
                , buildingActionExtraType2
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , IdaraId_FK
                , entryData
                , hostName
            )
            
             VALUES
            (
                  45
                , @residentInfoID_FK
                , @GeneralNo
                , @buildingActionDecisionNo
                , @buildingActionDecisionDate
                , @buildingDetailsID
                , @buildingDetailsNo
                , @WaitingClassID
                , @WaitingOrderTypeID
                , 1
                , @Notes
                , @ActionID
                , @IdaraID_INT
                , @entryData
                , @hostName
            );
            
       

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في نقل المستفيد لاجراءات التسكين', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في المستفيد لاجراءات التسكين - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), 27), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID_FK), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionDate), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"buildingActionNote": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ActionID), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'MOVETOOCCUPENTPROCEDURES'
                , @ActionID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم نقل المستفيد لاجراءات التسكين بنجاح' AS Message_;
            RETURN;
        END

       
         ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END


     END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[RentExemptionDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[RentExemptionDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
	, @NationalID      NVARCHAR(400)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   
       declare @residentInfoID nvarchar(1000)
       set @residentInfoID =
       (SELECT Top(1)
                 fr.residentInfoID [residentInfoID]
       FROM [DATACORE].[Housing].V_GetFullResidentDetails fr
           where fr.NationalID = @NationalID
           order by fr.residentDetailsID desc
           )


          -- One Resident Data

             SELECT distinct
                 fr.residentInfoID [residentInfoID]
                ,fr.NationalID [NationalID]
                ,fr.generalNo_FK [generalNo_FK]
                ,fr.firstName_A [firstName_A]
                ,fr.secondName_A [secondName_A]
                ,fr.thirdName_A [thirdName_A]
                ,fr.lastName_A [lastName_A]
                ,fr.firstName_E [firstName_E]
                ,fr.secondName_E [secondName_E]
                ,fr.thirdName_E [thirdName_E]
                ,fr.lastName_E [lastName_E]
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_A,
                     fr.secondName_A,
                     fr.thirdName_A,
                     fr.lastName_A
                 )
                 )) AS FullName_A
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_E,
                     fr.secondName_E,
                     fr.thirdName_E,
                     fr.lastName_E
                 )
                 )) AS FullName_E
                ,fr.rankID_FK [rankID_FK]
                ,fr.rankNameA
                ,fr.militaryUnitID_FK [militaryUnitID_FK]
                ,fr.militaryUnitName_A
                ,fr.martialStatusID_FK [martialStatusID_FK]
                ,fr.maritalStatusName_A
                ,fr.dependinceCounter [dependinceCounter]
                ,fr.nationalityID_FK [nationalityID_FK]
                ,fr.nationalityName_A
                ,fr.genderID_FK [genderID_FK]
                ,fr.genderName_A
                ,convert(nvarchar(10),fr.birthdate,23) birthdate
                ,fr.residentcontactDetails
                ,fr.note [note]
                ,fr.IdaraID IdaraID
                ,fr.IdaraName IdaraName
                ,(select count(*) from Housing.V_WaitingList w where w.NationalID = @NationalID and w.IdaraId = @idaraID and (w.LastActionTypeID IS NULL OR w.LastActionTypeID not in (19,53)) and w.IdaraId = @idaraID) WaitingListCount
                ,(select count(*) from Housing.V_WaitingListByLetter w where w.NationalID = @NationalID and w.IdaraId = @idaraID and (w.LastActionTypeID IS NULL OR w.LastActionTypeID not in (19,53)) and w.IdaraId = @idaraID) WaitingListByLetterCount

           FROM [Housing].V_GetFullResidentDetails fr
           where fr.NationalID = @NationalID

            

            --Get Waiting List By Resident Nationl ID


         SELECT 
         r.[residentRentExemptionTypeID_FK]
        ,r.[residentInfoID_FK]
        ,r.buildingDetailsID_FK
        ,b.buildingDetailsNo
        ,r.[residentRentExemptionActive]
        ,t.ResidentRentExemptionTypeName_A
        ,r.[residentRentExemptionLetterNo]
        ,convert(nvarchar(10),r.[residentRentExemptionLetterDate],23) residentRentExemptionLetterDate
        ,convert(nvarchar(10),r.[residentRentExemptionStartDate],23) residentRentExemptionStartDate
        ,convert(nvarchar(10),r.[residentRentExemptionEndDate],23) residentRentExemptionEndDate
        ,r.[residentRentExemptionDescription]
        ,r.[idaraID_FK]
        ,r.[entryDate]
        ,r.[entryData]
        ,r.[hostName]
        ,t.ResidentRentExemptionTypePercentage
        ,case when r.residentRentExemptionActive = 0 or cast(r.residentRentExemptionEndDate as date) < cast(GETDATE() as date) then N'0'
         else
         N'1'
         END RentExemptionStatus
          ,case when r.residentRentExemptionActive = 0 or cast(r.residentRentExemptionEndDate as date) < cast(GETDATE() as date) then N'منتهي'
         else
         N'نشط'
         END RentExemptionStatusText

        FROM [Housing].[ResidentRentExemption] r
        inner join Housing.ResidentRentExemptionType t on r.residentRentExemptionTypeID_FK = t.ResidentRentExemptionTypeID
        left join Housing.V_GetGeneralListForBuilding b on r.buildingDetailsID_FK = b.buildingDetailsID
        where r.residentInfoID_FK = @residentInfoID and r.idaraID_FK = @idaraID 
        





    -- Insert statements for procedure here
END
GO
/****** Object:  StoredProcedure [Housing].[ResidentsDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[ResidentsDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   

          -- Residents Data
            SELECT Top(1000)
                 fr.residentInfoID [residentInfoID]
                ,fr.NationalID [NationalID]
                ,fr.generalNo_FK [generalNo_FK]
                ,fr.firstName_A [firstName_A]
                ,fr.secondName_A [secondName_A]
                ,fr.thirdName_A [thirdName_A]
                ,fr.lastName_A [lastName_A]
                ,fr.firstName_E [firstName_E]
                ,fr.secondName_E [secondName_E]
                ,fr.thirdName_E [thirdName_E]
                ,fr.lastName_E [lastName_E]
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_A,
                     fr.secondName_A,
                     fr.thirdName_A,
                     fr.lastName_A
                 )
                 )) AS FullName_A
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_E ,
                     fr.secondName_E ,
                     fr.thirdName_E ,
                     fr.lastName_E 
                 )
                 )) AS FullName_E
                ,fr.rankID_FK [rankID_FK]
                ,fr.rankNameA
                ,fr.militaryUnitID_FK [militaryUnitID_FK]
                ,fr.militaryUnitName_A
                ,fr.martialStatusID_FK [martialStatusID_FK]
                ,fr.maritalStatusName_A
                ,fr.dependinceCounter [dependinceCounter]
                ,fr.nationalityID_FK [nationalityID_FK]
                ,fr.nationalityName_A
                ,fr.genderID_FK as [genderID_FK]
                ,fr.genderName_A
                ,convert(nvarchar(10),fr.birthdate,23) birthdate
                ,fr.residentcontactDetails
                ,fr.note [note]

                

           FROM [DATACORE].[Housing].V_GetFullResidentDetails fr
           where fr.IdaraID = @idaraID
            
           ORDER BY fr.residentInfoID desc;


             -- rank DDL
            SELECT bu.rankID, bu.rankNameA
            FROM [DATACORE].[dbo].[Rank] bu
            WHERE bu.rankActive = 1 
            order by bu.rankClassID_FK asc


            -- militaryUnit DDL
            SELECT r.militaryUnitID, r.militaryUnitName_A
            FROM [DATACORE].[dbo].[militaryUnit] r
            

            

            -- MaritalStatus DDL
            SELECT r.maritalStatusID, r.maritalStatusName_A
            FROM [DATACORE].[dbo].[MaritalStatus] r
            WHERE r.maritalStatusActive = 1 ;


            

            -- Nationality DDL
            SELECT r.nationalityID, r.nationalityName_A
            FROM [DATACORE].[dbo].[Nationality] r
            WHERE r.nationalityActive = 1;


            

            -- Gender DDL
            SELECT r.genderID, r.genderName_A
            FROM [DATACORE].[dbo].[Gender] r
            


            ---- test
            select r.residentInfoID,FullName_A from [DATACORE].[Housing].V_GetFullResidentDetails r
            where IdaraID = @idaraID



    -- Insert statements for procedure here
END
GO
/****** Object:  StoredProcedure [Housing].[ResidentsSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[ResidentsSP] 
(
      @Action                 NVARCHAR(100)   = NULL
     ,@residentInfoID         NVARCHAR(100)   = NULL
     ,@NationalID             NVARCHAR(100)   = NULL
     ,@generalNo              NVARCHAR(100)   = NULL
     ,@firstName_A            NVARCHAR(100)   = NULL
     ,@secondName_A           NVARCHAR(100)   = NULL
     ,@thirdName_A            NVARCHAR(100)   = NULL
     ,@lastName_A             NVARCHAR(100)   = NULL
     ,@firstName_E            NVARCHAR(100)   = NULL
     ,@secondName_E           NVARCHAR(100)   = NULL
     ,@thirdName_E            NVARCHAR(100)   = NULL
     ,@lastName_E             NVARCHAR(100)   = NULL
     ,@militaryUnitID_FK      NVARCHAR(100)   = NULL
     ,@rankID_FK              NVARCHAR(100)   = NULL
     ,@martialStatusID_FK     NVARCHAR(100)   = NULL
     ,@dependinceCounter      NVARCHAR(100)   = NULL
     ,@nationalityID_FK       NVARCHAR(100)   = NULL
     ,@genderID_FK            NVARCHAR(100)   = NULL
     ,@birthDate              NVARCHAR(100)   = NULL
	 ,@Mobile                 NVARCHAR(100)   = NULL
     ,@notes                  NVARCHAR(100)   = NULL
     ,@idaraID_FK             NVARCHAR(100)   = NULL
     ,@entryData              NVARCHAR(100)   = NULL
     ,@hostName               NVARCHAR(100)   = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @NewID           BIGINT = NULL
        , @Note            NVARCHAR(MAX) = NULL
        , @Identity_Insert BIGINT = NULL
        , @Identity_Insert1 BIGINT = NULL
        , @Identity_Insert2 BIGINT = NULL
        , @Identity_Update BIGINT = NULL
        , @Identity_Update1 BIGINT = NULL
        , @Identity_Update2 BIGINT = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), ''));

    DECLARE @militaryUnitID_FK_INT        INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@militaryUnitID_FK)), ''));
    DECLARE @rankID_FK_INT INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@rankID_FK)), ''));
    DECLARE @martialStatusID_FK_INT    INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@martialStatusID_FK)), ''));
    DECLARE @dependinceCounter_INT       INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@dependinceCounter)), ''));
    DECLARE @nationalityID_FK_INT INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@nationalityID_FK)), ''));
    DECLARE @genderID_FK_INT INT = TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@genderID_FK)), ''));


    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END
       

       IF(@Action IN('INSERT','UPDATE'))
       BEGIN

        IF NULLIF(LTRIM(RTRIM(@NationalID)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'رقم الهوية مطلوب', 1;
        END

          IF (select count(*) 
                from Housing.ResidentInfo ri
                inner join Housing.ResidentDetails rd on ri.residentInfoID = rd.residentInfoID_FK
                where ri.residentInfoActive = 1 and rd.residentDetailsActive = 1 and rd.generalNo_FK = @generalNo and ((@residentInfoID is not null) and (rd.residentInfoID_FK <> @residentInfoID))
                ) > 0
        BEGIN
            ;THROW 50001, N'الرقم العام مستخدم مسبقا لشخص اخر', 1;
        END


        if(@nationalityID_FK_INT = 1)
        Begin
        IF TRY_CONVERT(BIGINT, @NationalID) IS NULL
        BEGIN
            ;THROW 50001, N'رقم الهوية الوطنية يجب أن يكون أرقام فقط', 1;
        END

        IF LEN(@NationalID) <> 10
        BEGIN
            ;THROW 50001, N'رقم الهوية الوطنية يجب أن يكون 10 أرقام', 1;
        END
        
        IF LEFT(@NationalID, 1) <> N'1'
        BEGIN
            ;THROW 50001, N'رقم الهوية الوطنية يجب أن يبدأ بالرقم 1', 1;
        END
        END



         IF (
            (NULLIF(LTRIM(RTRIM(@firstName_A)), N'') IS NULL) 
         OR (NULLIF(LTRIM(RTRIM(@secondName_A)), N'') IS NULL)
         OR (NULLIF(LTRIM(RTRIM(@thirdName_A)), N'') IS NULL)
         OR (NULLIF(LTRIM(RTRIM(@lastName_A)), N'') IS NULL)
         )
        BEGIN
            ;THROW 50001, N'الاسم العربي الرباعي مطلوب', 1;
        END


         IF NULLIF(LTRIM(RTRIM(@militaryUnitID_FK)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'الوحدة العسكرية مطلوبة', 1;
        END


         IF NULLIF(LTRIM(RTRIM(@rankID_FK)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'الرتبة مطلوبة', 1;
        END

         IF NULLIF(LTRIM(RTRIM(@martialStatusID_FK)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'الحالة الاجتماعية مطلوبة', 1;
        END

         IF NULLIF(LTRIM(RTRIM(@nationalityID_FK)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'الجنسية مطلوبة', 1;
        END

         IF NULLIF(LTRIM(RTRIM(@genderID_FK)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'تحديد الجنس مطلوب', 1;
        END

      
         IF NULLIF(LTRIM(RTRIM(@Mobile)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'رقم الجوال مطلوب', 1;
        END
        

          IF TRY_CONVERT(BIGINT, @Mobile) IS NULL
        BEGIN
            ;THROW 50001, N'رقم الجوال يجب أن يكون أرقام فقط', 1;
        END

        IF LEN(@Mobile) <> 10
        BEGIN
            ;THROW 50001, N'رقم الجوال يجب أن يكون 10 أرقام', 1;
        END
        
        IF LEFT(@Mobile, 2) <> N'05'
        BEGIN
            ;THROW 50001, N'رقم الجوال يجب أن يبدأ بالرقم 05', 1;
        END


        END


         IF(@Action IN('DELETE'))
       BEGIN

       if(select count(*) from Housing.V_WaitingList w where w.residentInfoID = @residentInfoID) > 0
       begin
       ;THROW 50001, N'لايمكن حذف المستفيد لوجود اجراءات متعلقة به في النظام', 1;

       end

       END
        ----------------------------------------------------------------
        -- INSERT
        ----------------------------------------------------------------
        IF @Action = N'INSERT'
        BEGIN
            IF EXISTS (
                SELECT 1
                FROM  Housing.ResidentInfo c
                WHERE c.NationalID = @NationalID
                  AND c.residentInfoActive = 1
            )
            BEGIN
                ;THROW 50001, N'بيانات المستفيد مدخلة مسبقا', 1;
            END

            INSERT INTO  Housing.ResidentInfo
            (
                  [NationalID]
                 ,[residentInfoActive]
                 ,[entryData]
                 ,[hostName]
            )
            VALUES
            (
                  @NationalID
                , 1
                , @entryData
                , @hostName
            );

            SET @Identity_Insert = SCOPE_IDENTITY();
            IF @Identity_Insert IS NULL OR @Identity_Insert <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البيانات - ResidentInfo', 1; -- برمجي
            END

                INSERT INTO  Housing.ResidentDetails
                (
                      [residentInfoID_FK]
                     ,[generalNo_FK]
                     ,[rankID_FK]
                     ,[militaryUnitID_FK]
                     ,[martialStatusID_FK]
                     ,[dependinceCounter]
                     ,[nationalityID_FK]
                     ,[genderID_FK]
                     ,[firstName_A]
                     ,[secondName_A]
                     ,[thirdName_A]
                     ,[lastName_A]
                     ,[firstName_E]
                     ,[secondName_E]
                     ,[thirdName_E]
                     ,[lastName_E]
                     ,[note]
                     ,[birthdate]
                     ,[residentDetailsStartDate]
                     ,[residentDetailsActive]
                     ,[IdaraId_FK]
                     ,[entryData]
                     ,[hostName]
                )
                VALUES
                (
                      @Identity_Insert
                    , @generalNo
                    , @rankID_FK_INT
                    , @militaryUnitID_FK_INT
                    , @martialStatusID_FK_INT
                    , ISNULL(@dependinceCounter,0)
                    , @nationalityID_FK_INT
                    , @genderID_FK_INT
                    , @firstName_A
                    , @secondName_A
                    , @thirdName_A
                    , @lastName_A
                    , @firstName_E
                    , @secondName_E
                    , @thirdName_E
                    , @lastName_E
                    , @notes
                    , @birthDate
                    , GETDATE()
                    , 1
                    , @idaraID_FK
                    , @entryData
                    , @hostName
                );

                IF @@ROWCOUNT <= 0
                BEGIN
                    ;THROW 50003, N'حصل خطأ في اضافة البيانات - ResidentDetails', 1; -- برمجي
                END

                 INSERT INTO  Housing.ResidentContactInfo
                (
                      [residentInfoID_FK]
                     ,[residentcontanctTypeID_FK]
                     ,[residentcontactDetails]
                     ,[residentcontactInfoStartDate]
                     ,[residentcontactInfoActive]
                     ,[entryData]
                     ,[hostName]
                )
                VALUES
                (
                      @Identity_Insert
                    , 1
                    , @Mobile
                    , GETDATE()
                    , 1
                    , @entryData
                    , @hostName
                );

                IF @@ROWCOUNT <= 0
                BEGIN
                    ;THROW 50003, N'حصل خطأ في اضافة البيانات - ResidentContactInfo', 1; -- برمجي
                END



           

            SET @NewID = @Identity_Insert;

            SET @Note = N'{'
                + N'"residentInfoID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"generalNo_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @generalNo), '') + N'"'
                + N',"rankID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @rankID_FK_INT), '') + N'"'
                + N',"militaryUnitID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @militaryUnitID_FK_INT), '') + N'"'
                + N',"martialStatusID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @martialStatusID_FK_INT), '') + N'"'
                + N',"dependinceCounter": "' + ISNULL(CONVERT(NVARCHAR(MAX), @dependinceCounter), '') + N'"'
                + N',"nationalityID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @nationalityID_FK_INT), '') + N'"'
                + N',"genderID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @genderID_FK_INT), '') + N'"'
                + N',"firstName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @firstName_A), '') + N'"'
                + N',"secondName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @secondName_A), '') + N'"'
                + N',"thirdName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @thirdName_A), '') + N'"'
                + N',"lastName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @lastName_A), '') + N'"'
                + N',"firstName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @firstName_E), '') + N'"'
                + N',"secondName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @secondName_E), '') + N'"'
                + N',"thirdName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @thirdName_E), '') + N'"'
                + N',"lastName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @lastName_E), '') + N'"'
                + N',"notes": "' + ISNULL(CONVERT(NVARCHAR(MAX), @notes), '') + N'"'
                + N',"Mobile": "' + ISNULL(CONVERT(NVARCHAR(MAX), @Mobile), '') + N'"'
                + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N',"residentcontanctTypeID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"residentcontactDetails": "' + ISNULL(CONVERT(NVARCHAR(MAX), @Mobile), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[ResidentInfo],[Housing].[ResidentDetails],[Housing].[ResidentContactInfo]'
                , N'INSERT'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم اضافة البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- UPDATE
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPDATE'
        BEGIN
        
            IF @residentInfoID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

            IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.ResidentInfo bd
                WHERE bd.residentInfoID = @residentInfoID
                  AND bd.residentInfoActive = 1
            )
            BEGIN
                ;THROW 50001, N'المستفيد غير موجود', 1;
            END

            -- Duplicate check (مع تجاهل نفس السجل)
            --IF EXISTS
            --(
            --    SELECT 1
            --    FROM  Housing.ResidentInfo c
            --    WHERE c.NationalID = @NationalID
            --      AND c.residentInfoActive = 1
                  
            --)
            --BEGIN
            --    ;THROW 50001, N'البيانات مدخلة مسبقا', 1;
            --END

           
            UPDATE  Housing.ResidentInfo
            SET
                  NationalID = ISNULL(@NationalID, NationalID)
                , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)
            WHERE residentInfoID = @residentInfoID;

             SET @Identity_Update = @@ROWCOUNT;

            UPDATE  Housing.ResidentDetails
                SET
                      residentDetailsActive = 0
                    , residentDetailsEndDate = ISNULL(residentDetailsEndDate, GETDATE())
                    , entryData = ISNULL(@entryData, entryData)
                    , hostName  = ISNULL(@hostName, hostName)
                 WHERE residentInfoID_FK  = @residentInfoID
                  AND residentDetailsActive        = 1;

            SET @Identity_Update1 = @@ROWCOUNT;

            if (@Identity_Update1 > 0)
            BEGIN
                 INSERT INTO  Housing.ResidentDetails
                    (
                        residentInfoID_FK
                       , [generalNo_FK]          
                       , [rankID_FK]             
                       , [militaryUnitID_FK]     
                       , [martialStatusID_FK]    
                       , [dependinceCounter]     
                       , [nationalityID_FK]      
                       , [genderID_FK]           
                       , [firstName_A]           
                       , [secondName_A]          
                       , [thirdName_A]           
                       , [lastName_A]            
                       , [firstName_E]           
                       , [secondName_E]          
                       , [thirdName_E]           
                       , [lastName_E]            
                       , [note]                  
                       , [birthdate]
                       , [residentDetailsStartDate]
                       , [IdaraId_FK]      
                       ,residentDetailsActive
                       ,entryData
                       ,hostName
 
                    )
                    VALUES
                    (   
                         @residentInfoID
                        ,@generalNo
                        ,@rankID_FK_INT
                        ,@militaryUnitID_FK_INT
                        ,@martialStatusID_FK_INT
                        ,ISNULL(@dependinceCounter,0)
                        ,@nationalityID_FK_INT
                        ,@genderID_FK_INT
                        ,@firstName_A
                        ,@secondName_A
                        ,@thirdName_A
                        ,@lastName_A
                        ,@firstName_E
                        ,@secondName_E
                        ,@thirdName_E
                        ,@lastName_E
                        ,@notes
                        ,@birthDate
                        ,GETDATE()
                        ,@idaraID_FK 
                        ,1
                        ,@entryData
                        ,@hostName
 
                    );

                    SET @Identity_Insert1 = SCOPE_IDENTITY();
                   END


                      UPDATE  Housing.ResidentContactInfo
                SET
                      residentcontactInfoActive = 0
                    , residentcontactInfoEndDate = ISNULL(residentcontactInfoEndDate, GETDATE())
                    , entryData = ISNULL(@entryData, entryData)
                    , hostName  = ISNULL(@hostName, hostName)
                 WHERE residentInfoID_FK  = @residentInfoID
                  AND residentcontactInfoActive        = 1;

                  SET @Identity_Update2 = @@ROWCOUNT;

                  IF(@Identity_Update2 > 0)
                  BEGIN

                      INSERT INTO  Housing.ResidentContactInfo
                (
                      [residentInfoID_FK]
                     ,[residentcontanctTypeID_FK]
                     ,[residentcontactDetails]
                     ,[residentcontactInfoStartDate]
                     ,[residentcontactInfoActive]
                     ,[entryData]
                     ,[hostName]
                )
                VALUES
                (
                @residentInfoID
                ,1
                ,@Mobile
                ,GETDATE()
                ,1
                ,@entryData
                ,@hostName
                )
              
              SET @Identity_Insert2 = SCOPE_IDENTITY();

               END
               

                    ---- باقي تحديث الجوال

            SET @Note = N'{'
                + N'"residentInfoID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"generalNo_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @generalNo), '') + N'"'
                + N',"rankID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @rankID_FK_INT), '') + N'"'
                + N',"militaryUnitID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @militaryUnitID_FK_INT), '') + N'"'
                + N',"martialStatusID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @martialStatusID_FK_INT), '') + N'"'
                + N',"dependinceCounter": "' + ISNULL(CONVERT(NVARCHAR(MAX), @dependinceCounter), '') + N'"'
                + N',"nationalityID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @nationalityID_FK_INT), '') + N'"'
                + N',"genderID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @genderID_FK_INT), '') + N'"'
                + N',"firstName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @firstName_A), '') + N'"'
                + N',"secondName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @secondName_A), '') + N'"'
                + N',"thirdName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @thirdName_A), '') + N'"'
                + N',"lastName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @lastName_A), '') + N'"'
                + N',"firstName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @firstName_E), '') + N'"'
                + N',"secondName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @secondName_E), '') + N'"'
                + N',"thirdName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @thirdName_E), '') + N'"'
                + N',"lastName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @lastName_E), '') + N'"'
                + N',"notes": "' + ISNULL(CONVERT(NVARCHAR(MAX), @notes), '') + N'"'
                + N',"Mobile": "' + ISNULL(CONVERT(NVARCHAR(MAX), @Mobile), '') + N'"'
                + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N',"residentcontanctTypeID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"residentcontactDetails": "' + ISNULL(CONVERT(NVARCHAR(MAX), @Mobile), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[ResidentInfo],[Housing].[ResidentDetails],[Housing].[ResidentContactInfo]'
                , N'UPDATE'
                , @residentInfoID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم تحديث البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- DELETE (Soft Delete)
        ----------------------------------------------------------------
        ELSE IF @Action = N'DELETE'
        BEGIN

        IF @residentInfoID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

            IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.ResidentInfo bd
                WHERE bd.residentInfoID = @residentInfoID
                  AND bd.residentInfoActive = 1
            )
            BEGIN
                ;THROW 50001, N'المستفيد غير موجود', 1;
            END

             UPDATE  Housing.ResidentInfo
            SET
                  residentInfoActive = 0
                , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)
            WHERE residentInfoID = @residentInfoID;

             IF @@ROWCOUNT = 0
                    BEGIN
                        ;THROW 50002, N'حصل خطأ في تحديث البيانات - ResidentInfo', 1; -- برمجي/غير متوقع
                    END

            UPDATE  Housing.ResidentDetails
                SET
                      residentDetailsActive = 0
                    , residentDetailsEndDate = ISNULL(residentDetailsEndDate, GETDATE())
                    , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                    , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)
                 WHERE residentInfoID_FK  = @residentInfoID
                  AND residentDetailsActive        = 1;

                     IF @@ROWCOUNT = 0
                    BEGIN
                        ;THROW 50002, N'حصل خطأ في تحديث البيانات - ResidentDetails', 1; -- برمجي/غير متوقع
                    END
          
           

            SET @Note = N'{'
                + N'"residentInfoID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"generalNo_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @generalNo), '') + N'"'
                + N',"rankID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @rankID_FK_INT), '') + N'"'
                + N',"militaryUnitID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @militaryUnitID_FK_INT), '') + N'"'
                + N',"martialStatusID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @martialStatusID_FK_INT), '') + N'"'
                + N',"dependinceCounter": "' + ISNULL(CONVERT(NVARCHAR(MAX), @dependinceCounter), '') + N'"'
                + N',"nationalityID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @nationalityID_FK_INT), '') + N'"'
                + N',"genderID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @genderID_FK_INT), '') + N'"'
                + N',"firstName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @firstName_A), '') + N'"'
                + N',"secondName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @secondName_A), '') + N'"'
                + N',"thirdName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @thirdName_A), '') + N'"'
                + N',"lastName_A": "' + ISNULL(CONVERT(NVARCHAR(MAX), @lastName_A), '') + N'"'
                + N',"firstName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @firstName_E), '') + N'"'
                + N',"secondName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @secondName_E), '') + N'"'
                + N',"thirdName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @thirdName_E), '') + N'"'
                + N',"lastName_E": "' + ISNULL(CONVERT(NVARCHAR(MAX), @lastName_E), '') + N'"'
                + N',"notes": "' + ISNULL(CONVERT(NVARCHAR(MAX), @notes), '') + N'"'
                + N',"Mobile": "' + ISNULL(CONVERT(NVARCHAR(MAX), @Mobile), '') + N'"'
                + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N',"residentcontanctTypeID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"residentcontactDetails": "' + ISNULL(CONVERT(NVARCHAR(MAX), @Mobile), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[ResidentInfo],[Housing].[ResidentDetails],[Housing].[ResidentContactInfo]'
                , N'DELETE'
                , @residentInfoID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم حذف البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[UploadExcel_ImportSelected3Cols]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [Housing].[UploadExcel_ImportSelected3Cols]
(
    @Column1Name NVARCHAR(255) = NULL,
    @Column2Name NVARCHAR(255) = NULL,
    @Column3Name NVARCHAR(255) = NULL,
    @Column4Name NVARCHAR(255) = NULL,
    @FileHash    CHAR(64),
    @OriginalFileName NVARCHAR(260) = NULL,
    @Rows [Housing].[UploadExcelRowType] READONLY
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @StartedTran bit = 0;

    BEGIN TRY
        IF NULLIF(LTRIM(RTRIM(@FileHash)), N'') IS NULL
            THROW 50001, N'بصمة الملف غير موجودة.', 1;

        IF NOT EXISTS (SELECT 1 FROM @Rows)
            THROW 50001, N'لا توجد صفوف للإدخال.', 1;

        IF @@TRANCOUNT = 0
        BEGIN
            SET @StartedTran = 1;
            BEGIN TRAN;
        END

        -- ✅ منع استيراد نفس الملف أكثر من مرة فقط
        IF EXISTS (SELECT 1 FROM [Housing].[UploadExcelImportLog] WHERE FileHash = @FileHash)
        BEGIN
            IF @StartedTran = 1 COMMIT;
            SELECT CAST(0 AS bit) AS IsSuccessful,
                   N'تم استيراد نفس الملف سابقاً، ولن يتم تكرار الإدخال.' AS Message_,
                   0 AS InsertedRows;
            RETURN;
        END

        ;WITH Clean AS
        (
            SELECT
                UploadExcel1 = NULLIF(LTRIM(RTRIM(UploadExcel1)), N''),
                UploadExcel2 = NULLIF(LTRIM(RTRIM(UploadExcel2)), N''),
                UploadExcel3 = NULLIF(LTRIM(RTRIM(UploadExcel3)), N''),
                UploadExcel4 = NULLIF(LTRIM(RTRIM(UploadExcel4)), N'')
            FROM @Rows
            WHERE NOT (
                NULLIF(LTRIM(RTRIM(ISNULL(UploadExcel1,N''))), N'') IS NULL AND
                NULLIF(LTRIM(RTRIM(ISNULL(UploadExcel2,N''))), N'') IS NULL AND
                NULLIF(LTRIM(RTRIM(ISNULL(UploadExcel3,N''))), N'') IS NULL AND
                NULLIF(LTRIM(RTRIM(ISNULL(UploadExcel4,N''))), N'') IS NULL
            )
        )
        -- ✅ إدخال مباشر بدون منع تكرار داخل الجدول/الدفعة
        INSERT INTO [Housing].[UploadExcel] ([UploadExcel1],[UploadExcel2],[UploadExcel3],[UploadExcel4],[Column1Name],[Column2Name],[Column3Name],[Column4Name])
        SELECT UploadExcel1, UploadExcel2, UploadExcel3, UploadExcel4,@Column1Name,@Column2Name,@Column3Name ,@Column4Name
        FROM Clean;

        DECLARE @Inserted int = @@ROWCOUNT;

        INSERT INTO [Housing].[UploadExcelImportLog] (FileHash, OriginalFileName, InsertedRows)
        VALUES (@FileHash, @OriginalFileName, @Inserted);

        IF @StartedTran = 1 COMMIT;

        SELECT CAST(1 AS bit) AS IsSuccessful,
               CONCAT(N'تم إدخال ', @Inserted, N' صف بنجاح.') AS Message_,
               @Inserted AS InsertedRows;
    END TRY
    BEGIN CATCH
        IF @StartedTran = 1 AND @@TRANCOUNT > 0 ROLLBACK;
        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [Housing].[WaitingListByResidentDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [Housing].[WaitingListByResidentDL] 
	-- Add the parameters for the stored procedure here
	    @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
	, @NationalID      NVARCHAR(400)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   

          -- One Resident Data

             SELECT distinct
                 fr.residentInfoID [residentInfoID]
                ,fr.NationalID [NationalID]
                ,fr.generalNo_FK [generalNo_FK]
                ,fr.firstName_A [firstName_A]
                ,fr.secondName_A [secondName_A]
                ,fr.thirdName_A [thirdName_A]
                ,fr.lastName_A [lastName_A]
                ,fr.firstName_E [firstName_E]
                ,fr.secondName_E [secondName_E]
                ,fr.thirdName_E [thirdName_E]
                ,fr.lastName_E [lastName_E]
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_A,
                     fr.secondName_A,
                     fr.thirdName_A,
                     fr.lastName_A
                 )
                 )) AS FullName_A
                ,LTRIM(RTRIM(
                 CONCAT_WS(N' ',
                     fr.firstName_E,
                     fr.secondName_E,
                     fr.thirdName_E,
                     fr.lastName_E
                 )
                 )) AS FullName_E
                ,fr.rankID_FK [rankID_FK]
                ,fr.rankNameA
                ,fr.militaryUnitID_FK [militaryUnitID_FK]
                ,fr.militaryUnitName_A
                ,fr.martialStatusID_FK [martialStatusID_FK]
                ,fr.maritalStatusName_A
                ,fr.dependinceCounter [dependinceCounter]
                ,fr.nationalityID_FK [nationalityID_FK]
                ,fr.nationalityName_A
                ,fr.genderID_FK [genderID_FK]
                ,fr.genderName_A
                ,convert(nvarchar(10),fr.birthdate,23) birthdate
                ,fr.residentcontactDetails
                ,fr.note [note]
                ,fr.IdaraID IdaraID
                ,fr.IdaraName IdaraName
                ,(select count(*) from Housing.V_WaitingList w where w.NationalID = @NationalID and w.IdaraId = @idaraID and (w.LastActionTypeID IS NULL OR w.LastActionTypeID not in (19,53)) and w.IdaraId = @idaraID) WaitingListCount
                ,(select count(*) from Housing.V_WaitingListByLetter w where w.NationalID = @NationalID and w.IdaraId = @idaraID and (w.LastActionTypeID IS NULL OR w.LastActionTypeID not in (19,53)) and w.IdaraId = @idaraID) WaitingListByLetterCount

           FROM [DATACORE].[Housing].V_GetFullResidentDetails fr
           where fr.NationalID = @NationalID

            

            --Get Waiting List By Resident Nationl ID


            SELECT 
            w.ActionID,
            w.NationalID,
            w.GeneralNo + '1' GeneralNo,
            w.ActionDecisionNo,
            convert(nvarchar(10),w.[ActionDecisionDate],23) ActionDecisionDate,
            w.WaitingClassID,
            w.WaitingClassName,
            w.WaitingOrderTypeID,
            w.WaitingOrderTypeName,
            w.waitingClassSequence,
            w.residentInfoID,
            w.ActionNote,
            rd.FullName_A FullName_A,
            isnull(w.LastActionTypeID,0) LastActionTypeID,
            isnull(w.LastActionTypeName,N'لايوجد اجراء') LastActionTypeName,
            isnull(w.LastActionID,0) LastActionID
            FROM Housing.V_WaitingList w 
            inner join Housing.V_GetFullResidentDetails rd on w.residentInfoID = rd.residentInfoID 
            where w.NationalID = @NationalID
            AND w.IdaraId = @idaraID
            AND rd.IdaraID = @idaraID
            AND w.ActionTypeID = 1
            --AND (w.LastActionID is null or w.LastActionTypeID in (34,35))

             --Get Letter Waiting List By Resident Nationl ID


            SELECT 
            w.ActionID,
            w.NationalID,
            w.GeneralNo,
            w.ActionDecisionNo,
            convert(nvarchar(10),w.[ActionDecisionDate],23) ActionDecisionDate,
            w.WaitingClassID,
            w.WaitingClassName,
            w.WaitingOrderTypeID,
            w.WaitingOrderTypeName,
            w.waitingClassSequence,
            w.residentInfoID,
            w.ActionNote,
            rd.FullName_A FullName_A,
            isnull(w.LastActionTypeID,0) LastActionTypeID,
            isnull(w.LastActionTypeName,N'لايوجد اجراء') LastActionTypeName,
            isnull(w.LastActionID,0) LastActionID
            FROM Housing.V_WaitingList w 
            inner join Housing.V_GetFullResidentDetails rd on w.residentInfoID = rd.residentInfoID 
            where w.NationalID = @NationalID
            AND w.IdaraId = @idaraID
            AND rd.IdaraID = @idaraID
            AND w.ActionTypeID = 7

            -- Request Move To Other Idara List


        SELECT [ActionID]
              ,[residentInfoID]
              ,[NationalID]
              ,[GeneralNo]
              ,[fullname]
              ,[ActionDecisionNo]
              ,convert(nvarchar(10),[ActionDecisionDate],23) ActionDecisionDate
              ,[ActionDate]
              ,[IdaraId]
              ,[ActionIdaraName]
              ,[ToIdaraID]
              ,[Toidaraname]
              ,[WaitingListCount]
              ,[MainActionEntryData]
              ,convert(nvarchar(19),[MainActionEntryDate],120) MainActionEntryDate
              ,[ActionNote]
              ,[LastActionID]
              ,[LastActionTypeID]
              ,[LastActionIdaraID]
              ,[LastActionIdaraName]
              ,[LastActionTypeName]
              
              ,convert(nvarchar(19),[LastActionEntryDate],120) LastActionEntryDate
              ,[LastActionNote]
              ,[LastActionEntryData]
              ,[ActionStatus]
              
          FROM [DATACORE].[Housing].[V_MoveWaitingList] mw
          where mw.NationalID = @NationalID 
          and mw.IdaraId = @idaraID
          order by mw.ActionID desc





             -- WaitingClass DDL
            SELECT w.waitingClassID,w.waitingClassName_A
            FROM [DATACORE].[Housing].[WaitingClass] w
            WHERE w.idara_FK is null or w.idara_FK = @idaraID
            order by w.waitingClassID asc


            -- WaitingOrderType DDL
            SELECT r.waitingOrderTypeID,r.waitingOrderTypeName_A
            FROM [DATACORE].[Housing].[WaitingOrderType] r
            

            
            -- Idaras DDL
            SELECT r.idaraID,r.idaraLongName_A
            FROM [DATACORE].[dbo].[Idara] r
            where r.idaraID <> @idaraID
            order by r.idaraID asc
            

            SELECT B.buildingActionTypeID,B.buildingActionTypeName_A
            FROM Housing.BuildingActionType B
            WHERE B.buildingActionTypeID IN (19,53)







    -- Insert statements for procedure here
END
GO
/****** Object:  StoredProcedure [Housing].[WaitingListByResidentSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Housing].[WaitingListByResidentSP] 
(
      @Action                       NVARCHAR(200)
    , @ActionID                     BIGINT          = NULL
    , @residentInfoID_FK            NVARCHAR(100)   = NULL
    , @NationalID                   NVARCHAR(100)   = NULL
    , @GeneralNo                    NVARCHAR(100)   = NULL
    , @buildingActionDecisionNo     NVARCHAR(1000)  = NULL
    , @buildingActionDecisionDate   NVARCHAR(1000)  = NULL
    , @WaitingClassID               NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeID           NVARCHAR(1000)  = NULL
    , @ActionTypeID                 NVARCHAR(1000)  = NULL
    , @Notes                        NVARCHAR(1000)  = NULL
    , @NewIdaraForMoveWaitingList   NVARCHAR(1000)  = NULL
    , @idaraID_FK                   NVARCHAR(10)    = NULL
    , @entryData                    NVARCHAR(20)    = NULL
    , @hostName                     NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));

    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

        IF @Action IN(N'INSERTWAITINGLIST',N'UPDATEWAITINGLIST')
        BEGIN
       
            IF NULLIF(LTRIM(RTRIM(@residentInfoID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - resident ID', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@GeneralNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - GN', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@NationalID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - @NationalID', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'رقم القرار مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionDate)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'تاريخ القرار مطلوب', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@WaitingClassID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'فئة قائمة الانتظار مطلوبة', 1;
            END


             IF NULLIF(LTRIM(RTRIM(@WaitingOrderTypeID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'نوع فئة الانتظار مطلوبة', 1;
            END
        END


        IF @Action IN(N'INSERTOCCUBENTLETTER',N'UPDATEOCCUBENTLETTER')
        BEGIN
       
            IF NULLIF(LTRIM(RTRIM(@residentInfoID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - resident ID', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@GeneralNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - GN', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@NationalID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - @NationalID', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'رقم القرار مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionDate)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'تاريخ القرار مطلوب', 1;
            END

            -- IF NULLIF(LTRIM(RTRIM(@WaitingClassID)), N'') IS NULL
            --BEGIN
            --    ;THROW 50001, N'فئة قائمة الانتظار مطلوبة', 1;
            --END


            -- IF NULLIF(LTRIM(RTRIM(@WaitingOrderTypeID)), N'') IS NULL
            --BEGIN
            --    ;THROW 50001, N'نوع فئة الانتظار مطلوبة', 1;
            --END
        END



         IF @Action IN(N'MOVEWAITINGLIST',N'DELETERESIDENTALLWAITINGLIST')
        BEGIN
            --IF NULLIF(LTRIM(RTRIM(@ActionID)), N'') IS NULL
            --BEGIN
            --    ;THROW 50001, N'يوجد خطأ بجلب بيانات سجل الانتظار - Action ID', 1;
            --END

            IF NULLIF(LTRIM(RTRIM(@residentInfoID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - resident ID', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@GeneralNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - GN', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@NationalID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - @NationalID', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'رقم القرار مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionDate)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'تاريخ القرار مطلوب', 1;
            END

            -- IF NULLIF(LTRIM(RTRIM(@WaitingClassID)), N'') IS NULL
            --BEGIN
            --    ;THROW 50001, N'فئة قائمة الانتظار مطلوبة', 1;
            --END


            -- IF NULLIF(LTRIM(RTRIM(@WaitingOrderTypeID)), N'') IS NULL
            --BEGIN
            --    ;THROW 50001, N'نوع فئة الانتظار مطلوبة', 1;
            --END
        END

        ----------------------------------------------------------------
        -- INSERTWAITINGLIST
        ----------------------------------------------------------------
        IF @Action = N'INSERTWAITINGLIST'
        BEGIN

         if exists(SELECT 1
                FROM  Housing.V_MoveWaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  and w.IdaraId = @idaraID_FK
                  )
                  begin
                  
            if (
                SELECT top(1) W.LastActionTypeID
                FROM  Housing.V_MoveWaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  and w.IdaraId = @idaraID_FK 
                  order by w.ActionID desc
            ) = 33
            BEGIN
                ;THROW 50001, N'لايمكن تعديل سجل انتظار جديد للمستفيد لوجود طلب نقل له الى ادارة اخرى', 1;
            END
            end

        

            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.WaitingClassID = @WaitingClassID
            )
            BEGIN
                ;THROW 50001, N'يوجد سجل انتظار مدرج للمستفيد بالنظام بنفس الفئة', 1;
            END

        
        
            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.LastActionTypeID in(19)
                  AND w.IdaraId = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'تم الغاء جميع سجلات الانتظار للمستفيد مسبقا بسبب التقاعد', 1;
            END


            
            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.LastActionTypeID in (53)
                  AND w.IdaraId = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'تم الغاء جميع سجلات الانتظار للمستفيد مسبقا بسبب الفصل', 1;
            END


             IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.V_GetFullResidentDetails w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.IdaraID = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'ملف المستفيد ليس في ادارتك حاليا', 1;
            END


            INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingActionExtraType1
                , buildingActionExtraType2
                , buildingActionActive
                , buildingActionNote
                , IdaraId_FK
                , entryData
                , hostName
            )
            VALUES
            (
                  1
                , @residentInfoID_FK
                , @GeneralNo
                , @buildingActionDecisionNo
                , @buildingActionDecisionDate
                , @WaitingClassID
                , @WaitingOrderTypeID
                , 1
                , @Notes
                , @IdaraID_INT
                , @entryData
                , @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البيانات', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في اضافة البيانات - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "1"'
                + N',"residentInfoID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID_FK), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "' + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionNo), '') + N'"'
                + N',"buildingActionDecisionDate": "' + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionDate), '') + N'"'
                + N',"buildingActionExtraType1": "' + ISNULL(CONVERT(NVARCHAR(MAX), @WaitingClassID), '') + N'"'
                + N',"buildingActionExtraType2": "' + ISNULL(CONVERT(NVARCHAR(MAX), @WaitingOrderTypeID), '') + N'"'
                + N',"buildingActionActive": "1"'
                + N',"buildingActionNote": "' + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"IdaraId_FK": "'               + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                 + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'INSERTWAITINGLIST'
                , ISNULL(@NewID, 0)
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم اضافة البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- UPDATEWAITINGLIST
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPDATEWAITINGLIST'
        BEGIN
       
            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END

            if exists(SELECT 1
                FROM  Housing.V_MoveWaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  and w.IdaraId = @idaraID_FK
                  )
                  begin
                  
            if (
                SELECT top(1) W.LastActionTypeID
                FROM  Housing.V_MoveWaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  and w.IdaraId = @idaraID_FK 
                  order by w.ActionID desc
            ) = 33
            BEGIN
                ;THROW 50001, N'لايمكن تعديل سجل انتظار جديد للمستفيد لوجود طلب نقل له الى ادارة اخرى', 1;
            END
            end
            
            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.LastActionTypeID in(19)
                  AND w.IdaraId = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'تم الغاء جميع سجلات الانتظار للمستفيد مسبقا بسبب التقاعد', 1;
            END


            
            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.LastActionTypeID in (53)
                  AND w.IdaraId = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'تم الغاء جميع سجلات الانتظار للمستفيد مسبقا بسبب الفصل', 1;
            END


             IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.V_GetFullResidentDetails w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.IdaraID = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'ملف المستفيد ليس في ادارتك حاليا', 1;
            END


            --if exists (SELECT 1
            --    FROM  Housing.V_WaitingList w
            --    WHERE w.residentInfoID = @residentInfoID_FK
            --      AND w.buildingActionRoot in (2,3)
            --      AND w.ActionID = @ActionID
            --      AND w.IdaraId = @idaraID_FK)

            --      BEGIN
            --    ;THROW 50001, N'لايمكن التعديل على سجل الانتظار لوجود اجراءات تسكين او اخلاء تمت على هذا السجل', 1;
            --      END

             if exists (SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.LastActionTypeID is not null and w.LastActionTypeID not in (34,35)
                  AND w.ActionID = @ActionID
                  AND w.IdaraId = @idaraID_FK)

                  BEGIN
                ;THROW 50001, N'لايمكن التعديل على سجل الانتظار لوجود اجراءات تمت على هذا السجل', 1;
                  END




            UPDATE  Housing.BuildingAction
            SET

                  buildingActionDecisionNo      = ISNULL(@buildingActionDecisionNo, buildingActionDecisionNo)
                , buildingActionDecisionDate    = ISNULL(@buildingActionDecisionDate, buildingActionDecisionDate)
                --, buildingActionExtraType1      = ISNULL(@WaitingClassID, buildingActionExtraType1)
                , buildingActionExtraType2      = ISNULL(@WaitingOrderTypeID, buildingActionExtraType2)
                , buildingActionNote            = ISNULL(@Notes, buildingActionNote)
                , IdaraId_FK                    = ISNULL(@IdaraID_INT, IdaraId_FK)
                , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)

                
            WHERE buildingActionID = @ActionID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1; -- برمجي/غير متوقع
            END

             SET @Note = N'{'
                + N'"buildingActionID": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @ActionID), '') + N'"'
                + N',"buildingActionTypeID_FK": "1"'
                + N',"residentInfoID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID_FK), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "' + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionNo), '') + N'"'
                + N',"buildingActionDecisionDate": "' + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionDate), '') + N'"'
                + N',"buildingActionExtraType1": "' + ISNULL(CONVERT(NVARCHAR(MAX), @WaitingClassID), '') + N'"'
                + N',"buildingActionExtraType2": "' + ISNULL(CONVERT(NVARCHAR(MAX), @WaitingOrderTypeID), '') + N'"'
                + N',"buildingActionActive": "1"'
                + N',"buildingActionNote": "' + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"IdaraId_FK": "'               + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"entryData": "'                + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'                 + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'UPDATEWAITINGLIST'
                , @ActionID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم تحديث البيانات بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- DELETEWAITINGLIST (Soft Delete)
        ----------------------------------------------------------------
        ELSE IF @Action = N'DELETEWAITINGLIST'
        BEGIN

        
             IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END



            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.LastActionTypeID in(19)
                  AND w.IdaraId = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'تم الغاء جميع سجلات الانتظار للمستفيد مسبقا بسبب التقاعد', 1;
            END


            
            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.LastActionTypeID in (53)
                  AND w.IdaraId = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'تم الغاء جميع سجلات الانتظار للمستفيد مسبقا بسبب الفصل', 1;
            END


              IF NOT EXISTS
            (
                SELECT 1
                FROM  Housing.V_GetFullResidentDetails w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.IdaraID = @idaraID_FK
            )
            BEGIN
                ;THROW 50001, N'ملف المستفيد ليس في ادارتك حاليا', 1;
            END


             if exists(SELECT 1
                FROM  Housing.V_MoveWaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  and w.IdaraId = @idaraID_FK
                  )
                  begin
                  
            if (
                SELECT top(1) W.LastActionTypeID
                FROM  Housing.V_MoveWaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  and w.IdaraId = @idaraID_FK 
                  order by w.ActionID desc
            ) = 33
            BEGIN
                ;THROW 50001, N'لايمكن حذف سجل انتظار جديد للمستفيد لوجود طلب نقل له الى ادارة اخرى', 1;
            END
            end

              if exists (SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.LastActionTypeID is not null and w.LastActionTypeID not in (34,35)
                  AND w.ActionID = @ActionID
                  AND w.IdaraId = @idaraID_FK)

                  BEGIN
                ;THROW 50001, N'لايمكن حذف سجل الانتظار لوجود اجراءات  تمت على هذا السجل', 1;
                  END


            UPDATE  Housing.BuildingAction
            SET
                  buildingActionActive = 0
                , entryData = ISNULL(ISNULL(entryData,'')+N','+@entryData, entryData)
                , hostName  = ISNULL(ISNULL(@hostName,'')+N','+@hostName, hostName)
            WHERE buildingActionID = @ActionID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم حذف أي سجل', 1; -- برمجي/غير متوقع
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @ActionID), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingClass]'
                , N'DELETEWAITINGLIST'
                , @ActionID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم حذف البيانات بنجاح' AS Message_;
            RETURN;
        END


        ----------------------------------------------------------------
        -- INSERTOCCUBENTLETTER
        ----------------------------------------------------------------
        ELSE IF @Action = N'INSERTOCCUBENTLETTER'
        BEGIN

            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  AND w.IdaraId = @IdaraID_INT
                  AND w.ActionTypeID = 7
            )
            BEGIN
                ;THROW 50001, N'يوجد خطاب تسكين للمستفيد بالنظام بنفس الادارة', 1;
            END


             
             if exists(SELECT 1
                FROM  Housing.V_MoveWaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  and w.IdaraId = @idaraID_FK
                  )
                  begin
                  
            if (
                SELECT top(1) W.LastActionTypeID
                FROM  Housing.V_MoveWaitingList w
                WHERE w.residentInfoID = @residentInfoID_FK
                  and w.IdaraId = @idaraID_FK 
                  order by w.ActionID desc
            ) = 33

            BEGIN
                ;THROW 50001, N'لايمكن ادراج خطاب تسكين جديد للمستفيد لوجود طلب نقل له الى ادارة اخرى', 1;
            END

            end

            


        
            IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
