CREATE PROCEDURE [Housing].[WaitingListSP] 
(
      @Action                       NVARCHAR(200)
    , @ActionID                     BIGINT          = NULL
    , @residentInfoID_FK            NVARCHAR(100)   = NULL
    , @residentName                 NVARCHAR(100)   = NULL
    , @NationalID                   NVARCHAR(100)   = NULL
    , @GeneralNo                    NVARCHAR(100)   = NULL
    , @buildingActionDecisionNo     NVARCHAR(1000)  = NULL
    , @buildingActionDecisionDate   NVARCHAR(1000)  = NULL
    , @WaitingClassID               NVARCHAR(1000)  = NULL
    , @WaitingClassName             NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeID           NVARCHAR(1000)  = NULL
    , @WaitingOrderTypeName         NVARCHAR(1000)  = NULL
    , @Notes                        NVARCHAR(1000)  = NULL
    , @idaraID_FK                   NVARCHAR(10)    = NULL
    , @entryData                    NVARCHAR(20)    = NULL
    , @hostName                     NVARCHAR(200)   = NULL
)

AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE 
          @NewID BIGINT = NULL
        , @Note  NVARCHAR(MAX) = NULL;

    -- تحويلات رقمية آمنة
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, NULLIF(@idaraID_FK, ''));

    BEGIN TRY
        -- Transaction-safe
        IF @tc = 0
            BEGIN TRAN;

        ----------------------------------------------------------------
        -- Business validations => THROW 50001
        ----------------------------------------------------------------
        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

            IF NULLIF(LTRIM(RTRIM(@ActionID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات سجل الانتظار - Action ID', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@residentInfoID_FK)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - resident ID', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@GeneralNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - GN', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@NationalID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'يوجد خطأ بجلب بيانات المستفيد - @NationalID', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionNo)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'رقم القرار مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@buildingActionDecisionDate)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'تاريخ القرار مطلوب', 1;
            END

         IF NULLIF(LTRIM(RTRIM(@WaitingClassID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'فئة سجل الانتظار مطلوبة', 1;
            END

             IF NULLIF(LTRIM(RTRIM(@WaitingOrderTypeID)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'ترتيب سجل الانتظار مطلوبة', 1;
            END


        ----------------------------------------------------------------
        -- MOVETOASSIGNLIST
        ----------------------------------------------------------------
        IF @Action = N'MOVETOASSIGNLIST'
         BEGIN

        
            IF @ActionID IS NULL
            BEGIN
                ;THROW 50001, N'رقم السجل مطلوب للتحديث', 1;
            END

            IF NOT EXISTS
            (
                 SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID
            )
            BEGIN
                ;THROW 50001, N'السجل غير موجود', 1;
            END


             IF EXISTS
            (
                SELECT 1
                FROM  Housing.V_WaitingList w
                WHERE w.ActionID = @ActionID and w.LastActionTypeID = 27 and w.ToIdaraID = @idaraID_FK
                  
            )
            BEGIN
                ;THROW 50001, N'تم اتخاذ اجراء للطلب مسبقا', 1;
            END



              
                DECLARE @MyOrder int;
                DECLARE @ErrMsg_  nvarchar(4000);
                
                SELECT @MyOrder = x.rn
                FROM
                (
                    SELECT
                        w.ActionID,
                        ROW_NUMBER() OVER (ORDER BY w.ActionDecisionDate ASC,w.ActionDecisionNo ASC, w.GeneralNo ASC) AS rn
                   FROM Housing.V_WaitingList w
                   INNER JOIN Housing.V_GetFullResidentDetails rd 
                       ON w.residentInfoID = rd.residentInfoID
                   WHERE w.WaitingClassID = @WaitingClassID
                     AND w.IdaraId = @idaraID_FK
                     AND  (w.LastActionTypeID is null or w.LastActionTypeID in (34,35))
                ) x
                WHERE x.ActionID = @ActionID;
                
                IF @MyOrder IS NULL
                BEGIN
                    SET @ErrMsg_ = N'لم يتم العثور على الطلب داخل قائمة الانتظار';
                    ;THROW 50001, @ErrMsg_, 1;
                END
                
                IF cast(@MyOrder as int) <> 1
                BEGIN
                    SET @ErrMsg_ =
                        N' المستفيد '+CAST(@residentName AS nvarchar(200))+N' ليس في رأس قائمة الانتظار في '
                        + CAST(@WaitingClassName AS nvarchar(20));
                    ;THROW 50001, @ErrMsg_, 1;
                END

              

           

             INSERT INTO  Housing.BuildingAction
            (
                  buildingActionTypeID_FK
                , residentInfoID_FK
                , generalNo_FK
                , buildingActionDecisionNo
                , buildingActionDecisionDate
                , buildingActionExtraType1
                , buildingActionExtraType2
                , buildingActionActive
                , buildingActionNote
                , buildingActionParentID
                , IdaraId_FK
                , entryData
                , hostName
            )
            
             VALUES
            (
                  27
                , @residentInfoID_FK
                , @GeneralNo
                , @buildingActionDecisionNo
                , @buildingActionDecisionDate
                , @WaitingClassID
                , @WaitingOrderTypeID
                , 1
                , @Notes
                , @ActionID
                , @IdaraID_INT
                , @entryData
                , @hostName
            );
            
       

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في نقل لقائمة التخصيص', 1; -- برمجي
            END
            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في النقل لقائمة التخصيص - Identity', 1; -- برمجي
            END
            SET @Note = N'{'
                + N'"buildingActionID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
                + N',"buildingActionTypeID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), 27), '') + N'"'
                + N',"residentInfoID_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @residentInfoID_FK), '') + N'"'
                + N',"generalNo_FK": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @GeneralNo), '') + N'"'
                + N',"buildingActionDecisionNo": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionNo), '') + N'"'
                + N',"buildingActionDecisionDate": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @buildingActionDecisionDate), '') + N'"'
                + N',"buildingActionActive": "'      + ISNULL(CONVERT(NVARCHAR(MAX), '1'), '') + N'"'
                + N',"buildingActionNote": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
                + N',"buildingActionParentID": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @ActionID), '') + N'"'
                + N',"entryData": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO  dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[Housing].[BuildingAction]'
                , N'MOVETOASSIGNLIST'
                , @ActionID
                , @entryData
                , @Note
            );

            SELECT 1 AS IsSuccessful, N'تم النقل لقائمة التخصيص بنجاح' AS Message_;
            RETURN;
        END

       
         ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END


     END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [support].[SupportInboxDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE   PROCEDURE [support].[SupportInboxDL]
      @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      BIGINT
    , @hostname       NVARCHAR(400)
    , @statusID       TINYINT = NULL
    , @priorityID     TINYINT = NULL
    , @ticketTypeID   TINYINT = NULL
    , @assignedToID   BIGINT  = NULL
    , @dateFrom       DATE    = NULL
    , @dateTo         DATE    = NULL
    , @searchText     NVARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [support].[TeamMember] tm
        WHERE tm.userID_FK = @entrydata
          AND tm.teamMemberActive = 1
    )
    BEGIN
        THROW 50001, N'عفوا لاتملك صلاحية عرض صندوق الدعم', 1;
    END

    SELECT t.ticketID, t.ticketNo, t.ticketTitle, t.ticketDescription,
           tt.ticketTypeName_A, tp.priorityName_A, ts.statusName_A,
           t.createdByUserID_FK, uc.nationalID AS createdByNationalID,
           t.assignedToTeamMemberID_FK, tm.userID_FK AS assignedToUserID, ua.nationalID AS assignedToNationalID,
           t.affectedPageName, t.affectedActionName, t.entryDate, t.assignedDate, t.closedDate
    FROM [support].[Ticket] t
    INNER JOIN [support].[TicketType] tt ON tt.ticketTypeID = t.ticketTypeID_FK
    INNER JOIN [support].[TicketPriority] tp ON tp.priorityID = t.priorityID_FK
    INNER JOIN [support].[TicketStatus] ts ON ts.statusID = t.statusID_FK
    LEFT JOIN [support].[TeamMember] tm ON tm.teamMemberID = t.assignedToTeamMemberID_FK
    LEFT JOIN [dbo].[Users] uc ON uc.usersID = t.createdByUserID_FK
    LEFT JOIN [dbo].[Users] ua ON ua.usersID = tm.userID_FK
    WHERE t.ticketActive = 1
      AND (@statusID IS NULL OR t.statusID_FK = @statusID)
      AND (@priorityID IS NULL OR t.priorityID_FK = @priorityID)
      AND (@ticketTypeID IS NULL OR t.ticketTypeID_FK = @ticketTypeID)
      AND (@assignedToID IS NULL OR t.assignedToTeamMemberID_FK = @assignedToID)
      AND (@dateFrom IS NULL OR CAST(t.entryDate AS DATE) >= @dateFrom)
      AND (@dateTo IS NULL OR CAST(t.entryDate AS DATE) <= @dateTo)
      AND (
            NULLIF(LTRIM(RTRIM(ISNULL(@searchText, N''))), N'') IS NULL
            OR t.ticketNo LIKE N'%' + @searchText + N'%'
            OR t.ticketTitle LIKE N'%' + @searchText + N'%'
            OR t.ticketDescription LIKE N'%' + @searchText + N'%'
          )
    ORDER BY t.ticketID DESC;

    SELECT statusID, statusName_A FROM [support].[TicketStatus] WHERE statusActive = 1 ORDER BY statusID;
    SELECT priorityID, priorityName_A FROM [support].[TicketPriority] WHERE priorityActive = 1 ORDER BY priorityID;
    SELECT ticketTypeID, ticketTypeName_A FROM [support].[TicketType] WHERE ticketTypeActive = 1 ORDER BY ticketTypeID;

    SELECT tm.teamMemberID, tm.userID_FK, u.nationalID AS userName
    FROM [support].[TeamMember] tm
    INNER JOIN [dbo].[Users] u ON u.usersID = tm.userID_FK
    WHERE tm.teamMemberActive = 1 AND tm.canReceiveTickets = 1
    ORDER BY u.nationalID;
END

GO
/****** Object:  StoredProcedure [support].[SupportInboxSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [support].[SupportInboxSP]
(
      @Action                NVARCHAR(200)
    , @ticketID              BIGINT         = NULL
    , @statusID              TINYINT        = NULL
    , @assignToTeamMemberID  BIGINT         = NULL
    , @assignmentNote        NVARCHAR(1000) = NULL
    , @ticketIDsCsv          NVARCHAR(MAX)  = NULL
    , @entryData             NVARCHAR(20)   = NULL
    , @hostName              NVARCHAR(200)  = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @entryUserID BIGINT = TRY_CONVERT(BIGINT, @entryData)
        , @fromMemberID BIGINT = NULL
        , @rowsAffected INT = 0
        , @note NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @tc = 0
            BEGIN TRAN;

        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

        IF @entryUserID IS NULL
        BEGIN
            ;THROW 50001, N'المستخدم غير صالح', 1;
        END

        IF NOT EXISTS
        (
            SELECT 1 FROM [support].[TeamMember]
            WHERE userID_FK = @entryUserID AND teamMemberActive = 1
        )
        BEGIN
            ;THROW 50001, N'عفوا لاتملك صلاحية عمليات صندوق الدعم', 1;
        END

        IF @Action = N'SIN_ASSIGN'
        BEGIN
            IF @ticketID IS NULL OR @assignToTeamMemberID IS NULL
            BEGIN
                ;THROW 50001, N'بيانات التحويل غير مكتملة', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[Ticket] WHERE ticketID = @ticketID AND ticketActive = 1)
            BEGIN
                ;THROW 50001, N'التذكرة غير موجودة', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TeamMember] WHERE teamMemberID = @assignToTeamMemberID AND teamMemberActive = 1)
            BEGIN
                ;THROW 50001, N'الموظف غير موجود أو غير نشط', 1;
            END

            SELECT @fromMemberID = assignedToTeamMemberID_FK
            FROM [support].[Ticket]
            WHERE ticketID = @ticketID;

            UPDATE [support].[Ticket]
            SET assignedToTeamMemberID_FK = @assignToTeamMemberID,
                assignedByUserID_FK = @entryUserID,
                assignedDate = GETDATE(),
                statusID_FK = CASE WHEN statusID_FK = 1 THEN 2 ELSE statusID_FK END,
                entryData = ISNULL(ISNULL(entryData,N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName,N'') + N',' + @hostName, hostName)
            WHERE ticketID = @ticketID AND ticketActive = 1;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1;
            END

            INSERT INTO [support].[TicketAssignmentHistory]
            (ticketID_FK, fromTeamMemberID_FK, toTeamMemberID_FK, actionByUserID_FK, assignmentNote, entryData, hostName)
            VALUES (@ticketID, @fromMemberID, @assignToTeamMemberID, @entryUserID, @assignmentNote, @entryData, @hostName);

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تسجيل التحويل', 1;
            END

            SET @note = N'{"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketID), N'')
                      + N'","from":"' + ISNULL(CONVERT(NVARCHAR(20), @fromMemberID), N'')
                      + N'","to":"' + ISNULL(CONVERT(NVARCHAR(20), @assignToTeamMemberID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[Ticket]', N'SIN_ASSIGN', @ticketID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم تحويل التذكرة بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'SIN_CHANGE_STATUS'
        BEGIN
            IF @ticketID IS NULL OR @statusID IS NULL
            BEGIN
                ;THROW 50001, N'بيانات الحالة غير مكتملة', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TicketStatus] WHERE statusID = @statusID AND statusActive = 1)
            BEGIN
                ;THROW 50001, N'الحالة غير صالحة', 1;
            END

            UPDATE [support].[Ticket]
            SET statusID_FK = @statusID,
                closedDate = CASE WHEN @statusID = 4 THEN GETDATE() ELSE closedDate END,
                entryData = ISNULL(ISNULL(entryData,N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName,N'') + N',' + @hostName, hostName)
            WHERE ticketID = @ticketID AND ticketActive = 1;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1;
            END

            SET @note = N'{"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketID), N'')
                      + N'","statusID":"' + ISNULL(CONVERT(NVARCHAR(20), @statusID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[Ticket]', N'SIN_UPDATE_STATUS', @ticketID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم تحديث الحالة بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'SIN_BULK_ASSIGN'
        BEGIN
            IF NULLIF(LTRIM(RTRIM(ISNULL(@ticketIDsCsv, N''))), N'') IS NULL OR @assignToTeamMemberID IS NULL
            BEGIN
                ;THROW 50001, N'بيانات التحويل الجماعي غير مكتملة', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TeamMember] WHERE teamMemberID = @assignToTeamMemberID AND teamMemberActive = 1)
            BEGIN
                ;THROW 50001, N'الموظف غير موجود أو غير نشط', 1;
            END

            ;WITH ids AS
            (
                SELECT DISTINCT TRY_CONVERT(BIGINT, LTRIM(RTRIM(value))) AS ticketID
                FROM STRING_SPLIT(@ticketIDsCsv, ',')
                WHERE NULLIF(LTRIM(RTRIM(value)), N'') IS NOT NULL
            )
            UPDATE t
            SET assignedToTeamMemberID_FK = @assignToTeamMemberID,
                assignedByUserID_FK = @entryUserID,
                assignedDate = GETDATE(),
                statusID_FK = CASE WHEN statusID_FK = 1 THEN 2 ELSE statusID_FK END,
                entryData = ISNULL(ISNULL(entryData,N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName,N'') + N',' + @hostName, hostName)
            FROM [support].[Ticket] t
            INNER JOIN ids i ON i.ticketID = t.ticketID
            WHERE t.ticketActive = 1;

            SET @rowsAffected = @@ROWCOUNT;
            IF @rowsAffected <= 0
            BEGIN
                ;THROW 50001, N'لا توجد تذاكر صالحة للتحويل الجماعي', 1;
            END

            SET @note = N'{"assignTo":"' + ISNULL(CONVERT(NVARCHAR(20), @assignToTeamMemberID), N'')
                      + N'","count":"' + ISNULL(CONVERT(NVARCHAR(20), @rowsAffected), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[Ticket]', N'SIN_BULK_ASSIGN', 0, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم التحويل الجماعي بنجاح' AS Message_;
            RETURN;
        END
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END

GO
/****** Object:  StoredProcedure [support].[SupportMyTicketsDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE PROCEDURE [support].[SupportMyTicketsDL]
      @pageName_ NVARCHAR(400)
    , @idaraID   INT
    , @entrydata BIGINT
    , @hostname  NVARCHAR(400)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT t.ticketID, t.ticketNo, t.ticketTitle, t.ticketDescription,
           tt.ticketTypeName_A, tp.priorityName_A, ts.statusName_A,
           t.affectedPageName, t.affectedPageUrl, t.affectedActionName,
           t.entryDate, t.assignedDate, t.closedDate
    FROM [support].[Ticket] t
    INNER JOIN [support].[TicketType] tt ON tt.ticketTypeID = t.ticketTypeID_FK
    INNER JOIN [support].[TicketPriority] tp ON tp.priorityID = t.priorityID_FK
    INNER JOIN [support].[TicketStatus] ts ON ts.statusID = t.statusID_FK
    WHERE t.ticketActive = 1 AND t.createdByUserID_FK = @entrydata
    ORDER BY t.ticketID DESC;

    SELECT ticketTypeID, ticketTypeName_A
    FROM [support].[TicketType]
    WHERE ticketTypeActive = 1
    ORDER BY ticketTypeID;

    SELECT priorityID, priorityName_A
    FROM [support].[TicketPriority]
    WHERE priorityActive = 1
    ORDER BY priorityID;

    -- الصفحات المسموح بها للمستخدم
    SELECT DISTINCT
           v.menuID,
           m.menuName_A,
           m.menuName_E,
           m.menuLink
    FROM dbo.V_GetListUserPermission v
    INNER JOIN dbo.Menu m ON m.menuID = v.menuID
    WHERE v.userID = @entrydata
      AND ISNULL(m.menuActive, 1) = 1
      AND NULLIF(LTRIM(RTRIM(ISNULL(m.menuName_A, N''))), N'') IS NOT NULL
      AND NULLIF(LTRIM(RTRIM(ISNULL(m.menuLink, N''))), N'') IS NOT NULL
      AND (
            v.permissionTypeName_E = N'SELECT'
         OR v.permissionTypeName_E = N'ACCESS'
         OR v.permissionTypeName_E LIKE N'%_SELECT'
         OR v.permissionTypeName_E LIKE N'%_ACCESS'
      )
    ORDER BY m.menuName_A;

    -- الإجراءات المسموح بها لكل صفحة للمستخدم الحالي
    SELECT DISTINCT
           v.menuID,
           v.menuName_A,
           v.menuName_E,
           v.permissionTypeName_A,
           v.permissionTypeName_E
    FROM dbo.V_GetListUserPermission v
    WHERE v.userID = @entrydata
      AND NULLIF(LTRIM(RTRIM(ISNULL(v.menuName_A, N''))), N'') IS NOT NULL
      AND NULLIF(LTRIM(RTRIM(ISNULL(v.permissionTypeName_A, N''))), N'') IS NOT NULL
      AND NOT (
            v.permissionTypeName_E = N'ACCESS'
         OR v.permissionTypeName_E = N'SELECT'
         OR v.permissionTypeName_E LIKE N'%_ACCESS'
         OR v.permissionTypeName_E LIKE N'%_SELECT'
      )
    ORDER BY v.menuName_A, v.permissionTypeName_A;

    SELECT statusID, statusName_A
    FROM [support].[TicketStatus]
    WHERE statusActive = 1
    ORDER BY statusID;
END

GO
/****** Object:  StoredProcedure [support].[SupportMyTicketsSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE PROCEDURE [support].[SupportMyTicketsSP]
(
      @Action             NVARCHAR(200)
    , @ticketTypeID       TINYINT       = NULL
    , @priorityID         TINYINT       = NULL
    , @ticketTitle        NVARCHAR(300) = NULL
    , @ticketDescription  NVARCHAR(MAX) = NULL
    , @affectedPageName   NVARCHAR(200) = NULL
    , @affectedPageUrl    NVARCHAR(500) = NULL
    , @affectedActionName NVARCHAR(200) = NULL
    , @errorDetails       NVARCHAR(MAX) = NULL
    , @entryData          NVARCHAR(20)  = NULL
    , @hostName           NVARCHAR(200) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @newID BIGINT = NULL
        , @seq BIGINT = NULL
        , @ticketNo NVARCHAR(30) = NULL
        , @entryUserID BIGINT = TRY_CONVERT(BIGINT, @entryData)
        , @note NVARCHAR(MAX) = NULL
        , @affectedPageNameClean NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@affectedPageName)), N'')
        , @affectedPageUrlClean NVARCHAR(500) = NULLIF(LTRIM(RTRIM(@affectedPageUrl)), N'')
        , @affectedActionNameClean NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@affectedActionName)), N'');

    BEGIN TRY
        IF @tc = 0
            BEGIN TRAN;

        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
            THROW 50001, N'العملية مطلوبة', 1;

        IF @Action <> N'SMT_CREATE_TICKET'
            THROW 50001, N'العملية غير مسجلة', 1;

        IF @entryUserID IS NULL
            THROW 50001, N'المستخدم غير صالح', 1;

        IF @ticketTypeID IS NULL
            THROW 50001, N'نوع التذكرة مطلوب', 1;

        IF NOT EXISTS (SELECT 1 FROM [support].[TicketType] WHERE ticketTypeID = @ticketTypeID AND ticketTypeActive = 1)
            THROW 50001, N'نوع التذكرة غير صالح', 1;

        IF @priorityID IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM [support].[TicketPriority] WHERE priorityID = @priorityID AND priorityActive = 1)
            THROW 50001, N'أولوية التذكرة غير صالحة', 1;

        IF NULLIF(LTRIM(RTRIM(@ticketTitle)), N'') IS NULL
            THROW 50001, N'عنوان التذكرة مطلوب', 1;

        IF NULLIF(LTRIM(RTRIM(@ticketDescription)), N'') IS NULL
            THROW 50001, N'وصف التذكرة مطلوب', 1;

        IF @ticketTypeID IN (1, 2)
        BEGIN
            SET @affectedPageNameClean = NULL;
            SET @affectedPageUrlClean = NULL;
            SET @affectedActionNameClean = NULL;
        END
        ELSE IF @ticketTypeID = 3
        BEGIN
            IF @affectedPageNameClean IS NULL AND @affectedPageUrlClean IS NULL
                THROW 50001, N'لنوع خطأ صفحة محددة يجب تحديد اسم الصفحة أو رابطها', 1;

            SET @affectedActionNameClean = NULL;
        END
        ELSE IF @ticketTypeID = 4
        BEGIN
            IF @affectedPageNameClean IS NULL AND @affectedPageUrlClean IS NULL
                THROW 50001, N'لنوع خطأ إجراء داخل صفحة يجب تحديد اسم الصفحة أو رابطها', 1;

            IF @affectedActionNameClean IS NULL
                THROW 50001, N'لنوع خطأ إجراء داخل صفحة يجب تحديد اسم الإجراء', 1;
        END

        SET @seq = NEXT VALUE FOR [support].[SeqTicketNo];
        SET @ticketNo = CONVERT(NVARCHAR(8), GETDATE(), 112)
                      + RIGHT(REPLICATE(N'0', 20) + CONVERT(NVARCHAR(20), @seq), 20);

        INSERT INTO [support].[Ticket]
        (
            ticketNo, ticketTypeID_FK, priorityID_FK, statusID_FK,
            ticketTitle, ticketDescription,
            affectedPageName, affectedPageUrl, affectedActionName, errorDetails,
            createdByUserID_FK, entryData, hostName
        )
        VALUES
        (
            @ticketNo, @ticketTypeID, ISNULL(@priorityID, 2), 1,
            @ticketTitle, @ticketDescription,
            @affectedPageNameClean,
            @affectedPageUrlClean,
            @affectedActionNameClean,
            NULLIF(LTRIM(RTRIM(@errorDetails)), N''),
            @entryUserID, @entryData, @hostName
        );

        IF @@ROWCOUNT = 0
            THROW 50002, N'حصل خطأ في إنشاء التذكرة', 1;

        SET @newID = SCOPE_IDENTITY();
        IF @newID IS NULL OR @newID <= 0
            THROW 50002, N'حصل خطأ في إنشاء التذكرة - Identity', 1;

        SET @note = N'{' +
              N'"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @newID), N'') + N'"'
            + N',"ticketNo":"' + ISNULL(@ticketNo, N'') + N'"'
            + N',"ticketTypeID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketTypeID), N'') + N'"'
            + N',"priorityID":"' + ISNULL(CONVERT(NVARCHAR(20), @priorityID), N'') + N'"'
            + N',"entryData":"' + ISNULL(@entryData, N'') + N'"'
            + N'}';

        INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
        VALUES (N'[support].[Ticket]', N'SMT_CREATE_TICKET', @newID, @entryData, @note);

        SELECT 1 AS IsSuccessful, N'تم إنشاء التذكرة بنجاح' AS Message_;
        RETURN;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END

GO
/****** Object:  StoredProcedure [support].[SupportPhoneTicketsDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE   PROCEDURE [support].[SupportPhoneTicketsDL]
      @pageName_         NVARCHAR(400)
    , @idaraID           INT
    , @entrydata         BIGINT
    , @hostname          NVARCHAR(400)
    , @permissionUserID  NVARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @permUser BIGINT = ISNULL(TRY_CONVERT(BIGINT, @permissionUserID), @entrydata);

    SELECT
          t.ticketID
        , t.ticketNo
        , t.ticketTitle
        , t.ticketDescription
        , tt.ticketTypeName_A
        , tp.priorityName_A
        , ts.statusName_A
        , t.affectedPageName
        , t.affectedPageUrl
        , t.affectedActionName
        , u.nationalID AS callerNationalID
        , u.FullName   AS callerFullName
        , t.entryDate
        , t.assignedDate
        , t.closedDate
    FROM [support].[Ticket] t
    INNER JOIN [support].[TicketType] tt ON tt.ticketTypeID = t.ticketTypeID_FK
    INNER JOIN [support].[TicketPriority] tp ON tp.priorityID = t.priorityID_FK
    INNER JOIN [support].[TicketStatus] ts ON ts.statusID = t.statusID_FK
    LEFT JOIN dbo.V_GetFullSystemUsersDetails u ON u.usersID = t.createdByUserID_FK
    WHERE t.ticketActive = 1
      AND TRY_CONVERT(BIGINT, t.entryData) = @entrydata
    ORDER BY t.ticketID DESC;

    SELECT ticketTypeID, ticketTypeName_A
    FROM [support].[TicketType]
    WHERE ticketTypeActive = 1
    ORDER BY ticketTypeID;

    SELECT priorityID, priorityName_A
    FROM [support].[TicketPriority]
    WHERE priorityActive = 1
    ORDER BY priorityID;

    -- الصفحات المسموح بها للمستخدم المختار
    SELECT DISTINCT
           v.menuID,
           m.menuName_A,
           m.menuName_E,
           m.menuLink
    FROM dbo.V_GetListUserPermission v
    INNER JOIN dbo.Menu m ON m.menuID = v.menuID
    WHERE v.userID = @permUser
      AND ISNULL(m.menuActive, 1) = 1
      AND NULLIF(LTRIM(RTRIM(ISNULL(m.menuName_A, N''))), N'') IS NOT NULL
      AND NULLIF(LTRIM(RTRIM(ISNULL(m.menuLink, N''))), N'') IS NOT NULL
      AND (
            v.permissionTypeName_E = N'SELECT'
         OR v.permissionTypeName_E = N'ACCESS'
         OR v.permissionTypeName_E LIKE N'%_SELECT'
         OR v.permissionTypeName_E LIKE N'%_ACCESS'
      )
    ORDER BY m.menuName_A;

    -- الإجراءات المسموح بها لكل صفحة للمستخدم المختار
    SELECT DISTINCT
           v.menuID,
           v.menuName_A,
           v.menuName_E,
           v.permissionTypeName_A,
           v.permissionTypeName_E,
           v.permissionID
    FROM dbo.V_GetListUserPermission v
    WHERE v.userID = @permUser
      AND NULLIF(LTRIM(RTRIM(ISNULL(v.menuName_A, N''))), N'') IS NOT NULL
      AND NULLIF(LTRIM(RTRIM(ISNULL(v.permissionTypeName_A, N''))), N'') IS NOT NULL
      AND NOT (
            v.permissionTypeName_E = N'ACCESS'
         OR v.permissionTypeName_E = N'SELECT'
         OR v.permissionTypeName_E LIKE N'%_ACCESS'
         OR v.permissionTypeName_E LIKE N'%_SELECT'
      )
    ORDER BY v.menuName_A, v.permissionTypeName_A;

    -- مستخدمو النظام النشطون (المتصل)
    SELECT
          CAST(u.usersID AS BIGINT) AS usersID
        , CAST(ISNULL(u.nationalID, N'') + N' - ' + ISNULL(u.FullName, N'') +
               CASE WHEN NULLIF(LTRIM(RTRIM(ISNULL(u.idaraLongName_A, N''))), N'') IS NULL
                    THEN N''
                    ELSE N' - ' + u.idaraLongName_A
               END AS NVARCHAR(500)) AS callerDisplayName
    FROM dbo.V_GetFullSystemUsersDetails u
    WHERE u.userActive = 1
      AND u.usersID IS NOT NULL
    ORDER BY u.FullName;

    SELECT statusID, statusName_A
    FROM [support].[TicketStatus]
    WHERE statusActive = 1
    ORDER BY statusID;
END

GO
/****** Object:  StoredProcedure [support].[SupportPhoneTicketsSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE   PROCEDURE [support].[SupportPhoneTicketsSP]
(
      @Action             NVARCHAR(200)
    , @ticketTypeID       TINYINT       = NULL
    , @priorityID         TINYINT       = NULL
    , @ticketTitle        NVARCHAR(300) = NULL
    , @ticketDescription  NVARCHAR(MAX) = NULL
    , @affectedPageName   NVARCHAR(200) = NULL
    , @affectedPageUrl    NVARCHAR(500) = NULL
    , @affectedActionName NVARCHAR(200) = NULL
    , @errorDetails       NVARCHAR(MAX) = NULL
    , @callerUserID       BIGINT        = NULL
    , @entryData          NVARCHAR(20)  = NULL
    , @hostName           NVARCHAR(200) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @newID BIGINT = NULL
        , @seq BIGINT = NULL
        , @ticketNo NVARCHAR(30) = NULL
        , @entryUserID BIGINT = TRY_CONVERT(BIGINT, @entryData)
        , @note NVARCHAR(MAX) = NULL
        , @affectedPageNameClean NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@affectedPageName)), N'')
        , @affectedPageUrlClean NVARCHAR(500) = NULLIF(LTRIM(RTRIM(@affectedPageUrl)), N'')
        , @affectedActionNameClean NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@affectedActionName)), N'');

    BEGIN TRY
        IF @tc = 0
            BEGIN TRAN;

        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
            THROW 50001, N'العملية مطلوبة', 1;

        IF @Action <> N'SPT_CREATE_TICKET'
            THROW 50001, N'العملية غير مسجلة', 1;

        IF @entryUserID IS NULL
            THROW 50001, N'الموظف الحالي غير صالح', 1;

        IF @callerUserID IS NULL
            THROW 50001, N'المتصل مطلوب', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.V_GetFullSystemUsersDetails u
            WHERE u.usersID = @callerUserID
              AND u.userActive = 1
        )
            THROW 50001, N'المتصل غير صالح أو غير نشط', 1;

        IF @ticketTypeID IS NULL
            THROW 50001, N'نوع التذكرة مطلوب', 1;

        IF NOT EXISTS (SELECT 1 FROM [support].[TicketType] WHERE ticketTypeID = @ticketTypeID AND ticketTypeActive = 1)
            THROW 50001, N'نوع التذكرة غير صالح', 1;

        IF @priorityID IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM [support].[TicketPriority] WHERE priorityID = @priorityID AND priorityActive = 1)
            THROW 50001, N'أولوية التذكرة غير صالحة', 1;

        IF NULLIF(LTRIM(RTRIM(@ticketTitle)), N'') IS NULL
            THROW 50001, N'عنوان التذكرة مطلوب', 1;

        IF NULLIF(LTRIM(RTRIM(@ticketDescription)), N'') IS NULL
            THROW 50001, N'وصف التذكرة مطلوب', 1;

        IF @ticketTypeID IN (1, 2)
        BEGIN
            SET @affectedPageNameClean = NULL;
            SET @affectedPageUrlClean = NULL;
            SET @affectedActionNameClean = NULL;
        END
        ELSE IF @ticketTypeID = 3
        BEGIN
            IF @affectedPageNameClean IS NULL AND @affectedPageUrlClean IS NULL
                THROW 50001, N'لنوع خطأ صفحة محددة يجب تحديد اسم الصفحة أو رابطها', 1;

            SET @affectedActionNameClean = NULL;
        END
        ELSE IF @ticketTypeID = 4
        BEGIN
            IF @affectedPageNameClean IS NULL AND @affectedPageUrlClean IS NULL
                THROW 50001, N'لنوع خطأ إجراء داخل صفحة يجب تحديد اسم الصفحة أو رابطها', 1;

            IF @affectedActionNameClean IS NULL
                THROW 50001, N'لنوع خطأ إجراء داخل صفحة يجب تحديد اسم الإجراء', 1;
        END

        SET @seq = NEXT VALUE FOR [support].[SeqTicketNo];
        SET @ticketNo = CONVERT(NVARCHAR(8), GETDATE(), 112)
                      + RIGHT(REPLICATE(N'0', 20) + CONVERT(NVARCHAR(20), @seq), 20);

        INSERT INTO [support].[Ticket]
        (
            ticketNo, ticketTypeID_FK, priorityID_FK, statusID_FK,
            ticketTitle, ticketDescription,
            affectedPageName, affectedPageUrl, affectedActionName, errorDetails,
            createdByUserID_FK, entryData, hostName
        )
        VALUES
        (
            @ticketNo, @ticketTypeID, ISNULL(@priorityID, 2), 1,
            @ticketTitle, @ticketDescription,
            @affectedPageNameClean,
            @affectedPageUrlClean,
            @affectedActionNameClean,
            NULLIF(LTRIM(RTRIM(@errorDetails)), N''),
            @callerUserID, @entryData, @hostName
        );

        IF @@ROWCOUNT = 0
            THROW 50002, N'حصل خطأ في إنشاء التذكرة', 1;

        SET @newID = SCOPE_IDENTITY();
        IF @newID IS NULL OR @newID <= 0
            THROW 50002, N'حصل خطأ في إنشاء التذكرة - Identity', 1;

        SET @note = N'{' +
              N'"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @newID), N'') + N'"'
            + N',"ticketNo":"' + ISNULL(@ticketNo, N'') + N'"'
            + N',"ticketTypeID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketTypeID), N'') + N'"'
            + N',"priorityID":"' + ISNULL(CONVERT(NVARCHAR(20), @priorityID), N'') + N'"'
            + N',"callerUserID":"' + ISNULL(CONVERT(NVARCHAR(20), @callerUserID), N'') + N'"'
            + N',"entryData":"' + ISNULL(@entryData, N'') + N'"'
            + N'}';

        INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
        VALUES (N'[support].[Ticket]', N'SPT_CREATE_TICKET', @newID, @entryData, @note);

        SELECT 1 AS IsSuccessful, N'تم إنشاء التذكرة الهاتفية بنجاح' AS Message_;
        RETURN;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END

GO
/****** Object:  StoredProcedure [support].[SupportTeamManagementDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE   PROCEDURE [support].[SupportTeamManagementDL]
      @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      BIGINT
    , @hostname       NVARCHAR(400)
    , @onlyActive     BIT = 1
AS
BEGIN
    SET NOCOUNT ON;

    SELECT tm.teamMemberID, tm.userID_FK, u.nationalID, u.usersActive,
           tm.canReceiveTickets, tm.canAssignTickets, tm.teamMemberActive, tm.entryDate
    FROM [support].[TeamMember] tm
    INNER JOIN [dbo].[Users] u ON u.usersID = tm.userID_FK
   -- WHERE (@onlyActive = 0 OR tm.teamMemberActive = 1)
    ORDER BY tm.teamMemberID DESC;

    SELECT tmr.teamMemberRoleID, tmr.teamMemberID_FK, tmr.roleID_FK,
           r.roleName_A, r.roleName_E, tmr.teamMemberRoleActive, tmr.entryDate
    FROM [support].[TeamMemberRole] tmr
    INNER JOIN [dbo].[Role] r ON r.roleID = tmr.roleID_FK
    ORDER BY tmr.teamMemberRoleID DESC;

    SELECT u.usersID, u.nationalID
    FROM [dbo].[Users] u
    WHERE ISNULL(u.usersActive, 0) = 1
    ORDER BY u.nationalID;

    SELECT r.roleID, r.roleName_A, r.roleName_E
    FROM [dbo].[Role] r
    WHERE ISNULL(r.PublicView, 1) = 1
    ORDER BY r.roleID;
END

GO
/****** Object:  StoredProcedure [support].[SupportTeamManagementSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [support].[SupportTeamManagementSP]
(
      @Action             NVARCHAR(200)
    , @teamMemberID       BIGINT        = NULL
    , @userID             BIGINT        = NULL
    , @canReceiveTickets  BIT           = NULL
    , @canAssignTickets   BIT           = NULL
    , @memberActive       BIT           = NULL
    , @teamMemberRoleID   BIGINT        = NULL
    , @roleID             BIGINT        = NULL
    , @entryData          NVARCHAR(20)  = NULL
    , @hostName           NVARCHAR(200) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @entryUserID BIGINT = TRY_CONVERT(BIGINT, @entryData)
        , @newMemberID BIGINT = NULL
        , @newMemberRoleID BIGINT = NULL
        , @note NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @tc = 0
            BEGIN TRAN;

        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

        IF @entryUserID IS NULL
        BEGIN
            ;THROW 50001, N'المستخدم غير صالح', 1;
        END

        IF @Action = N'STM_ADD_MEMBER'
        BEGIN
            IF @userID IS NULL
            BEGIN
                ;THROW 50001, N'المستخدم مطلوب', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM dbo.[Users] WHERE usersID = @userID)
            BEGIN
                ;THROW 50001, N'المستخدم غير موجود', 1;
            END

            IF EXISTS (SELECT 1 FROM [support].[TeamMember] WHERE userID_FK = @userID)
            BEGIN
                ;THROW 50001, N'المستخدم مضاف مسبقاً في فريق الدعم', 1;
            END

            INSERT INTO [support].[TeamMember]
            (
                userID_FK, canReceiveTickets, canAssignTickets,
                teamMemberActive, entryData, hostName
            )
            VALUES
            (
                @userID, ISNULL(@canReceiveTickets, 1), ISNULL(@canAssignTickets, 0),
                1, @entryData, @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في إضافة عضو الدعم', 1;
            END

            SET @newMemberID = SCOPE_IDENTITY();
            IF @newMemberID IS NULL OR @newMemberID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في إضافة عضو الدعم - Identity', 1;
            END

            SET @note = N'{"teamMemberID":"' + ISNULL(CONVERT(NVARCHAR(20), @newMemberID), N'')
                      + N'","userID":"' + ISNULL(CONVERT(NVARCHAR(20), @userID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TeamMember]', N'STM_INSERT', @newMemberID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تمت إضافة عضو الدعم بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'STM_UPDATE_MEMBER'
        BEGIN
            IF @teamMemberID IS NULL
            BEGIN
                ;THROW 50001, N'عضو الدعم مطلوب', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TeamMember] WHERE teamMemberID = @teamMemberID)
            BEGIN
                ;THROW 50001, N'عضو الدعم غير موجود', 1;
            END

            UPDATE [support].[TeamMember]
            SET canReceiveTickets = ISNULL(@canReceiveTickets, canReceiveTickets),
                canAssignTickets = ISNULL(@canAssignTickets, canAssignTickets),
                teamMemberActive = ISNULL(@memberActive, teamMemberActive),
                entryData = ISNULL(ISNULL(entryData, N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName, N'') + N',' + @hostName, hostName)
            WHERE teamMemberID = @teamMemberID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1;
            END

            SET @note = N'{"teamMemberID":"' + ISNULL(CONVERT(NVARCHAR(20), @teamMemberID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TeamMember]', N'STM_UPDATE', @teamMemberID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم تحديث عضو الدعم بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'STM_DEACTIVATE_MEMBER'
        BEGIN
            IF @teamMemberID IS NULL
            BEGIN
                ;THROW 50001, N'عضو الدعم مطلوب', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TeamMember] WHERE teamMemberID = @teamMemberID)
            BEGIN
                ;THROW 50001, N'عضو الدعم غير موجود', 1;
            END

            UPDATE [support].[TeamMember]
            SET teamMemberActive = 0,
                entryData = ISNULL(ISNULL(entryData, N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName, N'') + N',' + @hostName, hostName)
            WHERE teamMemberID = @teamMemberID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1;
            END

            UPDATE [support].[TeamMemberRole]
            SET teamMemberRoleActive = 0,
                entryData = ISNULL(ISNULL(entryData, N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName, N'') + N',' + @hostName, hostName)
            WHERE teamMemberID_FK = @teamMemberID
              AND teamMemberRoleActive = 1;

            SET @note = N'{"teamMemberID":"' + ISNULL(CONVERT(NVARCHAR(20), @teamMemberID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TeamMember]', N'STM_DELETE', @teamMemberID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم تعطيل عضو الدعم بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'STM_ADD_MEMBER_ROLE'
        BEGIN
            IF @teamMemberID IS NULL OR @roleID IS NULL
            BEGIN
                ;THROW 50001, N'بيانات الدور غير مكتملة', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TeamMember] WHERE teamMemberID = @teamMemberID AND teamMemberActive = 1)
            BEGIN
                ;THROW 50001, N'عضو الدعم غير موجود أو غير نشط', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM dbo.[Role] WHERE roleID = @roleID)
            BEGIN
                ;THROW 50001, N'الدور غير موجود', 1;
            END

            IF EXISTS
            (
                SELECT 1
                FROM [support].[TeamMemberRole]
                WHERE teamMemberID_FK = @teamMemberID
                  AND roleID_FK = @roleID
                  AND teamMemberRoleActive = 1
            )
            BEGIN
                ;THROW 50001, N'الدور مضاف مسبقاً لهذا العضو', 1;
            END

            INSERT INTO [support].[TeamMemberRole]
            (
                teamMemberID_FK, roleID_FK, teamMemberRoleActive, entryData, hostName
            )
            VALUES
            (
                @teamMemberID, @roleID, 1, @entryData, @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في إضافة الدور', 1;
            END

            SET @newMemberRoleID = SCOPE_IDENTITY();
            IF @newMemberRoleID IS NULL OR @newMemberRoleID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في إضافة الدور - Identity', 1;
            END

            SET @note = N'{"teamMemberRoleID":"' + ISNULL(CONVERT(NVARCHAR(20), @newMemberRoleID), N'')
                      + N'","teamMemberID":"' + ISNULL(CONVERT(NVARCHAR(20), @teamMemberID), N'')
                      + N'","roleID":"' + ISNULL(CONVERT(NVARCHAR(20), @roleID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TeamMemberRole]', N'STM_INSERT', @newMemberRoleID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تمت إضافة الدور بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'STM_REMOVE_MEMBER_ROLE'
        BEGIN
            IF @teamMemberRoleID IS NULL
            BEGIN
                ;THROW 50001, N'ربط الدور مطلوب', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TeamMemberRole] WHERE teamMemberRoleID = @teamMemberRoleID)
            BEGIN
                ;THROW 50001, N'ربط الدور غير موجود', 1;
            END

            UPDATE [support].[TeamMemberRole]
            SET teamMemberRoleActive = 0,
                entryData = ISNULL(ISNULL(entryData, N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName, N'') + N',' + @hostName, hostName)
            WHERE teamMemberRoleID = @teamMemberRoleID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1;
            END

            SET @note = N'{"teamMemberRoleID":"' + ISNULL(CONVERT(NVARCHAR(20), @teamMemberRoleID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TeamMemberRole]', N'STM_DELETE', @teamMemberRoleID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم إزالة الدور بنجاح' AS Message_;
            RETURN;
        END
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END

GO
/****** Object:  StoredProcedure [support].[SupportTicketDetailsDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE   PROCEDURE [support].[SupportTicketDetailsDL]
      @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      BIGINT
    , @hostname       NVARCHAR(400)
    , @ticketID       BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;


    SELECT t.ticketID, t.ticketNo, t.ticketTitle, t.ticketDescription, t.errorDetails,
           t.ticketTypeID_FK, tt.ticketTypeName_A, t.priorityID_FK, tp.priorityName_A,
           t.statusID_FK, ts.statusName_A, t.affectedPageName, t.affectedPageUrl, t.affectedActionName,
           t.createdByUserID_FK, uc.nationalID AS createdByNationalID,
           t.assignedToTeamMemberID_FK, tm.userID_FK AS assignedToUserID, ua.nationalID AS assignedToNationalID,
           t.entryDate, t.assignedDate, t.closedDate
    FROM [support].[Ticket] t
    INNER JOIN [support].[TicketType] tt ON tt.ticketTypeID = t.ticketTypeID_FK
    INNER JOIN [support].[TicketPriority] tp ON tp.priorityID = t.priorityID_FK
    INNER JOIN [support].[TicketStatus] ts ON ts.statusID = t.statusID_FK
    LEFT JOIN [support].[TeamMember] tm ON tm.teamMemberID = t.assignedToTeamMemberID_FK
    LEFT JOIN [dbo].[Users] uc ON uc.usersID = t.createdByUserID_FK
    LEFT JOIN [dbo].[Users] ua ON ua.usersID = tm.userID_FK
    WHERE t.ticketID = @ticketID;

    SELECT r.ticketReplyID, r.ticketID_FK, r.replyText, r.replyByUserID_FK,
           u.nationalID AS replyByNationalID, r.isInternal, r.entryDate
    FROM [support].[TicketReply] r
    LEFT JOIN [dbo].[Users] u ON u.usersID = r.replyByUserID_FK
    WHERE r.ticketID_FK = @ticketID
      AND r.ticketReplyActive = 1
      AND (r.isInternal = 0 OR EXISTS
            (SELECT 1 FROM [support].[TeamMember] tm WHERE tm.userID_FK = @entrydata AND tm.teamMemberActive = 1))
    ORDER BY r.ticketReplyID ASC;

    SELECT a.ticketAttachmentID, a.ticketID_FK, a.fileName, a.contentType,
           a.fileSizeBytes, a.storagePath, a.uploadedByUserID_FK,
           u.nationalID AS uploadedByNationalID, a.entryDate
    FROM [support].[TicketAttachment] a
    LEFT JOIN [dbo].[Users] u ON u.usersID = a.uploadedByUserID_FK
    WHERE a.ticketID_FK = @ticketID AND a.ticketAttachmentActive = 1
    ORDER BY a.ticketAttachmentID DESC;

    SELECT h.ticketAssignmentHistoryID, h.ticketID_FK, h.fromTeamMemberID_FK,
           f.userID_FK AS fromUserID, uf.nationalID AS fromNationalID,
           h.toTeamMemberID_FK, tmm.userID_FK AS toUserID, ut.nationalID AS toNationalID,
           h.actionByUserID_FK, ua.nationalID AS actionByNationalID,
           h.assignmentNote, h.entryDate
    FROM [support].[TicketAssignmentHistory] h
    LEFT JOIN [support].[TeamMember] f ON f.teamMemberID = h.fromTeamMemberID_FK
    LEFT JOIN [support].[TeamMember] tmm ON tmm.teamMemberID = h.toTeamMemberID_FK
    LEFT JOIN [dbo].[Users] uf ON uf.usersID = f.userID_FK
    LEFT JOIN [dbo].[Users] ut ON ut.usersID = tmm.userID_FK
    LEFT JOIN [dbo].[Users] ua ON ua.usersID = h.actionByUserID_FK
    WHERE h.ticketID_FK = @ticketID
    ORDER BY h.ticketAssignmentHistoryID DESC;

    SELECT tk.ticketTaskID, tk.ticketID_FK, tk.taskNo, tk.taskTitle, tk.taskDescription,
           tk.statusID_FK, s.statusName_A, tk.priorityID_FK, p.priorityName_A,
           tk.assignedToTeamMemberID_FK, tm.userID_FK AS assignedToUserID, u.nationalID AS assignedToNationalID,
           tk.assignedDate, tk.dueDate, tk.completedDate, tk.taskOrder, tk.isRequired
    FROM [support].[TicketTask] tk
    INNER JOIN [support].[TicketStatus] s ON s.statusID = tk.statusID_FK
    INNER JOIN [support].[TicketPriority] p ON p.priorityID = tk.priorityID_FK
    LEFT JOIN [support].[TeamMember] tm ON tm.teamMemberID = tk.assignedToTeamMemberID_FK
    LEFT JOIN [dbo].[Users] u ON u.usersID = tm.userID_FK
    WHERE tk.ticketID_FK = @ticketID AND tk.taskActive = 1
    ORDER BY ISNULL(tk.taskOrder, 999999), tk.ticketTaskID;

    SELECT statusID, statusName_A FROM [support].[TicketStatus] WHERE statusActive = 1 ORDER BY statusID;
    SELECT priorityID, priorityName_A FROM [support].[TicketPriority] WHERE priorityActive = 1 ORDER BY priorityID;

        select t.teamMemberID,u.FullName 
    from support.TeamMember  t
    inner join dbo.V_GetFullSystemUsersDetails u on u.usersID = t.userID_FK
    where teamMemberActive = 1 
    and canReceiveTickets = 1
END

GO
/****** Object:  StoredProcedure [support].[SupportTicketDetailsSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [support].[SupportTicketDetailsSP]
(
      @Action                NVARCHAR(200)
    , @ticketID              BIGINT         = NULL
    , @replyText             NVARCHAR(MAX)  = NULL
    , @isInternal            BIT            = 0
    , @statusID              TINYINT        = NULL
    , @assignToTeamMemberID  BIGINT         = NULL
    , @assignmentNote        NVARCHAR(1000) = NULL
    , @taskTitle             NVARCHAR(300)  = NULL
    , @taskDescription       NVARCHAR(MAX)  = NULL
    , @taskPriorityID        TINYINT        = NULL
    , @taskAssignToMemberID  BIGINT         = NULL
    , @taskDueDate           DATETIME       = NULL
    , @taskID                BIGINT         = NULL
    , @taskStatusID          TINYINT        = NULL
    , @entryData             NVARCHAR(20)   = NULL
    , @hostName              NVARCHAR(200)  = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @entryUserID BIGINT = TRY_CONVERT(BIGINT, @entryData)
        , @isSupportUser BIT = 0
        , @currentAssigned BIGINT = NULL
        , @seq BIGINT = NULL
        , @newTaskNo NVARCHAR(40) = NULL
        , @newReplyID BIGINT = NULL
        , @newAssignmentID BIGINT = NULL
        , @newTaskID BIGINT = NULL
        , @note NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @tc = 0
            BEGIN TRAN;

        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN
            ;THROW 50001, N'العملية مطلوبة', 1;
        END

        IF @ticketID IS NULL
        BEGIN
            ;THROW 50001, N'رقم التذكرة مطلوب', 1;
        END

        IF @entryUserID IS NULL
        BEGIN
            ;THROW 50001, N'المستخدم غير صالح', 1;
        END

        IF NOT EXISTS (SELECT 1 FROM [support].[Ticket] WHERE ticketID = @ticketID AND ticketActive = 1)
        BEGIN
            ;THROW 50001, N'التذكرة غير موجودة', 1;
        END

        SELECT @isSupportUser = CASE WHEN EXISTS
        (
            SELECT 1 FROM [support].[TeamMember] WHERE userID_FK = @entryUserID AND teamMemberActive = 1
        ) THEN 1 ELSE 0 END;

        IF @Action = N'STD_ADD_REPLY'
        BEGIN
            IF NULLIF(LTRIM(RTRIM(@replyText)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'نص الرد مطلوب', 1;
            END

            INSERT INTO [support].[TicketReply]
            (
                ticketID_FK, replyText, replyByUserID_FK, isInternal, entryData, hostName
            )
            VALUES
            (
                @ticketID, @replyText, @entryUserID,
                CASE WHEN @isSupportUser = 1 THEN ISNULL(@isInternal, 0) ELSE 0 END,
                @entryData, @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في إضافة الرد', 1;
            END

            SET @newReplyID = SCOPE_IDENTITY();
            SET @note = N'{"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketID), N'')
                      + N'","replyID":"' + ISNULL(CONVERT(NVARCHAR(20), @newReplyID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TicketReply]', N'STD_INSERT', ISNULL(@newReplyID, 0), @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم إضافة الرد بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'STD_CHANGE_STATUS'
        BEGIN
            IF @statusID IS NULL
            BEGIN
                ;THROW 50001, N'الحالة مطلوبة', 1;
            END

            IF @isSupportUser = 0
            BEGIN
                ;THROW 50001, N'عفوا لاتملك صلاحية تغيير الحالة', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TicketStatus] WHERE statusID = @statusID AND statusActive = 1)
            BEGIN
                ;THROW 50001, N'الحالة غير صالحة', 1;
            END

            UPDATE [support].[Ticket]
            SET statusID_FK = @statusID,
                closedDate = CASE WHEN @statusID = 4 THEN GETDATE() ELSE closedDate END,
                entryData = ISNULL(ISNULL(entryData, N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName, N'') + N',' + @hostName, hostName)
            WHERE ticketID = @ticketID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1;
            END

            SET @note = N'{"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketID), N'')
                      + N'","statusID":"' + ISNULL(CONVERT(NVARCHAR(20), @statusID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[Ticket]', N'STD_UPDATE_STATUS', @ticketID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم تحديث حالة التذكرة بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'STD_ASSIGN'
        BEGIN
            IF @assignToTeamMemberID IS NULL
            BEGIN
                ;THROW 50001, N'الموظف المراد الإسناد له مطلوب', 1;
            END

            IF @isSupportUser = 0
            BEGIN
                ;THROW 50001, N'عفوا لاتملك صلاحية الإسناد', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TeamMember] WHERE teamMemberID = @assignToTeamMemberID AND teamMemberActive = 1)
            BEGIN
                ;THROW 50001, N'الموظف غير موجود أو غير نشط', 1;
            END

            SELECT @currentAssigned = assignedToTeamMemberID_FK
            FROM [support].[Ticket]
            WHERE ticketID = @ticketID;

            UPDATE [support].[Ticket]
            SET assignedToTeamMemberID_FK = @assignToTeamMemberID,
                assignedByUserID_FK = @entryUserID,
                assignedDate = GETDATE(),
                statusID_FK = CASE WHEN statusID_FK = 1 THEN 2 ELSE statusID_FK END,
                entryData = ISNULL(ISNULL(entryData, N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName, N'') + N',' + @hostName, hostName)
            WHERE ticketID = @ticketID;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1;
            END

            INSERT INTO [support].[TicketAssignmentHistory]
            (
                ticketID_FK, fromTeamMemberID_FK, toTeamMemberID_FK,
                actionByUserID_FK, assignmentNote, entryData, hostName
            )
            VALUES
            (
                @ticketID, @currentAssigned, @assignToTeamMemberID,
                @entryUserID, @assignmentNote, @entryData, @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في تسجيل التحويل', 1;
            END

            SET @newAssignmentID = SCOPE_IDENTITY();
            SET @note = N'{"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketID), N'')
                      + N'","from":"' + ISNULL(CONVERT(NVARCHAR(20), @currentAssigned), N'')
                      + N'","to":"' + ISNULL(CONVERT(NVARCHAR(20), @assignToTeamMemberID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TicketAssignmentHistory]', N'STD_INSERT', ISNULL(@newAssignmentID, 0), @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم تحويل التذكرة بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'STD_ADD_TASK'
        BEGIN
            IF @taskAssignToMemberID IS NULL
            BEGIN
                ;THROW 50001, N'الموظف للمهمة مطلوب', 1;
            END

            IF NULLIF(LTRIM(RTRIM(@taskTitle)), N'') IS NULL
            BEGIN
                ;THROW 50001, N'عنوان المهمة مطلوب', 1;
            END

            IF @isSupportUser = 0
            BEGIN
                ;THROW 50001, N'عفوا لاتملك صلاحية إضافة مهام', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TeamMember] WHERE teamMemberID = @taskAssignToMemberID AND teamMemberActive = 1)
            BEGIN
                ;THROW 50001, N'الموظف غير موجود أو غير نشط', 1;
            END

            IF @taskPriorityID IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM [support].[TicketPriority] WHERE priorityID = @taskPriorityID AND priorityActive = 1)
            BEGIN
                ;THROW 50001, N'أولوية المهمة غير صالحة', 1;
            END

            SET @seq = NEXT VALUE FOR [support].[SeqTicketNo];
            SET @newTaskNo = CONVERT(NVARCHAR(8), GETDATE(), 112)
                           + RIGHT(REPLICATE(N'0', 20) + CONVERT(NVARCHAR(20), @seq), 20);

            INSERT INTO [support].[TicketTask]
            (
                ticketID_FK, taskNo, taskTitle, taskDescription, statusID_FK, priorityID_FK,
                assignedToTeamMemberID_FK, assignedByUserID_FK, dueDate, entryData, hostName
            )
            VALUES
            (
                @ticketID, @newTaskNo, @taskTitle, @taskDescription, 1, ISNULL(@taskPriorityID, 2),
                @taskAssignToMemberID, @entryUserID, @taskDueDate, @entryData, @hostName
            );

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في إنشاء المهمة', 1;
            END

            SET @newTaskID = SCOPE_IDENTITY();
            IF @newTaskID IS NULL OR @newTaskID <= 0
            BEGIN
                ;THROW 50002, N'حصل خطأ في إنشاء المهمة - Identity', 1;
            END

            UPDATE [support].[Ticket]
            SET statusID_FK = CASE WHEN statusID_FK IN (1, 5) THEN 2 ELSE statusID_FK END,
                entryData = ISNULL(ISNULL(entryData, N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName, N'') + N',' + @hostName, hostName)
            WHERE ticketID = @ticketID;

            SET @note = N'{"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketID), N'')
                      + N'","taskID":"' + ISNULL(CONVERT(NVARCHAR(20), @newTaskID), N'')
                      + N'","taskNo":"' + ISNULL(@newTaskNo, N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TicketTask]', N'STD_INSERT', @newTaskID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم إنشاء المهمة بنجاح' AS Message_;
            RETURN;
        END
        ELSE IF @Action = N'STD_UPDATE_TASK_STATUS'
        BEGIN
            IF @taskID IS NULL OR @taskStatusID IS NULL
            BEGIN
                ;THROW 50001, N'بيانات المهمة غير مكتملة', 1;
            END

            IF NOT EXISTS (SELECT 1 FROM [support].[TicketStatus] WHERE statusID = @taskStatusID AND statusActive = 1)
            BEGIN
                ;THROW 50001, N'حالة المهمة غير صالحة', 1;
            END

            UPDATE [support].[TicketTask]
            SET statusID_FK = @taskStatusID,
                completedDate = CASE WHEN @taskStatusID IN (3, 4) THEN GETDATE() ELSE completedDate END,
                entryData = ISNULL(ISNULL(entryData, N'') + N',' + @entryData, entryData),
                hostName = ISNULL(ISNULL(hostName, N'') + N',' + @hostName, hostName)
            WHERE ticketTaskID = @taskID
              AND ticketID_FK = @ticketID
              AND taskActive = 1;

            IF @@ROWCOUNT = 0
            BEGIN
                ;THROW 50002, N'لم يتم تحديث أي سجل', 1;
            END

            SET @note = N'{"ticketID":"' + ISNULL(CONVERT(NVARCHAR(20), @ticketID), N'')
                      + N'","taskID":"' + ISNULL(CONVERT(NVARCHAR(20), @taskID), N'')
                      + N'","statusID":"' + ISNULL(CONVERT(NVARCHAR(20), @taskStatusID), N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[support].[TicketTask]', N'STD_UPDATE_STATUS', @taskID, @entryData, @note);

            SELECT 1 AS IsSuccessful, N'تم تحديث حالة المهمة' AS Message_;
            RETURN;
        END
        ELSE
        BEGIN
            ;THROW 50001, N'العملية غير مسجلة', 1;
        END
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END

GO
/****** Object:  StoredProcedure [Tickets].[ResidentDDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [Tickets].[ResidentDDL]
(
      @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @pageName_ = N'ResidentDDL'
    BEGIN
        ;WITH ResidentHousing AS
        (
            SELECT
                r.[residentInfoID] AS [residentInfoID],
                r.[NationalID] AS [NationalID],
                r.[generalNo_FK] AS [generalNo_FK],
                r.[FullName_A] AS [ResidentName_A],
                r.[FullName_E] AS [FullName_E],
                r.[rankNameA] AS [rankNameA],
                r.[militaryUnitName_A] AS [militaryUnitName_A],
                                CASE
                                        WHEN ba.[BuildingNo] IS NULL
                                            OR LTRIM(RTRIM(CONVERT(NVARCHAR(100), ba.[BuildingNo]))) = N''
                                            OR CONVERT(NVARCHAR(100), ba.[BuildingNo]) = N'No_house'
                                        THEN N'Ø¨Ø¯ÙˆÙ† Ø³ÙƒÙ†'
                                        ELSE CONVERT(NVARCHAR(100), ba.[BuildingNo])
                                END AS [BuildingNo],
                ROW_NUMBER() OVER
                (
                    PARTITION BY r.[residentInfoID]
                    ORDER BY
                        CASE
                            WHEN ba.[BuildingNo] IS NULL
                              OR LTRIM(RTRIM(CONVERT(NVARCHAR(100), ba.[BuildingNo]))) = N''
                              OR CONVERT(NVARCHAR(100), ba.[BuildingNo]) = N'No_house'
                            THEN 1 ELSE 0
                        END,
                        ba.[BuildingAssignDate] DESC,
                        ba.[BuildingAssignID] DESC
                ) AS [rn]
            FROM [Housing].[V_GetFullResidentDetails] r
            INNER JOIN [DATACORE].[Housing].[BuildingAssign] ba
                ON r.[generalNo_FK] = ba.[GeneralNo]
            INNER JOIN [DATACORE].[Housing].[BuildingAssignStatus] bas
                ON ba.[BuildingAssignStatusID_FK] = bas.[BuildingAssignStatusID]
            WHERE r.[IdaraID] = @idaraID
              AND bas.[Active] = 1
        )
        SELECT
            rh.[residentInfoID] AS [residentInfoID],
            rh.[NationalID] AS [NationalID],
            rh.[generalNo_FK] AS [generalNo_FK],
            rh.[ResidentName_A] AS [ResidentName_A],
            rh.[ResidentName_A]
                + N' | Ù‡ÙˆÙŠØ©: '
                + COALESCE(NULLIF(rh.[NationalID], N''), CONVERT(NVARCHAR(50), rh.[generalNo_FK]), N'-')
                + N' | Ø§Ù„Ø³ÙƒÙ†: '
                + COALESCE(NULLIF(rh.[BuildingNo], N''), N'Ø¨Ø¯ÙˆÙ† Ø³ÙƒÙ†') AS [FullName_A],
            rh.[ResidentName_A]
                + N' | Ù‡ÙˆÙŠØ©: '
                + COALESCE(NULLIF(rh.[NationalID], N''), CONVERT(NVARCHAR(50), rh.[generalNo_FK]), N'-')
                + N' | Ø§Ù„Ø³ÙƒÙ†: '
                + COALESCE(NULLIF(rh.[BuildingNo], N''), N'Ø¨Ø¯ÙˆÙ† Ø³ÙƒÙ†') AS [ResidentDisplay],
            rh.[FullName_E] AS [FullName_E],
            rh.[rankNameA] AS [rankNameA],
            rh.[militaryUnitName_A] AS [militaryUnitName_A],
            rh.[BuildingNo] AS [BuildingNo]
        FROM ResidentHousing rh
        WHERE rh.[rn] = 1
        ORDER BY rh.[ResidentName_A] ASC;

        RETURN;
    END
END

GO
/****** Object:  StoredProcedure [Tickets].[ServiceDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Tickets].[ServiceDL]
(
      @pageName_  NVARCHAR(400)
    , @idaraID    INT
    , @entryData  INT
    , @hostName   NVARCHAR(400)
    , @filterServiceID  BIGINT = NULL
    , @filterTicketClassID INT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @pageName_ = N'ServiceCatalogueList' OR @pageName_ IS NULL
    BEGIN
        SELECT
              s.[serviceID]
            , s.[serviceCode]
            , s.[serviceName_A]
            , s.[serviceName_E]
            , s.[serviceDesc]
            , s.[idaraID_FK]
            , s.[ticketClassID_FK]
            , tc.[ticketClassName_A]
            , tc.[ticketClassName_E]
            , s.[defaultPriorityID_FK]
            , p.[priorityName_A]
            , p.[priorityName_E]
            , s.[requiresLocation]
            , s.[allowsChildTickets]
            , s.[requiresQualityReview]
            , s.[serviceActive]
        FROM [Tickets].[Service] s
        LEFT JOIN [Tickets].[TicketClass] tc ON s.[ticketClassID_FK] = tc.[ticketClassID]
        LEFT JOIN [Tickets].[Priority] p ON s.[defaultPriorityID_FK] = p.[priorityID]
        WHERE s.[serviceActive] = 1
          AND (s.[idaraID_FK] = @idaraID OR s.[idaraID_FK] IS NULL)
          AND (s.[serviceID] = @filterServiceID OR @filterServiceID IS NULL)
          AND (s.[ticketClassID_FK] = @filterTicketClassID OR @filterTicketClassID IS NULL)
        ORDER BY s.[serviceID] DESC;

        SELECT [ticketClassID], [ticketClassName_A], [ticketClassName_E]
        FROM [Tickets].[TicketClass]
        WHERE [ticketClassActive] = 1
        ORDER BY [ticketClassID];

        SELECT [priorityID], [priorityName_A], [priorityName_E]
        FROM [Tickets].[Priority]
        WHERE [priorityActive] = 1
        ORDER BY [priorityID];

        RETURN;
    END

    IF @pageName_ = N'RoutingRuleLookup'
    BEGIN
        SELECT
              rr.[serviceRoutingRuleID]
            , rr.[serviceID_FK]
            , s.[serviceName_A]
            , s.[serviceName_E]
            , rr.[idaraID_FK]
            , rr.[targetDSDID_FK]
            , rr.[queueDistributorID_FK]
            , rr.[effectiveFrom]
            , rr.[effectiveTo]
            , rr.[changeReason]
            , rr.[serviceRoutingRuleActive]
        FROM [Tickets].[ServiceRoutingRule] rr
        INNER JOIN [Tickets].[Service] s ON rr.[serviceID_FK] = s.[serviceID]
        WHERE rr.[serviceRoutingRuleActive] = 1
          AND (rr.[idaraID_FK] = @idaraID OR rr.[idaraID_FK] IS NULL)
          AND rr.[effectiveFrom] <= GETDATE()
          AND (rr.[effectiveTo] IS NULL OR rr.[effectiveTo] > GETDATE())
        ORDER BY rr.[serviceRoutingRuleID] DESC;

        RETURN;
    END

    IF @pageName_ = N'SLAPolicyLookup'
    BEGIN
        SELECT
              sp.[serviceSLAPolicyID]
            , sp.[serviceID_FK]
            , s.[serviceName_A]
            , s.[serviceName_E]
            , sp.[priorityID_FK]
            , p.[priorityName_A]
            , sp.[firstResponseTargetMinutes]
            , sp.[assignmentTargetMinutes]
            , sp.[operationalCompletionTargetMinutes]
            , sp.[finalClosureTargetMinutes]
            , sp.[slaPolicyActive]
        FROM [Tickets].[ServiceSLAPolicy] sp
        INNER JOIN [Tickets].[Service] s ON sp.[serviceID_FK] = s.[serviceID]
        INNER JOIN [Tickets].[Priority] p ON sp.[priorityID_FK] = p.[priorityID]
        WHERE sp.[slaPolicyActive] = 1
          AND (sp.[idaraID_FK] = @idaraID OR sp.[idaraID_FK] IS NULL)
        ORDER BY sp.[serviceSLAPolicyID] DESC;

        RETURN;
    END

    IF @pageName_ = N'SuggestionReview'
    BEGIN
        SELECT
              scs.[serviceCatalogSuggestionID]
            , scs.[sourceTicketID_FK]
            , scs.[idaraID_FK]
            , scs.[proposedServiceName_A]
            , scs.[proposedServiceName_E]
            , scs.[proposedServiceDesc]
            , scs.[proposedTargetDSDID_FK]
            , scs.[proposedPriorityID_FK]
            , scs.[approvalStatus]
            , scs.[approvedByUserID]
            , scs.[approvalDate]
            , scs.[createdServiceID_FK]
            , scs.[suggestionActive]
        FROM [Tickets].[ServiceCatalogSuggestion] scs
        WHERE (scs.[idaraID_FK] = @idaraID OR scs.[idaraID_FK] IS NULL)
          AND scs.[suggestionActive] = 1
        ORDER BY scs.[serviceCatalogSuggestionID] DESC;

        RETURN;
    END

    IF @pageName_ = N'ServiceDDL'
    BEGIN
         SELECT s.[serviceID], s.[serviceName_A], s.[serviceName_E], s.[ticketClassID_FK]
        FROM [Tickets].[Service] s
        WHERE s.[serviceActive] = 1
          AND (s.[idaraID_FK] = @idaraID OR s.[idaraID_FK] IS NULL)
        ORDER BY s.[serviceName_A];

        RETURN;
    END
END
GO
/****** Object:  StoredProcedure [Tickets].[ServiceSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE PROCEDURE [Tickets].[ServiceSP]
(
      @Action                      NVARCHAR(200)
    , @serviceID                   BIGINT          = NULL
    , @serviceCode                 NVARCHAR(100)   = NULL
    , @serviceName_A               NVARCHAR(500)   = NULL
    , @serviceName_E               NVARCHAR(500)   = NULL
    , @serviceDesc                 NVARCHAR(2000)  = NULL
    , @idaraID_FK                  INT             = NULL
    , @ticketClassID_FK            INT             = NULL
    , @defaultPriorityID_FK        INT             = NULL
    , @requiresLocation            BIT             = NULL
    , @allowsChildTickets          BIT             = NULL
    , @requiresQualityReview       BIT             = NULL
    , @targetDSDID_FK              INT             = NULL
    , @queueDistributorID_FK       INT             = NULL
    , @changeReason                NVARCHAR(1000)  = NULL
    , @approvedByUserID            INT             = NULL
    , @serviceSLAPolicyID          BIGINT          = NULL
    , @priorityID_FK               INT             = NULL
    , @firstResponseTargetMinutes  INT             = NULL
    , @assignmentTargetMinutes     INT             = NULL
    , @operationalCompletionTargetMinutes INT       = NULL
    , @finalClosureTargetMinutes   INT             = NULL
    , @serviceCatalogSuggestionID  BIGINT          = NULL
    , @proposedServiceName_A       NVARCHAR(500)   = NULL
    , @proposedServiceName_E       NVARCHAR(500)   = NULL
    , @proposedServiceDesc_A       NVARCHAR(2000)  = NULL
    , @proposedServiceDesc         NVARCHAR(2000)  = NULL
    , @proposedTargetDSDID_FK      INT             = NULL
    , @proposedPriorityID_FK       INT             = NULL
    , @approvalNotes_A             NVARCHAR(2000)  = NULL
    , @approvalNotes               NVARCHAR(2000)  = NULL
    , @effectiveFrom               DATETIME        = NULL
    , @entryData                   NVARCHAR (20)   = NULL
    , @hostName                    NVARCHAR (200)  = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;
    DECLARE @NewID BIGINT = NULL;
    DECLARE @Note NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @tc = 0 BEGIN TRAN;

        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN ;THROW 50001, N'نوع الإجراء مطلوب', 1; END

        ----------------------------------------------------------------
        -- INSERT_SERVICE
        ----------------------------------------------------------------
        IF @Action = N'INSERT_SERVICE'
        BEGIN
            IF NULLIF(LTRIM(RTRIM(@serviceName_A)), N'') IS NULL
            BEGIN ;THROW 50001, N'اسم الخدمة بالعربية مطلوب', 1; END

            IF @idaraID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف الإدارة مطلوب', 1; END

            IF EXISTS (
                SELECT 1 FROM [Tickets].[Service]
                WHERE [serviceName_A] = @serviceName_A
                  AND [serviceActive] = 1
                  AND [idaraID_FK] = @idaraID_FK
            )
            BEGIN ;THROW 50001, N'توجد خدمة بنفس الاسم العربي لهذه الإدارة مسبقاً', 1; END

            INSERT INTO [Tickets].[Service]
            (
                  [serviceCode], [serviceName_A], [serviceName_E], [serviceDesc]
                , [idaraID_FK], [ticketClassID_FK], [defaultPriorityID_FK]
                , [requiresLocation], [allowsChildTickets], [requiresQualityReview]
                , [serviceActive], [entryData], [hostName]
            )
            VALUES
            (
                  @serviceCode, @serviceName_A, @serviceName_E, @serviceDesc
                , @idaraID_FK, @ticketClassID_FK, @defaultPriorityID_FK
                , ISNULL(@requiresLocation, 0), ISNULL(@allowsChildTickets, 0), ISNULL(@requiresQualityReview, 0)
                , 1, @entryData, @hostName
            );

            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN ;THROW 50002, N'فشل إنشاء الخدمة بسبب خطأ في توليد المعرف', 1; END

            SET @Note = N'{"serviceID":"' + CAST(@NewID AS NVARCHAR(20))
                + N'","serviceCode":"' + ISNULL(@serviceCode, N'')
                + N'","serviceName_A":"' + ISNULL(@serviceName_A, N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Service]', N'INSERT_SERVICE', @NewID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إنشاء الخدمة بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- UPDATE_SERVICE
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPDATE_SERVICE'
        BEGIN
            IF @serviceID IS NULL
            BEGIN ;THROW 50001, N'معرف الخدمة مطلوب للتحديث', 1; END

            IF NOT EXISTS (SELECT 1 FROM [Tickets].[Service] WHERE [serviceID] = @serviceID AND [serviceActive] = 1)
            BEGIN ;THROW 50001, N'لم يتم العثور على الخدمة أو أنها غير نشطة', 1; END

            UPDATE [Tickets].[Service]
            SET
                  [serviceCode]           = ISNULL(@serviceCode, [serviceCode])
                , [serviceName_A]         = ISNULL(@serviceName_A, [serviceName_A])
                , [serviceName_E]         = ISNULL(@serviceName_E, [serviceName_E])
                , [serviceDesc]           = ISNULL(@serviceDesc, [serviceDesc])
                , [ticketClassID_FK]      = ISNULL(@ticketClassID_FK, [ticketClassID_FK])
                , [defaultPriorityID_FK]  = ISNULL(@defaultPriorityID_FK, [defaultPriorityID_FK])
                , [requiresLocation]      = ISNULL(@requiresLocation, [requiresLocation])
                , [allowsChildTickets]    = ISNULL(@allowsChildTickets, [allowsChildTickets])
                , [requiresQualityReview] = ISNULL(@requiresQualityReview, [requiresQualityReview])
                , [entryData] = ISNULL(ISNULL([entryData],N'') + N',' + @entryData, [entryData])
                , [hostName]  = ISNULL(ISNULL(@hostName,N'') + N',' + [hostName], [hostName])
            WHERE [serviceID] = @serviceID;

            IF @@ROWCOUNT = 0
            BEGIN ;THROW 50002, N'لم يتم تحديث أي صفوف', 1; END

            SET @Note = N'{"serviceID":"' + CAST(@serviceID AS NVARCHAR(20)) + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Service]', N'UPDATE_SERVICE', @serviceID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم تحديث الخدمة بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- DELETE_SERVICE (soft delete)
        ----------------------------------------------------------------
        ELSE IF @Action = N'DELETE_SERVICE'
        BEGIN
            IF @serviceID IS NULL
            BEGIN ;THROW 50001, N'معرف الخدمة مطلوب للحذف', 1; END

            IF NOT EXISTS (SELECT 1 FROM [Tickets].[Service] WHERE [serviceID] = @serviceID AND [serviceActive] = 1)
            BEGIN ;THROW 50001, N'لم يتم العثور على الخدمة أو أنها غير نشطة مسبقاً', 1; END

            UPDATE [Tickets].[Service]
            SET [serviceActive] = 0
              , [entryData] = ISNULL(ISNULL([entryData],N'') + N',' + @entryData, [entryData])
              , [hostName]  = ISNULL(ISNULL(@hostName,N'') + N',' + [hostName], [hostName])
            WHERE [serviceID] = @serviceID;

            IF @@ROWCOUNT = 0
            BEGIN ;THROW 50002, N'لم يتم حذف أي صفوف', 1; END

            SET @Note = N'{"serviceID":"' + CAST(@serviceID AS NVARCHAR(20)) + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Service]', N'DELETE_SERVICE', @serviceID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم تعطيل الخدمة بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- INSERT_ROUTING_RULE
        ----------------------------------------------------------------
        ELSE IF @Action = N'INSERT_ROUTING_RULE'
        BEGIN
            IF @serviceID IS NULL
            BEGIN ;THROW 50001, N'معرف الخدمة مطلوب لقاعدة التوجيه', 1; END

            IF @targetDSDID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف الجهة المستهدفة مطلوب لقاعدة التوجيه', 1; END

            IF @idaraID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف الإدارة مطلوب لقاعدة التوجيه', 1; END

            IF NOT EXISTS (SELECT 1 FROM [Tickets].[Service] WHERE [serviceID] = @serviceID AND [serviceActive] = 1)
            BEGIN ;THROW 50001, N'لم يتم العثور على خدمة نشطة', 1; END

            DECLARE @EffFrom DATETIME = ISNULL(@effectiveFrom, GETDATE());

            INSERT INTO [Tickets].[ServiceRoutingRule]
            (
                  [serviceID_FK], [idaraID_FK], [targetDSDID_FK], [queueDistributorID_FK]
                , [effectiveFrom], [changeReason], [approvedByUserID]
                , [serviceRoutingRuleActive], [entryData], [hostName]
            )
            VALUES
            (
                  @serviceID, @idaraID_FK, @targetDSDID_FK, @queueDistributorID_FK
                , @EffFrom, @changeReason, @approvedByUserID
                , 1, @entryData, @hostName
            );

            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN ;THROW 50002, N'فشل إنشاء قاعدة التوجيه', 1; END

            SET @Note = N'{"serviceRoutingRuleID":"' + CAST(@NewID AS NVARCHAR(20))
                + N'","serviceID":"' + CAST(@serviceID AS NVARCHAR(20))
                + N'","targetDSDID_FK":"' + CAST(@targetDSDID_FK AS NVARCHAR(20)) + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ServiceRoutingRule]', N'INSERT_ROUTING_RULE', @NewID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إنشاء قاعدة التوجيه بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- CLOSE_ROUTING_RULE
        ----------------------------------------------------------------
        ELSE IF @Action = N'CLOSE_ROUTING_RULE'
        BEGIN
            DECLARE @RuleID BIGINT = @serviceID;

            IF @RuleID IS NULL
            BEGIN ;THROW 50001, N'معرف قاعدة توجيه الخدمة (الممرر كـ @serviceID) مطلوب', 1; END

            IF NOT EXISTS (SELECT 1 FROM [Tickets].[ServiceRoutingRule] WHERE [serviceRoutingRuleID] = @RuleID AND [serviceRoutingRuleActive] = 1)
            BEGIN ;THROW 50001, N'لم يتم العثور على قاعدة توجيه نشطة', 1; END

            UPDATE [Tickets].[ServiceRoutingRule]
            SET [effectiveTo] = GETDATE()
              , [serviceRoutingRuleActive] = 0
              , [entryData] = ISNULL(ISNULL([entryData],N'') + N',' + @entryData, [entryData])
              , [hostName]  = ISNULL(ISNULL(@hostName,N'') + N',' + [hostName], [hostName])
            WHERE [serviceRoutingRuleID] = @RuleID;

            IF @@ROWCOUNT = 0
            BEGIN ;THROW 50002, N'لم يتم إغلاق أي قاعدة توجيه', 1; END

            SET @Note = N'{"serviceRoutingRuleID":"' + CAST(@RuleID AS NVARCHAR(20)) + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ServiceRoutingRule]', N'CLOSE_ROUTING_RULE', @RuleID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إغلاق قاعدة التوجيه بنجاح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- UPSERT_SLA_POLICY
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPSERT_SLA_POLICY'
        BEGIN
            IF @serviceID IS NULL
            BEGIN ;THROW 50001, N'معرف الخدمة مطلوب لسياسة SLA', 1; END

            IF @priorityID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف الأولوية مطلوب لسياسة SLA', 1; END

            IF @idaraID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف الإدارة مطلوب لسياسة SLA', 1; END

            IF EXISTS (
                SELECT 1 FROM [Tickets].[ServiceSLAPolicy]
                WHERE [serviceID_FK] = @serviceID
                  AND [priorityID_FK] = @priorityID_FK
                  AND [idaraID_FK] = @idaraID_FK
                  AND [slaPolicyActive] = 1
            )
            BEGIN
                UPDATE [Tickets].[ServiceSLAPolicy]
                SET
                      [firstResponseTargetMinutes]         = ISNULL(@firstResponseTargetMinutes, [firstResponseTargetMinutes])
                    , [assignmentTargetMinutes]            = ISNULL(@assignmentTargetMinutes, [assignmentTargetMinutes])
                    , [operationalCompletionTargetMinutes] = ISNULL(@operationalCompletionTargetMinutes, [operationalCompletionTargetMinutes])
                    , [finalClosureTargetMinutes]          = ISNULL(@finalClosureTargetMinutes, [finalClosureTargetMinutes])
                    , [entryData] = ISNULL(ISNULL([entryData],N'') + N',' + @entryData, [entryData])
                    , [hostName]  = ISNULL(ISNULL(@hostName,N'') + N',' + [hostName], [hostName])
                WHERE [serviceID_FK] = @serviceID
                  AND [priorityID_FK] = @priorityID_FK
                  AND [idaraID_FK] = @idaraID_FK
                  AND [slaPolicyActive] = 1;

                SET @Note = N'{"action":"UPDATED","serviceID":"' + CAST(@serviceID AS NVARCHAR(20))
                    + N'","priorityID_FK":"' + CAST(@priorityID_FK AS NVARCHAR(20)) + N'"}';

                INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
                VALUES (N'[Tickets].[ServiceSLAPolicy]', N'UPSERT_SLA_POLICY', @serviceID, @entryData, @Note);

                SELECT 1 AS IsSuccessful, N'تم تحديث سياسة SLA بنجاح' AS Message_;
                RETURN;
            END
            ELSE
            BEGIN
                INSERT INTO [Tickets].[ServiceSLAPolicy]
                (
                      [idaraID_FK], [serviceID_FK], [priorityID_FK]
                    , [firstResponseTargetMinutes], [assignmentTargetMinutes]
                    , [operationalCompletionTargetMinutes], [finalClosureTargetMinutes]
                    , [effectiveFrom], [slaPolicyActive], [entryData], [hostName]
                )
                VALUES
                (
                      @idaraID_FK, @serviceID, @priorityID_FK
                    , @firstResponseTargetMinutes, @assignmentTargetMinutes
                    , @operationalCompletionTargetMinutes, @finalClosureTargetMinutes
                    , GETDATE(), 1, @entryData, @hostName
                );

                SET @NewID = SCOPE_IDENTITY();

                SET @Note = N'{"action":"INSERTED","serviceSLAPolicyID":"' + ISNULL(CAST(@NewID AS NVARCHAR(20)), N'')
                    + N'","serviceID":"' + CAST(@serviceID AS NVARCHAR(20))
                    + N'","priorityID_FK":"' + CAST(@priorityID_FK AS NVARCHAR(20)) + N'"}';

                INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
                VALUES (N'[Tickets].[ServiceSLAPolicy]', N'UPSERT_SLA_POLICY', @NewID, @entryData, @Note);

                SELECT 1 AS IsSuccessful, N'تم إنشاء سياسة SLA بنجاح' AS Message_;
                RETURN;
            END
        END

        ----------------------------------------------------------------
        -- APPROVE_SERVICE_SUGGESTION
        ----------------------------------------------------------------
        ELSE IF @Action = N'APPROVE_SERVICE_SUGGESTION'
        BEGIN
            IF @serviceCatalogSuggestionID IS NULL
            BEGIN ;THROW 50001, N'معرف اقتراح دليل الخدمة مطلوب', 1; END

            DECLARE @SugID BIGINT = @serviceCatalogSuggestionID;
            DECLARE @SugIdaraID INT;
            DECLARE @SugName_A NVARCHAR(500);
            DECLARE @SugName_E NVARCHAR(500);
            DECLARE @SugDesc NVARCHAR(2000);
            DECLARE @SugDSDID INT;
            DECLARE @SugPriorityID INT;

            SELECT
                  @SugIdaraID  = [idaraID_FK]
                , @SugName_A   = [proposedServiceName_A]
                , @SugName_E   = [proposedServiceName_E]
                                , @SugDesc     = COALESCE([proposedServiceDesc_A], [proposedServiceDesc])
                , @SugDSDID    = [proposedTargetDSDID_FK]
                , @SugPriorityID = [proposedPriorityID_FK]
            FROM [Tickets].[ServiceCatalogSuggestion]
            WHERE [serviceCatalogSuggestionID] = @SugID
              AND [approvalStatus] = N'PENDING';

            IF @SugName_A IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على الاقتراح أو أنه ليس في حالة PENDING', 1; END

            INSERT INTO [Tickets].[Service]
            (
                  [serviceCode], [serviceName_A], [serviceName_E], [serviceDesc]
                , [idaraID_FK], [defaultPriorityID_FK]
                , [requiresLocation], [allowsChildTickets], [requiresQualityReview]
                , [serviceActive], [entryData], [hostName]
            )
            VALUES
            (
                  N'SUG-' + CAST(@SugID AS NVARCHAR(20))
                , @SugName_A, @SugName_E, @SugDesc
                , @SugIdaraID, @SugPriorityID
                , 1, 0, 1
                , 1, @entryData, @hostName
            );

            SET @NewID = SCOPE_IDENTITY();

            UPDATE [Tickets].[ServiceCatalogSuggestion]
            SET
                  [approvalStatus]    = N'APPROVED'
                , [approvedByUserID]  = @approvedByUserID
                , [approvalDate]      = GETDATE()
                                , [approvalNotes_A]   = ISNULL(@approvalNotes_A, @approvalNotes)
                                , [approvalNotes]     = ISNULL(@approvalNotes, @approvalNotes_A)
                , [createdServiceID_FK] = @NewID
                , [entryData] = ISNULL(ISNULL([entryData],N'') + N',' + @entryData, [entryData])
                , [hostName]  = ISNULL(ISNULL(@hostName,N'') + N',' + [hostName], [hostName])
            WHERE [serviceCatalogSuggestionID] = @SugID;

            IF @SugDSDID IS NOT NULL
            BEGIN
                INSERT INTO [Tickets].[ServiceRoutingRule]
                (
                      [serviceID_FK], [idaraID_FK], [targetDSDID_FK]
                    , [effectiveFrom], [changeReason], [approvedByUserID]
                    , [serviceRoutingRuleActive], [entryData], [hostName]
                )
                VALUES
                (
                      @NewID, @SugIdaraID, @SugDSDID
                    , GETDATE(), N'تم الإنشاء تلقائياً من اقتراح معتمد رقم ' + CAST(@SugID AS NVARCHAR(20))
                    , @approvedByUserID
                    , 1, @entryData, @hostName
                );
            END

            SET @Note = N'{"suggestionID":"' + CAST(@SugID AS NVARCHAR(20))
                + N'","createdServiceID":"' + CAST(@NewID AS NVARCHAR(20)) + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ServiceCatalogSuggestion]', N'APPROVE_SERVICE_SUGGESTION', @SugID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تمت الموافقة على الاقتراح وإنشاء الخدمة' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- REJECT_SERVICE_SUGGESTION
        ----------------------------------------------------------------
        ELSE IF @Action = N'REJECT_SERVICE_SUGGESTION'
        BEGIN
            IF @serviceCatalogSuggestionID IS NULL
            BEGIN ;THROW 50001, N'معرف اقتراح دليل الخدمة مطلوب', 1; END

            SET @SugID = @serviceCatalogSuggestionID;

            IF NOT EXISTS (
                SELECT 1 FROM [Tickets].[ServiceCatalogSuggestion]
                WHERE [serviceCatalogSuggestionID] = @SugID
                  AND [approvalStatus] = N'PENDING'
            )
            BEGIN ;THROW 50001, N'لم يتم العثور على الاقتراح أو أنه ليس في حالة PENDING', 1; END

            UPDATE [Tickets].[ServiceCatalogSuggestion]
            SET
                  [approvalStatus]   = N'REJECTED'
                , [approvedByUserID] = @approvedByUserID
                , [approvalDate]     = GETDATE()
                                , [approvalNotes_A]  = ISNULL(@approvalNotes_A, @approvalNotes)
                                , [approvalNotes]    = ISNULL(@approvalNotes, @approvalNotes_A)
                , [suggestionActive] = 0
                , [entryData] = ISNULL(ISNULL([entryData],N'') + N',' + @entryData, [entryData])
                , [hostName]  = ISNULL(ISNULL(@hostName,N'') + N',' + [hostName], [hostName])
            WHERE [serviceCatalogSuggestionID] = @SugID;

            IF @@ROWCOUNT = 0
            BEGIN ;THROW 50002, N'لم يتم تحديث أي اقتراح', 1; END

            SET @Note = N'{"suggestionID":"' + CAST(@SugID AS NVARCHAR(20)) + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ServiceCatalogSuggestion]', N'REJECT_SERVICE_SUGGESTION', @SugID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم رفض الاقتراح' AS Message_;
            RETURN;
        END

        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'نوع الإجراء غير معروف في ServiceSP', 1;
        END

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        ;THROW;
    END CATCH
END


GO
/****** Object:  StoredProcedure [Tickets].[TicketDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE PROCEDURE [Tickets].[TicketDL]
(
      @pageName_          NVARCHAR(400)
    , @idaraID            INT
    , @entryData          INT
    , @hostName           NVARCHAR(400)
    , @filterTicketID     BIGINT = NULL
    , @filterTicketNo     NVARCHAR(50) = NULL
    , @filterStatusID     INT = NULL
    , @filterServiceID    BIGINT = NULL
    , @filterAssignedUserID INT = NULL
    , @filterDSDID        INT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @pageName_ = N'TicketDetails' OR @pageName_ IS NULL
    BEGIN
        SELECT
              t.[ticketID]
            , t.[ticketNo]
            , t.[idaraID_FK]
            , t.[parentTicketID_FK]
            , t.[rootTicketID_FK]
            , t.[serviceID_FK]
            , CASE
                WHEN svc.[serviceName_A] IS NULL OR svc.[serviceName_A] NOT LIKE N'%[ء-ي]%'
                  THEN svc.[serviceName_E]
                ELSE svc.[serviceName_A]
              END AS [serviceName_A]
            , svc.[serviceName_E]
            , t.[ticketClassID_FK]
            , CASE
                WHEN tc.[ticketClassName_A] IS NULL OR tc.[ticketClassName_A] NOT LIKE N'%[ء-ي]%'
                  THEN tc.[ticketClassName_E]
                ELSE tc.[ticketClassName_A]
              END AS [ticketClassName_A]
            , tc.[ticketClassName_E]
            , t.[requesterTypeID_FK]
            , CASE
                WHEN rt.[requesterTypeName_A] IS NULL OR rt.[requesterTypeName_A] NOT LIKE N'%[ء-ي]%'
                  THEN rt.[requesterTypeName_E]
                ELSE rt.[requesterTypeName_A]
              END AS [requesterTypeName_A]
            , rt.[requesterTypeName_E]
            , t.[requesterUserID_FK]
            , t.[requesterResidentID_FK]
            , LTRIM(RTRIM(
                  ISNULL(rud.firstName_A, N'') + N' ' +
                  ISNULL(rud.secondName_A, N'') + N' ' +
                  ISNULL(rud.thirdName_A, N'') + N' ' +
                  ISNULL(rud.lastName_A, N'')
              )) AS [requesterName]
            , COALESCE(t.[title_A], t.[title]) AS [title]
            , COALESCE(t.[description_A], t.[description_]) AS [description_]
            , t.[suggestedPriorityID_FK]
            , t.[effectivePriorityID_FK]
            , CASE
                WHEN p.[priorityName_A] IS NULL OR p.[priorityName_A] NOT LIKE N'%[ء-ي]%'
                  THEN p.[priorityName_E]
                ELSE p.[priorityName_A]
              END AS [priorityName_A]
            , p.[priorityName_E]
            , p.[priorityCode]
            , t.[ticketStatusID_FK]
            , ts.[ticketStatusCode]
            , CASE
                WHEN ts.[ticketStatusName_A] IS NULL OR ts.[ticketStatusName_A] NOT LIKE N'%[ء-ي]%'
                  THEN ts.[ticketStatusName_E]
                ELSE ts.[ticketStatusName_A]
              END AS [ticketStatusName_A]
            , ts.[ticketStatusName_E]
            , t.[currentDSDID_FK]
            , t.[currentQueueDistributorID_FK]
            , t.[assignedUserID_FK]
            , LTRIM(RTRIM(
                  ISNULL(aud.firstName_A, N'') + N' ' +
                  ISNULL(aud.secondName_A, N'') + N' ' +
                  ISNULL(aud.thirdName_A, N'') + N' ' +
                  ISNULL(aud.lastName_A, N'')
              )) AS [assignedUserName]
            , t.[locationBuildingNo]
            , t.[locationUnitNo]
            , COALESCE(t.[locationArea_A], t.[locationArea]) AS [locationArea]
            , t.[operationalResolutionDate]
            , t.[finalClosureDate]
            , t.[requiresQualityReview]
            , t.[isOtherService]
            , t.[isParentBlocked]
            , t.[ticketActive]
            , svc.[allowsChildTickets]
            , sla.[elapsedMinutes]   AS [slaElapsedMinutes]
            , sla.[targetMinutes]    AS [slaTargetMinutes]
            , sla.[isBreached]       AS [slaIsBreached]
            , sla.[slaTypeCode]      AS [slaTypeCode]
            , t.[entryDate]
        FROM [Tickets].[Ticket] t
        LEFT JOIN [Tickets].[Service] svc ON t.[serviceID_FK] = svc.[serviceID]
        LEFT JOIN [Tickets].[TicketClass] tc ON t.[ticketClassID_FK] = tc.[ticketClassID]
        LEFT JOIN [Tickets].[RequesterType] rt ON t.[requesterTypeID_FK] = rt.[requesterTypeID]
        LEFT JOIN [Tickets].[Priority] p ON t.[effectivePriorityID_FK] = p.[priorityID]
        LEFT JOIN [Tickets].[TicketStatus] ts ON t.[ticketStatusID_FK] = ts.[ticketStatusID]
        -- Requester user name (active details row only)
        OUTER APPLY (
            SELECT TOP 1
                  CASE WHEN ud.firstName_A IS NULL OR ud.firstName_A NOT LIKE N'%[ء-ي]%' THEN ud.firstName_E ELSE ud.firstName_A END AS firstName_A
                , CASE WHEN ud.secondName_A IS NULL OR ud.secondName_A NOT LIKE N'%[ء-ي]%' THEN ud.secondName_E ELSE ud.secondName_A END AS secondName_A
                , CASE WHEN ud.thirdName_A IS NULL OR ud.thirdName_A NOT LIKE N'%[ء-ي]%' THEN ud.thirdName_E ELSE ud.thirdName_A END AS thirdName_A
                , CASE WHEN ud.lastName_A IS NULL OR ud.lastName_A NOT LIKE N'%[ء-ي]%' THEN ud.lastName_E ELSE ud.lastName_A END AS lastName_A
            FROM dbo.UsersDetails ud
            WHERE ud.usersID_FK = t.[requesterUserID_FK]
              AND ud.userActive = 1
            ORDER BY ud.entryDate DESC, ud.usersDetailsID DESC
        ) rud
        -- Assigned user name (active details row only)
        OUTER APPLY (
            SELECT TOP 1
                  CASE WHEN ud.firstName_A IS NULL OR ud.firstName_A NOT LIKE N'%[ء-ي]%' THEN ud.firstName_E ELSE ud.firstName_A END AS firstName_A
                , CASE WHEN ud.secondName_A IS NULL OR ud.secondName_A NOT LIKE N'%[ء-ي]%' THEN ud.secondName_E ELSE ud.secondName_A END AS secondName_A
                , CASE WHEN ud.thirdName_A IS NULL OR ud.thirdName_A NOT LIKE N'%[ء-ي]%' THEN ud.thirdName_E ELSE ud.thirdName_A END AS thirdName_A
                , CASE WHEN ud.lastName_A IS NULL OR ud.lastName_A NOT LIKE N'%[ء-ي]%' THEN ud.lastName_E ELSE ud.lastName_A END AS lastName_A
            FROM dbo.UsersDetails ud
            WHERE ud.usersID_FK = t.[assignedUserID_FK]
              AND ud.userActive = 1
            ORDER BY ud.entryDate DESC, ud.usersDetailsID DESC
        ) aud
        -- Resolution SLA
        OUTER APPLY (
            SELECT TOP 1 sl.[elapsedMinutes], sl.[targetMinutes], sl.[isBreached], sl.[slaTypeCode]
            FROM [Tickets].[TicketSLA] sl
            WHERE sl.[ticketID_FK] = t.[ticketID]
              AND sl.[slaTypeCode] = N'RESOLUTION'
              AND sl.[ticketSLAActive] = 1
        ) sla
        WHERE t.[ticketActive] = 1
          AND (t.[idaraID_FK] = @idaraID OR @idaraID IS NULL)
          AND (t.[ticketID] = @filterTicketID OR @filterTicketID IS NULL)
          AND (t.[ticketNo] = @filterTicketNo OR @filterTicketNo IS NULL)
          AND (t.[ticketStatusID_FK] = @filterStatusID OR @filterStatusID IS NULL)
          AND (t.[serviceID_FK] = @filterServiceID OR @filterServiceID IS NULL)
          AND (t.[assignedUserID_FK] = @filterAssignedUserID OR @filterAssignedUserID IS NULL)
          AND (t.[currentDSDID_FK] = @filterDSDID OR @filterDSDID IS NULL)
        ORDER BY t.[ticketID] DESC;

        RETURN;
    END

    IF @pageName_ = N'TicketList'
    BEGIN
        SELECT
              t.[ticketID]
            , t.[ticketNo]
            , COALESCE(t.[title_A], t.[title]) AS [title]
            , CASE
                WHEN s.[serviceName_A] IS NULL OR s.[serviceName_A] NOT LIKE N'%[ء-ي]%'
                  THEN s.[serviceName_E]
                ELSE s.[serviceName_A]
              END AS [serviceName_A]
            , s.[serviceName_E]
            , CASE
                WHEN rt.[requesterTypeName_A] IS NULL OR rt.[requesterTypeName_A] NOT LIKE N'%[ء-ي]%'
                  THEN rt.[requesterTypeName_E]
                ELSE rt.[requesterTypeName_A]
              END AS [requesterTypeName_A]
            , rt.[requesterTypeName_E]
            , COALESCE(
                NULLIF(LTRIM(RTRIM(
                    ISNULL(rud.firstName_A, N'') + N' ' +
                    ISNULL(rud.secondName_A, N'') + N' ' +
                    ISNULL(rud.thirdName_A, N'') + N' ' +
                    ISNULL(rud.lastName_A, N'')
                )), N''),
                rres.[ResidentName_A]
              ) AS [requesterName]
            , CASE
                WHEN p.[priorityName_A] IS NULL OR p.[priorityName_A] NOT LIKE N'%[ء-ي]%'
                  THEN p.[priorityName_E]
                ELSE p.[priorityName_A]
              END AS [priorityName_A]
            , p.[priorityName_E]
            , CASE
                WHEN ts.[ticketStatusName_A] IS NULL OR ts.[ticketStatusName_A] NOT LIKE N'%[ء-ي]%'
                  THEN ts.[ticketStatusName_E]
                ELSE ts.[ticketStatusName_A]
              END AS [ticketStatusName_A]
            , ts.[ticketStatusName_E]
            , ts.[ticketStatusCode]
            , COALESCE(
                NULLIF(LTRIM(RTRIM(
                    ISNULL(aud.firstName_A, N'') + N' ' +
                    ISNULL(aud.secondName_A, N'') + N' ' +
                    ISNULL(aud.thirdName_A, N'') + N' ' +
                    ISNULL(aud.lastName_A, N'')
                )), N''),
                dsd.[dsdName_A]
              ) AS [assignedUserName]
            , sla.[elapsedMinutes]
            , t.[currentDSDID_FK]
            , t.[assignedUserID_FK]
            , t.[entryDate]
        FROM [Tickets].[Ticket] t
        LEFT JOIN [Tickets].[Service] s ON t.[serviceID_FK] = s.[serviceID]
        LEFT JOIN [Tickets].[Priority] p ON t.[effectivePriorityID_FK] = p.[priorityID]
        LEFT JOIN [Tickets].[TicketStatus] ts ON t.[ticketStatusID_FK] = ts.[ticketStatusID]
        LEFT JOIN [Tickets].[RequesterType] rt ON t.[requesterTypeID_FK] = rt.[requesterTypeID]
        -- Requester user name (active details row only)
        OUTER APPLY (
            SELECT TOP 1
                  CASE WHEN ud.firstName_A IS NULL OR ud.firstName_A NOT LIKE N'%[ء-ي]%' THEN ud.firstName_E ELSE ud.firstName_A END AS firstName_A
                , CASE WHEN ud.secondName_A IS NULL OR ud.secondName_A NOT LIKE N'%[ء-ي]%' THEN ud.secondName_E ELSE ud.secondName_A END AS secondName_A
                , CASE WHEN ud.thirdName_A IS NULL OR ud.thirdName_A NOT LIKE N'%[ء-ي]%' THEN ud.thirdName_E ELSE ud.thirdName_A END AS thirdName_A
                , CASE WHEN ud.lastName_A IS NULL OR ud.lastName_A NOT LIKE N'%[ء-ي]%' THEN ud.lastName_E ELSE ud.lastName_A END AS lastName_A
            FROM dbo.UsersDetails ud
            WHERE ud.usersID_FK = t.[requesterUserID_FK]
              AND ud.userActive = 1
            ORDER BY ud.entryDate DESC, ud.usersDetailsID DESC
        ) rud
        -- Assigned user name (active details row only)
        OUTER APPLY (
            SELECT TOP 1
                  CASE WHEN ud.firstName_A IS NULL OR ud.firstName_A NOT LIKE N'%[ء-ي]%' THEN ud.firstName_E ELSE ud.firstName_A END AS firstName_A
                , CASE WHEN ud.secondName_A IS NULL OR ud.secondName_A NOT LIKE N'%[ء-ي]%' THEN ud.secondName_E ELSE ud.secondName_A END AS secondName_A
                , CASE WHEN ud.thirdName_A IS NULL OR ud.thirdName_A NOT LIKE N'%[ء-ي]%' THEN ud.thirdName_E ELSE ud.thirdName_A END AS thirdName_A
                , CASE WHEN ud.lastName_A IS NULL OR ud.lastName_A NOT LIKE N'%[ء-ي]%' THEN ud.lastName_E ELSE ud.lastName_A END AS lastName_A
            FROM dbo.UsersDetails ud
            WHERE ud.usersID_FK = t.[assignedUserID_FK]
              AND ud.userActive = 1
            ORDER BY ud.entryDate DESC, ud.usersDetailsID DESC
        ) aud
        -- Requester resident name (for RESIDENT type tickets where requesterUserID_FK is NULL)
        OUTER APPLY (
            SELECT TOP 1 r.[FullName_A] AS [ResidentName_A]
            FROM [Housing].[V_GetFullResidentDetails] r
            WHERE r.[residentInfoID] = t.[requesterResidentID_FK]
        ) rres
        -- Resolution SLA elapsed minutes
        OUTER APPLY (
            SELECT TOP 1 sl.[elapsedMinutes]
            FROM [Tickets].[TicketSLA] sl
            WHERE sl.[ticketID_FK] = t.[ticketID]
              AND sl.[slaTypeCode] = N'RESOLUTION'
              AND sl.[ticketSLAActive] = 1
        ) sla
        -- Current DSD name (department/section/division) for tickets not yet assigned to a user
        OUTER APPLY (
            SELECT
                COALESCE(
                    NULLIF(LTRIM(RTRIM(
                        COALESCE(f.[DepartmentName], N'')
                        + CASE WHEN f.[SectionName] IS NOT NULL THEN N' / ' + f.[SectionName] ELSE N'' END
                        + CASE WHEN f.[DivisonName]  IS NOT NULL THEN N' / ' + f.[DivisonName]  ELSE N'' END
                    )), N''),
                    f.[IdaraName],
                    CAST(t.[currentDSDID_FK] AS NVARCHAR(20))
                ) AS [dsdName_A]
            FROM dbo.V_GetFullStructureForDSD f
            WHERE f.[DSDID] = t.[currentDSDID_FK]
        ) dsd
        WHERE t.[ticketActive] = 1
          AND (t.[idaraID_FK] = @idaraID OR @idaraID IS NULL)
          AND (t.[ticketStatusID_FK] = @filterStatusID OR @filterStatusID IS NULL)
          AND (t.[serviceID_FK] = @filterServiceID OR @filterServiceID IS NULL)
          AND (t.[currentDSDID_FK] = @filterDSDID OR @filterDSDID IS NULL)
        ORDER BY t.[ticketID] DESC;

        SELECT [ticketStatusID], [ticketStatusName_A], [ticketStatusName_E]
        FROM [Tickets].[TicketStatus]
        WHERE [ticketStatusActive] = 1
        ORDER BY [ticketStatusID];

        SELECT [serviceID], [serviceName_A], [serviceName_E]
        FROM [Tickets].[Service]
        WHERE [serviceActive] = 1
          AND ([idaraID_FK] = @idaraID OR @idaraID IS NULL OR [idaraID_FK] IS NULL)
        ORDER BY [serviceID];

        RETURN;
    END

    IF @pageName_ = N'TicketHistory'
    BEGIN
        SELECT
              th.[ticketHistoryID]
            , th.[ticketID_FK]
            , th.[actionTypeCode]
            , th.[oldStatusID_FK]
            , os.[ticketStatusCode]   AS [oldStatusCode]
            , COALESCE(os.[ticketStatusName_A], os.[ticketStatusName_E]) AS [oldStatusName_E]
            , os.[ticketStatusName_A] AS [oldStatusName_A]
            , th.[newStatusID_FK]
            , ns.[ticketStatusCode]   AS [newStatusCode]
            , COALESCE(ns.[ticketStatusName_A], ns.[ticketStatusName_E]) AS [newStatusName_E]
            , ns.[ticketStatusName_A] AS [newStatusName_A]
            , th.[oldDSDID_FK]
            , th.[newDSDID_FK]
            , th.[oldAssignedUserID]
            , th.[newAssignedUserID]
            , th.[performerUserID]
            , LTRIM(RTRIM(
                  ISNULL(pud.firstName_A, N'') + N' ' +
                  ISNULL(pud.secondName_A, N'') + N' ' +
                  ISNULL(pud.thirdName_A, N'') + N' ' +
                  ISNULL(pud.lastName_A, N'')
              )) AS [performerName]
            , COALESCE(
                NULLIF(th.[notes_A], N''),
                CASE th.[notes]
                  WHEN N'Ticket created' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â¥Ã™â€ Ã˜Â´Ã˜Â§Ã˜Â¡ Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â©'
                  WHEN N'Ticket routed' THEN N'Ã˜ÂªÃ™â€¦ Ã˜ÂªÃ™Ë†Ã˜Â¬Ã™Å Ã™â€¡ Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â©'
                  WHEN N'Ticket assigned' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â¥Ã˜Â³Ã™â€ Ã˜Â§Ã˜Â¯ Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â©'
                  WHEN N'Ticket reassigned' THEN N'Ã˜ÂªÃ™â€¦Ã˜Âª Ã˜Â¥Ã˜Â¹Ã˜Â§Ã˜Â¯Ã˜Â© Ã˜Â¥Ã˜Â³Ã™â€ Ã˜Â§Ã˜Â¯ Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â©'
                  WHEN N'Work started' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â¨Ã˜Â¯Ã˜Â¡ Ã˜Â§Ã™â€žÃ˜Â¹Ã™â€¦Ã™â€ž'
                  WHEN N'Ticket resolved - awaiting quality review' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â­Ã™â€ž Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â© - Ã˜Â¨Ã˜Â§Ã™â€ Ã˜ÂªÃ˜Â¸Ã˜Â§Ã˜Â± Ã™â€¦Ã˜Â±Ã˜Â§Ã˜Â¬Ã˜Â¹Ã˜Â© Ã˜Â§Ã™â€žÃ˜Â¬Ã™Ë†Ã˜Â¯Ã˜Â©'
                  WHEN N'Ticket resolved and closed' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â­Ã™â€ž Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â© Ã™Ë†Ã˜Â¥Ã˜ÂºÃ™â€žÃ˜Â§Ã™â€šÃ™â€¡Ã˜Â§'
                  WHEN N'Ticket closed' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â¥Ã˜ÂºÃ™â€žÃ˜Â§Ã™â€š Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â©'
                  WHEN N'Ticket paused' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â¥Ã™Å Ã™â€šÃ˜Â§Ã™Â Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â©'
                  WHEN N'Ticket resumed' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â§Ã˜Â³Ã˜ÂªÃ˜Â¦Ã™â€ Ã˜Â§Ã™Â Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â©'
                  WHEN N'Child ticket created' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â¥Ã™â€ Ã˜Â´Ã˜Â§Ã˜Â¡ Ã˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â© Ã™ÂÃ˜Â±Ã˜Â¹Ã™Å Ã˜Â©'
                  WHEN N'Quality review approved - ticket closed' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â§Ã˜Â¹Ã˜ÂªÃ™â€¦Ã˜Â§Ã˜Â¯ Ã™â€¦Ã˜Â±Ã˜Â§Ã˜Â¬Ã˜Â¹Ã˜Â© Ã˜Â§Ã™â€žÃ˜Â¬Ã™Ë†Ã˜Â¯Ã˜Â© - Ã˜ÂªÃ™â€¦ Ã˜Â¥Ã˜ÂºÃ™â€žÃ˜Â§Ã™â€š Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â°Ã™Æ’Ã˜Â±Ã˜Â©'
                  WHEN N'Quality review returned for correction' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â¥Ã˜Â±Ã˜Â¬Ã˜Â§Ã˜Â¹ Ã™â€¦Ã˜Â±Ã˜Â§Ã˜Â¬Ã˜Â¹Ã˜Â© Ã˜Â§Ã™â€žÃ˜Â¬Ã™Ë†Ã˜Â¯Ã˜Â© Ã™â€žÃ™â€žÃ˜ÂªÃ˜ÂµÃ˜Â­Ã™Å Ã˜Â­'
                  WHEN N'Quality review escalated to arbitration' THEN N'Ã˜ÂªÃ™â€¦ Ã˜ÂªÃ˜ÂµÃ˜Â¹Ã™Å Ã˜Â¯ Ã™â€¦Ã˜Â±Ã˜Â§Ã˜Â¬Ã˜Â¹Ã˜Â© Ã˜Â§Ã™â€žÃ˜Â¬Ã™Ë†Ã˜Â¯Ã˜Â© Ã˜Â¥Ã™â€žÃ™â€° Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â­Ã™Æ’Ã™Å Ã™â€¦'
                  WHEN N'Arbitration raised' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â±Ã™ÂÃ˜Â¹ Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â­Ã™Æ’Ã™Å Ã™â€¦'
                  WHEN N'Arbitration decided' THEN N'Ã˜ÂªÃ™â€¦ Ã˜Â§Ã˜ÂªÃ˜Â®Ã˜Â§Ã˜Â° Ã™â€šÃ˜Â±Ã˜Â§Ã˜Â± Ã˜Â§Ã™â€žÃ˜ÂªÃ˜Â­Ã™Æ’Ã™Å Ã™â€¦'
                  ELSE th.[notes]
                END
              ) AS [notes]
            , th.[actionDate]
        FROM [Tickets].[TicketHistory] th
        LEFT JOIN [Tickets].[TicketStatus] os ON th.[oldStatusID_FK] = os.[ticketStatusID]
        LEFT JOIN [Tickets].[TicketStatus] ns ON th.[newStatusID_FK] = ns.[ticketStatusID]
        OUTER APPLY (
            SELECT TOP 1
                  CASE WHEN ud.firstName_A IS NULL OR ud.firstName_A NOT LIKE N'%[ء-ي]%' THEN ud.firstName_E ELSE ud.firstName_A END AS firstName_A
                , CASE WHEN ud.secondName_A IS NULL OR ud.secondName_A NOT LIKE N'%[ء-ي]%' THEN ud.secondName_E ELSE ud.secondName_A END AS secondName_A
                , CASE WHEN ud.thirdName_A IS NULL OR ud.thirdName_A NOT LIKE N'%[ء-ي]%' THEN ud.thirdName_E ELSE ud.thirdName_A END AS thirdName_A
                , CASE WHEN ud.lastName_A IS NULL OR ud.lastName_A NOT LIKE N'%[ء-ي]%' THEN ud.lastName_E ELSE ud.lastName_A END AS lastName_A
            FROM dbo.UsersDetails ud
            WHERE ud.usersID_FK = th.[performerUserID]
            ORDER BY ud.entryDate DESC, ud.usersDetailsID DESC
        ) pud
        WHERE th.[ticketID_FK] = @filterTicketID
        ORDER BY th.[ticketHistoryID];

        RETURN;
    END

    IF @pageName_ = N'StatusDDL'
    BEGIN
        SELECT [ticketStatusID], [ticketStatusCode], [ticketStatusName_A], [ticketStatusName_E]
        FROM [Tickets].[TicketStatus]
        WHERE [ticketStatusActive] = 1
        ORDER BY [ticketStatusID];

        RETURN;
    END

    IF @pageName_ = N'ChildTickets'
    BEGIN
        SELECT
              ct.[ticketID]
            , ct.[ticketNo]
            , COALESCE(ct.[title_A], ct.[title]) AS [title]
            , ts.[ticketStatusCode]
            , COALESCE(ts.[ticketStatusName_A], ts.[ticketStatusName_E]) AS [ticketStatusName_E]
            , ts.[ticketStatusName_A]
            , COALESCE(p.[priorityName_A], p.[priorityName_E]) AS [priorityName_E]
            , ct.[entryDate]
        FROM [Tickets].[Ticket] ct
        LEFT JOIN [Tickets].[TicketStatus] ts ON ct.[ticketStatusID_FK] = ts.[ticketStatusID]
        LEFT JOIN [Tickets].[Priority] p ON ct.[effectivePriorityID_FK] = p.[priorityID]
        WHERE ct.[parentTicketID_FK] = @filterTicketID
          AND ct.[ticketActive] = 1
        ORDER BY ct.[ticketID] DESC;

        RETURN;
    END

    IF @pageName_ = N'PauseSessions'
    BEGIN
        SELECT
              ps.[ticketPauseSessionID]
            , ps.[ticketID_FK]
            , pr.[pauseReasonName_A]
            , pr.[pauseReasonName_E]
            , ps.[relatedChildTicketID_FK]
            , ps.[relatedArbitrationCaseID_FK]
            , ps.[relatedClarificationRequestID_FK]
            , ps.[pauseStart]
            , ps.[pauseEnd]
            , ps.[slaPauseFlag]
            , COALESCE(ps.[pauseNotes_A], ps.[pauseNotes]) AS [pauseNotes]
            , ps.[ticketPauseSessionActive]
        FROM [Tickets].[TicketPauseSession] ps
        LEFT JOIN [Tickets].[PauseReason] pr ON ps.[pauseReasonID_FK] = pr.[pauseReasonID]
        WHERE ps.[ticketID_FK] = @filterTicketID
        ORDER BY ps.[ticketPauseSessionID] DESC;

        RETURN;
    END

    IF @pageName_ = N'TicketSLAs'
    BEGIN
        SELECT
              sla.[ticketSLAID]
            , sla.[ticketID_FK]
            , sla.[slaTypeCode]
            , sla.[targetMinutes]
            , sla.[elapsedMinutes]
            , sla.[remainingMinutes]
            , sla.[isBreached]
            , sla.[slaStartDate]
            , sla.[slaStopDate]
            , sla.[slaCompletionDate]
            , sla.[ticketSLAActive]
        FROM [Tickets].[TicketSLA] sla
        WHERE sla.[ticketID_FK] = @filterTicketID
          AND sla.[ticketSLAActive] = 1
        ORDER BY sla.[ticketSLAID];

        RETURN;
    END

    IF @pageName_ = N'QualityReviews'
    BEGIN
        SELECT
              qr.[qualityReviewID]
            , qr.[ticketID_FK]
            , qr.[reviewerUserID]
            , qr.[reviewScope]
            , qr.[qualityReviewResultID_FK]
            , qrr.[qualityReviewResultCode]
            , qrr.[qualityReviewResultName_A]
            , qrr.[qualityReviewResultName_E]
            , qr.[reviewNotes]
            , qr.[returnToUserID]
            , qr.[finalized]
            , qr.[entryDate]
        FROM [Tickets].[QualityReview] qr
        LEFT JOIN [Tickets].[QualityReviewResult] qrr ON qr.[qualityReviewResultID_FK] = qrr.[qualityReviewResultID]
        WHERE qr.[ticketID_FK] = @filterTicketID
          AND qr.[qualityReviewActive] = 1
        ORDER BY qr.[qualityReviewID] DESC;

        RETURN;
    END

    IF @pageName_ = N'ArbitrationCases'
    BEGIN
        SELECT
              ac.[arbitrationCaseID]
            , ac.[ticketID_FK]
            , ac.[raisedByUserID]
            , ac.[raisedFromDSDID_FK]
            , ar.[arbitrationReasonName_A]
            , ar.[arbitrationReasonName_E]
            , ac.[arbitratorDistributorID]
            , ac.[arbitrationStatus]
            , ac.[decisionType]
            , ac.[decisionTargetDSDID_FK]
            , ac.[decisionNotes]
            , ac.[decisionDate]
            , ac.[entryDate]
        FROM [Tickets].[ArbitrationCase] ac
        LEFT JOIN [Tickets].[ArbitrationReason] ar ON ac.[arbitrationReasonID_FK] = ar.[arbitrationReasonID]
        WHERE ac.[ticketID_FK] = @filterTicketID
          AND ac.[arbitrationCaseActive] = 1
        ORDER BY ac.[arbitrationCaseID] DESC;

        RETURN;
    END

    IF @pageName_ = N'TicketAttachments'
    BEGIN
        SELECT
              ta.[ticketAttachmentID]
            , ta.[ticketID_FK]
            , ta.[fileName]
            , ta.[storedFileName]
            , ta.[filePath]
            , ta.[fileSizeBytes]
            , ta.[contentType]
            , ta.[uploadedByUserID]
            , ta.[attachmentType]
            , ta.[entryDate]
        FROM [Tickets].[TicketAttachment] ta
        WHERE ta.[ticketID_FK] = @filterTicketID
          AND ta.[ticketAttachmentActive] = 1
        ORDER BY ta.[ticketAttachmentID] DESC;

        RETURN;
    END

    IF @pageName_ = N'PauseReasonDDL'
    BEGIN
        SELECT [pauseReasonID], [pauseReasonCode], [pauseReasonName_A], [pauseReasonName_E]
        FROM [Tickets].[PauseReason]
        WHERE [pauseReasonActive] = 1
        ORDER BY [pauseReasonID];

        RETURN;
    END

    IF @pageName_ = N'ArbitrationReasonDDL'
    BEGIN
        SELECT [arbitrationReasonID], [arbitrationReasonCode], [arbitrationReasonName_A], [arbitrationReasonName_E]
        FROM [Tickets].[ArbitrationReason]
        WHERE [arbitrationReasonActive] = 1
        ORDER BY [arbitrationReasonID];

        RETURN;
    END

    IF @pageName_ = N'QualityReviewResultDDL'
    BEGIN
        SELECT [qualityReviewResultID], [qualityReviewResultCode], [qualityReviewResultName_A], [qualityReviewResultName_E]
        FROM [Tickets].[QualityReviewResult]
        WHERE [qualityReviewResultActive] = 1
        ORDER BY [qualityReviewResultID];

        RETURN;
    END

    IF @pageName_ = N'RequesterTypeDDL'
    BEGIN
        SELECT [requesterTypeID], [requesterTypeCode], [requesterTypeName_A], [requesterTypeName_E]
        FROM [Tickets].[RequesterType]
        WHERE [requesterTypeActive] = 1
        ORDER BY [requesterTypeID];

        RETURN;
    END

    IF @pageName_ = N'TicketClassDDL'
    BEGIN
        SELECT [ticketClassID], [ticketClassCode], [ticketClassName_A], [ticketClassName_E]
        FROM [Tickets].[TicketClass]
        WHERE [ticketClassActive] = 1
        ORDER BY [ticketClassID];

        RETURN;
    END

    IF @pageName_ = N'ClarificationReasonDDL'
    BEGIN
        SELECT [clarificationReasonID], [clarificationReasonCode], [clarificationReasonName_A], [clarificationReasonName_E]
        FROM [Tickets].[ClarificationReason]
        WHERE [clarificationReasonActive] = 1
        ORDER BY [clarificationReasonID];

        RETURN;
    END

    IF @pageName_ = N'PriorityDDL'
    BEGIN
        SELECT [priorityID], [priorityCode], [priorityName_A], [priorityName_E]
        FROM [Tickets].[Priority]
        WHERE [priorityActive] = 1
        ORDER BY [priorityID];

        RETURN;
    END

    IF @pageName_ = N'OpenArbitrations'
    BEGIN
        SELECT
              ac.[arbitrationCaseID]
            , ac.[ticketID_FK]
            , t.[ticketNo]
            , COALESCE(t.[title_A], t.[title]) AS [title]
            , COALESCE(ar.[arbitrationReasonName_A], ar.[arbitrationReasonName_E]) AS [arbitrationReasonName_E]
            , ac.[arbitrationStatus]
            , ac.[entryDate]
        FROM [Tickets].[ArbitrationCase] ac
        INNER JOIN [Tickets].[Ticket] t ON ac.[ticketID_FK] = t.[ticketID]
        LEFT JOIN [Tickets].[ArbitrationReason] ar ON ac.[arbitrationReasonID_FK] = ar.[arbitrationReasonID]
        WHERE ac.[arbitrationStatus] = N'OPEN'
          AND ac.[arbitrationCaseActive] = 1
          AND (ac.[idaraID_FK] = @idaraID OR @idaraID IS NULL)
        ORDER BY ac.[arbitrationCaseID] DESC;

        RETURN;
    END

    IF @pageName_ = N'PendingReviews'
    BEGIN
        SELECT
              qr.[qualityReviewID]
            , qr.[ticketID_FK]
            , t.[ticketNo]
            , COALESCE(t.[title_A], t.[title]) AS [title]
            , qr.[reviewScope]
            , qr.[entryDate]
        FROM [Tickets].[QualityReview] qr
        INNER JOIN [Tickets].[Ticket] t ON qr.[ticketID_FK] = t.[ticketID]
        WHERE qr.[finalized] = 0
          AND qr.[qualityReviewActive] = 1
          AND (qr.[idaraID_FK] = @idaraID OR @idaraID IS NULL)
        ORDER BY qr.[qualityReviewID] DESC;

        RETURN;
    END

    IF @pageName_ = N'BreachedSLAs'
    BEGIN
        SELECT
              sla.[ticketSLAID]
            , sla.[ticketID_FK]
            , t.[ticketNo]
            , COALESCE(t.[title_A], t.[title]) AS [title]
            , sla.[slaTypeCode]
            , sla.[targetMinutes]
            , sla.[elapsedMinutes]
            , sla.[isBreached]
            , sla.[slaStartDate]
        FROM [Tickets].[TicketSLA] sla
        INNER JOIN [Tickets].[Ticket] t ON sla.[ticketID_FK] = t.[ticketID]
        WHERE sla.[isBreached] = 1
          AND sla.[ticketSLAActive] = 1
          AND (sla.[idaraID_FK] = @idaraID OR @idaraID IS NULL)
        ORDER BY sla.[ticketSLAID] DESC;

        RETURN;
    END

    IF @pageName_ = N'TicketAdminLookup'
    BEGIN
        SELECT [ticketStatusID], [ticketStatusCode], [ticketStatusName_A], [ticketStatusName_E], [ticketStatusDesc], [ticketStatusActive], [entryDate]
        FROM [Tickets].[TicketStatus] ORDER BY [ticketStatusID];

        SELECT [pauseReasonID], [pauseReasonCode], [pauseReasonName_A], [pauseReasonName_E], [pauseReasonDesc], [pauseReasonActive], [entryDate]
        FROM [Tickets].[PauseReason] ORDER BY [pauseReasonID];

        SELECT [arbitrationReasonID], [arbitrationReasonCode], [arbitrationReasonName_A], [arbitrationReasonName_E], [arbitrationReasonDesc], [arbitrationReasonActive], [entryDate]
        FROM [Tickets].[ArbitrationReason] ORDER BY [arbitrationReasonID];

        SELECT [qualityReviewResultID], [qualityReviewResultCode], [qualityReviewResultName_A], [qualityReviewResultName_E], [qualityReviewResultDesc], [qualityReviewResultActive], [entryDate]
        FROM [Tickets].[QualityReviewResult] ORDER BY [qualityReviewResultID];

        SELECT [ticketClassID], [ticketClassCode], [ticketClassName_A], [ticketClassName_E], [ticketClassDesc], [ticketClassActive], [entryDate]
        FROM [Tickets].[TicketClass] ORDER BY [ticketClassID];

        SELECT [priorityID], [priorityCode], [priorityName_A], [priorityName_E], [priorityDesc], [priorityLevel], [priorityActive], [entryDate]
        FROM [Tickets].[Priority] ORDER BY [priorityLevel], [priorityID];

        RETURN;
    END

    IF @pageName_ = N'ResidentDDL'
    BEGIN
      ;WITH ResidentHousing AS
      (
        SELECT
          r.[residentInfoID] AS [residentInfoID],
          r.[NationalID] AS [NationalID],
          r.[generalNo_FK] AS [generalNo_FK],
          r.[FullName_A] AS [ResidentName_A],
          r.[FullName_E] AS [FullName_E],
          r.[rankNameA] AS [rankNameA],
          r.[militaryUnitName_A] AS [militaryUnitName_A],
                CASE
                    WHEN ba.[BuildingNo] IS NULL
                      OR LTRIM(RTRIM(CONVERT(NVARCHAR(100), ba.[BuildingNo]))) = N''
                      OR CONVERT(NVARCHAR(100), ba.[BuildingNo]) = N'No_house'
                    THEN N'بدون سكن'
                    ELSE CONVERT(NVARCHAR(100), ba.[BuildingNo])
                END AS [BuildingNo],
          ROW_NUMBER() OVER
          (
            PARTITION BY r.[residentInfoID]
            ORDER BY
              CASE
                WHEN ba.[BuildingNo] IS NULL
                  OR LTRIM(RTRIM(CONVERT(NVARCHAR(100), ba.[BuildingNo]))) = N''
                  OR CONVERT(NVARCHAR(100), ba.[BuildingNo]) = N'No_house'
                THEN 1 ELSE 0
              END,
              ba.[BuildingAssignDate] DESC,
              ba.[BuildingAssignID] DESC
          ) AS [rn]
        FROM [Housing].[V_GetFullResidentDetails] r
        INNER JOIN [DATACORE].[Housing].[BuildingAssign] ba
          ON r.[generalNo_FK] = ba.[GeneralNo]
        INNER JOIN [DATACORE].[Housing].[BuildingAssignStatus] bas
          ON ba.[BuildingAssignStatusID_FK] = bas.[BuildingAssignStatusID]
        WHERE r.[IdaraID] = @idaraID
          AND bas.[Active] = 1
      )
      SELECT
        rh.[residentInfoID] AS [residentInfoID],
        rh.[NationalID] AS [NationalID],
        rh.[generalNo_FK] AS [generalNo_FK],
        rh.[ResidentName_A] AS [ResidentName_A],
        rh.[ResidentName_A]
          + N' | هوية: '
          + COALESCE(NULLIF(rh.[NationalID], N''), CONVERT(NVARCHAR(50), rh.[generalNo_FK]), N'-')
          + N' | السكن: '
          + COALESCE(NULLIF(rh.[BuildingNo], N''), N'بدون سكن') AS [FullName_A],
        rh.[ResidentName_A]
          + N' | هوية: '
          + COALESCE(NULLIF(rh.[NationalID], N''), CONVERT(NVARCHAR(50), rh.[generalNo_FK]), N'-')
          + N' | السكن: '
          + COALESCE(NULLIF(rh.[BuildingNo], N''), N'بدون سكن') AS [ResidentDisplay],
        rh.[FullName_E] AS [FullName_E],
        rh.[rankNameA] AS [rankNameA],
        rh.[militaryUnitName_A] AS [militaryUnitName_A],
        rh.[BuildingNo] AS [BuildingNo]
      FROM ResidentHousing rh
      WHERE rh.[rn] = 1
      ORDER BY rh.[ResidentName_A] ASC;

        RETURN;
    END

    IF @pageName_ = N'BuildingDDL'
    BEGIN
        SELECT
            bd.[buildingDetailsID] AS [buildingDetailsID],
            bd.[buildingDetailsNo] AS [buildingDetailsNo],
            bd.[buildingDetailsRooms] AS [buildingDetailsRooms],
            bt.[buildingTypeName_A] AS [buildingTypeName_A],
            m.[militaryLocationName_A] AS [militaryLocationName_A],
            bc.[buildingClassName_A] AS [buildingClassName_A]
        FROM [DATACORE].[Housing].[BuildingDetails] bd
        INNER JOIN [DATACORE].[Housing].[BuildingType] bt ON bd.[buildingTypeID_FK] = bt.[buildingTypeID]
        INNER JOIN [DATACORE].[Housing].[MilitaryLocation] m ON bd.[militaryLocationID_FK] = m.[militaryLocationID]
        INNER JOIN [DATACORE].[Housing].[BuildingClass] bc ON bd.[buildingClassID_FK] = bc.[buildingClassID]
        WHERE bd.[buildingDetailsActive] = 1
          AND bd.[IdaraId_FK] = @idaraID
          AND bt.[buildingTypeActive] = 1
          AND m.[militaryLocationActive] = 1
          AND bc.[buildingClassActive] = 1
        ORDER BY bd.[buildingDetailsNo] ASC;

        RETURN;
    END

    IF @pageName_ = N'TicketReasonDDL'
    BEGIN
        SELECT
            [ticketReasonID],
            [ticketReasonCode],
            [ticketReasonName_A],
            [ticketReasonName_E],
            [priorityID_FK]
            , [serviceID_FK]
        FROM [Tickets].[TicketReason]
        WHERE [ticketReasonActive] = 1
          AND ([idaraID_FK] = @idaraID OR [idaraID_FK] IS NULL)
        ORDER BY [displayOrder] ASC, [ticketReasonID] ASC;

        RETURN;
    END

    IF @pageName_ = N'TicketDescriptionTemplateDDL'
    BEGIN
        SELECT
            [templateID],
            [templateCode],
            [templateName_A],
            [templateName_E],
            [templateContent_A]
            , [serviceID_FK]
        FROM [Tickets].[TicketDescriptionTemplate]
        WHERE [templateActive] = 1
          AND ([idaraID_FK] = @idaraID OR [idaraID_FK] IS NULL)
        ORDER BY [displayOrder] ASC, [templateID] ASC;

        RETURN;
    END

    IF @pageName_ = N'DSDDL'
    BEGIN
        SELECT
              f.[DSDID]
            , COALESCE(
                NULLIF(
                    LTRIM(RTRIM(
                        COALESCE(f.[DepartmentName], N'')
                        + CASE WHEN f.[SectionName]  IS NOT NULL THEN N' / ' + f.[SectionName]  ELSE N'' END
                        + CASE WHEN f.[DivisonName]  IS NOT NULL THEN N' / ' + f.[DivisonName]  ELSE N'' END
                    )), N''),
                f.[IdaraName],
                CAST(f.[DSDID] AS NVARCHAR(20))
              ) AS [dsdName_A]
        FROM dbo.V_GetFullStructureForDSD f
        WHERE f.[IdaraID] = @idaraID
        ORDER BY f.[DepartmentName], f.[SectionName], f.[DivisonName];

        RETURN;
    END

    -- Returns active users whose DSD membership matches the given DSDID (@parameter_01).
    -- Used by the Assign Ticket modal to show only staff in the ticket's current department.
    IF @pageName_ = N'DsdUsersDDL'
    BEGIN
        SELECT
              v.[usersID]
            , v.[FullName] AS [fullName_A]
        FROM dbo.V_GetListUsersInDSD v
        WHERE v.[DSDID] = TRY_CAST(@filterDSDID AS BIGINT)
        ORDER BY v.[FullName];

        RETURN;
    END

    -- Returns all active users with their DSDID for client-side filtering via DDLFiltered.
    -- Used by the Assign Ticket modal with DependsOn pattern.
    -- TableIndex 0 in Masters_DataLoad maps to this result.
    IF @pageName_ = N'DsdUsersAllDDL'
    BEGIN
        SELECT
              v.[usersID]
            , v.[FullName] AS [fullName_A]
            , v.[DSDID]
        FROM dbo.V_GetListUsersInDSD v
        ORDER BY v.[FullName];

        RETURN;
    END
END





GO
/****** Object:  StoredProcedure [Tickets].[TicketSP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
CREATE   PROCEDURE [Tickets].[TicketSP]
(
      @Action                      NVARCHAR(200)
    , @ticketID                    BIGINT          = NULL
    , @parentTicketID_FK           BIGINT          = NULL
    , @serviceID_FK                BIGINT          = NULL
    , @ticketClassID_FK            INT             = NULL
    , @requesterTypeID_FK          INT             = NULL
    , @requesterUserID_FK          INT             = NULL
    , @requesterResidentID_FK      BIGINT          = NULL
    , @title_A                     NVARCHAR(500)   = NULL
    , @title                       NVARCHAR(500)   = NULL
    , @description_A               NVARCHAR(4000)  = NULL
    , @description_                NVARCHAR(4000)  = NULL
    , @suggestedPriorityID_FK      INT             = NULL
    , @ticketStatusID_FK           INT             = NULL
    , @currentDSDID_FK             INT             = NULL
    , @currentQueueDistributorID_FK INT            = NULL
    , @assignedUserID_FK           INT             = NULL
    , @locationBuildingNo          NVARCHAR(100)   = NULL
    , @locationUnitNo              NVARCHAR(50)    = NULL
    , @locationArea_A              NVARCHAR(200)   = NULL
    , @locationArea                NVARCHAR(200)   = NULL
    , @requiresQualityReview       BIT             = NULL
    , @isOtherService              BIT             = NULL
    , @idaraID_FK                  INT             = NULL
    , @entryData                   NVARCHAR(20)    = NULL
    , @hostName                    NVARCHAR(200)   = NULL
    , @notes_A                     NVARCHAR(4000)  = NULL
    , @notes                       NVARCHAR(4000)  = NULL
    , @pauseNotes_A                NVARCHAR(2000)  = NULL
    , @pauseReasonID_FK            INT             = NULL
    , @reviewScope                 NVARCHAR(100)   = NULL
    , @qualityReviewResultID_FK    INT             = NULL
    , @reviewNotes                 NVARCHAR(4000)  = NULL
    , @returnToUserID              INT             = NULL
    , @arbitrationReasonID_FK      INT             = NULL
    , @arbitratorDistributorID     INT             = NULL
    , @decisionType                NVARCHAR(50)    = NULL
    , @decisionTargetDSDID_FK      INT             = NULL
    , @decisionNotes               NVARCHAR(4000)  = NULL
    , @arbitrationCaseID           BIGINT          = NULL
    , @fileName                    NVARCHAR(500)   = NULL
    , @storedFileName              NVARCHAR(500)   = NULL
    , @filePath                    NVARCHAR(1000)  = NULL
    , @fileSizeBytes               BIGINT          = NULL
    , @contentType                 NVARCHAR(200)   = NULL
    , @attachmentType              NVARCHAR(50)    = NULL
    , @performerUserID             INT             = NULL
    , @clarificationRequestID       BIGINT          = NULL
    , @clarificationReasonID_FK     INT             = NULL
    , @requestedFromUserID          INT             = NULL
    , @requestedFromDSDID_FK        INT             = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;
    DECLARE @NewID BIGINT = NULL;
    DECLARE @Note NVARCHAR(MAX) = NULL;
    DECLARE @NewTicketNo NVARCHAR(50) = NULL;
    DECLARE @titleToSave NVARCHAR(500) = COALESCE(@title_A, @title);
    DECLARE @descriptionToSave NVARCHAR(4000) = COALESCE(@description_A, @description_);
    DECLARE @locationAreaToSave NVARCHAR(200) = COALESCE(@locationArea_A, @locationArea);
    DECLARE @notesToSave NVARCHAR(4000) = COALESCE(@notes_A, @notes);
    DECLARE @pauseNotesToSave NVARCHAR(2000) = COALESCE(@pauseNotes_A, @notes_A, @notes);
    DECLARE @ParentTicketToUpdate BIGINT = NULL;
    DECLARE @RemainingOpenChildren INT = 0;
    DECLARE @ParentCurrentStatus INT = NULL;
    DECLARE @PausedStatusID INT = NULL;
    DECLARE @ResumeStatusID INT = NULL;

    BEGIN TRY
        IF @tc = 0 BEGIN TRAN;

        IF NULLIF(LTRIM(RTRIM(@Action)), N'') IS NULL
        BEGIN ;THROW 50001, N'نوع الإجراء مطلوب', 1; END

        ----------------------------------------------------------------
        -- INSERT_TICKET
        ----------------------------------------------------------------
        IF @Action = N'INSERT_TICKET'
        BEGIN
          IF NULLIF(LTRIM(RTRIM(@titleToSave)), N'') IS NULL
            BEGIN ;THROW 50001, N'عنوان التذكرة مطلوب', 1; END

            IF @idaraID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف الإدارة مطلوب', 1; END

            IF @ticketClassID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف فئة التذكرة مطلوب', 1; END

            IF @requesterTypeID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف نوع مقدم الطلب مطلوب', 1; END

            DECLARE @reqCode NVARCHAR(50);
            SELECT @reqCode = [requesterTypeCode]
            FROM [Tickets].[RequesterType]
            WHERE [requesterTypeID] = @requesterTypeID_FK;

            IF @reqCode = N'RESIDENT'
            BEGIN
                IF @requesterResidentID_FK IS NULL
                BEGIN ;THROW 50001, N'تذاكر السكان تتطلب معرف ساكن لمقدم الطلب', 1; END
                IF @requesterUserID_FK IS NOT NULL
                BEGIN ;THROW 50001, N'تذاكر السكان يجب ألا تحتوي على معرف مستخدم لمقدم الطلب', 1; END
            END
            ELSE IF @reqCode IN (N'INTERNAL', N'SUPERVISOR', N'MANAGER')
            BEGIN
                IF @requesterUserID_FK IS NULL
                BEGIN ;THROW 50001, N'التذاكر الداخلية تتطلب معرف مستخدم لمقدم الطلب', 1; END
                IF @requesterResidentID_FK IS NOT NULL
                BEGIN ;THROW 50001, N'التذاكر الداخلية يجب ألا تحتوي على معرف ساكن لمقدم الطلب', 1; END
            END

            IF @isOtherService IS NULL OR @isOtherService = 0
            BEGIN
                IF @serviceID_FK IS NULL
                BEGIN ;THROW 50001, N'معرف الخدمة مطلوب للتذاكر غير المصنفة كأخرى', 1; END
            END

            DECLARE @yr NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()));
            DECLARE @seq INT;
            SELECT @seq = ISNULL(MAX(CAST(RIGHT([ticketNo], 5) AS INT)), 0) + 1
            FROM [Tickets].[Ticket]
            WHERE [ticketNo] LIKE N'TKT-' + @yr + N'-%';

            SET @NewTicketNo = N'TKT-' + @yr + N'-' + RIGHT(N'00000' + CAST(@seq AS NVARCHAR(10)), 5);

            DECLARE @statusNewID INT;
            SELECT @statusNewID = [ticketStatusID]
            FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'NEW' AND [ticketStatusActive] = 1;

            IF @statusNewID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة NEW في جدول حالات التذاكر', 1; END

            DECLARE @svcDSDID INT = @currentDSDID_FK;
            DECLARE @svcRequiresQR BIT = ISNULL(@requiresQualityReview, 0);

            IF @serviceID_FK IS NOT NULL
            BEGIN
                SELECT @svcRequiresQR = ISNULL(@svcRequiresQR, ISNULL(s.[requiresQualityReview], 0))
                FROM [Tickets].[Service] s
                WHERE s.[serviceID] = @serviceID_FK AND s.[serviceActive] = 1;
            END

            DECLARE @effectivePriorityID INT = @suggestedPriorityID_FK;
            IF @effectivePriorityID IS NULL AND @serviceID_FK IS NOT NULL
            BEGIN
                SELECT @effectivePriorityID = s.[defaultPriorityID_FK]
                FROM [Tickets].[Service] s
                WHERE s.[serviceID] = @serviceID_FK;
            END

            IF @parentTicketID_FK IS NOT NULL AND @parentTicketID_FK > 0
            BEGIN
                ;THROW 50001, N'استخدم CREATE_CHILD_TICKET لإنشاء التذاكر الفرعية', 1;
            END

            SET @parentTicketID_FK = NULL;

            INSERT INTO [Tickets].[Ticket]
            (
                  [ticketNo], [idaraID_FK], [parentTicketID_FK], [rootTicketID_FK]
                , [serviceID_FK], [ticketClassID_FK], [requesterTypeID_FK]
                , [requesterUserID_FK], [requesterResidentID_FK]
                , [title], [title_A], [description_], [description_A]
                , [suggestedPriorityID_FK], [effectivePriorityID_FK], [ticketStatusID_FK]
                , [currentDSDID_FK], [currentQueueDistributorID_FK], [assignedUserID_FK]
                , [locationBuildingNo], [locationUnitNo], [locationArea], [locationArea_A]
                , [operationalResolutionDate], [finalClosureDate]
                , [requiresQualityReview], [isOtherService], [isParentBlocked], [ticketActive]
                , [entryData], [hostName]
            )
            VALUES
            (
                  @NewTicketNo, @idaraID_FK, @parentTicketID_FK, NULL
                , @serviceID_FK, @ticketClassID_FK, @requesterTypeID_FK
                , @requesterUserID_FK, @requesterResidentID_FK
                , @titleToSave, @titleToSave, @descriptionToSave, @descriptionToSave
                , @suggestedPriorityID_FK, @effectivePriorityID, @statusNewID
                , @svcDSDID, @currentQueueDistributorID_FK, @assignedUserID_FK
                , @locationBuildingNo, @locationUnitNo, @locationAreaToSave, @locationAreaToSave
                , NULL, NULL
                , @svcRequiresQR, ISNULL(@isOtherService, 0), 0, 1
                , @entryData, @hostName
            );

            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN ;THROW 50002, N'فشل إنشاء التذكرة بسبب خطأ في توليد المعرف', 1; END

            UPDATE [Tickets].[Ticket]
            SET [rootTicketID_FK] = @NewID
            WHERE [ticketID] = @NewID AND [rootTicketID_FK] IS NULL;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @NewID, @idaraID_FK, N'CREATED', NULL, @statusNewID
            , NULL, @svcDSDID, NULL, NULL
            , @requesterUserID_FK, N'تم إنشاء التذكرة', COALESCE(@notes_A, N'تم إنشاء التذكرة'), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@NewID AS NVARCHAR(20))
                + N'","ticketNo":"' + ISNULL(@NewTicketNo, N'') + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'INSERT_TICKET', @NewID, @entryData, @Note);

            SELECT 1 AS IsSuccessful
                 , N'تم إنشاء التذكرة بنجاح: ' + @NewTicketNo AS Message_;
        END

        ----------------------------------------------------------------
        -- ROUTE_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'ROUTE_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END

            DECLARE @rtOldStatus INT, @rtOldDSD INT;
            SELECT @rtOldStatus = [ticketStatusID_FK], @rtOldDSD = [currentDSDID_FK]
            FROM [Tickets].[Ticket] WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @rtOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            DECLARE @statusRoutedID INT;
            SELECT @statusRoutedID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'ROUTED' AND [ticketStatusActive] = 1;

            IF @statusRoutedID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة ROUTED', 1; END

            IF @rtOldStatus NOT IN (
                SELECT [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] IN (N'NEW', N'REOPENED') AND [ticketStatusActive] = 1
            )
            BEGIN ;THROW 50001, N'لا يمكن توجيه التذكرة من حالتها الحالية', 1; END

            DECLARE @routeDSDID INT = @currentDSDID_FK;
            DECLARE @routeQDID INT = @currentQueueDistributorID_FK;

            IF @routeDSDID IS NULL AND @serviceID_FK IS NOT NULL
            BEGIN
                SELECT TOP 1 @routeDSDID = rr.[targetDSDID_FK], @routeQDID = ISNULL(@routeQDID, rr.[queueDistributorID_FK])
                FROM [Tickets].[ServiceRoutingRule] rr
                WHERE rr.[serviceID_FK] = @serviceID_FK
                  AND rr.[serviceRoutingRuleActive] = 1
                  AND rr.[effectiveFrom] <= GETDATE()
                  AND (rr.[effectiveTo] IS NULL OR rr.[effectiveTo] > GETDATE())
                ORDER BY rr.[serviceRoutingRuleID] DESC;
            END

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @statusRoutedID
              , [currentDSDID_FK] = @routeDSDID
              , [currentQueueDistributorID_FK] = @routeQDID
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'ROUTED', @rtOldStatus, @statusRoutedID
            , @rtOldDSD, @routeDSDID, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم توجيه التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تم توجيه التذكرة')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'ROUTE_TICKET', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم توجيه التذكرة بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- ASSIGN_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'ASSIGN_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END
            IF @assignedUserID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف المستخدم المعيّن مطلوب', 1; END

          DECLARE @asOldStatus INT, @asOldAssigned INT;
          DECLARE @asCurrentQueueDistributorID BIGINT, @asCurrentDSDID BIGINT;
          SELECT @asOldStatus = [ticketStatusID_FK]
             , @asOldAssigned = [assignedUserID_FK]
             , @asCurrentQueueDistributorID = [currentQueueDistributorID_FK]
             , @asCurrentDSDID = [currentDSDID_FK]
            FROM [Tickets].[Ticket] WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @asOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

          IF @asCurrentQueueDistributorID IS NULL AND @asCurrentDSDID IS NULL
          BEGIN ;THROW 50001, N'لا يمكن إسناد التذكرة بدون مسار توزيع أو هيكل تنظيمي حالي', 1; END

          IF NOT EXISTS (
            SELECT 1
            FROM dbo.[UserDistributor] ud
            INNER JOIN dbo.[Distributor] d
              ON d.[distributorID] = ud.[distributorID_FK]
            WHERE ud.[userID_FK] = @assignedUserID_FK
              AND ISNULL(ud.[UDActive], 1) = 1
              AND (ud.[UDStartDate] IS NULL OR CAST(ud.[UDStartDate] AS date) <= CAST(GETDATE() AS date))
              AND (ud.[UDEndDate] IS NULL OR CAST(ud.[UDEndDate] AS date) >= CAST(GETDATE() AS date))
              AND ISNULL(d.[distributorActive], 1) = 1
              AND (
                (@asCurrentQueueDistributorID IS NOT NULL AND ud.[distributorID_FK] = @asCurrentQueueDistributorID)
               OR (@asCurrentDSDID IS NOT NULL AND d.[DSDID_FK] = @asCurrentDSDID)
              )
          )
          BEGIN ;THROW 50001, N'المستخدم المحدد غير مؤهل لاستلام التذكرة في المسار الحالي', 1; END

            DECLARE @statusAssignedID INT;
            SELECT @statusAssignedID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'ASSIGNED' AND [ticketStatusActive] = 1;

            IF @statusAssignedID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة ASSIGNED', 1; END

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @statusAssignedID
              , [assignedUserID_FK] = @assignedUserID_FK
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'ASSIGNED', @asOldStatus, @statusAssignedID
            , NULL, NULL, @asOldAssigned, @assignedUserID_FK
            , @performerUserID, ISNULL(@notes, N'تم إسناد التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تم إسناد التذكرة')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","assignedUserID":"' + CAST(@assignedUserID_FK AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'ASSIGN_TICKET', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إسناد التذكرة بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- REASSIGN_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'REASSIGN_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END
            IF @assignedUserID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف المستخدم الجديد المعيّن مطلوب', 1; END

          DECLARE @raOldStatus INT, @raOldAssigned INT, @raOldDSD BIGINT;
          DECLARE @raCurrentQueueDistributorID BIGINT, @raTargetDSDID BIGINT;
          SELECT @raOldStatus = [ticketStatusID_FK]
             , @raOldAssigned = [assignedUserID_FK]
             , @raOldDSD = [currentDSDID_FK]
             , @raCurrentQueueDistributorID = [currentQueueDistributorID_FK]
            FROM [Tickets].[Ticket] WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @raOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

          SET @raTargetDSDID = ISNULL(@currentDSDID_FK, @raOldDSD);

          IF @raCurrentQueueDistributorID IS NULL AND @raTargetDSDID IS NULL
          BEGIN ;THROW 50001, N'لا يمكن إعادة إسناد التذكرة بدون مسار توزيع أو هيكل تنظيمي حالي', 1; END

          IF NOT EXISTS (
            SELECT 1
            FROM dbo.[UserDistributor] ud
            INNER JOIN dbo.[Distributor] d
              ON d.[distributorID] = ud.[distributorID_FK]
            WHERE ud.[userID_FK] = @assignedUserID_FK
              AND ISNULL(ud.[UDActive], 1) = 1
              AND (ud.[UDStartDate] IS NULL OR CAST(ud.[UDStartDate] AS date) <= CAST(GETDATE() AS date))
              AND (ud.[UDEndDate] IS NULL OR CAST(ud.[UDEndDate] AS date) >= CAST(GETDATE() AS date))
              AND ISNULL(d.[distributorActive], 1) = 1
              AND (
                (@currentDSDID_FK IS NOT NULL AND d.[DSDID_FK] = @raTargetDSDID)
               OR (
                  @currentDSDID_FK IS NULL
                AND (
                    (@raCurrentQueueDistributorID IS NOT NULL AND ud.[distributorID_FK] = @raCurrentQueueDistributorID)
                   OR (@raTargetDSDID IS NOT NULL AND d.[DSDID_FK] = @raTargetDSDID)
                )
               )
              )
          )
          BEGIN ;THROW 50001, N'المستخدم المحدد غير مؤهل لاستلام التذكرة في المسار المستهدف', 1; END

            UPDATE [Tickets].[Ticket]
            SET [assignedUserID_FK] = @assignedUserID_FK
              , [currentDSDID_FK] = ISNULL(@currentDSDID_FK, [currentDSDID_FK])
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'REASSIGNED', @raOldStatus, @raOldStatus
            , @raOldDSD, ISNULL(@currentDSDID_FK, @raOldDSD), @raOldAssigned, @assignedUserID_FK
            , @performerUserID, ISNULL(@notes, N'تمت إعادة إسناد التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تمت إعادة إسناد التذكرة')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","newAssignedUserID":"' + CAST(@assignedUserID_FK AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'REASSIGN_TICKET', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إعادة إسناد التذكرة بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- UPDATE_PRIORITY
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPDATE_PRIORITY'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END
            IF @suggestedPriorityID_FK IS NULL
            BEGIN ;THROW 50001, N'الأولوية الجديدة مطلوبة', 1; END

            DECLARE @upOldStatus INT, @upOldSuggestedPriority INT, @upOldEffectivePriority INT;
            SELECT
                  @upOldStatus = [ticketStatusID_FK]
                , @upOldSuggestedPriority = [suggestedPriorityID_FK]
                , @upOldEffectivePriority = [effectivePriorityID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID
              AND [ticketActive] = 1;

            IF @upOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            IF @upOldStatus IN
            (
                SELECT [ticketStatusID]
                FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] IN (N'CLOSED', N'REJECTED')
                  AND [ticketStatusActive] = 1
            )
            BEGIN ;THROW 50001, N'لا يمكن تعديل أولوية التذكرة في حالتها الحالية', 1; END

            IF NOT EXISTS
            (
                SELECT 1
                FROM [Tickets].[Priority]
                WHERE [priorityID] = @suggestedPriorityID_FK
                  AND [priorityActive] = 1
            )
            BEGIN ;THROW 50001, N'الأولوية المحددة غير صالحة أو غير نشطة', 1; END

            UPDATE [Tickets].[Ticket]
            SET [suggestedPriorityID_FK] = @suggestedPriorityID_FK
              , [effectivePriorityID_FK] = @suggestedPriorityID_FK
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'UPDATE_PRIORITY', @upOldStatus, @upOldStatus
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم تعديل أولوية التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تم تعديل أولوية التذكرة')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","oldSuggestedPriorityID":"' + COALESCE(CAST(@upOldSuggestedPriority AS NVARCHAR(20)), N'')
                + N'","oldEffectivePriorityID":"' + COALESCE(CAST(@upOldEffectivePriority AS NVARCHAR(20)), N'')
                + N'","newPriorityID":"' + CAST(@suggestedPriorityID_FK AS NVARCHAR(20)) + N'"}';

            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'UPDATE_PRIORITY', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم تحديث أولوية التذكرة بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- START_WORK
        ----------------------------------------------------------------
        ELSE IF @Action = N'START_WORK'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END

            DECLARE @swOldStatus INT;
            SELECT @swOldStatus = [ticketStatusID_FK] FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @swOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            DECLARE @statusInProgressID INT;
            SELECT @statusInProgressID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'IN_PROGRESS' AND [ticketStatusActive] = 1;

            IF @statusInProgressID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة IN_PROGRESS', 1; END

            IF @swOldStatus NOT IN (
                SELECT [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] IN (N'ASSIGNED', N'REOPENED') AND [ticketStatusActive] = 1
            )
            BEGIN ;THROW 50001, N'يمكن بدء العمل على التذكرة فقط من حالتي ASSIGNED أو REOPENED', 1; END

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @statusInProgressID
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'STARTED', @swOldStatus, @statusInProgressID
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم بدء العمل'), COALESCE(@notes_A, ISNULL(@notes, N'تم بدء العمل')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'START_WORK', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم بدء العمل بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- RESOLVE_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'RESOLVE_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END

            DECLARE @rvOldStatus INT, @rvRequiresQR BIT;
            SELECT @rvOldStatus = [ticketStatusID_FK], @rvRequiresQR = ISNULL([requiresQualityReview], 0)
            FROM [Tickets].[Ticket] WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @rvOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            IF @rvOldStatus NOT IN (
                SELECT [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] IN (N'IN_PROGRESS', N'CLARIFICATION') AND [ticketStatusActive] = 1
            )
            BEGIN ;THROW 50001, N'يمكن حل التذكرة فقط من حالتي IN_PROGRESS أو CLARIFICATION', 1; END

            IF EXISTS (
              SELECT 1
              FROM [Tickets].[ClarificationRequest] cr
              WHERE cr.[ticketID_FK] = @ticketID
                AND ISNULL(cr.[clarificationActive], 1) = 1
                AND cr.[clarificationStatus] = N'OPEN'
            )
            BEGIN ;THROW 50001, N'لا يمكن حل التذكرة مع وجود طلب توضيح مفتوح', 1; END

            IF @rvRequiresQR = 0
               AND EXISTS (
                    SELECT 1
                    FROM [Tickets].[Ticket] child
                    WHERE child.[parentTicketID_FK] = @ticketID
                      AND child.[ticketActive] = 1
                      AND child.[ticketStatusID_FK] NOT IN (
                            SELECT [ticketStatusID]
                            FROM [Tickets].[TicketStatus]
                            WHERE [ticketStatusCode] IN (N'RESOLVED', N'CLOSED', N'REJECTED')
                              AND [ticketStatusActive] = 1
                      )
               )
            BEGIN ;THROW 50001, N'لا يمكن الإغلاق النهائي مع وجود تذاكر فرعية مفتوحة', 1; END

            IF @rvRequiresQR = 1
            BEGIN
                DECLARE @statusResolvedID INT;
                SELECT @statusResolvedID = [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] = N'RESOLVED' AND [ticketStatusActive] = 1;

                UPDATE [Tickets].[Ticket]
                SET [ticketStatusID_FK] = @statusResolvedID
                  , [operationalResolutionDate] = GETDATE()
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @ticketID;

                INSERT INTO [Tickets].[TicketHistory]
                ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                VALUES
                ( @ticketID, @idaraID_FK, N'RESOLVED', @rvOldStatus, @statusResolvedID
                , NULL, NULL, NULL, NULL
                , @performerUserID, ISNULL(@notes, N'تم حل التذكرة - بانتظار مراجعة الجودة'), COALESCE(@notes_A, ISNULL(@notes, N'تم حل التذكرة - بانتظار مراجعة الجودة')), @entryData, @hostName );

                SELECT 1 AS IsSuccessful, N'تم حل التذكرة - بانتظار مراجعة الجودة' AS Message_;
            END
            ELSE
            BEGIN
                DECLARE @statusClosedID INT;
                SELECT @statusClosedID = [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] = N'CLOSED' AND [ticketStatusActive] = 1;

                UPDATE [Tickets].[Ticket]
                SET [ticketStatusID_FK] = @statusClosedID
                  , [operationalResolutionDate] = GETDATE()
                  , [finalClosureDate] = GETDATE()
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @ticketID;

                INSERT INTO [Tickets].[TicketHistory]
                ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                VALUES
                ( @ticketID, @idaraID_FK, N'CLOSED', @rvOldStatus, @statusClosedID
                , NULL, NULL, NULL, NULL
                , @performerUserID, ISNULL(@notes, N'تم حل التذكرة وإغلاقها'), COALESCE(@notes_A, ISNULL(@notes, N'تم حل التذكرة وإغلاقها')), @entryData, @hostName );

                SELECT 1 AS IsSuccessful, N'تم حل التذكرة وإغلاقها' AS Message_;
            END

            SET @ParentTicketToUpdate = NULL;
            SET @RemainingOpenChildren = 0;
            SET @ParentCurrentStatus = NULL;
            SET @PausedStatusID = NULL;
            SET @ResumeStatusID = NULL;

            SELECT @ParentTicketToUpdate = [parentTicketID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID;

            IF @ParentTicketToUpdate IS NOT NULL
            BEGIN
                SELECT @RemainingOpenChildren = COUNT(*)
                FROM [Tickets].[Ticket] child
                WHERE child.[parentTicketID_FK] = @ParentTicketToUpdate
                  AND child.[ticketActive] = 1
                  AND child.[ticketStatusID_FK] NOT IN (
                        SELECT [ticketStatusID]
                        FROM [Tickets].[TicketStatus]
                        WHERE [ticketStatusCode] IN (N'RESOLVED', N'CLOSED', N'REJECTED')
                          AND [ticketStatusActive] = 1
                  );

                IF ISNULL(@RemainingOpenChildren, 0) = 0
                BEGIN
                    UPDATE [Tickets].[Ticket]
                    SET [isParentBlocked] = 0
                      , [entryData] = @entryData
                      , [hostName]  = @hostName
                    WHERE [ticketID] = @ParentTicketToUpdate;

                    UPDATE [Tickets].[TicketPauseSession]
                    SET [pauseEnd] = GETDATE()
                      , [ticketPauseSessionActive] = 0
                      , [entryData] = @entryData
                      , [hostName]  = @hostName
                    WHERE [ticketID_FK] = @ParentTicketToUpdate
                      AND [relatedChildTicketID_FK] IS NOT NULL
                      AND [pauseEnd] IS NULL;

                    SELECT @ParentCurrentStatus = [ticketStatusID_FK]
                    FROM [Tickets].[Ticket]
                    WHERE [ticketID] = @ParentTicketToUpdate;

                    SELECT @PausedStatusID = [ticketStatusID]
                    FROM [Tickets].[TicketStatus]
                    WHERE [ticketStatusCode] = N'PAUSED'
                      AND [ticketStatusActive] = 1;

                    IF @ParentCurrentStatus = @PausedStatusID
                       AND NOT EXISTS (
                            SELECT 1
                            FROM [Tickets].[TicketPauseSession]
                            WHERE [ticketID_FK] = @ParentTicketToUpdate
                              AND [pauseEnd] IS NULL
                              AND [ticketPauseSessionActive] = 1
                       )
                    BEGIN
                        SELECT TOP 1 @ResumeStatusID = [oldStatusID_FK]
                        FROM [Tickets].[TicketHistory]
                        WHERE [ticketID_FK] = @ParentTicketToUpdate
                          AND [actionTypeCode] = N'PAUSED'
                        ORDER BY [ticketHistoryID] DESC;

                        UPDATE [Tickets].[Ticket]
                        SET [ticketStatusID_FK] = ISNULL(@ResumeStatusID, @ParentCurrentStatus)
                          , [entryData] = @entryData
                          , [hostName]  = @hostName
                        WHERE [ticketID] = @ParentTicketToUpdate;

                        INSERT INTO [Tickets].[TicketHistory]
                        ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                        , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                        , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                        VALUES
                        ( @ParentTicketToUpdate, @idaraID_FK, N'RESUMED', @ParentCurrentStatus, ISNULL(@ResumeStatusID, @ParentCurrentStatus)
                        , NULL, NULL, NULL, NULL
                        , @performerUserID, N'تم استئناف التذكرة الأصلية تلقائياً بعد اكتمال التذاكر الفرعية', N'تم استئناف التذكرة الأصلية تلقائياً بعد اكتمال التذاكر الفرعية', @entryData, @hostName );
                    END
                END
            END

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'RESOLVE_TICKET', @ticketID, @entryData, @Note);
        END

        ----------------------------------------------------------------
        -- CLOSE_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'CLOSE_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END

            DECLARE @clOldStatus INT;
            SELECT @clOldStatus = [ticketStatusID_FK] FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @clOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            IF @clOldStatus NOT IN (
                SELECT [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] = N'RESOLVED' AND [ticketStatusActive] = 1
            )
            BEGIN ;THROW 50001, N'يمكن إغلاق التذكرة فقط من حالة RESOLVED', 1; END

            IF EXISTS (
                SELECT 1
                FROM [Tickets].[Ticket] child
                WHERE child.[parentTicketID_FK] = @ticketID
                  AND child.[ticketActive] = 1
                  AND child.[ticketStatusID_FK] NOT IN (
                        SELECT [ticketStatusID]
                        FROM [Tickets].[TicketStatus]
                        WHERE [ticketStatusCode] IN (N'RESOLVED', N'CLOSED', N'REJECTED')
                          AND [ticketStatusActive] = 1
                  )
            )
            BEGIN ;THROW 50001, N'لا يمكن إغلاق التذكرة مع وجود تذاكر فرعية مفتوحة', 1; END

            DECLARE @clStatusClosedID INT;
            SELECT @clStatusClosedID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'CLOSED' AND [ticketStatusActive] = 1;

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @clStatusClosedID
              , [finalClosureDate] = GETDATE()
              , [operationalResolutionDate] = ISNULL([operationalResolutionDate], GETDATE())
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'CLOSED', @clOldStatus, @clStatusClosedID
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم إغلاق التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تم إغلاق التذكرة')), @entryData, @hostName );

            SET @ParentTicketToUpdate = NULL;
            SET @RemainingOpenChildren = 0;
            SET @ParentCurrentStatus = NULL;
            SET @PausedStatusID = NULL;
            SET @ResumeStatusID = NULL;

            SELECT @ParentTicketToUpdate = [parentTicketID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID;

            IF @ParentTicketToUpdate IS NOT NULL
            BEGIN
                SELECT @RemainingOpenChildren = COUNT(*)
                FROM [Tickets].[Ticket] child
                WHERE child.[parentTicketID_FK] = @ParentTicketToUpdate
                  AND child.[ticketActive] = 1
                  AND child.[ticketStatusID_FK] NOT IN (
                        SELECT [ticketStatusID]
                        FROM [Tickets].[TicketStatus]
                        WHERE [ticketStatusCode] IN (N'RESOLVED', N'CLOSED', N'REJECTED')
                          AND [ticketStatusActive] = 1
                  );

                IF ISNULL(@RemainingOpenChildren, 0) = 0
                BEGIN
                    UPDATE [Tickets].[Ticket]
                    SET [isParentBlocked] = 0
                      , [entryData] = @entryData
                      , [hostName]  = @hostName
                    WHERE [ticketID] = @ParentTicketToUpdate;

                    UPDATE [Tickets].[TicketPauseSession]
                    SET [pauseEnd] = GETDATE()
                      , [ticketPauseSessionActive] = 0
                      , [entryData] = @entryData
                      , [hostName]  = @hostName
                    WHERE [ticketID_FK] = @ParentTicketToUpdate
                      AND [relatedChildTicketID_FK] IS NOT NULL
                      AND [pauseEnd] IS NULL;

                    SELECT @ParentCurrentStatus = [ticketStatusID_FK]
                    FROM [Tickets].[Ticket]
                    WHERE [ticketID] = @ParentTicketToUpdate;

                    SELECT @PausedStatusID = [ticketStatusID]
                    FROM [Tickets].[TicketStatus]
                    WHERE [ticketStatusCode] = N'PAUSED'
                      AND [ticketStatusActive] = 1;

                    IF @ParentCurrentStatus = @PausedStatusID
                       AND NOT EXISTS (
                            SELECT 1
                            FROM [Tickets].[TicketPauseSession]
                            WHERE [ticketID_FK] = @ParentTicketToUpdate
                              AND [pauseEnd] IS NULL
                              AND [ticketPauseSessionActive] = 1
                       )
                    BEGIN
                        SELECT TOP 1 @ResumeStatusID = [oldStatusID_FK]
                        FROM [Tickets].[TicketHistory]
                        WHERE [ticketID_FK] = @ParentTicketToUpdate
                          AND [actionTypeCode] = N'PAUSED'
                        ORDER BY [ticketHistoryID] DESC;

                        UPDATE [Tickets].[Ticket]
                        SET [ticketStatusID_FK] = ISNULL(@ResumeStatusID, @ParentCurrentStatus)
                          , [entryData] = @entryData
                          , [hostName]  = @hostName
                        WHERE [ticketID] = @ParentTicketToUpdate;

                        INSERT INTO [Tickets].[TicketHistory]
                        ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                        , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                        , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                        VALUES
                        ( @ParentTicketToUpdate, @idaraID_FK, N'RESUMED', @ParentCurrentStatus, ISNULL(@ResumeStatusID, @ParentCurrentStatus)
                        , NULL, NULL, NULL, NULL
                        , @performerUserID, N'تم استئناف التذكرة الأصلية تلقائياً بعد اكتمال التذاكر الفرعية', N'تم استئناف التذكرة الأصلية تلقائياً بعد اكتمال التذاكر الفرعية', @entryData, @hostName );
                    END
                END
            END

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'CLOSE_TICKET', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إغلاق التذكرة بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- REJECT_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'REJECT_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END

            DECLARE @rjOldStatus INT;
            SELECT @rjOldStatus = [ticketStatusID_FK] FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @rjOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            IF @rjOldStatus NOT IN (
                SELECT [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] IN (N'NEW', N'REOPENED') AND [ticketStatusActive] = 1
            )
            BEGIN ;THROW 50001, N'يمكن رفض التذكرة فقط من حالتي NEW أو REOPENED', 1; END

            DECLARE @statusRejectedID INT;
            SELECT @statusRejectedID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'REJECTED' AND [ticketStatusActive] = 1;

            IF @statusRejectedID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة REJECTED', 1; END

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @statusRejectedID
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'REJECTED', @rjOldStatus, @statusRejectedID
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم رفض التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تم رفض التذكرة')), @entryData, @hostName );

            SET @ParentTicketToUpdate = NULL;
            SET @RemainingOpenChildren = 0;

            SELECT @ParentTicketToUpdate = [parentTicketID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID;

            IF @ParentTicketToUpdate IS NOT NULL
            BEGIN
                SELECT @RemainingOpenChildren = COUNT(*)
                FROM [Tickets].[Ticket] child
                WHERE child.[parentTicketID_FK] = @ParentTicketToUpdate
                  AND child.[ticketActive] = 1
                  AND child.[ticketStatusID_FK] NOT IN (
                        SELECT [ticketStatusID]
                        FROM [Tickets].[TicketStatus]
                        WHERE [ticketStatusCode] IN (N'RESOLVED', N'CLOSED', N'REJECTED')
                          AND [ticketStatusActive] = 1
                  );

                IF ISNULL(@RemainingOpenChildren, 0) = 0
                BEGIN
                    UPDATE [Tickets].[Ticket]
                    SET [isParentBlocked] = 0
                      , [entryData] = @entryData
                      , [hostName]  = @hostName
                    WHERE [ticketID] = @ParentTicketToUpdate;

                    UPDATE [Tickets].[TicketPauseSession]
                    SET [pauseEnd] = GETDATE()
                      , [ticketPauseSessionActive] = 0
                      , [entryData] = @entryData
                      , [hostName]  = @hostName
                    WHERE [ticketID_FK] = @ParentTicketToUpdate
                      AND [relatedChildTicketID_FK] IS NOT NULL
                      AND [pauseEnd] IS NULL;
                END
            END

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'REJECT_TICKET', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم رفض التذكرة' AS Message_;
        END

        ----------------------------------------------------------------
        -- REOPEN_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'REOPEN_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END

            DECLARE @roOldStatus INT;
            SELECT @roOldStatus = [ticketStatusID_FK] FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @roOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            IF @roOldStatus NOT IN (
                SELECT [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] IN (N'CLOSED', N'RESOLVED') AND [ticketStatusActive] = 1
            )
            BEGIN ;THROW 50001, N'يمكن إعادة فتح التذكرة فقط من حالتي CLOSED أو RESOLVED', 1; END

            DECLARE @statusReopenedID INT;
            SELECT @statusReopenedID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'REOPENED' AND [ticketStatusActive] = 1;

            IF @statusReopenedID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة REOPENED', 1; END

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @statusReopenedID
              , [finalClosureDate] = NULL
              , [operationalResolutionDate] = NULL
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'REOPENED', @roOldStatus, @statusReopenedID
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تمت إعادة فتح التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تمت إعادة فتح التذكرة')), @entryData, @hostName );

            SET @ParentTicketToUpdate = NULL;
            SET @ParentCurrentStatus = NULL;
            SET @PausedStatusID = NULL;

            SELECT @ParentTicketToUpdate = [parentTicketID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID;

            IF @ParentTicketToUpdate IS NOT NULL
            BEGIN
                UPDATE [Tickets].[Ticket]
                SET [isParentBlocked] = 1
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @ParentTicketToUpdate;

                IF NOT EXISTS (
                    SELECT 1
                    FROM [Tickets].[TicketPauseSession]
                    WHERE [ticketID_FK] = @ParentTicketToUpdate
                      AND [relatedChildTicketID_FK] = @ticketID
                      AND [pauseEnd] IS NULL
                      AND [ticketPauseSessionActive] = 1
                )
                BEGIN
                    INSERT INTO [Tickets].[TicketPauseSession]
                    ( [ticketID_FK], [idaraID_FK], [pauseReasonID_FK], [relatedChildTicketID_FK]
                    , [pauseStart], [pauseEnd], [slaPauseFlag], [pauseNotes], [pauseNotes_A]
                    , [ticketPauseSessionActive], [entryData], [hostName] )
                    VALUES
                    ( @ParentTicketToUpdate, @idaraID_FK, 1, @ticketID
                    , GETDATE(), NULL, 1, N'إيقاف تلقائي: تمت إعادة فتح تذكرة فرعية', N'إيقاف تلقائي: تمت إعادة فتح تذكرة فرعية'
                    , 1, @entryData, @hostName );
                END

                SELECT @ParentCurrentStatus = [ticketStatusID_FK]
                FROM [Tickets].[Ticket]
                WHERE [ticketID] = @ParentTicketToUpdate;

                SELECT @PausedStatusID = [ticketStatusID]
                FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] = N'PAUSED'
                  AND [ticketStatusActive] = 1;

                IF @PausedStatusID IS NOT NULL
                   AND @ParentCurrentStatus IS NOT NULL
                   AND @ParentCurrentStatus <> @PausedStatusID
                BEGIN
                    UPDATE [Tickets].[Ticket]
                    SET [ticketStatusID_FK] = @PausedStatusID
                      , [entryData] = @entryData
                      , [hostName]  = @hostName
                    WHERE [ticketID] = @ParentTicketToUpdate;

                    INSERT INTO [Tickets].[TicketHistory]
                    ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                    , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                    , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                    VALUES
                    ( @ParentTicketToUpdate, @idaraID_FK, N'PAUSED', @ParentCurrentStatus, @PausedStatusID
                    , NULL, NULL, NULL, NULL
                    , @performerUserID, N'تم إيقاف التذكرة الأصلية تلقائياً بعد إعادة فتح تذكرة فرعية', N'تم إيقاف التذكرة الأصلية تلقائياً بعد إعادة فتح تذكرة فرعية', @entryData, @hostName );
                END
            END

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'REOPEN_TICKET', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تمت إعادة فتح التذكرة' AS Message_;
        END

        ----------------------------------------------------------------
        -- PAUSE_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'PAUSE_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END
            IF @pauseReasonID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف سبب الإيقاف مطلوب', 1; END

            DECLARE @pOldStatus INT;
            SELECT @pOldStatus = [ticketStatusID_FK] FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @pOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            IF EXISTS (SELECT 1 FROM [Tickets].[TicketPauseSession]
                       WHERE [ticketID_FK] = @ticketID AND [pauseEnd] IS NULL AND [ticketPauseSessionActive] = 1)
            BEGIN ;THROW 50001, N'التذكرة موقفة بالفعل', 1; END

            DECLARE @statusPausedID INT;
            SELECT @statusPausedID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'PAUSED' AND [ticketStatusActive] = 1;

            IF @statusPausedID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة PAUSED', 1; END

            INSERT INTO [Tickets].[TicketPauseSession]
            ( [ticketID_FK], [idaraID_FK], [pauseReasonID_FK]
            , [pauseStart], [pauseEnd], [slaPauseFlag], [pauseNotes], [pauseNotes_A]
            , [ticketPauseSessionActive], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, @pauseReasonID_FK
            , GETDATE(), NULL, 1, @pauseNotesToSave, @pauseNotesToSave
            , 1, @entryData, @hostName );

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @statusPausedID
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'PAUSED', @pOldStatus, @statusPausedID
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم إيقاف التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تم إيقاف التذكرة')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","pauseReasonID":"' + CAST(@pauseReasonID_FK AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'PAUSE_TICKET', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إيقاف التذكرة بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- RESUME_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'RESUME_TICKET'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END

            DECLARE @rmOldStatus INT;
            SELECT @rmOldStatus = [ticketStatusID_FK] FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @rmOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            DECLARE @openPauseID BIGINT, @prevStatusID INT, @openPauseClarificationRequestID BIGINT;
            SELECT TOP 1 @openPauseID = [ticketPauseSessionID]
                         , @openPauseClarificationRequestID = [relatedClarificationRequestID_FK]
            FROM [Tickets].[TicketPauseSession]
            WHERE [ticketID_FK] = @ticketID AND [pauseEnd] IS NULL AND [ticketPauseSessionActive] = 1
            ORDER BY [ticketPauseSessionID] DESC;

            IF @openPauseID IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على جلسة إيقاف مفتوحة لهذه التذكرة', 1; END

            IF @openPauseClarificationRequestID IS NOT NULL
            BEGIN ;THROW 50001, N'استخدم إجراء الرد على التوضيح لإنهاء هذا الإيقاف', 1; END

            SELECT TOP 1 @prevStatusID = [oldStatusID_FK]
            FROM [Tickets].[TicketHistory]
            WHERE [ticketID_FK] = @ticketID AND [actionTypeCode] = N'PAUSED'
            ORDER BY [ticketHistoryID] DESC;

            IF @prevStatusID IS NULL
            BEGIN
                SET @prevStatusID = @rmOldStatus;
            END

            UPDATE [Tickets].[TicketPauseSession]
            SET [pauseEnd] = GETDATE()
              , [ticketPauseSessionActive] = 0
            WHERE [ticketPauseSessionID] = @openPauseID;

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @prevStatusID
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'RESUMED', @rmOldStatus, @prevStatusID
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم استئناف التذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تم استئناف التذكرة')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'RESUME_TICKET', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم استئناف التذكرة بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- REQUEST_CLARIFICATION
        ----------------------------------------------------------------
        ELSE IF @Action = N'REQUEST_CLARIFICATION'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END
            IF @clarificationReasonID_FK IS NULL
            BEGIN ;THROW 50001, N'سبب طلب التوضيح مطلوب', 1; END
            IF @requestedFromUserID IS NULL AND @requestedFromDSDID_FK IS NULL
            BEGIN ;THROW 50001, N'يجب تحديد المستخدم أو الجهة المطلوب منها التوضيح', 1; END
            IF NULLIF(LTRIM(RTRIM(@notesToSave)), N'') IS NULL
            BEGIN ;THROW 50001, N'ملاحظات طلب التوضيح مطلوبة', 1; END

            DECLARE @crOldStatus INT;
            DECLARE @statusClarificationID INT;
            DECLARE @clarificationPauseReasonID INT;

            SELECT @crOldStatus = [ticketStatusID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID
              AND [ticketActive] = 1;

            IF @crOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            SELECT @statusClarificationID = [ticketStatusID]
            FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'CLARIFICATION'
              AND [ticketStatusActive] = 1;

            IF @statusClarificationID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة CLARIFICATION', 1; END

            IF @crOldStatus IN (
                SELECT [ticketStatusID]
                FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] IN (N'RESOLVED', N'CLOSED', N'REJECTED')
                  AND [ticketStatusActive] = 1
            )
            BEGIN ;THROW 50001, N'لا يمكن طلب توضيح لتذكرة منتهية أو مغلقة', 1; END

            IF @crOldStatus = @statusClarificationID
            BEGIN ;THROW 50001, N'التذكرة في حالة طلب توضيح بالفعل', 1; END

            IF EXISTS (
                SELECT 1
                FROM [Tickets].[ClarificationRequest]
                WHERE [ticketID_FK] = @ticketID
                  AND ISNULL([clarificationActive], 1) = 1
                  AND [clarificationStatus] = N'OPEN'
            )
            BEGIN ;THROW 50001, N'يوجد طلب توضيح مفتوح لهذه التذكرة بالفعل', 1; END

            IF EXISTS (
                SELECT 1
                FROM [Tickets].[TicketPauseSession]
                WHERE [ticketID_FK] = @ticketID
                  AND [pauseEnd] IS NULL
                  AND [ticketPauseSessionActive] = 1
            )
            BEGIN ;THROW 50001, N'لا يمكن طلب توضيح بينما التذكرة موقفة بالفعل', 1; END

            IF NOT EXISTS (
                SELECT 1
                FROM [Tickets].[ClarificationReason]
                WHERE [clarificationReasonID] = @clarificationReasonID_FK
                  AND [clarificationReasonActive] = 1
            )
            BEGIN ;THROW 50001, N'سبب طلب التوضيح المحدد غير صالح', 1; END

            IF @requestedFromDSDID_FK IS NOT NULL
               AND NOT EXISTS (
                    SELECT 1
                    FROM dbo.[V_GetFullStructureForDSD] f
                    WHERE f.[DSDID] = @requestedFromDSDID_FK
                      AND (@idaraID_FK IS NULL OR f.[IdaraID] = @idaraID_FK)
               )
            BEGIN ;THROW 50001, N'الجهة المطلوب منها التوضيح غير صالحة', 1; END

            SELECT @clarificationPauseReasonID = [pauseReasonID]
            FROM [Tickets].[PauseReason]
            WHERE [pauseReasonCode] = N'CLARIFICATION'
              AND [pauseReasonActive] = 1;

            IF @clarificationPauseReasonID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على سبب الإيقاف CLARIFICATION', 1; END

            INSERT INTO [Tickets].[ClarificationRequest]
            ( [ticketID_FK], [idaraID_FK], [requestedByUserID], [requestedFromUserID], [requestedFromDSDID_FK]
            , [clarificationReasonID_FK], [requestNotes], [responseNotes], [clarificationStatus], [clarificationActive], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, @performerUserID, @requestedFromUserID, @requestedFromDSDID_FK
            , @clarificationReasonID_FK, @notesToSave, NULL, N'OPEN', 1, @entryData, @hostName );

            SET @NewID = SCOPE_IDENTITY();

            INSERT INTO [Tickets].[TicketPauseSession]
            ( [ticketID_FK], [idaraID_FK], [pauseReasonID_FK], [relatedClarificationRequestID_FK]
            , [pauseStart], [pauseEnd], [slaPauseFlag], [pauseNotes], [pauseNotes_A]
            , [ticketPauseSessionActive], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, @clarificationPauseReasonID, @NewID
            , GETDATE(), NULL, 1, @pauseNotesToSave, @pauseNotesToSave
            , 1, @entryData, @hostName );

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @statusClarificationID
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'CLARIFICATION_REQUESTED', @crOldStatus, @statusClarificationID
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم طلب توضيح للتذكرة'), COALESCE(@notes_A, ISNULL(@notes, N'تم طلب توضيح للتذكرة')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","clarificationRequestID":"' + CAST(@NewID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ClarificationRequest]', N'REQUEST_CLARIFICATION', @NewID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إرسال طلب التوضيح بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- RESPOND_CLARIFICATION
        ----------------------------------------------------------------
        ELSE IF @Action = N'RESPOND_CLARIFICATION'
        BEGIN
            IF @clarificationRequestID IS NULL
            BEGIN ;THROW 50001, N'معرف طلب التوضيح مطلوب', 1; END
            IF NULLIF(LTRIM(RTRIM(@notesToSave)), N'') IS NULL
            BEGIN ;THROW 50001, N'ملاحظات الرد على التوضيح مطلوبة', 1; END

            DECLARE @responseTicketID BIGINT;
            DECLARE @responseClarificationStatus NVARCHAR(50);
            DECLARE @responseTicketStatus INT;
            DECLARE @responseResumeStatusID INT;
            DECLARE @responseOtherOpenClarifications INT;
            DECLARE @responseOtherOpenPauses INT;
            DECLARE @responseAssignedUserID INT;
            DECLARE @responseClarificationStatusID INT;
            DECLARE @responsePausedStatusID INT;
            DECLARE @responseAssignedStatusID INT;
            DECLARE @responseRoutedStatusID INT;

            SELECT @responseTicketID = [ticketID_FK]
                 , @responseClarificationStatus = [clarificationStatus]
            FROM [Tickets].[ClarificationRequest]
            WHERE [clarificationRequestID] = @clarificationRequestID
              AND ISNULL([clarificationActive], 1) = 1;

            IF @responseTicketID IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على طلب التوضيح', 1; END

            IF @responseClarificationStatus <> N'OPEN'
            BEGIN ;THROW 50001, N'طلب التوضيح ليس في حالة OPEN', 1; END

            SELECT @responseClarificationStatusID = [ticketStatusID]
            FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'CLARIFICATION'
              AND [ticketStatusActive] = 1;

            IF @responseClarificationStatusID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة CLARIFICATION', 1; END

            SELECT @responseTicketStatus = [ticketStatusID_FK]
                 , @responseAssignedUserID = [assignedUserID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @responseTicketID
              AND [ticketActive] = 1;

            IF @responseTicketStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على التذكرة المرتبطة بطلب التوضيح', 1; END

            UPDATE [Tickets].[ClarificationRequest]
            SET [responseNotes] = @notesToSave
              , [responseDate] = GETDATE()
              , [clarificationStatus] = N'RESPONDED'
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [clarificationRequestID] = @clarificationRequestID;

            UPDATE [Tickets].[TicketPauseSession]
            SET [pauseEnd] = GETDATE()
              , [ticketPauseSessionActive] = 0
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID_FK] = @responseTicketID
              AND [relatedClarificationRequestID_FK] = @clarificationRequestID
              AND [pauseEnd] IS NULL
              AND [ticketPauseSessionActive] = 1;

            SELECT @responseOtherOpenClarifications = COUNT(*)
            FROM [Tickets].[ClarificationRequest]
            WHERE [ticketID_FK] = @responseTicketID
              AND [clarificationRequestID] <> @clarificationRequestID
              AND ISNULL([clarificationActive], 1) = 1
              AND [clarificationStatus] = N'OPEN';

            SELECT @responseOtherOpenPauses = COUNT(*)
            FROM [Tickets].[TicketPauseSession]
            WHERE [ticketID_FK] = @responseTicketID
              AND [pauseEnd] IS NULL
              AND [ticketPauseSessionActive] = 1;

            SET @responseResumeStatusID = @responseTicketStatus;

            IF ISNULL(@responseOtherOpenClarifications, 0) = 0
               AND @responseTicketStatus = @responseClarificationStatusID
            BEGIN
                IF ISNULL(@responseOtherOpenPauses, 0) > 0
                BEGIN
                    SELECT @responsePausedStatusID = [ticketStatusID]
                    FROM [Tickets].[TicketStatus]
                    WHERE [ticketStatusCode] = N'PAUSED'
                      AND [ticketStatusActive] = 1;

                    SET @responseResumeStatusID = ISNULL(@responsePausedStatusID, @responseTicketStatus);
                END
                ELSE
                BEGIN
                    SELECT TOP 1 @responseResumeStatusID = [oldStatusID_FK]
                    FROM [Tickets].[TicketHistory]
                    WHERE [ticketID_FK] = @responseTicketID
                      AND [actionTypeCode] = N'CLARIFICATION_REQUESTED'
                      AND [oldStatusID_FK] IS NOT NULL
                      AND [oldStatusID_FK] <> @responseClarificationStatusID
                    ORDER BY [ticketHistoryID] DESC;

                    IF @responseResumeStatusID IS NULL
                    BEGIN
                        SELECT @responseAssignedStatusID = [ticketStatusID]
                        FROM [Tickets].[TicketStatus]
                        WHERE [ticketStatusCode] = N'ASSIGNED'
                          AND [ticketStatusActive] = 1;

                        SELECT @responseRoutedStatusID = [ticketStatusID]
                        FROM [Tickets].[TicketStatus]
                        WHERE [ticketStatusCode] = N'ROUTED'
                          AND [ticketStatusActive] = 1;

                        SET @responseResumeStatusID = CASE
                            WHEN @responseAssignedUserID IS NOT NULL THEN @responseAssignedStatusID
                            ELSE @responseRoutedStatusID
                        END;
                    END
                END

                UPDATE [Tickets].[Ticket]
                SET [ticketStatusID_FK] = ISNULL(@responseResumeStatusID, @responseTicketStatus)
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @responseTicketID;
            END

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @responseTicketID, @idaraID_FK, N'CLARIFICATION_RESPONDED', @responseTicketStatus, ISNULL(@responseResumeStatusID, @responseTicketStatus)
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم الرد على طلب التوضيح'), COALESCE(@notes_A, ISNULL(@notes, N'تم الرد على طلب التوضيح')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@responseTicketID AS NVARCHAR(20))
                + N'","clarificationRequestID":"' + CAST(@clarificationRequestID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ClarificationRequest]', N'RESPOND_CLARIFICATION', @clarificationRequestID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم تسجيل الرد على طلب التوضيح بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- CREATE_CHILD_TICKET
        ----------------------------------------------------------------
        ELSE IF @Action = N'CREATE_CHILD_TICKET'
        BEGIN
            IF @parentTicketID_FK IS NULL OR @parentTicketID_FK <= 0
            BEGIN ;THROW 50001, N'معرف التذكرة الأصلية مطلوب للتذاكر الفرعية', 1; END

          IF NULLIF(LTRIM(RTRIM(@titleToSave)), N'') IS NULL
            BEGIN ;THROW 50001, N'العنوان مطلوب', 1; END

            IF @idaraID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف الإدارة مطلوب', 1; END

            DECLARE @parentExists BIT = 0;
            DECLARE @parentRootID BIGINT;
            DECLARE @parentSvcID BIGINT;
            DECLARE @parentAllowsChild BIT = 0;

            SELECT @parentExists = 1
                 , @parentRootID = [rootTicketID_FK]
                 , @parentSvcID = [serviceID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @parentTicketID_FK AND [ticketActive] = 1;

            IF @parentExists = 0
            BEGIN ;THROW 50001, N'لم يتم العثور على التذكرة الأصلية أو أنها غير نشطة', 1; END

            SELECT @parentAllowsChild = ISNULL([allowsChildTickets], 0)
            FROM [Tickets].[Service]
            WHERE [serviceID] = @parentSvcID AND [serviceActive] = 1;

            IF @parentAllowsChild = 0
            BEGIN ;THROW 50001, N'خدمة التذكرة الأصلية لا تسمح بإنشاء تذاكر فرعية', 1; END

            DECLARE @childYr NVARCHAR(4) = CONVERT(NVARCHAR(4), YEAR(GETDATE()));
            DECLARE @childSeq INT;
            SELECT @childSeq = ISNULL(MAX(CAST(RIGHT([ticketNo], 5) AS INT)), 0) + 1
            FROM [Tickets].[Ticket]
            WHERE [ticketNo] LIKE N'TKT-' + @childYr + N'-%';

            SET @NewTicketNo = N'TKT-' + @childYr + N'-' + RIGHT(N'00000' + CAST(@childSeq AS NVARCHAR(10)), 5);

            DECLARE @childStatusNewID INT;
            SELECT @childStatusNewID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'NEW' AND [ticketStatusActive] = 1;

            INSERT INTO [Tickets].[Ticket]
            (
                  [ticketNo], [idaraID_FK], [parentTicketID_FK], [rootTicketID_FK]
                , [serviceID_FK], [ticketClassID_FK], [requesterTypeID_FK]
                , [requesterUserID_FK], [requesterResidentID_FK]
                , [title], [title_A], [description_], [description_A]
                , [suggestedPriorityID_FK], [effectivePriorityID_FK], [ticketStatusID_FK]
                , [currentDSDID_FK], [currentQueueDistributorID_FK], [assignedUserID_FK]
                , [locationBuildingNo], [locationUnitNo], [locationArea], [locationArea_A]
                , [operationalResolutionDate], [finalClosureDate]
                , [requiresQualityReview], [isOtherService], [isParentBlocked], [ticketActive]
                , [entryData], [hostName]
            )
            VALUES
            (
                  @NewTicketNo, @idaraID_FK, @parentTicketID_FK, @parentRootID
                , @serviceID_FK, @ticketClassID_FK, @requesterTypeID_FK
                , @requesterUserID_FK, @requesterResidentID_FK
                , @titleToSave, @titleToSave, @descriptionToSave, @descriptionToSave
                , @suggestedPriorityID_FK, @suggestedPriorityID_FK, @childStatusNewID
                , @currentDSDID_FK, @currentQueueDistributorID_FK, @assignedUserID_FK
                , @locationBuildingNo, @locationUnitNo, @locationAreaToSave, @locationAreaToSave
                , NULL, NULL
                , 0, 0, 0, 1
                , @entryData, @hostName
            );

            SET @NewID = SCOPE_IDENTITY();
            IF @NewID IS NULL OR @NewID <= 0
            BEGIN ;THROW 50002, N'فشل إنشاء التذكرة الفرعية', 1; END

            SELECT @ParentCurrentStatus = [ticketStatusID_FK]
            FROM [Tickets].[Ticket]
            WHERE [ticketID] = @parentTicketID_FK;

            SELECT @PausedStatusID = [ticketStatusID]
            FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'PAUSED'
              AND [ticketStatusActive] = 1;

            UPDATE [Tickets].[Ticket]
            SET [isParentBlocked] = 1
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @parentTicketID_FK;

            IF @PausedStatusID IS NOT NULL
               AND @ParentCurrentStatus IS NOT NULL
               AND @ParentCurrentStatus <> @PausedStatusID
            BEGIN
                UPDATE [Tickets].[Ticket]
                SET [ticketStatusID_FK] = @PausedStatusID
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @parentTicketID_FK;

                INSERT INTO [Tickets].[TicketHistory]
                ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                VALUES
                ( @parentTicketID_FK, @idaraID_FK, N'PAUSED', @ParentCurrentStatus, @PausedStatusID
                , NULL, NULL, NULL, NULL
                , @performerUserID, N'تم إيقاف التذكرة الأصلية تلقائياً بسبب إنشاء تذكرة فرعية', N'تم إيقاف التذكرة الأصلية تلقائياً بسبب إنشاء تذكرة فرعية', @entryData, @hostName );
            END

            INSERT INTO [Tickets].[TicketPauseSession]
            ( [ticketID_FK], [idaraID_FK], [pauseReasonID_FK], [relatedChildTicketID_FK]
            , [pauseStart], [pauseEnd], [slaPauseFlag], [pauseNotes], [pauseNotes_A]
            , [ticketPauseSessionActive], [entryData], [hostName] )
            VALUES
            ( @parentTicketID_FK, @idaraID_FK, 1, @NewID
            , GETDATE(), NULL, 1, N'إيقاف تلقائي: تم إنشاء تذكرة فرعية', N'إيقاف تلقائي: تم إنشاء تذكرة فرعية'
            , 1, @entryData, @hostName );

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @NewID, @idaraID_FK, N'CREATED', NULL, @childStatusNewID
            , NULL, @currentDSDID_FK, NULL, NULL
            , @performerUserID, N'تم إنشاء تذكرة فرعية', COALESCE(@notes_A, N'تم إنشاء تذكرة فرعية'), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@NewID AS NVARCHAR(20))
                + N'","ticketNo":"' + ISNULL(@NewTicketNo, N'') + N''
                + N'","parentTicketID":"' + CAST(@parentTicketID_FK AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[Ticket]', N'CREATE_CHILD_TICKET', @NewID, @entryData, @Note);

            SELECT 1 AS IsSuccessful
                 , N'تم إنشاء تذكرة فرعية: ' + @NewTicketNo AS Message_;
        END

        ----------------------------------------------------------------
        -- SUBMIT_QUALITY_REVIEW
        ----------------------------------------------------------------
        ELSE IF @Action = N'SUBMIT_QUALITY_REVIEW'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END
            IF @qualityReviewResultID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف نتيجة مراجعة الجودة مطلوب', 1; END

            IF NOT EXISTS (SELECT 1 FROM [Tickets].[Ticket] WHERE [ticketID] = @ticketID AND [ticketActive] = 1)
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            INSERT INTO [Tickets].[QualityReview]
            ( [ticketID_FK], [idaraID_FK], [reviewerUserID], [reviewScope]
            , [qualityReviewResultID_FK], [reviewNotes], [returnToUserID], [finalized]
            , [qualityReviewActive], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, @performerUserID, @reviewScope
            , @qualityReviewResultID_FK, @reviewNotes, @returnToUserID, 0
            , 1, @entryData, @hostName );

            SET @NewID = SCOPE_IDENTITY();

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'QUALITY_REVIEW', NULL, NULL
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@reviewNotes, N'تم إرسال مراجعة الجودة'), COALESCE(@notes_A, ISNULL(@reviewNotes, N'تم إرسال مراجعة الجودة')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","qualityReviewID":"' + CAST(@NewID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[QualityReview]', N'SUBMIT_QUALITY_REVIEW', @NewID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إرسال مراجعة الجودة' AS Message_;
        END

        ----------------------------------------------------------------
        -- FINALIZE_QUALITY_REVIEW
        ----------------------------------------------------------------
        ELSE IF @Action = N'FINALIZE_QUALITY_REVIEW'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END

            DECLARE @qrID BIGINT, @qrResultID INT, @qrReturnTo INT;
            SELECT TOP 1 @qrID = [qualityReviewID], @qrResultID = [qualityReviewResultID_FK], @qrReturnTo = [returnToUserID]
            FROM [Tickets].[QualityReview]
            WHERE [ticketID_FK] = @ticketID AND [finalized] = 0 AND [qualityReviewActive] = 1
            ORDER BY [qualityReviewID] DESC;

            IF @qrID IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على مراجعة جودة معلقة لهذه التذكرة', 1; END

            DECLARE @qrOldStatus INT;
            SELECT @qrOldStatus = [ticketStatusID_FK] FROM [Tickets].[Ticket]
            WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            DECLARE @qrResultCode NVARCHAR(50);
            SELECT @qrResultCode = [qualityReviewResultCode] FROM [Tickets].[QualityReviewResult]
            WHERE [qualityReviewResultID] = @qrResultID;

            UPDATE [Tickets].[QualityReview]
            SET [finalized] = 1
              , [reviewNotes] = ISNULL(@reviewNotes, [reviewNotes])
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [qualityReviewID] = @qrID;

            IF @qrResultCode = N'APPROVED'
            BEGIN
                IF EXISTS (
                    SELECT 1
                    FROM [Tickets].[Ticket] child
                    WHERE child.[parentTicketID_FK] = @ticketID
                      AND child.[ticketActive] = 1
                      AND child.[ticketStatusID_FK] NOT IN (
                            SELECT [ticketStatusID]
                            FROM [Tickets].[TicketStatus]
                            WHERE [ticketStatusCode] IN (N'RESOLVED', N'CLOSED', N'REJECTED')
                              AND [ticketStatusActive] = 1
                      )
                )
                BEGIN ;THROW 50001, N'لا يمكن اعتماد مراجعة الجودة مع وجود تذاكر فرعية مفتوحة', 1; END

                DECLARE @qrCloseID INT;
                SELECT @qrCloseID = [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] = N'CLOSED' AND [ticketStatusActive] = 1;

                UPDATE [Tickets].[Ticket]
                SET [ticketStatusID_FK] = @qrCloseID, [finalClosureDate] = GETDATE()
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @ticketID;

                INSERT INTO [Tickets].[TicketHistory]
                ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                VALUES
                ( @ticketID, @idaraID_FK, N'QUALITY_APPROVED', @qrOldStatus, @qrCloseID
                , NULL, NULL, NULL, NULL
                , @performerUserID, N'تم اعتماد مراجعة الجودة - تم إغلاق التذكرة', COALESCE(@notes_A, N'تم اعتماد مراجعة الجودة - تم إغلاق التذكرة'), @entryData, @hostName );

                SET @ParentTicketToUpdate = NULL;
                SET @RemainingOpenChildren = 0;
                SET @ParentCurrentStatus = NULL;
                SET @PausedStatusID = NULL;
                SET @ResumeStatusID = NULL;

                SELECT @ParentTicketToUpdate = [parentTicketID_FK]
                FROM [Tickets].[Ticket]
                WHERE [ticketID] = @ticketID;

                IF @ParentTicketToUpdate IS NOT NULL
                BEGIN
                    SELECT @RemainingOpenChildren = COUNT(*)
                    FROM [Tickets].[Ticket] child
                    WHERE child.[parentTicketID_FK] = @ParentTicketToUpdate
                      AND child.[ticketActive] = 1
                      AND child.[ticketStatusID_FK] NOT IN (
                            SELECT [ticketStatusID]
                            FROM [Tickets].[TicketStatus]
                            WHERE [ticketStatusCode] IN (N'RESOLVED', N'CLOSED', N'REJECTED')
                              AND [ticketStatusActive] = 1
                      );

                    IF ISNULL(@RemainingOpenChildren, 0) = 0
                    BEGIN
                        UPDATE [Tickets].[Ticket]
                        SET [isParentBlocked] = 0
                          , [entryData] = @entryData
                          , [hostName]  = @hostName
                        WHERE [ticketID] = @ParentTicketToUpdate;

                        UPDATE [Tickets].[TicketPauseSession]
                        SET [pauseEnd] = GETDATE()
                          , [ticketPauseSessionActive] = 0
                          , [entryData] = @entryData
                          , [hostName]  = @hostName
                        WHERE [ticketID_FK] = @ParentTicketToUpdate
                          AND [relatedChildTicketID_FK] IS NOT NULL
                          AND [pauseEnd] IS NULL;

                        SELECT @ParentCurrentStatus = [ticketStatusID_FK]
                        FROM [Tickets].[Ticket]
                        WHERE [ticketID] = @ParentTicketToUpdate;

                        SELECT @PausedStatusID = [ticketStatusID]
                        FROM [Tickets].[TicketStatus]
                        WHERE [ticketStatusCode] = N'PAUSED'
                          AND [ticketStatusActive] = 1;

                        IF @ParentCurrentStatus = @PausedStatusID
                           AND NOT EXISTS (
                                SELECT 1
                                FROM [Tickets].[TicketPauseSession]
                                WHERE [ticketID_FK] = @ParentTicketToUpdate
                                  AND [pauseEnd] IS NULL
                                  AND [ticketPauseSessionActive] = 1
                           )
                        BEGIN
                            SELECT TOP 1 @ResumeStatusID = [oldStatusID_FK]
                            FROM [Tickets].[TicketHistory]
                            WHERE [ticketID_FK] = @ParentTicketToUpdate
                              AND [actionTypeCode] = N'PAUSED'
                            ORDER BY [ticketHistoryID] DESC;

                            UPDATE [Tickets].[Ticket]
                            SET [ticketStatusID_FK] = ISNULL(@ResumeStatusID, @ParentCurrentStatus)
                              , [entryData] = @entryData
                              , [hostName]  = @hostName
                            WHERE [ticketID] = @ParentTicketToUpdate;

                            INSERT INTO [Tickets].[TicketHistory]
                            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                            VALUES
                            ( @ParentTicketToUpdate, @idaraID_FK, N'RESUMED', @ParentCurrentStatus, ISNULL(@ResumeStatusID, @ParentCurrentStatus)
                            , NULL, NULL, NULL, NULL
                            , @performerUserID, N'تم استئناف التذكرة الأصلية تلقائياً بعد اكتمال التذاكر الفرعية', N'تم استئناف التذكرة الأصلية تلقائياً بعد اكتمال التذاكر الفرعية', @entryData, @hostName );
                        END
                    END
                END
            END
            ELSE IF @qrResultCode IN (N'RETURN_CORRECTION', N'REJECTED')
            BEGIN
                DECLARE @qrInProgressID INT;
                SELECT @qrInProgressID = [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] = N'IN_PROGRESS' AND [ticketStatusActive] = 1;

                UPDATE [Tickets].[Ticket]
                SET [ticketStatusID_FK] = @qrInProgressID
                  , [assignedUserID_FK] = ISNULL(@qrReturnTo, [assignedUserID_FK])
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @ticketID;

                INSERT INTO [Tickets].[TicketHistory]
                ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                VALUES
                ( @ticketID, @idaraID_FK, N'QUALITY_RETURNED', @qrOldStatus, @qrInProgressID
                , NULL, NULL, NULL, @qrReturnTo
                , @performerUserID, N'تم إرجاع مراجعة الجودة للتصحيح', COALESCE(@notes_A, N'تم إرجاع مراجعة الجودة للتصحيح'), @entryData, @hostName );
            END
            ELSE IF @qrResultCode = N'ESCALATED'
            BEGIN
                DECLARE @qrArbID INT;
                SELECT @qrArbID = [ticketStatusID] FROM [Tickets].[TicketStatus]
                WHERE [ticketStatusCode] = N'ARBITRATION' AND [ticketStatusActive] = 1;

                UPDATE [Tickets].[Ticket]
                SET [ticketStatusID_FK] = @qrArbID
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @ticketID;

                INSERT INTO [Tickets].[TicketHistory]
                ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
                , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
                , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
                VALUES
                ( @ticketID, @idaraID_FK, N'QUALITY_ESCALATED', @qrOldStatus, @qrArbID
                , NULL, NULL, NULL, NULL
                , @performerUserID, N'تم تصعيد مراجعة الجودة إلى التحكيم', COALESCE(@notes_A, N'تم تصعيد مراجعة الجودة إلى التحكيم'), @entryData, @hostName );
            END

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","qualityReviewID":"' + CAST(@qrID AS NVARCHAR(20))
                + N'","result":"' + ISNULL(@qrResultCode, N'') + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[QualityReview]', N'FINALIZE_QUALITY_REVIEW', @qrID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إنهاء مراجعة الجودة' AS Message_;
        END

        ----------------------------------------------------------------
        -- RAISE_ARBITRATION
        ----------------------------------------------------------------
        ELSE IF @Action = N'RAISE_ARBITRATION'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END
            IF @arbitrationReasonID_FK IS NULL
            BEGIN ;THROW 50001, N'معرف سبب التحكيم مطلوب', 1; END

            DECLARE @abOldStatus INT, @abOldDSD INT;
            SELECT @abOldStatus = [ticketStatusID_FK], @abOldDSD = [currentDSDID_FK]
            FROM [Tickets].[Ticket] WHERE [ticketID] = @ticketID AND [ticketActive] = 1;

            IF @abOldStatus IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            DECLARE @statusArbID INT;
            SELECT @statusArbID = [ticketStatusID] FROM [Tickets].[TicketStatus]
            WHERE [ticketStatusCode] = N'ARBITRATION' AND [ticketStatusActive] = 1;

            IF @statusArbID IS NULL
            BEGIN ;THROW 50002, N'تعذر العثور على حالة ARBITRATION', 1; END

            INSERT INTO [Tickets].[ArbitrationCase]
            ( [ticketID_FK], [idaraID_FK], [raisedByUserID], [raisedFromDSDID_FK]
            , [arbitrationReasonID_FK], [arbitratorDistributorID]
            , [arbitrationStatus], [decisionType], [decisionNotes]
            , [arbitrationCaseActive], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, @performerUserID, @abOldDSD
            , @arbitrationReasonID_FK, @arbitratorDistributorID
            , N'OPEN', NULL, @notes
            , 1, @entryData, @hostName );

            SET @NewID = SCOPE_IDENTITY();

            INSERT INTO [Tickets].[TicketPauseSession]
            ( [ticketID_FK], [idaraID_FK], [pauseReasonID_FK], [relatedArbitrationCaseID_FK]
            , [pauseStart], [pauseEnd], [slaPauseFlag], [pauseNotes], [pauseNotes_A]
            , [ticketPauseSessionActive], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, 2, @NewID
            , GETDATE(), NULL, 1, N'إيقاف تلقائي: تم التصعيد للتحكيم', N'إيقاف تلقائي: تم التصعيد للتحكيم'
            , 1, @entryData, @hostName );

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = @statusArbID
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @ticketID;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, N'ARBITRATION', @abOldStatus, @statusArbID
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم رفع التحكيم'), COALESCE(@notes_A, ISNULL(@notes, N'تم رفع التحكيم')), @entryData, @hostName );

            SET @Note = N'{"ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","arbitrationCaseID":"' + CAST(@NewID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ArbitrationCase]', N'RAISE_ARBITRATION', @NewID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم رفع حالة التحكيم بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- DECIDE_ARBITRATION
        ----------------------------------------------------------------
        ELSE IF @Action = N'DECIDE_ARBITRATION'
        BEGIN
            IF @arbitrationCaseID IS NULL
            BEGIN ;THROW 50001, N'معرف قضية التحكيم مطلوب', 1; END
            IF @decisionType IS NULL
            BEGIN ;THROW 50001, N'نوع القرار مطلوب', 1; END

            DECLARE @daTicketID BIGINT, @daStatus NVARCHAR(50);
            SELECT @daTicketID = [ticketID_FK], @daStatus = [arbitrationStatus]
            FROM [Tickets].[ArbitrationCase]
            WHERE [arbitrationCaseID] = @arbitrationCaseID AND [arbitrationCaseActive] = 1;

            IF @daTicketID IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على قضية تحكيم نشطة', 1; END
            IF @daStatus <> N'OPEN'
            BEGIN ;THROW 50001, N'قضية التحكيم ليست في حالة OPEN', 1; END

            UPDATE [Tickets].[ArbitrationCase]
            SET [arbitrationStatus] = N'DECIDED'
              , [decisionType] = @decisionType
              , [decisionTargetDSDID_FK] = @decisionTargetDSDID_FK
              , [decisionNotes] = @decisionNotes
              , [decisionDate] = GETDATE()
              , [entryData] = @entryData
              , [hostName]  = ISNULL(ISNULL([hostName],N'') + N',' + [hostName], [hostName])
            WHERE [arbitrationCaseID] = @arbitrationCaseID;

            DECLARE @daOldStatus INT, @daOldDSD INT;
            SELECT @daOldStatus = [ticketStatusID_FK], @daOldDSD = [currentDSDID_FK]
            FROM [Tickets].[Ticket] WHERE [ticketID] = @daTicketID;

            DECLARE @daPrevStatus INT;
            SELECT TOP 1 @daPrevStatus = [oldStatusID_FK]
            FROM [Tickets].[TicketHistory]
            WHERE [ticketID_FK] = @daTicketID AND [actionTypeCode] = N'ARBITRATION'
            ORDER BY [ticketHistoryID] DESC;

            IF @decisionType = N'REDIRECT' AND @decisionTargetDSDID_FK IS NOT NULL
            BEGIN
                UPDATE [Tickets].[Ticket]
                SET [currentDSDID_FK] = @decisionTargetDSDID_FK
                  , [ticketStatusID_FK] = ISNULL(@daPrevStatus, @daOldStatus)
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @daTicketID;

                INSERT INTO [Tickets].[CatalogRoutingChangeLog]
                ( [serviceID_FK], [idaraID_FK], [oldRoutingRuleID_FK], [newRoutingRuleID_FK]
                , [changeReason], [sourceArbitrationCaseID_FK], [approvedByUserID]
                , [effectiveFrom] )
                SELECT t.[serviceID_FK], t.[idaraID_FK], NULL, NULL
                , @decisionNotes, @arbitrationCaseID, @performerUserID
                , GETDATE()
                FROM [Tickets].[Ticket] t WHERE t.[ticketID] = @daTicketID;
            END
            ELSE
            BEGIN
                UPDATE [Tickets].[Ticket]
                SET [ticketStatusID_FK] = ISNULL(@daPrevStatus, @daOldStatus)
                  , [entryData] = @entryData
                  , [hostName]  = @hostName
                WHERE [ticketID] = @daTicketID;
            END

            UPDATE [Tickets].[TicketPauseSession]
            SET [pauseEnd] = GETDATE(), [ticketPauseSessionActive] = 0
            WHERE [ticketID_FK] = @daTicketID AND [relatedArbitrationCaseID_FK] = @arbitrationCaseID
              AND [pauseEnd] IS NULL;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @daTicketID, @idaraID_FK, N'ARBITRATION_DECIDED', @daOldStatus, ISNULL(@daPrevStatus, @daOldStatus)
            , @daOldDSD, @decisionTargetDSDID_FK, NULL, NULL
            , @performerUserID, ISNULL(@decisionNotes, N'تم اتخاذ قرار التحكيم'), COALESCE(@notes_A, ISNULL(@decisionNotes, N'تم اتخاذ قرار التحكيم')), @entryData, @hostName );

            SET @Note = N'{"arbitrationCaseID":"' + CAST(@arbitrationCaseID AS NVARCHAR(20))
                + N'","decisionType":"' + ISNULL(@decisionType, N'') + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ArbitrationCase]', N'DECIDE_ARBITRATION', @arbitrationCaseID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم اتخاذ قرار التحكيم بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- CANCEL_ARBITRATION
        ----------------------------------------------------------------
        ELSE IF @Action = N'CANCEL_ARBITRATION'
        BEGIN
            IF @arbitrationCaseID IS NULL
            BEGIN ;THROW 50001, N'معرف قضية التحكيم مطلوب', 1; END

            DECLARE @caTicketID BIGINT;
            SELECT @caTicketID = [ticketID_FK]
            FROM [Tickets].[ArbitrationCase]
            WHERE [arbitrationCaseID] = @arbitrationCaseID AND [arbitrationStatus] = N'OPEN' AND [arbitrationCaseActive] = 1;

            IF @caTicketID IS NULL
            BEGIN ;THROW 50001, N'لم يتم العثور على قضية تحكيم مفتوحة', 1; END

            UPDATE [Tickets].[ArbitrationCase]
            SET [arbitrationStatus] = N'CANCELLED'
              , [decisionNotes] = ISNULL(@decisionNotes, N'Cancelled')
              , [entryData] = @entryData
              , [hostName]  = ISNULL(ISNULL([hostName],N'') + N',' + [hostName], [hostName])
            WHERE [arbitrationCaseID] = @arbitrationCaseID;

            DECLARE @caOldStatus INT;
            SELECT @caOldStatus = [ticketStatusID_FK] FROM [Tickets].[Ticket] WHERE [ticketID] = @caTicketID;

            DECLARE @caPrevStatus INT;
            SELECT TOP 1 @caPrevStatus = [oldStatusID_FK]
            FROM [Tickets].[TicketHistory]
            WHERE [ticketID_FK] = @caTicketID AND [actionTypeCode] = N'ARBITRATION'
            ORDER BY [ticketHistoryID] DESC;

            UPDATE [Tickets].[Ticket]
            SET [ticketStatusID_FK] = ISNULL(@caPrevStatus, @caOldStatus)
              , [entryData] = @entryData
              , [hostName]  = @hostName
            WHERE [ticketID] = @caTicketID;

            UPDATE [Tickets].[TicketPauseSession]
            SET [pauseEnd] = GETDATE(), [ticketPauseSessionActive] = 0
            WHERE [ticketID_FK] = @caTicketID AND [relatedArbitrationCaseID_FK] = @arbitrationCaseID
              AND [pauseEnd] IS NULL;

            INSERT INTO [Tickets].[TicketHistory]
            ( [ticketID_FK], [idaraID_FK], [actionTypeCode], [oldStatusID_FK], [newStatusID_FK]
            , [oldDSDID_FK], [newDSDID_FK], [oldAssignedUserID], [newAssignedUserID]
            , [performerUserID], [notes], [notes_A], [entryData], [hostName] )
            VALUES
            ( @caTicketID, @idaraID_FK, N'ARBITRATION_CANCELLED', @caOldStatus, ISNULL(@caPrevStatus, @caOldStatus)
            , NULL, NULL, NULL, NULL
            , @performerUserID, ISNULL(@notes, N'تم إلغاء التحكيم'), COALESCE(@notes_A, ISNULL(@notes, N'تم إلغاء التحكيم')), @entryData, @hostName );

            SET @Note = N'{"arbitrationCaseID":"' + CAST(@arbitrationCaseID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[ArbitrationCase]', N'CANCEL_ARBITRATION', @arbitrationCaseID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم إلغاء التحكيم' AS Message_;
        END

        ----------------------------------------------------------------
        -- UPLOAD_ATTACHMENT
        ----------------------------------------------------------------
        ELSE IF @Action = N'UPLOAD_ATTACHMENT'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف التذكرة مطلوب', 1; END
            IF NULLIF(LTRIM(RTRIM(@fileName)), N'') IS NULL
            BEGIN ;THROW 50001, N'اسم الملف مطلوب', 1; END
            IF NULLIF(LTRIM(RTRIM(@storedFileName)), N'') IS NULL
            BEGIN ;THROW 50001, N'اسم الملف المخزن مطلوب', 1; END
            IF NULLIF(LTRIM(RTRIM(@filePath)), N'') IS NULL
            BEGIN ;THROW 50001, N'مسار الملف مطلوب', 1; END

            IF NOT EXISTS (SELECT 1 FROM [Tickets].[Ticket] WHERE [ticketID] = @ticketID AND [ticketActive] = 1)
            BEGIN ;THROW 50001, N'لم يتم العثور على تذكرة نشطة', 1; END

            INSERT INTO [Tickets].[TicketAttachment]
            ( [ticketID_FK], [idaraID_FK], [fileName], [storedFileName], [filePath]
            , [fileSizeBytes], [contentType], [uploadedByUserID], [attachmentType]
            , [ticketAttachmentActive], [entryData], [hostName] )
            VALUES
            ( @ticketID, @idaraID_FK, @fileName, @storedFileName, @filePath
            , @fileSizeBytes, @contentType, @performerUserID, @attachmentType
            , 1, @entryData, @hostName );

            SET @NewID = SCOPE_IDENTITY();

            SET @Note = N'{"ticketAttachmentID":"' + CAST(@NewID AS NVARCHAR(20))
                + N'","ticketID":"' + CAST(@ticketID AS NVARCHAR(20))
                + N'","fileName":"' + ISNULL(@fileName, N'') + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[TicketAttachment]', N'UPLOAD_ATTACHMENT', @NewID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم رفع المرفق بنجاح' AS Message_;
        END

        ----------------------------------------------------------------
        -- DELETE_ATTACHMENT
        ----------------------------------------------------------------
        ELSE IF @Action = N'DELETE_ATTACHMENT'
        BEGIN
            IF @ticketID IS NULL
            BEGIN ;THROW 50001, N'معرف المرفق (الممرر كمعرف التذكرة) مطلوب', 1; END

            IF NOT EXISTS (SELECT 1 FROM [Tickets].[TicketAttachment]
                           WHERE [ticketAttachmentID] = @ticketID AND [ticketAttachmentActive] = 1)
            BEGIN ;THROW 50001, N'لم يتم العثور على مرفق نشط', 1; END

            UPDATE [Tickets].[TicketAttachment]
            SET [ticketAttachmentActive] = 0
              , [entryData] = @entryData
              , [hostName]  = ISNULL(ISNULL([hostName],N'') + N',' + [hostName], [hostName])
            WHERE [ticketAttachmentID] = @ticketID;

            SET @Note = N'{"ticketAttachmentID":"' + CAST(@ticketID AS NVARCHAR(20)) + N'"}';
            INSERT INTO dbo.AuditLog (TableName, ActionType, RecordID, PerformedBy, Notes)
            VALUES (N'[Tickets].[TicketAttachment]', N'DELETE_ATTACHMENT', @ticketID, @entryData, @Note);

            SELECT 1 AS IsSuccessful, N'تم حذف المرفق' AS Message_;
        END

        ----------------------------------------------------------------
        -- Unknown Action
        ----------------------------------------------------------------
        ELSE
        BEGIN
            ;THROW 50001, N'نوع الإجراء غير معروف في TicketSP', 1;
        END

        IF @tc = 0 COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        ;THROW;
    END CATCH
END



GO
