/****** Object:  StoredProcedure [VIC].[Custody_Close_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [VIC].[Custody_Close_SP]
(
      @vehicleWithUsersID INT
    , @endDate            DATETIME = NULL
    , @note               NVARCHAR(2000) = NULL
    , @entryData          NVARCHAR(40)
    , @hostName           NVARCHAR(400)
    , @idaraID_FK         NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;
    DECLARE @ED DATETIME = ISNULL(@endDate, GETDATE());

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- ADDED (Audit)
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @vehicleWithUsersID IS NULL OR @vehicleWithUsersID <= 0
            THROW 50001, N'vehicleWithUsersID مطلوب', 1;

        -- تحقق وجود العهدة وأنها نشطة
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.vehicleWithUsers w
            WHERE w.vehicleWithUsersID = @vehicleWithUsersID
              AND w.endDate IS NULL
        )
            THROW 50001, N'العهدة غير موجودة أو مغلقة مسبقًا', 1;

        -- فلترة الإدارة عبر المركبة
        IF EXISTS
        (
            SELECT 1
            FROM VIC.vehicleWithUsers w
            INNER JOIN VIC.Vehicles v
                ON v.chassisNumber = w.chassisNumber_FK
            WHERE w.vehicleWithUsersID = @vehicleWithUsersID
              AND (@IdaraID_BIG IS NOT NULL AND v.IdaraID_FK <> @IdaraID_BIG)
        )
            THROW 50001, N'العهدة لا تتبع هذه الإدارة', 1;

        IF @tc = 0 BEGIN TRAN;

        UPDATE VIC.vehicleWithUsers
        SET
              endDate   = @ED
            , note      = CASE WHEN @note IS NULL THEN note ELSE @note END
            , entryDate = GETDATE()
            , entryData = @entryData
            , hostName  = @hostName
        WHERE vehicleWithUsersID = @vehicleWithUsersID
          AND endDate IS NULL;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم إغلاق العهدة', 1; -- CHANGED (50002)

        -- ADDED (AuditLog)
        SET @Note_Audit = N'{'
            + N'"vehicleWithUsersID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleWithUsersID), '') + N'"'
            + N',"endDate": "' + ISNULL(CONVERT(NVARCHAR(MAX), @ED, 121), '') + N'"'
            + N',"idaraID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
            + N',"note": "' + ISNULL(CONVERT(NVARCHAR(MAX), @note), '') + N'"'
            + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[vehicleWithUsers]'
            , N'UPDATE'
            , @vehicleWithUsersID
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT CAST(1 AS BIT) AS IsSuccessful, N'تم إغلاق العهدة' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END;
GO
/****** Object:  StoredProcedure [VIC].[Custody_Create_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [VIC].[Custody_Create_SP]
(
      @chassisNumber   NVARCHAR(100)
    , @userID_FK        BIGINT
    , @startDate        DATETIME = NULL
    , @note             NVARCHAR(2000) = NULL
    , @entryData        NVARCHAR(40)
    , @hostName         NVARCHAR(400)
    , @idaraID_FK       NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');
    DECLARE @SD DATETIME = ISNULL(@startDate, GETDATE());

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, @IdaraID_BIG);

    -- ADDED (Audit)
    DECLARE
          @Note_Audit NVARCHAR(MAX) = NULL
        , @NewID_Audit INT = NULL;

    BEGIN TRY
        IF @CH IS NULL
            THROW 50001, N'chassisNumber مطلوب', 1;

        IF @userID_FK IS NULL OR @userID_FK <= 0
            THROW 50001, N'userID_FK مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        IF @IdaraID_INT IS NULL
            THROW 50001, N'idaraID_FK غير صحيح (لا يمكن تحويله إلى INT لسsnapshot)', 1;

        -- تحقق وجود المركبة ضمن نفس الإدارة
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND v.IdaraID_FK = @IdaraID_BIG
        )
            THROW 50001, N'المركبة غير موجودة أو لا تتبع الإدارة', 1;

        -- منع إذا خارج الخدمة أو إتلاف نهائي
        IF EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND v.IdaraID_FK = @IdaraID_BIG
              AND v.vehicleStatusID_FK IN (261, 262)
        )
            THROW 50001, N'لا يمكن إنشاء عهدة: المركبة خارج الخدمة أو مُتلفة نهائيًا', 1;

        -- منع ازدواج العهدة داخل نفس الإدارة (Snapshot)
        IF EXISTS
        (
            SELECT 1
            FROM VIC.vehicleWithUsers w
            WHERE w.chassisNumber_FK = @CH
              AND w.endDate IS NULL
              AND ISNULL(w.IdaraID_Snapshot, -1) = @IdaraID_INT
        )
            THROW 50001, N'يوجد عهدة نشطة على المركبة بالفعل داخل نفس الإدارة', 1;

        IF @tc = 0 BEGIN TRAN;

        INSERT INTO VIC.vehicleWithUsers
        (
              userID_FK
            , startDate
            , endDate
            , note
            , entryDate
            , entryData
            , hostName
            , chassisNumber_FK
            , OrgSnapshotDate
            , IdaraID_Snapshot
        )
        VALUES
        (
              @userID_FK
            , @SD
            , NULL
            , @note
            , GETDATE()
            , @entryData
            , @hostName
            , @CH
            , GETDATE()
            , @IdaraID_INT
        );

        SET @NewID_Audit = CONVERT(INT, SCOPE_IDENTITY());
        IF @NewID_Audit IS NULL OR @NewID_Audit <= 0
            THROW 50002, N'فشل إنشاء العهدة', 1; -- CHANGED (50002)

        -- ADDED (AuditLog)
        SET @Note_Audit = N'{'
            + N'"vehicleWithUsersID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID_Audit), '') + N'"'
            + N',"chassisNumber": "' + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
            + N',"userID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @userID_FK), '') + N'"'
            + N',"startDate": "' + ISNULL(CONVERT(NVARCHAR(MAX), @SD, 121), '') + N'"'
            + N',"idaraID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
            + N',"IdaraID_Snapshot": "' + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_INT), '') + N'"'
            + N',"note": "' + ISNULL(CONVERT(NVARCHAR(MAX), @note), '') + N'"'
            + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[vehicleWithUsers]'
            , N'INSERT'
            , ISNULL(@NewID_Audit, 0)
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT CAST(1 AS BIT) AS IsSuccessful, N'تم إنشاء العهدة' AS Message_, @NewID_Audit AS vehicleWithUsersID;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END;
GO
/****** Object:  StoredProcedure [VIC].[Custody_Current_ByUser_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [VIC].[Custody_Current_ByUser_DL]
(
      @userID     INT
    , @idaraID_FK NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @userID IS NULL OR @userID <= 0
    BEGIN
        THROW 50001, N'userID مطلوب', 1;
    END

    DECLARE @IdaraID_BIG BIGINT = TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    SELECT
          vw.vehicleWithUsersID
        , vw.chassisNumber_FK
        , vw.userID_FK
        , vw.RequestID_FK
        , vw.startDate
        , vw.endDate
        , vw.note
        , vw.entryDate
        , vw.entryData
        , vw.hostName

        /* Snapshot */
        , vw.GeneralNo_Snapshot
        , vw.UserFullName_Snapshot
        , vw.DSDID_Snapshot
        , vw.OrganizationName_Snap
        , vw.IdaraName_Snap
        , vw.DeptID_Snapshot
        , vw.DeptName_Snapshot
        , vw.SectionID_Snapshot
        , vw.SectionName_Snapshot
        , vw.DivisonName_Snap
        , vw.OrgSnapshotDate
        , vw.IdaraID_Snapshot

        /* Current User */
        , ut.fno           AS GeneralNo_Current
        , ut.IDNumber      AS NationalID_Current
        , ut.mobileNo      AS MobileNo_Current
        , CONCAT_WS(N' ', ut.fristName_A, ut.secondName_A, ut.thirdName_A, ut.lastName_A) AS UserFullName_A_Current
        , CONCAT_WS(N' ', ut.fristName_E, ut.secondName_E, ut.thirdName_E, ut.lastName_E) AS UserFullName_E_Current
        , ut.dsdID_FK      AS DSDID_Current

        /* Current Org */
        , fs.OrganizationName AS OrganizationName_Current
        , fs.IdaraName        AS IdaraName_Current
        , fs.DepartmentName   AS DepartmentName_Current
        , fs.SectionName      AS SectionName_Current
        , fs.DivisonName      AS DivisonName_Current
    FROM VIC.vehicleWithUsers AS vw
    LEFT JOIN DATACORE.dbo.UserTemp AS ut
        ON ut.userID_FK = vw.userID_FK
    LEFT JOIN DATACORE.dbo.V_GetFullStructureForDSD AS fs
        ON fs.DSDID = ut.dsdID_FK
    WHERE vw.endDate IS NULL
      AND vw.userID_FK = @userID
      AND (
            @IdaraID_BIG IS NULL
            OR vw.IdaraID_Snapshot = TRY_CONVERT(INT, @IdaraID_BIG)
          )
    ORDER BY vw.startDate DESC;
END
GO
/****** Object:  StoredProcedure [VIC].[Custody_History_ByUser_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [VIC].[Custody_History_ByUser_DL]
(
      @userID      INT
    , @fromDate    DATETIME = NULL
    , @toDate      DATETIME = NULL
    , @pageNumber  INT = 1
    , @pageSize    INT = 50
    , @idaraID_FK  NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    BEGIN TRY

        IF @tc = 0
            BEGIN TRAN;

        /* ===== Business Validation مثل المثال ===== */

        IF @userID IS NULL OR @userID <= 0
        BEGIN
            ;THROW 50001, N'userID مطلوب', 1;
        END

        DECLARE @P  INT = CASE WHEN @pageNumber IS NULL OR @pageNumber < 1 THEN 1 ELSE @pageNumber END;
        DECLARE @PS INT = CASE WHEN @pageSize IS NULL OR @pageSize < 1 OR @pageSize > 200 THEN 50 ELSE @pageSize END;
        DECLARE @Skip INT = (@P - 1) * @PS;

        SELECT
              vw.vehicleWithUsersID
            , vw.chassisNumber_FK
            , vw.userID_FK
            , vw.RequestID_FK
            , vw.startDate
            , vw.endDate
            , vw.note
            , vw.entryDate
            , vw.entryData
            , vw.hostName

            /* Snapshot */
            , vw.GeneralNo_Snapshot
            , vw.UserFullName_Snapshot
            , vw.DSDID_Snapshot
            , vw.OrganizationName_Snap
            , vw.IdaraName_Snap
            , vw.DeptID_Snapshot
            , vw.DeptName_Snapshot
            , vw.SectionID_Snapshot
            , vw.SectionName_Snapshot
            , vw.DivisonName_Snap
            , vw.OrgSnapshotDate
            , vw.IdaraID_Snapshot

            /* Current User */
            , ut.fno           AS GeneralNo_Current
            , ut.IDNumber      AS NationalID_Current
            , ut.mobileNo      AS MobileNo_Current
            , CONCAT_WS(N' ', ut.fristName_A, ut.secondName_A, ut.thirdName_A, ut.lastName_A) AS UserFullName_A_Current
            , CONCAT_WS(N' ', ut.fristName_E, ut.secondName_E, ut.thirdName_E, ut.lastName_E) AS UserFullName_E_Current
            , ut.dsdID_FK      AS DSDID_Current

            /* Current Org */
            , fs.OrganizationName AS OrganizationName_Current
            , fs.IdaraName        AS IdaraName_Current
            , fs.DepartmentName   AS DepartmentName_Current
            , fs.SectionName      AS SectionName_Current
            , fs.DivisonName      AS DivisonName_Current
        FROM VIC.vehicleWithUsers AS vw
        LEFT JOIN DATACORE.dbo.UserTemp AS ut
            ON ut.userID_FK = vw.userID_FK
        LEFT JOIN DATACORE.dbo.V_GetFullStructureForDSD AS fs
            ON fs.DSDID = ut.dsdID_FK
        WHERE vw.userID_FK = @userID
          AND (@fromDate IS NULL OR vw.startDate >= @fromDate)
          AND (@toDate   IS NULL OR vw.startDate < DATEADD(DAY, 1, @toDate))
          AND (
                @IdaraID_BIG IS NULL
                OR vw.IdaraID_Snapshot = TRY_CONVERT(INT, @IdaraID_BIG)
              )
        ORDER BY
            vw.startDate DESC,
            vw.entryDate DESC
        OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;

        IF @tc = 0
            COMMIT;

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;

        ;THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[Custody_History_ByVehicle_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع تاريخ العهد (الحالية والسابقة) لمركبة محددة حسب chassisNumber مع Paging،
   مع إمكانية فلترة النتائج بتاريخ البداية (From/To)، وإظهار Snapshot + البيانات الحالية للمستخدم والهيكل التنظيمي.
   Type: READ (LIST)
========================================================= */

CREATE   PROCEDURE [VIC].[Custody_History_ByVehicle_DL]
(
      @chassisNumber NVARCHAR(100)
    , @fromDate      DATETIME = NULL
    , @toDate        DATETIME = NULL
    , @pageNumber    INT = 1
    , @pageSize      INT = 50
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');
    IF @CH IS NULL
    BEGIN
        THROW 50001, N'chassisNumber مطلوب', 1;
    END

    DECLARE @P  INT = CASE WHEN @pageNumber IS NULL OR @pageNumber < 1 THEN 1 ELSE @pageNumber END;
    DECLARE @PS INT = CASE WHEN @pageSize IS NULL OR @pageSize < 1 OR @pageSize > 200 THEN 50 ELSE @pageSize END;
    DECLARE @Skip INT = (@P - 1) * @PS;

    SELECT
          vw.vehicleWithUsersID
        , vw.chassisNumber_FK
        , vw.userID_FK
        , vw.RequestID_FK
        , vw.startDate
        , vw.endDate
        , vw.note
        , vw.entryDate
        , vw.entryData
        , vw.hostName

        /* Snapshot */
        , vw.GeneralNo_Snapshot
        , vw.UserFullName_Snapshot
        , vw.DSDID_Snapshot
        , vw.OrganizationName_Snap
        , vw.IdaraName_Snap
        , vw.DeptID_Snapshot
        , vw.DeptName_Snapshot
        , vw.SectionID_Snapshot
        , vw.SectionName_Snapshot
        , vw.DivisonName_Snap
        , vw.OrgSnapshotDate

        /* Current User */
        , ut.fno           AS GeneralNo_Current
        , ut.IDNumber      AS NationalID_Current
        , ut.mobileNo      AS MobileNo_Current
        , CONCAT_WS(N' ', ut.fristName_A, ut.secondName_A, ut.thirdName_A, ut.lastName_A) AS UserFullName_A_Current
        , CONCAT_WS(N' ', ut.fristName_E, ut.secondName_E, ut.thirdName_E, ut.lastName_E) AS UserFullName_E_Current
        , ut.dsdID_FK      AS DSDID_Current

        /* Current Org */
        , fs.OrganizationName AS OrganizationName_Current
        , fs.IdaraName        AS IdaraName_Current
        , fs.DepartmentName   AS DepartmentName_Current
        , fs.SectionName      AS SectionName_Current
        , fs.DivisonName      AS DivisonName_Current
    FROM VIC.vehicleWithUsers AS vw
    LEFT JOIN DATACORE.dbo.UserTemp AS ut
        ON ut.userID_FK = vw.userID_FK
    LEFT JOIN DATACORE.dbo.V_GetFullStructureForDSD AS fs
        ON fs.DSDID = ut.dsdID_FK
    WHERE vw.chassisNumber_FK = @CH
      AND (@fromDate IS NULL OR vw.startDate >= @fromDate)
      AND (@toDate   IS NULL OR vw.startDate <  DATEADD(DAY, 1, @toDate))
    ORDER BY
        vw.startDate DESC,
        vw.entryDate DESC
    OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;
END
GO
/****** Object:  StoredProcedure [VIC].[Custody_Transfer_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [VIC].[Custody_Transfer_SP]
(
      @chassisNumber   NVARCHAR(100)
    , @toUserID_FK      BIGINT
    , @transferDate     DATETIME = NULL
    , @note             NVARCHAR(2000) = NULL
    , @entryData        NVARCHAR(40)
    , @hostName         NVARCHAR(400)
    , @idaraID_FK       NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');
    DECLARE @TD DATETIME = ISNULL(@transferDate, GETDATE());

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- ADDED (Audit)
    DECLARE
          @Note_Audit NVARCHAR(MAX) = NULL
        , @NewID_Audit INT = NULL;

    BEGIN TRY
        IF @CH IS NULL
            THROW 50001, N'chassisNumber مطلوب', 1;

        IF @toUserID_FK IS NULL OR @toUserID_FK <= 0
            THROW 50001, N'toUserID_FK مطلوب', 1;

        -- تحقق المركبة + فلتر الإدارة
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
        )
            THROW 50001, N'المركبة غير موجودة أو لا تتبع الإدارة', 1;

        -- منع إذا خارج الخدمة أو إتلاف نهائي
        IF EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
              AND v.vehicleStatusID_FK IN (261, 262)
        )
            THROW 50001, N'لا يمكن نقل العهدة: المركبة خارج الخدمة أو مُتلفة نهائيًا', 1;

        -- لازم فيه عهدة نشطة ليتم نقلها
        DECLARE @CurrentID INT;

        SELECT TOP (1) @CurrentID = w.vehicleWithUsersID
        FROM VIC.vehicleWithUsers w
        WHERE w.chassisNumber_FK = @CH
          AND w.endDate IS NULL
        ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC;

        IF @CurrentID IS NULL
            THROW 50001, N'لا توجد عهدة نشطة لنقلها', 1;

        IF @tc = 0 BEGIN TRAN;

        -- 1) إغلاق العهدة الحالية
        UPDATE VIC.vehicleWithUsers
        SET
              endDate   = @TD
            , note      = CASE WHEN @note IS NULL THEN note ELSE @note END
            , entryDate = GETDATE()
            , entryData = @entryData
            , hostName  = @hostName
        WHERE vehicleWithUsersID = @CurrentID
          AND endDate IS NULL;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'فشل إغلاق العهدة الحالية', 1; -- CHANGED (50002)

        -- 2) فتح عهدة جديدة
        INSERT INTO VIC.vehicleWithUsers
        (
              userID_FK
            , startDate
            , endDate
            , note
            , entryDate
            , entryData
            , hostName
            , chassisNumber_FK

            -- Snapshot (جزئي)
            , OrgSnapshotDate
            , IdaraID_Snapshot
        )
        VALUES
        (
              @toUserID_FK
            , @TD
            , NULL
            , @note
            , GETDATE()
            , @entryData
            , @hostName
            , @CH
            , GETDATE()
            , TRY_CONVERT(INT, @IdaraID_BIG)
        );

        SET @NewID_Audit = CONVERT(INT, SCOPE_IDENTITY());
        IF @NewID_Audit IS NULL OR @NewID_Audit <= 0
            THROW 50002, N'فشل إنشاء العهدة الجديدة', 1; -- CHANGED (50002)

        -- ADDED (AuditLog)
        SET @Note_Audit = N'{'
            + N'"chassisNumber": "' + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
            + N',"transferDate": "' + ISNULL(CONVERT(NVARCHAR(MAX), @TD, 121), '') + N'"'
            + N',"toUserID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @toUserID_FK), '') + N'"'
            + N',"idaraID_FK": "' + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
            + N',"ClosedVehicleWithUsersID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @CurrentID), '') + N'"'
            + N',"NewVehicleWithUsersID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID_Audit), '') + N'"'
            + N',"note": "' + ISNULL(CONVERT(NVARCHAR(MAX), @note), '') + N'"'
            + N',"entryData": "' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName": "' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[vehicleWithUsers]'
            , N'TRANSFER'
            , ISNULL(@NewID_Audit, 0)
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT
              CAST(1 AS BIT) AS IsSuccessful
            , N'تم نقل العهدة' AS Message_
            , @CurrentID AS ClosedVehicleWithUsersID
            , @NewID_Audit AS NewVehicleWithUsersID;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END;
GO
/****** Object:  StoredProcedure [VIC].[CustodyCurrentListDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [VIC].[CustodyCurrentListDL]
(
      @userID        INT = NULL
    , @generalNo     NVARCHAR(100) = NULL
    , @chassisNumber NVARCHAR(100) = NULL
    , @pageNumber    INT = 1
    , @pageSize      INT = 50
    , @idaraID_FK    NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @P  INT = CASE WHEN @pageNumber IS NULL OR @pageNumber < 1 THEN 1 ELSE @pageNumber END;
    DECLARE @PS INT = CASE WHEN @pageSize IS NULL OR @pageSize < 1 OR @pageSize > 200 THEN 50 ELSE @pageSize END;
    DECLARE @Skip INT = (@P - 1) * @PS;

    DECLARE @GN NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@generalNo)), N'');
    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    DECLARE @IdaraID_BIG BIGINT = TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    SELECT
          vw.vehicleWithUsersID
        , vw.chassisNumber_FK
        , vw.userID_FK
        , vw.RequestID_FK
        , vw.startDate
        , vw.endDate
        , vw.note
        , vw.entryDate
        , vw.entryData
        , vw.hostName

        /* Snapshot */
        , vw.GeneralNo_Snapshot
        , vw.UserFullName_Snapshot
        , vw.DSDID_Snapshot
        , vw.OrganizationName_Snap
        , vw.IdaraName_Snap
        , vw.DeptID_Snapshot
        , vw.DeptName_Snapshot
        , vw.SectionID_Snapshot
        , vw.SectionName_Snapshot
        , vw.DivisonName_Snap
        , vw.OrgSnapshotDate
        , vw.IdaraID_Snapshot

        /* Current User */
        , ut.fno           AS GeneralNo_Current
        , ut.IDNumber      AS NationalID_Current
        , ut.mobileNo      AS MobileNo_Current
        , CONCAT_WS(N' ', ut.fristName_A, ut.secondName_A, ut.thirdName_A, ut.lastName_A) AS UserFullName_A_Current
        , CONCAT_WS(N' ', ut.fristName_E, ut.secondName_E, ut.thirdName_E, ut.lastName_E) AS UserFullName_E_Current
        , ut.dsdID_FK      AS DSDID_Current

        /* Current Org */
        , fs.OrganizationName AS OrganizationName_Current
        , fs.IdaraName        AS IdaraName_Current
        , fs.DepartmentName   AS DepartmentName_Current
        , fs.SectionName      AS SectionName_Current
        , fs.DivisonName      AS DivisonName_Current
    FROM VIC.vehicleWithUsers AS vw
    LEFT JOIN DATACORE.dbo.UserTemp AS ut
        ON ut.userID_FK = vw.userID_FK
    LEFT JOIN DATACORE.dbo.V_GetFullStructureForDSD AS fs
        ON fs.DSDID = ut.dsdID_FK
    WHERE vw.endDate IS NULL
      AND (@userID IS NULL OR vw.userID_FK = @userID)
      AND (@CH IS NULL OR vw.chassisNumber_FK = @CH)
      AND (@GN IS NULL OR ut.fno = @GN OR vw.GeneralNo_Snapshot = @GN)
      AND (
            @IdaraID_BIG IS NULL
            OR vw.IdaraID_Snapshot = TRY_CONVERT(INT, @IdaraID_BIG)
          )
    ORDER BY vw.startDate DESC
    OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;
END
GO
/****** Object:  StoredProcedure [VIC].[Dashboard_Get_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [VIC].[Dashboard_Get_DL]
(
      @onlyHasCustody         BIT = NULL
    , @onlyHasActiveInsurance BIT = NULL
    , @onlyHasDocExpiry       INT = NULL
    , @onlyHasInsExpiry       INT = NULL
    , @idaraID_FK             NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    SELECT
        d.*
    FROM VIC.V_Dashboard_VehicleStatus d
    WHERE 1 = 1
      AND (
            @onlyHasCustody IS NULL
            OR (@onlyHasCustody = 1 AND d.CurrentUserID IS NOT NULL)
            OR (@onlyHasCustody = 0 AND d.CurrentUserID IS NULL)
          )
      AND (
            @onlyHasActiveInsurance IS NULL
            OR (@onlyHasActiveInsurance = 1 AND d.ActiveInsuranceTypeID IS NOT NULL)
            OR (@onlyHasActiveInsurance = 0 AND d.ActiveInsuranceTypeID IS NULL)
          )
      AND (
            @onlyHasDocExpiry IS NULL
            OR (d.NextDocEndDate IS NOT NULL AND d.DocDaysToExpire BETWEEN 0 AND @onlyHasDocExpiry)
          )
      AND (
            @onlyHasInsExpiry IS NULL
            OR (d.ActiveInsuranceEndDate IS NOT NULL AND d.InsDaysToExpire BETWEEN 0 AND @onlyHasInsExpiry)
          )
      AND (
            @IdaraID_BIG IS NULL
            OR d.IdaraID_FK = @IdaraID_BIG
          )
    ORDER BY
        ISNULL(d.DocDaysToExpire, 999999),
        ISNULL(d.InsDaysToExpire, 999999),
        d.chassisNumber;
END
GO
/****** Object:  StoredProcedure [VIC].[Dashboard_MaintenanceDue_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   داشبورد الصيانة الدورية:
   - يعرض المركبات المستحقة أو القريبة للصيانة
   - مع حالة وجود أمر صيانة مفتوح
   Type: READ (LIST)
========================================================= */

CREATE PROCEDURE [VIC].[Dashboard_MaintenanceDue_DL]
(
      @daysAhead   INT = 7
    , @idaraID_FK  NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @Now DATE = CAST(GETDATE() AS DATE);

    SELECT
          p.PlanID
        , p.chassisNumber_FK AS chassisNumber
        , v.plateLetters
        , v.plateNumbers
        , p.periodMonths
        , p.nextDueDate

        -- كم باقي يوم
        , DATEDIFF(DAY, @Now, CAST(p.nextDueDate AS DATE)) AS DaysToDue

        -- الحالة
        , CASE 
            WHEN CAST(p.nextDueDate AS DATE) < @Now THEN N'متأخرة'
            WHEN CAST(p.nextDueDate AS DATE) <= DATEADD(DAY, @daysAhead, @Now) THEN N'قريبة'
            ELSE N'طبيعية'
          END AS DueStatus

        -- هل فيه أمر مفتوح
        , CASE 
            WHEN EXISTS
            (
                SELECT 1
                FROM VIC.VehicleMaintenance m
                WHERE m.chassisNumber_FK = p.chassisNumber_FK
                  AND m.MaintOrdTypeID_FK = 265
                  AND m.MaintOrdActive = 1
            )
            THEN 1 ELSE 0
          END AS HasOpenOrder

    FROM VIC.VehicleMaintenancePlan p
    INNER JOIN VIC.Vehicles v
        ON v.chassisNumber = p.chassisNumber_FK

    WHERE p.planActive = 1
      AND (@IdaraID_BIG IS NULL OR p.IdaraID_FK = @IdaraID_BIG)
      AND CAST(p.nextDueDate AS DATE) <= DATEADD(DAY, @daysAhead, @Now)

    ORDER BY
          p.nextDueDate ASC;
END
GO
/****** Object:  StoredProcedure [VIC].[Handover_Create_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [VIC].[Handover_Create_SP]
(
      @requestID      INT
    , @handoverTypeID INT
    , @handoverDate   DATETIME = NULL
    , @note           NVARCHAR(1000) = NULL
    , @idaraID_FK     NVARCHAR(10) = NULL
    , @entryData      NVARCHAR(40)
    , @hostName       NVARCHAR(400)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- ADDED (Audit)
    DECLARE
          @NewID INT = NULL
        , @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @requestID IS NULL OR @requestID <= 0
            THROW 50001, N'requestID مطلوب', 1;

        IF @handoverTypeID IS NULL OR @handoverTypeID <= 0
            THROW 50001, N'handoverTypeID مطلوب', 1;

        -- وجود الطلب (ومطابقة الإدارة إذا تم تمريرها)
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.VehicleTransferRequest AS r
            WHERE r.RequestID = @requestID
              AND (@IdaraID_BIG IS NULL OR r.IdaraID_FK = @IdaraID_BIG)
        )
            THROW 50001, N'طلب النقل غير موجود أو لا يتبع نفس الإدارة', 1;

        IF @tc = 0 BEGIN TRAN;

        INSERT INTO VIC.VehicleHandover
        (
              RequestID_FK
            , handOverTypeID_FK
            , handoverDate
            , note
            , IdaraID_FK
            , entryDate
            , entryData
            , hostName
        )
        VALUES
        (
              @requestID
            , @handoverTypeID
            , ISNULL(@handoverDate, GETDATE())
            , @note
            , @IdaraID_BIG
            , GETDATE()
            , @entryData
            , @hostName
        );

        SET @NewID = CONVERT(INT, SCOPE_IDENTITY());
        IF @NewID IS NULL OR @NewID <= 0
            THROW 50002, N'فشل إنشاء المحضر', 1; -- CHANGED (50002)

        -- ADDED (AuditLog)
        SET @Note_Audit = N'{'
            + N'"VehicleHandoverID": "' + ISNULL(CONVERT(NVARCHAR(MAX), @NewID), '') + N'"'
            + N',"requestID": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @requestID), '') + N'"'
            + N',"handoverTypeID": "'   + ISNULL(CONVERT(NVARCHAR(MAX), @handoverTypeID), '') + N'"'
            + N',"handoverDate": "'     + ISNULL(CONVERT(NVARCHAR(MAX), ISNULL(@handoverDate, GETDATE()), 121), '') + N'"'
            + N',"note": "'             + ISNULL(CONVERT(NVARCHAR(MAX), @note), '') + N'"'
            + N',"idaraID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
            + N',"entryData": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName": "'         + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[VehicleHandover]'
            , N'INSERT'
            , ISNULL(@NewID, 0)
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT
              CAST(1 AS BIT) AS IsSuccessful
            , N'تم إنشاء المحضر بنجاح' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[Handover_Get_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع تفاصيل محضر تسليم/استلام واحد حسب VehicleHandoverID،
   مع بيانات نوع المحضر (HandoverType) وبيانات طلب النقل المرتبط (VehicleTransferRequest).
   + التحقق من الإدارة (IdaraID_FK) بمعيار BIGINT.
   Type: READ (GET)
========================================================= */

CREATE   PROCEDURE [VIC].[Handover_Get_DL]
(
      @vehicleHandoverID INT
    , @idaraID_FK        NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    BEGIN TRY

        IF @tc = 0 BEGIN TRAN;

        /* ===== Business Validation ===== */

        IF @vehicleHandoverID IS NULL OR @vehicleHandoverID <= 0
            THROW 50001, N'vehicleHandoverID مطلوب', 1;

        IF NOT EXISTS (
            SELECT 1
            FROM VIC.VehicleHandover h
            WHERE h.VehicleHandoverID = @vehicleHandoverID
        )
            THROW 50001, N'المحضر غير موجود', 1;

        IF @IdaraID_BIG IS NOT NULL
        BEGIN
            IF NOT EXISTS (
                SELECT 1
                FROM VIC.VehicleHandover h
                WHERE h.VehicleHandoverID = @vehicleHandoverID
                  AND h.IdaraID_FK = @IdaraID_BIG
            )
                THROW 50001, N'المحضر لا يتبع نفس الإدارة', 1;
        END

        /* ===== Query ===== */

        SELECT
              h.VehicleHandoverID
            , h.RequestID_FK
            , h.handOverTypeID_FK
            , h.handoverDate
            , h.note
            , h.entryDate
            , h.entryData
            , h.hostName
            , h.IdaraID_FK

            , t.handOverTypeName_A
            , t.handOverTypeName_E
            , t.active AS handOverTypeActive

            , r.RequestID
            , r.chassisNumber_FK
            , r.fromUserID_FK
            , r.toUserID_FK
            , r.deptID_FK
            , r.active AS RequestActive
            , r.entryDate AS RequestEntryDate
        FROM VIC.VehicleHandover AS h
        INNER JOIN VIC.HandoverType AS t
            ON t.handOverTypeID = h.handOverTypeID_FK
        INNER JOIN VIC.VehicleTransferRequest AS r
            ON r.RequestID = h.RequestID_FK
        WHERE h.VehicleHandoverID = @vehicleHandoverID;

        IF @tc = 0 COMMIT;

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[Handover_List_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع قائمة محاضر التسليم/الاستلام (Handover) مع Paging،
   مع فلاتر اختيارية حسب RequestID أو نوع المحضر أو نطاق تاريخ المحضر، وإظهار بيانات الطلب المرتبط ونوع المحضر.
   + إضافة فلتر الإدارة (IdaraID_FK) بمعيار BIGINT.
   + تحقق مدخلات Paging (pageNumber/pageSize) بأسلوب THROW.
   Type: READ (LIST)
========================================================= */

CREATE     PROCEDURE [VIC].[Handover_List_DL]
(
      @requestID      INT = NULL
    , @handoverTypeID INT = NULL
    , @fromDate       DATETIME = NULL
    , @toDate         DATETIME = NULL
    , @pageNumber     INT = 1
    , @pageSize       INT = 50
    , @idaraID_FK     NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    BEGIN TRY

        IF @tc = 0 BEGIN TRAN;

        /* ===== Business Validation مثل المثال ===== */
        IF @pageNumber IS NULL OR @pageNumber < 1
            THROW 50001, N'pageNumber غير صحيح', 1;

        IF @pageSize IS NULL OR @pageSize < 1 OR @pageSize > 200
            THROW 50001, N'pageSize غير صحيح', 1;

        DECLARE @P  INT = @pageNumber;
        DECLARE @PS INT = @pageSize;
        DECLARE @Skip INT = (@P - 1) * @PS;

        SELECT
              h.VehicleHandoverID
            , h.RequestID_FK
            , h.handOverTypeID_FK
            , h.handoverDate
            , h.note
            , h.entryDate
            , h.entryData
            , h.IdaraID_FK

            , t.handOverTypeName_A
            , t.handOverTypeName_E

            , r.chassisNumber_FK
            , r.fromUserID_FK
            , r.toUserID_FK
            , r.deptID_FK
        FROM VIC.VehicleHandover AS h
        INNER JOIN VIC.HandoverType AS t
            ON t.handOverTypeID = h.handOverTypeID_FK
        INNER JOIN VIC.VehicleTransferRequest AS r
            ON r.RequestID = h.RequestID_FK
        WHERE 1 = 1
          AND (@requestID IS NULL OR h.RequestID_FK = @requestID)
          AND (@handoverTypeID IS NULL OR h.handOverTypeID_FK = @handoverTypeID)
          AND (@fromDate IS NULL OR h.handoverDate >= @fromDate)
          AND (@toDate   IS NULL OR h.handoverDate <  DATEADD(DAY, 1, @toDate))
          AND (@IdaraID_BIG IS NULL OR h.IdaraID_FK = @IdaraID_BIG)
        ORDER BY
            h.handoverDate DESC,
            h.VehicleHandoverID DESC
        OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;

        IF @tc = 0 COMMIT;

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[Handover_Print_Get_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع بيانات محضر تسليم/استلام جاهزة للطباعة (صف واحد) حسب vehicleHandoverID،
   وتشمل بيانات المحضر + الطلب/المركبة + بيانات الطرفين (من/إلى) من UserTemp والهيكل التنظيمي لكل طرف (إن وجد).
   + إضافة تحقق/فلتر الإدارة (IdaraID_FK) بمعيار BIGINT.
   Type: READ (PRINT/GET)
========================================================= */

CREATE   PROCEDURE [VIC].[Handover_Print_Get_DL]
(
      @vehicleHandoverID INT
    , @idaraID_FK        NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    BEGIN TRY

        IF @tc = 0 BEGIN TRAN;

        /* ===== Business Validation مثل المثال ===== */

        IF @vehicleHandoverID IS NULL OR @vehicleHandoverID <= 0
            THROW 50001, N'vehicleHandoverID مطلوب', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.VehicleHandover h
            WHERE h.VehicleHandoverID = @vehicleHandoverID
        )
            THROW 50001, N'المحضر غير موجود', 1;

        IF @IdaraID_BIG IS NOT NULL
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM VIC.VehicleHandover h
                WHERE h.VehicleHandoverID = @vehicleHandoverID
                  AND h.IdaraID_FK = @IdaraID_BIG
            )
                THROW 50001, N'المحضر لا يتبع نفس الإدارة', 1;
        END

        /* ===== Query ===== */

        SELECT
            /* (A) بيانات المحضر */
              h.VehicleHandoverID
            , h.handoverDate
            , h.note
            , h.IdaraID_FK
            , t.handOverTypeName_A
            , t.handOverTypeName_E

            /* (B) بيانات الطلب/المركبة */
            , r.RequestID
            , r.chassisNumber_FK
            , r.deptID_FK

            /* (C) بيانات الأطراف (UserTemp) */
            , r.fromUserID_FK AS FromUserID
            , CONCAT_WS(N' ', uf.fristName_A, uf.secondName_A, uf.thirdName_A, uf.lastName_A) AS FromUserName_A
            , uf.fno       AS FromFno
            , uf.mobileNo  AS FromMobileNo
            , uf.IDNumber  AS FromIDNumber

            , r.toUserID_FK AS ToUserID
            , CONCAT_WS(N' ', ut.fristName_A, ut.secondName_A, ut.thirdName_A, ut.lastName_A) AS ToUserName_A
            , ut.fno       AS ToFno
            , ut.mobileNo  AS ToMobileNo
            , ut.IDNumber  AS ToIDNumber

            /* (D) بيانات تنظيمية اختيارية */
            , ff.OrganizationName AS From_OrganizationName
            , ff.DepartmentName   AS From_DepartmentName
            , ff.SectionName      AS From_SectionName

            , ft.OrganizationName AS To_OrganizationName
            , ft.DepartmentName   AS To_DepartmentName
            , ft.SectionName      AS To_SectionName
        FROM VIC.VehicleHandover AS h
        INNER JOIN VIC.VehicleTransferRequest AS r
            ON r.RequestID = h.RequestID_FK
        INNER JOIN VIC.HandoverType AS t
            ON t.handOverTypeID = h.handOverTypeID_FK
        LEFT JOIN DATACORE.dbo.UserTemp AS uf
            ON uf.userID_FK = r.fromUserID_FK
        LEFT JOIN DATACORE.dbo.UserTemp AS ut
            ON ut.userID_FK = r.toUserID_FK
        LEFT JOIN DATACORE.dbo.V_GetFullStructureForDSD AS ff
            ON ff.DSDID = uf.dsdID_FK
        LEFT JOIN DATACORE.dbo.V_GetFullStructureForDSD AS ft
            ON ft.DSDID = ut.dsdID_FK
        WHERE h.VehicleHandoverID = @vehicleHandoverID
          AND (@IdaraID_BIG IS NULL OR h.IdaraID_FK = @IdaraID_BIG);

        IF @tc = 0 COMMIT;

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END
GO
