/* =========================================================
   Description:
   قائمة خطط الصيانة الدورية مع فلاتر اختيارية + Paging
   Type: READ (LIST)
========================================================= */

CREATE   PROCEDURE [VIC].[MaintenancePlan_List_DL]
(
      @chassisNumber NVARCHAR(100) = NULL
    , @active        BIT = NULL
    , @pageNumber    INT = 1
    , @pageSize      INT = 50
    , @idaraID_FK    NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @P  INT = CASE WHEN @pageNumber IS NULL OR @pageNumber < 1 THEN 1 ELSE @pageNumber END;
    DECLARE @PS INT = CASE WHEN @pageSize IS NULL OR @pageSize < 1 OR @pageSize > 200 THEN 50 ELSE @pageSize END;
    DECLARE @Skip INT = (@P - 1) * @PS;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    SELECT
          p.PlanID
        , p.chassisNumber_FK
        , v.plateLetters
        , v.plateNumbers
        , p.periodMonths
        , p.nextDueDate
        , p.planActive
        , p.entryDate
        , p.entryData
        , p.hostName
    FROM VIC.VehicleMaintenancePlan p
    INNER JOIN VIC.Vehicles v
        ON v.chassisNumber = p.chassisNumber_FK
    WHERE 1 = 1
      AND (@IdaraID_BIG IS NULL OR p.IdaraID_FK = @IdaraID_BIG)
      AND (@CH IS NULL OR p.chassisNumber_FK = @CH)
      AND (@active IS NULL OR p.planActive = @active)
    ORDER BY
        p.PlanID DESC
    OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;
END
GO
/****** Object:  StoredProcedure [VIC].[MaintenancePlan_SetActive_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تفعيل أو تعطيل خطة الصيانة الدورية في جدول VIC.VehicleMaintenancePlan.
   Type: WRITE (SETACTIVE)
========================================================= */

CREATE   PROCEDURE [VIC].[MaintenancePlan_SetActive_SP]
(
      @planID       INT
    , @active       BIT
    , @idaraID_FK   NVARCHAR(10) = NULL
    , @entryData    NVARCHAR(40)
    , @hostName     NVARCHAR(400)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE
          @ChassisNumber NVARCHAR(100)
        , @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY

        IF @tc = 0
            BEGIN TRAN;

        IF @planID IS NULL OR @planID <= 0
            THROW 50001, N'planID غير صحيح', 1;

        -- تحقق وجود الخطة + مطابقة الإدارة
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.VehicleMaintenancePlan p
            WHERE p.PlanID = @planID
              AND (@IdaraID_BIG IS NULL OR p.IdaraID_FK = @IdaraID_BIG)
        )
            THROW 50001, N'الخطة غير موجودة أو لا تطابق الإدارة', 1;

        -- جلب بيانات قبل التحديث (للاستخدام لاحقًا)
        SELECT
              @ChassisNumber = p.chassisNumber_FK
        FROM VIC.VehicleMaintenancePlan p
        WHERE p.PlanID = @planID;

        -- التحديث
        UPDATE VIC.VehicleMaintenancePlan
        SET
              planActive = @active
            , entryDate  = GETDATE()
            , entryData  = @entryData
            , hostName   = @hostName
        WHERE PlanID = @planID;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم تحديث أي سجل', 1;

        -- ADDED (AuditLog)
        SET @Note_Audit = N'{'
            + N'"planID": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @planID), '') + N'"'
            + N',"chassisNumber": "'+ ISNULL(CONVERT(NVARCHAR(MAX), @ChassisNumber), '') + N'"'
            + N',"active": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @active), '') + N'"'
            + N',"idaraID_FK": "'   + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
            + N',"entryData": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName": "'     + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[VehicleMaintenancePlan]'
            , N'SETACTIVE'
            , @planID
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0
            COMMIT;

        SELECT 1 AS IsSuccessful,
               CASE WHEN @active = 1 
                    THEN N'تم تفعيل الخطة بنجاح'
                    ELSE N'تم تعطيل الخطة بنجاح'
               END AS Message_;

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END
