/* =========================================================
   Description:
   إضافة/تعديل بند داخل قالب الصيانة في جدول VIC.MaintenanceTemplate.
   Type: WRITE (UPSERT)
========================================================= */

CREATE   PROCEDURE [VIC].[MaintenanceTemplate_Upsert_SP]
(
      @TemplateID         INT = NULL
    , @MaintOrdTypeID_FK  INT
    , @typesID_FK         INT
    , @TemplateOrder      INT = 1
    , @active             BIT = 1
    , @entryData          NVARCHAR(40) = NULL
    , @hostName           NVARCHAR(400) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE
          @ActionType NVARCHAR(20) = NULL
        , @Note_Audit NVARCHAR(MAX) = NULL
        , @NewID INT = NULL;

    BEGIN TRY
        IF @tc = 0
            BEGIN TRAN;

        IF @MaintOrdTypeID_FK IS NULL OR @MaintOrdTypeID_FK <= 0
            THROW 50001, N'MaintOrdTypeID_FK مطلوب', 1;

        IF @typesID_FK IS NULL OR @typesID_FK <= 0
            THROW 50001, N'typesID_FK مطلوب', 1;

        IF @TemplateOrder IS NULL OR @TemplateOrder <= 0
            THROW 50001, N'TemplateOrder مطلوب ويجب أن يكون أكبر من صفر', 1;

        -- تحقق من نوع أمر الصيانة (من Parent 264)
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.TypesRoot t
            WHERE t.typesID = @MaintOrdTypeID_FK
              AND t.typesRoot_ParentID = 264
              AND ISNULL(t.typesActive, 0) = 1
        )
            THROW 50001, N'نوع أمر الصيانة غير صحيح', 1;

        -- تحقق من البند
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.TypesRoot t
            WHERE t.typesID = @typesID_FK
              AND ISNULL(t.typesActive, 0) = 1
        )
            THROW 50001, N'بند القالب غير صحيح', 1;

        IF @TemplateID IS NULL
        BEGIN
            IF EXISTS
            (
                SELECT 1
                FROM VIC.MaintenanceTemplate mt
                WHERE mt.MaintOrdTypeID_FK = @MaintOrdTypeID_FK
                  AND mt.typesID_FK = @typesID_FK
                  AND mt.templateActive = 1
            )
                THROW 50001, N'هذا البند موجود مسبقًا في القالب', 1;

            INSERT INTO VIC.MaintenanceTemplate
            (
                  MaintOrdTypeID_FK
                , typesID_FK
                , TemplateOrder
                , templateActive
                , entryDate
                , entryData
                , hostName
            )
            VALUES
            (
                  @MaintOrdTypeID_FK
                , @typesID_FK
                , @TemplateOrder
                , @active
                , GETDATE()
                , @entryData
                , @hostName
            );

            SET @TemplateID = CONVERT(INT, SCOPE_IDENTITY());

            IF @TemplateID IS NULL OR @TemplateID <= 0
                THROW 50002, N'فشل إضافة بند القالب', 1;

            SET @ActionType = N'INSERT';
        END
        ELSE
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM VIC.MaintenanceTemplate mt
                WHERE mt.TemplateID = @TemplateID
            )
                THROW 50001, N'TemplateID غير موجود للتعديل', 1;

            UPDATE VIC.MaintenanceTemplate
            SET
                  MaintOrdTypeID_FK = @MaintOrdTypeID_FK
                , typesID_FK        = @typesID_FK
                , TemplateOrder     = @TemplateOrder
                , templateActive    = @active
                , entryDate         = GETDATE()
                , entryData         = @entryData
                , hostName          = @hostName
            WHERE TemplateID = @TemplateID;

            IF @@ROWCOUNT <= 0
                THROW 50002, N'لم يتم تعديل أي سجل', 1;

            SET @ActionType = N'UPDATE';
        END

        SET @NewID = @TemplateID;
        SET @Note_Audit = N'{'
            + N'"TemplateID": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @TemplateID), '') + N'"'
            + N',"MaintOrdTypeID_FK": "'+ ISNULL(CONVERT(NVARCHAR(MAX), @MaintOrdTypeID_FK), '') + N'"'
            + N',"typesID_FK": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @typesID_FK), '') + N'"'
            + N',"TemplateOrder": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @TemplateOrder), '') + N'"'
            + N',"active": "'           + ISNULL(CONVERT(NVARCHAR(MAX), @active), '') + N'"'
            + N',"entryData": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName": "'         + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[MaintenanceTemplate]'
            , @ActionType
            , ISNULL(@NewID, 0)
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0
            COMMIT;

        SELECT 1 AS IsSuccessful, N'تم حفظ بند القالب بنجاح' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[Report_DocumentsExpiring_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تقرير وثائق المركبات التي ستنتهي خلال عدد أيام محدد (@days)،
   مع خيار تضمين الوثائق المنتهية بالفعل (@includeExpired=1) أو استبعادها.
   Type: READ (REPORT)
========================================================= */

CREATE   PROCEDURE [VIC].[Report_DocumentsExpiring_DL]
(
      @days           INT = 30
    , @includeExpired BIT = 1
    , @idaraID_FK     NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @days IS NULL OR @days < 0
        THROW 50001, N'days غير صحيح', 1;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @Today  DATE = CAST(GETDATE() AS DATE);
    DECLARE @Cutoff DATE = DATEADD(DAY, @days, @Today);

    SELECT
          d.chassisNumber_FK
        , v.plateLetters
        , v.plateNumbers
        , t.vehicleDocumentTypeName_A
        , d.vehicleDocumentNo
        , d.vehicleDocumentEndDate
        , DATEDIFF(DAY, @Today, d.vehicleDocumentEndDate) AS DaysRemaining
    FROM VIC.vehicleDocument d
    INNER JOIN VIC.VehiclesDocumentType t
        ON t.vehicleDocumentTypeID = d.vehicleDocumentTypeID_FK
    INNER JOIN VIC.Vehicles v
        ON v.chassisNumber = d.chassisNumber_FK
    WHERE d.vehicleDocumentEndDate IS NOT NULL
      AND (@IdaraID_BIG IS NULL OR d.IdaraID_FK = @IdaraID_BIG)
      AND (
            (@includeExpired = 1 AND d.vehicleDocumentEndDate <= @Cutoff)
         OR (@includeExpired = 0 AND d.vehicleDocumentEndDate BETWEEN @Today AND @Cutoff)
          )
    ORDER BY d.vehicleDocumentEndDate ASC;
END
GO
/****** Object:  StoredProcedure [VIC].[Report_InsuranceExpiring_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تقرير التأمينات التي ستنتهي خلال عدد أيام محدد (@days)،
   مع خيار تضمين المنتهي (@includeExpired) وخيار حصر النتائج على التأمينات النشطة فقط (@activeOnly).
   Type: READ (REPORT)
========================================================= */

CREATE   PROCEDURE [VIC].[Report_InsuranceExpiring_DL]
(
      @days           INT = 30
    , @includeExpired BIT = 1
    , @activeOnly     BIT = 1
    , @idaraID_FK     NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @days IS NULL OR @days < 0
        THROW 50001, N'days غير صحيح', 1;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @Today  DATE = CAST(GETDATE() AS DATE);
    DECLARE @Cutoff DATE = DATEADD(DAY, @days, @Today);

    SELECT
          i.chassisNumber_FK
        , v.plateLetters
        , v.plateNumbers
        , i.EndInsurance
        , i.Amount
        , i.active
        , DATEDIFF(DAY, @Today, i.EndInsurance) AS DaysRemaining
    FROM VIC.VehicleInsurance i
    INNER JOIN VIC.Vehicles v
        ON v.chassisNumber = i.chassisNumber_FK
    WHERE i.EndInsurance IS NOT NULL
      AND (@IdaraID_BIG IS NULL OR i.IdaraID_FK = @IdaraID_BIG)
      AND (@activeOnly = 0 OR i.active = 1)
      AND (
            (@includeExpired = 1 AND i.EndInsurance <= @Cutoff)
         OR (@includeExpired = 0 AND i.EndInsurance BETWEEN @Today AND @Cutoff)
          )
    ORDER BY i.EndInsurance ASC;
END
GO
/****** Object:  StoredProcedure [VIC].[Report_MaintenanceCostByVehicle_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تقرير عدد أوامر الصيانة لكل مركبة خلال نطاق تاريخ اختياري،
   مع عرض عدد الأوامر وإرجاع إجمالي تكلفة افتراضي (0) لعدم توفر حقل تكلفة في الهيكل الحالي.
   Type: READ (REPORT)
========================================================= */

CREATE   PROCEDURE [VIC].[Report_MaintenanceCostByVehicle_DL]
(
      @fromDate   DATETIME = NULL
    , @toDate     DATETIME = NULL
    , @idaraID_FK NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    SELECT
          m.chassisNumber_FK AS chassisNumber
        , v.plateLetters
        , v.plateNumbers
        , COUNT(DISTINCT m.MaintOrdID) AS OrdersCount
        , CAST(0 AS DECIMAL(18,2)) AS TotalCost
        , N'التكلفة غير متاحة في هيكل الصيانة الحالي' AS Note
    FROM VIC.VehicleMaintenance m
    INNER JOIN VIC.Vehicles v
        ON v.chassisNumber = m.chassisNumber_FK
    WHERE (@IdaraID_BIG IS NULL OR m.IdaraID_FK = @IdaraID_BIG)
      AND (@fromDate IS NULL OR m.MaintOrdStartDate >= @fromDate)
      AND (@toDate   IS NULL OR m.MaintOrdStartDate <= @toDate)
    GROUP BY
          m.chassisNumber_FK
        , v.plateLetters
        , v.plateNumbers;
END
GO
/****** Object:  StoredProcedure [VIC].[Report_UnpaidViolations_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تقرير المخالفات غير المسددة من جدول VIC.Violations مع فلاتر اختيارية
   حسب رقم الهيكل ونطاق التاريخ، وإظهار نوع المخالفة من VIC.TypesRoot.
   Type: READ (REPORT)
========================================================= */

CREATE   PROCEDURE [VIC].[Report_UnpaidViolations_DL]
(
      @chassisNumber NVARCHAR(100) = NULL
    , @fromDate      DATE = NULL
    , @toDate        DATE = NULL
    , @idaraID_FK    NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    /* ملاحظة: هذه النسخة تتطلب أن يكون اسم عمود رقم الهيكل ثابتًا في VIC.Violations (chassisNumber_FK). */
    SELECT
          v.violationID
        , v.chassisNumber_FK AS chassisNumber
        , v.violationDate
        , v.violationPrice
        , v.violationLocation
        , v.violationTypeRoot_FK
        , t.typesName_A
    FROM VIC.Violations v
    INNER JOIN VIC.TypesRoot t
        ON t.typesID = v.violationTypeRoot_FK
    WHERE v.PaymentDate IS NULL
      AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
      AND (@CH IS NULL OR v.chassisNumber_FK = @CH)
      AND (@fromDate IS NULL OR v.violationDate >= @fromDate)
      AND (@toDate   IS NULL OR v.violationDate <= @toDate)
    ORDER BY v.violationDate DESC;
END
GO
/****** Object:  StoredProcedure [VIC].[Report_VehiclesWithoutCustody_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
