/* =========================================================
   Description:
   تقرير المركبات التي لا يوجد عليها عهدة حالية (لا يوجد سجل custody نشط endDate IS NULL)،
   مع إظهار آخر تاريخ انتهاء عهدة إن وجد، وخيار حصر النتائج على المركبات النشطة فقط (isActive).
   Type: READ (REPORT)
========================================================= */

CREATE   PROCEDURE [VIC].[Report_VehiclesWithoutCustody_DL]
(
      @onlyActiveVehicles BIT = 0
    , @idaraID_FK         NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- لأن الحقل في الجدول Snapshot هو INT
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, @IdaraID_BIG);

    SELECT
          v.chassisNumber
        , v.plateLetters
        , v.plateNumbers
        , v.yearModel
        , (
            SELECT MAX(w.endDate)
            FROM VIC.vehicleWithUsers w
            WHERE w.chassisNumber_FK = v.chassisNumber
              AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)
          ) AS LastCustodyEndDate
    FROM VIC.Vehicles v
    WHERE (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
      AND NOT EXISTS
    (
        SELECT 1
        FROM VIC.vehicleWithUsers w
        WHERE w.chassisNumber_FK = v.chassisNumber
          AND w.endDate IS NULL
          AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)
    )
      AND (@onlyActiveVehicles = 0 OR v.isActive = 1);
END
GO
/****** Object:  StoredProcedure [VIC].[Report_VehicleTimeline_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تقرير “الخط الزمني” لمركبة واحدة حسب chassisNumber، ويجمع الأحداث من عدة مصادر:
   العهد (بدء/انتهاء) + طلبات النقل + المحاضر + الصيانة (بدء/انتهاء) + الوثائق (بدء/انتهاء) + التأمين (بدء/انتهاء)
   مع فلاتر اختيارية لنطاق التاريخ.
   Type: READ (REPORT)
========================================================= */

CREATE   PROCEDURE [VIC].[Report_VehicleTimeline_DL]
(
      @chassisNumber NVARCHAR(100)
    , @fromDate      DATETIME = NULL
    , @toDate        DATETIME = NULL
    , @idaraID_FK    NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');
    IF @CH IS NULL
        THROW 50001, N'chassisNumber مطلوب', 1;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- لأن جدول العهدة فيه Snapshot كـ INT
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, @IdaraID_BIG);

    -- تحقق وجود المركبة + مطابقة الإدارة إن تم تمريرها (READ لا يرجع “فاضي” بصمت)
    IF NOT EXISTS
    (
        SELECT 1
        FROM VIC.Vehicles v
        WHERE v.chassisNumber = @CH
          AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
    )
        THROW 50001, N'المركبة غير موجودة أو لا تطابق الإدارة', 1;

    ;WITH Timeline AS
    (
        -- Custody Start
        SELECT
              N'Custody'              AS EventType
            , w.startDate             AS EventDate
            , w.vehicleWithUsersID    AS RefID
            , N'بدء عهدة'             AS Title
            , ISNULL(w.note, N'')     AS Details
        FROM VIC.vehicleWithUsers w
        WHERE w.chassisNumber_FK = @CH
          AND w.startDate IS NOT NULL
          AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)

        UNION ALL

        -- Custody End
        SELECT
              N'Custody'
            , w.endDate
            , w.vehicleWithUsersID
            , N'انتهاء عهدة'
            , ISNULL(w.note, N'')
        FROM VIC.vehicleWithUsers w
        WHERE w.chassisNumber_FK = @CH
          AND w.endDate IS NOT NULL
          AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)

        UNION ALL

        -- Transfer Request
        SELECT
              N'Transfer'
            , r.entryDate
            , r.RequestID
            , N'طلب نقل مركبة'
            , N''
        FROM VIC.VehicleTransferRequest r
        WHERE r.chassisNumber_FK = @CH
          AND (@IdaraID_BIG IS NULL OR r.IdaraID_FK = @IdaraID_BIG)

        UNION ALL

        -- Handover
        SELECT
              N'Handover'
            , h.handoverDate
            , h.VehicleHandoverID
            , N'محضر تسليم/استلام'
            , ISNULL(h.note, N'')
        FROM VIC.VehicleHandover h
        INNER JOIN VIC.VehicleTransferRequest r
            ON r.RequestID = h.RequestID_FK
        WHERE r.chassisNumber_FK = @CH
          AND (@IdaraID_BIG IS NULL OR r.IdaraID_FK = @IdaraID_BIG)

        UNION ALL

        -- Maintenance Start
        SELECT
              N'Maintenance'
            , m.MaintOrdStartDate
            , m.MaintOrdID
            , N'بدء صيانة'
            , ISNULL(m.MaintOrdDesc, N'')
        FROM VIC.VehicleMaintenance m
        WHERE m.chassisNumber_FK = @CH
          AND m.MaintOrdStartDate IS NOT NULL
          AND (@IdaraID_BIG IS NULL OR m.IdaraID_FK = @IdaraID_BIG)

        UNION ALL

        -- Maintenance End
        SELECT
              N'Maintenance'
            , m.MaintOrdEndDate
            , m.MaintOrdID
            , N'انتهاء صيانة'
            , ISNULL(m.MaintOrdDesc, N'')
        FROM VIC.VehicleMaintenance m
        WHERE m.chassisNumber_FK = @CH
          AND m.MaintOrdEndDate IS NOT NULL
          AND (@IdaraID_BIG IS NULL OR m.IdaraID_FK = @IdaraID_BIG)

        UNION ALL

        -- Document Start
        SELECT
              N'Document'
            , d.vehicleDocumentStartDate
            , d.vehicleDocumentID
            , N'بدء وثيقة'
            , ISNULL(d.vehicleDocumentNo, N'')
        FROM VIC.vehicleDocument d
        WHERE d.chassisNumber_FK = @CH
          AND d.vehicleDocumentStartDate IS NOT NULL
          AND (@IdaraID_BIG IS NULL OR d.IdaraID_FK = @IdaraID_BIG)

        UNION ALL

        -- Document End
        SELECT
              N'Document'
            , d.vehicleDocumentEndDate
            , d.vehicleDocumentID
            , N'انتهاء وثيقة'
            , ISNULL(d.vehicleDocumentNo, N'')
        FROM VIC.vehicleDocument d
        WHERE d.chassisNumber_FK = @CH
          AND d.vehicleDocumentEndDate IS NOT NULL
          AND (@IdaraID_BIG IS NULL OR d.IdaraID_FK = @IdaraID_BIG)

        UNION ALL

        -- Insurance Start
        SELECT
              N'Insurance'
            , i.StartInsurance
            , i.VehicleInsuranceID
            , N'بدء تأمين'
            , ISNULL(i.Source, N'')
        FROM VIC.VehicleInsurance i
        WHERE i.chassisNumber_FK = @CH
          AND i.StartInsurance IS NOT NULL
          AND (@IdaraID_BIG IS NULL OR i.IdaraID_FK = @IdaraID_BIG)

        UNION ALL

        -- Insurance End
        SELECT
              N'Insurance'
            , i.EndInsurance
            , i.VehicleInsuranceID
            , N'انتهاء تأمين'
            , ISNULL(i.Source, N'')
        FROM VIC.VehicleInsurance i
        WHERE i.chassisNumber_FK = @CH
          AND i.EndInsurance IS NOT NULL
          AND (@IdaraID_BIG IS NULL OR i.IdaraID_FK = @IdaraID_BIG)
    )
    SELECT
          EventType
        , EventDate
        , RefID
        , Title
        , Details
    FROM Timeline
    WHERE (@fromDate IS NULL OR EventDate >= @fromDate)
      AND (@toDate   IS NULL OR EventDate <= @toDate)
    ORDER BY EventDate ASC;
END
GO
/****** Object:  StoredProcedure [VIC].[Scrap_Action_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تنفيذ إجراء على محضر الإتلاف:
   - APPROVE: اعتماد الإتلاف + تطبيق آثار الإتلاف على المركبة (Scrapped) وإغلاق العهدة/الطلبات/الصيانة النشطة.
   - CANCEL : إلغاء المسودة فقط (Status=Cancelled) دون تعديل المركبة.
   Type: WRITE (WORKFLOW)
   Output: صف واحد IsSuccessful / Message_
========================================================= */
CREATE   PROCEDURE [VIC].[Scrap_Action_SP]
(
      @Action         NVARCHAR(20)   -- APPROVE | CANCEL
    , @ScrapID        BIGINT
    , @idaraID_FK     NVARCHAR(10) = NULL

    , @actionByUserID BIGINT = NULL
    , @actionNote     NVARCHAR(1000) = NULL

    , @entryData      NVARCHAR(80)  = NULL
    , @hostName       NVARCHAR(800) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @Act NVARCHAR(20) = UPPER(NULLIF(LTRIM(RTRIM(@Action)), N''));
    IF @Act IS NULL OR @Act NOT IN (N'APPROVE', N'CANCEL')
        THROW 50001, N'Action غير صحيح (APPROVE/CANCEL)', 1;

    IF @ScrapID IS NULL OR @ScrapID <= 0
        THROW 50001, N'ScrapID غير صحيح', 1;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE
          @CH NVARCHAR(200)
        , @ScrapStatus NVARCHAR(40)
        , @ScrapRefNo NVARCHAR(200)
        , @ScrapReason NVARCHAR(800)
        , @ScrapNote NVARCHAR(2000)
        , @ScrapDate DATETIME
        , @ScrapIdara BIGINT;

    -- ADDED (Audit)
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        /* جلب السجل + مطابقة الإدارة (إذا تم تمريرها) */
        SELECT
              @CH          = s.chassisNumber_FK
            , @ScrapStatus = s.Status
            , @ScrapDate   = s.ScrapDate
            , @ScrapRefNo  = s.RefNo
            , @ScrapReason = s.Reason
            , @ScrapNote   = s.Note
            , @ScrapIdara  = s.IdaraID_FK
        FROM VIC.VehicleScrap s
        WHERE s.ScrapID = @ScrapID;

        IF @CH IS NULL
            THROW 50001, N'سجل الإتلاف غير موجود', 1;

        IF @IdaraID_BIG IS NOT NULL
        BEGIN
            IF ISNULL(@ScrapIdara, -1) <> @IdaraID_BIG
                THROW 50001, N'سجل الإتلاف لا يتبع هذه الإدارة', 1;
        END

        /* لازم يكون Draft للتصرف */
        IF @ScrapStatus <> N'Draft'
            THROW 50001, N'لا يمكن تنفيذ العملية لأن السجل ليس Draft', 1;

        /* المركبة + مطابقة الإدارة على Vehicles */
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
        )
            THROW 50001, N'المركبة غير موجودة أو لا تتبع هذه الإدارة', 1;

        IF @tc = 0 BEGIN TRAN;

        /* =========================
           CANCEL
        ========================= */
        IF @Act = N'CANCEL'
        BEGIN
            UPDATE VIC.VehicleScrap
            SET
                  Status    = N'Cancelled'
                , entryDate = GETDATE()
                , entryData = @entryData
                , hostName  = @hostName
                , Notes     = COALESCE(@actionNote, Notes)
            WHERE ScrapID = @ScrapID;

            IF @@ROWCOUNT <= 0
                THROW 50002, N'لم يتم تحديث السجل', 1; -- CHANGED (50002)

            -- ADDED (AuditLog)
            SET @Note_Audit = N'{'
                + N'"Action": "'         + ISNULL(CONVERT(NVARCHAR(MAX), @Act), '') + N'"'
                + N',"ScrapID": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapID), '') + N'"'
                + N',"chassisNumber": "' + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
                + N',"fromStatus": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapStatus), '') + N'"'
                + N',"toStatus": "Cancelled"'
                + N',"idaraID_FK": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
                + N',"actionByUserID": "'+ ISNULL(CONVERT(NVARCHAR(MAX), @actionByUserID), '') + N'"'
                + N',"actionNote": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @actionNote), '') + N'"'
                + N',"entryData": "'     + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[VIC].[VehicleScrap]'
                , @Act
                , ISNULL(@ScrapID, 0)
                , @entryData
                , @Note_Audit
            );

            IF @tc = 0 COMMIT;

            SELECT 1 AS IsSuccessful, N'تم إلغاء مسودة الإتلاف' AS Message_;
            RETURN;
        END

        /* =========================
           APPROVE
        ========================= */

        /* منع اعتماد إذا المركبة أصلاً Scrapped */
        IF EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND v.vehicleStatusID_FK = 262
        )
            THROW 50001, N'المركبة متلفة نهائيًا بالفعل', 1;

        /* 1) إغلاق أي عهدة نشطة */
        UPDATE VIC.vehicleWithUsers
        SET endDate = GETDATE()
        WHERE chassisNumber_FK = @CH
          AND endDate IS NULL;

        /* 2) إغلاق/تعطيل طلبات نقل نشطة */
        ;WITH ActiveReq AS
        (
            SELECT r.RequestID
            FROM VIC.VehicleTransferRequest r
            WHERE r.chassisNumber_FK = @CH
              AND ISNULL(r.active, 0) = 1
        )
        UPDATE r
        SET
              active     = 0
            , aproveNote = LEFT(COALESCE(@actionNote, r.aproveNote, N'Closed due to scrap'), 400)
            , entryDate  = GETDATE()
            , entryData  = COALESCE(@entryData, r.entryData)
            , hostName   = COALESCE(@hostName, r.hostName)
        FROM VIC.VehicleTransferRequest r
        INNER JOIN ActiveReq a ON a.RequestID = r.RequestID;

        /* 2-B) تسجيل حدث تاريخ لطلبات النقل التي أغلقت بسبب الإتلاف (مرة واحدة لكل طلب) */
        INSERT INTO VIC.VehicleTransferRequestHistory
        (
              RequestID_FK, Status, ActionBy, ActionDate, Notes, hostName
        )
        SELECT
              r.RequestID
            , N'ClosedDueToScrap'
            , TRY_CONVERT(BIGINT, @actionByUserID)
            , GETDATE()
            , @actionNote
            , @hostName
        FROM VIC.VehicleTransferRequest r
        WHERE r.chassisNumber_FK = @CH
          AND ISNULL(r.active, 0) = 0
          AND NOT EXISTS
          (
              SELECT 1
              FROM VIC.VehicleTransferRequestHistory h
              WHERE h.RequestID_FK = r.RequestID
                AND h.Status = N'ClosedDueToScrap'
          );

        /* 3) إغلاق أوامر صيانة نشطة تلقائيًا */
        UPDATE VIC.VehicleMaintenance
        SET
              MaintOrdActive  = 0
            , MaintOrdEndDate = COALESCE(MaintOrdEndDate, GETDATE())
            , entryDate       = GETDATE()
            , entryData       = COALESCE(@entryData, entryData)
            , hostName        = COALESCE(@hostName, hostName)
        WHERE chassisNumber_FK = @CH
          AND ISNULL(MaintOrdActive, 0) = 1;

        /* 4) اعتماد السجل */
        UPDATE VIC.VehicleScrap
        SET
              Status           = N'Approved'
            , ApprovedByUserID = @actionByUserID
            , ApprovedDate     = GETDATE()
            , entryDate        = GETDATE()
            , entryData        = @entryData
            , hostName         = @hostName
            , Notes            = COALESCE(@actionNote, Notes)
        WHERE ScrapID = @ScrapID;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم اعتماد السجل', 1; -- CHANGED (50002)

        /* 5) تحديث المركبة Scrapped */
        UPDATE VIC.Vehicles
        SET
              isActive            = 0
            , vehicleStatusID_FK  = 262
            , scrapDate           = COALESCE(@ScrapDate, GETDATE())
            , scrapRefNo          = @ScrapRefNo
            , scrapReason         = @ScrapReason
            , scrapNote           = @ScrapNote
        WHERE chassisNumber = @CH
          AND (@IdaraID_BIG IS NULL OR IdaraID_FK = @IdaraID_BIG);

        IF @@ROWCOUNT <= 0
            THROW 50002, N'فشل تحديث حالة المركبة إلى Scrapped', 1; -- CHANGED (50002)

        -- ADDED (AuditLog)
        SET @Note_Audit = N'{'
            + N'"Action": "'         + ISNULL(CONVERT(NVARCHAR(MAX), @Act), '') + N'"'
            + N',"ScrapID": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapID), '') + N'"'
            + N',"chassisNumber": "' + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
            + N',"fromStatus": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapStatus), '') + N'"'
            + N',"toStatus": "Approved"'
            + N',"ScrapDate": "'     + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapDate, 121), '') + N'"'
            + N',"RefNo": "'         + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapRefNo), '') + N'"'
            + N',"Reason": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapReason), '') + N'"'
            + N',"Note": "'          + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapNote), '') + N'"'
            + N',"idaraID_FK": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
            + N',"actionByUserID": "'+ ISNULL(CONVERT(NVARCHAR(MAX), @actionByUserID), '') + N'"'
            + N',"actionNote": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @actionNote), '') + N'"'
            + N',"entryData": "'     + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName": "'      + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[VehicleScrap]'
            , @Act
            , ISNULL(@ScrapID, 0)
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم اعتماد الإتلاف وتحديث حالة المركبة' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[Scrap_Upsert_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إنشاء/تعديل محضر إتلاف (مسودة) في VIC.VehicleScrap.
   - لا يغير حالة المركبة
   - لا يغلق عهدة/طلبات/صيانة
   - الحالة: Draft
   Type: WRITE (UPSERT)
   Output: صف واحد IsSuccessful / Message_
========================================================= */
CREATE   PROCEDURE [VIC].[Scrap_Upsert_SP]
(
      @ScrapID        BIGINT        = NULL
    , @chassisNumber  NVARCHAR(100)
    , @idaraID_FK     NVARCHAR(10)   = NULL

    , @ScrapDate      DATETIME      = NULL
    , @ScrapTypeID_FK INT           = NULL
    , @RefNo          NVARCHAR(200)  = NULL
    , @Reason         NVARCHAR(800)  = NULL
    , @Note           NVARCHAR(2000) = NULL
    , @Notes          NVARCHAR(2000) = NULL

    , @entryData      NVARCHAR(80)   = NULL
    , @hostName       NVARCHAR(800)  = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');
    IF @CH IS NULL
        THROW 50001, N'chassisNumber مطلوب', 1;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- ADDED (Audit)
    DECLARE
          @ActionType NVARCHAR(20) = NULL
        , @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        /* تحقق وجود المركبة + مطابقة الإدارة */
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
        )
            THROW 50001, N'المركبة غير موجودة أو لا تتبع هذه الإدارة', 1;

        /* منع المسودة إذا المركبة Scrapped */
        IF EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
              AND v.vehicleStatusID_FK = 262
        )
            THROW 50001, N'المركبة متلفة نهائيًا (Scrapped) ولا يمكن إنشاء/تعديل مسودة إتلاف لها', 1;

        IF @tc = 0 BEGIN TRAN;

        IF @ScrapID IS NULL
        BEGIN
            INSERT INTO VIC.VehicleScrap
            (
                  chassisNumber_FK
                , IdaraID_FK
                , ScrapDate
                , ScrapTypeID_FK
                , RefNo
                , Reason
                , Note
                , Status
                , entryDate
                , entryData
                , hostName
                , Notes
            )
            VALUES
            (
                  @CH
                , @IdaraID_BIG
                , @ScrapDate
                , @ScrapTypeID_FK
                , @RefNo
                , @Reason
                , @Note
                , N'Draft'
                , GETDATE()
                , @entryData
                , @hostName
                , @Notes
            );

            SET @ScrapID = CONVERT(BIGINT, SCOPE_IDENTITY());
            IF @ScrapID IS NULL OR @ScrapID <= 0
                THROW 50002, N'فشل إنشاء مسودة الإتلاف', 1; -- CHANGED (50002)

            SET @ActionType = N'INSERT'; -- ADDED
        END
        ELSE
        BEGIN
            /* لا نعدّل إلا مسودة */
            IF NOT EXISTS
            (
                SELECT 1
                FROM VIC.VehicleScrap s
                WHERE s.ScrapID = @ScrapID
                  AND s.Status = N'Draft'
            )
                THROW 50001, N'لا يمكن تعديل هذا السجل (ليس Draft أو غير موجود)', 1;

            /* مطابقة الإدارة من السجل نفسه (إذا تمررت) */
            IF @IdaraID_BIG IS NOT NULL
            BEGIN
                IF NOT EXISTS
                (
                    SELECT 1
                    FROM VIC.VehicleScrap s
                    WHERE s.ScrapID = @ScrapID
                      AND s.IdaraID_FK = @IdaraID_BIG
                )
                    THROW 50001, N'السجل لا يتبع هذه الإدارة', 1;
            END

            UPDATE VIC.VehicleScrap
            SET
                  chassisNumber_FK = @CH
                , IdaraID_FK       = COALESCE(@IdaraID_BIG, IdaraID_FK)
                , ScrapDate        = @ScrapDate
                , ScrapTypeID_FK   = @ScrapTypeID_FK
                , RefNo            = @RefNo
                , Reason           = @Reason
                , Note             = @Note
                , entryDate        = GETDATE()
                , entryData        = @entryData
                , hostName         = @hostName
                , Notes            = @Notes
            WHERE ScrapID = @ScrapID;

            IF @@ROWCOUNT <= 0
                THROW 50002, N'لم يتم تعديل أي سجل', 1; -- CHANGED (50002)

            SET @ActionType = N'UPDATE'; -- ADDED
        END

        -- ADDED (AuditLog)
        SET @Note_Audit = N'{'
            + N'"ScrapID": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapID), '') + N'"'
            + N',"chassisNumber": "'+ ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
            + N',"idaraID_FK": "'   + ISNULL(CONVERT(NVARCHAR(MAX), @idaraID_FK), '') + N'"'
            + N',"ScrapDate": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapDate, 121), '') + N'"'
            + N',"ScrapTypeID_FK": "'+ ISNULL(CONVERT(NVARCHAR(MAX), @ScrapTypeID_FK), '') + N'"'
            + N',"RefNo": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @RefNo), '') + N'"'
            + N',"Reason": "'       + ISNULL(CONVERT(NVARCHAR(MAX), @Reason), '') + N'"'
            + N',"Note": "'         + ISNULL(CONVERT(NVARCHAR(MAX), @Note), '') + N'"'
            + N',"Notes": "'        + ISNULL(CONVERT(NVARCHAR(MAX), @Notes), '') + N'"'
            + N',"Status": "Draft"'
            + N',"entryData": "'    + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName": "'     + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[VehicleScrap]'
            , @ActionType
            , ISNULL(@ScrapID, 0)
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT
              1 AS IsSuccessful
            , N'تم حفظ مسودة الإتلاف بنجاح' AS Message_
            , @ScrapID AS ScrapID;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[ScrapDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* =========================================================
   Description:
   قائمة / تفاصيل / طباعة محاضر الإتلاف من VIC.VehicleScrap

   Modes:
   - List  : بدون @scrapID
   - Get   : مع @scrapID
   - Print : نفس Get (يستخدم في الطباعة)

   Filters:
   - chassisNumber
   - Status
   - Date range

   Type: READ (LIST / GET / PRINT)
========================================================= */
CREATE   PROCEDURE [VIC].[ScrapDL]
(
      @scrapID        BIGINT        = NULL
    , @chassisNumber  NVARCHAR(100) = NULL
    , @Status         NVARCHAR(40)  = NULL
    , @DateFrom       DATETIME      = NULL
    , @DateTo         DATETIME      = NULL
    , @pageNumber     INT           = 1
    , @pageSize       INT           = 50
    , @idaraID_FK     NVARCHAR(10)  = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @CH NVARCHAR(100) =
        NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    DECLARE @ST NVARCHAR(40) =
        NULLIF(LTRIM(RTRIM(@Status)), N'');

    IF ISNULL(@pageNumber,0) <= 0 SET @pageNumber = 1;
    IF ISNULL(@pageSize,0) <= 0 SET @pageSize = 50;

    /* =====================================================
       1) GET / PRINT
    ===================================================== */
    IF @scrapID IS NOT NULL
    BEGIN
        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.VehicleScrap s
            INNER JOIN VIC.Vehicles v
                ON v.chassisNumber = s.chassisNumber_FK
            WHERE s.ScrapID = @scrapID
              AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
        )
        BEGIN
            ;THROW 50001, N'محضر الإتلاف غير موجود', 1;
        END;

        SELECT
              s.ScrapID
            , s.chassisNumber_FK
            , s.IdaraID_FK
            , s.ScrapDate
            , s.ScrapTypeID_FK
            , s.RefNo
            , s.Reason
            , s.Note
            , s.Notes
            , s.Status
            , s.ApprovedByUserID
            , s.ApprovedDate
            , s.entryDate
            , s.entryData
            , s.hostName

            -- بيانات المركبة
            , v.plateLetters
            , v.plateNumbers
            , v.armyNumber
            , v.vehicleStatusID_FK

        FROM VIC.VehicleScrap s
        INNER JOIN VIC.Vehicles v
            ON v.chassisNumber = s.chassisNumber_FK
        WHERE s.ScrapID = @scrapID
          AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG);

        RETURN;
    END;

    /* =====================================================
       2) LIST
    ===================================================== */
    ;WITH Q AS
    (
        SELECT
              s.ScrapID
            , s.chassisNumber_FK
            , s.IdaraID_FK
            , s.ScrapDate
            , s.ScrapTypeID_FK
            , s.RefNo
            , s.Reason
            , s.Status
            , s.ApprovedDate

            -- بيانات المركبة
            , v.plateLetters
            , v.plateNumbers
            , v.armyNumber
            , v.vehicleStatusID_FK

            , ROW_NUMBER() OVER (ORDER BY s.ScrapID DESC) AS RN
            , COUNT(*) OVER () AS TotalRows

        FROM VIC.VehicleScrap s
        INNER JOIN VIC.Vehicles v
            ON v.chassisNumber = s.chassisNumber_FK

        WHERE
            (@CH IS NULL OR s.chassisNumber_FK LIKE N'%' + @CH + N'%')
        AND (@ST IS NULL OR s.Status = @ST)
        AND (@DateFrom IS NULL OR s.ScrapDate >= @DateFrom)
        AND (@DateTo IS NULL OR s.ScrapDate <= @DateTo)
        AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
    )
    SELECT *
    FROM Q
    WHERE RN BETWEEN ((@pageNumber - 1) * @pageSize) + 1
                 AND (@pageNumber * @pageSize)
    ORDER BY RN;
END
GO
/****** Object:  StoredProcedure [VIC].[TransferRequest_Approve_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   (C) TransferRequest_Approve_SP
   - يمنع التفعيل إذا يوجد طلب نشط آخر لنفس المركبة داخل نفس الإدارة
========================================================= */
CREATE   PROCEDURE [VIC].[TransferRequest_Approve_SP]
(
      @requestID  INT
    , @actionBy   INT
    , @note       NVARCHAR(1000) = NULL
    , @hostName   NVARCHAR(400) = NULL
    , @idaraID_FK NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @requestID IS NULL OR @requestID <= 0
        THROW 50001, N'requestID مطلوب', 1;

    IF @actionBy IS NULL OR @actionBy <= 0
        THROW 50001, N'actionBy مطلوب', 1;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    IF @IdaraID_BIG IS NULL
        THROW 50001, N'idaraID_FK مطلوب', 1;

    DECLARE @CH NVARCHAR(100);

    BEGIN TRY
        IF @tc = 0 BEGIN TRAN;

        SELECT @CH = r.chassisNumber_FK
        FROM VIC.VehicleTransferRequest r
        WHERE r.RequestID = @requestID
          AND r.IdaraID_FK = @IdaraID_BIG;

        IF @CH IS NULL
            THROW 50001, N'الطلب غير موجود أو لا يطابق الإدارة', 1;

        IF EXISTS
        (
            SELECT 1
            FROM VIC.VehicleTransferRequest r
            WHERE r.chassisNumber_FK = @CH
              AND r.IdaraID_FK = @IdaraID_BIG
              AND ISNULL(r.active, 0) = 1
              AND r.RequestID <> @requestID
        )
            THROW 50001, N'يوجد طلب نقل نشط لهذه المركبة، أغلقه أولاً', 1;

        UPDATE VIC.VehicleTransferRequest
        SET
              active      = 1
            , aproveNote  = CASE WHEN @note IS NULL THEN aproveNote ELSE LEFT(@note, 400) END
            , entryDate   = GETDATE()
            , entryData   = CONVERT(NVARCHAR(40), @actionBy)
            , hostName    = @hostName
        WHERE RequestID = @requestID
          AND IdaraID_FK = @IdaraID_BIG;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم تحديث أي سجل', 1; -- CHANGED (50002)

        INSERT INTO VIC.VehicleTransferRequestHistory
        (
              RequestID_FK
            , Status
            , ActionBy
            , ActionDate
            , Notes
            , hostName
            , entryDate
            , entryData
        )
        VALUES
        (
              @requestID
            , N'Approved'
            , @actionBy
            , GETDATE()
            , @note
            , @hostName
            , GETDATE()
            , CONVERT(NVARCHAR(40), @actionBy)
        );

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم اعتماد الطلب' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[TransferRequest_Approved_List_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع طلبات نقل المركبات الموافق عليها فقط من جدول
   VIC.VehicleTransferRequest بحيث تكون آخر حالة في
   VIC.VehicleTransferRequestHistory = Approved
   ولم يتم إغلاقها أو رفضها أو إلغاؤها.

   الغرض:
   استخدامه في صفحة تنفيذ نقل العهد، بحيث لا تظهر
   إلا الطلبات الموافق عليها والجاهزة للتنفيذ.

   Type: READ (LIST)
========================================================= */

CREATE         PROCEDURE [VIC].[TransferRequest_Approved_List_DL]
(
      @requestID      INT = NULL
    , @chassisNumber  NVARCHAR(100) = NULL
    , @fromUserID     INT = NULL
    , @toUserID       INT = NULL
    , @pageNumber     INT = 1
    , @pageSize       INT = 50
    , @idaraID_FK     NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @P  INT = CASE WHEN @pageNumber IS NULL OR @pageNumber < 1 THEN 1 ELSE @pageNumber END;
    DECLARE @PS INT = CASE WHEN @pageSize IS NULL OR @pageSize < 1 OR @pageSize > 200 THEN 50 ELSE @pageSize END;
    DECLARE @Skip INT = (@P - 1) * @PS;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    ;WITH R AS
    (
        SELECT
              r.RequestID
            , r.RequestTypeID_FK
            , r.chassisNumber_FK
            , r.fromUserID_FK
            , r.toUserID_FK
            , r.deptID_FK
            , r.CreateByUser
            , r.aproveNote
            , r.active
            , r.IdaraID_FK
            , r.entryDate
            , r.entryData
            , r.hostName

            , hLast.HistoryID       AS LastHistoryID
            , hLast.Status          AS LastStatus
            , hLast.ActionBy        AS LastActionBy
            , hLast.ActionDate      AS LastActionDate
            , hLast.Notes           AS LastNotes
        FROM VIC.VehicleTransferRequest r
        OUTER APPLY
        (
            SELECT TOP (1)
                  h.HistoryID
                , h.Status
                , h.ActionBy
                , h.ActionDate
                , h.Notes
            FROM VIC.VehicleTransferRequestHistory h
            WHERE h.RequestID_FK = r.RequestID
            ORDER BY h.ActionDate DESC, h.HistoryID DESC
        ) hLast
        WHERE 1 = 1
          AND (@requestID IS NULL OR r.RequestID = @requestID)
          AND (@CH IS NULL OR r.chassisNumber_FK = @CH)
          AND (@fromUserID IS NULL OR r.fromUserID_FK = @fromUserID)
          AND (@toUserID IS NULL OR r.toUserID_FK = @toUserID)
          AND (@IdaraID_BIG IS NULL OR r.IdaraID_FK = @IdaraID_BIG)
    )
    SELECT
          R.RequestID
        , R.RequestTypeID_FK
        , T.VehicleTransferRequestTypeNameA AS RequestTypeNameA
        , T.VehicleTransferRequestTypeNameE AS RequestTypeNameE
        , R.chassisNumber_FK
        , R.fromUserID_FK
        , R.toUserID_FK
        , R.deptID_FK
        , R.CreateByUser
        , R.aproveNote
        , R.active
        , R.IdaraID_FK
        , R.entryDate
        , R.entryData
        , R.hostName
        , R.LastHistoryID
        , R.LastStatus
        , R.LastActionBy
        , R.LastActionDate
        , R.LastNotes
    FROM R
    LEFT JOIN VIC.VehicleTransferRequestType T
        ON T.VehicleTransferRequestTypeID = R.RequestTypeID_FK
    WHERE R.LastStatus = N'Approved'
      AND ISNULL(R.active, 0) = 1
    ORDER BY
          R.LastActionDate DESC
        , R.RequestID DESC
    OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;
END
GO
