/* =========================================================
   (F) TransferRequest_Cancel_SP  (تعطيل + History Cancelled)
========================================================= */
CREATE PROCEDURE [VIC].[TransferRequest_Cancel_SP]
(
      @requestID  INT
    , @actionBy   INT
    , @note       NVARCHAR(1000)
    , @hostName   NVARCHAR(400)
    , @idaraID_FK NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @requestID IS NULL OR @requestID <= 0
        THROW 50001, N'requestID مطلوب', 1;

    IF @actionBy IS NULL OR @actionBy <= 0
        THROW 50001, N'actionBy مطلوب', 1;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    BEGIN TRY
        IF @tc = 0 BEGIN TRAN;

        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.VehicleTransferRequest r
            WHERE r.RequestID = @requestID
              AND (@IdaraID_BIG IS NULL OR r.IdaraID_FK = @IdaraID_BIG)
        )
            THROW 50001, N'الطلب غير موجود أو لا يطابق الإدارة', 1;

        UPDATE VIC.VehicleTransferRequest
        SET
              active      = 0
            , aproveNote  = CASE WHEN @note IS NULL THEN aproveNote ELSE LEFT(@note, 400) END
            , entryDate   = GETDATE()
            , entryData   = CONVERT(NVARCHAR(40), @actionBy)
            , hostName    = @hostName
        WHERE RequestID = @requestID
          AND (@IdaraID_BIG IS NULL OR IdaraID_FK = @IdaraID_BIG); -- CHANGED (Idara filter)

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم تحديث أي سجل', 1;

        INSERT INTO VIC.VehicleTransferRequestHistory
        (
              RequestID_FK
            , Status
            , ActionBy
            , ActionDate
            , Notes
            , hostName
            , entryDate      -- ADDED (Unify History)
            , entryData      -- ADDED (Unify History)
        )
        VALUES
        (
              @requestID
            , N'Cancelled'
            , @actionBy
            , GETDATE()
            , @note
            , @hostName
            , GETDATE()                         -- ADDED
            , CONVERT(NVARCHAR(40), @actionBy)  -- ADDED
        );

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم إلغاء الطلب' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[TransferRequest_Close_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   (D) TransferRequest_Close_SP
   - يغلق الطلب (active=0)
   - History Closed مع منع تكرار Closed كآخر حالة
========================================================= */
CREATE   PROCEDURE [VIC].[TransferRequest_Close_SP]
(
      @requestID  INT
    , @actionBy   INT
    , @note       NVARCHAR(1000)
    , @hostName   NVARCHAR(400)
    , @idaraID_FK NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @requestID IS NULL OR @requestID <= 0
        THROW 50001, N'requestID مطلوب', 1;

    IF @actionBy IS NULL OR @actionBy <= 0
        THROW 50001, N'actionBy مطلوب', 1;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @Now DATETIME = GETDATE();
    DECLARE @EntryData NVARCHAR(20) = LEFT(CONVERT(NVARCHAR(40), @actionBy), 20);

    BEGIN TRY
        IF @tc = 0 BEGIN TRAN;

        IF NOT EXISTS (
            SELECT 1
            FROM VIC.VehicleTransferRequest
            WHERE RequestID = @requestID
              AND ISNULL(active,0) = 1
              AND (@IdaraID_BIG IS NULL OR IdaraID_FK = @IdaraID_BIG)
        )
            THROW 50001, N'الطلب غير موجود أو غير نشط', 1;

        UPDATE VIC.VehicleTransferRequest
        SET
              active      = 0
            , aproveNote  = CASE WHEN @note IS NULL THEN aproveNote ELSE LEFT(@note,200) END
            , entryDate   = @Now
            , entryData   = @EntryData
            , hostName    = LEFT(@hostName,200)
        WHERE RequestID = @requestID
          AND (@IdaraID_BIG IS NULL OR IdaraID_FK = @IdaraID_BIG);

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم تحديث أي سجل', 1; -- ADDED (50002)

        IF NOT EXISTS (
            SELECT 1
            FROM VIC.VehicleTransferRequestHistory h
            WHERE h.RequestID_FK = @requestID
              AND h.HistoryID = (
                    SELECT MAX(HistoryID)
                    FROM VIC.VehicleTransferRequestHistory
                    WHERE RequestID_FK = @requestID
              )
              AND h.Status = N'Closed'
        )
        BEGIN
            INSERT INTO VIC.VehicleTransferRequestHistory
            (
                  RequestID_FK
                , Status
                , ActionBy
                , ActionDate
                , Notes
                , hostName
                , entryDate
                , entryData
            )
            VALUES
            (
                  @requestID
                , N'Closed'
                , @actionBy
                , @Now
                , LEFT(@note,1000)
                , LEFT(@hostName,200)
                , @Now
                , @EntryData
            );
        END

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم إغلاق الطلب' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[TransferRequest_Create_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إنشاء طلب نقل مركبة مع تحقق صارم من:
   - وجود عهدة نشطة حالية على المركبة
   - مطابقة fromUserID لصاحب العهدة الحالية
   - كون toUserID من نفس القسم ونفس الإدارة
   - عدم وجود عهدة نشطة على toUserID
   - عدم وجود طلب نقل نشط سابق لنفس المركبة
   Type: WRITE
========================================================= */

CREATE PROCEDURE [VIC].[TransferRequest_Create_SP]
(
      @requestTypeID INT
    , @chassisNumber NVARCHAR(100)
    , @fromUserID    INT
    , @toUserID      INT
    , @deptID        INT
    , @createByUser  NVARCHAR(200)
    , @note          NVARCHAR(400) = NULL
    , @idaraID_FK    NVARCHAR(10) = NULL
    , @entryData     NVARCHAR(40) = NULL
    , @hostName      NVARCHAR(400) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');
    DECLARE @CB NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@createByUser)), N'');

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE
          @CurrentCustodyUserID BIGINT = NULL
        , @CurrentCustodyDeptID INT = NULL
        , @FromDeptID INT = NULL
        , @ToDeptID INT = NULL
        , @FromIdaraID INT = NULL
        , @ToIdaraID INT = NULL;

    BEGIN TRY
        IF @requestTypeID IS NULL OR @requestTypeID <= 0
            THROW 50001, N'requestTypeID مطلوب', 1;

        IF @CH IS NULL
            THROW 50001, N'chassisNumber مطلوب', 1;

        IF @fromUserID IS NULL OR @fromUserID <= 0
            THROW 50001, N'fromUserID مطلوب', 1;

        IF @toUserID IS NULL OR @toUserID <= 0
            THROW 50001, N'toUserID مطلوب', 1;

        IF @fromUserID = @toUserID
            THROW 50001, N'لا يمكن النقل لنفس المستخدم', 1;

        IF @deptID IS NULL OR @deptID <= 0
            THROW 50001, N'deptID مطلوب', 1;

        IF @CB IS NULL
            THROW 50001, N'createByUser مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH
              AND v.IdaraID_FK = @IdaraID_BIG
        )
            THROW 50001, N'المركبة غير موجودة أو لا تطابق الإدارة', 1;

        /* العهدة الحالية على المركبة */
        SELECT TOP (1)
              @CurrentCustodyUserID = w.userID_FK
            , @CurrentCustodyDeptID = w.DeptID_Snapshot
        FROM VIC.vehicleWithUsers w
        INNER JOIN VIC.Vehicles v
            ON v.chassisNumber = w.chassisNumber_FK
        WHERE w.chassisNumber_FK = @CH
          AND w.endDate IS NULL
          AND v.IdaraID_FK = @IdaraID_BIG
          AND ISNULL(w.IdaraID_Snapshot, -1) = TRY_CONVERT(INT, @IdaraID_BIG)
        ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC;

        IF @CurrentCustodyUserID IS NULL
            THROW 50001, N'لا توجد عهدة نشطة حالية على المركبة', 1;

        IF @CurrentCustodyUserID <> @fromUserID
            THROW 50001, N'fromUserID لا يطابق صاحب العهدة الحالية', 1;

        IF @CurrentCustodyDeptID IS NULL
            THROW 50001, N'تعذر تحديد قسم العهدة الحالية', 1;

        IF @deptID <> @CurrentCustodyDeptID
            THROW 50001, N'deptID لا يطابق قسم العهدة الحالية', 1;

        /* إدارة/قسم fromUserID */
        SELECT TOP (1)
              @FromDeptID = TRY_CONVERT(INT, fs.DepartmentID)
            , @FromIdaraID = TRY_CONVERT(INT, fs.IdaraID)
        FROM DATACORE.dbo.UserTemp ut
        INNER JOIN DATACORE.dbo.V_GetFullStructureForDSD fs
            ON fs.DSDID = ut.dsdID_FK
        WHERE ut.userID_FK = @fromUserID;

        IF @FromDeptID IS NULL OR @FromIdaraID IS NULL
            THROW 50001, N'تعذر تحديد بيانات المستخدم المنقول منه', 1;

        /* إدارة/قسم toUserID */
        SELECT TOP (1)
              @ToDeptID = TRY_CONVERT(INT, fs.DepartmentID)
            , @ToIdaraID = TRY_CONVERT(INT, fs.IdaraID)
        FROM DATACORE.dbo.UserTemp ut
        INNER JOIN DATACORE.dbo.V_GetFullStructureForDSD fs
            ON fs.DSDID = ut.dsdID_FK
        WHERE ut.userID_FK = @toUserID;

        IF @ToDeptID IS NULL OR @ToIdaraID IS NULL
            THROW 50001, N'تعذر تحديد بيانات المستخدم المنقول إليه', 1;

        IF @FromIdaraID <> TRY_CONVERT(INT, @IdaraID_BIG) OR @ToIdaraID <> TRY_CONVERT(INT, @IdaraID_BIG)
            THROW 50001, N'المستخدمون لا يتبعون نفس الإدارة', 1;

        IF @FromDeptID <> @deptID OR @ToDeptID <> @deptID
            THROW 50001, N'المستخدمون لا يتبعون نفس القسم', 1;

        /* منع إذا كان المنقول إليه عنده عهدة نشطة */
        IF EXISTS
        (
            SELECT 1
            FROM VIC.vehicleWithUsers w
            WHERE w.userID_FK = @toUserID
              AND w.endDate IS NULL
              AND ISNULL(w.IdaraID_Snapshot, -1) = TRY_CONVERT(INT, @IdaraID_BIG)
        )
            THROW 50001, N'المنقول إليه لديه عهدة نشطة بالفعل', 1;

        /* منع وجود طلب نقل نشط لنفس المركبة */
        IF EXISTS
        (
            SELECT 1
            FROM VIC.VehicleTransferRequest r
            WHERE r.chassisNumber_FK = @CH
              AND r.IdaraID_FK = @IdaraID_BIG
              AND ISNULL(r.active, 0) = 1
        )
            THROW 50001, N'يوجد طلب نقل نشط لهذه المركبة، أغلقه أولاً', 1;

        IF @tc = 0 BEGIN TRAN;

        INSERT INTO VIC.VehicleTransferRequest
        (
              RequestTypeID_FK
            , chassisNumber_FK
            , fromUserID_FK
            , toUserID_FK
            , deptID_FK
            , CreateByUser
            , aproveNote
            , active
            , IdaraID_FK
            , entryDate
            , entryData
            , hostName
        )
        VALUES
        (
              @requestTypeID
            , @CH
            , @fromUserID
            , @toUserID
            , @deptID
            , @CB
            , @note
            , 1
            , @IdaraID_BIG
            , GETDATE()
            , @entryData
            , @hostName
        );

        DECLARE @newRequestID INT = CONVERT(INT, SCOPE_IDENTITY());

        IF @newRequestID IS NULL OR @newRequestID <= 0
            THROW 50002, N'فشل إنشاء الطلب', 1;

        INSERT INTO VIC.VehicleTransferRequestHistory
        (
              RequestID_FK
            , Status
            , ActionBy
            , ActionDate
            , Notes
            , hostName
            , entryDate
            , entryData
        )
        VALUES
        (
              @newRequestID
            , N'Created'
            , @fromUserID
            , GETDATE()
            , @note
            , @hostName
            , GETDATE()
            , @entryData
        );

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم رفع الطلب بنجاح' AS Message_, @newRequestID AS RequestID;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[TransferRequest_EligibleUsers_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع بيانات المستخدمين المؤهلين لطلب نقل مركبة محددة.

   النتيجة الأولى:
   - "من" = صاحب/أصحاب العهدة الحالية على المركبة المحددة
     (عمليًا غالبًا شخص واحد فقط endDate IS NULL)

   النتيجة الثانية:
   - "إلى" = موظفو نفس القسم ونفس الإدارة
     الذين لا يملكون عهدة نشطة حاليًا

   الغرض:
   استخدامه في مودال "طلب نقل المركبة"

   Type: READ (LOOKUP/LIST)
========================================================= */

CREATE     PROCEDURE [VIC].[TransferRequest_EligibleUsers_DL]
(
      @chassisNumber NVARCHAR(100)
    , @userID        INT
    , @idaraID_FK    NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @CH NVARCHAR(100) =
        NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    BEGIN TRY

        IF @tc = 0 BEGIN TRAN;

        /* ===== Validation ===== */

        IF @userID IS NULL OR @userID <= 0
            THROW 50001, N'userID مطلوب', 1;

        IF @CH IS NULL
            THROW 50001, N'chassisNumber مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        DECLARE
              @CurrentDeptID INT = NULL
            , @CurrentFromUserID BIGINT = NULL
            , @CurrentVehicleWithUsersID INT = NULL;

        /* =====================================================
           1) تحديد قسم المستخدم الحالي
        ===================================================== */
        SELECT TOP (1)
            @CurrentDeptID = TRY_CONVERT(INT, fs.DepartmentID)
        FROM DATACORE.dbo.UserTemp ut
        INNER JOIN DATACORE.dbo.V_GetFullStructureForDSD fs
            ON fs.DSDID = ut.dsdID_FK
        WHERE ut.userID_FK = @userID;

        IF @CurrentDeptID IS NULL
            THROW 50001, N'تعذر تحديد قسم المستخدم الحالي', 1;

        /* =====================================================
           2) التحقق من وجود عهدة نشطة حالية على المركبة
              وأنها ضمن نفس الإدارة ونفس القسم
        ===================================================== */
        SELECT TOP (1)
              @CurrentFromUserID = w.userID_FK
            , @CurrentVehicleWithUsersID = w.vehicleWithUsersID
        FROM VIC.vehicleWithUsers w
        INNER JOIN VIC.Vehicles v
            ON v.chassisNumber = w.chassisNumber_FK
        WHERE w.chassisNumber_FK = @CH
          AND w.endDate IS NULL
          AND v.IdaraID_FK = @IdaraID_BIG
          AND ISNULL(w.IdaraID_Snapshot, -1) = TRY_CONVERT(INT, @IdaraID_BIG)
          AND ISNULL(w.DeptID_Snapshot, -1) = @CurrentDeptID
        ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC;

        IF @CurrentFromUserID IS NULL
            THROW 50001, N'لا توجد عهدة نشطة لهذه المركبة ضمن نفس القسم والإدارة', 1;

        /* =====================================================
           النتيجة الأولى: FROM
           صاحب العهدة الحالية على المركبة
        ===================================================== */
        SELECT
              w.vehicleWithUsersID
            , w.chassisNumber_FK
            , w.userID_FK                     AS FromUserID
            , w.startDate
            , w.note
            , w.GeneralNo_Snapshot
            , w.UserFullName_Snapshot
            , w.DeptID_Snapshot
            , w.DeptName_Snapshot
            , w.SectionID_Snapshot
            , w.SectionName_Snapshot
            , w.OrganizationName_Snap
            , w.IdaraID_Snapshot
            , w.IdaraName_Snap
            , ut.IDNumber                    AS NationalID
            , ut.mobileNo                    AS MobileNo
            , CONCAT_WS(N' ', ut.fristName_A, ut.secondName_A, ut.thirdName_A, ut.lastName_A) AS UserFullName_A
        FROM VIC.vehicleWithUsers w
        LEFT JOIN DATACORE.dbo.UserTemp ut
            ON ut.userID_FK = w.userID_FK
        WHERE w.vehicleWithUsersID = @CurrentVehicleWithUsersID;

        /* =====================================================
           النتيجة الثانية: TO
           موظفو نفس القسم ونفس الإدارة ممن لا يملكون عهدة نشطة
        ===================================================== */
        ;WITH DeptUsers AS
        (
            SELECT
                  ut.userID_FK
                , ut.dsdID_FK
                , ut.fno
                , ut.IDNumber
                , ut.mobileNo
                , CONCAT_WS(N' ', ut.fristName_A, ut.secondName_A, ut.thirdName_A, ut.lastName_A) AS UserFullName_A
                , fs.OrganizationID
                , fs.OrganizationName
                , fs.IdaraID
                , fs.IdaraName
                , fs.DepartmentID
                , fs.DepartmentName
                , fs.SectionID
                , fs.SectionName
                , fs.DivisonID
                , fs.DivisonName
            FROM DATACORE.dbo.UserTemp ut
            INNER JOIN DATACORE.dbo.V_GetFullStructureForDSD fs
                ON fs.DSDID = ut.dsdID_FK
            WHERE fs.IdaraID = TRY_CONVERT(INT, @IdaraID_BIG)
              AND fs.DepartmentID = @CurrentDeptID
        )
        SELECT
              du.userID_FK                   AS ToUserID
            , du.UserFullName_A
            , du.fno                         AS GeneralNo
            , du.IDNumber                    AS NationalID
            , du.mobileNo                    AS MobileNo
            , du.OrganizationID
            , du.OrganizationName
            , du.IdaraID
            , du.IdaraName
            , du.DepartmentID
            , du.DepartmentName
            , du.SectionID
            , du.SectionName
            , du.DivisonID
            , du.DivisonName
        FROM DeptUsers du
        WHERE du.userID_FK <> @CurrentFromUserID
          AND NOT EXISTS
          (
              SELECT 1
              FROM VIC.vehicleWithUsers w2
              WHERE w2.userID_FK = du.userID_FK
                AND w2.endDate IS NULL
                AND ISNULL(w2.IdaraID_Snapshot, -1) = TRY_CONVERT(INT, @IdaraID_BIG)
          )
        ORDER BY du.UserFullName_A ASC;

        IF @tc = 0 COMMIT;

    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[TransferRequest_Execute_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تنفيذ طلب نقل مركبة معاملة واحدة:
   - يتحقق أن الطلب Approved
   - يقفل العهدة الحالية
   - ينشئ عهدة جديدة للمنقول إليه
   - يغلق الطلب
   Type: WRITE
========================================================= */

CREATE     PROCEDURE [VIC].[TransferRequest_Execute_SP]
(
      @requestID      INT
    , @entryData      NVARCHAR(40)
    , @hostName       NVARCHAR(400)
    , @idaraID_FK     NVARCHAR(10)
    , @note           NVARCHAR(1000) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE
          @CH NVARCHAR(100)
        , @FromUserID BIGINT
        , @ToUserID BIGINT
        , @DeptID INT
        , @ReqActive BIT
        , @LastStatus NVARCHAR(100)
        , @CurrentVehicleWithUsersID INT
        , @CurrentCustodyUserID BIGINT
        , @CurrentCustodyDeptID INT
        , @NewVehicleWithUsersID INT
        , @Now DATETIME = GETDATE();

    BEGIN TRY
        IF @requestID IS NULL OR @requestID <= 0
            THROW 50001, N'requestID مطلوب', 1;

        IF NULLIF(LTRIM(RTRIM(@entryData)), N'') IS NULL
            THROW 50001, N'entryData مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        IF @tc = 0 BEGIN TRAN;

        /* ===== الطلب ===== */
        SELECT
              @CH = r.chassisNumber_FK
            , @FromUserID = r.fromUserID_FK
            , @ToUserID = r.toUserID_FK
            , @DeptID = r.deptID_FK
            , @ReqActive = r.active
        FROM VIC.VehicleTransferRequest r
        WHERE r.RequestID = @requestID
          AND r.IdaraID_FK = @IdaraID_BIG;

        IF @CH IS NULL
            THROW 50001, N'الطلب غير موجود أو لا يطابق الإدارة', 1;

        IF ISNULL(@ReqActive, 0) <> 1
            THROW 50001, N'الطلب غير نشط', 1;

        SELECT TOP (1)
            @LastStatus = h.Status
        FROM VIC.VehicleTransferRequestHistory h
        WHERE h.RequestID_FK = @requestID
        ORDER BY h.ActionDate DESC, h.HistoryID DESC;

        IF ISNULL(@LastStatus, N'') <> N'Approved'
            THROW 50001, N'لا يمكن تنفيذ الطلب إلا بعد الموافقة', 1;

        /* ===== العهدة الحالية ===== */
        SELECT TOP (1)
              @CurrentVehicleWithUsersID = w.vehicleWithUsersID
            , @CurrentCustodyUserID = w.userID_FK
            , @CurrentCustodyDeptID = w.DeptID_Snapshot
        FROM VIC.vehicleWithUsers w
        INNER JOIN VIC.Vehicles v
            ON v.chassisNumber = w.chassisNumber_FK
        WHERE w.chassisNumber_FK = @CH
          AND w.endDate IS NULL
          AND v.IdaraID_FK = @IdaraID_BIG
          AND ISNULL(w.IdaraID_Snapshot, -1) = TRY_CONVERT(INT, @IdaraID_BIG)
        ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC;

        IF @CurrentVehicleWithUsersID IS NULL
            THROW 50001, N'لا توجد عهدة نشطة حالية على المركبة', 1;

        IF @CurrentCustodyUserID <> @FromUserID
            THROW 50001, N'صاحب العهدة الحالية لا يطابق المستخدم المنقول منه في الطلب', 1;

        IF @CurrentCustodyDeptID <> @DeptID
            THROW 50001, N'قسم العهدة الحالية لا يطابق قسم الطلب', 1;

        /* ===== المنقول إليه يجب ألا يملك عهدة نشطة ===== */
        IF EXISTS
        (
            SELECT 1
            FROM VIC.vehicleWithUsers w
            WHERE w.userID_FK = @ToUserID
              AND w.endDate IS NULL
              AND ISNULL(w.IdaraID_Snapshot, -1) = TRY_CONVERT(INT, @IdaraID_BIG)
        )
            THROW 50001, N'المنقول إليه لديه عهدة نشطة بالفعل', 1;

        /* ===== إغلاق العهدة الحالية ===== */
        UPDATE VIC.vehicleWithUsers
        SET
              endDate = @Now
            , note = CASE
                        WHEN NULLIF(LTRIM(RTRIM(@note)), N'') IS NULL
                            THEN ISNULL(note, N'') + N' | إغلاق تلقائي بسبب تنفيذ طلب نقل رقم ' + CONVERT(NVARCHAR(20), @requestID)
                        ELSE LEFT(@note, 2000)
                     END
            , entryDate = @Now
            , entryData = @entryData
            , hostName = @hostName
        WHERE vehicleWithUsersID = @CurrentVehicleWithUsersID
          AND endDate IS NULL;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'فشل إغلاق العهدة الحالية', 1;

        /* ===== إنشاء العهدة الجديدة ===== */
        INSERT INTO VIC.vehicleWithUsers
        (
              userID_FK
            , RequestID_FK
            , startDate
            , endDate
            , note
            , entryDate
            , entryData
            , hostName
            , chassisNumber_FK
            , OrgSnapshotDate
            , IdaraID_Snapshot
            , DeptID_Snapshot
        )
        VALUES
        (
              @ToUserID
            , @requestID
            , @Now
            , NULL
            , CASE
                  WHEN NULLIF(LTRIM(RTRIM(@note)), N'') IS NULL
                      THEN N'تم الإنشاء تلقائياً من تنفيذ طلب نقل رقم ' + CONVERT(NVARCHAR(20), @requestID)
                  ELSE LEFT(@note, 2000)
              END
            , @Now
            , @entryData
            , @hostName
            , @CH
            , @Now
            , TRY_CONVERT(INT, @IdaraID_BIG)
            , @DeptID
        );

        SET @NewVehicleWithUsersID = CONVERT(INT, SCOPE_IDENTITY());

        IF @NewVehicleWithUsersID IS NULL OR @NewVehicleWithUsersID <= 0
            THROW 50002, N'فشل إنشاء العهدة الجديدة', 1;

        /* ===== إغلاق الطلب ===== */
        UPDATE VIC.VehicleTransferRequest
        SET
              active = 0
            , aproveNote = CASE
                              WHEN NULLIF(LTRIM(RTRIM(@note)), N'') IS NULL
                                  THEN ISNULL(aproveNote, N'') + N' | تم التنفيذ'
                              ELSE LEFT(@note, 400)
                           END
            , entryDate = @Now
            , entryData = @entryData
            , hostName = @hostName
        WHERE RequestID = @requestID
          AND IdaraID_FK = @IdaraID_BIG
          AND ISNULL(active, 0) = 1;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'فشل إغلاق طلب النقل', 1;

        /* ===== History ===== */
        INSERT INTO VIC.VehicleTransferRequestHistory
        (
              RequestID_FK
            , Status
            , ActionBy
            , ActionDate
            , Notes
            , hostName
            , entryDate
            , entryData
        )
        VALUES
        (
              @requestID
            , N'Closed'
            , TRY_CONVERT(INT, @entryData)
            , @Now
            , CASE
                  WHEN NULLIF(LTRIM(RTRIM(@note)), N'') IS NULL
                      THEN N'تم تنفيذ الطلب وإنشاء عهدة جديدة'
                  ELSE @note
              END
            , @hostName
            , @Now
            , @entryData
        );

        IF @tc = 0 COMMIT;

        SELECT
              CAST(1 AS BIT) AS IsSuccessful
            , N'تم تنفيذ طلب النقل بنجاح' AS Message_
            , @NewVehicleWithUsersID AS vehicleWithUsersID;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[TransferRequest_Get_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع تفاصيل طلب نقل مركبة واحد من جدول VIC.VehicleTransferRequest حسب requestID،
   ويشمل نوع الطلب، رقم الهيكل، الأطراف، الجهة، الملاحظات، حالة التفعيل وحقول التدقيق.
   Type: READ (GET)
========================================================= */

CREATE   PROCEDURE [VIC].[TransferRequest_Get_DL]
(
      @requestID  INT
    , @idaraID_FK NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @requestID IS NULL OR @requestID <= 0
        THROW 50001, N'requestID مطلوب', 1;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    IF NOT EXISTS
    (
        SELECT 1
        FROM VIC.VehicleTransferRequest r
        WHERE r.RequestID = @requestID
          AND (@IdaraID_BIG IS NULL OR r.IdaraID_FK = @IdaraID_BIG)
    )
        THROW 50001, N'الطلب غير موجود أو لا يطابق الإدارة', 1;

    SELECT
          r.RequestID
        , r.RequestTypeID_FK
        , r.chassisNumber_FK
        , r.fromUserID_FK
        , r.toUserID_FK
        , r.deptID_FK
        , r.CreateByUser
        , r.aproveNote
        , r.active
        , r.entryDate
        , r.entryData
        , r.hostName
    FROM VIC.VehicleTransferRequest AS r
    WHERE r.RequestID = @requestID
      AND (@IdaraID_BIG IS NULL OR r.IdaraID_FK = @IdaraID_BIG);
END
GO
/****** Object:  StoredProcedure [VIC].[TransferRequest_Pending_ByDept_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   قائمة طلبات نقل المركبات لمدير القسم
   - نفس الإدارة
   - نفس القسم
   - فقط الطلبات التي آخر حالتها = Created
   Type: READ (LIST)
========================================================= */

CREATE   PROCEDURE [VIC].[TransferRequest_Pending_ByDept_DL]
(
      @userID        INT
    , @idaraID_FK    NVARCHAR(10)
    , @pageNumber    INT = 1
    , @pageSize      INT = 50
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @IdaraID INT =
        TRY_CONVERT(INT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @CurrentDeptID INT;

    /* ===== قسم المستخدم ===== */
    SELECT TOP 1
        @CurrentDeptID = fs.DepartmentID
    FROM DATACORE.dbo.UserTemp ut
    INNER JOIN DATACORE.dbo.V_GetFullStructureForDSD fs
        ON fs.DSDID = ut.dsdID_FK
    WHERE ut.userID_FK = @userID;

    IF @CurrentDeptID IS NULL
        THROW 50001, N'تعذر تحديد قسم المستخدم', 1;

    DECLARE @Skip INT = (@pageNumber - 1) * @pageSize;

    /* ===== القائمة ===== */
    SELECT
          r.RequestID
        , r.chassisNumber_FK
        , r.fromUserID_FK
        , r.toUserID_FK
        , r.deptID_FK
        , r.entryDate
        , r.aproveNote

        , v.plateNumbers
        , v.plateLetters
        , v.armyNumber

        , f.UserFullName_Snapshot AS FromUserName
        , t.UserFullName_A        AS ToUserName

        , h.Status
        , h.ActionDate

    FROM VIC.VehicleTransferRequest r

    INNER JOIN VIC.Vehicles v
        ON v.chassisNumber = r.chassisNumber_FK

    /* من */
    LEFT JOIN VIC.vehicleWithUsers f
        ON f.chassisNumber_FK = r.chassisNumber_FK
       AND f.userID_FK = r.fromUserID_FK

    /* إلى */
    LEFT JOIN DATACORE.dbo.UserTemp ut2
        ON ut2.userID_FK = r.toUserID_FK

    LEFT JOIN DATACORE.dbo.V_GetFullStructureForDSD fs2
        ON fs2.DSDID = ut2.dsdID_FK

    CROSS APPLY
    (
        SELECT TOP 1
              h1.Status
            , h1.ActionDate
        FROM VIC.VehicleTransferRequestHistory h1
        WHERE h1.RequestID_FK = r.RequestID
        ORDER BY h1.ActionDate DESC, h1.HistoryID DESC
    ) h

    OUTER APPLY
    (
        SELECT CONCAT_WS(N' ', ut.fristName_A, ut.secondName_A, ut.thirdName_A, ut.lastName_A) AS UserFullName_A
        FROM DATACORE.dbo.UserTemp ut
        WHERE ut.userID_FK = r.toUserID_FK
    ) t

    WHERE r.IdaraID_FK = @IdaraID
      AND r.deptID_FK = @CurrentDeptID
      AND ISNULL(r.active, 0) = 1
      AND h.Status = N'PENDING'

    ORDER BY r.RequestID DESC
    OFFSET @Skip ROWS FETCH NEXT @pageSize ROWS ONLY;

END
