/* =========================================================
   Description:
   إرجاع قائمة أنواع الجذور (TypesRoot) مع فلترة اختيارية حسب:
   - ParentID (جذر/فرعي)
   - ActiveOnly (النشط فقط)
   - Search (بحث بالاسم عربي/إنجليزي)
   Type: READ (LOOKUP_LIST / LIST)
========================================================= */

CREATE     PROCEDURE [VIC].[TypesRoot_List_DL]
(
      @parentID   INT = NULL
    , @activeOnly BIT = 0
    , @search     NVARCHAR(200) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @S NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@search)), N'');

    SELECT
          t.typesID
        , t.typesName_A
        , t.typesName_E
        , t.typesDesc
        , t.typesActive
        , t.typesStartDate
        , t.typesEndDate
        , t.typesRoot_ParentID
    FROM VIC.TypesRoot AS t
    WHERE 1 = 1
      AND (
            (@parentID IS NULL AND t.typesRoot_ParentID IS NULL)
            OR
            (@parentID IS NOT NULL AND t.typesRoot_ParentID = @parentID)
          )
      AND (@activeOnly = 0 OR t.typesActive = 1)
      AND (
            @S IS NULL
            OR t.typesName_A LIKE N'%' + @S + N'%'
            OR t.typesName_E LIKE N'%' + @S + N'%'
          )
    ORDER BY t.typesName_A;
END
GO
/****** Object:  StoredProcedure [VIC].[TypesRoot_Upsert_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إضافة/تعديل سجل في جدول VIC.TypesRoot (الأنواع)، مع التحقق من:
   - الاسم العربي إلزامي
   - صحة نطاق التواريخ (EndDate >= StartDate)
   - منع ربط العنصر بنفسه كأب
   ويقوم بتعبئة حقول التدقيق entryDate/entryData/hostName.
   Type: WRITE (UPSERT)
========================================================= */

CREATE   PROCEDURE [VIC].[TypesRoot_Upsert_SP]
(
      @typesID            INT = NULL
    , @typesName_A        NVARCHAR(200)
    , @typesName_E        NVARCHAR(200) = NULL
    , @typesDesc          NVARCHAR(600) = NULL
    , @typesActive        BIT = 1
    , @typesStartDate     DATETIME = NULL
    , @typesEndDate       DATETIME = NULL
    , @typesRoot_ParentID INT = NULL
    , @entryData          NVARCHAR(100)
    , @hostName           NVARCHAR(400)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @NameA_Trim NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@typesName_A)), N'');
    DECLARE @NameE_Trim NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@typesName_E)), N'');
    DECLARE @Desc_Trim  NVARCHAR(600) = NULLIF(LTRIM(RTRIM(@typesDesc)), N'');

    DECLARE @SD DATETIME = ISNULL(@typesStartDate, GETDATE());
    DECLARE @ED DATETIME = @typesEndDate;

    DECLARE @IsInsert BIT = CASE WHEN @typesID IS NULL THEN 1 ELSE 0 END;

    -- AuditLog
    DECLARE @ActionType NVARCHAR(20);
    DECLARE @Note_Audit NVARCHAR(MAX);

    BEGIN TRY

        IF @tc = 0
            BEGIN TRAN;

        IF @NameA_Trim IS NULL
            THROW 50001, N'الاسم العربي مطلوب', 1;

        IF (@ED IS NOT NULL AND @ED < @SD)
            THROW 50001, N'لا يمكن أن يكون تاريخ النهاية أقل من تاريخ البداية', 1;

        IF (@typesID IS NOT NULL AND @typesRoot_ParentID IS NOT NULL AND @typesRoot_ParentID = @typesID)
            THROW 50001, N'لا يمكن ربط العنصر بنفسه كأب', 1;

        IF @IsInsert = 1
        BEGIN
            INSERT INTO VIC.TypesRoot
            (
                  typesName_A
                , typesName_E
                , typesDesc
                , typesActive
                , typesStartDate
                , typesEndDate
                , typesRoot_ParentID
                , entryDate
                , entryData
                , hostName
            )
            VALUES
            (
                  @NameA_Trim
                , @NameE_Trim
                , @Desc_Trim
                , @typesActive
                , @SD
                , @ED
                , @typesRoot_ParentID
                , GETDATE()
                , @entryData
                , @hostName
            );

            SET @typesID = CONVERT(INT, SCOPE_IDENTITY());
            IF @typesID IS NULL OR @typesID <= 0
                THROW 50002, N'فشل إضافة النوع', 1;

            -- AuditLog (INSERT)
            SET @ActionType = N'INSERT';

            SET @Note_Audit = N'{'
                + N'"typesID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @typesID), '') + N'"'
                + N',"typesName_A":"' + ISNULL(@NameA_Trim, '') + N'"'
                + N',"typesName_E":"' + ISNULL(@NameE_Trim, '') + N'"'
                + N',"typesDesc":"' + ISNULL(@Desc_Trim, '') + N'"'
                + N',"typesActive":"' + ISNULL(CONVERT(NVARCHAR(10), @typesActive), '') + N'"'
                + N',"typesStartDate":"' + ISNULL(CONVERT(NVARCHAR(30), @SD, 121), '') + N'"'
                + N',"typesEndDate":"' + ISNULL(CONVERT(NVARCHAR(30), @ED, 121), '') + N'"'
                + N',"typesRoot_ParentID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @typesRoot_ParentID), '') + N'"'
                + N',"entryData":"' + ISNULL(@entryData, '') + N'"'
                + N',"hostName":"' + ISNULL(@hostName, '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[VIC].[TypesRoot]'
                , @ActionType
                , @typesID
                , @entryData
                , @Note_Audit
            );
        END
        ELSE
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM VIC.TypesRoot WHERE typesID = @typesID)
                THROW 50001, N'السجل غير موجود للتعديل', 1;

            UPDATE VIC.TypesRoot
            SET
                  typesName_A        = @NameA_Trim
                , typesName_E        = @NameE_Trim
                , typesDesc          = @Desc_Trim
                , typesActive        = @typesActive
                , typesStartDate     = @SD
                , typesEndDate       = @ED
                , typesRoot_ParentID = @typesRoot_ParentID
                , entryDate          = GETDATE()
                , entryData          = @entryData
                , hostName           = @hostName
            WHERE typesID = @typesID;

            IF @@ROWCOUNT <= 0
                THROW 50002, N'لم يتم تعديل أي سجل', 1;

            -- AuditLog (UPDATE)
            SET @ActionType = N'UPDATE';

            SET @Note_Audit = N'{'
                + N'"typesID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @typesID), '') + N'"'
                + N',"typesName_A":"' + ISNULL(@NameA_Trim, '') + N'"'
                + N',"typesName_E":"' + ISNULL(@NameE_Trim, '') + N'"'
                + N',"typesDesc":"' + ISNULL(@Desc_Trim, '') + N'"'
                + N',"typesActive":"' + ISNULL(CONVERT(NVARCHAR(10), @typesActive), '') + N'"'
                + N',"typesStartDate":"' + ISNULL(CONVERT(NVARCHAR(30), @SD, 121), '') + N'"'
                + N',"typesEndDate":"' + ISNULL(CONVERT(NVARCHAR(30), @ED, 121), '') + N'"'
                + N',"typesRoot_ParentID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @typesRoot_ParentID), '') + N'"'
                + N',"entryData":"' + ISNULL(@entryData, '') + N'"'
                + N',"hostName":"' + ISNULL(@hostName, '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[VIC].[TypesRoot]'
                , @ActionType
                , @typesID
                , @entryData
                , @Note_Audit
            );
        END

        IF @tc = 0
            COMMIT;

        SELECT
              1 AS IsSuccessful
            , CASE WHEN @IsInsert = 1 THEN N'تمت الإضافة بنجاح' ELSE N'تم التعديل بنجاح' END AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0
            ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[Vehicle_Get_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   جلب بيانات مركبة واحدة من VIC.Vehicles حسب رقم الهيكل (chassisNumber).
   يتضمن خيار التحقق من صلاحية القائمة عبر fn_UserHasMenuPermission عند SkipPermission=0.
   Type: READ (GET)
========================================================= */

CREATE   PROCEDURE [VIC].[Vehicle_Get_DL]
(
      @UsersID        INT = NULL
    , @MenuLink       NVARCHAR(1000) = NULL
    , @SkipPermission BIT = 1
    , @chassisNumber  NVARCHAR(100)
    , @idaraID_FK     NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @MenuLink_Trim NVARCHAR(1000) = NULLIF(LTRIM(RTRIM(@MenuLink)), N'');
    DECLARE @CH_Trim       NVARCHAR(100)  = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    IF ISNULL(@SkipPermission, 1) = 0 AND @MenuLink_Trim IS NOT NULL
    BEGIN
        IF dbo.fn_UserHasMenuPermission(@UsersID, @MenuLink_Trim) = 0
            THROW 50001, N'عفواً لا تملك صلاحية', 1;
    END

    IF @CH_Trim IS NULL
        THROW 50001, N'chassisNumber مطلوب', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM VIC.Vehicles v
        WHERE v.chassisNumber = @CH_Trim
          AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
    )
        THROW 50001, N'المركبة غير موجودة أو لا تطابق الإدارة', 1;

    SELECT v.*
    FROM VIC.Vehicles v
    WHERE v.chassisNumber = @CH_Trim
      AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG);
END
GO
/****** Object:  StoredProcedure [VIC].[Vehicle_GetLookups_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع بيانات القوائم المساعدة (Lookups) اللازمة لشاشة/وحدة المركبات:
   - TypesRoot (مع فلترة اختيارية حسب ParentID)
   - VehicleTransferRequestType (النشط فقط)
   - HandoverType (النشط فقط)
   - VehiclesDocumentType (النشط فقط)
   يتضمن خيار التحقق من صلاحية القائمة عبر fn_UserHasMenuPermission عند SkipPermission=0.
   Type: READ (LOOKUP_LIST)
========================================================= */

CREATE   PROCEDURE [VIC].[Vehicle_GetLookups_DL]
(
      @UsersID            INT = NULL
    , @MenuLink           NVARCHAR(1000) = NULL
    , @SkipPermission     BIT = 1
    , @TypesRoot_ParentID INT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @MenuLink_Trim NVARCHAR(1000) = NULLIF(LTRIM(RTRIM(@MenuLink)), N'');

    IF ISNULL(@SkipPermission, 1) = 0 AND @MenuLink_Trim IS NOT NULL
    BEGIN
        IF dbo.fn_UserHasMenuPermission(@UsersID, @MenuLink_Trim) = 0
            THROW 50001, N'عفواً لا تملك صلاحية', 1;
    END

    /* 1) TypesRoot */
    SELECT
          t.typesID
        , t.typesName_A
        , t.typesName_E
        , t.typesDesc
        , t.typesActive
        , t.typesStartDate
        , t.typesEndDate
        , t.typesRoot_ParentID
    FROM VIC.TypesRoot t
    WHERE ISNULL(t.typesActive, 1) = 1
      AND (@TypesRoot_ParentID IS NULL OR t.typesRoot_ParentID = @TypesRoot_ParentID)
    ORDER BY ISNULL(t.typesRoot_ParentID, -1), t.typesID;

    /* 2) VehicleTransferRequestType */
    SELECT
          x.VehicleTransferRequestTypeID
        , x.VehicleTransferRequestTypeNameA
        , x.VehicleTransferRequestTypeNameE
        , x.Active
    FROM VIC.VehicleTransferRequestType x
    WHERE ISNULL(x.Active, 1) = 1
    ORDER BY x.VehicleTransferRequestTypeID;

    /* 3) HandoverType */
    SELECT
          h.handOverTypeID
        , h.handOverTypeName_A
        , h.handOverTypeName_E
        , h.active
    FROM VIC.HandoverType h
    WHERE ISNULL(h.active, 1) = 1
    ORDER BY h.handOverTypeID;

    /* 4) VehiclesDocumentType */
    SELECT
          d.vehicleDocumentTypeID
        , d.vehicleDocumentTypeName_A
        , d.vehicleDocumentTypeName_E
        , d.vehicleDocumentTypeActive
    FROM VIC.VehiclesDocumentType d
    WHERE ISNULL(d.vehicleDocumentTypeActive, 1) = 1
    ORDER BY d.vehicleDocumentTypeID;
END
GO
