SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إرجاع قائمة المركبات من VIC.Vehicles مع Paging وفلاتر اختيارية:
   - ownerID_FK
   - plateLetters
   - plateNumbers
   - HasCustody (هل عليها عهدة حالية أم لا)
   ويُرجع كذلك:
   - CurrentUserID / CustodyStartDate
   - vehicleStatusID_FK / VehicleStatusName
   Type: READ (LIST)
========================================================= */

CREATE PROCEDURE [VIC].[Vehicle_List_DL]
(
      @ownerID_FK    NVARCHAR(100) = NULL
    , @plateLetters  NVARCHAR(100) = NULL
    , @plateNumbers  INT = NULL
    , @hasCustody    BIT = NULL
    , @pageNumber    INT = 1
    , @pageSize      INT = 50
    , @idaraID_FK    NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PN INT = CASE WHEN @pageNumber IS NULL OR @pageNumber < 1 THEN 1 ELSE @pageNumber END;
    DECLARE @PS INT = CASE WHEN @pageSize IS NULL OR @pageSize < 1 OR @pageSize > 200 THEN 50 ELSE @pageSize END;
    DECLARE @Skip INT = (@PN - 1) * @PS;

    DECLARE @Owner_Trim   NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@ownerID_FK)), N'');
    DECLARE @Letters_Trim NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@plateLetters)), N'');

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, @IdaraID_BIG);

    ;WITH Base AS
    (
        SELECT
              v.chassisNumber
            , v.vehicleID
            , v.ownerID_FK
            , v.plateLetters
            , v.plateNumbers
            , v.armyNumber
            , v.yearModel
            , v.entryDate
            , v.isActive
            , v.vehicleStatusID_FK
            , CASE 
                  WHEN v.vehicleStatusID_FK = 262 THEN N'تالف'
                  WHEN v.vehicleStatusID_FK = 261 THEN N'غير نشط'
                  WHEN v.vehicleStatusID_FK = 260 THEN N'نشط'
                  ELSE N'غير محدد'
              END AS VehicleStatusName
        FROM VIC.Vehicles v
        WHERE 1 = 1
          AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
          AND (@Owner_Trim   IS NULL OR v.ownerID_FK = @Owner_Trim)
          AND (@Letters_Trim IS NULL OR v.plateLetters = @Letters_Trim)
          AND (@plateNumbers IS NULL OR v.plateNumbers = @plateNumbers)
    ),
    WithCustody AS
    (
        SELECT
              b.*
            , cu.userID_FK AS CurrentUserID
            , cu.startDate AS CustodyStartDate
        FROM Base b
        OUTER APPLY
        (
            SELECT TOP (1)
                  w.userID_FK
                , w.startDate
            FROM VIC.vehicleWithUsers w
            WHERE w.chassisNumber_FK = b.chassisNumber
              AND w.endDate IS NULL
              AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)
            ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC
        ) cu
    )
    SELECT *
    FROM WithCustody
    WHERE
    (
           @hasCustody IS NULL
        OR (@hasCustody = 1 AND CurrentUserID IS NOT NULL)
        OR (@hasCustody = 0 AND CurrentUserID IS NULL)
    )
    ORDER BY entryDate DESC, chassisNumber
    OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;
END
GO
/****** Object:  StoredProcedure [VIC].[Vehicle_List_EXT_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   قائمة موسّعة للمركبات (Vehicle List Extended) مع:
   - تحقق صلاحيات اختياري (UsersID/MenuLink/SkipPermission)
   - بحث عام q (شاصي/لوحة/رقم عسكري)
   - فلاتر: ownerID_FK / plateLetters / plateNumbers / HasCustody / HasActiveRequest
   - إثراء البيانات: العهدة الحالية + الطلب النشط (من V_ActiveTransferRequests)
   - Paging: OFFSET/FETCH
   Type: READ (LIST)
========================================================= */

CREATE   PROCEDURE [VIC].[Vehicle_List_EXT_DL]
(
      @UsersID          INT = NULL
    , @MenuLink         NVARCHAR(1000) = NULL
    , @SkipPermission   BIT = 1

    , @q                NVARCHAR(200) = NULL
    , @ownerID_FK       NVARCHAR(100) = NULL
    , @plateLetters     NVARCHAR(100) = NULL
    , @plateNumbers     INT = NULL
    , @HasCustody       BIT = NULL
    , @HasActiveRequest BIT = NULL

    , @PageNumber       INT = 1
    , @PageSize         INT = 50

    , @idaraID_FK       NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @MenuLink_Trim NVARCHAR(1000) = NULLIF(LTRIM(RTRIM(@MenuLink)), N'');

    IF ISNULL(@SkipPermission, 1) = 0 AND @MenuLink_Trim IS NOT NULL
    BEGIN
        IF dbo.fn_UserHasMenuPermission(@UsersID, @MenuLink_Trim) = 0
            THROW 50001, N'عفواً لا تملك صلاحية', 1;
    END

    DECLARE @QTrim        NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@q)), N'');
    DECLARE @Owner_Trim   NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@ownerID_FK)), N'');
    DECLARE @Letters_Trim NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@plateLetters)), N'');

    DECLARE @PN INT = CASE WHEN @PageNumber IS NULL OR @PageNumber < 1 THEN 1 ELSE @PageNumber END;
    DECLARE @PS INT = CASE WHEN @PageSize   IS NULL OR @PageSize   < 1 OR @PageSize   > 200 THEN 50 ELSE @PageSize END;
    DECLARE @Skip INT = (@PN - 1) * @PS;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- لأن جدول العهدة فيه Snapshot كـ INT
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, @IdaraID_BIG);

    ;WITH Base AS
    (
        SELECT
              v.vehicleID
            , v.chassisNumber
            , v.ownerID_FK
            , v.plateLetters
            , v.plateNumbers
            , v.armyNumber
            , v.yearModel
            , v.vehicleNote
            , v.entryDate
        FROM VIC.Vehicles v
        WHERE 1 = 1
          AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
          AND (@Owner_Trim   IS NULL OR v.ownerID_FK   = @Owner_Trim)
          AND (@Letters_Trim IS NULL OR v.plateLetters = @Letters_Trim)
          AND (@plateNumbers IS NULL OR v.plateNumbers = @plateNumbers)
          AND (
                @QTrim IS NULL
                OR v.chassisNumber LIKE N'%' + @QTrim + N'%'
                OR v.armyNumber    LIKE N'%' + @QTrim + N'%'
                OR v.plateLetters  LIKE N'%' + @QTrim + N'%'
                OR (TRY_CONVERT(INT, @QTrim) IS NOT NULL AND v.plateNumbers = TRY_CONVERT(INT, @QTrim))
              )
    ),
    Enriched AS
    (
        SELECT
              b.*
            , cu.userID_FK        AS CurrentUserID
            , cu.startDate        AS CustodyStartDate
            , ar.RequestID        AS ActiveRequestID
            , ar.LastStatus       AS ActiveRequestLastStatus
            , ar.LastActionDate   AS ActiveRequestLastActionDate
        FROM Base b
        OUTER APPLY
        (
            SELECT TOP (1) w.userID_FK, w.startDate
            FROM VIC.vehicleWithUsers w
            WHERE w.chassisNumber_FK = b.chassisNumber
              AND w.endDate IS NULL
              AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)
            ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC
        ) cu
        OUTER APPLY
        (
            SELECT TOP (1)
                  r.RequestID
                , r.LastStatus
                , r.LastActionDate
            FROM VIC.V_ActiveTransferRequests r
            INNER JOIN VIC.VehicleTransferRequest vr
                ON vr.RequestID = r.RequestID
            WHERE r.chassisNumber_FK = b.chassisNumber
              AND (@IdaraID_BIG IS NULL OR vr.IdaraID_FK = @IdaraID_BIG)
        ) ar
    )
    SELECT e.*
    FROM Enriched e
    WHERE (
            @HasCustody IS NULL
         OR (@HasCustody = 1 AND e.CurrentUserID IS NOT NULL)
         OR (@HasCustody = 0 AND e.CurrentUserID IS NULL)
    )
      AND (
            @HasActiveRequest IS NULL
         OR (@HasActiveRequest = 1 AND e.ActiveRequestID IS NOT NULL)
         OR (@HasActiveRequest = 0 AND e.ActiveRequestID IS NULL)
    )
    ORDER BY e.entryDate DESC, e.chassisNumber
    OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;
END
GO
/****** Object:  StoredProcedure [VIC].[Vehicle_Profile_Get_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   ملف مركبة (Vehicle Profile) يعيد عدة Result Sets:
   1) Summary: بيانات المركبة + العهدة الحالية + الطلب النشط + عدّادات (وثائق/تأمين/صيانة/مخالفات)
   2) Documents: أحدث/الأقرب انتهاءً من وثائق المركبة
   3) Insurance: تأمين المركبة (النشط أولاً ثم الأقرب انتهاءً)
   4) Maintenance: أوامر الصيانة (النشط أولاً + عدد البنود لكل أمر)
   5) Violations: مخالفات المركبة (الأحدث)
   مع تحقق صلاحيات اختياري عبر fn_UserHasMenuPermission عند SkipPermission=0.
   Type: READ (GET)
========================================================= */

CREATE   PROCEDURE [VIC].[Vehicle_Profile_Get_DL]
(
      @UsersID         INT = NULL
    , @MenuLink        NVARCHAR(1000) = NULL
    , @SkipPermission  BIT = 1

    , @chassisNumber   NVARCHAR(100)

    , @TopDocuments    INT = 20
    , @TopInsurance    INT = 20
    , @TopMaintenance  INT = 20
    , @TopViolations   INT = 50

    , @idaraID_FK       NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @MenuLink_Trim NVARCHAR(1000) = NULLIF(LTRIM(RTRIM(@MenuLink)), N'');
    DECLARE @CH_Trim       NVARCHAR(100)  = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- لأن جدول العهدة فيه Snapshot كـ INT
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, @IdaraID_BIG);

    IF ISNULL(@SkipPermission, 1) = 0 AND @MenuLink_Trim IS NOT NULL
    BEGIN
        IF dbo.fn_UserHasMenuPermission(@UsersID, @MenuLink_Trim) = 0
            THROW 50001, N'عفواً لا تملك صلاحية', 1;
    END

    IF @CH_Trim IS NULL
        THROW 50001, N'chassisNumber مطلوب', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM VIC.Vehicles v
        WHERE v.chassisNumber = @CH_Trim
          AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
    )
        THROW 50001, N'المركبة غير موجودة أو لا تطابق الإدارة', 1;

    DECLARE @TD INT = CASE WHEN @TopDocuments   IS NULL OR @TopDocuments   < 1 OR @TopDocuments   > 200 THEN 20 ELSE @TopDocuments   END;
    DECLARE @TI INT = CASE WHEN @TopInsurance   IS NULL OR @TopInsurance   < 1 OR @TopInsurance   > 200 THEN 20 ELSE @TopInsurance   END;
    DECLARE @TM INT = CASE WHEN @TopMaintenance IS NULL OR @TopMaintenance < 1 OR @TopMaintenance > 200 THEN 20 ELSE @TopMaintenance END;
    DECLARE @TV INT = CASE WHEN @TopViolations  IS NULL OR @TopViolations  < 1 OR @TopViolations  > 500 THEN 50 ELSE @TopViolations  END;

    /* 1) Summary */
    SELECT
        v.*,

        cu.userID_FK AS CurrentUserID,
        cu.startDate AS CustodyStartDate,

        ar.RequestID        AS ActiveRequestID,
        ar.RequestTypeID_FK AS ActiveRequestTypeID,
        ar.fromUserID_FK    AS ActiveFromUserID,
        ar.toUserID_FK      AS ActiveToUserID,
        ar.LastStatus       AS ActiveRequestLastStatus,
        ar.LastActionDate   AS ActiveRequestLastActionDate,

        (SELECT COUNT(*) FROM VIC.vehicleDocument d
          WHERE d.chassisNumber_FK = v.chassisNumber
            AND (@IdaraID_BIG IS NULL OR d.IdaraID_FK = @IdaraID_BIG)
        ) AS DocumentsCount,

        (SELECT COUNT(*) FROM VIC.VehicleInsurance i
          WHERE i.chassisNumber_FK = v.chassisNumber
            AND (@IdaraID_BIG IS NULL OR i.IdaraID_FK = @IdaraID_BIG)
        ) AS InsuranceCount,

        (SELECT COUNT(*) FROM VIC.VehicleMaintenance m
          WHERE m.chassisNumber_FK = v.chassisNumber
            AND (@IdaraID_BIG IS NULL OR m.IdaraID_FK = @IdaraID_BIG)
        ) AS MaintenanceCount,

        (SELECT COUNT(*) FROM VIC.Violations vi
          WHERE vi.chassisNumber_FK = v.chassisNumber
            AND (@IdaraID_BIG IS NULL OR vi.IdaraID_FK = @IdaraID_BIG)
        ) AS ViolationsCount
    FROM VIC.Vehicles v
    OUTER APPLY
    (
        SELECT TOP (1) w.userID_FK, w.startDate
        FROM VIC.vehicleWithUsers w
        WHERE w.chassisNumber_FK = v.chassisNumber
          AND w.endDate IS NULL
          AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)
        ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC
    ) cu
    OUTER APPLY
    (
        SELECT TOP (1) r.*
        FROM VIC.V_ActiveTransferRequests r
        INNER JOIN VIC.VehicleTransferRequest vr
            ON vr.RequestID = r.RequestID
        WHERE r.chassisNumber_FK = v.chassisNumber
          AND (@IdaraID_BIG IS NULL OR vr.IdaraID_FK = @IdaraID_BIG)
    ) ar
    WHERE v.chassisNumber = @CH_Trim
      AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG);

    /* 2) Documents */
    SELECT TOP (@TD) d.*
    FROM VIC.vehicleDocument d
    WHERE d.chassisNumber_FK = @CH_Trim
      AND (@IdaraID_BIG IS NULL OR d.IdaraID_FK = @IdaraID_BIG)
    ORDER BY
        CASE WHEN d.vehicleDocumentEndDate IS NULL THEN 1 ELSE 0 END,
        d.vehicleDocumentEndDate ASC,
        d.entryDate DESC,
        d.vehicleDocumentID DESC;

    /* 3) Insurance */
    SELECT TOP (@TI) i.*
    FROM VIC.VehicleInsurance i
    WHERE i.chassisNumber_FK = @CH_Trim
      AND (@IdaraID_BIG IS NULL OR i.IdaraID_FK = @IdaraID_BIG)
    ORDER BY
        CASE WHEN ISNULL(i.active, 0) = 1 THEN 0 ELSE 1 END,
        CASE WHEN i.EndInsurance IS NULL THEN 1 ELSE 0 END,
        i.EndInsurance ASC,
        i.entryDate DESC,
        i.VehicleInsuranceID DESC;

    /* 4) Maintenance Orders */
    SELECT TOP (@TM)
        m.*,
        (SELECT COUNT(*)
         FROM VIC.MaintenanceDetails md
         WHERE md.MaintOrdID_FK = m.MaintOrdID
        ) AS DetailsCount
    FROM VIC.VehicleMaintenance m
    WHERE m.chassisNumber_FK = @CH_Trim
      AND (@IdaraID_BIG IS NULL OR m.IdaraID_FK = @IdaraID_BIG)
    ORDER BY
        CASE WHEN ISNULL(m.MaintOrdActive, 0) = 1 THEN 0 ELSE 1 END,
        CASE WHEN m.MaintOrdStartDate IS NULL THEN 1 ELSE 0 END,
        m.MaintOrdStartDate DESC,
        m.entryDate DESC,
        m.MaintOrdID DESC;

    /* 5) Violations */
    SELECT TOP (@TV) v.*
    FROM VIC.Violations v
    WHERE v.chassisNumber_FK = @CH_Trim
      AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
    ORDER BY
        CASE WHEN v.violationDate IS NULL THEN 1 ELSE 0 END,
        v.violationDate DESC,
        v.entrydate DESC,
        v.violationID DESC;
END
GO
/****** Object:  StoredProcedure [VIC].[Vehicle_Search_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   بحث سريع عن المركبات:
   - إذا تم تمرير plateLetters + plateNumbers: يرجع مطابقات اللوحة مباشرة (مسار سريع).
   - غير ذلك: يستخدم q للبحث العام (شاصي/رقم عسكري/حروف لوحة/أرقام لوحة) مع تفضيل المطابقة الدقيقة.
   ويُرجع كذلك بيانات العهدة الحالية + الطلب النشط (من V_ActiveTransferRequests).
   Type: READ (SEARCH/LIST)
========================================================= */

CREATE   PROCEDURE [VIC].[Vehicle_Search_DL]
(
      @q            NVARCHAR(200) = NULL
     , @plateLetters NVARCHAR(100) = NULL
    , @plateNumbers INT = NULL
    , @Top          INT = 50
    , @idaraID_FK    NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @QTrim       NVARCHAR(200) = NULLIF(LTRIM(RTRIM(@q)), N'');
    DECLARE @LettersTrim NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@plateLetters)), N'');
    DECLARE @TopN INT = CASE WHEN @Top IS NULL OR @Top <= 0 OR @Top > 200 THEN 50 ELSE @Top END;

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- لأن جدول العهدة فيه Snapshot كـ INT
    DECLARE @IdaraID_INT INT = TRY_CONVERT(INT, @IdaraID_BIG);

    /* مسار اللوحة (سريع) */
    IF @LettersTrim IS NOT NULL AND @plateNumbers IS NOT NULL
    BEGIN
        SELECT TOP (@TopN)
            v.*,

            cu.userID_FK         AS CurrentUserID,
            cu.startDate         AS CustodyStartDate,

            tr.RequestID         AS ActiveRequestID,
            tr.RequestTypeID_FK  AS ActiveRequestTypeID,
            tr.fromUserID_FK     AS ActiveFromUserID,
            tr.toUserID_FK       AS ActiveToUserID,
            tr.LastStatus        AS ActiveRequestLastStatus,
            tr.LastActionDate    AS ActiveRequestLastActionDate
        FROM VIC.Vehicles v
        OUTER APPLY
        (
            SELECT TOP (1) w.userID_FK, w.startDate
            FROM VIC.vehicleWithUsers w
            WHERE w.chassisNumber_FK = v.chassisNumber
              AND w.endDate IS NULL
              AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)
            ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC
        ) cu
        OUTER APPLY
        (
            SELECT TOP (1) ar.*
            FROM VIC.V_ActiveTransferRequests ar
            INNER JOIN VIC.VehicleTransferRequest vr
                ON vr.RequestID = ar.RequestID
            WHERE ar.chassisNumber_FK = v.chassisNumber
              AND (@IdaraID_BIG IS NULL OR vr.IdaraID_FK = @IdaraID_BIG)
        ) tr
        WHERE v.plateLetters = @LettersTrim
          AND v.plateNumbers = @plateNumbers
          AND (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
        ORDER BY v.chassisNumber;

        RETURN;
    END

    /* مسار البحث العام */
    IF @QTrim IS NULL
        THROW 50001, N'أدخل قيمة للبحث', 1;

    ;WITH Candidates AS
    (
        /* Exact أولاً */
        SELECT TOP (@TopN) v.chassisNumber
        FROM VIC.Vehicles v
        WHERE (@IdaraID_BIG IS NULL OR v.IdaraID_FK = @IdaraID_BIG)
          AND (v.chassisNumber = @QTrim OR v.armyNumber = @QTrim)

        UNION ALL

        /* Like/Partial */
        SELECT TOP (@TopN) v2.chassisNumber
        FROM VIC.Vehicles v2
        WHERE (@IdaraID_BIG IS NULL OR v2.IdaraID_FK = @IdaraID_BIG)
          AND (
                (v2.chassisNumber LIKE N'%' + @QTrim + N'%')
             OR (v2.armyNumber    LIKE N'%' + @QTrim + N'%')
             OR (v2.plateLetters  LIKE N'%' + @QTrim + N'%')
             OR (TRY_CONVERT(INT, @QTrim) IS NOT NULL AND v2.plateNumbers = TRY_CONVERT(INT, @QTrim))
          )
    )
    SELECT TOP (@TopN)
        v.*,

        cu.userID_FK         AS CurrentUserID,
        cu.startDate         AS CustodyStartDate,

        tr.RequestID         AS ActiveRequestID,
        tr.RequestTypeID_FK  AS ActiveRequestTypeID,
        tr.fromUserID_FK     AS ActiveFromUserID,
        tr.toUserID_FK       AS ActiveToUserID,
        tr.LastStatus        AS ActiveRequestLastStatus,
        tr.LastActionDate    AS ActiveRequestLastActionDate
    FROM (SELECT DISTINCT chassisNumber FROM Candidates) c
    INNER JOIN VIC.Vehicles v
        ON v.chassisNumber = c.chassisNumber
    OUTER APPLY
    (
        SELECT TOP (1) w.userID_FK, w.startDate
        FROM VIC.vehicleWithUsers w
        WHERE w.chassisNumber_FK = v.chassisNumber
          AND w.endDate IS NULL
          AND (@IdaraID_INT IS NULL OR w.IdaraID_Snapshot = @IdaraID_INT)
        ORDER BY w.startDate DESC, w.vehicleWithUsersID DESC
    ) cu
    OUTER APPLY
    (
        SELECT TOP (1) ar.*
        FROM VIC.V_ActiveTransferRequests ar
        INNER JOIN VIC.VehicleTransferRequest vr
            ON vr.RequestID = ar.RequestID
        WHERE ar.chassisNumber_FK = v.chassisNumber
          AND (@IdaraID_BIG IS NULL OR vr.IdaraID_FK = @IdaraID_BIG)
    ) tr
    ORDER BY
        CASE WHEN v.chassisNumber = @QTrim THEN 0 ELSE 1 END,
        v.chassisNumber;
END
GO
/****** Object:  StoredProcedure [VIC].[Vehicle_Upsert_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إضافة/تعديل مركبة في VIC.Vehicles حسب رقم الهيكل (chassisNumber).
   - يدعم تحقق صلاحيات اختياري عبر fn_UserHasMenuPermission عند SkipPermission=0.
   - يعبّي/يحدّث حقول التدقيق entryDate/entryData/hostName (وفق معيار VIC).
   - يرجع IsSuccessful/Message_ + chassisNumber بعد النجاح.
   Type: WRITE (UPSERT)
========================================================= */

CREATE   PROCEDURE [VIC].[Vehicle_Upsert_SP]
(
      @UsersID         INT = NULL
    , @MenuLink        NVARCHAR(1000) = NULL
    , @SkipPermission  BIT = 1

    , @chassisNumber           NVARCHAR(100)

    , @ownerID_FK              NVARCHAR(100) = NULL
    , @ManufacturerNameID_FK   INT = NULL
    , @vehicleModelID_FK       INT = NULL
    , @vehicleClassID_FK       INT = NULL
    , @TypeOfUseID_FK          INT = NULL
    , @vehicleColorID_FK       INT = NULL
    , @countryMadeID_FK        INT = NULL
    , @regstritionTypeID_FK    INT = NULL
    , @regionID_FK             INT = NULL
    , @fuelTypeID_FK           INT = NULL
    , @vehicleTypeID_FK        INT = NULL
    , @yearModel               INT = NULL
    , @capacity                INT = NULL
    , @serialNumber            NVARCHAR(100) = NULL
    , @plateLetters            NVARCHAR(100) = NULL
    , @plateNumbers            INT = NULL
    , @armyNumber              NVARCHAR(100) = NULL
    , @vehicleNote             NVARCHAR(800) = NULL
    , @idaraID_FK              NVARCHAR(10)  = NULL
    , @entryData               NVARCHAR(40)  = NULL
    , @hostName                NVARCHAR(400) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @MenuLink_Trim NVARCHAR(1000) = NULLIF(LTRIM(RTRIM(@MenuLink)), N'');
    DECLARE @CH_Trim       NVARCHAR(100)  = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    DECLARE @Owner_Trim    NVARCHAR(100)  = NULLIF(LTRIM(RTRIM(@ownerID_FK)), N'');
    DECLARE @Serial_Trim   NVARCHAR(100)  = NULLIF(LTRIM(RTRIM(@serialNumber)), N'');
    DECLARE @Letters_Trim  NVARCHAR(100)  = NULLIF(LTRIM(RTRIM(@plateLetters)), N'');
    DECLARE @Army_Trim     NVARCHAR(100)  = NULLIF(LTRIM(RTRIM(@armyNumber)), N'');
    DECLARE @Note_Trim     NVARCHAR(800)  = NULLIF(LTRIM(RTRIM(@vehicleNote)), N'');

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- AuditLog
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF ISNULL(@SkipPermission, 1) = 0 AND @MenuLink_Trim IS NOT NULL
        BEGIN
            IF dbo.fn_UserHasMenuPermission(@UsersID, @MenuLink_Trim) = 0
                THROW 50001, N'عفواً لا تملك صلاحية', 1;
        END

        IF @CH_Trim IS NULL
            THROW 50001, N'chassisNumber مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        DECLARE @IsInsert BIT = CASE WHEN EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles v
            WHERE v.chassisNumber = @CH_Trim
              AND v.IdaraID_FK = @IdaraID_BIG
        ) THEN 0 ELSE 1 END;

        -- لو الشاصي موجود لكن بإدارة مختلفة => نرفض (تجنّب تداخل الإدارات)
        IF @IsInsert = 1 AND EXISTS (SELECT 1 FROM VIC.Vehicles v2 WHERE v2.chassisNumber = @CH_Trim)
            THROW 50001, N'رقم الهيكل موجود بإدارة أخرى', 1;

        IF @tc = 0 BEGIN TRAN;

        IF @IsInsert = 0
        BEGIN
            UPDATE VIC.Vehicles
            SET
                  ownerID_FK            = @Owner_Trim
                , ManufacturerNameID_FK = @ManufacturerNameID_FK
                , vehicleModelID_FK     = @vehicleModelID_FK
                , vehicleClassID_FK     = @vehicleClassID_FK
                , TypeOfUseID_FK        = @TypeOfUseID_FK
                , vehicleColorID_FK     = @vehicleColorID_FK
                , countryMadeID_FK      = @countryMadeID_FK
                , regstritionTypeID_FK  = @regstritionTypeID_FK
                , regionID_FK           = @regionID_FK
                , fuelTypeID_FK         = @fuelTypeID_FK
                , vehicleTypeID_FK      = @vehicleTypeID_FK
                , yearModel             = @yearModel
                , capacity              = @capacity
                , serialNumber          = @Serial_Trim
                , plateLetters          = @Letters_Trim
                , plateNumbers          = @plateNumbers
                , armyNumber            = @Army_Trim
                , vehicleNote           = @Note_Trim
                , entryDate             = GETDATE()
                , entryData             = @entryData
                , hostName              = @hostName
            WHERE chassisNumber = @CH_Trim
              AND IdaraID_FK = @IdaraID_BIG;

            IF @@ROWCOUNT <= 0
                THROW 50002, N'لم يتم تعديل أي سجل', 1; -- CHANGED (50002)

            -- AuditLog (UPDATE)
            SET @Note_Audit = N'{'
                + N'"chassisNumber":"' + ISNULL(CONVERT(NVARCHAR(MAX), @CH_Trim), '') + N'"'
                + N',"IdaraID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_BIG), '') + N'"'
                + N',"ownerID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Owner_Trim), '') + N'"'
                + N',"ManufacturerNameID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @ManufacturerNameID_FK), '') + N'"'
                + N',"vehicleModelID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleModelID_FK), '') + N'"'
                + N',"vehicleClassID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleClassID_FK), '') + N'"'
                + N',"TypeOfUseID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @TypeOfUseID_FK), '') + N'"'
                + N',"vehicleColorID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleColorID_FK), '') + N'"'
                + N',"countryMadeID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @countryMadeID_FK), '') + N'"'
                + N',"regstritionTypeID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @regstritionTypeID_FK), '') + N'"'
                + N',"regionID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @regionID_FK), '') + N'"'
                + N',"fuelTypeID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @fuelTypeID_FK), '') + N'"'
                + N',"vehicleTypeID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleTypeID_FK), '') + N'"'
                + N',"yearModel":"' + ISNULL(CONVERT(NVARCHAR(MAX), @yearModel), '') + N'"'
                + N',"capacity":"' + ISNULL(CONVERT(NVARCHAR(MAX), @capacity), '') + N'"'
                + N',"serialNumber":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Serial_Trim), '') + N'"'
                + N',"plateLetters":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Letters_Trim), '') + N'"'
                + N',"plateNumbers":"' + ISNULL(CONVERT(NVARCHAR(MAX), @plateNumbers), '') + N'"'
                + N',"armyNumber":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Army_Trim), '') + N'"'
                + N',"vehicleNote":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Note_Trim), '') + N'"'
                + N',"entryData":"' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName":"' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[VIC].[Vehicles]'
                , N'UPDATE'
                , 0
                , @entryData
                , @Note_Audit
            );
        END
        ELSE
        BEGIN
            INSERT INTO VIC.Vehicles
            (
                  ownerID_FK
                , ManufacturerNameID_FK
                , vehicleModelID_FK
                , vehicleClassID_FK
                , TypeOfUseID_FK
                , vehicleColorID_FK
                , countryMadeID_FK
                , regstritionTypeID_FK
                , regionID_FK
                , fuelTypeID_FK
                , vehicleTypeID_FK
                , yearModel
                , capacity
                , chassisNumber
                , serialNumber
                , plateLetters
                , plateNumbers
                , armyNumber
                , vehicleNote
                , IdaraID_FK
                , entryDate
                , entryData
                , hostName
            )
            VALUES
            (
                  @Owner_Trim
                , @ManufacturerNameID_FK
                , @vehicleModelID_FK
                , @vehicleClassID_FK
                , @TypeOfUseID_FK
                , @vehicleColorID_FK
                , @countryMadeID_FK
                , @regstritionTypeID_FK
                , @regionID_FK
                , @fuelTypeID_FK
                , @vehicleTypeID_FK
                , @yearModel
                , @capacity
                , @CH_Trim
                , @Serial_Trim
                , @Letters_Trim
                , @plateNumbers
                , @Army_Trim
                , @Note_Trim
                , @IdaraID_BIG
                , GETDATE()
                , @entryData
                , @hostName
            );

            -- AuditLog (INSERT)
            SET @Note_Audit = N'{'
                + N'"chassisNumber":"' + ISNULL(CONVERT(NVARCHAR(MAX), @CH_Trim), '') + N'"'
                + N',"IdaraID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_BIG), '') + N'"'
                + N',"ownerID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Owner_Trim), '') + N'"'
                + N',"ManufacturerNameID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @ManufacturerNameID_FK), '') + N'"'
                + N',"vehicleModelID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleModelID_FK), '') + N'"'
                + N',"vehicleClassID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleClassID_FK), '') + N'"'
                + N',"TypeOfUseID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @TypeOfUseID_FK), '') + N'"'
                + N',"vehicleColorID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleColorID_FK), '') + N'"'
                + N',"countryMadeID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @countryMadeID_FK), '') + N'"'
                + N',"regstritionTypeID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @regstritionTypeID_FK), '') + N'"'
                + N',"regionID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @regionID_FK), '') + N'"'
                + N',"fuelTypeID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @fuelTypeID_FK), '') + N'"'
                + N',"vehicleTypeID_FK":"' + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleTypeID_FK), '') + N'"'
                + N',"yearModel":"' + ISNULL(CONVERT(NVARCHAR(MAX), @yearModel), '') + N'"'
                + N',"capacity":"' + ISNULL(CONVERT(NVARCHAR(MAX), @capacity), '') + N'"'
                + N',"serialNumber":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Serial_Trim), '') + N'"'
                + N',"plateLetters":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Letters_Trim), '') + N'"'
                + N',"plateNumbers":"' + ISNULL(CONVERT(NVARCHAR(MAX), @plateNumbers), '') + N'"'
                + N',"armyNumber":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Army_Trim), '') + N'"'
                + N',"vehicleNote":"' + ISNULL(CONVERT(NVARCHAR(MAX), @Note_Trim), '') + N'"'
                + N',"entryData":"' + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName":"' + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[VIC].[Vehicles]'
                , N'INSERT'
                , 0
                , @entryData
                , @Note_Audit
            );
        END

        IF @tc = 0 COMMIT;

        SELECT
              1 AS IsSuccessful
            , CASE WHEN @IsInsert = 1 THEN N'تمت الإضافة بنجاح' ELSE N'تم التعديل بنجاح' END AS Message_
            , @CH_Trim AS chassisNumber;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
