/* =========================================================
   Description:
   إرجاع قائمة أنواع وثائق المركبات من جدول VIC.VehiclesDocumentType
   لاستخدامها في الشاشات (Lookup/Dropdown)، مع خيار إرجاع النشطة فقط.
   Type: READ (LOOKUP_LIST)
========================================================= */

CREATE     PROCEDURE [VIC].[VehicleDocumentType_List_DL]
(
      @ActiveOnly BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
          t.vehicleDocumentTypeID
        , t.vehicleDocumentTypeName_A
        , t.vehicleDocumentTypeName_E
        , t.vehicleDocumentTypeActive
    FROM VIC.VehiclesDocumentType AS t
    WHERE (@ActiveOnly = 0 OR t.vehicleDocumentTypeActive = 1)
    ORDER BY t.vehicleDocumentTypeName_A ASC;
END
GO
/****** Object:  StoredProcedure [VIC].[VehicleDocumentType_Upsert_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إضافة/تعديل نوع وثيقة مركبة في جدول VIC.VehiclesDocumentType.
   - يتحقق من الاسم العربي وعدم تكراره.
   - يدعم Insert عند عدم تمرير vehicleDocumentTypeID
   - ويدعم Update عند تمريره
   Type: WRITE (UPSERT)
========================================================= */

CREATE PROCEDURE [VIC].[VehicleDocumentType_Upsert_SP]
(
      @vehicleDocumentTypeID INT = NULL
    , @NameA                 NVARCHAR(100)
    , @NameE                 NVARCHAR(100) = NULL
    , @Active                BIT = 1

    -- ADDED: for AuditLog (same pattern as other lookups in your codebase)
    , @entryData             NVARCHAR(40)  = NULL
    , @hostName              NVARCHAR(400) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @FinalID INT = NULL;

    DECLARE @NameA_Trim NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@NameA)), N'');
    DECLARE @NameE_Trim NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@NameE)), N'');

    -- AuditLog
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @NameA_Trim IS NULL
            THROW 50001, N'اسم النوع العربي مطلوب', 1;

        IF EXISTS
        (
            SELECT 1
            FROM VIC.VehiclesDocumentType AS dt
            WHERE dt.vehicleDocumentTypeName_A = @NameA_Trim
              AND (@vehicleDocumentTypeID IS NULL OR dt.vehicleDocumentTypeID <> @vehicleDocumentTypeID)
        )
            THROW 50001, N'اسم النوع العربي موجود مسبقاً', 1;

        IF @tc = 0 BEGIN TRAN;

        IF @vehicleDocumentTypeID IS NULL
        BEGIN
            INSERT INTO VIC.VehiclesDocumentType
            (
                  vehicleDocumentTypeName_A
                , vehicleDocumentTypeName_E
                , vehicleDocumentTypeActive
            )
            VALUES
            (
                  @NameA_Trim
                , @NameE_Trim
                , @Active
            );

            SET @FinalID = CONVERT(INT, SCOPE_IDENTITY());

            IF @FinalID IS NULL OR @FinalID <= 0
                THROW 50002, N'فشل إضافة نوع الوثيقة', 1; -- CHANGED (50002)

            -- AuditLog (INSERT)
            SET @Note_Audit = N'{'
                + N'"vehicleDocumentTypeID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @FinalID), '') + N'"'
                + N',"NameA":"' + ISNULL(@NameA_Trim, '') + N'"'
                + N',"NameE":"' + ISNULL(@NameE_Trim, '') + N'"'
                + N',"Active":"' + ISNULL(CONVERT(NVARCHAR(10), @Active), '') + N'"'
                + N',"entryData":"' + ISNULL(@entryData, '') + N'"'
                + N',"hostName":"' + ISNULL(@hostName, '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[VIC].[VehiclesDocumentType]'
                , N'INSERT'
                , ISNULL(@FinalID, 0)
                , @entryData
                , @Note_Audit
            );
        END
        ELSE
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM VIC.VehiclesDocumentType AS dt WHERE dt.vehicleDocumentTypeID = @vehicleDocumentTypeID)
                THROW 50001, N'السجل غير موجود للتعديل', 1;

            UPDATE VIC.VehiclesDocumentType
            SET
                  vehicleDocumentTypeName_A = @NameA_Trim
                , vehicleDocumentTypeName_E = @NameE_Trim
                , vehicleDocumentTypeActive = @Active
            WHERE vehicleDocumentTypeID = @vehicleDocumentTypeID;

            IF @@ROWCOUNT <= 0
                THROW 50002, N'لم يتم تعديل أي سجل', 1; -- CHANGED (50002)

            SET @FinalID = @vehicleDocumentTypeID;

            -- AuditLog (UPDATE)
            SET @Note_Audit = N'{'
                + N'"vehicleDocumentTypeID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @FinalID), '') + N'"'
                + N',"NameA":"' + ISNULL(@NameA_Trim, '') + N'"'
                + N',"NameE":"' + ISNULL(@NameE_Trim, '') + N'"'
                + N',"Active":"' + ISNULL(CONVERT(NVARCHAR(10), @Active), '') + N'"'
                + N',"entryData":"' + ISNULL(@entryData, '') + N'"'
                + N',"hostName":"' + ISNULL(@hostName, '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[VIC].[VehiclesDocumentType]'
                , N'UPDATE'
                , ISNULL(@FinalID, 0)
                , @entryData
                , @Note_Audit
            );
        END

        IF @tc = 0 COMMIT;

        SELECT
              CAST(1 AS BIT) AS IsSuccessful
            , CASE WHEN @vehicleDocumentTypeID IS NULL THEN N'تمت الإضافة بنجاح' ELSE N'تم التعديل بنجاح' END AS Message_
            , @FinalID AS vehicleDocumentTypeID;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[VehicleInsurance_List_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   قائمة تأمينات المركبات من جدول VIC.VehicleInsurance مع دعم:
   - فلاتر عامة (نوع التأمين/نوع العملية/نشط/تواريخ البداية/شاصي)
   - (اختياري) فلتر الانتهاء خلال X يوم مع خيار IncludeExpired
   
   Type: READ (LIST)
========================================================= */
CREATE   PROCEDURE [VIC].[VehicleInsurance_List_DL]
(
      @chassisNumber     NVARCHAR(100) = NULL
    , @InsuranceTypeID   INT = NULL
    , @OperationTypeID   INT = NULL
    , @Active            BIT = NULL
    , @FromDate          DATETIME = NULL
    , @ToDate            DATETIME = NULL
    , @Page              INT = 1
    , @PageSize          INT = 50

    -- Expiring filter (دمج VehicleInsurance_Expiring_List)
    , @Days              INT = NULL          -- إذا NULL: لا يطبق فلتر الانتهاء
    , @IncludeExpired    BIT = 1             -- يستخدم فقط إذا @Days ليست NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @P    INT = CASE WHEN @Page IS NULL OR @Page < 1 THEN 1 ELSE @Page END;
    DECLARE @PS   INT = CASE WHEN @PageSize IS NULL OR @PageSize < 1 OR @PageSize > 200 THEN 50 ELSE @PageSize END;
    DECLARE @Skip INT = (@P - 1) * @PS;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    DECLARE @D INT = CASE
                        WHEN @Days IS NULL THEN NULL
                        WHEN @Days < 0 THEN 30
                        ELSE @Days
                     END;

    DECLARE @Today DATETIME = GETDATE();
    DECLARE @CutoffDate DATETIME = CASE
                                      WHEN @D IS NULL THEN NULL
                                      ELSE DATEADD(DAY, @D, CAST(@Today AS DATE))
                                   END;

    SELECT
          i.VehicleInsuranceID
        , i.chassisNumber_FK
        , i.InsuranceOpertionType_FK
        , i.InsuranceTypeID_FK
        , i.Source
        , i.StartInsurance
        , i.EndInsurance
        , i.Amount
        , i.Note
        , i.active
        , i.entryDate
        , i.entryData

        , v.plateLetters
        , v.plateNumbers
        , v.yearModel
    FROM VIC.VehicleInsurance AS i
    LEFT JOIN VIC.Vehicles AS v
        ON v.chassisNumber = i.chassisNumber_FK
    WHERE 1=1
      AND (@CH IS NULL OR i.chassisNumber_FK = @CH)
      AND (@InsuranceTypeID IS NULL OR i.InsuranceTypeID_FK = @InsuranceTypeID)
      AND (@OperationTypeID IS NULL OR i.InsuranceOpertionType_FK = @OperationTypeID)
      AND (@Active IS NULL OR i.active = @Active)
      AND (@FromDate IS NULL OR i.StartInsurance >= @FromDate)
      AND (@ToDate   IS NULL OR i.StartInsurance <  DATEADD(DAY, 1, @ToDate))
      AND
      (
            @D IS NULL
            OR
            (
                i.EndInsurance IS NOT NULL
                AND
                (
                    (@IncludeExpired = 1 AND i.EndInsurance <= @CutoffDate)
                    OR
                    (@IncludeExpired = 0 AND i.EndInsurance >= @Today AND i.EndInsurance <= @CutoffDate)
                )
            )
      )
    ORDER BY
        CASE WHEN @D IS NULL THEN i.EndInsurance END DESC,
        CASE WHEN @D IS NOT NULL THEN i.EndInsurance END ASC,
        i.VehicleInsuranceID DESC
    OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;
END
GO
/****** Object:  StoredProcedure [VIC].[VehicleInsurance_SetActive_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تغيير حالة تأمين محدد (active) في VIC.VehicleInsurance.
   - عند تفعيل سجل (@active=1): يتم إلغاء تفعيل باقي تأمينات نفس المركبة.
   - يحدث حقول التدقيق entryDate/entryData/hostName.
   Type: WRITE (SETACTIVE)
========================================================= */
CREATE PROCEDURE [VIC].[VehicleInsurance_SetActive_SP]
(
      @VehicleInsuranceID INT
    , @active             BIT
    , @idaraID_FK         NVARCHAR(10) = NULL
    , @entryData          NVARCHAR(40)
    , @hostName           NVARCHAR(400)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @CH NVARCHAR(100);

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- AuditLog
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @VehicleInsuranceID IS NULL OR @VehicleInsuranceID <= 0
            THROW 50001, N'VehicleInsuranceID مطلوب', 1;

        IF @active IS NULL
            THROW 50001, N'active مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        SELECT @CH = i.chassisNumber_FK
        FROM VIC.VehicleInsurance AS i
        WHERE i.VehicleInsuranceID = @VehicleInsuranceID
          AND i.IdaraID_FK = @IdaraID_BIG;

        IF @CH IS NULL
            THROW 50001, N'سجل التأمين غير موجود أو لا يطابق الإدارة', 1;

        IF @tc = 0 BEGIN TRAN;

        IF @active = 1
        BEGIN
            UPDATE VIC.VehicleInsurance
            SET
                  active    = 0
                , entryDate = GETDATE()
                , entryData = @entryData
                , hostName  = @hostName
            WHERE chassisNumber_FK = @CH
              AND IdaraID_FK = @IdaraID_BIG
              AND VehicleInsuranceID <> @VehicleInsuranceID
              AND ISNULL(active, 0) = 1;
        END

        UPDATE VIC.VehicleInsurance
        SET
              active    = @active
            , entryDate = GETDATE()
            , entryData = @entryData
            , hostName  = @hostName
        WHERE VehicleInsuranceID = @VehicleInsuranceID
          AND IdaraID_FK = @IdaraID_BIG;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم تحديث السجل', 1;

        -- AuditLog (SETACTIVE)
        SET @Note_Audit = N'{'
            + N'"VehicleInsuranceID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @VehicleInsuranceID), '') + N'"'
            + N',"chassisNumber":"'     + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
            + N',"active":"'            + ISNULL(CONVERT(NVARCHAR(MAX), @active), '') + N'"'
            + N',"IdaraID_FK":"'         + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_BIG), '') + N'"'
            + N',"entryData":"'          + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N',"hostName":"'           + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName, ActionType, RecordID, PerformedBy, Notes
        )
        VALUES
        (
              N'[VIC].[VehicleInsurance]'
            , N'SETACTIVE'
            , ISNULL(@VehicleInsuranceID, 0)
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم تحديث حالة التأمين' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[VehicleInsurance_Upsert_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
