GO

/* =========================================================
   Description:
   إضافة/تعديل سجل تأمين لمركبة في VIC.VehicleInsurance.
   - يتحقق من وجود المركبة
   - يتحقق من منطق تواريخ التأمين (End >= Start)
   - يحدّث حقول التدقيق entryDate/entryData/hostName
   Type: WRITE (UPSERT)
========================================================= */
CREATE PROCEDURE [VIC].[VehicleInsurance_Upsert_SP]
(
      @VehicleInsuranceID INT = NULL
    , @chassisNumber      NVARCHAR(100)
    , @OperationTypeID    INT = NULL
    , @InsuranceTypeID    INT = NULL
    , @Source             NVARCHAR(300) = NULL
    , @StartInsurance     DATETIME = NULL
    , @EndInsurance       DATETIME = NULL
    , @Amount             FLOAT = NULL
    , @Note               NVARCHAR(800) = NULL
    , @active             BIT = 1
    , @idaraID_FK         NVARCHAR(10) = NULL
    , @entryData          NVARCHAR(40)
    , @hostName           NVARCHAR(400)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @FinalID INT = NULL;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');
    DECLARE @StartDT DATETIME = ISNULL(@StartInsurance, GETDATE());

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- AuditLog
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @CH IS NULL
            THROW 50001, N'chassisNumber مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles AS v
            WHERE v.chassisNumber = @CH
              AND v.IdaraID_FK = @IdaraID_BIG
        )
            THROW 50001, N'رقم الشاصي غير موجود أو لا يطابق الإدارة', 1;

        IF @EndInsurance IS NOT NULL AND @EndInsurance < @StartDT
            THROW 50001, N'لا يمكن أن يكون تاريخ نهاية التأمين أقل من تاريخ البداية', 1;

        IF @tc = 0 BEGIN TRAN;

        IF @VehicleInsuranceID IS NULL
        BEGIN
            INSERT INTO VIC.VehicleInsurance
            (
                  InsuranceOpertionType_FK
                , InsuranceTypeID_FK
                , chassisNumber_FK
                , Source
                , StartInsurance
                , EndInsurance
                , Amount
                , Note
                , active
                , IdaraID_FK
                , entryDate
                , entryData
                , hostName
            )
            VALUES
            (
                  @OperationTypeID
                , @InsuranceTypeID
                , @CH
                , @Source
                , @StartDT
                , @EndInsurance
                , @Amount
                , @Note
                , @active
                , @IdaraID_BIG
                , GETDATE()
                , @entryData
                , @hostName
            );

            SET @FinalID = CONVERT(INT, SCOPE_IDENTITY());

            IF @FinalID IS NULL OR @FinalID <= 0
                THROW 50002, N'فشل إضافة التأمين', 1;

            SET @Note_Audit = N'{'
                + N'"VehicleInsuranceID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @FinalID), '') + N'"'
                + N',"chassisNumber":"'     + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
                + N',"OperationTypeID":"'   + ISNULL(CONVERT(NVARCHAR(MAX), @OperationTypeID), '') + N'"'
                + N',"InsuranceTypeID":"'   + ISNULL(CONVERT(NVARCHAR(MAX), @InsuranceTypeID), '') + N'"'
                + N',"StartInsurance":"'    + ISNULL(CONVERT(NVARCHAR(30), @StartDT, 121), '') + N'"'
                + N',"EndInsurance":"'      + ISNULL(CONVERT(NVARCHAR(30), @EndInsurance, 121), '') + N'"'
                + N',"active":"'            + ISNULL(CONVERT(NVARCHAR(MAX), @active), '') + N'"'
                + N',"IdaraID_FK":"'         + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_BIG), '') + N'"'
                + N',"entryData":"'          + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName":"'           + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName, ActionType, RecordID, PerformedBy, Notes
            )
            VALUES
            (
                  N'[VIC].[VehicleInsurance]'
                , N'INSERT'
                , ISNULL(@FinalID, 0)
                , @entryData
                , @Note_Audit
            );
        END
        ELSE
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM VIC.VehicleInsurance AS i
                WHERE i.VehicleInsuranceID = @VehicleInsuranceID
                  AND i.IdaraID_FK = @IdaraID_BIG
            )
                THROW 50001, N'VehicleInsuranceID غير موجود للتعديل أو لا يطابق الإدارة', 1;

            UPDATE VIC.VehicleInsurance
            SET
                  InsuranceOpertionType_FK = @OperationTypeID
                , InsuranceTypeID_FK       = @InsuranceTypeID
                , chassisNumber_FK         = @CH
                , Source                   = @Source
                , StartInsurance           = @StartDT
                , EndInsurance             = @EndInsurance
                , Amount                   = @Amount
                , Note                     = @Note
                , active                   = @active
                , IdaraID_FK               = @IdaraID_BIG
                , entryDate                = GETDATE()
                , entryData                = @entryData
                , hostName                 = @hostName
            WHERE VehicleInsuranceID = @VehicleInsuranceID
              AND IdaraID_FK = @IdaraID_BIG;

            IF @@ROWCOUNT <= 0
                THROW 50002, N'لم يتم تعديل أي سجل', 1;

            SET @FinalID = @VehicleInsuranceID;

            SET @Note_Audit = N'{'
                + N'"VehicleInsuranceID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @FinalID), '') + N'"'
                + N',"chassisNumber":"'     + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
                + N',"OperationTypeID":"'   + ISNULL(CONVERT(NVARCHAR(MAX), @OperationTypeID), '') + N'"'
                + N',"InsuranceTypeID":"'   + ISNULL(CONVERT(NVARCHAR(MAX), @InsuranceTypeID), '') + N'"'
                + N',"StartInsurance":"'    + ISNULL(CONVERT(NVARCHAR(30), @StartDT, 121), '') + N'"'
                + N',"EndInsurance":"'      + ISNULL(CONVERT(NVARCHAR(30), @EndInsurance, 121), '') + N'"'
                + N',"active":"'            + ISNULL(CONVERT(NVARCHAR(MAX), @active), '') + N'"'
                + N',"IdaraID_FK":"'         + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_BIG), '') + N'"'
                + N',"entryData":"'          + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
                + N',"hostName":"'           + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName, ActionType, RecordID, PerformedBy, Notes
            )
            VALUES
            (
                  N'[VIC].[VehicleInsurance]'
                , N'UPDATE'
                , ISNULL(@FinalID, 0)
                , @entryData
                , @Note_Audit
            );
        END

        IF @tc = 0 COMMIT;

        SELECT
              1 AS IsSuccessful
            , N'تم حفظ التأمين بنجاح' AS Message_
            , @FinalID AS VehicleInsuranceID;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[VehicleScrap_Approve_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   اعتماد محضر/طلب إتلاف مركبة (VIC.VehicleScrap) مع تطبيق قواعد المنع:
   - إغلاق أي عهدة نشطة تلقائياً
   - إغلاق/تعطيل أي طلب نقل نشط للمركبة + إضافة History
   - إغلاق أي أمر صيانة نشط تلقائياً
   - تحديث VIC.Vehicles: isActive=0 + vehicleStatusID_FK=Scrapped + تعبئة scrap*
   - تحديث VehicleScrap إلى Approved
   Type: WRITE (WORKFLOW/APPROVE)
========================================================= */

CREATE PROCEDURE [VIC].[VehicleScrap_Approve_SP]
(
      @ScrapID          BIGINT
    , @ApprovedByUserID BIGINT
    , @ApprovedDate     DATETIME = NULL
    , @entryData        NVARCHAR(80)  = NULL
    , @hostName         NVARCHAR(800) = NULL
    , @idaraID_FK        NVARCHAR(10)  = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @Now DATETIME = GETDATE();
    DECLARE @ApprDT DATETIME = ISNULL(@ApprovedDate, @Now);

    DECLARE @CH NVARCHAR(200);
    DECLARE @ScrapStatus NVARCHAR(40);
    DECLARE @ScrapDate DATETIME;
    DECLARE @RefNo NVARCHAR(200);
    DECLARE @Reason NVARCHAR(800);
    DECLARE @Note NVARCHAR(2000);
    DECLARE @ScrapIdara BIGINT;

    DECLARE @VehicleIdara BIGINT;
    DECLARE @VehicleStatus INT;

    -- AuditLog
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @ScrapID IS NULL OR @ScrapID <= 0
            THROW 50001, N'ScrapID غير صحيح', 1;

        IF @ApprovedByUserID IS NULL OR @ApprovedByUserID <= 0
            THROW 50001, N'ApprovedByUserID مطلوب', 1;

        SELECT
              @CH          = s.chassisNumber_FK
            , @ScrapStatus = s.Status
            , @ScrapDate   = s.ScrapDate
            , @RefNo       = s.RefNo
            , @Reason      = s.Reason
            , @Note        = ISNULL(NULLIF(LTRIM(RTRIM(s.Note)), N''), s.Notes)  -- عندك Note + Notes
            , @ScrapIdara  = s.IdaraID_FK
        FROM VIC.VehicleScrap s
        WHERE s.ScrapID = @ScrapID;

        IF @CH IS NULL
            THROW 50001, N'محضر الإتلاف غير موجود', 1;

        IF @ScrapStatus IN (N'Approved', N'Cancelled')
            THROW 50001, N'لا يمكن اعتماد محضر بحالة Approved/Cancelled', 1;

        SELECT
              @VehicleIdara  = v.IdaraID_FK
            , @VehicleStatus = v.vehicleStatusID_FK
        FROM VIC.Vehicles v
        WHERE v.chassisNumber = @CH;

        IF @VehicleIdara IS NULL
            THROW 50001, N'المركبة غير موجودة', 1;

        IF @IdaraID_BIG IS NOT NULL AND @VehicleIdara <> @IdaraID_BIG
            THROW 50001, N'الإدارة غير مطابقة للمركبة', 1;

        IF @ScrapIdara IS NOT NULL AND @IdaraID_BIG IS NOT NULL AND @ScrapIdara <> @IdaraID_BIG
            THROW 50001, N'الإدارة غير مطابقة لمحضر الإتلاف', 1;

        IF @VehicleStatus = 262
            THROW 50001, N'المركبة مُتلفة مسبقاً', 1;

        IF @tc = 0 BEGIN TRAN;

        /* 1) إغلاق أي عهدة نشطة */
        UPDATE VIC.vehicleWithUsers
        SET endDate = @Now
        WHERE chassisNumber_FK = @CH
          AND endDate IS NULL;

        /* 2) إغلاق/تعطيل أي طلب نقل نشط + History */
        DECLARE @Req TABLE (RequestID INT);

        UPDATE r
        SET
              r.active    = 0
            , r.entryDate = @Now
            , r.entryData = COALESCE(@entryData, r.entryData)
            , r.hostName  = COALESCE(@hostName, r.hostName)
        OUTPUT INSERTED.RequestID INTO @Req(RequestID)
        FROM VIC.VehicleTransferRequest r
        WHERE r.chassisNumber_FK = @CH
          AND ISNULL(r.active, 0) = 1
          AND (@IdaraID_BIG IS NULL OR r.IdaraID_FK = @IdaraID_BIG);

        INSERT INTO VIC.VehicleTransferRequestHistory
        (
              RequestID_FK
            , Status
            , ActionBy
            , ActionDate
            , Notes
            , hostName
            , entryDate
            , entryData
        )
        SELECT
              q.RequestID
            , N'Closed'
            , TRY_CONVERT(INT, @ApprovedByUserID)
            , @Now
            , N'Auto closed by scrap approve'
            , @hostName
            , @Now
            , @entryData
        FROM @Req q;

        /* 3) إغلاق أوامر الصيانة النشطة */
        UPDATE m
        SET
              m.MaintOrdActive  = 0
            , m.MaintOrdEndDate = COALESCE(m.MaintOrdEndDate, @Now)
            , m.entryDate       = @Now
            , m.entryData       = COALESCE(@entryData, m.entryData)
            , m.hostName        = COALESCE(@hostName, m.hostName)
        FROM VIC.VehicleMaintenance m
        WHERE m.chassisNumber_FK = @CH
          AND ISNULL(m.MaintOrdActive, 0) = 1
          AND (@IdaraID_BIG IS NULL OR m.IdaraID_FK = @IdaraID_BIG);

        /* 4) تحديث المركبة إلى Scrapped */
        UPDATE VIC.Vehicles
        SET
              isActive           = 0
            , vehicleStatusID_FK = 262
            , scrapDate          = COALESCE(@ScrapDate, @Now)
            , scrapRefNo         = @RefNo
            , scrapReason        = @Reason
            , scrapNote          = @Note
            , entryDate          = @Now
            , entryData          = COALESCE(@entryData, entryData)
            , hostName           = COALESCE(@hostName, hostName)
        WHERE chassisNumber = @CH
          AND (@IdaraID_BIG IS NULL OR IdaraID_FK = @IdaraID_BIG);

        IF @@ROWCOUNT <= 0
            THROW 50002, N'فشل تحديث حالة المركبة', 1;

        /* 5) تحديث محضر الإتلاف إلى Approved */
        UPDATE VIC.VehicleScrap
        SET
              Status           = N'Approved'
            , ApprovedByUserID = @ApprovedByUserID
            , ApprovedDate     = @ApprDT
            , entryDate        = @Now
            , entryData        = COALESCE(@entryData, entryData)
            , hostName         = COALESCE(@hostName, hostName)
            , IdaraID_FK        = COALESCE(IdaraID_FK, @VehicleIdara) -- تثبيت إن كانت NULL
        WHERE ScrapID = @ScrapID;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'فشل اعتماد محضر الإتلاف', 1;

        -- AuditLog (SCRAP_APPROVE)
        SET @Note_Audit = N'{'
            + N'"ScrapID":"'           + ISNULL(CONVERT(NVARCHAR(MAX), @ScrapID), '') + N'"'
            + N',"chassisNumber":"'    + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
            + N',"ApprovedByUserID":"' + ISNULL(CONVERT(NVARCHAR(MAX), @ApprovedByUserID), '') + N'"'
            + N',"ApprovedDate":"'     + ISNULL(CONVERT(NVARCHAR(30), @ApprDT, 121), '') + N'"'
            + N',"IdaraID_FK":"'        + ISNULL(CONVERT(NVARCHAR(MAX), COALESCE(@IdaraID_BIG, @VehicleIdara)), '') + N'"'
            + N',"hostName":"'         + ISNULL(CONVERT(NVARCHAR(MAX), @hostName), '') + N'"'
            + N',"entryData":"'        + ISNULL(CONVERT(NVARCHAR(MAX), @entryData), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[VehicleScrap]'
            , N'SCRAP_APPROVE'
            , ISNULL(CONVERT(BIGINT, @ScrapID), 0)
            , COALESCE(@entryData, CONVERT(NVARCHAR(80), @ApprovedByUserID))
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم اعتماد الإتلاف وتطبيق الإغلاقات تلقائياً' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END;
GO
/****** Object:  StoredProcedure [VIC].[Violation_Get_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   جلب سجل مخالفة واحد حسب violationID
   مع إرجاع بيانات المركبة الأساسية ونوع المخالفة.
   - تمت إضافة vehicleID داخليًا
   Type: READ (GET)
========================================================= */
CREATE PROCEDURE [VIC].[Violation_Get_DL]
(
      @violationID  INT
    , @idaraID_FK   NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    IF @violationID IS NULL OR @violationID <= 0
        THROW 50001, N'violationID مطلوب', 1;

    SELECT
          vln.violationID
        , vh.vehicleID
        , vln.violationTypeRoot_FK
        , vln.chassisNumber_FK
        , vln.violationDate
        , vln.violationPrice
        , vln.violationLocation
        , vln.PaymentDate
        , vln.entryPayment
        , vln.entryDate
        , vln.entryData
        , vln.hostName
        , vln.IdaraID_FK

        , CASE WHEN vln.PaymentDate IS NULL THEN CAST(0 AS BIT) ELSE CAST(1 AS BIT) END AS IsPaid
        , CASE WHEN vln.PaymentDate IS NULL THEN N'غير مسددة' ELSE N'مسددة' END AS PaymentStatusName_A

        , tr.typesName_A AS ViolationTypeName_A
        , tr.typesName_E AS ViolationTypeName_E

        , vh.plateLetters
        , vh.plateNumbers
        , vh.yearModel
        , vh.armyNumber
    FROM VIC.Violations AS vln
    INNER JOIN VIC.TypesRoot AS tr
        ON tr.typesID = vln.violationTypeRoot_FK
    LEFT JOIN VIC.Vehicles AS vh
        ON vh.chassisNumber = vln.chassisNumber_FK
    WHERE vln.violationID = @violationID
      AND (@IdaraID_BIG IS NULL OR vln.IdaraID_FK = @IdaraID_BIG);
END
GO
/****** Object:  StoredProcedure [VIC].[Violation_GetLookups_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
