/* =========================================================
   Description:
   إرجاع قائمة أنواع المخالفات من VIC.TypesRoot
   تحت Root ثابت = 257
   مع خيار إرجاع النشطة فقط.
   Type: READ (LOOKUP_LIST)
========================================================= */
CREATE PROCEDURE [VIC].[Violation_GetLookups_DL]
(
      @ActiveOnly BIT = 1
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
          t.typesID
        , t.typesName_A
        , t.typesName_E
        , t.typesActive
    FROM VIC.TypesRoot AS t
    WHERE t.typesRoot_ParentID = 257
      AND (@ActiveOnly = 0 OR t.typesActive = 1)
    ORDER BY t.typesName_A;
END
GO
/****** Object:  StoredProcedure [VIC].[Violation_List_DL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   قائمة المخالفات مع فلاتر اختيارية (شاصي/نوع/مدفوعة/نطاق تاريخ)
   وإرجاع اسم النوع من TypesRoot + بيانات المركبة مع Paging.
   - تمت إضافة vehicleID داخليًا
   - تمت إضافة حالة السداد المحسوبة
   Type: READ (LIST)
========================================================= */
CREATE PROCEDURE [VIC].[Violation_List_DL]
(
      @chassisNumber   NVARCHAR(100) = NULL
    , @violationTypeID INT = NULL
    , @Paid            BIT = NULL      -- 1=مدفوعة, 0=غير مدفوعة
    , @FromDate        DATE = NULL
    , @ToDate          DATE = NULL
    , @Page            INT = 1
    , @PageSize        INT = 50
    , @idaraID_FK      NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @P  INT = CASE WHEN @Page IS NULL OR @Page < 1 THEN 1 ELSE @Page END;
    DECLARE @PS INT = CASE WHEN @PageSize IS NULL OR @PageSize < 1 OR @PageSize > 200 THEN 50 ELSE @PageSize END;
    DECLARE @Skip INT = (@P - 1) * @PS;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    SELECT
          vln.violationID
        , vh.vehicleID                              -- داخلي فقط
        , vln.violationTypeRoot_FK
        , vln.chassisNumber_FK
        , vln.violationDate
        , vln.violationPrice
        , vln.violationLocation
        , vln.PaymentDate
        , vln.entryPayment
        , vln.entryDate
        , vln.entryData
        , vln.hostName

        , CASE WHEN vln.PaymentDate IS NULL THEN CAST(0 AS BIT) ELSE CAST(1 AS BIT) END AS IsPaid
        , CASE WHEN vln.PaymentDate IS NULL THEN N'غير مسددة' ELSE N'مسددة' END AS PaymentStatusName_A

        , tr.typesName_A AS ViolationTypeName_A
        , tr.typesName_E AS ViolationTypeName_E

        , vh.plateLetters
        , vh.plateNumbers
        , vh.yearModel
        , vh.armyNumber
    FROM VIC.Violations AS vln
    INNER JOIN VIC.TypesRoot AS tr
        ON tr.typesID = vln.violationTypeRoot_FK
    LEFT JOIN VIC.Vehicles AS vh
        ON vh.chassisNumber = vln.chassisNumber_FK
    WHERE 1 = 1
      AND (@IdaraID_BIG IS NULL OR vln.IdaraID_FK = @IdaraID_BIG)
      AND (@CH IS NULL OR vln.chassisNumber_FK = @CH)
      AND (@violationTypeID IS NULL OR vln.violationTypeRoot_FK = @violationTypeID)
      AND (
            @Paid IS NULL
            OR (@Paid = 1 AND vln.PaymentDate IS NOT NULL)
            OR (@Paid = 0 AND vln.PaymentDate IS NULL)
          )
      AND (@FromDate IS NULL OR vln.violationDate >= @FromDate)
      AND (@ToDate   IS NULL OR vln.violationDate < DATEADD(DAY, 1, @ToDate))
    ORDER BY
        vln.violationDate DESC,
        vln.violationID DESC
    OFFSET @Skip ROWS FETCH NEXT @PS ROWS ONLY;
END
GO
/****** Object:  StoredProcedure [VIC].[Violation_SetPayment_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   تسجيل سداد مخالفة محددة عبر تحديث PaymentDate وبيانات المُسدد.
   - يمنع تسجيل السداد إذا كانت المخالفة مسددة مسبقاً
   Type: WRITE (WORKFLOW)
   Output: IsSuccessful / Message_
========================================================= */
CREATE PROCEDURE [VIC].[Violation_SetPayment_SP]
(
      @violationID   INT
    , @PaymentDate   DATETIME = NULL
    , @entryPayment  NVARCHAR(100)
    , @hostname      NVARCHAR(400)
    , @idaraID_FK    NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;
    DECLARE @PayDT DATETIME = ISNULL(@PaymentDate, GETDATE());

    -- معيار الإدارة (BIGINT)
    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    -- AuditLog
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @violationID IS NULL OR @violationID <= 0
            THROW 50001, N'violationID مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        IF NULLIF(LTRIM(RTRIM(@entryPayment)), N'') IS NULL
            THROW 50001, N'entryPayment مطلوب', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Violations AS vln
            WHERE vln.violationID = @violationID
              AND vln.IdaraID_FK = @IdaraID_BIG
        )
            THROW 50001, N'المخالفة غير موجودة أو لا تطابق الإدارة', 1;

        IF EXISTS
        (
            SELECT 1
            FROM VIC.Violations AS vln
            WHERE vln.violationID = @violationID
              AND vln.IdaraID_FK = @IdaraID_BIG
              AND vln.PaymentDate IS NOT NULL
        )
            THROW 50001, N'المخالفة مسددة مسبقاً', 1;

        IF @tc = 0 BEGIN TRAN;

        UPDATE VIC.Violations
        SET
              PaymentDate  = @PayDT
            , entryPayment = @entryPayment
            , hostName     = @hostname
        WHERE violationID = @violationID
          AND IdaraID_FK = @IdaraID_BIG;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم تحديث السداد', 1;

        -- AuditLog (PAYMENT)
        SET @Note_Audit = N'{'
            + N'"violationID":"'   + ISNULL(CONVERT(NVARCHAR(MAX), @violationID), '') + N'"'
            + N',"PaymentDate":"'  + ISNULL(CONVERT(NVARCHAR(30), @PayDT, 121), '') + N'"'
            + N',"entryPayment":"' + ISNULL(CONVERT(NVARCHAR(MAX), @entryPayment), '') + N'"'
            + N',"hostName":"'     + ISNULL(CONVERT(NVARCHAR(MAX), @hostname), '') + N'"'
            + N',"IdaraID_FK":"'   + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_BIG), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[Violations]'
            , N'PAYMENT'
            , ISNULL(@violationID, 0)
            , @entryPayment
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم تسجيل سداد المخالفة' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [VIC].[Violation_Upsert_SP]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* =========================================================
   Description:
   إضافة أو تعديل سجل مخالفة في VIC.Violations
   - لا يتم تعديل بيانات السداد هنا
   - التحقق من وجود المركبة ومطابقة الإدارة
   - التحقق من وجود نوع المخالفة وصحته
   Type: WRITE (UPSERT)
   Output: IsSuccessful / Message_
========================================================= */
CREATE PROCEDURE [VIC].[Violation_Upsert_SP]
(
      @violationID        INT = NULL
    , @violationTypeID    INT
    , @chassisNumber      NVARCHAR(100)
    , @violationDate      DATETIME
    , @violationPrice     DECIMAL(18,2) = NULL
    , @violationLocation  NVARCHAR(500) = NULL
    , @idaraID_FK         NVARCHAR(10) = NULL
    , @entryData          NVARCHAR(40)
    , @hostName           NVARCHAR(400)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @tc INT = @@TRANCOUNT;

    DECLARE @CH NVARCHAR(100) = NULLIF(LTRIM(RTRIM(@chassisNumber)), N'');
    DECLARE @LOC NVARCHAR(500) = NULLIF(LTRIM(RTRIM(@violationLocation)), N'');

    DECLARE @IdaraID_BIG BIGINT =
        TRY_CONVERT(BIGINT, NULLIF(LTRIM(RTRIM(@idaraID_FK)), N''));

    DECLARE @vehicleID INT = NULL;
    DECLARE @Note_Audit NVARCHAR(MAX) = NULL;

    BEGIN TRY
        IF @violationTypeID IS NULL OR @violationTypeID <= 0
            THROW 50001, N'نوع المخالفة مطلوب', 1;

        IF @CH IS NULL
            THROW 50001, N'رقم الشاصي مطلوب', 1;

        IF @violationDate IS NULL
            THROW 50001, N'تاريخ المخالفة مطلوب', 1;

        IF @IdaraID_BIG IS NULL
            THROW 50001, N'idaraID_FK مطلوب', 1;

        IF NULLIF(LTRIM(RTRIM(@entryData)), N'') IS NULL
            THROW 50001, N'entryData مطلوب', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Vehicles AS v
            WHERE v.chassisNumber = @CH
              AND v.IdaraID_FK = @IdaraID_BIG
        )
            THROW 50001, N'المركبة غير موجودة أو لا تطابق الإدارة', 1;

        SELECT @vehicleID = v.vehicleID
        FROM VIC.Vehicles AS v
        WHERE v.chassisNumber = @CH
          AND v.IdaraID_FK = @IdaraID_BIG;

        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.TypesRoot AS t
            WHERE t.typesID = @violationTypeID
              AND ISNULL(t.typesActive, 0) = 1
        )
            THROW 50001, N'نوع المخالفة غير موجود أو غير نشط', 1;

        IF @violationPrice IS NOT NULL AND @violationPrice < 0
            THROW 50001, N'قيمة المخالفة لا يمكن أن تكون سالبة', 1;

        IF @tc = 0 BEGIN TRAN;

        IF ISNULL(@violationID, 0) = 0
        BEGIN
            INSERT INTO VIC.Violations
            (
                  violationTypeRoot_FK
                , chassisNumber_FK
                , violationDate
                , violationPrice
                , violationLocation
                , entryDate
                , entryData
                , hostName
                , IdaraID_FK
            )
            VALUES
            (
                  @violationTypeID
                , @CH
                , @violationDate
                , @violationPrice
                , @LOC
                , GETDATE()
                , @entryData
                , @hostName
                , @IdaraID_BIG
            );

            SET @violationID = SCOPE_IDENTITY();

            SET @Note_Audit = N'{'
                + N'"violationID":"'       + ISNULL(CONVERT(NVARCHAR(MAX), @violationID), '') + N'"'
                + N',"vehicleID":"'        + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleID), '') + N'"'
                + N',"chassisNumber":"'    + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
                + N',"violationTypeID":"'  + ISNULL(CONVERT(NVARCHAR(MAX), @violationTypeID), '') + N'"'
                + N',"violationDate":"'    + ISNULL(CONVERT(NVARCHAR(30), @violationDate, 121), '') + N'"'
                + N',"violationPrice":"'   + ISNULL(CONVERT(NVARCHAR(MAX), @violationPrice), '') + N'"'
                + N',"violationLocation":"'+ ISNULL(CONVERT(NVARCHAR(MAX), @LOC), '') + N'"'
                + N',"IdaraID_FK":"'       + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_BIG), '') + N'"'
                + N'}';

            INSERT INTO DATACORE.dbo.AuditLog
            (
                  TableName
                , ActionType
                , RecordID
                , PerformedBy
                , Notes
            )
            VALUES
            (
                  N'[VIC].[Violations]'
                , N'INSERT'
                , @violationID
                , @entryData
                , @Note_Audit
            );

            IF @tc = 0 COMMIT;

            SELECT 1 AS IsSuccessful, N'تمت إضافة المخالفة بنجاح' AS Message_;
            RETURN;
        END

        IF NOT EXISTS
        (
            SELECT 1
            FROM VIC.Violations AS vln
            WHERE vln.violationID = @violationID
              AND vln.IdaraID_FK = @IdaraID_BIG
        )
            THROW 50001, N'المخالفة غير موجودة أو لا تطابق الإدارة', 1;

        UPDATE VIC.Violations
        SET
              violationTypeRoot_FK = @violationTypeID
            , chassisNumber_FK     = @CH
            , violationDate        = @violationDate
            , violationPrice       = @violationPrice
            , violationLocation    = @LOC
            , entryDate            = GETDATE()
            , entryData            = @entryData
            , hostName             = @hostName
        WHERE violationID = @violationID
          AND IdaraID_FK = @IdaraID_BIG;

        IF @@ROWCOUNT <= 0
            THROW 50002, N'لم يتم تحديث المخالفة', 1;

        SET @Note_Audit = N'{'
            + N'"violationID":"'       + ISNULL(CONVERT(NVARCHAR(MAX), @violationID), '') + N'"'
            + N',"vehicleID":"'        + ISNULL(CONVERT(NVARCHAR(MAX), @vehicleID), '') + N'"'
            + N',"chassisNumber":"'    + ISNULL(CONVERT(NVARCHAR(MAX), @CH), '') + N'"'
            + N',"violationTypeID":"'  + ISNULL(CONVERT(NVARCHAR(MAX), @violationTypeID), '') + N'"'
            + N',"violationDate":"'    + ISNULL(CONVERT(NVARCHAR(30), @violationDate, 121), '') + N'"'
            + N',"violationPrice":"'   + ISNULL(CONVERT(NVARCHAR(MAX), @violationPrice), '') + N'"'
            + N',"violationLocation":"'+ ISNULL(CONVERT(NVARCHAR(MAX), @LOC), '') + N'"'
            + N',"IdaraID_FK":"'       + ISNULL(CONVERT(NVARCHAR(MAX), @IdaraID_BIG), '') + N'"'
            + N'}';

        INSERT INTO DATACORE.dbo.AuditLog
        (
              TableName
            , ActionType
            , RecordID
            , PerformedBy
            , Notes
        )
        VALUES
        (
              N'[VIC].[Violations]'
            , N'UPDATE'
            , @violationID
            , @entryData
            , @Note_Audit
        );

        IF @tc = 0 COMMIT;

        SELECT 1 AS IsSuccessful, N'تم تحديث المخالفة بنجاح' AS Message_;
    END TRY
    BEGIN CATCH
        IF @tc = 0 AND XACT_STATE() <> 0 ROLLBACK;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [WH].[WarehouseLocationsDL]    Script Date: 6/17/2026 11:39:00 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [WH].[WarehouseLocationsDL] 
	-- Add the parameters for the stored procedure here
	
      @pageName_      NVARCHAR(400)
    , @idaraID        INT
    , @entrydata      INT
    , @hostname       NVARCHAR(400)
    

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	   

  -- warehouse

     SELECT 
       [warehouseID]
      ,[warehouseName]
      ,[warehousePartName_A]
      ,[warehousePartOldParentID_FK]
      ,[warehouseActive]
      ,case when warehouseActive = 1 then N'نشط' 
      else N'غير نشط' end 
      as warehouseStatus
  FROM [DATACORE].[WH].[V_warehouse] w
  where w.IdaraID_FK = @idaraID

   -- building

    SELECT 
       [warehouseID]
      ,wh.warehouseName
      ,wh.warehousePartName_A
      ,[buildingID]
      ,[buildingName]
      ,[buildingPartName_A]
      ,[buildingActive]
      ,case when buildingActive = 1 then N'نشط' 
      else N'غير نشط' end 
      as buildingStatus
      
  FROM [DATACORE].[WH].[V_building] w
  inner join [DATACORE].[WH].[V_warehouse] wh on w.buildingParentID_FK = wh.warehouseID
  where w.IdaraID_FK = @idaraID 

  -- shelf

    SELECT 
       wh.[warehouseID]
      ,wh.warehouseName
      ,wh.warehousePartName_A
      ,[buildingID]
      ,[buildingName]
      ,[buildingPartName_A]
      ,[shelfID]
      ,[shelfName]
      ,[shelfName_A]
      ,[shelfActive]
      ,case when shelfActive = 1 then N'نشط' 
      else N'غير نشط' end 
      as shelfStatus

  FROM [DATACORE].[WH].[V_shelf] w
  inner join [DATACORE].[WH].[V_building] b on b.buildingID = w.shelfParentID_FK
  inner join [DATACORE].[WH].[V_warehouse] wh on b.buildingParentID_FK = wh.warehouseID
  where w.IdaraID_FK = @idaraID 

   -- column

  
    SELECT 
       wh.[warehouseID]
      ,wh.warehouseName
      ,wh.warehousePartName_A
      ,[buildingID]
      ,[buildingName]
      ,[buildingPartName_A]
      ,[shelfID]
      ,[shelfName]
      ,[shelfName_A]
      ,[columnID]
      ,[columnName]
      ,[columnName_A]
      ,[columnActive]
      ,case when columnActive = 1 then N'نشط' 
      else N'غير نشط' end 
      as columnStatus


  FROM [DATACORE].[WH].[V_column] c
  inner join [DATACORE].[WH].[V_shelf] w on c.columnParentID_FK = w.shelfID
  inner join [DATACORE].[WH].[V_building] b on b.buildingID = w.shelfParentID_FK
  inner join [DATACORE].[WH].[V_warehouse] wh on b.buildingParentID_FK = wh.warehouseID
  where w.IdaraID_FK = @idaraID


  -- row

  
    SELECT 
       wh.[warehouseID]
      ,wh.warehouseName
      ,wh.warehousePartName_A
      ,[buildingID]
      ,[buildingName]
      ,[buildingPartName_A]
      ,[shelfID]
      ,[shelfName]
      ,[shelfName_A]
      ,[columnID]
      ,[columnName]
      ,[columnName_A]
      ,[rowID]
      ,[rowName]
      ,[rowName_A]
      ,[rowActive]
      ,case when rowActive = 1 then N'نشط' 
      else N'غير نشط' end 
      as rowStatus


  FROM [DATACORE].[WH].[V_row] r
  inner join [DATACORE].[WH].[V_column] c on r.rowParentID_FK = c.columnID
  inner join [DATACORE].[WH].[V_shelf] w on c.columnParentID_FK = w.shelfID
  inner join [DATACORE].[WH].[V_building] b on b.buildingID = w.shelfParentID_FK
  inner join [DATACORE].[WH].[V_warehouse] wh on b.buildingParentID_FK = wh.warehouseID
  where w.IdaraID_FK = @idaraID
           
END
GO
